local function deepCopy(value)
    if type(value) ~= "table" then
        return value
    end
    local out = {}
    for k, v in pairs(value) do
        out[deepCopy(k)] = deepCopy(v)
    end
    return out
end

local function ensureFolder()
    if type(makeFolder) ~= "function" then
        return false
    end

    local ok = pcall(function()
        if type(isFolder) == "function" then
            if not isFolder("SH") then makeFolder("SH") end
            if not isFolder(PREF_FOLDER) then makeFolder(PREF_FOLDER) end
        else
            pcall(makeFolder, "SH")
            pcall(makeFolder, PREF_FOLDER)
        end
    end)

    return ok
end

local function readPrefs()
    if type(readFile) ~= "function" then
        return nil
    end

    local exists = true
    if type(isFile) == "function" then
        local ok, result = pcall(isFile, PREF_PATH)
        exists = ok and result == true
    end

    if not exists then
        return nil
    end

    local okRead, body = pcall(readFile, PREF_PATH)
    if not okRead or type(body) ~= "string" or body == "" then
        return nil
    end

    local okJson, decoded = pcall(HttpService.JSONDecode, HttpService, body)
    if not okJson or type(decoded) ~= "table" then
        return nil
    end

    return decoded
end

local function savePrefs(data)
    if type(writeFile) ~= "function" then
        return false, "writefile unavailable"
    end

    ensureFolder()

    local okJson, body = pcall(HttpService.JSONEncode, HttpService, data)
    if not okJson then
        return false, "JSON encode failed"
    end

    local okWrite, err = pcall(writeFile, PREF_PATH, body)
    return okWrite, okWrite and nil or tostring(err)
end

local function readGlobalGuiPrefs()
    if type(readFile) ~= "function" then
        return nil
    end

    local exists = true
    if type(isFile) == "function" then
        local ok, result = pcall(isFile, GLOBAL_GUI_PREF_PATH)
        exists = ok and result == true
    end

    if not exists then
        return nil
    end

    local okRead, body = pcall(readFile, GLOBAL_GUI_PREF_PATH)
    if not okRead or type(body) ~= "string" or body == "" then
        return nil
    end

    local okJson, decoded = pcall(HttpService.JSONDecode, HttpService, body)
    if not okJson or type(decoded) ~= "table" or decoded.enabled ~= true then
        return nil
    end

    if decoded.completed ~= true
        or type(decoded.layouts) ~= "table"
        or type(decoded.fontName) ~= "string" then
        return nil
    end

    return decoded
end

local function saveGlobalGuiPrefs(data)
    if type(writeFile) ~= "function" then
        return false, "writefile unavailable"
    end

    ensureFolder()

    local payload = deepCopy(data or {})
    payload.enabled = true
    payload.completed = true
    payload.globalSavedAt = os.time()
    payload.sourceUserId = player.UserId
    payload.sourceUsername = player.Name

    local okJson, body = pcall(HttpService.JSONEncode, HttpService, payload)
    if not okJson then
        return false, "Global GUI JSON encode failed"
    end

    local okWrite, err = pcall(writeFile, GLOBAL_GUI_PREF_PATH, body)
    return okWrite, okWrite and nil or tostring(err)
end

local function disableGlobalGuiPrefs()
    if type(deleteFile) == "function" then
        local okDelete = pcall(function()
            if type(isFile) ~= "function" or isFile(GLOBAL_GUI_PREF_PATH) then
                deleteFile(GLOBAL_GUI_PREF_PATH)
            end
        end)

        if okDelete then
            return true
        end
    end

    if type(writeFile) ~= "function" then
        return false, "Could not disable shared GUI preferences"
    end

    ensureFolder()
    local okJson, body = pcall(HttpService.JSONEncode, HttpService, {
        version = 1,
        enabled = false,
        disabledAt = os.time(),
        sourceUserId = player.UserId,
        sourceUsername = player.Name,
    })

    if not okJson then
        return false, "Global GUI disable encode failed"
    end

    local okWrite, err = pcall(writeFile, GLOBAL_GUI_PREF_PATH, body)
    return okWrite, okWrite and nil or tostring(err)
end

local function clearPrefs()
    if type(deleteFile) ~= "function" then
        return false, "delfile unavailable"
    end

    local ok = pcall(function()
        if type(isFile) ~= "function" or isFile(PREF_PATH) then
            deleteFile(PREF_PATH)
        end
    end)

    return ok, ok and nil or "delete failed"
end

local function readFastStartupPreference()
    if type(readFile) ~= "function" then return false end
    local path = PREF_FOLDER .. "/v12_new_" .. tostring(player.UserId) .. ".json"
    local okRead, raw = pcall(readFile, path)
    if not okRead or type(raw) ~= "string" or raw == "" then return false end
    local okDecode, document = pcall(HttpService.JSONDecode, HttpService, raw)
    if not okDecode or type(document) ~= "table" or type(document.Values) ~= "table" then
        return false
    end
    return document.Values.FastStartup == true
end

local accountExisting = readPrefs()
local globalGuiExisting = readGlobalGuiPrefs()
local forceGuiSetup = ENV.SliceHubNewGenWelcomeMode == "RESET"
    or ENV.SliceHubForceGuiSetup == true

-- Premium shared-GUI mode intentionally wins over per-account GUI preferences.
-- This is what lets multi-instance farms use one exact layout/font everywhere.
local existing = (not forceGuiSetup and globalGuiExisting)
    or accountExisting

local fastStartupPreference = readFastStartupPreference()
if type(ENV.SliceHubKaitun) == "table" then
    if type(ENV.SliceHubKaitun.SkipWelcomeGUI) == "boolean" then
        fastStartupPreference = ENV.SliceHubKaitun.SkipWelcomeGUI == true
    elseif type(ENV.SliceHubKaitun.UI) == "table" and ENV.SliceHubKaitun.UI.FastStartup == true then
        fastStartupPreference = true
    end
end

if fastStartupPreference
    and not (ENV.SliceHubNewGenWelcomeMode == "RESET" or ENV.SliceHubForceGuiSetup == true)
    and not (existing and existing.completed == true) then
    existing = {
        version = 1,
        completed = true,
        completedAt = os.time(),
        fontName = "Gotham",
        layouts = deepCopy(DEFAULT_SCHEMA),
        fastStartupBypass = true,
    }
end

local State = {
    Version = 1,
    Completed = (not forceGuiSetup) and existing and existing.completed == true or false,
    FirstRun = forceGuiSetup or not (existing and existing.completed == true),
    ResetMode = forceGuiSetup,
    ApplyGuiToAllInstances = globalGuiExisting ~= nil,

    CurrentStep = "Welcome",
    WelcomeAccepted = false,
    PreviewAccepted = false,
    FinalAccepted = false,

    FontName = existing and existing.fontName or "Gotham",
    Layouts = existing and existing.layouts or deepCopy(DEFAULT_SCHEMA),
    PreviewRuntime = "Main Menu",

    Dirty = false,
    Status = "Ready",
}


ENV.SliceHubNewGenWelcomeComplete = false
ENV.SliceHubNewGenGuiPreferences = existing

local function markWelcomeComplete(preferences)
    ENV.SliceHubNewGenGuiPreferences = preferences
        or readGlobalGuiPrefs()
        or readPrefs()
    ENV.SliceHubNewGenWelcomeComplete = true
    ENV.SliceHubNewGenWelcomeMode = nil
end

local function requestGuiReset()
    local ok, err = clearPrefs()
    if ok then
        ENV.SliceHubNewGenGuiPreferences = nil
        ENV.SliceHubNewGenWelcomeComplete = false
        ENV.SliceHubNewGenWelcomeMode = "RESET"
        ENV.SliceHubForceGuiSetup = true
        return true
    end
    return false, err
end

ENV.SliceHubResetGuiPreferences = requestGuiReset


local function reconcileLayouts()
    for runtimeName, defaultRuntime in pairs(DEFAULT_SCHEMA) do
        local runtime = State.Layouts[runtimeName]

        if type(runtime) ~= "table" then
            State.Layouts[runtimeName] = deepCopy(defaultRuntime)
            continue
        end

        runtime.tabOrder = type(runtime.tabOrder) == "table"
            and runtime.tabOrder
            or {}

        runtime.tabs = type(runtime.tabs) == "table"
            and runtime.tabs
            or {}

        local seenTabs = {}
        for _, tabId in ipairs(runtime.tabOrder) do
            seenTabs[tabId] = true
        end

        for _, tabId in ipairs(defaultRuntime.tabOrder) do
            if not seenTabs[tabId] then
                runtime.tabOrder[#runtime.tabOrder + 1] = tabId
            end

            local defaultTab = defaultRuntime.tabs[tabId]
            local tab = runtime.tabs[tabId]

            if type(tab) ~= "table" then
                runtime.tabs[tabId] = deepCopy(defaultTab)
                tab = runtime.tabs[tabId]
            end

            tab.id = tabId
            tab.name = defaultTab.name
            tab.functionOrder = type(tab.functionOrder) == "table"
                and tab.functionOrder
                or {}
            tab.functions = type(tab.functions) == "table"
                and tab.functions
                or {}

            local seenFunctions = {}
            for _, functionId in ipairs(tab.functionOrder) do
                seenFunctions[functionId] = true
            end

            for _, functionId in ipairs(defaultTab.functionOrder) do
                if not seenFunctions[functionId] then
                    tab.functionOrder[#tab.functionOrder + 1] = functionId
                end
                tab.functions[functionId] =
                    deepCopy(defaultTab.functions[functionId])
            end
        end
    end
end

reconcileLayouts()

local function currentFont()
    for _, item in ipairs(FONT_OPTIONS) do
        if item.Name == State.FontName then
            return item.Font
        end
    end
    return Enum.Font.Gotham
end

local function parentGui(screen)
    local parent = nil

    if type(gethui) == "function" then
        pcall(function()
            parent = gethui()
        end)
    end

    if not parent then
        parent = CoreGui
    end

    local ok = pcall(function()
        screen.Parent = parent
    end)

    if not ok or not screen.Parent then
        screen.Parent = playerGui
    end
end

local old = nil
pcall(function()
    old = CoreGui:FindFirstChild("SliceHubNewGenWelcome")
        or playerGui:FindFirstChild("SliceHubNewGenWelcome")
end)
if old then old:Destroy() end

