    Moved = false,
    UserMoved = false,
}

close.Visible = not UserInputService.TouchEnabled

close.Activated:Connect(function()
    screen:Destroy()
end)

mobileToggle.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.Touch
        and input.UserInputType ~= Enum.UserInputType.MouseButton1 then
        return
    end

    mobileToggleDrag.Dragging = true
    mobileToggleDrag.Input = input
    mobileToggleDrag.StartInput = input.Position
    mobileToggleDrag.StartCenter = mobileToggle.AbsolutePosition + (mobileToggle.AbsoluteSize / 2)
    mobileToggleDrag.Moved = false

    input.Changed:Connect(function()
        if input.UserInputState == Enum.UserInputState.End then
            mobileToggleDrag.Dragging = false
            mobileToggleDrag.Input = nil
            task.defer(function()
                mobileToggleDrag.Moved = false
            end)
        end
    end)
end)

UserInputService.InputChanged:Connect(function(input)
    if mobileToggleDrag.Dragging ~= true
        or not mobileToggleDrag.StartInput
        or not mobileToggleDrag.StartCenter then
        return
    end

    local validTouch = input.UserInputType == Enum.UserInputType.Touch and input == mobileToggleDrag.Input
    local validMouse = input.UserInputType == Enum.UserInputType.MouseMovement
    if not validTouch and not validMouse then return end

    local delta = input.Position - mobileToggleDrag.StartInput
    if delta.Magnitude >= 5 then
        mobileToggleDrag.Moved = true
        mobileToggleDrag.UserMoved = true
    end

    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
    local x = math.clamp(mobileToggleDrag.StartCenter.X + delta.X, 24, math.max(24, viewport.X - 24))
    local y = math.clamp(mobileToggleDrag.StartCenter.Y + delta.Y, 24, math.max(24, viewport.Y - 24))
    mobileToggle.Position = UDim2.fromOffset(math.floor(x + 0.5), math.floor(y + 0.5))
end)

mobileToggle.Activated:Connect(function()
    if mobileToggleDrag.Moved == true then return end
    window.Visible = not window.Visible
end)

