local STEPS = {
    "Welcome",
    "Font",
    "Main Menu",
    "Lobby",
    "Mission",
    "Preview",
    "Community",
    "Done",
}

local Pages = {}
local StepButtons = {}
local Refreshers = {}

local function clear(container)
    for _, child in ipairs(container:GetChildren()) do
        child:Destroy()
    end
end

local function corner(object, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius or 8)
    c.Parent = object
    return c
end

local function stroke(object, transparency)
    local s = Instance.new("UIStroke")
    s.Color = THEME.Stroke
    s.Transparency = transparency or 0.35
    s.Thickness = 1
    s.Parent = object
    return s
end

local function label(parent, textValue, size, position, textSize, bold, color)
    local x = Instance.new("TextLabel")
    x.Size = size
    x.Position = position or UDim2.new()
    x.BackgroundTransparency = 1
    x.Text = textValue or ""
    x.Font = bold and Enum.Font.GothamBold or currentFont()
    x.TextSize = textSize or 10
    x.TextColor3 = color or THEME.Text
    x.TextXAlignment = Enum.TextXAlignment.Left
    x.TextYAlignment = Enum.TextYAlignment.Center
    x.TextWrapped = true
    x.Parent = parent
    return x
end

local function button(parent, textValue, size, position)
    local x = Instance.new("TextButton")
    x.Size = size
    x.Position = position or UDim2.new()
    x.BackgroundColor3 = THEME.Card2
    x.BorderSizePixel = 0
    x.Text = textValue or "BUTTON"
    x.Font = Enum.Font.GothamBold
    x.TextSize = 9
    x.TextColor3 = THEME.Text
    x.AutoButtonColor = false
    x.Parent = parent
    corner(x, 7)
    stroke(x, 0.55)
    return x
end

local function makePage(name)
    local page = Instance.new("Frame")
    page.Name = name:gsub("%s+", "") .. "Page"
    page.Size = UDim2.fromScale(1,1)
    page.BackgroundTransparency = 1
    page.Visible = false
    page.Parent = content
    Pages[name] = page
    return page
end

local progressLayout = Instance.new("UIListLayout")
progressLayout.FillDirection = Enum.FillDirection.Horizontal
progressLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
progressLayout.VerticalAlignment = Enum.VerticalAlignment.Center
progressLayout.Padding = UDim.new(0, 5)
progressLayout.Parent = progress

for index, stepName in ipairs(STEPS) do
    local b = button(
        progress,
        string.format("%d  %s", index, stepName:upper()),
        UDim2.fromOffset(index == 1 and 104 or 92, 28)
    )
    b.LayoutOrder = index
    b.Active = false
    StepButtons[stepName] = b
end

local function currentStepIndex()
    for i, step in ipairs(STEPS) do
        if step == State.CurrentStep then return i end
    end
    return 1
end

local function canNext()
    if State.CurrentStep == "Welcome" then
        return State.WelcomeAccepted == true
    elseif State.CurrentStep == "Preview" then
        return State.PreviewAccepted == true
    elseif State.CurrentStep == "Community" then
        return State.FinalAccepted == true
    elseif State.CurrentStep == "Done" then
        return false
    end
    return true
end

local function updateFooter()
    local index = currentStepIndex()
    backButton.Visible = index > 1 and State.CurrentStep ~= "Done"

    local allowed = canNext()

    nextButton.Active = allowed
    nextButton.AutoButtonColor = false
    nextButton.BackgroundColor3 = allowed and THEME.Accent or THEME.Card2
    nextButton.TextColor3 = allowed and THEME.Text or THEME.Muted

    if State.CurrentStep == "Community" then
        nextButton.Text = "FINISH SETUP"
        nextButton.Visible = true
    elseif State.CurrentStep == "Done" then
        if State.CompactTouch == true then


            nextButton.Text = "LAUNCH SLICEHUB"
            nextButton.Visible = true
            nextButton.Active = true
            nextButton.BackgroundColor3 = THEME.Accent
            nextButton.TextColor3 = THEME.Text
        else
            nextButton.Text = "COMPLETE"
            nextButton.Visible = false
        end
    else
        nextButton.Text = "NEXT"
        nextButton.Visible = true
    end

    status.Text = State.Status or "Ready"
end

local function setStep(name, direction)
    if not Pages[name] then return end

    local oldPage = Pages[State.CurrentStep]
    local newPage = Pages[name]

    State.CurrentStep = name

    for _, page in pairs(Pages) do
        if page ~= newPage then
            page.Visible = false
        end
    end

    newPage.Visible = true

    local width = math.max(320, content.AbsoluteSize.X)
    local offset = direction == "back" and -width * 0.06 or width * 0.06

    newPage.Position = UDim2.fromOffset(offset, 0)
    newPage.BackgroundTransparency = 1

    TweenService:Create(
        newPage,
        TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        {Position = UDim2.new(), BackgroundTransparency = 1}
    ):Play()

    for stepName, b in pairs(StepButtons) do
        local active = stepName == name
        b.BackgroundColor3 = active and THEME.Accent or THEME.Card2
        b.TextColor3 = active and THEME.Text or THEME.Muted
    end

    if Refreshers[name] then
        Refreshers[name]()
    end

    updateFooter()
end

local function moveItem(order, index, delta)
    local target = index + delta
    if target < 1 or target > #order then
        return false
    end

    local item = table.remove(order, index)
    table.insert(order, target, item)
    State.Dirty = true
    return true
end

local function makeCheck(parent, textValue, position, getter, setter)
    local row = Instance.new("TextButton")
    row.Position = position
    row.Size = UDim2.new(1, -36, 0, 44)
    row.BackgroundColor3 = THEME.Card2
    row.BorderSizePixel = 0
    row.Text = ""
    row.AutoButtonColor = false
    row.Parent = parent
    corner(row, 8)
    stroke(row, 0.55)

    local box = Instance.new("Frame")
    box.Position = UDim2.fromOffset(12, 12)
    box.Size = UDim2.fromOffset(20, 20)
    box.BorderSizePixel = 0
    box.Parent = row
    corner(box, 5)

    local tick = label(
        box,
        "✓",
        UDim2.fromScale(1,1),
        UDim2.new(),
        13,
        true,
        THEME.Text
    )
    tick.TextXAlignment = Enum.TextXAlignment.Center

    local textLabel = label(
        row,
        textValue,
        UDim2.new(1, -52, 1, 0),
        UDim2.fromOffset(44, 0),
        10,
        false,
        THEME.Text
    )

    local function refresh()
        local value = getter() == true
        box.BackgroundColor3 = value and THEME.Accent or THEME.Background
        tick.Visible = value
    end

    row.Activated:Connect(function()
        setter(not getter())
        refresh()
        updateFooter()
    end)

    refresh()
    return refresh
end


