        UDim2.new(1,-24,0,24),
        UDim2.fromOffset(12,32),
        8,
        false,
        THEME.Muted
    )

    local functionScroll = Instance.new("ScrollingFrame")
    functionScroll.Position = UDim2.fromOffset(10, 62)
    functionScroll.Size = UDim2.new(1,-20,1,-72)
    functionScroll.BackgroundTransparency = 1
    functionScroll.BorderSizePixel = 0
    functionScroll.ScrollBarThickness = 2
    functionScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
