    label(previewPanel, runtimeName:upper() .. " PREVIEW", UDim2.new(1,-24,0,22), UDim2.fromOffset(12,10), 10, true)

    local miniTabs = Instance.new("ScrollingFrame")
    miniTabs.Position = UDim2.fromOffset(10, 42)
    miniTabs.Size = UDim2.new(1,-20,0,76)
    miniTabs.BackgroundColor3 = THEME.Background
