    local miniFunctionLayout = Instance.new("UIListLayout")
    miniFunctionLayout.Padding = UDim.new(0,4)
    miniFunctionLayout.Parent = miniFunctions

    local refreshAll

    local function addMoveButtons(row, order, index, refresh)
        local up = button(row, "↑", UDim2.fromOffset(28,26), UDim2.new(1,-64,0,5))
        local down = button(row, "↓", UDim2.fromOffset(28,26), UDim2.new(1,-32,0,5))
        up.TextSize = 12
        down.TextSize = 12

        up.Activated:Connect(function()
            if moveItem(order, index, -1) then refresh() end
        end)

        down.Activated:Connect(function()
            if moveItem(order, index, 1) then refresh() end
        end)
    end

    local function refreshTabs()
        for _, child in ipairs(tabScroll:GetChildren()) do
            if child:IsA("Frame") then child:Destroy() end
        end

        if not runtime.tabs[activeTabId] then
            activeTabId = runtime.tabOrder[1]
        end

        for index, tabId in ipairs(runtime.tabOrder) do
            local tabData = runtime.tabs[tabId]

            local row = Instance.new("Frame")
            row.Size = UDim2.new(1,0,0,36)
            row.BackgroundColor3 = activeTabId == tabId and THEME.AccentSoft or THEME.Card2
            row.BorderSizePixel = 0
            row.Parent = tabScroll
            corner(row, 6)

            local selectButton = Instance.new("TextButton")
            selectButton.Size = UDim2.new(1,-70,1,0)
            selectButton.BackgroundTransparency = 1
            selectButton.Text = "☰  " .. tostring(tabData and tabData.name or tabId)
            selectButton.Font = currentFont()
            selectButton.TextSize = 8
            selectButton.TextColor3 = THEME.Text
            selectButton.TextXAlignment = Enum.TextXAlignment.Left
            selectButton.Parent = row

            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0,8)
            pad.Parent = selectButton

            selectButton.Activated:Connect(function()
                activeTabId = tabId
                refreshAll()
            end)

            addMoveButtons(row, runtime.tabOrder, index, refreshAll)
        end
    end

    local function refreshFunctions()
        for _, child in ipairs(functionScroll:GetChildren()) do
            if child:IsA("Frame") then child:Destroy() end
        end

        local tabData = runtime.tabs[activeTabId]
        if not tabData then return end

        functionsHead.Text = string.upper(tabData.name) .. " • FUNCTIONS"
        functionsHint.Text = tostring(#tabData.functionOrder) .. " current NewGen cards • layout only"

        for index, functionId in ipairs(tabData.functionOrder) do
            local functionData = tabData.functions[functionId]

            local row = Instance.new("Frame")
            row.Size = UDim2.new(1,0,0,36)
            row.BackgroundColor3 = THEME.Card2
            row.BorderSizePixel = 0
            row.Parent = functionScroll
            corner(row, 6)

            local name = label(
                row,
                "☰  " .. tostring(functionData and functionData.name or functionId),
                UDim2.new(1,-74,1,0),
                UDim2.fromOffset(8,0),
                8,
                false
            )
            name.Font = currentFont()
            name.TextTruncate = Enum.TextTruncate.AtEnd
            name.TextWrapped = false

            addMoveButtons(row, tabData.functionOrder, index, refreshAll)
        end
    end

    local function refreshMiniPreview()
        for _, child in ipairs(miniTabs:GetChildren()) do
            if child:IsA("TextLabel") then child:Destroy() end
        end
        for _, child in ipairs(miniFunctions:GetChildren()) do
            if child:IsA("Frame") then child:Destroy() end
        end

        for index, tabId in ipairs(runtime.tabOrder) do
            local tabData = runtime.tabs[tabId]
            local x = label(
                miniTabs,
                (activeTabId == tabId and "● " or "○ ") .. tostring(tabData.name),
                UDim2.new(1,-8,0,18),
                UDim2.new(),
                7,
                activeTabId == tabId,
                activeTabId == tabId and THEME.Text or THEME.Muted
            )
            x.LayoutOrder = index
            x.Font = currentFont()
        end

        local tabData = runtime.tabs[activeTabId]
        if not tabData then return end

        for index, functionId in ipairs(tabData.functionOrder) do
            local functionData = tabData.functions[functionId]
            local card = Instance.new("Frame")
            card.LayoutOrder = index
            card.Size = UDim2.new(1,0,0,34)
            card.BackgroundColor3 = THEME.Card
            card.BorderSizePixel = 0
            card.Parent = miniFunctions
            corner(card, 5)

            local x = label(
                card,
                tostring(functionData and functionData.name or functionId),
                UDim2.new(1,-12,1,0),
                UDim2.fromOffset(6,0),
                7,
                false,
                THEME.Text
            )
            x.Font = currentFont()
            x.TextTruncate = Enum.TextTruncate.AtEnd
            x.TextWrapped = false
        end
    end

    refreshAll = function()
        refreshTabs()
        refreshFunctions()
        refreshMiniPreview()
    end

    Refreshers[runtimeName] = refreshAll
end

