local function renderPreview()
    local runtime = State.Layouts[State.PreviewRuntime]
    if not runtime then return end

    if not previewActiveTab or not runtime.tabs[previewActiveTab] then
        previewActiveTab = runtime.tabOrder[1]
    end

    for _, child in ipairs(previewNav:GetChildren()) do
        if child:IsA("TextButton") then child:Destroy() end
    end
    for _, child in ipairs(previewBody:GetChildren()) do
        if child:IsA("Frame") then child:Destroy() end
    end

    for index, tabId in ipairs(runtime.tabOrder) do
        local tabData = runtime.tabs[tabId]
        local b = button(previewNav, tostring(tabData.name), UDim2.new(1,-8,0,30))
