local function finishWelcomeLaunch()
    local preferences = readPrefs() or {
        version = State.Version,
        completed = true,
        completedAt = os.time(),
        fontName = State.FontName,
        layouts = State.Layouts,
    }

    if State.ApplyGuiToAllInstances == true then
        local okGlobal, globalErr = saveGlobalGuiPrefs(preferences)
        if not okGlobal then
            State.Status = "Could not save shared GUI: " .. tostring(globalErr)
            updateFooter()
            return false
        end

        preferences = readGlobalGuiPrefs() or preferences
        State.Status = "Shared GUI saved for all SliceHub Premium instances."
    else
        local okDisable, disableErr = disableGlobalGuiPrefs()
        if not okDisable then
            State.Status = "Could not disable shared GUI: " .. tostring(disableErr)
            updateFooter()
            return false
        end
    end

    markWelcomeComplete(preferences)
    if screen and screen.Parent then
        screen:Destroy()
    end
    return true
end

