local function applyViewport()
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(1280,720)

    local isTouch = UserInputService.TouchEnabled
    local width
    local height

    if isTouch then
        local landscape = viewport.X >= viewport.Y


        local widthFactor = landscape and 0.90 or 0.96
        local heightFactor = landscape and 0.94 or 0.88
        local availableWidth = math.max(320, math.floor(viewport.X - 12))
        local availableHeight = math.max(300, math.floor(viewport.Y - 12))

        width = math.min(980, availableWidth, math.max(320, math.floor(viewport.X * widthFactor)))
        height = math.min(620, availableHeight, math.max(300, math.floor(viewport.Y * heightFactor)))
    else
        local margin = 36
        width = math.clamp(viewport.X - margin, 320, 980)
        height = math.clamp(viewport.Y - margin, 300, 620)
    end


    local function snapCenteredSize(value, axis)
        value = math.max(2, math.floor(value + 0.5))
        axis = math.floor(axis + 0.5)
        if ((axis - value) % 2) ~= 0 then
            value = math.max(2, value - 1)
        end
        return value
    end

    width = snapCenteredSize(width, viewport.X)
    height = snapCenteredSize(height, viewport.Y)

    window.Size = UDim2.fromOffset(width, height)
    close.Visible = not isTouch
    mobileToggle.Visible = isTouch

    if isTouch then
        if mobileToggleDrag.UserMoved ~= true then
            mobileToggle.Position = UDim2.fromOffset(
                math.max(24, viewport.X - 28),
                math.floor(viewport.Y * 0.5 + 0.5)
            )
        else
            local center = mobileToggle.AbsolutePosition + (mobileToggle.AbsoluteSize / 2)
            mobileToggle.Position = UDim2.fromOffset(
                math.clamp(math.floor(center.X + 0.5), 24, math.max(24, viewport.X - 24)),
                math.clamp(math.floor(center.Y + 0.5), 24, math.max(24, viewport.Y - 24))
            )
        end
    end


    local compactTouch = isTouch and (viewport.X < 700 or viewport.Y < 560)
    State.CompactTouch = compactTouch

    if viewport.X < 700 or compactTouch then
        progress.Visible = false
        content.Position = UDim2.fromOffset(0,58)
        content.Size = UDim2.new(1,0,1,-116)
        footer.Size = UDim2.new(1,0,0,58)

        title.Size = UDim2.new(1,-68,0,22)
        subtitle.Size = UDim2.new(1,-68,0,16)
    else
        progress.Visible = true
        content.Position = UDim2.fromOffset(0,100)
        content.Size = UDim2.new(1,0,1,-158)
        footer.Size = UDim2.new(1,0,0,58)
        title.Size = UDim2.new(1,-150,0,22)
        subtitle.Size = UDim2.new(1,-150,0,16)
    end


    if isTouch then
        title.TextSize = 18
        subtitle.TextSize = 10
        status.TextSize = 10
        backButton.TextSize = 10
        nextButton.TextSize = 10
    else
        title.TextSize = 16
        subtitle.TextSize = 9
        status.TextSize = 9
        backButton.TextSize = 9
        nextButton.TextSize = 9
    end

    if Refreshers.Done then
        pcall(Refreshers.Done)
    end
    updateFooter()
end
