local RuntimeKind = AOT_LOBBY_PLACE_IDS[CURRENT_PLACE_ID] and "Lobby"
    or (AOT_MAIN_MENU_PLACE_IDS[CURRENT_PLACE_ID] and "MainMenu" or "Gameplay")

