local function chooseParent()
    local p
    if type(gethui) == "function" then
        pcall(function() p = gethui() end)
    end
    return p or CoreGui or playerGui
end

local parent = chooseParent()

-- V14.5 R4 SINGLETON HOTFIX
-- A stale SliceHub instance can survive when an executor changes GUI hosts
-- between PlayerGui/CoreGui/gethui(). That caused stacked transparent GUIs
-- and allowed the previous result watcher to send an old webhook layout.
do
    local runtimeEnv =
        (type(getgenv) == "function" and getgenv())
        or _G

    if type(runtimeEnv.__SliceHubActiveShutdown) == "function" then
        pcall(runtimeEnv.__SliceHubActiveShutdown, "re-execute")
    end
    runtimeEnv.__SliceHubActiveShutdown = nil

    -- Recover from a stale 3D-off instance before rebuilding the UI.
    pcall(function()
        game:GetService("RunService"):Set3dRenderingEnabled(true)
    end)

    local seenHosts = {}
    local function clearHost(host)
        if not host or seenHosts[host] then return end
        seenHosts[host] = true

        for _, child in ipairs(host:GetChildren()) do
            if child.Name == "SliceHubNewGen"
                or child.Name == "SliceHubRenderSleep"
                or child.Name == "SliceHubAutoTSQuestRuntime"
                or child.Name == "SliceHubAutoTSQuestCard" then
                pcall(function() child:Destroy() end)
            end
        end
    end

    clearHost(parent)
    clearHost(CoreGui)
    clearHost(playerGui)

    if type(gethui) == "function" then
        local okHost, hiddenHost = pcall(gethui)
        if okHost then clearHost(hiddenHost) end
    end
end

local C = {
