    InvalidSoloSince = 0,
    ProgressSince = 0,
    StableSince = 0,
    Recovering = false,
    Status = "Ready",
}

App.TransitionGuard.BlockGameplay = function()
    if App.TransitionGuard.ResultActive == true
        or App.TransitionGuard.RetryArmed == true then
        return true
    end

    return App.Cutscene ~= nil
        and App.Cutscene.Active == true
end


do
    local __env = type(getgenv) == "function" and getgenv() or _G
    App.GuiPreferences =
        type(__env.SliceHubNewGenGuiPreferences) == "table"
        and __env.SliceHubNewGenGuiPreferences
        or {}

    function App.RefreshGuiPreferences()
        App.GuiPreferences =
            type(__env.SliceHubNewGenGuiPreferences) == "table"
            and __env.SliceHubNewGenGuiPreferences
            or {}
        return App.GuiPreferences
    end

    local __fontMap = {
        ["Gotham"] = Enum.Font.Gotham,
        ["Gotham Medium"] = Enum.Font.GothamMedium,
        ["Gotham Bold"] = Enum.Font.GothamBold,
        ["Code"] = Enum.Font.Code,
        ["Roboto Mono"] = Enum.Font.RobotoMono,
        ["Source Sans"] = Enum.Font.SourceSans,
    }

    function App.PreferredGuiFont()
        local prefs = App.GuiPreferences or {}
        return __fontMap[tostring(prefs.fontName or "Gotham")]
            or Enum.Font.Gotham
    end

    function App.ApplyPreferredFont(root)
        if not root then return end
        local font = App.PreferredGuiFont()

        local function apply(object)
            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then
                pcall(function()
                    object.Font = font
                end)
            end
        end

        apply(root)
        for _, object in ipairs(root:GetDescendants()) do
            apply(object)
        end
    end
end


App.RuntimeHealth = App.RuntimeHealth or {
    StartedAt = os.clock(),
    Alive = true,
    Connections = {},
}

App.RuntimeHealth.Track = function(connection)
    if connection ~= nil then
        App.RuntimeHealth.Connections[#App.RuntimeHealth.Connections + 1] = connection
    end
    return connection
end

App.RuntimeHealth.Cleanup = function()
    if App.RuntimeHealth.Alive ~= true then return end
    App.RuntimeHealth.Alive = false
    for index = #App.RuntimeHealth.Connections, 1, -1 do
        local connection = App.RuntimeHealth.Connections[index]
        App.RuntimeHealth.Connections[index] = nil
        if connection then
            pcall(function() connection:Disconnect() end)
        end
    end
end

App.RuntimeHealth.StatusText = function()
    local seconds = math.max(0, math.floor(os.clock() - (tonumber(App.RuntimeHealth.StartedAt) or os.clock())))
    local age = seconds < 60 and (tostring(seconds) .. "s")
        or string.format("%dm %02ds", math.floor(seconds / 60), seconds % 60)
    local context = RuntimeKind == "MainMenu" and "Main Menu"
        or (RuntimeKind == "Lobby" and "Lobby" or "Gameplay")
    if App.Failsafe and App.Failsafe.Triggering == true then
        return "Recovering • " .. context
    end
    return "Healthy • " .. context .. " • " .. age
end

App.RuntimeHealth.StatusKind = function()
    if App.Failsafe and App.Failsafe.Triggering == true then return "warn" end
    return App.RuntimeHealth.Alive == true and "good" or "failed"
end


