}

V12Config.ApplyExplicitAutoSlot = function(document)
    local slot = type(document) == "table" and document.AutoSlot or nil
    if type(slot) ~= "table" then return false end

    if type(slot.Enabled) == "boolean" then
        App.Values.MainAutoSelectSlot = slot.Enabled
    end
    if slot.Delay ~= nil or slot.DelaySeconds ~= nil then
        App.Values.MainAutoSlotDelay = math.clamp(
            math.floor((tonumber(slot.DelaySeconds ~= nil and slot.DelaySeconds or slot.Delay) or 15) + 0.5),
            0,
            120
        )
    end
    if type(slot.Slot) == "string" then
        App.Values.MainSlot = slot.Slot
    end
    if type(slot.Destination) == "string" then
        App.Values.MainDestination = slot.Destination
    end
    if type(slot.AutoJoinPrivateServer) == "boolean" then
        App.Values.MainAutoJoinPrivateServer = slot.AutoJoinPrivateServer
    end
    if slot.PrivateServerCode ~= nil then
        App.Values.MainPrivateServerCode = tostring(slot.PrivateServerCode)
        if slot.AutoJoinPrivateServer == nil and App.Values.MainPrivateServerCode ~= "" then
            App.Values.MainAutoJoinPrivateServer = true
        end
    end
    return true
end

local function v12Environment()
    local env = nil
    pcall(function()
        if type(getgenv) == "function" then
            env = getgenv()
        end
    end)
    return type(env) == "table" and env or _G
end

local function v12FileFunctions()
    local env = v12Environment()
    return
        (env and env.readfile) or (type(readfile) == "function" and readfile or nil),
        (env and env.writefile) or (type(writefile) == "function" and writefile or nil),
        (env and env.makefolder) or (type(makefolder) == "function" and makefolder or nil),
        (env and env.isfile) or (type(isfile) == "function" and isfile or nil),
        (env and env.delfile) or (type(delfile) == "function" and delfile or nil)
end

local function v12EnsureConfigFolder()
    local _, _, makeFolder = v12FileFunctions()
    if type(makeFolder) ~= "function" then
        return
    end

    pcall(makeFolder, "SH")
    pcall(makeFolder, "SH/config")
end

local function encodeConfigValue(value)
    if typeof(value) == "Color3" then
        return {
            __type = "Color3",
            R = value.R,
            G = value.G,
            B = value.B,
        }
    end

    if type(value) == "boolean"
        or type(value) == "number"
        or type(value) == "string" then
        return value
    end

    return nil
end

local function decodeConfigValue(value)
    if type(value) == "table" and value.__type == "Color3" then
        return Color3.new(
            math.clamp(tonumber(value.R) or 0, 0, 1),
            math.clamp(tonumber(value.G) or 0, 0, 1),
            math.clamp(tonumber(value.B) or 0, 0, 1)
        )
    end

    if type(value) == "boolean"
        or type(value) == "number"
        or type(value) == "string" then
        return value
    end

    return nil
end

local function captureV12ConfigValues()
    local values = {}

    for key, value in pairs(App.Values) do
        if key ~= "AutoLoadConfig"
            and key ~= "AutoExecuteOnTeleport"
            and key ~= "GlobalConfigSync"
            and string.sub(tostring(key), 1, 13) ~= "ConfigLibrary"
            and key ~= "SharedConfigCode"
            and key ~= "ConfigShareStatus"
            and key ~= "WebhookStatus"
            and key ~= "WebhookHourlyStatus"
            and key ~= "LobbyActivityWebhookStatus"
            and key ~= "MissionRunCount"
            and key ~= "MissionLoopStatus"
            and key ~= "MissionLastResult"
            and key ~= "LobbyStatus"
            and key ~= "LobbyStatusKind" then
            local encoded = encodeConfigValue(value)
            if encoded ~= nil then
                values[key] = encoded
            end
        end
    end

    return values
end

local function writeV12Config()
    local _, writeFile = v12FileFunctions()

    if type(writeFile) ~= "function" then
        V12Config.LastStatus = "File storage unavailable"
        return false, V12Config.LastStatus
    end

    v12EnsureConfigFolder()

    local document = {
        Version = V12Config.SchemaVersion,
        Name = V12Config.Name,
        UserId = player.UserId,
        SavedAt = os.time(),
        AutoLoad = App.Values.AutoLoadConfig == true,
        AutoExecuteOnTeleport = App.Values.AutoExecuteOnTeleport == true,

        PerAccount = true,
        AutoSlot = {
            Enabled = App.Values.MainAutoSelectSlot == true,
            Delay = math.clamp(math.floor((tonumber(App.Values.MainAutoSlotDelay) or 15) + 0.5), 0, 120),
            Slot = tostring(App.Values.MainSlot or "A"),
            Destination = tostring(App.Values.MainDestination or "Town"),
            AutoJoinPrivateServer = App.Values.MainAutoJoinPrivateServer == true,
            PrivateServerCode = tostring(App.Values.MainPrivateServerCode or ""),
        },
        Window = {
            Width = math.floor((tonumber(V12Config.WindowWidth) or 920) + 0.5),
            Height = math.floor((tonumber(V12Config.WindowHeight) or 570) + 0.5),
        },

        WebhookPreset = {
            Enabled = App.Values.WebhookEnabled == true,
            -- Offline builds store the direct Discord URL locally. The old
            -- vault-only gate turned every normal URL into an empty string.
            URL = tostring(App.Values.WebhookURL or ""),
            HourlyURL = tostring(App.Values.WebhookHourlyURL or ""),
            SendCompleted = App.Values.WebhookSendCompleted ~= false,
            SendFailed = App.Values.WebhookSendFailed == true,
            IncludeStats = App.Values.WebhookStats ~= false,
            HighValue = App.Values.WebhookHighValue ~= false,
            ShowUsername = App.Values.WebhookShowUsername ~= false,
            PingUserId = tostring(App.Values.WebhookPingUserId or ""),
            FamilyEnabled = App.Values.FamilyWebhookEnabled == true,
            FamilyUserId = tostring(App.Values.FamilyWebhookUserId or ""),
            HourlyEnabled = App.Values.WebhookHourlyEnabled == true,
            HourlyIntervalHours = math.clamp(math.floor((tonumber(App.Values.WebhookHourlyIntervalHours) or 1) + 0.5), 1, 12),
            HourlyShowGold = App.Values.WebhookHourlyShowGold ~= false,
            HourlyShowMissions = App.Values.WebhookHourlyShowMissions ~= false,
            HourlyShowActivity = App.Values.WebhookHourlyShowActivity ~= false,
            HourlyShowSummary = App.Values.WebhookHourlyShowSummary ~= false,
            HourlyShowModes = App.Values.WebhookHourlyShowModes ~= false,
            HourlyShowSession = App.Values.WebhookHourlyShowSession ~= false,
            HourlyShowDrops = App.Values.WebhookHourlyShowDrops ~= false,
            HourlyShowBestDrop = App.Values.WebhookHourlyShowBestDrop ~= false,
            HourlyShowStability = App.Values.WebhookHourlyShowStability ~= false,
            NoPingFarmFinished = App.Values.WebhookNoPingFarmFinished == true,
            NoPingAttention = App.Values.WebhookNoPingAttention == true,
            NoPingBoosts = App.Values.WebhookNoPingBoosts == true,
            NoPingPerks = App.Values.WebhookNoPingPerks == true,
            NoPingPrestige = App.Values.WebhookNoPingPrestige == true,
            NoPingGear = App.Values.WebhookNoPingGear == true,
        },

        Values = captureV12ConfigValues(),
    }

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(document)
    end)

    if not okEncode then
        V12Config.LastStatus = "Config encode failed"
        return false, V12Config.LastStatus
    end

    local okWrite, err = pcall(writeFile, V12Config.File, encoded)

    if not okWrite then
        V12Config.LastStatus = tostring(err)
        return false, V12Config.LastStatus
    end

    V12Config.LastStatus = "Saved all settings • " .. tostring(player.Name)

    if App.Values.GlobalConfigSync == true
        and type(V12Config.EnableGlobalFromSaved) == "function" then
        if V12Config.GlobalEnabled ~= true
            or tonumber(V12Config.GlobalSourceUserId) == tonumber(player.UserId) then
            local globalOk, globalMessage = V12Config.EnableGlobalFromSaved()
            if not globalOk then
                V12Config.LastStatus =
                    "Per-account saved • global sync failed: "
                    .. tostring(globalMessage or "Unknown error")
                return false, V12Config.LastStatus
            end
            V12Config.LastStatus =
                "Saved + synced globally • " .. tostring(player.Name)
        else
            V12Config.LastStatus =
                "Saved per-account • global source remains "
                .. tostring(V12Config.ResolveSourceUsername())
        end
    end

    return true, V12Config.LastStatus
end

V12Config.ScheduleSave = function(delaySeconds)
    V12Config.SaveSerial = (tonumber(V12Config.SaveSerial) or 0) + 1
    local serial = V12Config.SaveSerial
    local delayValue = math.clamp(tonumber(delaySeconds) or 0.35, 0.05, 2.0)
    task.delay(delayValue, function()
        if serial ~= V12Config.SaveSerial then return end
        pcall(V12Config.SaveMetadataOnly)
    end)
end

local function readV12Config()
    local readFile = select(1, v12FileFunctions())

    if type(readFile) ~= "function" then
        return nil, "File storage unavailable"
    end

    local okRead, raw = pcall(readFile, V12Config.File)
    if not okRead or type(raw) ~= "string" or raw == "" then
        return nil, "No saved config"
    end

    local okDecode, document = pcall(function()
        return HttpService:JSONDecode(raw)
    end)

    if not okDecode or type(document) ~= "table" then
        return nil, "Saved config is invalid"
    end

    return document
end


V12Config.SaveMetadataOnly = function()
    local _, writeFile = v12FileFunctions()

    if type(writeFile) ~= "function" then
        V12Config.LastStatus = "File storage unavailable"
        return false, V12Config.LastStatus
    end

    local document = readV12Config()
    if type(document) ~= "table" then
        document = {
            Version = V12Config.SchemaVersion,
            Name = V12Config.Name,
            UserId = player.UserId,
            Values = {},
        }
    end
    if type(document.Values) ~= "table" then
        document.Values = {}
    end

    document.Version = V12Config.SchemaVersion
    document.Name = tostring(document.Name or V12Config.Name)
    document.UserId = player.UserId
    document.PerAccount = true
    document.GlobalSync = nil
    document.AutoLoad = App.Values.AutoLoadConfig == true
    document.AutoExecuteOnTeleport = App.Values.AutoExecuteOnTeleport == true
    document.FlagsUpdatedAt = os.time()
    document.AutoSlot = {
        Enabled = App.Values.MainAutoSelectSlot == true,
        Delay = math.clamp(math.floor((tonumber(App.Values.MainAutoSlotDelay) or 15) + 0.5), 0, 120),
        Slot = tostring(App.Values.MainSlot or "A"),
        Destination = tostring(App.Values.MainDestination or "Town"),
        AutoJoinPrivateServer = App.Values.MainAutoJoinPrivateServer == true,
        PrivateServerCode = tostring(App.Values.MainPrivateServerCode or ""),
    }
    document.Window = {
        Width = math.floor((tonumber(V12Config.WindowWidth) or 920) + 0.5),
        Height = math.floor((tonumber(V12Config.WindowHeight) or 570) + 0.5),
    }

    v12EnsureConfigFolder()
    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(document)
    end)
    if not okEncode then
        V12Config.LastStatus = "Config metadata encode failed"
        return false, V12Config.LastStatus
    end

    local okWrite, err = pcall(writeFile, V12Config.File, encoded)
    if not okWrite then
        V12Config.LastStatus = tostring(err)
        return false, V12Config.LastStatus
    end

    V12Config.LastStatus = "Updated per-account metadata"
    return true, V12Config.LastStatus
end

V12Config.SaveFlagsOnly = V12Config.SaveMetadataOnly


V12Config.ApplyValues = function(values)
    if type(values) ~= "table" then
        return false
    end

    for key, rawValue in pairs(values) do
        if App.Values[key] ~= nil
            and key ~= "AutoLoadConfig"
            and key ~= "AutoExecuteOnTeleport"
            and key ~= "GlobalConfigSync"
            and key ~= "SharedConfigCode"
            and key ~= "ConfigShareStatus"
            and string.sub(tostring(key), 1, 13) ~= "ConfigLibrary" then

            local decoded = decodeConfigValue(rawValue)
            if decoded ~= nil then
                App.Values[key] = decoded
            end
        end
    end

    return true
end

V12Config.ApplyValuesTracked = function(values)
    if type(values) ~= "table" then return {} end
    local before = {}
    for key in pairs(values) do
        before[key] = App.Values[key]
    end
    V12Config.ApplyValues(values)
    local changed = {}
    for key, oldValue in pairs(before) do
        if App.Values[key] ~= oldValue then
            changed[key] = true
        end
    end
    return changed
end


V12Config.SanitizeLoadedValues = function()
    local function member(value, allowed, fallback)
        value = tostring(value or "")
        for _, option in ipairs(allowed) do
            if value == option then return value end
        end
        return fallback
    end

    App.Values.MainSlot = member(App.Values.MainSlot, {"A","B","C"}, "A")
    App.Values.MainDestination = member(App.Values.MainDestination, {"Town","Trade"}, "Town")
    App.Values.MainAutoSlotDelay = math.clamp(math.floor((tonumber(App.Values.MainAutoSlotDelay) or 15) + 0.5), 0, 120)
    App.Values.MainAutoJoinPrivateServer = App.Values.MainAutoJoinPrivateServer == true
    App.Values.MainPrivateServerCode = tostring(App.Values.MainPrivateServerCode or "")
        :gsub("^%s+", "")
        :gsub("%s+$", "")
        :sub(1, 160)
    App.Values.Density = member(App.Values.Density, {"Compact","Comfortable"}, "Compact")
    App.Values.LobbyMode = member(App.Values.LobbyMode, {"Mission","Raid","Waves"}, "Mission")
    App.Values.BoostedDifficulty = member(
        App.Values.BoostedDifficulty,
        {"Easy","Normal","Hard","Severe","Aberrant","Hardest"},
        "Hardest"
    )
    App.Values.AutoJoinBoostedMaps = App.Values.AutoJoinBoostedMaps == true
    App.Values.BoostedModifiersEnabled = App.Values.BoostedModifiersEnabled == true
    for _, routeKey in ipairs({
        "Shiganshina","Trost","Outskirts","GiantForest",
        "UtgardCastle","LoadingDocks","Stohess","Chapel",
    }) do
        local enabledKey = "BoostedRoute" .. routeKey .. "Enabled"
        App.Values[enabledKey] = App.Values[enabledKey] ~= false
        local objectiveKey = "BoostedRoute" .. routeKey .. "Objective"
        App.Values[objectiveKey] = tostring(App.Values[objectiveKey] or "Auto")
        local modifiersKey = "BoostedRoute" .. routeKey .. "UseModifiers"
        App.Values[modifiersKey] = App.Values[modifiersKey] ~= false
    end
    App.Values.MultiGrindRole = member(App.Values.MultiGrindRole, {"Host","Alt"}, "Host")
    App.Values.MultiGrindHostUsername = tostring(App.Values.MultiGrindHostUsername or ""):gsub("^%s+", ""):gsub("%s+$", ""):sub(1, 40)
    App.Values.MultiGrindExpectedAlts = tostring(App.Values.MultiGrindExpectedAlts or ""):sub(1, 500)
    App.Values.MultiGrindRequiredPlayers = math.clamp(math.floor((tonumber(App.Values.MultiGrindRequiredPlayers) or 2) + 0.5), 2, 8)
    App.Values.MultiGrindReadyDelay = math.clamp(tonumber(App.Values.MultiGrindReadyDelay) or 2, 0, 10)
    App.Values.PrestigeBuff = member(App.Values.PrestigeBuff, {"Luck","EXP","Gold"}, "Luck")

    App.Values.FailsafeMinutes = math.clamp(math.floor((tonumber(App.Values.FailsafeMinutes) or 5) + 0.5), 1, 1440)
    App.Values.LobbyLaunchDelay = math.clamp(math.floor((tonumber(App.Values.LobbyLaunchDelay) or 10) + 0.5), 1, 300)
    App.Values.WindowTransparency = math.clamp(math.floor((tonumber(App.Values.WindowTransparency) or 50) + 0.5), 20, 70)
    App.Values.AFKTimeLimitHours = math.clamp(math.floor((tonumber(App.Values.AFKTimeLimitHours) or 0) + 0.5), 0, 168)
    App.Values.AFKEndAction = member(App.Values.AFKEndAction, {"Stay Idle","Return to Lobby","Return to Main Menu"}, "Return to Lobby")
    App.Values.BoostMinGems = math.clamp(math.floor((tonumber(App.Values.BoostMinGems) or 0) + 0.5), 0, 1000000000)
    App.Values.SpinTarget = math.clamp(math.floor((tonumber(App.Values.SpinTarget) or 0) + 0.5), 0, 1000000)
    App.Values.SpinMinGems = math.clamp(math.floor((tonumber(App.Values.SpinMinGems) or 0) + 0.5), 0, 1000000000)
    App.Values.SpinPurchaseLimit = math.clamp(math.floor((tonumber(App.Values.SpinPurchaseLimit) or 10) + 0.5), 1, 100)
    App.Values.CrateOpenDelay = math.clamp(tonumber(App.Values.CrateOpenDelay) or 0.20, 0.05, 10.00)

    local tierEnv=v12Environment()
    local tierHub=type(tierEnv.SliceHub)=="table" and tierEnv.SliceHub or {}
    local premium=tierHub.IsPremium==true
        or string.upper(tostring(tierHub.BuildTier or ""))=="PREMIUM"
        or string.upper(tostring(tierEnv.SliceHubExpectedTier or ""))=="PREMIUM"
    App.Values.FPSCap = math.clamp(
        math.floor((tonumber(App.Values.FPSCap) or 60) + 0.5),
        premium and 1 or 30,
        premium and 600 or 240
    )
    if not premium then App.Values.FPSUnlimited = false end

    App.Values.PrestigeP0M = math.clamp(math.floor((tonumber(App.Values.PrestigeP0M) or 200) + 0.5), 1, 200)
    App.Values.PrestigeP1M = math.clamp(math.floor((tonumber(App.Values.PrestigeP1M) or 400) + 0.5), 1, 400)
    App.Values.PrestigeP2M = math.clamp(math.floor((tonumber(App.Values.PrestigeP2M) or 600) + 0.5), 1, 600)
    App.Values.PrestigeP3M = math.clamp(math.floor((tonumber(App.Values.PrestigeP3M) or 800) + 0.5), 1, 800)
    App.Values.PrestigeP4M = math.clamp(math.floor((tonumber(App.Values.PrestigeP4M) or 1000) + 0.5), 1, 1000)
    App.Values.TitanMasteryMultiHit = math.clamp(math.floor((tonumber(App.Values.TitanMasteryMultiHit) or 4) + 0.5), 3, 5)
end


