V12Config.ShareCodec = V12Config.ShareCodec or {}
V12Config.ShareCodec.Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
V12Config.ShareCodec.Map = V12Config.ShareCodec.Map or {}
for i = 1, #V12Config.ShareCodec.Alphabet do
    V12Config.ShareCodec.Map[string.sub(V12Config.ShareCodec.Alphabet,i,i)] = i - 1
end

V12Config.ShareCodec.Encode = function(data)
    local out = {}
    for i = 1, #data, 3 do
        local a = string.byte(data, i) or 0
        local b = string.byte(data, i + 1)
        local c = string.byte(data, i + 2)
        local n = a * 65536 + (b or 0) * 256 + (c or 0)
        local c1 = math.floor(n / 262144) % 64 + 1
        local c2 = math.floor(n / 4096) % 64 + 1
        local c3 = math.floor(n / 64) % 64 + 1
        local c4 = n % 64 + 1
        out[#out+1] = string.sub(V12Config.ShareCodec.Alphabet, c1, c1)
        out[#out+1] = string.sub(V12Config.ShareCodec.Alphabet, c2, c2)
        if b then out[#out+1] = string.sub(V12Config.ShareCodec.Alphabet, c3, c3) end
        if c then out[#out+1] = string.sub(V12Config.ShareCodec.Alphabet, c4, c4) end
    end
    return (table.concat(out):gsub("%+", "-"):gsub("/", "_"))
end

V12Config.ShareCodec.Decode = function(data)
    data = tostring(data or ""):gsub("-", "+"):gsub("_", "/")
    if data == "" or string.find(data, "[^A-Za-z0-9+/]", 1) then return nil end
    local out = {}
    for i = 1, #data, 4 do
        local a,b,c,d = string.sub(data,i,i),string.sub(data,i+1,i+1),string.sub(data,i+2,i+2),string.sub(data,i+3,i+3)
        local va,vb = V12Config.ShareCodec.Map[a],V12Config.ShareCodec.Map[b]
        if va == nil or vb == nil then return nil end
        local vc,vd = c ~= "" and V12Config.ShareCodec.Map[c] or nil, d ~= "" and V12Config.ShareCodec.Map[d] or nil
        local n = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
        out[#out+1] = string.char(math.floor(n / 65536) % 256)
        if vc ~= nil then out[#out+1] = string.char(math.floor(n / 256) % 256) end
        if vd ~= nil then out[#out+1] = string.char(n % 256) end
    end
    return table.concat(out)
end

V12Config.ShareCodec.Pack = function(value)
    if typeof(value) == "Color3" then
        return {"c", math.floor(value.R*255+0.5), math.floor(value.G*255+0.5), math.floor(value.B*255+0.5)}
    end
    local t = type(value)
    if t == "boolean" or t == "string" or t == "number" then return value end
    return nil
end

V12Config.ShareCodec.Unpack = function(value)
    if type(value) == "table" and value[1] == "c" then
        local r,g,b = tonumber(value[2]),tonumber(value[3]),tonumber(value[4])
        if r and g and b then return Color3.fromRGB(math.clamp(r,0,255),math.clamp(g,0,255),math.clamp(b,0,255)) end
        return nil
    end
    local t=type(value)
    if t=="boolean" or t=="string" or t=="number" then return value end
    return nil
end


V12Config.ShareCodec.IsBlockedKey = function(key)
    local normalized = string.lower(tostring(key or ""))
    return normalized == "sharedconfigcode"
        or string.find(normalized, "webhookurl", 1, true) ~= nil
        or string.find(normalized, "userid", 1, true) ~= nil
        or string.find(normalized, "hwid", 1, true) ~= nil
        or string.find(normalized, "license", 1, true) ~= nil
end

V12Config.ShareCodec.TierCode = function()
    local function isPremiumTier(value)
        return string.upper(tostring(value or "")) == "PREMIUM"
    end

    if BUILD and (BUILD.IsPremium == true or isPremiumTier(BUILD.Tier)) then
        return "P"
    end

    if Environment and type(Environment.SliceHub) == "table"
        and (Environment.SliceHub.IsPremium == true
            or isPremiumTier(Environment.SliceHub.BuildTier)) then
        return "P"
    end

    if Environment and isPremiumTier(Environment.SliceHubExpectedTier) then
        return "P"
    end

    return "F"
end

V12Config.EnforceShareTier = function()
    local adjusted = 0
    if V12Config.ShareCodec and V12Config.ShareCodec.TierCode and V12Config.ShareCodec.TierCode()=="P" then return adjusted end
    local function cap(key, maximum)
        if App.Values[key] ~= nil and tonumber(App.Values[key]) ~= nil then
            local before=tonumber(App.Values[key]); local after=math.min(before,maximum)
            if after ~= before then App.Values[key]=after; adjusted += 1 end
        end
    end
    cap("BladeMultiHit",5)
    cap("RaidBossMultiHit",1)
    cap("SpearMultiHit",1)
    if App.Values.FPSUnlimited == true then App.Values.FPSUnlimited=false; adjusted += 1 end
    return adjusted
end

V12Config.ExportShareCode = function()
    App.Values.ConfigShareStatus = "Config sharing removed • per-account only"
    return false, App.Values.ConfigShareStatus
end

V12Config.ImportShareCode = function()
    App.Values.ConfigShareStatus = "Config sharing removed • per-account only"
    return false, App.Values.ConfigShareStatus
end

V12Config.ImportShareCodeSession = function(raw)
    raw=tostring(raw or ""):gsub("^%s+",""):gsub("%s+$","")
    if string.sub(raw,1,7) ~= "SHCFG1:" then
        return false,"Paste a valid SHCFG1 code",0,0,0
    end
    local decoded=V12Config.ShareCodec.Decode(string.sub(raw,8))
    if not decoded then return false,"Config code decode failed",0,0,0 end
    local ok,document=pcall(function() return HttpService:JSONDecode(decoded) end)
    if not ok or type(document)~="table" or tonumber(document.v)~=1 or type(document.x)~="table" then
        return false,"Unsupported config code",0,0,0
    end
    local applied,skipped=0,0
    for _,entry in ipairs(document.x) do
        local id=type(entry)=="table" and tonumber(entry[1]) or nil
        local key=id and V12Config.ShareKeys[id] or nil
        local value=type(entry)=="table" and V12Config.ShareCodec.Unpack(entry[2]) or nil
        if key and not V12Config.ShareCodec.IsBlockedKey(key) and App.Values[key] ~= nil and value ~= nil then
            App.Values[key]=value
            applied += 1
        else
            skipped += 1
        end
    end
    V12Config.SanitizeLoadedValues()
    local adjusted=V12Config.EnforceShareTier()
    App.Values.SharedConfigCode=raw
    return true,string.format("SHCFG1 session • %d applied • %d adjusted • %d ignored",applied,adjusted,skipped),applied,adjusted,skipped
end

V12Config.BuildSessionShareCode = function()
    local entries={}
    for id,key in ipairs(V12Config.ShareKeys) do
        if not V12Config.ShareCodec.IsBlockedKey(key) and App.Values[key] ~= nil then
            local packed=V12Config.ShareCodec.Pack(App.Values[key])
            if packed ~= nil then entries[#entries+1]={id,packed} end
        end
    end
    local ok,raw=pcall(function()
        return HttpService:JSONEncode({
            v=1,
            t=V12Config.ShareCodec.TierCode(),
            r="15.6",
            x=entries,
        })
    end)
    if not ok then return nil end
    return "SHCFG1:"..V12Config.ShareCodec.Encode(raw)
end

V12Config.ApplyKaitun = function()
    local env=v12Environment()
    local cfg=type(env)=="table" and env.SliceHubKaitun or nil
    if type(cfg)~="table" then return false,"No Kaitun" end

    local hub=type(env.SliceHub)=="table" and env.SliceHub or {}
    local premium=hub.IsPremium==true
        or string.upper(tostring(hub.BuildTier or ""))=="PREMIUM"
        or string.upper(tostring(env.SliceHubExpectedTier or ""))=="PREMIUM"

    if not premium then
        V12Config.KaitunBlocked=true
        V12Config.KaitunStatus="Nah uh bro, nice try 💀 SliceHub Kaitun is Premium only."
        task.delay(1.0,function()
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification",{
                    Title="SliceHub Kaitun",
                    Text=V12Config.KaitunStatus,
                    Duration=8,
                })
            end)
        end)
        return false,V12Config.KaitunStatus
    end

    V12Config.KaitunActive=true
    V12Config.KaitunBlocked=false
    App.Values.AutoLoadConfig=false
    App.Values.GlobalConfigSync=false
    V12Config.GlobalEnabled=false

    local applied,ignored=0,0
    local function setValue(key,value)
        if value==nil then return false end
        if App.Values[key]==nil then ignored += 1 return false end
        local expected=typeof(App.Values[key])
        local actual=typeof(value)
        if expected=="Color3" then
            if actual~="Color3" then ignored += 1 return false end
        elseif type(App.Values[key])~=type(value) then
            ignored += 1
            return false
        end
        App.Values[key]=value
        applied += 1
        return true
    end
    local function setBool(key,value)
        if type(value)=="boolean" then return setValue(key,value) end
        return false
    end
    local function setNumber(key,value)
        if tonumber(value)~=nil then return setValue(key,tonumber(value)) end
        return false
    end
    local function setString(key,value)
        if type(value)=="string" then return setValue(key,value) end
        return false
    end
    local function firstTableValue(tbl,index)
        return type(tbl)=="table" and tbl[index] or nil
    end

    local configCode=cfg.Config or cfg.ConfigCode
    if type(configCode)=="string" and configCode~="" then
        local okImport,message,a,_,s=V12Config.ImportShareCodeSession(configCode)
        if okImport then
            applied += tonumber(a) or 0
            ignored += tonumber(s) or 0
            V12Config.KaitunConfigStatus=message
        else
            ignored += 1
            V12Config.KaitunConfigStatus=tostring(message)
        end
    end

    setBool("MissionAutoRetry", cfg.MissionAutoRetry)
    setBool("RaidRetry", cfg.RaidRetry)

    local farm=cfg.Farm
    if type(farm)=="table" then
        if type(farm.Enabled)=="boolean" then
            if farm.Enabled==false then
                setValue("AutoFarmBlades",false)
                setValue("AutoFarmSpears",false)
            elseif farm.Blades==nil and farm.Spears==nil then
                setValue("AutoFarmBlades",true)
            end
        end
        setBool("AutoFarmBlades",farm.Blades)
        setBool("AutoFarmSpears",farm.Spears)
        setBool("MissionAutoRetry",farm.AutoRetry)
        if type(farm.AutoReload)=="boolean" then
            if farm.AutoBladeRefill==nil then setValue("AutoBladeRefill",farm.AutoReload) end
            if farm.AutoSpearRefill==nil then setValue("AutoSpearRefill",farm.AutoReload) end
        end
        setBool("AutoBladeRefill",farm.AutoBladeRefill)
        setBool("AutoSpearRefill",farm.AutoSpearRefill)
        setNumber("MissionLimit",farm.MissionLimit)
        setNumber("BladeMultiHit",farm.BladeMultiHit)
        setNumber("SpearMultiHit",farm.SpearMultiHit)
        setString("MovementMode",farm.HoverMethod or farm.MovementMode)
        setNumber("SmoothSpeed",farm.HoverSpeed or farm.SmoothSpeed)
        setBool("SafeFarm",farm.SafeFarm)
        setNumber("FarmSafetyDelay",farm.FinalTitanDelay or farm.FarmSafetyDelay)
        setBool("LeaveIfAnotherPlayer",farm.LeaveIfAnotherPlayer)
        setBool("AutoDieAtStreak",farm.AutoDieAtStreak)
        setNumber("AutoDieStreak",farm.StreakToDieAt or farm.AutoDieStreak)
        setString("TargetPriority",farm.TargetPriority)
        setNumber("TargetRange",farm.TargetRange)
        setBool("Disable3DRendering",farm.Disable3DRendering)
        if tonumber(farm.FPSCap)~=nil then
            setValue("FPSCapEnabled",true)
            setNumber("FPSCap",farm.FPSCap)
        end
        setBool("RemoveMapProps",farm.HideMapProps)
        if farm.ReturnToLobby~=nil then ignored += 1 end
    end

    local launch=cfg.AutoLaunch
    if type(launch)=="table" then
        setBool("LobbyAutoLaunch",launch.Enabled)
        App.Values.LobbyKickPartyBeforeLaunch = false
        setNumber("LobbyLaunchDelay",launch.Delay)
        if type(launch.Type)=="string" then
            local mode=string.lower(launch.Type)
            if mode=="mission" or mode=="missions" then setValue("LobbyMode","Mission")
            elseif mode=="raid" or mode=="raids" then setValue("LobbyMode","Raid")
            elseif mode=="wave" or mode=="waves" then setValue("LobbyMode","Waves")
            else ignored += 1 end
        end
        setString("LobbyMap",launch.Map)
        setString("LobbyObjective",launch.Objective)
        setString("LobbyDifficulty",launch.Difficulty)
        setString("LobbyRaidChoice",launch.Raid)
        if type(launch.Modifiers)=="table" then
            local modifierKeys={
                ["no perks"]="LobbyModNoPerks",
                ["no skills"]="LobbyModNoSkills",
                ["no memories"]="LobbyModNoMemories",
                ["nightmare"]="LobbyModNightmare",
                ["oddball"]="LobbyModOddball",
                ["injury prone"]="LobbyModInjuryProne",
                ["chronic injuries"]="LobbyModChronicInjuries",
                ["fog"]="LobbyModFog",
                ["glass cannon"]="LobbyModGlassCannon",
                ["time trial"]="LobbyModTimeTrial",
                ["simple"]="LobbyModSimple",
                ["boring"]="LobbyModBoring",
            }
            for _,key in pairs(modifierKeys) do App.Values[key]=false end
            local count=0
            for _,name in ipairs(launch.Modifiers) do
                local key=modifierKeys[string.lower(tostring(name))]
                if key then App.Values[key]=true; count += 1 else ignored += 1 end
            end
            App.Values.LobbyModifiersEnabled=count>0
            applied += count + 1
        end
    end

    local slot=cfg.AutoSlot
    if type(slot)=="table" then
        setBool("MainAutoSelectSlot",slot.Enabled)
        if slot.Delay~=nil or slot.DelaySeconds~=nil then
            setValue("MainAutoSlotDelay",slot.DelaySeconds~=nil and slot.DelaySeconds or slot.Delay)
        end
        setString("MainSlot",slot.Slot)
        setString("MainDestination",slot.Destination)
        if slot.AutoJoinPrivateServer~=nil then
            setBool("MainAutoJoinPrivateServer",slot.AutoJoinPrivateServer)
        end
        if slot.PrivateServerCode~=nil then
            setString("MainPrivateServerCode",slot.PrivateServerCode)
            if slot.AutoJoinPrivateServer==nil and tostring(slot.PrivateServerCode)~="" then
                setBool("MainAutoJoinPrivateServer",true)
            end
        end
    end

    local prestige=cfg.AutoPrestige
    if type(prestige)=="table" then
        setBool("AutoPrestigeEnabled",prestige.Enabled)
        if type(prestige.Boost)=="string" then
            local boost=string.lower(prestige.Boost)
            if string.find(boost,"gold",1,true) then setValue("PrestigeBuff","Gold")
            elseif string.find(boost,"luck",1,true) then setValue("PrestigeBuff","Luck")
            elseif string.find(boost,"xp",1,true) or string.find(boost,"exp",1,true) then setValue("PrestigeBuff","EXP")
            else ignored += 1 end
        end
        if type(prestige.GoldThresholds)=="table" then
            local keys={"PrestigeP0M","PrestigeP1M","PrestigeP2M","PrestigeP3M","PrestigeP4M"}
            for index,key in ipairs(keys) do
                local raw=tonumber(prestige.GoldThresholds[index])
                if raw then
                    local millions=raw>10000 and (raw/1000000) or raw
                    setValue(key,math.floor(millions+0.5))
                end
            end
        end
    end

    local upgrade=cfg.AutoUpgrade
    if type(upgrade)=="table" then
        setBool("AutoUpgradeEnabled",upgrade.Enabled)
        if type(upgrade.Blades)=="boolean" then
            setValue("UpgradeBladeDurability",upgrade.Blades)
            setValue("UpgradeCritChance",upgrade.Blades)
            setValue("UpgradeCritDamage",upgrade.Blades)
        end
        if type(upgrade.ODM)=="boolean" then
            for _,key in ipairs({"UpgradeODMDamage","UpgradeODMGas","UpgradeODMRange","UpgradeODMControl","UpgradeODMSpeed"}) do
                setValue(key,upgrade.ODM)
            end
        end
        if type(upgrade.Spears)=="boolean" then
            for _,key in ipairs({"UpgradeTSDamage","UpgradeBlastRadius","UpgradeTSGas","UpgradeTSRange","UpgradeTSSpeed","UpgradeTSControl"}) do
                setValue(key,upgrade.Spears)
            end
            if upgrade.Blades==nil then
                setValue("UpgradeCritChance",upgrade.Spears)
                setValue("UpgradeCritDamage",upgrade.Spears)
            end
        end
    end

    local boosts=cfg.Boosts
    if type(boosts)=="table" then
        setBool("AutoBuyBoosts",boosts.AutoBuy)
        setBool("AutoUseBoost",boosts.AutoUse)
        setBool("AutoUseBoostWhenExpired",boosts.RepeatWhenExpired)
        setString("BoostType",boosts.Type)
        setString("BoostDuration",boosts.Duration)
        setNumber("BoostBuyAmount",boosts.BuyAmount)
        setNumber("BoostMinGems",boosts.MinGems)
        local selected=firstTableValue(boosts.Selected,1)
        if type(selected)=="string" then
            local lower=string.lower(selected)
            if string.find(lower,"gold",1,true) then setValue("BoostType","Gold")
            elseif string.find(lower,"luck",1,true) then setValue("BoostType","Luck")
            elseif string.find(lower,"xp",1,true) or string.find(lower,"exp",1,true) then setValue("BoostType","XP") end
            if string.find(lower,"30m",1,true) then setValue("BoostDuration","30m")
            elseif string.find(lower,"1h",1,true) then setValue("BoostDuration","1h")
            elseif string.find(lower,"2h",1,true) then setValue("BoostDuration","2h") end
        end
    end

    local selling=cfg.SellPerks
    if type(selling)=="table" then
        setBool("AutoSellPerks",selling.Enabled)
        local rarities=selling.Rarities
        if type(rarities)=="table" then
            setBool("SellPerkCommon",rarities.Common)
            setBool("SellPerkRare",rarities.Rare)
            setBool("SellPerkEpic",rarities.Epic)
            setBool("SellPerkLegendary",rarities.Legendary)
            setBool("SellPerkMythic",rarities.Mythic)
        end
    end

    local lobby=cfg.Lobby
    if type(lobby)=="table" then
        setBool("AutoClaimAchievements",lobby.ClaimAchievements)
        if lobby.ClaimQuests~=nil then ignored += 1 end
    end

    if type(cfg.SkillTree)=="table" then ignored += 1 end
    if type(cfg.EquipPerks)=="table" then ignored += 1 end
    if type(cfg.EnhancePerks)=="table" then ignored += 1 end

    local afk=cfg.AFK
    if type(afk)=="table" then
        setNumber("MissionLimit",afk.MissionLimit)
        if tonumber(afk.TimeLimitHours)~=nil then
            setNumber("AFKTimeLimitHours",afk.TimeLimitHours)
        elseif tonumber(afk.TimeLimitMinutes)~=nil then
            local minutes=math.max(0,tonumber(afk.TimeLimitMinutes) or 0)
            setValue("AFKTimeLimitHours",minutes<=0 and 0 or math.max(1,math.ceil(minutes/60)))
        end
        if type(afk.FinishAction)=="string" then
            local action=string.lower(afk.FinishAction)
            if action=="stay idle" then setValue("AFKEndAction","Stay Idle")
            elseif action=="return to lobby" then setValue("AFKEndAction","Return to Lobby")
            elseif action=="return to main menu" then setValue("AFKEndAction","Return to Main Menu")
            else ignored += 1 end
        end
        setBool("AFKAttentionAlerts",afk.AttentionAlerts)
        setBool("AFKPingUser",afk.PingUser)
        setBool("AFKNotifyOnFinish",afk.NotifyOnFinish)
    end

    local recovery=cfg.Recovery
    if type(recovery)=="table" then
        setBool("FailsafeEnabled",recovery.Enabled)
        setBool("FailsafeSmart",recovery.Smart)
        if tonumber(recovery.Minutes)~=nil then
            setNumber("FailsafeMinutes",recovery.Minutes)
        elseif tonumber(recovery.Timeout)~=nil then
            setValue("FailsafeMinutes",math.max(1,math.ceil((tonumber(recovery.Timeout) or 60)/60)))
        end
    end

    local raids=cfg.Raids
    if type(raids)=="table" then
        setBool("RaidRetry",raids.AutoRetry)
        setNumber("RaidBossMultiHit",raids.BossMultiHit)
        setBool("ColossalRemastered",raids.ColossalRemastered)
        setBool("RaidAutoOpenChests",raids.AutoOpenChests)
        setBool("RaidOpenFreeChest",raids.FreeChest)
        setBool("RaidOpenPremiumChest",raids.PremiumChest)
    end

    local waves=cfg.Waves
    if type(waves)=="table" then
        setBool("WavesAutoFarm",waves.AutoFarm)
        setBool("WavesAutoSkip",waves.AutoSkip)
        setBool("WavesAutoCrates",waves.AutoCrates)
        setBool("WavesAutoUpgrade",waves.AutoUpgrade)
        setBool("WavesUpgradeGear",waves.UpgradeGear)
        setString("WavesGearTarget",waves.GearTarget)
        setBool("WavesUpgradeHQ",waves.UpgradeHQ)
        setBool("WavesHQMax",waves.HQMaxHealth)
        setBool("WavesHQRegen",waves.HQRegen)
        setBool("WavesHQRefills",waves.HQRefills)
        setBool("WavesHQReplenish",waves.HQReplenish)
        setBool("WavesHQRevive",waves.HQRevive)
        setBool("WavesAutoBuyTS",waves.AutoBuyThunderSpears or waves.AutoBuyTS)
        setBool("WavesUpgradeDamage",waves.Damage)
        setBool("WavesUpgradeCritical",waves.Critical)
        setBool("WavesUpgradeCooldown",waves.Cooldown)
        setBool("WavesUpgradeRegen",waves.Regen)
        setString("WavesUpgradePriority",waves.Priority)
    end

    local skills=cfg.Skills
    if type(skills)=="table" then
        setBool("AutoUseSkills",skills.Enabled)
        setBool("SkillOrderRage",skills.OrderRage)
        setBool("SkillOrderAdvance",skills.OrderAdvance)
        setBool("SkillBlackFlare",skills.BlackFlare)
        setBool("SkillRedFlare",skills.RedFlare)
        setBool("SkillRageMode",skills.RageMode)
        setBool("SkillConquer",skills.Conquer)
        setBool("SkillOrderCommand",skills.OrderCommand)
        setBool("SkillOrderRevolution",skills.OrderRevolution)
    end

    local ts=cfg.AutoThunderSpears
    if type(ts)=="table" then
        setBool("AutoTSClaimCompleted",ts.ClaimCompleted)
        setBool("AutoTSLaunchNext",ts.LaunchNext)
        setBool("AutoTSDoQuests",ts.DoQuests)
        setBool("AutoTSReturnLobby",ts.ReturnLobby)
    end

    local family=cfg.FamilySpinner
    if type(family)=="table" then
        setBool("FamilySpinEnabled",family.Enabled)
        setBool("FamilyAutoDepositMythic", family.AutoDepositMythics or family.AutoDepositRolledFamily or family.DepositMythics)
        setString("FamilyTargetMode",family.TargetMode)
        setNumber("FamilySpinDelay",family.Delay)
        local rarities=family.Rarities
        if type(rarities)=="table" then
            setBool("FamilyTargetEpic",rarities.Epic)
            setBool("FamilyTargetLegendary",rarities.Legendary)
            setBool("FamilyTargetMythic",rarities.Mythic)
        end
        if type(family.Families)=="table" then
            local familyKeys={
                Arlert="FamilyTargetArlert",Zoe="FamilyTargetZoe",Tybur="FamilyTargetTybur",
                Leonhart="FamilyTargetLeonhart",Galliard="FamilyTargetGalliard",Finger="FamilyTargetFinger",
                Braun="FamilyTargetBraun",Ksaver="FamilyTargetKsaver",Ackerman="FamilyTargetAckerman",
                Yeager="FamilyTargetYeager",Reiss="FamilyTargetReiss",Fritz="FamilyTargetFritz",Helos="FamilyTargetHelos",
            }
            for _,key in pairs(familyKeys) do App.Values[key]=false end
            for _,name in ipairs(family.Families) do
                local key=familyKeys[tostring(name)]
                if key then App.Values[key]=true; applied += 1 else ignored += 1 end
            end
        end
    end

    local optimization=cfg.Optimization
    if type(optimization)=="table" then
        setString("OptPreset",optimization.Preset)
        setBool("SimpleLighting",optimization.SimpleLighting)
        setBool("RemoveFog",optimization.RemoveFog)
        setBool("DisableParticlesTrails",optimization.DisableParticlesTrails)
        setBool("LowDetailMaterials",optimization.LowDetailMaterials)
        setBool("RemoveMapTextures",optimization.RemoveMapTextures)
        setBool("RemoveMapProps",optimization.RemoveMapProps)
        setBool("ReduceTitanEffects",optimization.ReduceTitanEffects)
        setBool("DisableCameraEffects",optimization.DisableCameraEffects)
        setBool("SleepHidden",optimization.SleepWhenHidden)
        setBool("Disable3DRendering",optimization.Disable3DRendering)
        if tonumber(optimization.FPSCap)~=nil then
            setValue("FPSCapEnabled",true)
            setNumber("FPSCap",optimization.FPSCap)
        end
        setBool("FPSUnlimited",optimization.FPSUnlimited)
    end

    local ui=cfg.UI
    if type(ui)=="table" then
        setBool("StartHidden",ui.StartHidden)
        setBool("AutoHideUI",ui.AutoHide)
        setBool("FastStartup",ui.FastStartup)
        setString("Density",ui.Density)
        setNumber("WindowTransparency",ui.WindowTransparency)
        setBool("ShowMacButtons",ui.ShowMacButtons)
        setBool("ScriptCursor",ui.ScriptCursor)
    end

    if type(cfg.SkipWelcomeGUI)=="boolean" then
        setBool("FastStartup",cfg.SkipWelcomeGUI)
    end

    if type(cfg.AutoSkipCutscene)=="boolean" then setValue("AutoSkipCutscene",cfg.AutoSkipCutscene) end

    local webhooks=cfg.Webhooks
    if type(webhooks)=="table" then
        local preset=type(V12Config.WebhookPreset)=="table" and V12Config.WebhookPreset or {}
        if type(webhooks.Enabled)=="boolean" then
            setValue("WebhookEnabled",webhooks.Enabled)
            preset.Enabled=webhooks.Enabled
        end
        if type(webhooks.URL)=="string" then
            App.Values.WebhookURL=webhooks.URL
            preset.URL=webhooks.URL
            applied += 1
        end
        if type(webhooks.DiscordUserID)=="string" or type(webhooks.DiscordUserID)=="number" then
            App.Values.WebhookPingUserId=tostring(webhooks.DiscordUserID)
            preset.PingUserId=tostring(webhooks.DiscordUserID)
            applied += 1
        end
        if type(webhooks.SendCompleted)=="boolean" then setValue("WebhookSendCompleted",webhooks.SendCompleted); preset.SendCompleted=webhooks.SendCompleted end
        if type(webhooks.SendFailed)=="boolean" then setValue("WebhookSendFailed",webhooks.SendFailed); preset.SendFailed=webhooks.SendFailed end
        if type(webhooks.IncludeStats)=="boolean" then setValue("WebhookStats",webhooks.IncludeStats); preset.IncludeStats=webhooks.IncludeStats end
        if type(webhooks.PingOnRareDrop)=="boolean" then setValue("WebhookHighValue",webhooks.PingOnRareDrop); preset.HighValue=webhooks.PingOnRareDrop end
        if type(webhooks.PingOnAttention)=="boolean" then
            setValue("AFKAttentionAlerts",webhooks.PingOnAttention)
            setValue("WebhookNoPingAttention",not webhooks.PingOnAttention)
            preset.NoPingAttention=not webhooks.PingOnAttention
        end
        V12Config.WebhookPreset=preset
        V12Config.KaitunWebhookPresetApplied=true
        if webhooks.ShowUsername~=nil then ignored += 1 end
    end

    if type(cfg.Values)=="table" then
        local allowed={}
        for _,key in ipairs(V12Config.ShareKeys) do allowed[key]=true end
        for key,value in pairs(cfg.Values) do
            key=tostring(key)
            if allowed[key] and not V12Config.ShareCodec.IsBlockedKey(key) then
                setValue(key,value)
            else
                ignored += 1
            end
        end
    end

    if type(cfg.AutoExecuteOnTeleport)=="boolean" then
        setValue("AutoExecuteOnTeleport",cfg.AutoExecuteOnTeleport)
    else
        setValue("AutoExecuteOnTeleport",true)
    end

    App.Values.GlobalConfigSync=false
    V12Config.GlobalEnabled=false
    V12Config.SanitizeLoadedValues()
    if not premium then
        V12Config.EnforceShareTier()
    end

    -- Kaitun is authoritative after every overlay. Re-apply values that are
    -- particularly sensitive to saved/global config timing.
    if premium and type(farm)=="table" then
        if tonumber(farm.BladeMultiHit)~=nil then
            App.Values.BladeMultiHit=math.clamp(math.floor(tonumber(farm.BladeMultiHit)+0.5),1,10)
        end
        if tonumber(farm.SpearMultiHit)~=nil then
            App.Values.SpearMultiHit=math.clamp(math.floor(tonumber(farm.SpearMultiHit)+0.5),1,10)
        end
    end

    V12Config.KaitunCarryCode=V12Config.BuildSessionShareCode()
    V12Config.LoadedAtBoot=true
    V12Config.BootSource="Kaitun"
    V12Config.KaitunStatus=string.format("Premium Kaitun • execution owns config • %d applied • %d ignored",applied,ignored)
    V12Config.LastStatus=V12Config.KaitunStatus
    App.Values.ConfigShareStatus=V12Config.KaitunStatus

    if cfg.PersistConfig==true then
        App.Values.AutoLoadConfig=true
        local callOk,saved=pcall(writeV12Config)
        if callOk and saved then V12Config.KaitunStatus=V12Config.KaitunStatus.." • saved" end
    end

    return true,V12Config.KaitunStatus
end


V12Config.ReadGlobal = function()
    local readFile = select(1, v12FileFunctions())

    if type(readFile) ~= "function" then
        return nil, "File storage unavailable"
    end

    local okRead, raw = pcall(readFile, V12Config.GlobalFile)
    if not okRead or type(raw) ~= "string" or raw == "" then
        return nil, "No global config"
    end

    local okDecode, document = pcall(function()
        return HttpService:JSONDecode(raw)
    end)

    if not okDecode or type(document) ~= "table" then
        return nil, "Global config is invalid"
    end

    return document
end

V12Config.WriteGlobal = function(document)
    local _, writeFile = v12FileFunctions()

    if type(writeFile) ~= "function" then
        return false, "File storage unavailable"
    end

    v12EnsureConfigFolder()

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(document)
    end)

    if not okEncode then
        return false, "Global config encode failed"
    end

    local okWrite, err = pcall(
        writeFile,
        V12Config.GlobalFile,
        encoded
    )

    if not okWrite then
        return false, tostring(err)
    end

    return true, "Global config saved"
end

V12Config.EnableGlobalFromSaved = function()
    local saved, readReason = readV12Config()

    if type(saved) ~= "table"
        or type(saved.Values) ~= "table" then
        return false,
            tostring(
                readReason
                or "Save Default config first"
            )
    end

    local document = {
        Version = 1,
        Enabled = true,
        Name = tostring(saved.Name or V12Config.Name),
        SourceUserId = player.UserId,
        SourceUsername = player.Name,
        SourceSavedAt = saved.SavedAt,
        GlobalSavedAt = os.time(),
        Values = saved.Values,
    }

    local ok, reason = V12Config.WriteGlobal(document)
    if not ok then
        return false, reason
    end

    V12Config.GlobalEnabled = true
    V12Config.GlobalSourceUserId = player.UserId
    V12Config.GlobalSourceUsername = player.Name
    V12Config.GlobalConfigName = tostring(document.Name or V12Config.ActiveName or "Default")
    V12Config.GlobalSavedAt = document.GlobalSavedAt
    V12Config.LastGlobalSeenAt = document.GlobalSavedAt
    App.Values.GlobalConfigSync = true
    V12Config.LastStatus = "GLOBAL • " .. tostring(player.Name)

    pcall(V12Config.SaveMetadataOnly)

    return true, "Global snapshot enabled • " .. tostring(player.Name)
end

V12Config.DisableGlobal = function()
    local previous = V12Config.ReadGlobal()

    local document = {
        Version = 1,
        Enabled = false,
        Name = type(previous) == "table"
            and tostring(previous.Name or V12Config.Name)
            or V12Config.Name,
        SourceUserId = type(previous) == "table"
            and previous.SourceUserId
            or player.UserId,
        SourceUsername = type(previous) == "table"
            and previous.SourceUsername
            or player.Name,
        SourceSavedAt = type(previous) == "table"
            and previous.SourceSavedAt
            or nil,
        GlobalSavedAt = os.time(),
        Values = type(previous) == "table"
            and previous.Values
            or nil,
    }

    local ok, reason = V12Config.WriteGlobal(document)
    if not ok then
        return false, reason
    end

    V12Config.GlobalEnabled = false
    V12Config.GlobalSourceUserId = document.SourceUserId
    V12Config.GlobalSourceUsername = document.SourceUsername
    V12Config.GlobalConfigName = tostring(document.Name or "Default")
    V12Config.GlobalSavedAt = document.GlobalSavedAt
    V12Config.LastGlobalSeenAt = document.GlobalSavedAt
    App.Values.GlobalConfigSync = false
    V12Config.LastStatus = "Per-account mode • " .. tostring(player.Name)

    pcall(V12Config.SaveMetadataOnly)

    return true, "Global snapshot disabled"
end

V12Config.RefreshGlobalFromSaved = function()
    if App.Values.GlobalConfigSync ~= true then
        return true, "Global sync off"
    end

    return V12Config.EnableGlobalFromSaved()
end

V12Config.ResolveSourceUsername = function()
    local username = tostring(
        V12Config.GlobalSourceUsername or ""
    )

    if username ~= "" then
        return username
    end

    local sourceId =
        tonumber(V12Config.GlobalSourceUserId)

    if sourceId and sourceId > 0 then
        local ok, result = pcall(function()
            return Players:GetNameFromUserIdAsync(sourceId)
        end)

        if ok
            and type(result) == "string"
            and result ~= "" then
            V12Config.GlobalSourceUsername = result
            return result
        end
    end

    return "Unknown"
end



-- SEP10 Config Library QOL: named per-account configs with full-state share/import.
V12Config.DefaultFile = V12Config.DefaultFile or ("SH/config/v12_new_" .. tostring(player.UserId) .. ".json")
V12Config.LibraryIndexFile = "SH/config/library_" .. tostring(player.UserId) .. ".json"
V12Config.LibraryFolder = "SH/config/profiles/" .. tostring(player.UserId)
V12Config.ActiveName = V12Config.ActiveName or "Default"
V12Config.AutoLoadName = V12Config.AutoLoadName or ""
V12Config.LibraryIndex = V12Config.LibraryIndex or nil

V12Config.NormalizeProfileName = function(raw)
    local name = tostring(raw or "")
        :gsub("[%c]", " ")
        :gsub("^%s+", "")
        :gsub("%s+$", "")
        :gsub("%s%s+", " ")
    if name == "" then name = "Default" end
    if #name > 40 then name = string.sub(name, 1, 40):gsub("%s+$", "") end
    if name == "" then name = "Default" end
    return name
end

V12Config.ProfileFile = function(rawName)
    local name = V12Config.NormalizeProfileName(rawName)
    if string.lower(name) == "default" then
        return V12Config.DefaultFile
    end
    local encoded = {}
    for i = 1, #name do
        encoded[#encoded + 1] = string.format("%02x", string.byte(name, i))
    end
    return V12Config.LibraryFolder .. "/" .. table.concat(encoded) .. ".json"
end

V12Config.EnsureLibraryFolders = function()
    v12EnsureConfigFolder()
    local _, _, makeFolder = v12FileFunctions()
    if type(makeFolder) == "function" then
        pcall(makeFolder, "SH/config/profiles")
        pcall(makeFolder, V12Config.LibraryFolder)
    end
end

V12Config.ReadLibraryIndex = function()
    local readFile = select(1, v12FileFunctions())
    if type(readFile) ~= "function" then return nil, false end
    local okRead, raw = pcall(readFile, V12Config.LibraryIndexFile)
    if not okRead or type(raw) ~= "string" or raw == "" then return nil, false end
    local okDecode, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not okDecode or type(data) ~= "table" then return nil, false end
    return data, true
end

V12Config.WriteLibraryIndex = function()
    local _, writeFile = v12FileFunctions()
    if type(writeFile) ~= "function" then return false, "File storage unavailable" end
    V12Config.EnsureLibraryFolders()
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {}
    idx.Version = 1
    idx.UserId = player.UserId
    idx.ActiveName = V12Config.NormalizeProfileName(V12Config.ActiveName)
    idx.AutoLoadName = V12Config.AutoLoadName ~= "" and V12Config.NormalizeProfileName(V12Config.AutoLoadName) or ""
    idx.UpdatedAt = os.time()
    if type(idx.Names) ~= "table" then idx.Names = {"Default"} end
    V12Config.LibraryIndex = idx
    local okEncode, encoded = pcall(function() return HttpService:JSONEncode(idx) end)
    if not okEncode then return false, "Config library encode failed" end
    local okWrite, err = pcall(writeFile, V12Config.LibraryIndexFile, encoded)
    if not okWrite then return false, tostring(err) end
    return true, "Config library updated"
end

V12Config.ProfileKnown = function(rawName)
    local name = V12Config.NormalizeProfileName(rawName)
    if string.lower(name) == "default" then return true end
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {}
    for _, existing in ipairs(type(idx.Names) == "table" and idx.Names or {}) do
        if string.lower(tostring(existing)) == string.lower(name) then return true end
    end
    return false
end

V12Config.ResolveProfileName = function(rawName)
    local name = V12Config.NormalizeProfileName(rawName)
    if string.lower(name) == "default" then return "Default" end
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {}
    for _, existing in ipairs(type(idx.Names) == "table" and idx.Names or {}) do
        if string.lower(tostring(existing)) == string.lower(name) then return tostring(existing) end
    end
    return name
end

V12Config.RegisterProfile = function(rawName)
    local name = V12Config.NormalizeProfileName(rawName)
    if string.lower(name) == "default" then name = "Default" end
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {Names={"Default"}}
    if type(idx.Names) ~= "table" then idx.Names = {"Default"} end
    local found = false
    for _, existing in ipairs(idx.Names) do
        if string.lower(tostring(existing)) == string.lower(name) then
            name = tostring(existing)
            found = true
            break
        end
    end
    if not found then idx.Names[#idx.Names + 1] = name end
    table.sort(idx.Names, function(a, b)
        local aDefault = tostring(a) == "Default"
        local bDefault = tostring(b) == "Default"
        if aDefault ~= bDefault then return aDefault end
        return string.lower(tostring(a)) < string.lower(tostring(b))
    end)
    V12Config.LibraryIndex = idx
    return name
end

V12Config.ListNames = function()
    local names = {}
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {}
    for _, name in ipairs(type(idx.Names) == "table" and idx.Names or {"Default"}) do
        names[#names + 1] = tostring(name)
    end
    if #names == 0 then names = {"Default"} end
    return names
end

V12Config.SetActiveName = function(rawName, register)
    local name = V12Config.NormalizeProfileName(rawName)
    if register == true then name = V12Config.RegisterProfile(name) else name = V12Config.ResolveProfileName(name) end
    V12Config.ActiveName = name
    V12Config.Name = name
    V12Config.File = V12Config.ProfileFile(name)
    App.Values.ConfigLibrarySelected = name
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {Names={"Default"}}
    idx.ActiveName = name
    V12Config.LibraryIndex = idx
    return name
end

V12Config.ShouldAutoLoadActive = function()
    return V12Config.AutoLoadName ~= ""
        and string.lower(tostring(V12Config.AutoLoadName)) == string.lower(tostring(V12Config.ActiveName))
end

V12Config.InitializeLibrary = function()
    V12Config.EnsureLibraryFolders()
    local idx, existed = V12Config.ReadLibraryIndex()
    if type(idx) ~= "table" then idx = {Version=1, Names={"Default"}, ActiveName="Default", AutoLoadName=""} end
    if type(idx.Names) ~= "table" then idx.Names = {"Default"} end

    local normalized, seen = {}, {}
    local function addName(value)
        local name = V12Config.NormalizeProfileName(value)
        if string.lower(name) == "default" then name = "Default" end
        local key = string.lower(name)
        if not seen[key] then seen[key] = true; normalized[#normalized + 1] = name end
    end
    addName("Default")
    for _, name in ipairs(idx.Names) do addName(name) end
    idx.Names = normalized
    V12Config.LibraryIndex = idx

    if existed ~= true then
        local legacy = readV12Config()
        if type(legacy) == "table" and legacy.AutoLoad == true then idx.AutoLoadName = "Default" end
    end

    V12Config.AutoLoadName = tostring(idx.AutoLoadName or "")
    if V12Config.AutoLoadName ~= "" then V12Config.AutoLoadName = V12Config.ResolveProfileName(V12Config.AutoLoadName) end
    local requested = V12Config.AutoLoadName ~= "" and V12Config.AutoLoadName or tostring(idx.ActiveName or "Default")
    if not V12Config.ProfileKnown(requested) then requested = "Default" end
    V12Config.SetActiveName(requested, false)
    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    V12Config.WriteLibraryIndex()
end

V12Config.SetAutoLoadName = function(rawName)
    local name = V12Config.ResolveProfileName(rawName or V12Config.ActiveName)
    if not V12Config.ProfileKnown(name) then return false, "Select a saved config first" end
    V12Config.AutoLoadName = name
    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    V12Config.WriteLibraryIndex()
    if string.lower(name) == string.lower(tostring(V12Config.ActiveName)) then pcall(V12Config.SaveMetadataOnly) end
    V12Config.LastStatus = "Autoload • " .. tostring(name)
    return true, V12Config.LastStatus
end

V12Config.ClearAutoLoad = function()
    V12Config.AutoLoadName = ""
    App.Values.AutoLoadConfig = false
    V12Config.WriteLibraryIndex()
    pcall(V12Config.SaveMetadataOnly)
    V12Config.LastStatus = "Autoload off"
    return true, V12Config.LastStatus
end

V12Config.SaveNamed = function(rawName)
    local requested = tostring(rawName or "")
    if requested:gsub("%s", "") == "" then requested = tostring(App.Values.ConfigLibrarySelected or V12Config.ActiveName) end
    local name = V12Config.SetActiveName(requested, true)
    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    local ok, message = writeV12Config()
    if not ok then return false, message end
    V12Config.WriteLibraryIndex()
    App.Values.ConfigLibraryNewName = ""
    V12Config.LastStatus = "Saved config • " .. tostring(name)
    return true, V12Config.LastStatus
end

V12Config.LoadNamed = function(rawName)
    local name = V12Config.ResolveProfileName(rawName or App.Values.ConfigLibrarySelected or V12Config.ActiveName)
    if not V12Config.ProfileKnown(name) then return false, "Config not found" end
    local previousName = tostring(V12Config.ActiveName or "Default")
    V12Config.SetActiveName(name, false)
    local document, reason = readV12Config()
    if type(document) ~= "table" then
        V12Config.SetActiveName(previousName, false)
        return false, tostring(reason or "No saved config")
    end

    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    App.Values.AutoExecuteOnTeleport = document.AutoExecuteOnTeleport == true
    if type(document.Window) == "table" then
        V12Config.WindowWidth = math.clamp(math.floor((tonumber(document.Window.Width) or 920) + 0.5), 680, 1600)
        V12Config.WindowHeight = math.clamp(math.floor((tonumber(document.Window.Height) or 570) + 0.5), 430, 1000)
    end
    if type(document.WebhookPreset) == "table" then V12Config.WebhookPreset = document.WebhookPreset end
    local changed = V12Config.ApplyValuesTracked(document.Values)
    V12Config.ApplyExplicitAutoSlot(document)
    V12Config.SanitizeLoadedValues()
    local tierAdjusted = V12Config.EnforceShareTier()
    if tonumber(tierAdjusted) and tonumber(tierAdjusted) > 0 then pcall(writeV12Config) end
    V12Config.WriteLibraryIndex()
    if type(V12Config.OnScopeValuesApplied) == "function" then pcall(V12Config.OnScopeValuesApplied, changed) end
    if App.Webhook and type(App.Webhook.Save) == "function" then pcall(App.Webhook.Save) end
    V12Config.LastStatus = "Loaded config • " .. tostring(name)
    return true, V12Config.LastStatus
end

V12Config.DeleteNamed = function(rawName)
    local name = V12Config.ResolveProfileName(rawName or App.Values.ConfigLibrarySelected or "")
    if string.lower(name) == "default" then return false, "Default config is protected" end
    if not V12Config.ProfileKnown(name) then return false, "Config not found" end
    local _, _, _, _, deleteFile = v12FileFunctions()
    if type(deleteFile) == "function" then pcall(deleteFile, V12Config.ProfileFile(name)) end
    local idx = type(V12Config.LibraryIndex) == "table" and V12Config.LibraryIndex or {Names={"Default"}}
    local kept = {}
    for _, existing in ipairs(type(idx.Names) == "table" and idx.Names or {}) do
        if string.lower(tostring(existing)) ~= string.lower(name) then kept[#kept + 1] = existing end
    end
    idx.Names = kept
    V12Config.LibraryIndex = idx
    if string.lower(tostring(V12Config.AutoLoadName)) == string.lower(name) then V12Config.AutoLoadName = "" end
    local deletedActive = string.lower(tostring(V12Config.ActiveName)) == string.lower(name)
    if deletedActive then V12Config.SetActiveName("Default", false) end
    App.Values.ConfigLibrarySelected = V12Config.ActiveName
    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    V12Config.WriteLibraryIndex()
    if deletedActive then pcall(V12Config.LoadNamed, "Default") end
    V12Config.LastStatus = "Deleted config • " .. tostring(name)
    return true, V12Config.LastStatus
end

V12Config.UniqueImportName = function(rawName)
    local base = V12Config.NormalizeProfileName(rawName)
    if not V12Config.ProfileKnown(base) then return base end
    local stem = string.sub(base, 1, 26):gsub("%s+$", "")
    if stem == "" then stem = "Imported Config" end
    local root = V12Config.NormalizeProfileName(stem .. " Imported")
    if not V12Config.ProfileKnown(root) then return root end
    for i = 2, 99 do
        local candidate = V12Config.NormalizeProfileName(stem .. " Imported " .. tostring(i))
        if not V12Config.ProfileKnown(candidate) then return candidate end
    end
    return V12Config.NormalizeProfileName("Imported " .. tostring(os.time()))
end

V12Config.ExportFullShareCode = function()
    local okSave, saveMessage = V12Config.SaveNamed(V12Config.ActiveName)
    if not okSave then return false, saveMessage end
    local document, reason = readV12Config()
    if type(document) ~= "table" or type(document.Values) ~= "table" then return false, tostring(reason or "Save config first") end
    local okClone, cloned = pcall(function()
        return HttpService:JSONDecode(HttpService:JSONEncode(document))
    end)
    if not okClone or type(cloned) ~= "table" then return false, "Config export failed" end
    cloned.UserId = nil
    cloned.AutoLoad = false
    cloned.FlagsUpdatedAt = nil
    cloned.Name = V12Config.ActiveName
    local okEncode, raw = pcall(function()
        return HttpService:JSONEncode({v=2, schema=V12Config.SchemaVersion, name=V12Config.ActiveName, document=cloned})
    end)
    if not okEncode then return false, "Config export encode failed" end
    local code = "SHCFG2:" .. V12Config.ShareCodec.Encode(raw)
    App.Values.SharedConfigCode = code
    App.Values.ConfigShareStatus = "Full config ready • includes webhook settings/vault handles + private-server code"
    return true, code
end

V12Config.ImportFullShareCode = function(raw)
    raw = tostring(raw or App.Values.SharedConfigCode or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if #raw > 350000 then return false, "Config code is too large" end
    if string.sub(raw, 1, 7) == "SHCFG1:" then
        local okLegacy, message = V12Config.ImportShareCodeSession(raw)
        if not okLegacy then return false, message end
        local requested = tostring(App.Values.ConfigLibraryNewName or "")
        if requested:gsub("%s", "") == "" then requested = "Imported SHCFG1" end
        local name = V12Config.UniqueImportName(requested)
        local okSave, saveMessage = V12Config.SaveNamed(name)
        if not okSave then return false, saveMessage end
        App.Values.ConfigShareStatus = "Imported legacy config • " .. tostring(name)
        return true, App.Values.ConfigShareStatus
    end
    if string.sub(raw, 1, 7) ~= "SHCFG2:" then return false, "Paste a valid SHCFG2 config code" end
    local decoded = V12Config.ShareCodec.Decode(string.sub(raw, 8))
    if not decoded then return false, "Config code decode failed" end
    local okDecode, wrapper = pcall(function() return HttpService:JSONDecode(decoded) end)
    if not okDecode or type(wrapper) ~= "table" or tonumber(wrapper.v) ~= 2 or type(wrapper.document) ~= "table" then
        return false, "Unsupported config code"
    end
    local document = wrapper.document
    if type(document.Values) ~= "table" then return false, "Shared config has no settings" end
    local requested = tostring(App.Values.ConfigLibraryNewName or "")
    if requested:gsub("%s", "") == "" then requested = tostring(wrapper.name or document.Name or "Imported Config") end
    local name = V12Config.UniqueImportName(requested)
    name = V12Config.RegisterProfile(name)
    V12Config.SetActiveName(name, false)
    document.Version = V12Config.SchemaVersion
    document.Name = name
    document.UserId = player.UserId
    document.PerAccount = true
    document.AutoLoad = false
    document.GlobalSync = nil
    document.SavedAt = os.time()
    local _, writeFile = v12FileFunctions()
    if type(writeFile) ~= "function" then return false, "File storage unavailable" end
    V12Config.EnsureLibraryFolders()
    local okEncode, encoded = pcall(function() return HttpService:JSONEncode(document) end)
    if not okEncode then return false, "Imported config encode failed" end
    local okWrite, err = pcall(writeFile, V12Config.File, encoded)
    if not okWrite then return false, tostring(err) end
    V12Config.WriteLibraryIndex()
    App.Values.ConfigLibraryNewName = ""
    App.Values.SharedConfigCode = raw
    local okLoad, loadMessage = V12Config.LoadNamed(name)
    if not okLoad then return false, loadMessage end
    App.Values.ConfigShareStatus = "Imported full config • " .. tostring(name)
    return true, App.Values.ConfigShareStatus
end

V12Config.StatusText = function()
    if V12Config.GlobalEnabled == true
        or App.Values.GlobalConfigSync == true then
        return "GLOBAL • " .. tostring(V12Config.GlobalConfigName or V12Config.ActiveName or "Default") .. " • "
            .. tostring(V12Config.ResolveSourceUsername())
            .. " [" .. tostring(V12Config.GlobalSourceUserId or "?") .. "]"
    end
    local suffix = V12Config.ShouldAutoLoadActive() and " • AUTOLOAD" or ""
    return "PER-ACCOUNT • " .. tostring(V12Config.ActiveName or "Default") .. " • " .. tostring(player.Name) .. suffix
end

V12Config.GlobalSourceText = function()
    if V12Config.GlobalEnabled ~= true
        and App.Values.GlobalConfigSync ~= true then
        return "Off • each Roblox account uses its own named config"
    end
    return tostring(V12Config.ResolveSourceUsername())
        .. " [" .. tostring(V12Config.GlobalSourceUserId or "?") .. "]"
        .. " • " .. tostring(V12Config.GlobalConfigName or "Default")
end

V12Config.RestorePerAccount = function()
    local accountDocument = readV12Config()
    V12Config.GlobalEnabled = false
    App.Values.GlobalConfigSync = false

    if type(accountDocument) ~= "table" then
        V12Config.LastStatus = "Per-account mode • no saved config"
        return false, V12Config.LastStatus
    end

    App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
    App.Values.AutoExecuteOnTeleport = accountDocument.AutoExecuteOnTeleport == true

    if V12Config.ShouldAutoLoadActive() ~= true
        or type(accountDocument.Values) ~= "table" then
        V12Config.LastStatus = "Per-account mode • Auto Load off"
        return true, V12Config.LastStatus
    end

    local changed = V12Config.ApplyValuesTracked(accountDocument.Values)
    V12Config.ApplyExplicitAutoSlot(accountDocument)
    V12Config.SanitizeLoadedValues()
    V12Config.LastStatus = "Restored per-account • " .. tostring(player.Name)

    if type(V12Config.OnScopeValuesApplied) == "function" then
        pcall(V12Config.OnScopeValuesApplied, changed)
    end
    return true, V12Config.LastStatus
end

V12Config.ApplyGlobalDocument = function(document, live)
    if type(document) ~= "table"
        or document.Enabled ~= true
        or type(document.Values) ~= "table" then
        return false, "Global config unavailable"
    end

    V12Config.GlobalEnabled = true
    V12Config.GlobalSourceUserId = document.SourceUserId
    V12Config.GlobalSourceUsername = document.SourceUsername
    V12Config.GlobalConfigName = tostring(document.Name or "Default")
    V12Config.GlobalSavedAt = document.GlobalSavedAt
    V12Config.LastGlobalSeenAt = document.GlobalSavedAt
    App.Values.GlobalConfigSync = true

    local changed
    if live == true then
        changed = V12Config.ApplyValuesTracked(document.Values)
    else
        V12Config.ApplyValues(document.Values)
        changed = {}
    end
    V12Config.SanitizeLoadedValues()
    V12Config.LastStatus =
        "Loaded GLOBAL • " .. tostring(V12Config.ResolveSourceUsername())

    if live == true
        and type(V12Config.OnScopeValuesApplied) == "function" then
        pcall(V12Config.OnScopeValuesApplied, changed)
    end
    return true, V12Config.LastStatus
end

V12Config.GlobalWatchStep = function()
    if V12Config.KaitunWorkspaceBypass == true then return end

    local document = V12Config.ReadGlobal()
    local enabled = type(document) == "table"
        and document.Enabled == true
        and type(document.Values) == "table"

    if enabled then
        local stamp = tonumber(document.GlobalSavedAt) or 0
        local sourceId = tonumber(document.SourceUserId) or 0
        if V12Config.GlobalEnabled ~= true
            or tonumber(V12Config.LastGlobalSeenAt) ~= stamp
            or tonumber(V12Config.GlobalSourceUserId) ~= sourceId then
            V12Config.ApplyGlobalDocument(document, true)
        end
        return
    end

    if V12Config.GlobalEnabled == true
        or App.Values.GlobalConfigSync == true then
        V12Config.LastGlobalSeenAt = type(document) == "table"
            and document.GlobalSavedAt or nil
        V12Config.RestorePerAccount()
    end
end

local function loadV12ConfigAtBoot()
    do
        local env=v12Environment()
        local requested=type(env)=="table" and type(env.SliceHubKaitun)=="table"
        local hub=type(env)=="table" and type(env.SliceHub)=="table" and env.SliceHub or {}
        local premium=hub.IsPremium==true
            or string.upper(tostring(hub.BuildTier or ""))=="PREMIUM"
            or (type(env)=="table" and string.upper(tostring(env.SliceHubExpectedTier or ""))=="PREMIUM")
        if requested and premium then
            V12Config.KaitunWorkspaceBypass=true
            V12Config.GlobalEnabled=false
            App.Values.AutoLoadConfig=false
            App.Values.GlobalConfigSync=false
            V12Config.LoadedAtBoot=false
            V12Config.BootSource="Kaitun"
            V12Config.LastStatus="Kaitun owns boot • config scope ignored"
            return false
        end
    end

    local accountDocument = readV12Config()
    local accountSchemaVersion = type(accountDocument) == "table" and tonumber(accountDocument.Version) or 0
    local hasExplicitAutoSlot = type(accountDocument) == "table" and type(accountDocument.AutoSlot) == "table"
    V12Config.LegacyConfigLoaded = type(accountDocument) == "table" and accountSchemaVersion < V12Config.SchemaVersion

    if type(accountDocument) == "table" then
        if type(accountDocument.WebhookPreset) == "table" then
            V12Config.WebhookPreset = accountDocument.WebhookPreset
        end
        App.Values.AutoLoadConfig = V12Config.ShouldAutoLoadActive()
        App.Values.AutoExecuteOnTeleport = accountDocument.AutoExecuteOnTeleport == true
        if type(accountDocument.Window) == "table" then
            V12Config.WindowWidth = math.clamp(math.floor((tonumber(accountDocument.Window.Width) or 920) + 0.5), 680, 1600)
            V12Config.WindowHeight = math.clamp(math.floor((tonumber(accountDocument.Window.Height) or 570) + 0.5), 430, 1000)
        end
    end

    local globalDocument = V12Config.ReadGlobal()
    if type(globalDocument) == "table"
        and globalDocument.Enabled == true
        and type(globalDocument.Values) == "table" then
        V12Config.ApplyGlobalDocument(globalDocument, false)
        V12Config.LoadedAtBoot = true
        V12Config.BootSource = "Global"
        return true
    end

    V12Config.GlobalEnabled = false
    App.Values.GlobalConfigSync = false

    if type(accountDocument) ~= "table" then
        V12Config.LastStatus = "No saved per-account config"
        return false
    end

    if hasExplicitAutoSlot then
        V12Config.ApplyExplicitAutoSlot(accountDocument)
    end

    if V12Config.ShouldAutoLoadActive() ~= true
        or type(accountDocument.Values) ~= "table" then
        V12Config.SanitizeLoadedValues()
        V12Config.LastStatus = "Per-account Auto Load off"
        return false
    end

    V12Config.ApplyValues(accountDocument.Values)
    if hasExplicitAutoSlot then
        V12Config.ApplyExplicitAutoSlot(accountDocument)
    end
    V12Config.SanitizeLoadedValues()

    V12Config.LoadedAtBoot = true
    V12Config.BootSource = "PerAccount"
    V12Config.LastStatus = "Loaded all settings • " .. tostring(player.Name)
    return true
end

V12Config.InitializeLibrary()
loadV12ConfigAtBoot()
V12Config.ApplyKaitun()


