App.RunState.Save = function()
    local _, write, make = App.RunState.FileFunctions()
    if type(write) ~= "function" then return false end

    if type(make) == "function" then
        pcall(make, "SH")
        pcall(make, "SH/state")
    end

    local data = App.RunState.Data or App.RunState.Default()
    data.UserId = player.UserId
    data.UpdatedAt = os.time()

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(data)
    end)

    return okEncode and pcall(write, App.RunState.File, encoded) == true
end

App.RunState.Load = function()
    local read = App.RunState.FileFunctions()
    local data = nil

    if type(read) == "function" then
        local okRead, raw = pcall(read, App.RunState.File)
        if okRead and type(raw) == "string" and raw ~= "" then
            local okDecode, decoded = pcall(function()
                return HttpService:JSONDecode(raw)
            end)
            if okDecode
                and type(decoded) == "table"
                and tonumber(decoded.UserId) == tonumber(player.UserId) then
                data = decoded
            end
        end
    end

    data = type(data) == "table" and data or App.RunState.Default()
    data.Count = math.max(0, math.floor((tonumber(data.Count) or 0) + 0.5))
    data.RunId = math.max(0, math.floor((tonumber(data.RunId) or 0) + 0.5))
    data.LastCountedRunId = math.max(0, math.floor((tonumber(data.LastCountedRunId) or 0) + 0.5))
    data.RunJobId = tostring(data.RunJobId or "")
    data.RunStartedUnix = tonumber(data.RunStartedUnix) or 0
    data.RunOpen = data.RunOpen == true
    data.Completed = math.max(0, math.floor((tonumber(data.Completed) or 0) + 0.5))
    data.Failed = math.max(0, math.floor((tonumber(data.Failed) or 0) + 0.5))
    data.TotalCompletionSeconds = math.max(0, tonumber(data.TotalCompletionSeconds) or 0)
    data.TimedRuns = math.max(0, math.floor((tonumber(data.TimedRuns) or 0) + 0.5))
    data.SessionRewardGold = math.max(0, tonumber(data.SessionRewardGold) or 0)
    data.SessionRewardGems = math.max(0, tonumber(data.SessionRewardGems) or 0)
    data.SessionRewardXP = math.max(0, tonumber(data.SessionRewardXP) or 0)
    data.LastRewardCountedRunId = math.max(0, math.floor((tonumber(data.LastRewardCountedRunId) or 0) + 0.5))
    data.Hourly = type(data.Hourly) == "table" and data.Hourly or {}
    data.Hourly.PeriodStart = tonumber(data.Hourly.PeriodStart) or os.time()
    data.Hourly.BaseCompleted = math.max(0, tonumber(data.Hourly.BaseCompleted) or tonumber(data.Completed) or 0)
    data.Hourly.BaseFailed = math.max(0, tonumber(data.Hourly.BaseFailed) or tonumber(data.Failed) or 0)
    data.Hourly.BaseTimedRuns = math.max(0, tonumber(data.Hourly.BaseTimedRuns) or tonumber(data.TimedRuns) or 0)
    data.Hourly.BaseRunSeconds = math.max(0, tonumber(data.Hourly.BaseRunSeconds) or tonumber(data.TotalCompletionSeconds) or 0)
    data.Hourly.BaseGold = math.max(0, tonumber(data.Hourly.BaseGold) or tonumber(data.SessionRewardGold) or 0)
    data.Hourly.BaseGems = math.max(0, tonumber(data.Hourly.BaseGems) or tonumber(data.SessionRewardGems) or 0)
    data.Hourly.BaseXP = math.max(0, tonumber(data.Hourly.BaseXP) or tonumber(data.SessionRewardXP) or 0)
    data.Hourly.BaseRecoveries = math.max(0, tonumber(data.Hourly.BaseRecoveries) or tonumber(data.Recoveries) or 0)
    data.Hourly.Samples = type(data.Hourly.Samples) == "table" and data.Hourly.Samples or {}
    data.Hourly.Activity = type(data.Hourly.Activity) == "table" and data.Hourly.Activity or {}
    data.Hourly.Modes = type(data.Hourly.Modes) == "table" and data.Hourly.Modes or {}
    data.Hourly.Rarities = type(data.Hourly.Rarities) == "table" and data.Hourly.Rarities or {Mythic=0,Legendary=0,Epic=0}
    data.Hourly.Kills = math.max(0, tonumber(data.Hourly.Kills) or 0)
    data.Hourly.BestStreak = math.max(0, tonumber(data.Hourly.BestStreak) or 0)
    data.Hourly.BestDropRank = math.max(0, tonumber(data.Hourly.BestDropRank) or 0)
    data.Hourly.Reconnects = math.max(0, tonumber(data.Hourly.Reconnects) or 0)
    data.Hourly.Failsafes = math.max(0, tonumber(data.Hourly.Failsafes) or 0)
    data.Hourly.LastAttemptAt = tonumber(data.Hourly.LastAttemptAt) or 0
    data.Recoveries = math.max(0, math.floor((tonumber(data.Recoveries) or 0) + 0.5))
    data.SessionStartedUnix = tonumber(data.SessionStartedUnix) or 0
    if data.SessionStartedUnix <= 0 then data.SessionStartedUnix = os.time() end
    data.LastAttention = tostring(data.LastAttention or "None")
    data.LastAttentionAt = tonumber(data.LastAttentionAt) or 0
    data.PendingResetOnLobby = data.PendingResetOnLobby == true
    App.RunState.Data = data

    if RuntimeKind == "Lobby" and data.PendingResetOnLobby then
        data.Count = 0
        data.Completed = 0
        data.Failed = 0
        data.TotalCompletionSeconds = 0
        data.TimedRuns = 0
        data.SessionRewardGold = 0
        data.SessionRewardGems = 0
        data.SessionRewardXP = 0
        data.LastRewardCountedRunId = 0
        data.Recoveries = 0
        data.Hourly = {
            PeriodStart = os.time(),
            BaseCompleted = 0,
            BaseFailed = 0,
            BaseTimedRuns = 0,
            BaseRunSeconds = 0,
            BaseGold = 0,
            BaseGems = 0,
            BaseXP = 0,
            BaseRecoveries = 0,
            Samples = {},
            Activity = {},
            Modes = {},
            Rarities = {Mythic=0, Legendary=0, Epic=0},
            BestDrop = nil,
            BestDropRank = 0,
            Kills = 0,
            BestStreak = 0,
            BestRunSeconds = nil,
            Reconnects = 0,
            Failsafes = 0,
            LastAttemptAt = 0,
        }
        data.SessionStartedUnix = os.time()
        data.LastAttention = "None"
        data.LastAttentionAt = 0
        data.PendingResetOnLobby = false
        data.RunOpen = false
        data.RunJobId = ""
        data.RunStartedUnix = 0
        App.RunState.Save()
    end

    App.Values.MissionRunCount = data.Count
    return data
end

App.RunState.BeginRun = function(force)
    local data = App.RunState.Data or App.RunState.Load()
    local jobId = tostring(game.JobId or "")

    if force == true
        or data.RunOpen ~= true
        or data.RunJobId ~= jobId then
        data.RunId = (tonumber(data.RunId) or 0) + 1
        data.RunOpen = true
        data.RunJobId = jobId
        data.RunStartedUnix = os.time()
        data.LastCompletionSeconds = nil
        App.RunState.Save()
    end

    return data.RunId
end

App.RunState.FormatDuration = function(seconds)
    seconds = math.max(0, math.floor((tonumber(seconds) or 0) + 0.5))
    if seconds < 60 then
        return tostring(seconds) .. "s"
    end
    return string.format("%dm %02ds", math.floor(seconds / 60), seconds % 60)
end

App.RunState.CountResult = function(resultState)
    local data = App.RunState.Data or App.RunState.Load()
    local currentJobId = tostring(game.JobId or "")
    local existingRunId = tonumber(data.RunId) or 0


    if data.RunOpen ~= true
        and existingRunId > 0
        and tonumber(data.LastCountedRunId) == existingRunId
        and tostring(data.RunJobId or "") == currentJobId then

        App.Values.MissionRunCount =
            math.max(0, math.floor((tonumber(data.Count) or 0) + 0.5))

        return
            App.Values.MissionRunCount,
            tonumber(data.LastCompletionSeconds),
            true
    end

    if data.RunOpen ~= true then
        App.RunState.BeginRun(true)
        data = App.RunState.Data
    end

    local runId = tonumber(data.RunId) or 0
    local duplicate = runId > 0 and tonumber(data.LastCountedRunId) == runId

    local elapsed = nil
    if tonumber(data.RunStartedUnix) and tonumber(data.RunStartedUnix) > 0 then
        elapsed = math.max(0, os.time() - tonumber(data.RunStartedUnix))
    end

    if not duplicate then
        data.Count = math.max(0, (tonumber(data.Count) or 0) + 1)
        data.LastCountedRunId = runId
        data.LastResult = tostring(resultState or "Result")
        local resultText = string.lower(tostring(resultState or ""))
        if string.find(resultText, "complete", 1, true) or string.find(resultText, "success", 1, true) then
            data.Completed = math.max(0, (tonumber(data.Completed) or 0) + 1)
        elseif string.find(resultText, "fail", 1, true) or string.find(resultText, "defeat", 1, true) then
            data.Failed = math.max(0, (tonumber(data.Failed) or 0) + 1)
        end
        data.LastCompletionSeconds = elapsed
        if tonumber(elapsed) ~= nil then
            data.TotalCompletionSeconds = math.max(0, (tonumber(data.TotalCompletionSeconds) or 0) + elapsed)
            data.TimedRuns = math.max(0, (tonumber(data.TimedRuns) or 0) + 1)
        end
        data.RunOpen = false
        App.RunState.Save()
    end

    App.Values.MissionRunCount = math.max(0, math.floor((tonumber(data.Count) or 0) + 0.5))
    return App.Values.MissionRunCount, elapsed or data.LastCompletionSeconds, duplicate
end

App.RunState.MarkResetAfterLobby = function()
    local data = App.RunState.Data or App.RunState.Load()
    data.PendingResetOnLobby = true
    App.RunState.Save()
end

App.RunState.Load()

