App.SliceTrack.Environment = function()
    local env = type(getgenv) == "function" and getgenv() or _G
    return type(env) == "table" and env or _G
end

App.SliceTrack.IsPremium = function()
    local env = App.SliceTrack.Environment()
    local sliceHub = type(env.SliceHub) == "table" and env.SliceHub or {}
    return sliceHub.IsPremium == true
        or string.upper(tostring(sliceHub.BuildTier or "")) == "PREMIUM"
        or string.upper(tostring(env.SliceHubExpectedTier or "")) == "PREMIUM"
end

App.SliceTrack.ResolveDeviceId = function()
    return ""
end

App.SliceTrack.Endpoint = function()
    local env = App.SliceTrack.Environment()
    local config = type(env.SliceHubKeyGateConfig) == "table"
        and env.SliceHubKeyGateConfig
        or {}
    local raw = tostring(
        env.SLICEHUB_KEY_API_URL
        or env.SliceHubKeyApiUrl
        or config.ApiUrl
        or ""
    )

    raw = raw:match("^[^,;\\r\\n]+") or raw
    raw = raw:gsub("%s+$", "")
    raw = raw:gsub("[?#].*$", "")
    raw = raw:gsub("/+$", "")

    local startAt = string.find(raw, "/api/validate", 1, true)
    if startAt then
        return string.sub(raw, 1, startAt - 1) .. "/api/slice-track/heartbeat"
    end

    return ""
end

App.SliceTrack.RequestFunctions = function()
    local env = App.SliceTrack.Environment()
    local list, seen = {}, {}

    local function add(candidate)
        if type(candidate) ~= "function" or seen[candidate] then return end
        seen[candidate] = true
        list[#list + 1] = candidate
    end

    add(env.request)
    add(env.http_request)
    add(env.httprequest)
    add(type(syn) == "table" and syn.request or nil)
    add(type(http) == "table" and http.request or nil)
    add(type(fluxus) == "table" and fluxus.request or nil)

    return list
end

App.SliceTrack.ResolveSlot = function(profile)
    if type(profile) ~= "table" then return nil end

    if App.Prestige and type(App.Prestige.ResolveSlot) == "function" then
        local ok, _, resolved = pcall(App.Prestige.ResolveSlot, profile)
        if ok and type(resolved) == "table" then
            return resolved
        end
    end

    local slotKey = profile.Current_Slot or player:GetAttribute("Slot")
    local slots = type(profile.Slots) == "table" and profile.Slots or nil
    local slot = slots and (
        slots[slotKey]
        or slots[tostring(slotKey)]
        or slots[tonumber(slotKey)]
    ) or nil

    return type(slot) == "table" and slot or nil
end

App.SliceTrack.FetchProfile = function()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")
    if not (remote and remote:IsA("RemoteFunction")) then
        return nil, nil
    end

    local ok, profile = pcall(function()
        return remote:InvokeServer("Data", "Copy")
    end)
    if ok and type(profile) == "table" then
        local slot = App.SliceTrack.ResolveSlot(profile)
        if slot then return profile, slot end
    end

    ok, profile = pcall(function()
        return remote:InvokeServer("Functions", "Data")
    end)
    if ok and type(profile) == "table" then
        local slot = App.SliceTrack.ResolveSlot(profile)
        if slot then return profile, slot end
    end

    ok, profile = pcall(function()
        return remote:InvokeServer("Functions", "Settings", "Get")
    end)
    if ok and type(profile) == "table" then
        local slot = App.SliceTrack.ResolveSlot(profile)
        if slot then return profile, slot end
    end

    return nil, nil
end

App.SliceTrack.Inventory = function(slot)
    local inventory = type(slot) == "table" and slot.Inventory or nil
    local items = type(inventory) == "table" and inventory.Items or nil
    if type(items) ~= "table" then return {} end

    local out = {}
    local used = 0
    for name, rawQty in pairs(items) do
        if used >= 1200 then break end
        local qty = tonumber(rawQty)
        if qty and qty > 0 then
            out[tostring(name)] = math.max(0, math.floor(qty + 0.5))
            used += 1
        end
    end
    return out
end


