App.SliceTrack.CategoryFor = function(name, sourceCategory, sourceType)
    local raw = tostring(name or "")
    local n = string.lower(raw)
    local source = string.lower(tostring(sourceCategory or ""))
    local typeName = string.lower(tostring(sourceType or ""))

    local titanSkins = {
        ["onikiri"] = true, ["forsaken"] = true, ["krampus"] = true,
        ["jötunn"] = true, ["jotunn"] = true, ["moai"] = true,
        ["grumpy"] = true, ["deus ex machina"] = true,
        ["equinox moon"] = true, ["cinder lord"] = true,
    }
    if titanSkins[n] then return "TITAN_SKINS" end

    local raidSet = string.find(n, "onikiri", 1, true)
        or string.find(n, "jotunn", 1, true)
        or string.find(n, "jötunn", 1, true)
        or string.find(n, "deus", 1, true)
    local raidGear = string.find(n, "gear", 1, true)
        or string.find(n, "spear", 1, true)
        or string.find(n, "equipment", 1, true)
        or string.find(n, "blade", 1, true)
        or string.find(n, "sheath", 1, true)
    if n == "emperor's key" or (raidSet and raidGear) then return "RAID_DROPS" end

    if string.find(n, "serum", 1, true) then return "SERUMS" end
    if string.find(n, "shard", 1, true) then return "SHARDS" end
    if typeName == "boosts" or string.find(n, "boost", 1, true) then return "BOOSTS" end
    if typeName == "crates" or string.find(n, "crate", 1, true)
        or string.find(n, "fashion", 1, true)
        or string.find(n, "all%-stars")
        or string.find(n, "blade burst", 1, true) then return "CRATES" end
    if source == "cosmetics" or typeName == "cosmetics" then return "COSMETICS" end
    return "OTHER"
end

App.SliceTrack.InventoryMeta = function()
    local pg = player and player:FindFirstChildOfClass("PlayerGui") or nil
    local interface = pg and pg:FindFirstChild("Interface") or nil
    local inventoryGui = interface and interface:FindFirstChild("Inventory") or nil
    local main = inventoryGui and inventoryGui:FindFirstChild("Main") or nil
    local holder = main and main:FindFirstChild("Holder") or nil
    local items = holder and holder:FindFirstChild("Items") or nil
    if not items then return {} end

    local out, used = {}, 0
    for _, card in ipairs(items:GetChildren()) do
        if used >= 1200 then break end
        if card:IsA("GuiObject") then
            local inner = card:FindFirstChild("Main")
            local itemName = inner and inner:GetAttribute("Item") or nil
            if type(itemName) ~= "string" or itemName == "" then
                itemName = tostring(card.Name or ""):gsub("^%d+%s*%-%s*", "")
            end
            if itemName ~= "" then
                local sourceCategory = inner and inner:GetAttribute("Category") or nil
                local sourceType = card:GetAttribute("Type")
                local rarity = inner and inner:GetAttribute("Rarity") or nil
                local image = ""
                local quantity = nil
                local innerFrame = inner and inner:FindFirstChild("Inner") or nil
                local qtyLabel = innerFrame and innerFrame:FindFirstChild("Quantity") or nil
                if qtyLabel and qtyLabel:IsA("TextLabel") then quantity = tonumber(tostring(qtyLabel.Text or ""):gsub("[^%d%.%-]", "")) end
                for _, desc in ipairs(card:GetDescendants()) do
                    if desc:IsA("ImageLabel") and tostring(desc.Image or "") ~= "" then
                        image = tostring(desc.Image)
                        break
                    end
                end
                out[itemName] = {
                    rarity = tostring(rarity or ""),
                    sourceCategory = tostring(sourceCategory or ""),
                    sourceType = tostring(sourceType or ""),
                    trackCategory = App.SliceTrack.CategoryFor(itemName, sourceCategory, sourceType),
                    image = image,
                    quantity = quantity and math.max(0, math.floor(quantity + 0.5)) or nil,
                }
                used += 1
            end
        end
    end
    return out
end

App.SliceTrack.PerkNameFromInfo = function(info)
    if type(info) == "string" and info ~= "" then return info end
    if type(info) ~= "table" then return "Unknown" end
    for _, key in ipairs({"Name","name","Perk","perk","PerkName","perkName","ItemName","itemName","DisplayName","displayName","Title","title"}) do
        local value = rawget(info, key)
        if type(value) == "string" and value ~= "" then return value end
    end
    return "Unknown"
end

App.SliceTrack.PerkReadNumber = function(node, keys, depth, seen)
    if type(node) ~= "table" or (tonumber(depth) or 0) > 5 then return nil end
    seen = seen or {}
    if seen[node] then return nil end
    seen[node] = true
    for _, key in ipairs(keys) do
        local value = rawget(node, key)
        if tonumber(value) ~= nil then return tonumber(value) end
    end
    for _, value in pairs(node) do
        if type(value) == "table" then
            local found = App.SliceTrack.PerkReadNumber(value, keys, (tonumber(depth) or 0) + 1, seen)
            if found ~= nil then return found end
        end
    end
    return nil
end

App.SliceTrack.Perks = function(slot)
    local perks = type(slot) == "table" and slot.Perks or nil
    local storage = type(perks) == "table" and perks.Storage or nil
    if type(storage) ~= "table" then
        return {complete = false, totalCopies = 0, mythicCopies = 0, items = {}}
    end

    local equipped = {}
    local function collectEquipped(node, depth)
        if type(node) ~= "table" or depth > 7 then return end
        for key, value in pairs(node) do
            if type(value) == "string" and #value >= 32 and string.find(value, "-", 1, true) then
                equipped[value] = tostring(key)
            elseif type(value) == "table" then
                collectEquipped(value, depth + 1)
            end
        end
    end
    if type(perks.Equipped) == "table" then collectEquipped(perks.Equipped, 0) end

    local result = {complete = true, totalCopies = 0, mythicCopies = 0, items = {}}
    local used = 0
    for rawId, info in pairs(storage) do
        if used >= 2000 then break end
        local id = tostring(rawId or "")
        local name = App.SliceTrack.PerkNameFromInfo(info)
        if name ~= "Unknown" then
            local rarity = tostring(App.SliceTrack.PerkRarityByName[name] or "Unknown")
            local slotName = tostring(App.SliceTrack.PerkSlotByName[name] or "Unknown")
            local level = App.SliceTrack.PerkReadNumber(info, {"Level","level","LVL","Lvl","lvl","EnhanceLevel","enhanceLevel","Enhancement","enhancement","UpgradeLevel","upgradeLevel"}, 0, {})
            if level ~= nil and (level < 0 or level > 10) then level = nil end
            local row = result.items[name]
            if type(row) ~= "table" then
                row = {quantity = 0, rarity = rarity, slot = slotName, equipped = 0, maxLevel = 0}
                result.items[name] = row
            end
            row.quantity += 1
            if equipped[id] ~= nil then row.equipped += 1 end
            if level ~= nil then row.maxLevel = math.max(tonumber(row.maxLevel) or 0, math.floor(level + 0.5)) end
            result.totalCopies += 1
            if rarity == "Mythic" then result.mythicCopies += 1 end
            used += 1
        end
    end
    result.complete = result.totalCopies > 0 or next(storage) == nil
    return result
end



App.SliceTrack.ArtifactSlotByName = {
    ["Attack Scars"] = "Face",
    ["Colossal Scars"] = "Face",
    ["Female Scars"] = "Face",
    ["Scorched Cloak"] = "Back",
    ["Cloak"] = "Back",
    ["Hoodie"] = "Back",
    ["Warrior's Armband"] = "Back",
    ["Crystal Necklace"] = "Neck",
    ["Scarf"] = "Neck",
    ["Handkerchief"] = "Neck",
    ["Key"] = "Neck",
}

App.SliceTrack.ArtifactNormalizeRarity = function(value)
    local raw = tostring(value or "")
    local map = {
        common = "Common", uncommon = "Uncommon", rare = "Rare",
        epic = "Epic", legendary = "Legendary", mythic = "Mythic",
        exclusive = "Exclusive",
    }
    return map[string.lower(raw)] or (raw ~= "" and raw or "Unknown")
end

App.SliceTrack.ArtifactNormalizeSlot = function(value)
    local raw = tostring(value or "")
    local map = {back="Back", face="Face", hat="Hat", neck="Neck"}
    return map[string.lower(raw)] or "Unknown"
end

App.SliceTrack.ArtifactNameFromInfo = function(info)
    if type(info) == "string" and info ~= "" then return info end
    if type(info) ~= "table" then return "Unknown" end
    for _, key in ipairs({"Real_Tag","Tag","Name","name","Artifact","artifact","ArtifactName","artifactName","Item","item","ItemName","itemName","DisplayName","displayName","Title","title"}) do
        local value = rawget(info, key)
        if type(value) == "string" and value ~= "" then return value end
    end
    return "Unknown"
end

App.SliceTrack.ArtifactStorage = function(slot)
    if type(slot) ~= "table" then return nil, nil end
    local artifacts = rawget(slot, "Artifacts") or rawget(slot, "Artifact")
    if type(artifacts) ~= "table" then
        local equipment = rawget(slot, "Equipment")
        if type(equipment) == "table" then
            artifacts = rawget(equipment, "Artifacts") or rawget(equipment, "Artifact")
        end
    end
    if type(artifacts) ~= "table" then return nil, nil end

    local storage = rawget(artifacts, "Storage")
        or rawget(artifacts, "Items")
        or rawget(artifacts, "Inventory")
        or rawget(artifacts, "Owned")

    if type(storage) ~= "table" then
        local looksLikeStorage = false
        local checked = 0
        for key, info in pairs(artifacts) do
            checked += 1
            if checked > 50 then break end
            if type(info) == "table" then
                local name = App.SliceTrack.ArtifactNameFromInfo(info)
                local id = rawget(info, "ID") or rawget(info, "Id") or rawget(info, "id") or key
                if name ~= "Unknown" and tostring(id or ""):find("-", 1, true) then
                    looksLikeStorage = true
                    break
                end
            end
        end
        if looksLikeStorage then storage = artifacts end
    end
    return type(storage) == "table" and storage or nil, artifacts
end

App.SliceTrack.Artifacts = function(slot)
    local storage, artifacts = App.SliceTrack.ArtifactStorage(slot)
    if type(storage) ~= "table" then
        return {complete = false, totalCopies = 0, mythicCopies = 0, items = {}}
    end

    local equipped = {}
    local function collectEquipped(node, depth)
        if type(node) ~= "table" or depth > 8 then return end
        for key, value in pairs(node) do
            if type(value) == "string" and #value >= 32 and string.find(value, "-", 1, true) then
                equipped[value] = tostring(key)
            elseif type(value) == "table" then
                collectEquipped(value, depth + 1)
            end
        end
    end
    if type(artifacts) == "table" then
        for _, key in ipairs({"Equipped","Equipment","Loadout","Slots"}) do
            local node = rawget(artifacts, key)
            if type(node) == "table" then collectEquipped(node, 0) end
        end
    end

    local result = {complete = true, totalCopies = 0, mythicCopies = 0, items = {}}
    local used = 0
    for rawId, info in pairs(storage) do
        if used >= 2000 then break end
        if type(info) == "table" then
            local name = App.SliceTrack.ArtifactNameFromInfo(info)
            local id = tostring(rawget(info, "ID") or rawget(info, "Id") or rawget(info, "id") or rawId or "")
            local rarity = App.SliceTrack.ArtifactNormalizeRarity(
                rawget(info, "Rarity") or rawget(info, "rarity")
                or rawget(info, "Tier") or rawget(info, "tier")
                or rawget(info, "Grade") or rawget(info, "grade")
            )
            if name ~= "Unknown" and (id:find("-", 1, true) or rarity ~= "Unknown") then
                local slotName = "Unknown"
                for _, key in ipairs({"Slot","slot","Type","type","Category","category","ArtifactType","artifactType","Position","position"}) do
                    slotName = App.SliceTrack.ArtifactNormalizeSlot(rawget(info, key))
                    if slotName ~= "Unknown" then break end
                end
                if slotName == "Unknown" then slotName = tostring(App.SliceTrack.ArtifactSlotByName[name] or "Unknown") end
                local image = rawget(info, "Image") or rawget(info, "image") or rawget(info, "Icon") or rawget(info, "icon") or rawget(info, "ImageId") or rawget(info, "imageId") or ""
                image = tostring(image or "")
                if image:match("^%d+$") then image = "rbxassetid://" .. image end
                local row = result.items[name]
                if type(row) ~= "table" then
                    row = {quantity = 0, rarity = rarity, slot = slotName, equipped = 0, image = image}
                    result.items[name] = row
                end
                row.quantity += 1
                if row.rarity == "Unknown" and rarity ~= "Unknown" then row.rarity = rarity end
                if row.slot == "Unknown" and slotName ~= "Unknown" then row.slot = slotName end
                if (row.image == nil or row.image == "") and image ~= "" then row.image = image end
                if equipped[id] ~= nil or rawget(info, "Equipped") == true or rawget(info, "equipped") == true then row.equipped += 1 end
                result.totalCopies += 1
                if rarity == "Mythic" then result.mythicCopies += 1 end
                used += 1
            end
        end
    end
    result.complete = result.totalCopies > 0 or next(storage) == nil
    return result
end

App.SliceTrack.FarmSnapshot = function()
    local data = App.RunState and App.RunState.Data or nil
    local mode = type(data) == "table" and tostring(data.PendingMode or "") or ""
    if mode == "" then mode = tostring(App.Values.LobbyMode or RuntimeKind or "") end

    local map = tostring(App.Values.LobbyMap or "")
    if mode == "Waves" then
        map = "Trost"
    elseif mode == "Raid" and type(data) == "table" and tostring(data.PendingRaidChoice or "") ~= "" then
        map = tostring(data.PendingRaidChoice)
    end

    local runs = type(data) == "table" and tonumber(data.LastCountedRunId) or nil
    if runs == nil then runs = tonumber(App.Values.MissionRunCount) or 0 end

    return {
        mode = mode,
        map = map,
        runs = math.max(0, math.floor(runs + 0.5)),
    }
end

App.SliceTrack.BuildSnapshot = function()
    local _, slot = App.SliceTrack.FetchProfile()
    if type(slot) ~= "table" then return nil end

    local progression = type(slot.Progression) == "table" and slot.Progression or {}
    local currency = type(slot.Currency) == "table" and slot.Currency or {}

    return {
        username = tostring(player.Name or ""),
        displayName = tostring(player.DisplayName or player.Name or ""),
        progression = {
            prestige = tonumber(progression.Prestige) or 0,
            level = tonumber(progression.Level) or 0,
        },
        currencies = {
            gems = tonumber(currency.Gems or currency.Gem) or 0,
            gold = tonumber(currency.Gold) or 0,
        },
        farming = App.SliceTrack.FarmSnapshot(),
        inventory = App.SliceTrack.Inventory(slot),
        inventoryMeta = App.SliceTrack.InventoryMeta(),
        perks = App.SliceTrack.Perks(slot),
        artifacts = App.SliceTrack.Artifacts(slot),
    }
end

App.SliceTrack.Post = function(payload)
    local okEncode, body = pcall(function()
        return HttpService:JSONEncode(payload)
    end)
    if not okEncode then return false, "JSON encode failed" end

    local url = App.SliceTrack.Endpoint()
    for _, requestFn in ipairs(App.SliceTrack.RequestFunctions()) do
        local ok, response = pcall(requestFn, {
            Url = url,
            URL = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["Accept"] = "application/json",
            },
            Body = body,
        })

        if ok then
            if type(response) ~= "table" then return true end
            local status = tonumber(response.StatusCode or response.Status or response.status_code)
            local responseBody = response.Body or response.body or response.Response or response.response
            local decoded = nil
            if type(responseBody) == "string" and responseBody ~= "" then
                pcall(function() decoded = HttpService:JSONDecode(responseBody) end)
            end
            if type(decoded) == "table" and decoded.ok == false then
                return false, tostring(decoded.message or decoded.reason or decoded.code or "SliceTrack sync rejected"), status or 200
            end
            if response.Success == true or (status and status >= 200 and status < 300) then
                return true, nil, status or 200
            end
            if status and status >= 400 and status < 500 then
                local detail = type(decoded) == "table" and (decoded.message or decoded.reason or decoded.code) or nil
                return false, tostring(detail or ("HTTP " .. tostring(status))), status
            end
        end
    end

    local okPost = pcall(function()
        HttpService:PostAsync(url, body, Enum.HttpContentType.ApplicationJson, false)
    end)
    return okPost, okPost and nil or "No supported HTTP request method", okPost and 200 or nil
end

App.SliceTrack.Send = function(reason)
    App.SliceTrack.LastStatus = "Offline • telemetry disabled"
    return false, App.SliceTrack.LastStatus
end

App.SliceTrack.Trigger = function(delaySeconds)
    local generation = App.SliceTrack.Generation
    task.delay(math.max(0, tonumber(delaySeconds) or 0), function()
        local env = App.SliceTrack.Environment()
        if env.__SliceHubSliceTrackGeneration == generation then
            App.SliceTrack.Send("result")
        end
    end)
end

do
    local env = App.SliceTrack.Environment()
    env.__SliceHubSliceTrackGeneration = (tonumber(env.__SliceHubSliceTrackGeneration) or 0) + 1
    App.SliceTrack.Generation = env.__SliceHubSliceTrackGeneration
    local generation = App.SliceTrack.Generation

    task.spawn(function()
        task.wait(2.5)
        while env.__SliceHubSliceTrackGeneration == generation do
            App.SliceTrack.Send("heartbeat")
            task.wait(math.max(10, tonumber(App.SliceTrack.HeartbeatSeconds) or 20))
        end
    end)
end


App.Webhook = App.Webhook or {
    File = "SH/webhook.json",
    LastSentSerial = 0,
    LastCapture = nil,
    Busy = false,
}

App.Webhook.Environment = function()
    local env = type(getgenv) == "function" and getgenv() or _G
    return type(env) == "table" and env or _G
end

App.Webhook.FileFunctions = function()
    local env = App.Webhook.Environment()
    local read = env.readfile or (type(readfile) == "function" and readfile or nil)
    local write = env.writefile or (type(writefile) == "function" and writefile or nil)
    local make = env.makefolder or (type(makefolder) == "function" and makefolder or nil)
    return read, write, make
end

App.Webhook.Trim = function(value)
    local text = tostring(value or "")
    text = string.gsub(text, "[\r\n\t]", "")
    text = string.gsub(text, "^%s+", "")
    text = string.gsub(text, "%s+$", "")
    return text
end

App.Webhook.MaskURL = function(value)
    local url = App.Webhook.Trim(value)
    if url == "" then return "Not set" end
    local suffix = string.sub(url, math.max(1, #url - 5))
    return "••••••••••••" .. suffix
end

App.Webhook.ValidURL = function(value)
    local url = string.lower(App.Webhook.Trim(value))
    return string.find(url, "https://discord.com/api/webhooks/", 1, true) == 1
        or string.find(url, "https://discordapp.com/api/webhooks/", 1, true) == 1
end

App.Webhook.FormatNumber = function(value)
    local n = tonumber(value)
    if not n then return "0" end
    n = math.floor(n + 0.5)

    local sign = n < 0 and "-" or ""
    local text = tostring(math.abs(n))
    local result = text

    while true do
        local nextText, replaced =
            string.gsub(result, "^(%d+)(%d%d%d)", "%1,%2")
        result = nextText
        if replaced == 0 then break end
    end

    return sign .. result
end

App.Webhook.Save = function()
    local _, write, make = App.Webhook.FileFunctions()

    if type(write) ~= "function" then
        App.Values.WebhookStatus = "File storage unavailable"
        return false
    end

    if type(make) == "function" then
        pcall(make, "SH")
    end

    local document = {
        Version = 1,
        Enabled = App.Values.WebhookEnabled == true,
        URL = App.Webhook.Trim(App.Values.WebhookURL),
        SendCompleted = App.Values.WebhookSendCompleted ~= false,
        SendFailed = App.Values.WebhookSendFailed == true,
        IncludeStats = App.Values.WebhookStats ~= false,
        HighValue = App.Values.WebhookHighValue ~= false,
        ShowUsername = App.Values.WebhookShowUsername ~= false,
        HourlyEnabled = App.Values.WebhookHourlyEnabled == true,
        HourlyURL = App.Webhook.Trim(App.Values.WebhookHourlyURL),
        HourlyIntervalHours = math.clamp(math.floor((tonumber(App.Values.WebhookHourlyIntervalHours) or 1) + 0.5), 1, 12),
        HourlyShowGold = App.Values.WebhookHourlyShowGold ~= false,
        HourlyShowMissions = App.Values.WebhookHourlyShowMissions ~= false,
        HourlyShowActivity = App.Values.WebhookHourlyShowActivity ~= false,
        HourlyShowSummary = App.Values.WebhookHourlyShowSummary ~= false,
        HourlyShowModes = App.Values.WebhookHourlyShowModes ~= false,
        HourlyShowSession = App.Values.WebhookHourlyShowSession ~= false,
        HourlyShowDrops = App.Values.WebhookHourlyShowDrops ~= false,
        HourlyShowBestDrop = App.Values.WebhookHourlyShowBestDrop ~= false,
        HourlyShowStability = App.Values.WebhookHourlyShowStability ~= false,
        PingUserId = tostring(App.Values.WebhookPingUserId or ""),
        FamilyUserId = tostring(App.Values.FamilyWebhookUserId or ""),
        SavedAt = os.time(),
    }

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(document)
    end)

    if not okEncode then
        App.Values.WebhookStatus = "Webhook save encode failed"
        return false
    end

    local okWrite = pcall(write, App.Webhook.File, encoded)

    if not okWrite then
        App.Values.WebhookStatus = "Webhook save failed"
        return false
    end

    if App.Values.WebhookEnabled
        and not App.Webhook.ValidURL(App.Values.WebhookURL) then
        App.Values.WebhookStatus = "Enter a valid Discord webhook URL"
    elseif App.Values.WebhookEnabled then
        App.Values.WebhookStatus = "Ready"
    else
        App.Values.WebhookStatus = "Off"
    end

    return true
end

App.Webhook.Load = function()
    local read = select(1, App.Webhook.FileFunctions())

    if type(read) ~= "function" then
        App.Values.WebhookStatus = "File storage unavailable"
        return false
    end

    local okRead, raw = pcall(read, App.Webhook.File)
    if not okRead or type(raw) ~= "string" or raw == "" then
        App.Values.WebhookStatus = "Not configured"
        return false
    end

    local okDecode, document = pcall(function()
        return HttpService:JSONDecode(raw)
    end)

    if not okDecode or type(document) ~= "table" then
        App.Values.WebhookStatus = "Saved webhook config invalid"
        return false
    end

    App.Values.WebhookEnabled = document.Enabled == true
    App.Values.WebhookURL = tostring(document.URL or "")
    App.Values.WebhookSendCompleted = document.SendCompleted ~= false
    App.Values.WebhookSendFailed = document.SendFailed == true
    App.Values.WebhookStats = document.IncludeStats ~= false
    App.Values.WebhookHighValue = document.HighValue ~= false
    App.Values.WebhookShowUsername = document.ShowUsername ~= false
    App.Values.WebhookHourlyEnabled = document.HourlyEnabled == true
    App.Values.WebhookHourlyURL = tostring(document.HourlyURL or "")
    App.Values.WebhookHourlyIntervalHours = math.clamp(math.floor((tonumber(document.HourlyIntervalHours) or 1) + 0.5), 1, 12)
    App.Values.WebhookHourlyShowGold = document.HourlyShowGold ~= false
    App.Values.WebhookHourlyShowMissions = document.HourlyShowMissions ~= false
    App.Values.WebhookHourlyShowActivity = document.HourlyShowActivity ~= false
    App.Values.WebhookHourlyShowSummary = document.HourlyShowSummary ~= false
    App.Values.WebhookHourlyShowModes = document.HourlyShowModes ~= false
    App.Values.WebhookHourlyShowSession = document.HourlyShowSession ~= false
    App.Values.WebhookHourlyShowDrops = document.HourlyShowDrops ~= false
    App.Values.WebhookHourlyShowBestDrop = document.HourlyShowBestDrop ~= false
    App.Values.WebhookHourlyShowStability = document.HourlyShowStability ~= false
    App.Values.WebhookPingUserId =
        tostring(document.PingUserId or App.Values.WebhookPingUserId or "")
    App.Values.FamilyWebhookUserId =
        tostring(document.FamilyUserId or App.Values.FamilyWebhookUserId or "")

    if App.Values.WebhookEnabled
        and App.Webhook.ValidURL(App.Values.WebhookURL) then
        App.Values.WebhookStatus = "Ready"
    elseif App.Values.WebhookEnabled then
        App.Values.WebhookStatus = "Webhook URL invalid"
    else
        App.Values.WebhookStatus = "Off"
    end

    return true
end

App.Webhook.RequestFunctions = function()
    local env = App.Webhook.Environment()
    local list = {}
    local seen = {}

    local function add(name, candidate)
        if type(candidate) ~= "function"
            or seen[candidate] then
            return
        end

        seen[candidate] = true
        list[#list + 1] = {
            Name = tostring(name),
            Fn = candidate,
        }
    end

    add("request", env.request)
    add("http_request", env.http_request)
    add("httprequest", env.httprequest)
    add(
        "syn.request",
        type(syn) == "table"
            and syn.request
            or nil
    )
    add(
        "http.request",
        type(http) == "table"
            and http.request
            or nil
    )
    add(
        "fluxus.request",
        type(fluxus) == "table"
            and fluxus.request
            or nil
    )

    return list
end

-- Compatibility for older internal callers.
App.Webhook.RequestFunction = function()
    local first = App.Webhook.RequestFunctions()[1]
    return first and first.Fn or nil
end

App.Webhook.Post = function(payload)
    local url = App.Webhook.Trim(App.Values.WebhookURL)

    if not App.Webhook.ValidURL(url) then
        return false, "Invalid Discord webhook URL"
    end

    local okEncode, body = pcall(function()
        return HttpService:JSONEncode(payload)
    end)

    if not okEncode then
        return false, "Webhook JSON encode failed"
    end

    local failures = {}

    for _, candidate in ipairs(App.Webhook.RequestFunctions()) do
        local ok, response = pcall(candidate.Fn, {
            Url = url,
            URL = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
            },
            Body = body,
        })

        if ok then
            if type(response) ~= "table" then
                -- Some executors return nil/string on a successful request.
                return true, "Sent • " .. candidate.Name
            end

            local status = tonumber(
                response.StatusCode
                or response.Status
                or response.status_code
            )

            if response.Success == true
                or (
                    status
                    and status >= 200
                    and status < 300
                ) then
                return true,
                    "Sent • "
                    .. candidate.Name
                    .. (
                        status
                        and (" • HTTP " .. tostring(status))
                        or ""
                    )
            end

            failures[#failures + 1] =
                candidate.Name
                .. " HTTP "
                .. tostring(status or "unknown")
        else
            failures[#failures + 1] =
                candidate.Name .. " failed"
        end
    end

    -- Last-resort fallback for environments that allow PostAsync directly.
    local okPost = pcall(function()
        HttpService:PostAsync(
            url,
            body,
            Enum.HttpContentType.ApplicationJson,
            false
        )
    end)

    if okPost then
        return true, "Sent • HttpService"
    end

    if #failures > 0 then
        return false, table.concat(failures, " | ")
    end

    return false, "No supported HTTP request method"
end


-- WEBHOOK VAULT R1
-- Raw Discord webhook URLs are accepted only long enough to enroll them with
-- SliceBot. Workspace/config files persist only the opaque WH7 handle.
App.Webhook.VaultBase = ""

App.Webhook.IsVaultHandle = function(value)
    return string.match(App.Webhook.Trim(value), "^WH7_[%w_-]+$") ~= nil
end

App.Webhook.IsDiscordURL = function(value)
    local url = string.lower(App.Webhook.Trim(value))
    return string.find(url, "https://discord.com/api/webhooks/", 1, true) == 1
        or string.find(url, "https://discordapp.com/api/webhooks/", 1, true) == 1
        or string.find(url, "https://canary.discord.com/api/webhooks/", 1, true) == 1
        or string.find(url, "https://ptb.discord.com/api/webhooks/", 1, true) == 1
end

App.Webhook.ValidURL = function(value)
    return App.Webhook.IsDiscordURL(value)
end

App.Webhook.DeviceId = function()
    return ""
end

App.Webhook.VaultCredential = function()
    local read = select(1, App.Webhook.FileFunctions())
    if type(read) == "function" then
        local okRead, raw = pcall(read, "SH/auth_r7.json")
        if okRead and type(raw) == "string" and raw ~= "" then
            local okDecode, document = pcall(HttpService.JSONDecode, HttpService, raw)
            if okDecode and type(document) == "table" then
                local grant = tostring(document.grant or "")
                if string.match(grant, "^AG7_[%w_-]+$") then return grant end
            end
        end
    end

    local env = App.Webhook.Environment()
    local grant = tostring(env and env.SCRIPT_KEY or "")
    if string.match(grant, "^AG7_[%w_-]+$") then return grant end
    return ""
end

App.Webhook.VaultRequest = function(action, extra)
    local grant = App.Webhook.VaultCredential()
    if grant == "" then return false, nil, "Webhook vault authorization unavailable" end

    local requestBody = type(extra) == "table" and extra or {}
    requestBody.grant = grant
    requestBody.userId = tostring(player.UserId)
    requestBody.deviceId = App.Webhook.DeviceId()

    local okEncode, body = pcall(HttpService.JSONEncode, HttpService, requestBody)
    if not okEncode then return false, nil, "Webhook vault encode failed" end

    local endpoint = App.Webhook.VaultBase .. "/" .. tostring(action or "")
    local failures = {}
    for _, candidate in ipairs(App.Webhook.RequestFunctions()) do
        local requestData = {
            Url = endpoint,
            URL = endpoint,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["Accept"] = "application/json, text/plain",
            },
            Body = body,
        }
        local ok, response = pcall(candidate.Fn, requestData)
        if not ok then
            requestData = {
                url = endpoint,
                method = "POST",
                headers = requestData.Headers,
                body = body,
            }
            ok, response = pcall(candidate.Fn, requestData)
        end

        if ok then
            local status = type(response) == "table"
                and tonumber(response.StatusCode or response.Status or response.status_code or response.status)
                or nil
            local responseBody = type(response) == "table"
                and (response.Body or response.body or response.Response or response.response or response.Data or response.data)
                or response

            if status == nil or (status >= 200 and status < 300) then
                if type(responseBody) == "string" and responseBody ~= "" then
                    local okDecode, document = pcall(HttpService.JSONDecode, HttpService, responseBody)
                    if okDecode and type(document) == "table" then
                        return true, document, "Vault OK"
                    end
                end
                return true, {}, "Vault OK"
            end
            failures[#failures + 1] = tostring(candidate.Name) .. " HTTP " .. tostring(status or "unknown")
        else
            failures[#failures + 1] = tostring(candidate.Name) .. " failed"
        end
    end

    return false, nil, #failures > 0 and table.concat(failures, " | ") or "No request method"
end

App.Webhook.EnsureVault = function(value, purpose)
    local destination = App.Webhook.Trim(value)
    if App.Webhook.IsVaultHandle(destination) then return true, destination, "Vault ready" end
    if not App.Webhook.IsDiscordURL(destination) then return false, nil, "Invalid Discord webhook URL" end

    local ok, document, message = App.Webhook.VaultRequest("register", {
        url = destination,
        purpose = tostring(purpose or "main"),
    })
    if not ok or type(document) ~= "table" then return false, nil, tostring(message or "Vault enrollment failed") end

    local handle = tostring(document.handle or "")
    if not App.Webhook.IsVaultHandle(handle) then return false, nil, "Vault enrollment failed" end

    if tostring(purpose or "main") == "hourly" then
        App.Values.WebhookHourlyURL = handle
    else
        App.Values.WebhookURL = handle
    end
    App.Webhook.Save()
    return true, handle, "Vaulted"
end

App.Webhook.Save = function()
    local _, write, make = App.Webhook.FileFunctions()
    if type(write) ~= "function" then
        App.Values.WebhookStatus = "File storage unavailable"
        return false
    end
    if type(make) == "function" then pcall(make, "SH") end

    local main = App.Webhook.Trim(App.Values.WebhookURL)
    local hourly = App.Webhook.Trim(App.Values.WebhookHourlyURL)
    local document = {
        Version = 2,
        Enabled = App.Values.WebhookEnabled == true,
        URL = App.Webhook.IsDiscordURL(main) and main or "",
        HourlyURL = App.Webhook.IsDiscordURL(hourly) and hourly or "",
        SendCompleted = App.Values.WebhookSendCompleted ~= false,
        SendFailed = App.Values.WebhookSendFailed == true,
        IncludeStats = App.Values.WebhookStats ~= false,
        HighValue = App.Values.WebhookHighValue ~= false,
        ShowUsername = App.Values.WebhookShowUsername ~= false,
        PingUserId = tostring(App.Values.WebhookPingUserId or ""),
        FamilyUserId = tostring(App.Values.FamilyWebhookUserId or ""),
        HourlyEnabled = App.Values.WebhookHourlyEnabled == true,
        HourlyIntervalHours = tonumber(App.Values.WebhookHourlyIntervalHours) or 1,
        HourlyShowGold = App.Values.WebhookHourlyShowGold ~= false,
        HourlyShowMissions = App.Values.WebhookHourlyShowMissions ~= false,
        HourlyShowActivity = App.Values.WebhookHourlyShowActivity ~= false,
        HourlyShowSummary = App.Values.WebhookHourlyShowSummary ~= false,
        HourlyShowModes = App.Values.WebhookHourlyShowModes ~= false,
        HourlyShowSession = App.Values.WebhookHourlyShowSession ~= false,
        HourlyShowDrops = App.Values.WebhookHourlyShowDrops ~= false,
        HourlyShowBestDrop = App.Values.WebhookHourlyShowBestDrop ~= false,
        HourlyShowStability = App.Values.WebhookHourlyShowStability ~= false,
        SavedAt = os.time(),
    }

    local okEncode, encoded = pcall(HttpService.JSONEncode, HttpService, document)
    if not okEncode then return false end
    local okWrite = pcall(write, App.Webhook.File, encoded)
    if not okWrite then return false end

    -- Keep the named-config copy in sync. Without this, a later V12 config
    -- load can restore an older blank webhook value over webhook.json.
    if type(V12Config) == "table" then
        V12Config.WebhookPreset = {
            Enabled = document.Enabled,
            URL = document.URL,
            HourlyURL = document.HourlyURL,
            SendCompleted = document.SendCompleted,
            SendFailed = document.SendFailed,
            IncludeStats = document.IncludeStats,
            HighValue = document.HighValue,
            ShowUsername = false,
            PingUserId = document.PingUserId,
            FamilyUserId = document.FamilyUserId,
            HourlyEnabled = document.HourlyEnabled,
            HourlyIntervalHours = document.HourlyIntervalHours,
            HourlyShowGold = document.HourlyShowGold,
            HourlyShowMissions = document.HourlyShowMissions,
            HourlyShowActivity = document.HourlyShowActivity,
            HourlyShowSummary = document.HourlyShowSummary,
            HourlyShowModes = document.HourlyShowModes,
            HourlyShowSession = document.HourlyShowSession,
            HourlyShowDrops = document.HourlyShowDrops,
            HourlyShowBestDrop = document.HourlyShowBestDrop,
            HourlyShowStability = document.HourlyShowStability,
        }
        if type(V12Config.ScheduleSave) == "function" then
            V12Config.ScheduleSave(0.05)
        end
    end

    if App.Values.WebhookEnabled == true then
        App.Values.WebhookStatus = App.Webhook.ValidURL(main) and "Ready" or "Enter a valid Discord webhook URL"
    else
        App.Values.WebhookStatus = "Off"
    end
    return true
end

App.Webhook.Load = function()
    local read = select(1, App.Webhook.FileFunctions())
    if type(read) ~= "function" then return false end

    local okRead, raw = pcall(read, App.Webhook.File)
    if not okRead or type(raw) ~= "string" or raw == "" then
        App.Values.WebhookStatus = "Not configured"
        return false
    end

    local okDecode, document = pcall(HttpService.JSONDecode, HttpService, raw)
    if not okDecode or type(document) ~= "table" then
        App.Values.WebhookStatus = "Saved webhook config invalid"
        return false
    end

    App.Values.WebhookEnabled = document.Enabled == true
    App.Values.WebhookURL = tostring(document.URL or "")
    App.Values.WebhookHourlyURL = tostring(document.HourlyURL or "")
    App.Values.WebhookSendCompleted = document.SendCompleted ~= false
    App.Values.WebhookSendFailed = document.SendFailed == true
    App.Values.WebhookStats = document.IncludeStats ~= false
    App.Values.WebhookHighValue = document.HighValue ~= false
    App.Values.WebhookShowUsername = document.ShowUsername ~= false
    App.Values.WebhookPingUserId = tostring(document.PingUserId or App.Values.WebhookPingUserId or "")
    App.Values.FamilyWebhookUserId = tostring(document.FamilyUserId or App.Values.FamilyWebhookUserId or "")
    App.Values.WebhookHourlyEnabled = document.HourlyEnabled == true
    App.Values.WebhookHourlyIntervalHours = math.clamp(math.floor((tonumber(document.HourlyIntervalHours) or 1) + 0.5), 1, 12)
    App.Values.WebhookHourlyShowGold = document.HourlyShowGold ~= false
    App.Values.WebhookHourlyShowMissions = document.HourlyShowMissions ~= false
    App.Values.WebhookHourlyShowActivity = document.HourlyShowActivity ~= false
    App.Values.WebhookHourlyShowSummary = document.HourlyShowSummary ~= false
    App.Values.WebhookHourlyShowModes = document.HourlyShowModes ~= false
    App.Values.WebhookHourlyShowSession = document.HourlyShowSession ~= false
    App.Values.WebhookHourlyShowDrops = document.HourlyShowDrops ~= false
    App.Values.WebhookHourlyShowBestDrop = document.HourlyShowBestDrop ~= false
    App.Values.WebhookHourlyShowStability = document.HourlyShowStability ~= false

    -- Legacy plaintext migration: keep the URL in memory only long enough to
    -- enroll it. Save() already refuses to persist raw Discord URLs.
    if App.Webhook.IsDiscordURL(App.Values.WebhookURL) then
        task.spawn(function()
            local ok = App.Webhook.EnsureVault(App.Values.WebhookURL, "main")
            if ok then App.Values.WebhookStatus = "Ready" end
        end)
    end
    if App.Webhook.IsDiscordURL(App.Values.WebhookHourlyURL) then
        task.spawn(function()
            App.Webhook.EnsureVault(App.Values.WebhookHourlyURL, "hourly")
        end)
    end

    App.Values.WebhookStatus = App.Values.WebhookEnabled
        and (App.Webhook.ValidURL(App.Values.WebhookURL) and "Ready" or "Webhook not configured")
        or "Off"
    return true
end

App.Webhook.Post = function(payload)
    local okVault, handle, vaultMessage = App.Webhook.EnsureVault(App.Values.WebhookURL, "main")
    if not okVault then
        App.Values.WebhookStatus = tostring(vaultMessage or "Webhook vault unavailable")
        return false, App.Values.WebhookStatus
    end

    local ok, _, message = App.Webhook.VaultRequest("send", {
        handle = handle,
        payload = payload,
    })
    App.Webhook.Status = ok and "Sent" or tostring(message or "Webhook relay failed")
    App.Values.WebhookStatus = App.Webhook.Status
    return ok, App.Webhook.Status
end

App.Webhook.ReadAccount = function()
    local result = {
        Gold = nil,
        Gems = nil,
        Prestige = nil,
        Level = nil,
        Slot = nil,
    }

    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")

    if not (remote and remote:IsA("RemoteFunction")) then
        return result
    end

    local ok, profile = pcall(function()
        return remote:InvokeServer("Data", "Copy")
    end)

    if not ok or type(profile) ~= "table" then
        return result
    end

    local slotKey = profile.Current_Slot or player:GetAttribute("Slot")
    local slots = type(profile.Slots) == "table" and profile.Slots or nil
    local slot = slots and (
        slots[slotKey]
        or slots[tostring(slotKey)]
        or slots[tonumber(slotKey)]
    ) or nil

    if type(slot) ~= "table" then
        return result
    end

    local progression = type(slot.Progression) == "table" and slot.Progression or {}
    local currency = type(slot.Currency) == "table" and slot.Currency or {}

    result.Slot = slotKey
    result.Prestige = tonumber(progression.Prestige)
    result.Level = tonumber(progression.Level)
    result.Gold = tonumber(currency.Gold)
    result.Gems = tonumber(currency.Gems or currency.Gem)

    return result
end

App.Webhook.ReadAccountFresh = function()
    local best = App.Webhook.ReadAccount()

    -- Result rewards and account currency do not always settle on the same frame.
    -- A few bounded read-only Data/Copy samples keeps totals accurate without polling.
    for _ = 1, 3 do
        task.wait(0.18)

        local nextValue = App.Webhook.ReadAccount()
        if type(nextValue) == "table" then
            local hasUsefulValue =
                nextValue.Gold ~= nil
                or nextValue.Gems ~= nil
                or nextValue.Prestige ~= nil
                or nextValue.Level ~= nil

            if hasUsefulValue then
                best = nextValue
            end
        end
    end

    return best
end

App.Webhook.SessionStart = App.Webhook.SessionStart or App.Webhook.ReadAccount()

App.Webhook.NormalizeCategory = function(category, name, runType)
    local cat = string.lower(tostring(category or ""))
    local lowerName = string.lower(tostring(name or ""))

    cat = string.gsub(cat, "[^%w]", "")

    if string.find(cat, "perk", 1, true) then
        return "Perks"
    end

    if string.find(cat, "artifact", 1, true) then
        return "Artifacts"
    end

    if string.find(cat, "serum", 1, true)
        or string.find(lowerName, "serum", 1, true) then
        return "Serums"
    end

    if string.find(cat, "material", 1, true) then
        return "Materials"
    end

    if string.find(cat, "cosmetic", 1, true)
        or string.find(cat, "skin", 1, true)
        or string.find(cat, "emote", 1, true) then
        return "Cosmetics"
    end

    if string.find(cat, "raid", 1, true)
        or string.find(cat, "drop", 1, true) then
        return tostring(runType) == "Raid"
            and "Raid Drops"
            or "Drops"
    end

    return "Other"
end

App.Webhook.CaptureRewards = function(runType)
    local capture = {
        XP = 0,
        Gold = 0,
        Gems = 0,
        Stats = {},
        Items = {},
        Chests = {},
        Seconds = nil,
        Safety = "Unknown",
        Disabled = nil,
        Raw = nil,
    }

    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")

    if not (remote and remote:IsA("RemoteFunction")) then
        return capture
    end

    local ok, response = pcall(function()
        return remote:InvokeServer(
            "S_Rewards",
            "Get",
            true
        )
    end)

    if not ok or type(response) ~= "table" then
        return capture
    end

    -- Keep only parsed reward fields. Holding the full server response in
    -- LastCapture retained unnecessary tables across long AFK sessions.
    capture.Seconds = tonumber(response.Seconds)
    capture.Disabled = response.Disabled

    -- V15.6.10: S_Rewards.Disabled is a literal reward-response field, not an
    -- authoritative trade/join/ban verdict. A missing/false value must never
    -- be promoted to "Safe".
    if response.Disabled == nil then
        capture.Safety = "Disabled flag not present • restriction status unverified"
    elseif response.Disabled == false then
        capture.Safety = "Disabled flag: false • restriction status unverified"
    elseif type(response.Disabled) == "table" then
        local encodedOk, encoded = pcall(HttpService.JSONEncode, HttpService, response.Disabled)
        capture.Safety = encodedOk
            and ("Disabled flag: " .. tostring(encoded))
            or "Disabled flag present"
    else
        capture.Safety = "Disabled flag: " .. tostring(response.Disabled)
    end

    local obtained =
        type(response.Obtained) == "table"
        and response.Obtained
        or {}

    capture.XP = math.max(0, tonumber(obtained.XP) or 0)
    capture.Gold = math.max(0, tonumber(obtained.Gold) or 0)
    capture.Gems = math.max(0, tonumber(obtained.Gems) or 0)
    capture.Stats =
        type(response.Stats) == "table"
        and response.Stats
        or {}

    local seen = {}

    local function add(name, category, rarity, quantity)
        name = App.Webhook.Trim(name)
        if name == "" then return end

        local normalized =
            App.Webhook.NormalizeCategory(
                category,
                name,
                runType
            )

        local qty = math.max(
            1,
            math.floor((tonumber(quantity) or 1) + 0.5)
        )

        local rarityText = App.Webhook.Trim(rarity)
        if rarityText == "" then rarityText = nil end
        if rarityText == nil
            and normalized == "Perks"
            and App.PerkManager
            and type(App.PerkManager.RarityByName) == "table" then
            rarityText = App.PerkManager.RarityByName[name]
        end

        local key =
            string.lower(normalized)
            .. "|"
            .. string.lower(name)
            .. "|"
            .. string.lower(tostring(rarityText or ""))

        if not seen[key] then
            seen[key] = {
                Name = name,
                Category = normalized,
                Rarity = rarityText,
                Quantity = 0,
            }

            capture.Items[#capture.Items + 1] =
                seen[key]
        end

        seen[key].Quantity += qty
    end

    local function collect(value, category, depth)
        depth = tonumber(depth) or 0
        if depth > 7 or value == nil then return end

        if type(value) == "string" then
            add(value, category, nil, 1)
            return
        end

        if type(value) ~= "table" then
            return
        end

        local name =
            value.Name
            or value.name
            or value.Item
            or value.item
            or value.ItemName
            or value.itemName
            or value.Tag
            or value.tag

        local rarity =
            value.Rarity
            or value.rarity

        local nestedCategory =
            value.Category
            or value.category
            or value.Type
            or value.type
            or category

        local quantity =
            value.Quantity
            or value.quantity
            or value.Amount
            or value.amount
            or value.Count
            or value.count
            or 1

        if type(name) == "string" and name ~= "" then
            add(
                name,
                nestedCategory,
                rarity,
                quantity
            )
        end

        for key, child in pairs(value) do
            local keyText = tostring(key)

            if keyText ~= "Name"
                and keyText ~= "name"
                and keyText ~= "Item"
                and keyText ~= "item"
                and keyText ~= "ItemName"
                and keyText ~= "itemName"
                and keyText ~= "Tag"
                and keyText ~= "tag"
                and keyText ~= "Rarity"
                and keyText ~= "rarity"
                and keyText ~= "Category"
                and keyText ~= "category"
                and keyText ~= "Type"
                and keyText ~= "type"
                and keyText ~= "Quantity"
                and keyText ~= "quantity"
                and keyText ~= "Amount"
                and keyText ~= "amount"
                and keyText ~= "Count"
                and keyText ~= "count" then

                if type(child) == "number"
                    and type(key) == "string"
                    and child > 0 then
                    add(
                        keyText,
                        category,
                        nil,
                        child
                    )
                elseif type(child) == "boolean"
                    and type(key) == "string"
                    and child == true then
                    add(
                        keyText,
                        category,
                        nil,
                        1
                    )
                elseif type(child) == "table"
                    or type(child) == "string" then
                    local nextCategory =
                        type(key) == "string"
                        and keyText
                        or category

                    collect(
                        child,
                        nextCategory,
                        depth + 1
                    )
                end
            end
        end
    end


    collect(obtained.Perks, "Perks", 0)


    collect(obtained.Drops, "Drops", 0)


    for key, value in pairs(obtained) do
        local keyText = tostring(key)
        if keyText ~= "XP"
            and keyText ~= "Gold"
            and keyText ~= "Gems"
            and keyText ~= "Perks"
            and keyText ~= "Drops"
            and keyText ~= "Chests"
            and type(value) == "table"
            and next(value) ~= nil then
            collect(value, keyText, 0)
        end
    end

    if type(obtained.Chests) == "table" then
        for key, value in pairs(obtained.Chests) do
            if value == true then
                capture.Chests[#capture.Chests + 1] =
                    tostring(key)
            elseif type(value) == "number"
                and value > 0 then
                capture.Chests[#capture.Chests + 1] =
                    tostring(key)
                    .. " x"
                    .. tostring(math.floor(value + 0.5))
            end
        end
    end

    table.sort(capture.Chests)

    return capture
end

App.Webhook.RunInfo = function(resultInfo)
    local state = tostring(resultInfo and resultInfo.State or "")
    local stateLower = string.lower(state)
    local runType = "Mission"

    if string.find(stateLower, "raid", 1, true) then
        runType = "Raid"
    elseif string.find(stateLower, "wave", 1, true) then
        runType = "Waves"
    end

    local liveMap = nil

    pcall(function()
        local assets = ReplicatedStorage:FindFirstChild("Assets")
        local remotes = assets and assets:FindFirstChild("Remotes")
        local remote = remotes and remotes:FindFirstChild("GET")

        if not (
            remote
            and remote:IsA("RemoteFunction")
        ) then
            return
        end

        local profile =
            remote:InvokeServer(
                "Data",
                "Copy"
            )

        if type(profile) == "table"
            and type(profile.Map) == "table" then
            liveMap = profile.Map
        end
    end)

    do
        local waves = workspace:FindFirstChild("Waves")
        local unclimbable = workspace:FindFirstChild("Unclimbable")
        local objective = unclimbable and unclimbable:FindFirstChild("Objective")
        local liveObjective = string.lower(tostring(liveMap and liveMap.Objective or ""))
        local actualWaves = (
            waves ~= nil
            and objective ~= nil
            and objective:FindFirstChild("Waves") ~= nil
        ) or string.find(liveObjective, "wave", 1, true) ~= nil
        if actualWaves then
            runType = "Waves"
        elseif runType == "Waves" then
            runType = "Mission"
        end
    end

    if runType == "Waves" then
        return {
            Type = "Waves",
            Map =
                liveMap
                and tostring(
                    liveMap.Map
                    or liveMap.Name
                    or "Trost"
                )
                or "Trost",
            Objective =
                liveMap
                and tostring(
                    liveMap.Objective
                    or "Waves"
                )
                or "Waves",
            Difficulty =
                liveMap
                and tostring(
                    liveMap.Difficulty
                    or "Easy"
                )
                or "Easy",
        }
    end

    if runType == "Raid" then
        local choice =
            tostring(
                App.Values.LobbyRaidChoice
                or "Unknown Raid"
            )

        local raid =
            App.LobbyRaidData
            and App.LobbyRaidData[choice]
            or nil

        if liveMap and App.LobbyRaidData then
            local liveMapName = string.lower(tostring(liveMap.Map or liveMap.Name or ""))
            local liveObjective = string.lower(tostring(liveMap.Objective or ""))
            for raidChoice, raidData in pairs(App.LobbyRaidData) do
                local raidMap = string.lower(tostring(raidData and raidData.Map or ""))
                local raidObjective = string.lower(tostring(raidData and raidData.Objective or ""))
                if liveMapName ~= ""
                    and liveObjective ~= ""
                    and liveMapName == raidMap
                    and liveObjective == raidObjective then
                    choice = tostring(raidChoice)
                    raid = raidData
                    break
                end
            end
        end

        local fallbackDifficulty =
            tostring(
                App.Values.LobbyDifficulty
                or "Hard"
            )

        if raid
            and type(raid.Difficulties) == "table"
            and #raid.Difficulties > 0 then

            if fallbackDifficulty == "Hardest" then
                fallbackDifficulty =
                    tostring(
                        raid.Difficulties[
                            #raid.Difficulties
                        ]
                    )
            elseif not table.find(
                raid.Difficulties,
                fallbackDifficulty
            ) then
                fallbackDifficulty =
                    tostring(raid.Difficulties[1])
            end
        end

        local resolvedDifficulty =
            liveMap
            and liveMap.Difficulty
            and tostring(liveMap.Difficulty)
            or fallbackDifficulty

        if raid
            and type(raid.Difficulties) == "table"
            and #raid.Difficulties > 0
            and not table.find(
                raid.Difficulties,
                resolvedDifficulty
            ) then
            -- Raid webhooks can never inherit a stale Mission-only difficulty.
            -- Armored raids resolve to Hard/Severe/Aberrant and Colossal to
            -- its configured raid difficulty set (currently Aberrant).
            resolvedDifficulty = fallbackDifficulty
        end

        return {
            Type = "Raid",
            Raid = choice,
            Map =
                liveMap
                and tostring(
                    liveMap.Map
                    or liveMap.Name
                    or "Unknown"
                )
                or (
                    raid
                    and tostring(raid.Map)
                    or tostring(
                        App.Values.LobbyMap
                        or "Unknown"
                    )
                ),
            Objective =
                liveMap
                and tostring(
                    liveMap.Objective
                    or "Unknown"
                )
                or (
                    raid
                    and tostring(raid.Objective)
                    or tostring(
                        App.Values.LobbyObjective
                        or "Unknown"
                    )
                ),
            Difficulty = resolvedDifficulty,
        }
    end


    return {
        Type = "Mission",
        Map =
            liveMap
            and tostring(
                liveMap.Map
                or liveMap.Name
                or "Unknown"
            )
            or tostring(
                App.Values.LobbyMap
                or "Unknown"
            ),
        Objective =
            liveMap
            and tostring(
                liveMap.Objective
                or "Unknown"
            )
            or tostring(
                App.Values.LobbyObjective
                or "Unknown"
            ),
        Difficulty =
            liveMap
            and tostring(
                liveMap.Difficulty
                or "Unknown"
            )
            or tostring(
                App.Values.LobbyDifficulty
                or "Unknown"
            ),
    }
end

App.Webhook.ItemText = function(items)
    if type(items) ~= "table"
        or #items == 0 then
        return nil
    end

    local order = {
        "Perks",
        "Artifacts",
        "Serums",
        "Materials",
        "Cosmetics",
        "Drops",
        "Other",
    }

    local groups = {}
    local total = 0
    local shown = 0
    local maxShown = 10

    for _, category in ipairs(order) do
        groups[category] = {}
    end

    for _, item in ipairs(items) do
        total += 1

        if shown < maxShown then
            local category =
                groups[item.Category]
                and item.Category
                or "Other"

            local line =
                "• "
                .. tostring(
                    item.Name
                    or "Unknown"
                )

            if item.Rarity
                and item.Rarity ~= "" then
                line ..=
                    " • "
                    .. tostring(item.Rarity)
            end

            if (tonumber(item.Quantity) or 1) > 1 then
                line ..=
                    " ×"
                    .. tostring(
                        math.floor(
                            (tonumber(item.Quantity) or 1)
                            + 0.5
                        )
                    )
            end

            groups[category][#groups[category] + 1] =
                line

            shown += 1
        end
    end

    local sections = {}

    for _, category in ipairs(order) do
        if #groups[category] > 0 then
            sections[#sections + 1] =
                "**"
                .. category
                .. "**\n"
                .. table.concat(
                    groups[category],
                    "\n"
                )
        end
    end

    if total > shown then
        sections[#sections + 1] =
            "• +"
            .. tostring(total - shown)
            .. " more"
    end

    if #sections == 0 then
        return nil
    end

    local text =
        table.concat(
            sections,
            "\n\n"
        )

    if #text > 950 then
        text =
            string.sub(
                text,
                1,
                947
            )
            .. "..."
    end

    return text
end


App.Webhook.HasHighValue = function(items)
    for _, item in ipairs(type(items) == "table" and items or {}) do
        local category =
            string.lower(tostring(item.Category or ""))

        local rarity =
            string.lower(tostring(item.Rarity or ""))

        local name =
            string.lower(tostring(item.Name or ""))

        local serum =
            category == "serums"
            or string.find(name, "serum", 1, true) ~= nil

        local mythic =
            rarity == "mythic"
            and (
                category == "perks"
                or category == "artifacts"
            )

        if serum or mythic then
            return true
        end
    end

    return false
end


App.Shadowban = App.Shadowban or {
    Status = "⚪ UNVERIFIED",
    Evidence = "No authoritative multiplayer verification was completed.",
    Source = "none",
    CheckedAt = 0,
    CacheVersion = 3,
    CleanTTL = 6 * 60 * 60,
}

App.Shadowban.CachePath = function()
    return "SH/state/shadowban_verified_v3_"
        .. tostring(player.UserId)
        .. ".json"
end

App.Shadowban.NormalizeStatus = function(value)
    local text = string.upper(tostring(value or ""))

    if string.find(text, "SHADOWBANNED", 1, true)
        and not string.find(text, "NOT SHADOWBANNED", 1, true) then
        return "🔴 SHADOWBANNED — VERIFIED"
    end

    if string.find(text, "NOT SHADOWBANNED", 1, true) then
        return "🟢 NOT SHADOWBANNED — VERIFIED"
    end

    return "⚪ UNVERIFIED"
end

App.Shadowban.IsVerified = function(status)
    status = App.Shadowban.NormalizeStatus(status)
    return status == "🔴 SHADOWBANNED — VERIFIED"
        or status == "🟢 NOT SHADOWBANNED — VERIFIED"
end

App.Shadowban.SourceAllowed = function(status, source)
    local normalized = App.Shadowban.NormalizeStatus(status)
    local sourceText = string.lower(tostring(source or ""))

    if normalized == "🔴 SHADOWBANNED — VERIFIED" then
        return string.find(sourceText, "controlled_multiplayer_join_rejection", 1, true) ~= nil
            or string.find(sourceText, "confirmed_multiplayer_restriction", 1, true) ~= nil
    end

    if normalized == "🟢 NOT SHADOWBANNED — VERIFIED" then
        return string.find(sourceText, "controlled_multiplayer_join_success", 1, true) ~= nil
            or string.find(sourceText, "confirmed_multiplayer_membership", 1, true) ~= nil
    end

    return false
end

App.Shadowban.Save = function()
    if not App.Shadowban.IsVerified(App.Shadowban.Status) then
        return false
    end

    local _, write, make = App.Webhook.FileFunctions()
    if type(write) ~= "function" then
        return false
    end

    if type(make) == "function" then
        pcall(make, "SH")
        pcall(make, "SH/state")
    end

    local payload = {
        Version = App.Shadowban.CacheVersion,
        Status = App.Shadowban.Status,
        Evidence = tostring(App.Shadowban.Evidence or ""),
        Source = tostring(App.Shadowban.Source or ""),
        CheckedAt = tonumber(App.Shadowban.CheckedAt) or os.time(),
    }

    return pcall(
        write,
        App.Shadowban.CachePath(),
        HttpService:JSONEncode(payload)
    )
end

App.Shadowban.SetAuthoritative = function(status, evidence, source)
    local normalized = App.Shadowban.NormalizeStatus(status)


    if not App.Shadowban.SourceAllowed(normalized, source) then
        App.Shadowban.Status = "⚪ UNVERIFIED"
        App.Shadowban.Evidence =
            tostring(
                evidence
                or "Authoritative multiplayer evidence was not completed."
            )
        App.Shadowban.Source = "unverified"
        App.Shadowban.CheckedAt = os.time()
        return false
    end

    App.Shadowban.Status = normalized
    App.Shadowban.Evidence =
        tostring(
            evidence
            or (
                normalized == "🔴 SHADOWBANNED — VERIFIED"
                and "Server rejected the controlled multiplayer join with the confirmed restriction."
                or "Controlled multiplayer join was accepted and membership was confirmed."
            )
        )
    App.Shadowban.Source = tostring(source)
    App.Shadowban.CheckedAt = os.time()
    App.Shadowban.Save()
    return true
end

App.Shadowban.Load = function()
    local read = select(1, App.Webhook.FileFunctions())
    if type(read) ~= "function" then
        return false
    end

    local ok, raw = pcall(read, App.Shadowban.CachePath())
    if not ok or type(raw) ~= "string" or raw == "" then
        return false
    end

    local decodedOk, data =
        pcall(HttpService.JSONDecode, HttpService, raw)

    if not decodedOk
        or type(data) ~= "table"
        or tonumber(data.Version) ~= App.Shadowban.CacheVersion then
        return false
    end

    local status =
        App.Shadowban.NormalizeStatus(data.Status)

    if not App.Shadowban.IsVerified(status)
        or not App.Shadowban.SourceAllowed(status, data.Source) then
        return false
    end

    local checkedAt = tonumber(data.CheckedAt) or 0


    if status == "🟢 NOT SHADOWBANNED — VERIFIED"
        and (
            checkedAt <= 0
            or os.time() - checkedAt > App.Shadowban.CleanTTL
        ) then
        return false
    end

    App.Shadowban.Status = status
    App.Shadowban.Evidence =
        tostring(data.Evidence or "Authoritative verification cached.")
    App.Shadowban.Source = tostring(data.Source or "cache")
    App.Shadowban.CheckedAt = checkedAt
    return true
end

App.Shadowban.StatusText = function()
    return tostring(App.Shadowban.Status or "⚪ UNVERIFIED")
end

App.Shadowban.EvidenceText = function()
    local evidence =
        tostring(
            App.Shadowban.Evidence
            or "No authoritative multiplayer verification was completed."
        )

    if #evidence > 150 then
        evidence = string.sub(evidence, 1, 147) .. "..."
    end

    return evidence
end

App.Shadowban.Snapshot = function()
    return {
        Status = App.Shadowban.StatusText(),
        Evidence = App.Shadowban.EvidenceText(),
        Source = tostring(App.Shadowban.Source or "none"),
        CheckedAt = tonumber(App.Shadowban.CheckedAt) or 0,
    }
end


App.Shadowban.Load()

App.Webhook.LayoutVersion = "R5_BOOSTS_RELIABLE_SEND"

App.Webhook.ActiveBoostsText = function()
    local boosts = player:FindFirstChild("Boosts")
    local active = {}

    for _, definition in ipairs({
        {Key="XP", Label="EXP"},
        {Key="Gold", Label="Gold"},
        {Key="Luck", Label="Luck"},
    }) do
        local object = boosts and boosts:FindFirstChild(definition.Key)
        local seconds = object
            and (object:IsA("IntValue") or object:IsA("NumberValue"))
            and math.max(0, tonumber(object.Value) or 0)
            or 0

        if seconds > 0 then
            local hours = math.floor(seconds / 3600)
            local minutes = math.floor((seconds % 3600) / 60)
            local remain = math.floor(seconds % 60)
            local timeText = hours > 0
                and string.format("%dh %02dm", hours, minutes)
                or string.format("%dm %02ds", minutes, remain)
            active[#active + 1] = "**" .. definition.Label .. "** • " .. timeText
        end
    end

    return #active > 0
        and table.concat(active, "\n")
        or "No boosts running"
end

App.Webhook.BuildPayload = function(data)
    local failed = data.Failed == true
    local rewards =
        type(data.Rewards) == "table"
        and data.Rewards
        or {
            XP = 0,
            Gold = 0,
            Gems = 0,
            Stats = {},
            Items = {},
            Chests = {},
            Safety = "Unknown",
        }

    local account =
        type(data.Account) == "table"
        and data.Account
        or {}

    local run =
        type(data.Run) == "table"
        and data.Run
        or {}

    local highValue =
        App.Values.WebhookHighValue ~= false
        and App.Webhook.HasHighValue(rewards.Items)

    local runType = tostring(run.Type or "Mission")
    local runUpper = string.upper(runType)
    local mapName = tostring(run.Map or "Unknown")
    local objective = tostring(run.Objective or "Unknown")
    local difficulty = tostring(run.Difficulty or "Unknown")

    local limit =
        math.max(
            0,
            math.floor(
                (tonumber(data.Limit) or 0)
                + 0.5
            )
        )

    local progress =
        limit > 0
        and (
            tostring(data.Count or 0)
            .. " / "
            .. tostring(limit)
        )
        or (
            tostring(data.Count or 0)
            .. " / ∞"
        )

    local resolvedSeconds = tonumber(data.CompletionSeconds) or tonumber(rewards.Seconds)
    local duration = resolvedSeconds ~= nil
        and App.RunState.FormatDuration(resolvedSeconds)
        or "—"

    local function deltaText(value)
        if value == nil then return nil end
        local n = tonumber(value)
        if n == nil then return nil end
        return (
            n > 0
            and "+"
            or ""
        ) .. App.Webhook.FormatNumber(n)
    end

    local function compactNumber(value)
        local n = tonumber(value)
        if not n then
            return App.Webhook.FormatNumber(value)
        end

        local abs = math.abs(n)
        if abs >= 1000000000 then
            return string.format("%.2fB", n / 1000000000)
        elseif abs >= 1000000 then
            return string.format("%.2fM", n / 1000000)
        elseif abs >= 1000 then
            return string.format("%.1fK", n / 1000)
        end

        return App.Webhook.FormatNumber(n)
    end

    local sessionStart =
        type(App.Webhook.SessionStart) == "table"
        and App.Webhook.SessionStart
        or {}

    local currentGold = tonumber(account.Gold)
    local startGold = tonumber(sessionStart.Gold)
    local currentGems = tonumber(account.Gems)
    local startGems = tonumber(sessionStart.Gems)

    local goldDelta =
        currentGold ~= nil
        and startGold ~= nil
        and (currentGold - startGold)
        or nil

    local gemDelta =
        currentGems ~= nil
        and startGems ~= nil
        and (currentGems - startGems)
        or nil

    local fields = {
        {
            name = "DIFFICULTY",
            value = "**" .. difficulty .. "**",
            inline = true,
        },
        {
            name = "TIME",
            value = "**" .. tostring(duration) .. "**",
            inline = true,
        },
        {
            name = "RUN",
            value = "**" .. progress .. "**",
            inline = true,
        },
    }

    local accountParts = {}

    if account.Prestige ~= nil then
        accountParts[#accountParts + 1] =
            "P" .. tostring(account.Prestige)
    end

    if account.Level ~= nil then
        accountParts[#accountParts + 1] =
            "LV" .. tostring(account.Level)
    end

    if account.Slot ~= nil then
        accountParts[#accountParts + 1] =
            "Slot " .. tostring(account.Slot)
    end

    if #accountParts > 0 then
        fields[#fields + 1] = {
            name = "ACCOUNT",
            value =
                "**"
                .. table.concat(accountParts, " • ")
                .. "**",
            inline = false,
        }
    end

    if account.Gold ~= nil then
        local value =
            "**"
            .. App.Webhook.FormatNumber(account.Gold)
            .. "**"

        if goldDelta ~= nil then
            value ..=
                "\n▲ "
                .. deltaText(goldDelta)
                .. " session"
        end

        fields[#fields + 1] = {
            name = "GOLD",
            value = value,
            inline = true,
        }
    end

    if account.Gems ~= nil then
        local value =
            "**"
            .. App.Webhook.FormatNumber(account.Gems)
            .. "**"

        if gemDelta ~= nil then
            value ..=
                "\n▲ "
                .. deltaText(gemDelta)
                .. " session"
        end

        fields[#fields + 1] = {
            name = "GEMS",
            value = value,
            inline = true,
        }
    end

    fields[#fields + 1] = {
        name = "RUN PROFIT",
        value =
            "`+"
            .. App.Webhook.FormatNumber(rewards.XP)
            .. " XP`  •  `+"
            .. App.Webhook.FormatNumber(rewards.Gold)
            .. " Gold`  •  `+"
            .. App.Webhook.FormatNumber(rewards.Gems)
            .. " Gems`",
        inline = false,
    }

    fields[#fields + 1] = {
        name = "ACTIVE BOOSTS",
        value = tostring(data.ActiveBoosts or "No boosts running"),
        inline = false,
    }

    local regularItems = {}
    local raidItems = {}

    for _, item in ipairs(
        type(rewards.Items) == "table"
        and rewards.Items
        or {}
    ) do
        if tostring(item.Category or "") == "Raid Drops" then
            raidItems[#raidItems + 1] = item
        else
            regularItems[#regularItems + 1] = item
        end
    end

    local itemText =
        App.Webhook.ItemText(regularItems)

    if itemText then
        fields[#fields + 1] = {
            name =
                highValue
                and "⭐ DROPS"
                or "DROPS",
            value = itemText,
            inline = false,
        }
    end

    if #raidItems > 0 then
        local raidLines = {}

        for index, item in ipairs(raidItems) do
            if index > 8 then
                raidLines[#raidLines + 1] =
                    "• +"
                    .. tostring(#raidItems - 8)
                    .. " more"
                break
            end

            local line =
                "• **"
                .. tostring(item.Name or "Drop")
                .. "**"

            if (tonumber(item.Quantity) or 1) > 1 then
                line ..=
                    " ×"
                    .. tostring(
                        math.floor(
                            (tonumber(item.Quantity) or 1)
                            + 0.5
                        )
                    )
            end

            raidLines[#raidLines + 1] = line
        end

        fields[#fields + 1] = {
            name = "RAID DROP",
            value = table.concat(raidLines, "\n"),
            inline = true,
        }
    end

    if type(rewards.Chests) == "table"
        and #rewards.Chests > 0 then
        fields[#fields + 1] = {
            name = "CHESTS",
            value =
                "**"
                .. table.concat(rewards.Chests, " • ")
                .. "**",
            inline = true,
        }
    end

    if App.Values.WebhookStats ~= false then
        local stats =
            type(rewards.Stats) == "table"
            and rewards.Stats
            or {}

        local combat = {}

        if tonumber(stats.Kills) ~= nil then
            combat[#combat + 1] =
                "**"
                .. App.Webhook.FormatNumber(stats.Kills)
                .. "** kills"
        end

        if tonumber(stats.Crits) ~= nil then
            combat[#combat + 1] =
                "**"
                .. App.Webhook.FormatNumber(stats.Crits)
                .. "** crits"
        end

        if tonumber(data.Streak) ~= nil then
            combat[#combat + 1] =
                "**"
                .. App.Webhook.FormatNumber(data.Streak)
                .. "** streak"
        end

        local combatText =
            #combat > 0
            and table.concat(combat, "  •  ")
            or nil

        if tonumber(stats.Damage) ~= nil then
            local damageText =
                "**"
                .. compactNumber(stats.Damage)
                .. "** damage"

            combatText =
                combatText
                and (
                    combatText
                    .. "\n"
                    .. damageText
                )
                or damageText
        end

        -- Boss_Damage is intentionally omitted. The old value was not a
        -- user-meaningful raid metric and produced confusing lines like "Boss 98".
        if combatText then
            fields[#fields + 1] = {
                name = "COMBAT",
                value = combatText,
                inline = false,
            }
        end
    end

    local shadowban = App.Shadowban.Snapshot()
    if App.Shadowban.IsVerified(shadowban.Status) then
        fields[#fields + 1] = {
            name = "SAFETY",
            value = "**" .. tostring(shadowban.Status) .. "**",
            inline = false,
        }
    end

    local accent = 3066993
    if runType == "Raid" then
        accent = 10181046
    elseif runType == "Waves" then
        accent = 3447003
    end

    if highValue then
        accent = 16766720
    end

    if failed then
        accent = 15158332
    end

    local title =
        (highValue and "⭐ " or "")
        .. "SLICEHUB // "
        .. runUpper
        .. (
            failed
            and " FAILED"
            or " COMPLETE"
        )

    local descriptionParts = {
        "**" .. string.upper(mapName) .. "**",
    }

    if runType == "Raid"
        and run.Raid
        and tostring(run.Raid) ~= ""
        and string.lower(tostring(run.Raid))
            ~= string.lower(mapName) then
        descriptionParts[#descriptionParts + 1] =
            tostring(run.Raid)
    end

    if objective ~= ""
        and objective ~= "Unknown" then
        descriptionParts[#descriptionParts + 1] =
            objective
    end

    return {
        username = "SliceHub",
        allowed_mentions = {parse = {}},
        embeds = {{
            title = title,
            description =
                table.concat(
                    descriptionParts,
                    "  •  "
                ),
            color = accent,
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            fields = fields,
            footer = {
                text = App.Values.WebhookShowUsername ~= false
                    and ("SliceHub • AOT:R • @" .. tostring(player.Name))
                    or "SliceHub • AOT:R",
            },
        }},
    }
end

App.Webhook.QueueResult = function(resultInfo, serial, count, limit, completionSeconds)
    -- V14.5 R4: a superseded runtime is never allowed to send a result.
    if App.RuntimeHealth
        and App.RuntimeHealth.Alive ~= true then
        return false
    end

    if App.Values.WebhookEnabled ~= true then
        return false
    end

    if not App.Webhook.ValidURL(App.Values.WebhookURL) then
        App.Values.WebhookStatus =
            "Webhook URL invalid"
        return false
    end

    local lower =
        string.lower(
            tostring(
                resultInfo
                and resultInfo.State
                or ""
            )
        )

    local failed =
        string.find(
            lower,
            "failed",
            1,
            true
        ) ~= nil

    if failed
        and App.Values.WebhookSendFailed ~= true then
        return false
    end

    if not failed
        and App.Values.WebhookSendCompleted == false then
        return false
    end

    serial = tonumber(serial) or 0
    count = tonumber(count) or 0

    local env = App.Webhook.Environment()

    env.__SliceHubNewGenWebhookDedupe =
        type(env.__SliceHubNewGenWebhookDedupe) == "table"
        and env.__SliceHubNewGenWebhookDedupe
        or {}

    local dedupe = env.__SliceHubNewGenWebhookDedupe
    local now = os.clock()

    -- V15.6.10: dedupe by the run itself, not by the UI result serial.
    -- The same visible result panel can be re-detected with a new serial.
    local accountKey = table.concat({
        tostring(player.UserId),
        tostring(game.PlaceId),
        tostring(game.JobId or ""),
        tostring(lower),
        tostring(count),
    }, ":")

    local existing = dedupe[accountKey]
    if existing == "pending" then
        App.Values.WebhookStatus = "Duplicate result skipped"
        return false
    end
    if type(existing) == "table"
        and existing.State == "sent"
        and now - (tonumber(existing.At) or 0) < 30 then
        App.Values.WebhookStatus = "Duplicate result skipped"
        return false
    end

    dedupe[accountKey] = "pending"

    App.Values.WebhookStatus =
        "Reading result rewards"


    local runInfo =
        App.Webhook.RunInfo(resultInfo)

    local rewards =
        App.Webhook.CaptureRewards(
            runInfo.Type
        )

    local account =
        App.Webhook.ReadAccountFresh
        and App.Webhook.ReadAccountFresh()
        or App.Webhook.ReadAccount()

    if not failed and App.RunState then
        local session = App.RunState.Data or App.RunState.Load()
        local rewardRunId = math.max(0, tonumber(session.LastCountedRunId) or tonumber(session.RunId) or 0)
        if rewardRunId <= 0 or tonumber(session.LastRewardCountedRunId) ~= rewardRunId then
            session.SessionRewardGold = math.max(0, tonumber(session.SessionRewardGold) or 0)
                + math.max(0, tonumber(rewards.Gold) or 0)
            session.SessionRewardGems = math.max(0, tonumber(session.SessionRewardGems) or 0)
                + math.max(0, tonumber(rewards.Gems) or 0)
            session.SessionRewardXP = math.max(0, tonumber(session.SessionRewardXP) or 0)
                + math.max(0, tonumber(rewards.XP) or 0)
            if rewardRunId > 0 then session.LastRewardCountedRunId = rewardRunId end
            pcall(App.RunState.Save)
        end
    end

    if type(App.Webhook.SessionStart) ~= "table"
        or (
            App.Webhook.SessionStart.Gold == nil
            and App.Webhook.SessionStart.Gems == nil
        ) then
        App.Webhook.SessionStart = {
            Gold = account.Gold,
            Gems = account.Gems,
            Prestige = account.Prestige,
            Level = account.Level,
            Slot = account.Slot,
        }
    end

    local data = {
        Failed = failed,
        Run = runInfo,
        Count = tonumber(count) or 0,
        Limit = tonumber(limit) or 0,
        Rewards = rewards,
        Account = account,
        Streak = tonumber(player:GetAttribute("Streak")),
        CompletionSeconds = tonumber(completionSeconds),
        ActiveBoosts = App.Webhook.ActiveBoostsText(),
    }

    App.Webhook.LastCapture = data
    if App.Webhook.Hourly and type(App.Webhook.Hourly.RecordResult) == "function" then
        pcall(App.Webhook.Hourly.RecordResult, data)
    end

    App.Values.WebhookStatus =
        "Sending result"

    App.Webhook.ResultDispatchPending = true

    task.spawn(function()
        local buildOk, payload = pcall(App.Webhook.BuildPayload, data)
        if not buildOk then
            dedupe[accountKey] = nil
            App.Webhook.ResultDispatchPending = false
            App.Values.WebhookStatus = "Payload build failed • " .. tostring(payload)
            return
        end

        local ok, message = false, "Webhook failed"

        for attempt = 1, 3 do
            App.Values.WebhookStatus =
                "Sending result • "
                .. tostring(attempt)
                .. "/3"

            ok, message = App.Webhook.Post(payload)

            if ok then
                break
            end

            if attempt < 3 then
                task.wait(0.75 * attempt)
            end
        end

        if ok then
            dedupe[accountKey] = {State = "sent", At = os.clock()}
            App.Values.WebhookStatus = "Sent"
        else


            dedupe[accountKey] = nil
            App.Values.WebhookStatus =
                tostring(message or "Webhook failed")
        end

        App.Webhook.ResultDispatchPending = false
    end)

    return true
end

App.Webhook.WaitForResultDispatch = function(timeoutSeconds)
    local timeout = math.clamp(tonumber(timeoutSeconds) or 3.5, 0, 8)
    local started = os.clock()
    while App.Webhook.ResultDispatchPending == true
        and os.clock() - started < timeout do
        task.wait(0.05)
    end
    return App.Webhook.ResultDispatchPending ~= true
end

App.Webhook.SendTest = function()
    if not App.Webhook.ValidURL(App.Values.WebhookURL) then
        App.Values.WebhookStatus =
            "Enter a valid Discord webhook URL"
        return false, App.Values.WebhookStatus
    end

    local account =
        App.Webhook.ReadAccountFresh
        and App.Webhook.ReadAccountFresh()
        or App.Webhook.ReadAccount()

    local sessionStart =
        type(App.Webhook.SessionStart) == "table"
        and App.Webhook.SessionStart
        or {}

    local function deltaText(current, start)
        local currentNumber = tonumber(current)
        local startNumber = tonumber(start)

        if currentNumber == nil or startNumber == nil then
            return "—"
        end

        local value = currentNumber - startNumber

        return (
            value > 0
            and "+"
            or ""
        ) .. App.Webhook.FormatNumber(value)
    end

    local accountText = {}

    if account.Prestige ~= nil then
        accountText[#accountText + 1] =
            "P" .. tostring(account.Prestige)
    end

    if account.Level ~= nil then
        accountText[#accountText + 1] =
            "LV" .. tostring(account.Level)
    end

    if account.Slot ~= nil then
        accountText[#accountText + 1] =
            "Slot " .. tostring(account.Slot)
    end

    local fields = {
        {
            name = "ACCOUNT",
            value =
                #accountText > 0
                and (
                    "**"
                    .. table.concat(accountText, " • ")
                    .. "**"
                )
                or "Unavailable",
            inline = false,
        },
        {
            name = "GOLD",
            value =
                account.Gold ~= nil
                and (
                    "**"
                    .. App.Webhook.FormatNumber(account.Gold)
                    .. "**\n▲ "
                    .. deltaText(
                        account.Gold,
                        sessionStart.Gold
                    )
                    .. " session"
                )
                or "Unavailable",
            inline = true,
        },
        {
            name = "GEMS",
            value =
                account.Gems ~= nil
                and (
                    "**"
                    .. App.Webhook.FormatNumber(account.Gems)
                    .. "**\n▲ "
                    .. deltaText(
                        account.Gems,
                        sessionStart.Gems
                    )
                    .. " session"
                )
                or "Unavailable",
            inline = true,
        },
        {
            name = "ACTIVE BOOSTS",
            value = App.Webhook.ActiveBoostsText(),
            inline = false,
        },
        {
            name = "TRANSPORT",
            value = "Live `Data / Copy` snapshot ready",
            inline = false,
        },
    }

    local shadowban = App.Shadowban.Snapshot()
    if App.Shadowban.IsVerified(shadowban.Status) then
        fields[#fields + 1] = {
            name = "SAFETY",
            value = "**" .. tostring(shadowban.Status) .. "**",
            inline = false,
        }
    end

    local payload = {
        username = "SliceHub",
        allowed_mentions = {parse = {}},
        embeds = {{
            title = "SLICEHUB // WEBHOOK TEST",
            description = App.Values.WebhookShowUsername ~= false
                and ("**@" .. tostring(player.Name) .. "**  •  live account transport")
                or "Live account transport",
            color = 3066993,
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            fields = fields,
            footer = {
                text = "SliceHub • AOT:R",
            },
        }},
    }

    App.Values.WebhookStatus = "Sending test"

    local ok, message =
        App.Webhook.Post(payload)

    App.Values.WebhookStatus =
        ok
        and tostring(message or "Test sent")
        or tostring(message or "Test failed")

    return ok, App.Values.WebhookStatus
end


-- V15.6.37: Atlas-style V2 periodic dashboard image reports.
-- V15.6.38: dedicated dashboard webhook destination with Main Webhook fallback.
App.Webhook.Hourly = App.Webhook.Hourly or {
    RenderURL = "",
    Busy = false,
    LastSampleAt = 0,
}

App.Webhook.Hourly.Ensure = function()
    local data = App.RunState and (App.RunState.Data or App.RunState.Load()) or nil
    if type(data) ~= "table" then return nil, nil end

    data.Hourly = type(data.Hourly) == "table" and data.Hourly or {}
    local h = data.Hourly
    h.PeriodStart = tonumber(h.PeriodStart) or os.time()
    h.BaseCompleted = math.max(0, tonumber(h.BaseCompleted) or tonumber(data.Completed) or 0)
    h.BaseFailed = math.max(0, tonumber(h.BaseFailed) or tonumber(data.Failed) or 0)
    h.BaseTimedRuns = math.max(0, tonumber(h.BaseTimedRuns) or tonumber(data.TimedRuns) or 0)
    h.BaseRunSeconds = math.max(0, tonumber(h.BaseRunSeconds) or tonumber(data.TotalCompletionSeconds) or 0)
    h.BaseGold = math.max(0, tonumber(h.BaseGold) or tonumber(data.SessionRewardGold) or 0)
    h.BaseGems = math.max(0, tonumber(h.BaseGems) or tonumber(data.SessionRewardGems) or 0)
    h.BaseXP = math.max(0, tonumber(h.BaseXP) or tonumber(data.SessionRewardXP) or 0)
    h.BaseRecoveries = math.max(0, tonumber(h.BaseRecoveries) or tonumber(data.Recoveries) or 0)
    h.Samples = type(h.Samples) == "table" and h.Samples or {}
    h.Activity = type(h.Activity) == "table" and h.Activity or {}
    h.Modes = type(h.Modes) == "table" and h.Modes or {}
    h.Rarities = type(h.Rarities) == "table" and h.Rarities or {Mythic=0,Legendary=0,Epic=0}
    h.Kills = math.max(0, tonumber(h.Kills) or 0)
    h.BestStreak = math.max(0, tonumber(h.BestStreak) or 0)
    h.BestDropRank = math.max(0, tonumber(h.BestDropRank) or 0)
    h.Reconnects = math.max(0, tonumber(h.Reconnects) or 0)
    h.Failsafes = math.max(0, tonumber(h.Failsafes) or 0)
    h.LastAttemptAt = tonumber(h.LastAttemptAt) or 0
    return data, h
end

App.Webhook.Hourly.ModeKey = function(run)
    run = type(run) == "table" and run or {}
    if tostring(run.Type) == "Waves" then return "Waves" end

    local raid = string.lower(tostring(run.Raid or ""))
    local objective = string.lower(tostring(run.Objective or ""))
    local map = tostring(run.Map or "")

    if string.find(raid, "col", 1, true)
        or string.find(objective, "colossal", 1, true) then
        return "Colossal"
    end

    if map == "Shiganshina" then return "Shiganshina" end
    if map ~= "" and map ~= "Unknown" then return map end
    return tostring(run.Type or "Other")
end

App.Webhook.Hourly.RecordResult = function(data)
    local state, h = App.Webhook.Hourly.Ensure()
    if not h or type(data) ~= "table" then return end

    local mode = App.Webhook.Hourly.ModeKey(data.Run)
    h.Modes[mode] = math.max(0, tonumber(h.Modes[mode]) or 0) + 1
    h.Activity[#h.Activity + 1] = {At=os.time(), Mode=mode}
    while #h.Activity > 120 do table.remove(h.Activity, 1) end

    local rewards = type(data.Rewards) == "table" and data.Rewards or {}
    local stats = type(rewards.Stats) == "table" and rewards.Stats or {}
    h.Kills = math.max(0, tonumber(h.Kills) or 0) + math.max(0, tonumber(stats.Kills) or 0)
    h.BestStreak = math.max(
        math.max(0, tonumber(h.BestStreak) or 0),
        math.max(0, tonumber(data.Streak) or 0)
    )

    local seconds = tonumber(data.CompletionSeconds)
    if seconds and seconds > 0 then
        h.BestRunSeconds = h.BestRunSeconds == nil
            and seconds
            or math.min(tonumber(h.BestRunSeconds) or seconds, seconds)
    end

    local rank = {Common=1,Rare=2,Epic=3,Legendary=4,Mythic=5,Mythical=5}
    for _, item in ipairs(type(rewards.Items) == "table" and rewards.Items or {}) do
        local rarity = tostring(item.Rarity or "")
        local normalized = rarity == "Mythical" and "Mythic" or rarity
        local quantity = math.max(1, math.floor((tonumber(item.Quantity) or 1) + 0.5))

        if normalized == "Mythic" or normalized == "Legendary" or normalized == "Epic" then
            h.Rarities[normalized] = math.max(0, tonumber(h.Rarities[normalized]) or 0) + quantity
        end

        local currentRank = tonumber(rank[rarity] or rank[normalized] or 0) or 0
        if currentRank > (tonumber(h.BestDropRank) or 0) then
            h.BestDropRank = currentRank
            h.BestDrop = tostring(item.Name or "Unknown")
                .. (rarity ~= "" and (" • " .. rarity) or "")
        end
    end

    pcall(App.RunState.Save)
end

App.Webhook.Hourly.Sample = function(force)
    local state, h = App.Webhook.Hourly.Ensure()
    if not h then return false end

    local now = os.time()
    if force ~= true
        and now - (tonumber(App.Webhook.Hourly.LastSampleAt) or 0) < 55 then
        return false
    end

    App.Webhook.Hourly.LastSampleAt = now

    local mode = "Other"
    if App.Webhook.LastCapture and type(App.Webhook.LastCapture.Run) == "table" then
        mode = App.Webhook.Hourly.ModeKey(App.Webhook.LastCapture.Run)
    elseif App.AFKManager and type(App.AFKManager.ModeText) == "function" then
        mode = tostring(App.AFKManager.ModeText() or "Other")
    end

    h.Samples[#h.Samples + 1] = {
        At = now,
        Gold = math.max(0, (tonumber(state.SessionRewardGold) or 0) - (tonumber(h.BaseGold) or 0)),
        Completed = math.max(0, (tonumber(state.Completed) or 0) - (tonumber(h.BaseCompleted) or 0)),
        Mode = mode,
    }

    while #h.Samples > 90 do table.remove(h.Samples, 1) end
    pcall(App.RunState.Save)
    return true
end

App.Webhook.Hourly.BuildReport = function()
    local state, h = App.Webhook.Hourly.Ensure()
    if not h then return nil end

    App.Webhook.Hourly.Sample(true)

    local completed = math.max(0, (tonumber(state.Completed) or 0) - (tonumber(h.BaseCompleted) or 0))
    local failed = math.max(0, (tonumber(state.Failed) or 0) - (tonumber(h.BaseFailed) or 0))
    local timed = math.max(0, (tonumber(state.TimedRuns) or 0) - (tonumber(h.BaseTimedRuns) or 0))
    local runSeconds = math.max(0, (tonumber(state.TotalCompletionSeconds) or 0) - (tonumber(h.BaseRunSeconds) or 0))
    local average = timed > 0 and runSeconds / timed or 0

    local goldSeries, missionSeries = {}, {}
    local previous = nil

    for _, sample in ipairs(h.Samples) do
        if previous then
            local dt = math.max(1, (tonumber(sample.At) or 0) - (tonumber(previous.At) or 0))
            local dg = math.max(0, (tonumber(sample.Gold) or 0) - (tonumber(previous.Gold) or 0))
            local dm = math.max(0, (tonumber(sample.Completed) or 0) - (tonumber(previous.Completed) or 0))
            goldSeries[#goldSeries + 1] = dg * 60 / dt
            missionSeries[#missionSeries + 1] = dm * 60 / dt
        end
        previous = sample
    end

    if #goldSeries == 0 then goldSeries[1] = 0 end
    if #missionSeries == 0 then missionSeries[1] = 0 end

    local activity = {}
    for _, event in ipairs(h.Activity) do
        activity[#activity + 1] = {
            at = tonumber(event.At) or os.time(),
            mode = App.Webhook.Hourly.ModeKey({Type=event.Mode, Map=event.Mode, Raid=event.Mode, Objective=event.Mode}),
        }
    end

    local reconnects = math.max(0, tonumber(h.Reconnects) or 0)
    local failsafes = math.max(0, tonumber(h.Failsafes) or 0)
    local recoveries = math.max(0, (tonumber(state.Recoveries) or 0) - (tonumber(h.BaseRecoveries) or 0))

    return {
        intervalHours = math.clamp(math.floor((tonumber(App.Values.WebhookHourlyIntervalHours) or 1) + 0.5), 1, 12),
        gold = math.max(0, (tonumber(state.SessionRewardGold) or 0) - (tonumber(h.BaseGold) or 0)),
        gems = math.max(0, (tonumber(state.SessionRewardGems) or 0) - (tonumber(h.BaseGems) or 0)),
        xp = math.max(0, (tonumber(state.SessionRewardXP) or 0) - (tonumber(h.BaseXP) or 0)),
        completed = completed,
        failed = failed,
        avgRun = average,
        bestRun = tonumber(h.BestRunSeconds) or 0,
        kills = math.max(0, tonumber(h.Kills) or 0),
        bestStreak = math.max(0, tonumber(h.BestStreak) or 0),
        reconnects = reconnects,
        failsafes = failsafes,
        recoveries = recoveries,
        modes = h.Modes,
        rarities = h.Rarities,
        bestDrop = tostring(h.BestDrop or "None"),
        goldSeries = goldSeries,
        missionSeries = missionSeries,
        activity = activity,
        show = {
            gold = App.Values.WebhookHourlyShowGold ~= false,
            missions = App.Values.WebhookHourlyShowMissions ~= false,
            activity = App.Values.WebhookHourlyShowActivity ~= false,
            summary = App.Values.WebhookHourlyShowSummary ~= false,
            modes = App.Values.WebhookHourlyShowModes ~= false,
            session = App.Values.WebhookHourlyShowSession ~= false,
            drops = App.Values.WebhookHourlyShowDrops ~= false,
            bestDrop = App.Values.WebhookHourlyShowBestDrop ~= false,
            stability = App.Values.WebhookHourlyShowStability ~= false,
        },
    }
end

App.Webhook.Hourly.Render = function(report)
    local body = HttpService:JSONEncode(report)
    local failures = {}

    for _, candidate in ipairs(App.Webhook.RequestFunctions()) do
        local ok, response = pcall(candidate.Fn, {
            Url = App.Webhook.Hourly.RenderURL,
            URL = App.Webhook.Hourly.RenderURL,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["Accept"] = "image/png",
            },
            Body = body,
        })

        if ok then
            local status = type(response) == "table"
                and tonumber(response.StatusCode or response.Status or response.status_code)
                or nil
            local responseBody = type(response) == "table"
                and (response.Body or response.body or response.Response or response.response)
                or response

            if type(responseBody) == "string"
                and string.sub(responseBody, 1, 8) == "\137PNG\r\n\26\n"
                and (status == nil or (status >= 200 and status < 300)) then
                return responseBody, "Rendered • " .. candidate.Name
            end
        end

        failures[#failures + 1] = tostring(candidate.Name)
    end

    return nil, "Dashboard renderer unavailable • " .. table.concat(failures, ", ")
end

App.Webhook.Hourly.DestinationURL = function()
    local dedicated = App.Webhook.Trim(App.Values.WebhookHourlyURL)
    if dedicated ~= "" then
        if App.Webhook.ValidURL(dedicated) then
            return dedicated, "Dedicated dashboard webhook"
        end
        return nil, "Dashboard webhook URL is invalid"
    end

    local fallback = App.Webhook.Trim(App.Values.WebhookURL)
    if App.Webhook.ValidURL(fallback) then
        return fallback, "Main webhook fallback"
    end

    return nil, "Enter a Dashboard Webhook URL or configure the Main Webhook"
end

App.Webhook.PostImage = function(png, report, destinationURL)
    local url = App.Webhook.Trim(destinationURL or App.Values.WebhookURL)
    if not App.Webhook.ValidURL(url) then return false, "Invalid Discord webhook URL" end
    if type(png) ~= "string" or string.sub(png, 1, 8) ~= "\137PNG\r\n\26\n" then
        return false, "Invalid dashboard PNG"
    end

    local boundary = "SliceHubBoundary" .. tostring(os.time()) .. tostring(math.random(100000,999999))
    local payload = {
        username = "SliceHub",
        allowed_mentions = {parse = {}},
        attachments = {{
            id = 0,
            filename = "slicehub-hourly-report.png",
            description = "SliceHub V2 periodic dashboard report",
        }},
    }

    local payloadJson = HttpService:JSONEncode(payload)
    local crlf = "\r\n"
    local parts = {
        "--" .. boundary .. crlf,
        'Content-Disposition: form-data; name="payload_json"' .. crlf,
        "Content-Type: application/json" .. crlf .. crlf,
        payloadJson .. crlf,
        "--" .. boundary .. crlf,
        'Content-Disposition: form-data; name="files[0]"; filename="slicehub-hourly-report.png"' .. crlf,
        "Content-Type: image/png" .. crlf .. crlf,
        png .. crlf,
        "--" .. boundary .. "--" .. crlf,
    }
    local multipart = table.concat(parts)

    local failures = {}
    for _, candidate in ipairs(App.Webhook.RequestFunctions()) do
        local ok, response = pcall(candidate.Fn, {
            Url = url,
            URL = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "multipart/form-data; boundary=" .. boundary,
            },
            Body = multipart,
        })

        if ok then
            if type(response) ~= "table" then return true, "Dashboard sent • " .. candidate.Name end
            local status = tonumber(response.StatusCode or response.Status or response.status_code)
            if response.Success == true or (status and status >= 200 and status < 300) then
                return true, "Dashboard sent • " .. candidate.Name
            end
            failures[#failures + 1] = candidate.Name .. " HTTP " .. tostring(status or "unknown")
        else
            failures[#failures + 1] = candidate.Name .. " failed"
        end
    end

    return false, #failures > 0 and table.concat(failures, " | ") or "No multipart request method"
end

App.Webhook.Hourly.ResetPeriod = function()
    local state, h = App.Webhook.Hourly.Ensure()
    if not h then return false end

    h.PeriodStart = os.time()
    h.BaseCompleted = math.max(0, tonumber(state.Completed) or 0)
    h.BaseFailed = math.max(0, tonumber(state.Failed) or 0)
    h.BaseTimedRuns = math.max(0, tonumber(state.TimedRuns) or 0)
    h.BaseRunSeconds = math.max(0, tonumber(state.TotalCompletionSeconds) or 0)
    h.BaseGold = math.max(0, tonumber(state.SessionRewardGold) or 0)
    h.BaseGems = math.max(0, tonumber(state.SessionRewardGems) or 0)
    h.BaseXP = math.max(0, tonumber(state.SessionRewardXP) or 0)
    h.BaseRecoveries = math.max(0, tonumber(state.Recoveries) or 0)
    h.Samples = {}
    h.Activity = {}
    h.Modes = {}
    h.Rarities = {Mythic=0, Legendary=0, Epic=0}
    h.BestDrop = nil
    h.BestDropRank = 0
    h.Kills = 0
    h.BestStreak = 0
    h.BestRunSeconds = nil
    h.Reconnects = 0
    h.Failsafes = 0
    h.LastAttemptAt = 0
    pcall(App.RunState.Save)
    return true
end

App.Webhook.Hourly.Send = function(isTest)
    if App.Webhook.Hourly.Busy then return false, "Hourly report already sending" end

    local destinationURL, destinationMode = App.Webhook.Hourly.DestinationURL()
    if not destinationURL then
        return false, tostring(destinationMode or "Dashboard webhook unavailable")
    end

    App.Webhook.Hourly.Busy = true
    App.Values.WebhookHourlyStatus = isTest and "Rendering test" or "Rendering dashboard"

    local report = App.Webhook.Hourly.BuildReport()
    if not report then
        App.Webhook.Hourly.Busy = false
        App.Values.WebhookHourlyStatus = "No session data"
        return false, App.Values.WebhookHourlyStatus
    end

    local okRender, png, renderMessage = pcall(App.Webhook.Hourly.Render, report)
    if not okRender then
        renderMessage = tostring(png)
        png = nil
    end

    if not png then
        App.Webhook.Hourly.Busy = false
        App.Values.WebhookHourlyStatus = tostring(renderMessage or "Dashboard render failed")
        return false, App.Values.WebhookHourlyStatus
    end

    App.Values.WebhookHourlyStatus = "Sending image"
    local ok, message = App.Webhook.PostImage(png, report, destinationURL)
    if ok then message = tostring(message or "Dashboard sent") .. " • " .. tostring(destinationMode or "Webhook") end
    App.Webhook.Hourly.Busy = false
    App.Values.WebhookHourlyStatus = ok and tostring(message or "Dashboard sent") or tostring(message or "Dashboard failed")

    if ok and isTest ~= true then
        App.Webhook.Hourly.ResetPeriod()
    end

    return ok, App.Values.WebhookHourlyStatus
end


-- WEBHOOK VAULT R1: render + deliver the dashboard server-side. The client no
-- longer receives a PNG and therefore never needs the real Discord destination.
App.Webhook.Hourly.DestinationURL = function()
    local dedicated = App.Webhook.Trim(App.Values.WebhookHourlyURL)
    if dedicated ~= "" then
        if App.Webhook.ValidURL(dedicated) then
            return dedicated, "Dedicated dashboard webhook"
        end
        return nil, "Dashboard webhook URL is invalid"
    end

    local fallback = App.Webhook.Trim(App.Values.WebhookURL)
    if App.Webhook.ValidURL(fallback) then
        return fallback, "Main webhook fallback"
    end
    return nil, "Enter a Dashboard Webhook URL or configure the Main Webhook"
end

App.Webhook.Hourly.Send = function(isTest)
    if App.Webhook.Hourly.Busy then return false, "Hourly report already sending" end

    local destination, destinationMode = App.Webhook.Hourly.DestinationURL()
    if not destination then
        return false, tostring(destinationMode or "Dashboard webhook unavailable")
    end

    App.Webhook.Hourly.Busy = true
    App.Values.WebhookHourlyStatus = isTest and "Sending test" or "Sending dashboard"

    local report = App.Webhook.Hourly.BuildReport()
    if not report then
        App.Webhook.Hourly.Busy = false
        App.Values.WebhookHourlyStatus = "No session data"
        return false, App.Values.WebhookHourlyStatus
    end

    local purpose = destinationMode == "Dedicated dashboard webhook" and "hourly" or "main"
    local okVault, handle, vaultMessage = App.Webhook.EnsureVault(destination, purpose)
    if not okVault then
        App.Webhook.Hourly.Busy = false
        App.Values.WebhookHourlyStatus = tostring(vaultMessage or "Webhook vault unavailable")
        return false, App.Values.WebhookHourlyStatus
    end

    local ok, _, message = App.Webhook.VaultRequest("send-hourly", {
        handle = handle,
        report = report,
    })
    App.Webhook.Hourly.Busy = false
    App.Values.WebhookHourlyStatus = ok
        and ("Dashboard sent • " .. tostring(destinationMode or "Webhook"))
        or tostring(message or "Dashboard failed")

    if ok and isTest ~= true then App.Webhook.Hourly.ResetPeriod() end
    return ok, App.Values.WebhookHourlyStatus
end

-- OFFLINE BUILD: Discord is contacted directly; SliceBot webhook vault/renderer
-- endpoints are never used. Account identifiers are scrubbed from outbound text.
App.Webhook.EnsureVault = function(value)
    local url = App.Webhook.Trim(value)
    if App.Webhook.IsDiscordURL(url) then return true, url, "Direct Discord webhook" end
    return false, nil, "Invalid Discord webhook URL"
end

App.Webhook.VaultRequest = function()
    return false, nil, "Offline build: relay disabled"
end

App.Webhook.SanitizePayload = function(value)
    local ownName = tostring(player.Name or "")
    local ownDisplayName = tostring(player.DisplayName or "")
    local ownId = tostring(player.UserId or "")
    local function scrub(item)
        if type(item) == "string" then
            -- if ownName ~= "" then item = item:gsub(ownName, "[redacted]") end
            -- if ownDisplayName ~= "" then item = item:gsub(ownDisplayName, "[redacted]") end
            -- if ownId ~= "" then item = item:gsub(ownId, "[redacted]") end
            return item
        end
        if type(item) == "table" then
            local clean = {}
            for key, nested in pairs(item) do clean[scrub(key)] = scrub(nested) end
            return clean
        end
        return item
    end
    return scrub(value)
end

App.Webhook.Post = function(payload)
    local url = App.Webhook.Trim(App.Values.WebhookURL)
    if not App.Webhook.IsDiscordURL(url) then return false, "Invalid Discord webhook URL" end
    local okEncode, body = pcall(HttpService.JSONEncode, HttpService, App.Webhook.SanitizePayload(payload))
    if not okEncode then return false, "Webhook JSON encode failed" end
    local failures = {}
    for _, candidate in ipairs(App.Webhook.RequestFunctions()) do
        local ok, response = pcall(candidate.Fn, {Url=url, URL=url, Method="POST", Headers={["Content-Type"]="application/json"}, Body=body})
        if ok then
            if type(response) ~= "table" then return true, "Sent • " .. candidate.Name end
            local status = tonumber(response.StatusCode or response.Status or response.status_code)
            if response.Success == true or (status and status >= 200 and status < 300) then
                return true, "Sent • " .. candidate.Name
            end
            failures[#failures + 1] = candidate.Name .. " HTTP " .. tostring(status or "unknown")
        else
            failures[#failures + 1] = candidate.Name .. " failed"
        end
    end
    return false, #failures > 0 and table.concat(failures, " | ") or "No supported HTTP request method"
end

-- The old image dashboard required a remote renderer. Keep periodic reports
-- working as native Discord embeds instead of sending report data elsewhere.
App.Webhook.Hourly.Send = function(isTest)
    if App.Webhook.Hourly.Busy then return false, "Hourly report already sending" end
    if not App.Webhook.IsDiscordURL(App.Webhook.Trim(App.Values.WebhookHourlyURL)) then
        App.Values.WebhookHourlyURL = App.Values.WebhookURL
    end
    App.Webhook.Hourly.Busy = true
    local report = App.Webhook.Hourly.BuildReport()
    if not report then App.Webhook.Hourly.Busy=false return false, "No session data" end
    local payload = {username="SliceHub", allowed_mentions={parse={}}, embeds={{
        title="SLICEHUB // PERIODIC REPORT",
        color=10181046,
        fields={
            {name="Completed", value=tostring(report.completed or 0), inline=true},
            {name="Failed", value=tostring(report.failed or 0), inline=true},
            {name="Gold", value=tostring(report.gold or 0), inline=true},
            {name="Best drop", value=tostring(report.bestDrop or "None"), inline=false},
        },
        footer={text="Offline dashboard • no renderer or relay"},
        timestamp=os.date("!%Y-%m-%dT%H:%M:%SZ"),
    }}}
    local savedURL = App.Values.WebhookURL
    App.Values.WebhookURL = App.Webhook.Trim(App.Values.WebhookHourlyURL)
    local ok, message = App.Webhook.Post(payload)
    App.Values.WebhookURL = savedURL
    App.Webhook.Hourly.Busy = false
    App.Values.WebhookHourlyStatus = ok and "Dashboard sent • Direct Discord" or tostring(message)
    if ok and isTest ~= true then App.Webhook.Hourly.ResetPeriod() end
    return ok, App.Values.WebhookHourlyStatus
end

