task.spawn(function()
    task.wait(3)
    App.Webhook.Hourly.Sample(true)

    while true do
        task.wait(30)

        if App.Values.WebhookHourlyEnabled == true then
            App.Webhook.Hourly.Sample(false)

            local _, h = App.Webhook.Hourly.Ensure()
            if h then
                local interval = math.clamp(
                    math.floor((tonumber(App.Values.WebhookHourlyIntervalHours) or 1) + 0.5),
                    1,
                    12
                ) * 3600
                local now = os.time()

                if now - (tonumber(h.PeriodStart) or now) >= interval
                    and now - (tonumber(h.LastAttemptAt) or 0) >= 300
                    and App.Webhook.Hourly.Busy ~= true then
                    h.LastAttemptAt = now
                    pcall(App.RunState.Save)
                    task.spawn(function()
                        App.Webhook.Hourly.Send(false)
                    end)
                end
            end
        end
    end
end)


