App.AFKManager = App.AFKManager or {
    NeedsAttention = false,
    LastAttention = "None",
    LastAttentionAt = 0,
    LastAlertReason = "",
    LastAlertAt = 0,
    LimitHandled = false,
}

App.AFKManager.Data = function()
    local data = App.RunState and (App.RunState.Data or App.RunState.Load()) or nil
    if type(data) ~= "table" then return nil end
    data.Completed = math.max(0, math.floor((tonumber(data.Completed) or 0) + 0.5))
    data.Failed = math.max(0, math.floor((tonumber(data.Failed) or 0) + 0.5))
    data.Recoveries = math.max(0, math.floor((tonumber(data.Recoveries) or 0) + 0.5))
    data.SessionStartedUnix = tonumber(data.SessionStartedUnix) or 0
    if data.SessionStartedUnix <= 0 then
        data.SessionStartedUnix = os.time()
        if App.RunState then pcall(App.RunState.Save) end
    end
    return data
end

App.AFKManager.FormatDuration = function(seconds)
    seconds = math.max(0, math.floor((tonumber(seconds) or 0) + 0.5))
    local hours = math.floor(seconds / 3600)
    local minutes = math.floor((seconds % 3600) / 60)
    local secs = seconds % 60
    if hours > 0 then return string.format("%dh %02dm", hours, minutes) end
    if minutes > 0 then return string.format("%dm %02ds", minutes, secs) end
    return tostring(secs) .. "s"
end

App.AFKManager.ModeText = function()
    if RuntimeKind == "MainMenu" then return "Main Menu" end
    if RuntimeKind == "Lobby" then return "Lobby" end

    local waves = workspace:FindFirstChild("Waves")
    local unclimbable = workspace:FindFirstChild("Unclimbable")
    local objective = unclimbable and unclimbable:FindFirstChild("Objective")
    if waves and objective and objective:FindFirstChild("Waves") then
        return "Waves"
    end

    if App.FreeRaidGuard and App.FreeRaidGuard.IsRaid and App.FreeRaidGuard.IsRaid() then return "Raid" end
    return "Mission"
end

App.AFKManager.AutomationActive = function()
    if App.Failsafe and type(App.Failsafe.AutomationActive) == "function" then
        local ok, active = pcall(App.Failsafe.AutomationActive)
        if ok then return active == true end
    end
    if RuntimeKind == "Lobby" then return App.Values.LobbyAutoLaunch == true end
    if RuntimeKind == "MainMenu" then return App.Values.MainAutoSelectSlot == true end
    return App.Values.AutoFarmBlades == true
        or App.Values.AutoFarmSpears == true
        or (App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true)
        or App.Values.WavesAutoFarm == true
        or App.Values.AutoTSDoQuests == true
end

App.AFKManager.StatusText = function()
    if App.AFKManager.NeedsAttention == true then return "NEEDS ATTENTION" end
    if App.Failsafe and App.Failsafe.Triggering == true then return "RECOVERING" end
    if App.Failsafe and App.Values.FailsafeSmart == true then
        local smart = tostring(App.Failsafe.SmartState or "Idle")
        if smart ~= "Idle" and smart ~= "Healthy" then return "RECOVERING" end
    end
    if not App.AFKManager.AutomationActive() then return "WAITING" end
    return "STABLE"
end

App.AFKManager.StatusKind = function()
    local status = App.AFKManager.StatusText()
    if status == "STABLE" then return "good" end
    if status == "NEEDS ATTENTION" then return "failed" end
    return "waiting"
end

App.AFKManager.SessionText = function()
    local data = App.AFKManager.Data()
    local started = data and tonumber(data.SessionStartedUnix) or os.time()
    return App.AFKManager.FormatDuration(math.max(0, os.time() - started))
end

App.AFKManager.ProgressText = function()
    local data = App.AFKManager.Data()
    local count = data and math.max(0, math.floor((tonumber(data.Count) or 0) + 0.5)) or 0
    local limit = math.clamp(math.floor((tonumber(App.Values.MissionLimit) or 0) + 0.5), 0, 250)
    return tostring(count) .. " / " .. (limit > 0 and tostring(limit) or "Unlimited")
end

App.AFKManager.CompletedText = function()
    local data = App.AFKManager.Data()
    return tostring(data and data.Completed or 0)
end

App.AFKManager.FailedText = function()
    local data = App.AFKManager.Data()
    return tostring(data and data.Failed or 0)
end

App.AFKManager.RecoveriesText = function()
    local data = App.AFKManager.Data()
