end

App.AFKManager.ValidPingUserId = function(value)
    if App.Webhook and type(App.Webhook.ValidPingUserId) == "function" then
        local ok, result = pcall(App.Webhook.ValidPingUserId, value)
        if ok then return result end
    end
    local text = string.gsub(tostring(value or ""), "%D", "")
    return (#text >= 15 and #text <= 22) and text or nil
end

