App.AFKManager.LastAttentionText = function()
    local data = App.AFKManager.Data()
    local text = tostring((data and data.LastAttention) or App.AFKManager.LastAttention or "None")
    if text == "" then text = "None" end
    local at = tonumber((data and data.LastAttentionAt) or App.AFKManager.LastAttentionAt) or 0
    if text ~= "None" and at > 0 then text = text .. " • " .. os.date("%H:%M", at) end
    return text
end

App.AFKManager.SendAlert = function(reason, kind, force)
    reason = tostring(reason or "Please check this account.")
    kind = tostring(kind or "attention")
    if not App.Webhook or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        return false, "Set a valid Results webhook first"
    end

    local now = os.time()
    if force ~= true
        and tostring(App.AFKManager.LastAlertReason or "") == reason
        and now - (tonumber(App.AFKManager.LastAlertAt) or 0) < 600 then
        return false, "Duplicate alert suppressed"
    end

    local title = kind == "finish" and "✅ SLICEHUB — FARM FINISHED"
        or (kind == "test" and "🧪 SLICEHUB — AFK TEST" or "⚠️ SLICEHUB — ATTENTION NEEDED")
    local status = kind == "finish" and "Finished"
        or (kind == "test" and "Test" or "Needs attention")

    local suppressPing = (kind == "finish" and App.Values.WebhookNoPingFarmFinished == true)
        or (kind == "attention" and App.Values.WebhookNoPingAttention == true)
    local pingUserId = App.Values.AFKPingUser == true and not suppressPing
        and App.AFKManager.ValidPingUserId(App.Values.WebhookPingUserId)
        or nil

    local alertFields = {}
    if App.Values.WebhookShowUsername ~= false then
        alertFields[#alertFields + 1] = {name = "Account", value = tostring(player.Name), inline = true}
    end
    alertFields[#alertFields + 1] = {name = "Status", value = status, inline = true}
    alertFields[#alertFields + 1] = {name = "Mode", value = App.AFKManager.ModeText(), inline = true}
    alertFields[#alertFields + 1] = {name = "Session", value = App.AFKManager.SessionText(), inline = true}

    local payload = {
        content = pingUserId and ("<@" .. pingUserId .. ">") or nil,
        allowed_mentions = pingUserId and {parse = {}, users = {pingUserId}} or {parse = {}},
        embeds = {{
            title = title,
            description = reason,
            color = kind == "attention" and 15158332 or (kind == "finish" and 3066993 or 3447003),
            fields = alertFields,
            footer = {text = "SliceHub V15.6 • AFK Manager"},
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }},
    }

    local ok, message = App.Webhook.Post(payload)
    if ok then
        App.AFKManager.LastAlertReason = reason
        App.AFKManager.LastAlertAt = now
    end
    return ok, message
end


App.AFKManager.SendSessionRecap = function(reason)
    reason = tostring(reason or "Session finished")
    if not App.Webhook or App.Values.WebhookEnabled ~= true or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        return false, "Results webhook is off"
    end
    local data = App.RunState and (App.RunState.Data or App.RunState.Load()) or {}
    local account = App.Webhook.ReadAccountFresh and App.Webhook.ReadAccountFresh() or App.Webhook.ReadAccount()
    local started = tonumber(data.SessionStartedUnix) or os.time()
    local runtimeSeconds = math.max(0, os.time() - started)
    local timedRuns = math.max(0, tonumber(data.TimedRuns) or 0)
    local totalRunSeconds = math.max(0, tonumber(data.TotalCompletionSeconds) or 0)
    local average = timedRuns > 0 and App.RunState.FormatDuration(totalRunSeconds / timedRuns) or "—"
    local startWallet = type(App.Webhook.SessionStart) == "table" and App.Webhook.SessionStart or {}
    local function delta(nowValue, oldValue)
        if tonumber(nowValue) == nil or tonumber(oldValue) == nil then return "—" end
        local n = tonumber(nowValue) - tonumber(oldValue)
        return (n >= 0 and "+" or "") .. App.Webhook.FormatNumber(n)
    end
    local fields = {
        {name="END REASON", value="**" .. reason .. "**", inline=false},
        {name="RUNTIME", value="**" .. App.RunState.FormatDuration(runtimeSeconds) .. "**", inline=true},
        {name="RUNS", value="**" .. tostring(tonumber(data.Count) or 0) .. "**", inline=true},
        {name="AVG RUN", value="**" .. average .. "**", inline=true},
        {name="COMPLETED", value="**" .. tostring(tonumber(data.Completed) or 0) .. "**", inline=true},
        {name="FAILED", value="**" .. tostring(tonumber(data.Failed) or 0) .. "**", inline=true},
        {name="MODE", value="**" .. App.AFKManager.ModeText() .. "**", inline=true},
    }
    local sessionGold = tonumber(data.SessionRewardGold)
    local sessionGems = tonumber(data.SessionRewardGems)
    if sessionGold ~= nil then
        fields[#fields+1] = {name="GOLD SESSION", value="**+" .. App.Webhook.FormatNumber(sessionGold) .. "**", inline=true}
    elseif account and account.Gold ~= nil then
        fields[#fields+1] = {name="GOLD SESSION", value="**" .. delta(account.Gold, startWallet.Gold) .. "**", inline=true}
    end
    if sessionGems ~= nil then
        fields[#fields+1] = {name="GEMS SESSION", value="**+" .. App.Webhook.FormatNumber(sessionGems) .. "**", inline=true}
    elseif account and account.Gems ~= nil then
        fields[#fields+1] = {name="GEMS SESSION", value="**" .. delta(account.Gems, startWallet.Gems) .. "**", inline=true}
    end
    return App.Webhook.Post({
        allowed_mentions={parse={}},
        embeds={{
            title="✅ SLICEHUB — SESSION RECAP",
            description=App.Values.WebhookShowUsername ~= false
                and ("**" .. tostring(player.Name) .. "** finished an automation session.")
                or "Automation session finished.",
            color=3066993,
            fields=fields,
            footer={text="SliceHub V15.6.32 • Session Recap"},
            timestamp=os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }},
    })
end

App.AFKManager.MarkAttention = function(reason)
    reason = tostring(reason or "Automation could not continue")
    App.AFKManager.NeedsAttention = true
    App.AFKManager.LastAttention = reason
    App.AFKManager.LastAttentionAt = os.time()
    local data = App.AFKManager.Data()
    if data then
        data.LastAttention = reason
        data.LastAttentionAt = App.AFKManager.LastAttentionAt
        if App.RunState then pcall(App.RunState.Save) end
    end
    if App.Values.AFKAttentionAlerts == true then
        task.spawn(function() pcall(App.AFKManager.SendAlert, reason, "attention", false) end)
    end
end

App.AFKManager.StopAutomation = function()
    App.Values.MissionAutoRetry = false
    App.Values.RaidRetry = false
    App.Values.AutoFarmBlades = false
    App.Values.AutoFarmSpears = false
    App.Values.WavesAutoFarm = false
    App.Values.WavesAutoSkip = false
    App.Values.WavesAutoCrates = false
    App.Values.WavesAutoUpgrade = false
    App.Values.AutoTSDoQuests = false
    App.Values.AutoTSLaunchNext = false
    App.Values.LobbyAutoLaunch = false
    -- V15.6.34: Auto Select Slot is a saved user preference, not session state.
    -- AFK/failsafe shutdown may stop active farming, but must never poison the
    -- next reconnect by saving MainAutoSelectSlot=false behind the user's back.
    if V12Config and type(V12Config.ScheduleSave) == "function" then V12Config.ScheduleSave(0.10) end
end

App.AFKManager.ReturnMainMenu = function()
    App.AFKManager.StopAutomation()
    App.TeleportTrace.Record("AFK_MAIN_MENU", "AFK Manager • returning to Main Menu")
    local ok, err = pcall(function()
        TeleportService:Teleport(13379208636, player)
    end)
    if not ok then
        App.AFKManager.MarkAttention("Recovery could not complete")
        return false, tostring(err)
    end
    return true, "Returning to Main Menu"
end

App.AFKManager.HandleLimit = function(reason)
    if App.AFKManager.LimitHandled == true then return false end
    App.AFKManager.LimitHandled = true
    reason = tostring(reason or "AFK limit reached")
    pcall(App.AFKManager.SendSessionRecap, reason)
    App.AFKManager.StopAutomation()

    local action = tostring(App.Values.AFKEndAction or "Return to Lobby")
    if action == "Return to Main Menu" then
        task.delay(0.35, function() App.AFKManager.ReturnMainMenu() end)
        return true
    end

    if action == "Return to Lobby" and type(App.AFKManager.ReturnToLobby) == "function" then
        task.delay(0.35, function()
            local ok = App.AFKManager.ReturnToLobby()
            if ok ~= true then App.AFKManager.MarkAttention("Automation could not continue") end
        end)
        return true
    end

    return true
end

App.AFKManager.ResetSession = function()
    local data = App.AFKManager.Data()
    if not data then return false end
    data.Count = 0
    data.Completed = 0
    data.Failed = 0
    data.Recoveries = 0
    data.LastResult = "None"
    data.LastCompletionSeconds = nil
    data.TotalCompletionSeconds = 0
    data.TimedRuns = 0
    data.SessionRewardGold = 0
    data.SessionRewardGems = 0
    data.SessionRewardXP = 0
    data.LastRewardCountedRunId = 0
    data.SessionStartedUnix = os.time()
    data.LastAttention = "None"
    data.LastAttentionAt = 0
    data.PendingResetOnLobby = false
    App.Values.MissionRunCount = 0
    App.Values.MissionLastResult = "None"
    App.AFKManager.NeedsAttention = false
    App.AFKManager.LastAttention = "None"
    App.AFKManager.LastAttentionAt = 0
    App.AFKManager.LimitHandled = false
    if App.RunState then pcall(App.RunState.Save) end
    return true
end


