local NAV = RuntimeKind == "MainMenu"
    and {
        {Group="MAIN MENU", Pages={"Auto", "Player", "Config"}},
    }
    or (RuntimeKind == "Lobby"
        and {
            {Group="LOBBY", Pages={"Launch", "Automation", "Perks", "Webhooks", "Auto Thunder Spears"}},
            {Group="SYSTEM", Pages={"Optimization", "Settings"}},
        }
        or {
            {Group="FARMING", Pages={"Missions", "Raids", "Waves", "Auto Thunder Spears"}},
            {Group="SYSTEM", Pages={"Farm", "Results", "Optimization", "Settings"}},
        })

do
    local __defaultPages = {}
    local __defaultOrder = {}
    for _, group in ipairs(NAV) do
        for _, pageName in ipairs(group.Pages or {}) do
            if not __defaultPages[pageName] then
                __defaultPages[pageName] = true
                __defaultOrder[#__defaultOrder + 1] = pageName
            end
        end
    end

    function App.ApplyTabPreferences()
        App.RefreshGuiPreferences()
        local prefs = App.GuiPreferences or {}
        local layouts = type(prefs.layouts) == "table" and prefs.layouts or {}
        local runtimeName =
            RuntimeKind == "MainMenu" and "Main Menu"
            or (RuntimeKind == "Lobby" and "Lobby" or "Mission")
        local layout = layouts[runtimeName]
        if type(layout) ~= "table"
            or type(layout.tabOrder) ~= "table"
            or type(layout.tabs) ~= "table" then
            return false
        end

        local ordered = {}
        local seen = {}
        for _, tabId in ipairs(layout.tabOrder) do
            local tab = layout.tabs[tabId]
            local pageName = type(tab) == "table" and tostring(tab.name or "") or ""
            if __defaultPages[pageName] and not seen[pageName] then
                ordered[#ordered + 1] = pageName
                seen[pageName] = true
            end
        end

        for _, pageName in ipairs(__defaultOrder) do
            if not seen[pageName] then
                ordered[#ordered + 1] = pageName
                seen[pageName] = true
            end
        end

        if #ordered > 0 then
            NAV = {{
                Group =
                    RuntimeKind == "MainMenu" and "MAIN MENU"
                    or (RuntimeKind == "Lobby" and "LOBBY" or "MISSION"),
                Pages = ordered,
            }}
            return true
        end

        return false
    end

    App.ApplyTabPreferences()
end

