-- V15.6.34: Boosted Maps returns as a routing layer, not a second launcher.
-- Default Launch remains untouched and is copied live whenever the current 2X
-- map is blacklisted/unconfigured/not detected. A valid boosted route only
-- overrides mission Map/Objectives/Difficulty/Modifiers for that one launch.
App.BoostedMaps = App.BoostedMaps or {
    LastDetectedMap = nil,
    LastDetectedSource = "",
    LastDetectedScore = 0,
    LastRefreshAt = 0,
    LastStatus = "Off",
    LastAction = "Default Launch",
}

App.BoostedMaps.RouteSlugs = {
    ["Shiganshina"] = "Shiganshina",
    ["Trost"] = "Trost",
    ["Outskirts"] = "Outskirts",
    ["Giant Forest"] = "GiantForest",
    ["Utgard Castle"] = "UtgardCastle",
    ["Loading Docks"] = "LoadingDocks",
    ["Stohess"] = "Stohess",
    ["Chapel"] = "Chapel",
}

App.BoostedMaps.ObjectiveOptions = function(mapName)
    local out = {"Auto"}
    for _, objective in ipairs(App.LobbyMissionData[tostring(mapName or "")] or {}) do
        if objective ~= "Random" then
            out[#out + 1] = objective
        end
    end
    return out
end

App.BoostedMaps.AutoObjective = function(mapName)
    local supported = App.LobbyMissionData[tostring(mapName or "")] or {}
    if table.find(supported, "Skirmish") then return "Skirmish" end
    for _, objective in ipairs(supported) do
        if objective ~= "Random" then return objective end
    end
    return supported[1] or "Skirmish"
end

App.BoostedMaps.RouteEnabled = function(mapName)
    local slug = App.BoostedMaps.RouteSlugs[tostring(mapName or "")]
    if not slug then return false end
    return App.Values["BoostedRoute" .. slug .. "Enabled"] ~= false
end

App.BoostedMaps.RouteObjective = function(mapName)
    local slug = App.BoostedMaps.RouteSlugs[tostring(mapName or "")]
    if not slug then return App.BoostedMaps.AutoObjective(mapName) end
    local selected = tostring(App.Values["BoostedRoute" .. slug .. "Objective"] or "Auto")
    local supported = App.LobbyMissionData[tostring(mapName or "")] or {}
    if selected ~= "Auto" and table.find(supported, selected) then
        return selected
    end
    return App.BoostedMaps.AutoObjective(mapName)
end

App.BoostedMaps.SelectedModifiers = function(mapName)
    if App.Values.BoostedModifiersEnabled ~= true then return {} end
    local slug = App.BoostedMaps.RouteSlugs[tostring(mapName or "")]
    if not slug or App.Values["BoostedRoute" .. slug .. "UseModifiers"] ~= true then
        return {}
    end
    local selected = {}
    for lobbyKey, name in pairs(App.LobbyModifierMap) do
        local boostedKey = string.gsub(tostring(lobbyKey), "^LobbyMod", "BoostedMod")
        if App.Values[boostedKey] == true then
            selected[#selected + 1] = name
        end
    end
    table.sort(selected)
    return selected
end

App.BoostedMaps.IsOwnGui = function(object)
    local cursor = object
    for _ = 1, 8 do
        cursor = cursor and cursor.Parent
        if not cursor then break end
        if string.find(string.lower(tostring(cursor.Name or "")), "slicehub", 1, true) then
            return true
        end
    end
    return false
end

App.BoostedMaps.Detect = function(force)
    if App.Values.AutoJoinBoostedMaps ~= true then
        App.BoostedMaps.LastDetectedMap = nil
        App.BoostedMaps.LastDetectedSource = ""
        App.BoostedMaps.LastDetectedScore = 0
        App.BoostedMaps.LastBoostedTimer = nil
        App.BoostedMaps.LastStatus = "Off"
        App.BoostedMaps.LastAction = "Default Launch"
        return nil
    end

    local now = os.clock()
    if force ~= true
        and now - (tonumber(App.BoostedMaps.LastRefreshAt) or 0) < 0.35 then
        return App.BoostedMaps.LastDetectedMap
    end
    App.BoostedMaps.LastRefreshAt = now

    local rawMap = nil
    local rawTimer = nil
    pcall(function()
        rawMap = workspace:GetAttribute("Boosted_Map")
        rawTimer = workspace:GetAttribute("Boosted_Timer")
    end)

    local clean = string.lower(tostring(rawMap or ""))
    clean = string.gsub(clean, "[_%-]+", " ")
    clean = string.gsub(clean, "%s+", " ")
    clean = string.gsub(clean, "^%s+", "")
    clean = string.gsub(clean, "%s+$", "")

    local aliases = {
        ["shiganshina"] = "Shiganshina",
        ["trost"] = "Trost",
        ["outskirts"] = "Outskirts",
        ["giant forest"] = "Giant Forest",
        ["forest"] = "Giant Forest",
        ["utgard"] = "Utgard Castle",
        ["utgard castle"] = "Utgard Castle",
        ["docks"] = "Loading Docks",
        ["loading docks"] = "Loading Docks",
        ["stohess"] = "Stohess",
        ["chapel"] = "Chapel",
    }

    local mapName = aliases[clean]
    local timer = tonumber(rawTimer)
    App.BoostedMaps.LastDetectedMap = mapName
    App.BoostedMaps.LastDetectedSource = rawMap ~= nil and "Workspace.Boosted_Map" or ""
    App.BoostedMaps.LastDetectedScore = mapName and 1000 or 0
    App.BoostedMaps.LastBoostedTimer = timer
    App.BoostedMaps.LastDiagnostic = rawMap ~= nil and tostring(rawMap) or "Boosted_Map missing"

    local timerText = ""
    if timer ~= nil and timer >= 0 then
        local seconds = math.max(0, math.floor(timer + 0.5))
        timerText = string.format(" • %02d:%02d", math.floor(seconds / 60), seconds % 60)
    end

    if not mapName then
        App.BoostedMaps.LastStatus = rawMap ~= nil
            and ("Unknown boosted map • " .. tostring(rawMap))
            or "Boosted map unavailable"
        App.BoostedMaps.LastAction = "Default Launch"
        return nil
    end

    if not App.BoostedMaps.RouteEnabled(mapName) then
        App.BoostedMaps.LastStatus = mapName .. " • 2X" .. timerText .. " • BLACKLISTED"
        App.BoostedMaps.LastAction = "Fallback → Default Launch"
    else
        App.BoostedMaps.LastStatus = mapName .. " • 2X" .. timerText
        App.BoostedMaps.LastAction = "Boosted → " .. App.BoostedMaps.RouteObjective(mapName)
    end

    return mapName
end

App.BoostedMaps.ResolveConfig = function(defaultConfig)
    if App.Values.AutoJoinBoostedMaps ~= true then
        return defaultConfig, "default"
    end

    local mapName = App.BoostedMaps.Detect(false)
    if not mapName or not App.BoostedMaps.RouteEnabled(mapName) then
        return defaultConfig, "default"
    end

    local objective = App.BoostedMaps.RouteObjective(mapName)
    local difficulty = tostring(App.Values.BoostedDifficulty or "Hardest")
    local config = {
        CreateMode = "Mission",
        Map = mapName,
        Objective = objective,
        Difficulty = difficulty,
        Modifiers = App.BoostedMaps.SelectedModifiers(mapName),
        BoostedRoute = true,
        BoostedSource = tostring(App.BoostedMaps.LastDetectedSource or "Detected"),
    }

    App.BoostedMaps.LastStatus = mapName .. " • 2X"
    App.BoostedMaps.LastAction = "Launching " .. mapName .. " • " .. objective
    return config, "boosted"
end

