App.FormatGoldMillions = function(value)
    value = tonumber(value) or 0
    if value >= 1000 then
        local billions = value / 1000
        return (billions % 1 == 0)
            and string.format("%.0fB", billions)
            or string.format("%.2fB", billions)
    end
    return string.format("%.0fM", value)
end

App.AutoTS = App.AutoTS or {
    Runtime = nil,
    LastStatus = "Initializing",
    Prestige = nil,
    Grade = nil,
    AberrantEligible = nil,
    AberrantProbeBusy = false,
    AberrantProbeAt = 0,
    LastPrestigeProbeAt = 0,
    LastClaimAt = 0,
    TerminalComplete = false,
}

App.AutoTS.IsEligible = function()
    local prestige = tonumber(App.AutoTS.Prestige)
    return prestige ~= nil
        and prestige >= 1
        and prestige <= 5
        and App.AutoTS.AberrantEligible == true
end

App.AutoTS.LockReason = function()
    if App.AutoTS.TerminalComplete == true then
        return "Complete • Thunder Spears unlocked"
    end

    local prestige = tonumber(App.AutoTS.Prestige)

    if prestige == nil then
        return "Scanning Prestige..."
    end

    if prestige <= 0 then
        return "Locked • Prestige 1+ required"
    end

    if App.AutoTS.AberrantEligible == nil then
        return "Scanning equipped gear grade..."
    end

    if App.AutoTS.AberrantEligible ~= true then
        return "Locked • A- / Aberrant gear required"
    end

    return "Ready • P"
        .. tostring(math.floor(prestige))
        .. " • "
        .. tostring(App.AutoTS.Grade or "A-")
        .. " gear"
end

App.AutoTS.GradeRank = {
    ["E-"] = 1, ["E"] = 2, ["E+"] = 3,
    ["D-"] = 4, ["D"] = 5, ["D+"] = 6,
    ["C-"] = 7, ["C"] = 8, ["C+"] = 9,
    ["B-"] = 10, ["B"] = 11, ["B+"] = 12,
    ["A-"] = 13, ["A"] = 14, ["A+"] = 15,
    ["S-"] = 16, ["S"] = 17, ["S+"] = 18,
}

App.AutoTS.ParseGradeText = function(raw)
    local value = string.upper(tostring(raw or ""))

    local grade =
        string.match(
            value,
            "UPGRADES%s*%[%s*([^%]]-)%s+GRADE%s*%]"
        )

    if not grade then
        grade =
            string.match(
                value,
                "%f[%a]([EDCBAS][%+%-]?)%s+GRADE%f[%A]"
            )
    end

    if not grade then
        return nil
    end

    grade = string.gsub(grade, "^%s+", "")
    grade = string.gsub(grade, "%s+$", "")

    return App.AutoTS.GradeRank[grade]
        and grade
        or nil
end

App.AutoTS.ReadNativeGrade = function()
    local interface = playerGui:FindFirstChild("Interface")
    local equipment = interface and interface:FindFirstChild("Equipment")
    local categories = equipment and equipment:FindFirstChild("Categories")
    local upgrades = categories and categories:FindFirstChild("Upgrades")
    local main = upgrades and upgrades:FindFirstChild("Main")
    local title = main and main:FindFirstChild("Title")

    if title
        and (
            title:IsA("TextLabel")
            or title:IsA("TextButton")
            or title:IsA("TextBox")
        ) then
        local grade =
            App.AutoTS.ParseGradeText(title.Text)

        if grade then
            return grade
        end
    end

    local checked = 0

    for _, object in ipairs(playerGui:GetDescendants()) do
        checked += 1

        if checked > 2500 then
            break
        end

        if not object:IsDescendantOf(gui)
            and (
                object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox")
            ) then
            local grade =
                App.AutoTS.ParseGradeText(object.Text)

            if grade then
                return grade
            end
        end
    end

    return nil
end

App.AutoTS.LastEquipmentPrimeAt = 0

App.AutoTS.PrimeNativeEquipmentGrade = function()
    if RuntimeKind ~= "Lobby" then return nil end
    local now = os.clock()
    if now - (tonumber(App.AutoTS.LastEquipmentPrimeAt) or 0) < 4.0 then
        return App.AutoTS.ReadNativeGrade()
    end
    App.AutoTS.LastEquipmentPrimeAt = now

    local interface = playerGui:FindFirstChild("Interface")
    local topbar = interface and interface:FindFirstChild("Topbar")
    local main = topbar and topbar:FindFirstChild("Main")
    local categories = main and main:FindFirstChild("Categories")
    local equipmentCategory = categories and categories:FindFirstChild("Equipment")
    local equipmentButton = equipmentCategory and equipmentCategory:FindFirstChild("Interact", true)
    if not equipmentButton or not equipmentButton:IsA("GuiButton") then
        return App.AutoTS.ReadNativeGrade()
    end


    local restoreButton = nil
    if categories and interface then
        for _, category in ipairs(categories:GetChildren()) do
            if category ~= equipmentCategory then
                local page = interface:FindFirstChild(category.Name)
                if page and page:IsA("GuiObject") and page.Visible then
                    local candidate = category:FindFirstChild("Interact", true)
                    if candidate and candidate:IsA("GuiButton") then
                        restoreButton = candidate
                        break
                    end
                end
            end
        end
    end

    pcall(function() equipmentButton:Activate() end)
    task.wait(0.14)
    local grade = App.AutoTS.ReadNativeGrade()

    if restoreButton then
        task.defer(function()
            task.wait(0.03)
            pcall(function() restoreButton:Activate() end)
        end)
    end

    return grade
end

App.AutoTS.RefreshLobbyEligibility = function(force)
    if RuntimeKind ~= "Lobby" then
        return false
    end

    local now = os.clock()

    if force ~= true
        and now - (
            tonumber(App.AutoTS.LastPrestigeProbeAt)
            or 0
        ) < 1.5 then
        return App.AutoTS.IsEligible()
    end

    App.AutoTS.LastPrestigeProbeAt = now

    if App.Prestige
        and type(App.Prestige.GetProfile) == "function"
        and type(App.Prestige.ParseProfile) == "function" then

        local profile =
            App.Prestige.GetProfile()

        local prestige =
            App.Prestige.ParseProfile(profile)

        if tonumber(prestige) ~= nil then
            App.AutoTS.Prestige =
                tonumber(prestige)
        end
    end

    local prestige =
        tonumber(App.AutoTS.Prestige)

    if prestige ~= nil
        and prestige <= 0 then

        App.AutoTS.Grade = nil
        App.AutoTS.AberrantEligible = false
        App.AutoTS.LastStatus =
            "P0 detected • Thunder Spear quests unavailable"

        return false
    end

    if prestige ~= nil
        and prestige >= 1 then

        local grade =
            App.AutoTS.ReadNativeGrade()

        if not grade then
            grade = App.AutoTS.PrimeNativeEquipmentGrade()
        end

        App.AutoTS.Grade = grade

        local rank =
            grade
            and App.AutoTS.GradeRank[grade]
            or nil

        App.AutoTS.AberrantEligible =
            rank ~= nil
            and rank >= App.AutoTS.GradeRank["A-"]

        App.AutoTS.LastStatus =
            App.AutoTS.AberrantEligible
            and (
                "Eligibility ready • P"
                .. tostring(math.floor(prestige))
                .. " • "
                .. tostring(grade)
            )
            or (
                grade
                and (
                    "Locked • "
                    .. tostring(grade)
                    .. " gear • A- required"
                )
                or "Scanning equipped gear grade"
            )
    end

    return App.AutoTS.IsEligible()
end

App.AutoTS.StageText = function()
    local prestige = tonumber(App.AutoTS.Prestige)

    if prestige ~= nil and prestige <= 0 then
        return "Unavailable at Prestige 0"
    end

    local runtime = App.AutoTS.Runtime
    local scan = runtime and runtime.CurrentScan or nil
    if not scan then return "Waiting for TS quest data" end
    if scan.Completed then return "Thunder Spears questline complete" end
    if scan.PendingReward and scan.PendingReward.Definition then
        return "Claim: " .. tostring(scan.PendingReward.Definition.Name)
    end
    if scan.Route and scan.Route.Definition then
        return "Next: " .. tostring(scan.Route.Definition.Name)
    end
    return "Scanning next TS quest"
end

App.AutoTS.ProgressText = function()
    local prestige = tonumber(App.AutoTS.Prestige)

    if prestige ~= nil and prestige <= 0 then
        return "No Thunder Spear questline at P0"
    end

    local runtime = App.AutoTS.Runtime
    local scan = runtime and runtime.CurrentScan or nil
    if not scan or type(scan.States) ~= "table" then return "—" end
    local order = {4,5,1,2,3}
    local chunks = {}
    for _, index in ipairs(order) do
        local state = scan.States[index]
        if state and state.Definition then
            local symbol = state.Status == "complete" and "✓"
                or state.Status == "reward_pending" and "!"
                or state.Status == "active" and ">"
                or state.Status == "locked" and "L"
                or "?"
            chunks[#chunks+1] = symbol .. " "
                .. tostring(state.Definition.Short or state.Definition.Name)
                .. " " .. tostring(state.Current or 0)
                .. "/" .. tostring(state.Amount or 0)
        end
    end
    return table.concat(chunks, "  •  ")
end

