}

App.FamilySpin = App.FamilySpin or {
    Running = false,
    Serial = 0,
    Rolls = 0,
    Status = "Idle",
    CurrentFamily = "Unknown",
    CurrentRarity = "Unknown",
    SkipRollOwned = false,
    SkipRollStatus = "Checking",
    SkipRollGamePassId = nil,
    LastDelay = nil,
    StartedAt = 0,
}

App.FamilySpin.IsPremium = function()

    return true
end

App.FamilySpin.TierText = function()
    return App.FamilySpin.IsPremium() and "Premium" or "Free"
end

App.FamilySpin.TargetSummary = function()
    if App.Values.FamilyTargetMode == "Families" then
        local selected = {}
        for _, name in ipairs({
            "Arlert","Zoe","Tybur","Leonhart","Galliard","Finger","Braun","Ksaver",
            "Ackerman","Yeager","Reiss","Fritz","Helos",
        }) do
            if App.Values["FamilyTarget" .. name] == true then
                selected[#selected + 1] = name
            end
        end
        return #selected > 0 and table.concat(selected, ", ") or "None"
    end

    local selected = {}
    if App.Values.FamilyTargetEpic then selected[#selected + 1] = "Epic" end
    if App.Values.FamilyTargetLegendary then selected[#selected + 1] = "Legendary" end
    if App.Values.FamilyTargetMythic then selected[#selected + 1] = "Mythic" end
    return #selected > 0 and table.concat(selected, " + ") or "None"
end

