    Safety = {
        Subtitle = "Movement safety, native-input Blade farming, and streak controls.",
        Sections = {
            {"MOVEMENT", {
                {Type="segments", Name="Hover Method", Desc="Regular rises to safe height first, then moves horizontally. Teleport snaps directly to the safe hover point.", Key="MovementMode", Options={"Regular","Teleport"}, Rebuild=true},
                {Type="slider", Name="Regular Speed", Desc="Regular hover travel speed.", Key="SmoothSpeed", Min=100, Max=1200, Step=50, OnlyWhen={Key="MovementMode", Value="Regular"}},
                {Type="sliderbox", Name="Wait Before Final Titan", Desc="0 disables it. Waits only when one required Titan remains. Breach Phase 1 and Defend HQ waves 1–4 never wait; Breach becomes eligible only after Defend HQ reaches 5/5.", Key="FarmSafetyDelay", Min=0, Max=150, Step=1,
                    Format=function(value)
                        value = math.max(0, math.floor((tonumber(value) or 0) + 0.5))
                        if value == 0 then return "0s • Off" end
                        if value >= 60 then
                            return string.format("%dm %02ds", math.floor(value / 60), value % 60)
                        end
                        return tostring(value) .. "s"
                    end},
            }},
            {"SAFE FARM", {
                {Type="toggle", Name="Safe Farm", Desc="Blades only • movement stays Regular/Teleport. At each kill pack SliceHub briefly fires 1–2 ground-hook visuals, plays a Blade swing, then synchronizes the existing Multi-Hit Slash/Register kill. No Q/E/Mouse1 input spam.", Key="SafeFarm"},
                {Type="live", Name="Safe Farm Status", ValueFunction=function()
                    return App.SafeFarm
                        and tostring(App.SafeFarm.LastStatus or "Idle")
                        or "Idle"
                end},
                {Type="live", Name="Final Titan Timer", ValueFunction=function()
                    return App.Safety
                        and tostring(App.Safety.FinalTitanStatus or "Ready")
                        or "Ready"
                end},
            }},
            {"PARTY SAFETY", {
                {Type="toggle", Name="Leave If Another Player Is In Mission", Desc="Solo protection. If any Player other than you loads into the mission, SliceHub immediately returns to Town Central.", Key="LeaveIfAnotherPlayer"},
                {Type="live", Name="Party Safety Status", ValueFunction=function()
                    return App.Safety
                        and tostring(App.Safety.PlayerSafetyStatus or "Off")
                        or "Off"
                end},
            }},
            {"STREAK", {
                {Type="live", Name="Current Streak", ValueFunction=function()
                    local value = player:GetAttribute("Streak")
                    if tonumber(value) == nil then return "Unavailable" end
                    return App.Webhook.FormatNumber(value)
                end},
                {Type="toggle", Name="Auto Die at Streak", Desc="Arms at the configured streak. The threshold/re-arm logic is active; the actual AOT:R defeat action stays fail-closed until a confirmed method is plugged in.", Key="AutoDieAtStreak", Rebuild=true},
                {Type="sliderbox", Name="Streak Limit", Desc="Trigger threshold for Auto Die. Slider and number box share the same value.", Key="AutoDieStreak", Min=10000, Max=1000000, Step=1000,
                    Format=function(value)
                        return App.Webhook.FormatNumber(value)
                    end,
                    OnlyWhen={Key="AutoDieAtStreak", Value=true}},
                {Type="live", Name="Auto Die Status", ValueFunction=function()
                    return App.Safety
                        and tostring(App.Safety.Status or "Off")
                        or "Off"
                end},
            }},
        }
    },

