do
    local function slug(value)
        local text = string.lower(tostring(value or ""))
        text = string.gsub(text, "[^%w]+", "_")
        text = string.gsub(text, "^_+", "")
        text = string.gsub(text, "_+$", "")
        return text ~= "" and text or "item"
    end

    local function assignIds(definitions, tabId, counters)
        for _, def in ipairs(definitions or {}) do
            if type(def) == "table" and def.Name ~= nil then
                if def.__NewGenPreferenceId == nil then
                    local base = slug(def.Name)
                    counters[base] = (counters[base] or 0) + 1
                    local id = tostring(tabId) .. "__" .. base
                    if counters[base] > 1 then
                        id = id .. "__" .. tostring(counters[base])
                    end
                    def.__NewGenPreferenceId = id
                end

                if type(def.Children) == "table" then
                    assignIds(def.Children, tabId, counters)
                end
            end
        end
    end

    local function sortChildren(definitions, rank)
        table.sort(definitions, function(a, b)
            local ar = rank[tostring(a.__NewGenPreferenceId or "")] or math.huge
            local br = rank[tostring(b.__NewGenPreferenceId or "")] or math.huge
            if ar == br then
                return tostring(a.__NewGenPreferenceId or a.Name or "")
                    < tostring(b.__NewGenPreferenceId or b.Name or "")
            end
            return ar < br
        end)

        for _, def in ipairs(definitions) do
            if type(def.Children) == "table" and def.__NewGenPreserveChildOrder ~= true then
                sortChildren(def.Children, rank)
            end
        end
    end

    -- R6 GUI HOTFIX: preserve the real section structure. Saved GUI
    -- preferences may reorder controls inside a section, but must never
    -- flatten a whole page into one giant "YOUR LAYOUT" section.
    local function sortPageSections(pageNames, tabId, tabPreference)
        if type(tabPreference) ~= "table"
            or type(tabPreference.functionOrder) ~= "table" then
            return
        end

        local rank = {}
        for index, id in ipairs(tabPreference.functionOrder) do
            rank[tostring(id)] = index
        end

        for _, pageName in ipairs(pageNames) do
            local info = PageInfo[pageName]
            if type(info) == "table" and type(info.Sections) == "table" then
                local counters = {}

                for _, sectionDef in ipairs(info.Sections) do
                    local definitions = sectionDef[2] or {}
                    assignIds(definitions, tabId, counters)
                    sortChildren(definitions, rank)
                end
            end
        end
    end

    function App.ApplyFunctionPreferences()
        App.RefreshGuiPreferences()
        local prefs = App.GuiPreferences or {}
        local layouts = type(prefs.layouts) == "table" and prefs.layouts or {}
        local runtimeName =
            RuntimeKind == "MainMenu" and "Main Menu"
            or (RuntimeKind == "Lobby" and "Lobby" or "Mission")
        local layout = layouts[runtimeName]
        if type(layout) ~= "table" or type(layout.tabs) ~= "table" then
            return false
        end

        for tabId, tabPreference in pairs(layout.tabs) do
            local pageName = tostring(tabPreference.name or "")
            if tabId == "farm" and RuntimeKind == "Gameplay" then
                sortPageSections({"Combat", "Safety"}, "farm", tabPreference)
            elseif PageInfo[pageName] then
                sortPageSections({pageName}, tostring(tabId), tabPreference)
            end
        end

        return true
    end

    App.ApplyFunctionPreferences()
end

