local function corner(object, r)
    local x = Instance.new("UICorner")
    x.CornerRadius = UDim.new(0, r or 7)
    x.Parent = object
end

local function stroke(object, transparency)
    local x = Instance.new("UIStroke")
    x.Color = C.Stroke
    x.Transparency = transparency == nil and 0.5 or transparency
    x.Thickness = 1
    x.Parent = object
end

local function label(parentObject, text, size, position, textSize, color, font)
    local x = Instance.new("TextLabel")
    x.BackgroundTransparency = 1
    x.Text = text or ""
    x.Size = size or UDim2.new(1,0,0,20)
    x.Position = position or UDim2.new()
    x.Font = font or Enum.Font.Gotham
    x.TextSize = textSize or 10
    x.TextColor3 = color or C.Text
    x.TextXAlignment = Enum.TextXAlignment.Left
    x.TextYAlignment = Enum.TextYAlignment.Center
    x.TextWrapped = true
    x.Parent = parentObject
    return x
end

local function button(parentObject, text, size, position)
    local b = Instance.new("TextButton")
    b.AutoButtonColor = false
    b.Text = text
    b.Size = size
    b.Position = position or UDim2.new()
    b.BackgroundColor3 = C.Surface2
    b.BorderSizePixel = 0
    b.TextColor3 = C.Text
    b.Font = Enum.Font.GothamMedium
    b.TextSize = 10
    b.Parent = parentObject
    corner(b, 6)
    stroke(b, 0.65)

    local hoverScale = Instance.new("UIScale")
    hoverScale.Scale = 1
    hoverScale.Parent = b

    b.MouseEnter:Connect(function()
        TweenService:Create(
            hoverScale,
            TweenInfo.new(0.11, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
            {Scale = 1.025}
        ):Play()
    end)

    b.MouseLeave:Connect(function()
        TweenService:Create(
            hoverScale,
            TweenInfo.new(0.11, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
            {Scale = 1}
        ):Play()
    end)

    return b
end

