-- V14.5 R4: register a real runtime shutdown hook so future re-executes
-- terminate this instance before another SliceHub runtime is created.
do
    local runtimeEnv =
        (type(getgenv) == "function" and getgenv())
        or _G

    runtimeEnv.__SliceHubActiveShutdown = function()
        pcall(function()
            if App.PerformanceControl
                and App.PerformanceControl.Apply3D then
                App.Values.Disable3DRendering = false
                App.PerformanceControl.Apply3D(false)
            end
        end)

        pcall(function()
            if App.RestoreMapProps then
                App.RestoreMapProps()
            end
        end)

        pcall(function()
            if App.RuntimeHealth
                and App.RuntimeHealth.Cleanup then
                App.RuntimeHealth.Cleanup()
            end
        end)

        pcall(function()
            if gui and gui.Parent then
                gui:Destroy()
            end
        end)
    end
end


App.UnloadCompletely = function(reason)
    reason = tostring(reason or "User unloaded SliceHub")
    pcall(function()
        if App.AFKManager and App.AFKManager.SendSessionRecap then App.AFKManager.SendSessionRecap(reason) end
    end)
    for _, key in ipairs({
        "MainAutoSelectSlot","LobbyAutoLaunch","MissionAutoRetry","RaidRetry","AutoFarmBlades","AutoFarmSpears",
        "WavesAutoFarm","WavesAutoSkip","WavesAutoCrates","WavesAutoUpgrade","AutoTSDoQuests","AutoTSLaunchNext",
        "AutoClaimAchievements","AutoBuySpins","AutoBuyBoosts","AutoUseBoost","AutoOpenCrates","AutoUpgradeEnabled",
        "AutoPrestigeEnabled","FamilySpinEnabled","MultiGrindEnabled"
    }) do
        if App.Values[key] ~= nil then App.Values[key] = false end
    end
    pcall(function() if App.FamilySpin and App.FamilySpin.Stop then App.FamilySpin.Stop("SliceHub unloaded") end end)
    pcall(function() if App.PerformanceControl and App.PerformanceControl.Apply3D then App.Values.Disable3DRendering=false; App.PerformanceControl.Apply3D(false) end end)
    pcall(function() if App.RestoreMapProps then App.RestoreMapProps() end end)
    pcall(function() if App.RuntimeHealth and App.RuntimeHealth.Cleanup then App.RuntimeHealth.Cleanup() end end)
    pcall(function() if App.PerformanceControl and App.PerformanceControl.Overlay then App.PerformanceControl.Overlay:Destroy() end end)
    local env = (type(getgenv) == "function" and getgenv()) or _G
    if type(env) == "table" then
        env.__SliceHubActiveShutdown = nil
        env.__SliceHubMultiGrindRuntime = nil
    end
    pcall(function() if gui and gui.Parent then gui:Destroy() end end)
    return true
end

