App.DensityScaleTarget = function()
    if App.Mobile and App.Mobile.Compact then
        return 1
    end
    return tostring(App.Values.Density or "Compact") == "Comfortable" and 1.075 or 1
end

App.SetHidden = function(hidden, animated)
    hidden = hidden == true
    App.Hidden = hidden

    if hidden then
        if animated ~= false then
            local uiScale = shell:FindFirstChildOfClass("UIScale")
            if uiScale then
                TweenService:Create(
                    uiScale,
                    TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    {Scale = App.DensityScaleTarget() * 0.97}
                ):Play()
                task.wait(0.12)
            end
        end
        if shell and shell.Parent then shell.Visible = false end
    else
        if shell and shell.Parent then
            shell.Visible = true
            local uiScale = shell:FindFirstChildOfClass("UIScale")
            if uiScale then
                uiScale.Scale = App.DensityScaleTarget() * 0.97
                TweenService:Create(
                    uiScale,
                    TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                    {Scale = App.DensityScaleTarget()}
                ):Play()
            end
        end
    end

    if App.RefreshMobileReopenButton then
        task.defer(App.RefreshMobileReopenButton)
    end
end

