App.MobileToggleDrag = App.MobileToggleDrag or {
    Dragging = false,
    Input = nil,
    StartInput = nil,
    StartCenter = nil,
    Moved = false,
    UserMoved = false,
}

App.ClampMobileTogglePosition = function(x, y)
    local camera = workspace.CurrentCamera
    local viewportSize = camera and camera.ViewportSize or Vector2.new(1280, 720)
    return Vector2.new(
        math.clamp(math.floor((tonumber(x) or viewportSize.X - 28) + 0.5), 24, math.max(24, viewportSize.X - 24)),
        math.clamp(math.floor((tonumber(y) or viewportSize.Y * 0.5) + 0.5), 24, math.max(24, viewportSize.Y - 24))
    )
end

App.RefreshMobileReopenButton = function()
    local button = App.MobileReopenButton
    if not button or not button.Parent then return end

    local compact = (App.Mobile and App.Mobile.Compact) or UserInputService.TouchEnabled
    button.Visible = compact == true
    if not compact then return end

    local camera = workspace.CurrentCamera
    local viewportSize = camera and camera.ViewportSize or Vector2.new(1280, 720)

    if App.MobileToggleDrag.UserMoved ~= true then
        button.Position = UDim2.fromOffset(
            math.max(24, viewportSize.X - 28),
            math.floor(viewportSize.Y * 0.5 + 0.5)
        )
        return
    end

    local center = button.AbsolutePosition + (button.AbsoluteSize / 2)
    local clamped = App.ClampMobileTogglePosition(center.X, center.Y)
    button.Position = UDim2.fromOffset(clamped.X, clamped.Y)
end

App.MobileReopenButton.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.Touch
        and input.UserInputType ~= Enum.UserInputType.MouseButton1 then
        return
    end

    App.MobileToggleDrag.Dragging = true
    App.MobileToggleDrag.Input = input
    App.MobileToggleDrag.StartInput = input.Position
    App.MobileToggleDrag.StartCenter =
        App.MobileReopenButton.AbsolutePosition
        + (App.MobileReopenButton.AbsoluteSize / 2)
    App.MobileToggleDrag.Moved = false

    input.Changed:Connect(function()
        if input.UserInputState == Enum.UserInputState.End then
            App.MobileToggleDrag.Dragging = false
            App.MobileToggleDrag.Input = nil
            task.defer(function()
                App.MobileToggleDrag.Moved = false
            end)
        end
    end)
end)

UserInputService.InputChanged:Connect(function(input)
    if App.MobileToggleDrag.Dragging ~= true
        or not App.MobileToggleDrag.StartInput
        or not App.MobileToggleDrag.StartCenter then
        return
    end

    local tracked = App.MobileToggleDrag.Input
    local validTouch = input.UserInputType == Enum.UserInputType.Touch and input == tracked
    local validMouse = input.UserInputType == Enum.UserInputType.MouseMovement
    if not validTouch and not validMouse then return end

    local delta = input.Position - App.MobileToggleDrag.StartInput
    if delta.Magnitude >= 5 then
        App.MobileToggleDrag.Moved = true
        App.MobileToggleDrag.UserMoved = true
    end

    local target = App.ClampMobileTogglePosition(
        App.MobileToggleDrag.StartCenter.X + delta.X,
        App.MobileToggleDrag.StartCenter.Y + delta.Y
    )
    App.MobileReopenButton.Position = UDim2.fromOffset(target.X, target.Y)
end)

App.MobileReopenButton.Activated:Connect(function()
    if App.MobileToggleDrag.Moved == true then return end
    App.SetHidden(not App.Hidden, true)
end)

