}

-- V14.5 R2 PERFORMANCE SCHEDULER
-- Non-critical controllers back off while the SliceHub UI is hidden/minimized
-- or 3D rendering is disabled. Combat timing remains fast while actively farming.
App.PerformanceControl.IsLowPower = function()
    return App.Values.Disable3DRendering == true
        or App.Hidden == true
        or (MacState and MacState.Minimized == true)
end

App.PerformanceControl.Delay = function(foreground, lowPower)
    local normal = math.max(0.01, tonumber(foreground) or 0.10)
    local reduced = math.max(normal, tonumber(lowPower) or normal)
    return App.PerformanceControl.IsLowPower()
        and reduced
        or normal
end

App.PerformanceControl.FpsFunctions = function()
    local env = v12Environment()
    local setter = (env and env.setfpscap) or (type(setfpscap) == "function" and setfpscap or nil)
    local getter = (env and env.getfpscap) or (type(getfpscap) == "function" and getfpscap or nil)
    return setter, getter
end

App.PerformanceControl.ApplyFPSCap = function()
    App.Values.FPSCap = math.clamp(
        math.floor((tonumber(App.Values.FPSCap) or 60) + 0.5),
        1,
        600
    )

    local setter, getter = App.PerformanceControl.FpsFunctions()
    if type(setter) ~= "function" then
        App.PerformanceControl.LastFPSStatus = "Unsupported by executor"
        if App.Values.FPSCapEnabled == true then
            App.Values.FPSCapEnabled = false
        end
        return false, "setfpscap unavailable"
    end

    if App.Values.FPSCapEnabled == true then
        if App.PerformanceControl.OriginalFPSCap == nil and type(getter) == "function" then
            local okGet, current = pcall(getter)
            if okGet and tonumber(current) then
                App.PerformanceControl.OriginalFPSCap = tonumber(current)
            end
        end

        if App.Values.FPSUnlimited == true then
            local okUnlimited, unlimitedErr = pcall(setter, 0)
            if okUnlimited then
                App.PerformanceControl.FpsTouched = true
                App.PerformanceControl.LastFPSStatus = "Unlimited requested"
                return true
            end
            App.Values.FPSUnlimited = false
            App.PerformanceControl.LastFPSStatus = "Unlimited unsupported • using numeric cap"
        end

        local target = App.Values.FPSCap
        local ok, err = pcall(setter, target)
        if ok then App.PerformanceControl.FpsTouched = true end
        App.PerformanceControl.LastFPSStatus = ok
            and (tostring(target) .. " FPS")
            or ("Failed: " .. tostring(err))
        return ok, err
    end


    if App.PerformanceControl.FpsTouched ~= true then
        App.PerformanceControl.LastFPSStatus = "Off"
        return true
    end

    local restoreTarget = tonumber(App.PerformanceControl.OriginalFPSCap) or 600
    local ok, err = pcall(setter, restoreTarget)
    if ok then App.PerformanceControl.FpsTouched = false end
    App.PerformanceControl.LastFPSStatus = ok and "Off" or ("Failed: " .. tostring(err))
    return ok, err
end

App.PerformanceControl.EnsureOverlay = function()
    local overlay = App.PerformanceControl.Overlay
    if overlay and overlay.Parent then
        return overlay
    end

    overlay = Instance.new("ScreenGui")
    overlay.Name = "SliceHubRenderSleep"
    overlay.ResetOnSpawn = false
    overlay.IgnoreGuiInset = true
    overlay.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    overlay.DisplayOrder = 999
    overlay.Enabled = false
    overlay.Parent = parent

    local frame = Instance.new("Frame")
    frame.Size = UDim2.fromScale(1, 1)
    frame.BackgroundColor3 = App.Values.RenderOverlayColor or C.Surface
    frame.BorderSizePixel = 0
    frame.Parent = overlay

    local title = label(
        frame,
        "SLICEHUB • 3D RENDERING OFF",
        UDim2.new(1, -40, 0, 28),
        UDim2.new(0, 20, 0.5, -30),
        16,
        C.Text,
        Enum.Font.GothamBold
    )
    title.TextXAlignment = Enum.TextXAlignment.Center

    local body = label(
        frame,
        "Automation is still running • open SliceHub to restore rendering",
        UDim2.new(1, -40, 0, 22),
        UDim2.new(0, 20, 0.5, 4),
        9,
        C.Muted,
        Enum.Font.GothamMedium
    )
    body.TextXAlignment = Enum.TextXAlignment.Center

    App.PerformanceControl.Overlay = overlay
    App.PerformanceControl.OverlayFrame = frame
    return overlay
end

App.PerformanceControl.RefreshOverlay = function()
    local overlay = App.PerformanceControl.EnsureOverlay()
    local frame = App.PerformanceControl.OverlayFrame
    if not overlay or not frame then return end

    App.PerformanceControl.RgbToken += 1
    local token = App.PerformanceControl.RgbToken
    local premiumRgb = true and App.Values.RenderOverlayRGB == true

    if not premiumRgb then
        frame.BackgroundColor3 = true
            and (App.Values.RenderOverlayColor or C.Surface)
            or Color3.fromRGB(12, 15, 21)
        return
    end

    task.spawn(function()
        local hue = 0
        while token == App.PerformanceControl.RgbToken
            and overlay and overlay.Parent
            and overlay.Enabled
            and App.Values.Disable3DRendering == true do
            hue = (hue + 0.018) % 1
            frame.BackgroundColor3 = Color3.fromHSV(hue, 0.78, 0.78)
            task.wait(App.PerformanceControl.Delay(0.16, 0.28))
        end
    end)
end

App.PerformanceControl.Apply3D = function(disableOverride)
    local disable = disableOverride
    if disable == nil then
        disable = App.Values.Disable3DRendering == true
    else
        disable = disable == true
    end

    local overlay = App.PerformanceControl.EnsureOverlay()
    local ok, err = pcall(function()
        game:GetService("RunService"):Set3dRenderingEnabled(not disable)
    end)

    if not ok then
        App.Values.Disable3DRendering = false
        if overlay then overlay.Enabled = false end
        App.PerformanceControl.LastRenderStatus = "Unsupported by executor/client"
        return false, err
    end

    if overlay then
        overlay.Enabled = disable
    end
    App.PerformanceControl.LastRenderStatus = disable
        and "3D rendering off"
        or "3D rendering on"

    App.PerformanceControl.RefreshOverlay()
    return true
end

local function rememberTransparency(object)
    if TransparencyBase[object] ~= nil then
        return
    end
    if object:IsA("Frame") or object:IsA("TextButton") or object:IsA("TextBox") or object:IsA("ScrollingFrame") then
        if object.BackgroundTransparency < 1 then
            TransparencyBase[object] = object.BackgroundTransparency
        end
    end
end

local function applyWindowTransparency()
    local amount = math.clamp((tonumber(App.Values.WindowTransparency) or 50) / 100, 0.20, 0.70)

    for _, object in ipairs(gui:GetDescendants()) do
        rememberTransparency(object)
        local base = TransparencyBase[object]

        if base ~= nil then
            local protected =
                object == statusDot
                or object == accent
                or object.Name == "Marker"
                or object.Name == "MacRed"
                or object.Name == "MacYellow"
                or object.Name == "MacGreen"

            if not protected then
                local weight = 0.72

                if object == shell or object == sidebar or object == content
                    or object == header or object == statusBar then
                    weight = 1.15
                elseif object.Name == "Section" then
                    weight = 0.88
                elseif object:IsA("TextButton") or object:IsA("TextBox") then
                    weight = 0.42
                end

                object.BackgroundTransparency = math.clamp(base + amount * weight, 0, 0.86)
            end
        end
    end
end

local function setMacButtonsVisible(visible)
    visible = visible == true
    local compact = App.Mobile and App.Mobile.Compact

    if compact then
        visible = false
    end

    if MacButtons then
        MacButtons.Visible = visible
    end


    close.Visible = compact ~= true and not visible

    local x = visible and 76 or 15
    brandLabel.Position = UDim2.fromOffset(x, 16)
    metaLabel.Position = UDim2.fromOffset(x, 28)
end

local function tweenShellScale(target, duration, easing)
    local uiScale = shell:FindFirstChildOfClass("UIScale")
    if not uiScale then
        return nil
    end
    local tween = TweenService:Create(
        uiScale,
        TweenInfo.new(duration or 0.18, easing or Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
        {Scale = target}
    )
    tween:Play()
    return tween
end

local function closeWithAnimation()
    if shell
        and shell.Parent
        and not MacState.Minimized
        and not (App.Mobile and App.Mobile.Compact) then

        local logicalWidth = tonumber(shell.Size.X.Offset) or 0
        local logicalHeight = tonumber(shell.Size.Y.Offset) or 0

        if logicalWidth >= 680
            and logicalHeight >= 430 then

            V12Config.WindowWidth =
                math.clamp(
                    math.floor(
                        logicalWidth + 0.5
                    ),
                    680,
                    1600
                )

            V12Config.WindowHeight =
                math.clamp(
                    math.floor(
                        logicalHeight + 0.5
                    ),
                    430,
                    1000
                )

            pcall(V12Config.SaveMetadataOnly)
        end
    end

    local tween = tweenShellScale(0.965, 0.14, Enum.EasingStyle.Quad)
    if tween then tween.Completed:Wait() end
    if App.PerformanceControl then
        App.Values.Disable3DRendering = false
        pcall(App.PerformanceControl.Apply3D)
        App.Values.FPSCapEnabled = false
        pcall(App.PerformanceControl.ApplyFPSCap)
    end
    if App.RestoreNapeVisuals then pcall(App.RestoreNapeVisuals) end
    if App.RestoreMapProps then pcall(App.RestoreMapProps) end
    if PerformanceState.MapPropConnection then
        pcall(function() PerformanceState.MapPropConnection:Disconnect() end)
        PerformanceState.MapPropConnection = nil
    end
    if App.PerformanceControl then
        App.PerformanceControl.RgbToken += 1
        local overlay = App.PerformanceControl.Overlay
        if overlay and overlay.Parent then pcall(function() overlay:Destroy() end) end
        App.PerformanceControl.Overlay = nil
        App.PerformanceControl.OverlayFrame = nil
    end
    if gui and gui.Parent then
        gui:Destroy()
    end
end

local function setMinimized(minimized)
    if minimized == MacState.Minimized then
        return
    end

    if minimized then
        MacState.BeforeMinimizeSize = shell.Size
        MacState.BeforeMinimizePosition = shell.Position

        if not MacState.Maximized then
            MacState.NormalSize = shell.Size
            MacState.NormalPosition = shell.Position
        end

        MacState.Minimized = true
        sidebar.Visible = false
        content.Visible = false
        statusBar.Visible = false

        TweenService:Create(
            shell,
            TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {
                Size = UDim2.fromOffset(390, 52),
                Position = UDim2.new(shell.Position.X.Scale, shell.Position.X.Offset, shell.Position.Y.Scale, shell.Position.Y.Offset),
            }
        ):Play()
    else
        MacState.Minimized = false
        local targetSize = MacState.BeforeMinimizeSize
        local targetPos = MacState.BeforeMinimizePosition

        local tween = TweenService:Create(
            shell,
            TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Size = targetSize, Position = targetPos}
        )
        tween:Play()
        tween.Completed:Connect(function()
            if shell and shell.Parent and not MacState.Minimized then
                sidebar.Visible = true
                content.Visible = true
                statusBar.Visible = true
            end
        end)
    end
end

local function toggleMaximize()
    if MacState.Minimized then
        setMinimized(false)
        return
    end

    local camera = workspace.CurrentCamera
    if not camera then return end
    local viewport = camera.ViewportSize

    if not MacState.Maximized then
        MacState.NormalSize = shell.Size
        MacState.NormalPosition = shell.Position
        MacState.Maximized = true

        TweenService:Create(
            shell,
            TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {
                Size = UDim2.fromOffset(
                    math.clamp(viewport.X - 42, 680, 1600),
                    math.clamp(viewport.Y - 42, 430, 1000)
                ),
                Position = UDim2.fromScale(0.5, 0.5),
            }
        ):Play()
    else
        MacState.Maximized = false
        TweenService:Create(
            shell,
            TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {
                Size = MacState.NormalSize,
                Position = MacState.NormalPosition,
            }
        ):Play()
    end
end

