local function applySimpleLighting(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    if PerformanceState.Lighting == nil then
        PerformanceState.Lighting = {
            GlobalShadows = Lighting.GlobalShadows,
        }
    end

    if enabled then
        Lighting.GlobalShadows = false

        for _, effect in ipairs(Lighting:GetChildren()) do
            if effect:IsA("BloomEffect")
                or effect:IsA("BlurEffect")
                or effect:IsA("ColorCorrectionEffect")
                or effect:IsA("DepthOfFieldEffect")
                or effect:IsA("SunRaysEffect") then
                if effect:GetAttribute("SliceHubV12_OriginalEnabled") == nil then
                    effect:SetAttribute("SliceHubV12_OriginalEnabled", effect.Enabled)
                end
                effect.Enabled = false
            end
        end
    else
        if PerformanceState.Lighting then
            Lighting.GlobalShadows = PerformanceState.Lighting.GlobalShadows
        end

        for _, effect in ipairs(Lighting:GetChildren()) do
            local original = effect:GetAttribute("SliceHubV12_OriginalEnabled")
            if original ~= nil and effect:IsA("PostEffect") then
                effect.Enabled = original
                effect:SetAttribute("SliceHubV12_OriginalEnabled", nil)
            end
        end
    end
end

local function applyRemoveFog(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    if PerformanceState.Fog == nil then
        PerformanceState.Fog = {
            FogStart = Lighting.FogStart,
            FogEnd = Lighting.FogEnd,
        }
    end

    if enabled then
        Lighting.FogStart = 1000000000
        Lighting.FogEnd = 10000000000

        for _, atmosphere in ipairs(Lighting:GetChildren()) do
            if atmosphere:IsA("Atmosphere") then
                if PerformanceState.Atmospheres[atmosphere] == nil then
                    PerformanceState.Atmospheres[atmosphere] = {
                        Density = atmosphere.Density,
                        Haze = atmosphere.Haze,
                        Glare = atmosphere.Glare,
                    }
                end
                atmosphere.Density = 0
                atmosphere.Haze = 0
                atmosphere.Glare = 0
            end
        end
    else
        if PerformanceState.Fog then
            Lighting.FogStart = PerformanceState.Fog.FogStart
            Lighting.FogEnd = PerformanceState.Fog.FogEnd
        end

        for atmosphere, original in pairs(PerformanceState.Atmospheres) do
            if atmosphere and atmosphere.Parent then
                atmosphere.Density = original.Density
                atmosphere.Haze = original.Haze
                atmosphere.Glare = original.Glare
            end
        end
    end
end


local EFFECT_CLASSES = {
    ParticleEmitter = true,
    Trail = true,
    Beam = true,
    Smoke = true,
    Fire = true,
    Sparkles = true,
}

local function isEffectInstance(object)
    return EFFECT_CLASSES[object.ClassName] == true
end

local function setEffectEnabled(object, enabled)
    if object:IsA("ParticleEmitter")
        or object:IsA("Trail")
        or object:IsA("Beam")
        or object:IsA("Smoke")
        or object:IsA("Fire")
        or object:IsA("Sparkles") then
        object.Enabled = enabled
    end
end

local function applyDisableCameraEffects(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    local camera = workspace.CurrentCamera
    if not camera then
        return
    end

    local function shouldDisable(effect)
        return effect:IsA("BloomEffect")
            or effect:IsA("BlurEffect")
            or effect:IsA("ColorCorrectionEffect")
            or effect:IsA("DepthOfFieldEffect")
            or effect:IsA("SunRaysEffect")
    end

    if enabled then
        for _, effect in ipairs(camera:GetDescendants()) do
            if shouldDisable(effect) then
                if PerformanceState.CameraEffects[effect] == nil then
                    PerformanceState.CameraEffects[effect] = effect.Enabled
                end
                effect.Enabled = false
            end
        end
    else
        for effect, original in pairs(PerformanceState.CameraEffects) do
            if effect and effect.Parent then
                effect.Enabled = original
            end
        end
        PerformanceState.CameraEffects = {}
    end
end

local PROTECTED_WORDS = {
    "objective", "quest", "mission", "raid", "boss", "titan",
    "cannon", "refill", "gastank", "gas tank", "station",
    "interact", "prompt", "wave", "waves", "cutscene",
    "eren", "bertholdt", "annie", "colossal",
    "player", "character", "spawn", "checkpoint",
    "hitbox", "nape", "humanoid", "rootpart",
    "baseplate", "ground", "floor", "road", "path",
    "safezone", "barrier", "runtime", "projectile", "attack",
    "watchtower", "watch_tower", "watch tower", "ts_towers",
    "thunderspear", "thunderspear_towers", "supplies_circle", "escort", "horse",
    "toweractivation", "tower_activation",
    "colossalcannon", "colossal_cannon", "cannonhitbox", "cannon_hitbox",
    "wall", "walls", "_walls", "gate", "climbable", "rampart", "battlement",
}

local function containsAny(text, words)
    text = string.lower(text or "")
    for _, word in ipairs(words) do
        if string.find(text, word, 1, true) then
            return true
        end
    end
    return false
end

local function protectedMapObject(instance)
    if not instance or not instance.Parent then
        return true
    end


    if App.LoadingProtection
        and App.LoadingProtection.Suspended == true then
        return true
    end

    if instance == workspace.Terrain
        or instance == workspace.CurrentCamera
        or (player.Character and instance:IsDescendantOf(player.Character)) then
        return true
    end


    local climbableRoot = workspace:FindFirstChild("Climbable")
    if climbableRoot and instance:IsDescendantOf(climbableRoot) then
        return true
    end

    if App.Colossal
        and App.Colossal.Active == true
        and instance:IsA("BasePart")
        and instance.CanCollide == true then
        return true
    end

    local node = instance
    local depth = 0

    while node and node ~= workspace and depth < 9 do
        if containsAny(node.Name, PROTECTED_WORDS) then
            return true
        end

        if node:IsA("Model") and node:FindFirstChildOfClass("Humanoid") then
            return true
        end

        node = node.Parent
        depth += 1
    end

    local ok, tags = pcall(function()
        return game:GetService("CollectionService"):GetTags(instance)
    end)

    if ok and type(tags) == "table" then
        for _, tag in ipairs(tags) do
            if containsAny(tostring(tag), PROTECTED_WORDS) then
                return true
            end
        end
    end

    return false
end


local function applyDisableParticlesTrails(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    if enabled then
        for _, object in ipairs(workspace:GetDescendants()) do
            if isEffectInstance(object)
                and not (titanFolder and titanFolder() and object:IsDescendantOf(titanFolder()))
                and not protectedMapObject(object) then

                if PerformanceState.Effects[object] == nil then
                    PerformanceState.Effects[object] = object.Enabled
                end

                setEffectEnabled(object, false)
            end
        end
    else
        for object, original in pairs(PerformanceState.Effects) do
            if object and object.Parent then
                setEffectEnabled(object, original)
            end
        end
        PerformanceState.Effects = {}
    end
end

local function applyLowDetailMaterials(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    if enabled then
        for _, object in ipairs(workspace:GetDescendants()) do
            if object:IsA("BasePart") and not protectedMapObject(object) then
                if PerformanceState.Materials[object] == nil then
                    PerformanceState.Materials[object] = {
                        Material = object.Material,
                        Reflectance = object.Reflectance,
                        CastShadow = object.CastShadow,
                    }
                end

                object.Material = Enum.Material.SmoothPlastic
                object.Reflectance = 0
                object.CastShadow = false
            end
        end
    else
        for object, original in pairs(PerformanceState.Materials) do
            if object and object.Parent then
                object.Material = original.Material
                object.Reflectance = original.Reflectance
                object.CastShadow = original.CastShadow
            end
        end
        PerformanceState.Materials = {}
    end
end

local function applyRemoveMapTextures(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    if enabled then
        for _, object in ipairs(workspace:GetDescendants()) do
            if (object:IsA("Decal") or object:IsA("Texture"))
                and not protectedMapObject(object) then

                if PerformanceState.Textures[object] == nil then
                    PerformanceState.Textures[object] = {
                        Kind = "Transparency",
                        Transparency = object.Transparency,
                    }
                end

                object.Transparency = 1

            elseif object:IsA("SurfaceAppearance")
                and not protectedMapObject(object) then

                if PerformanceState.Textures[object] == nil then
                    PerformanceState.Textures[object] = {
                        Kind = "Parent",
                        Parent = object.Parent,
                    }
                end

                object.Parent = nil
            end
        end
    else
        for object, original in pairs(PerformanceState.Textures) do
            if object and original then
                if original.Kind == "Transparency" and object.Parent then
                    object.Transparency = original.Transparency
                elseif original.Kind == "Parent" and original.Parent and original.Parent.Parent then
                    object.Parent = original.Parent
                end
            end
        end
        PerformanceState.Textures = {}
    end
end

local function applyReduceTitanEffects(enabled)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end
    local folder = workspace:FindFirstChild("Titans")
    if not folder then
        return
    end

    if enabled then
        for _, object in ipairs(folder:GetDescendants()) do
            if isEffectInstance(object) then
                if PerformanceState.TitanEffects[object] == nil then
                    PerformanceState.TitanEffects[object] = object.Enabled
                end
                setEffectEnabled(object, false)
            end
        end
    else
        for object, original in pairs(PerformanceState.TitanEffects) do
            if object and object.Parent then
                setEffectEnabled(object, original)
            end
        end
        PerformanceState.TitanEffects = {}
    end
end

App.RememberMapPropCandidate = function(object)
    if not object or not object:IsA("BasePart") or protectedMapObject(object) then
        return false
    end
    PerformanceState.MapPropCandidates = PerformanceState.MapPropCandidates or setmetatable({}, {__mode = "k"})
    PerformanceState.MapPropCandidates[object] = true
    return true
end

App.HideMapPropLocal = function(object)
    if not object or not object.Parent or protectedMapObject(object) then
        return false
    end
    if PerformanceState.RemovedMapParts[object] == nil then
        PerformanceState.RemovedMapParts[object] = {
            LocalTransparencyModifier = object.LocalTransparencyModifier,
            CastShadow = object.CastShadow,
        }
    end
    object.LocalTransparencyModifier = 1
    object.CastShadow = false
    return true
end

App.EnsureMapPropCache = function()
    PerformanceState.MapPropCandidates = PerformanceState.MapPropCandidates or setmetatable({}, {__mode = "k"})
    if PerformanceState.MapPropCacheReady ~= true then
        local snapshot = workspace:GetDescendants()
        for index, object in ipairs(snapshot) do
            App.RememberMapPropCandidate(object)
            if index % 300 == 0 then task.wait() end
        end
        PerformanceState.MapPropCacheReady = true
    end

    if not PerformanceState.MapPropConnection then
        PerformanceState.MapPropConnection = workspace.DescendantAdded:Connect(function(object)
            if App.Values.RemoveMapProps == true
                and not (
                    App.LoadingProtection
                    and App.LoadingProtection.Suspended == true
                )
                and App.RememberMapPropCandidate(object) then

                task.defer(function()
                    if object and object.Parent then
                        pcall(
                            App.HideMapPropLocal,
                            object
                        )
                    end
                end)
            end
        end)
    end
end

local function applyRemoveMapProps(enabled, quiet)
    if RuntimeKind == "MainMenu" then return end
    if enabled and App.LoadingProtection and App.LoadingProtection.Suspended == true then return end

    -- V14.5 R4 COLOSSAL GEOMETRY GUARD
    -- Do not keep any locally-hidden map props while the Colossal director is
    -- active. The previous optimization could hide a wall segment before
    -- Colossal detection and leave it invisible after the object became
    -- protected. Reliability wins over decorative map stripping in this raid.
    if enabled
        and App.Colossal
        and App.Colossal.Active == true then
        enabled = false
    end

    if enabled then
        App.EnsureMapPropCache()
        local hidden = 0
        local processed = 0
        for object in pairs(PerformanceState.MapPropCandidates or {}) do
            processed += 1
            if App.HideMapPropLocal(object) then hidden += 1 end
            if processed % 300 == 0 then task.wait() end
        end
        if not quiet then
            toast("Remove Map Props", tostring(hidden) .. " decorative map parts hidden locally.")
        end
    else
        local restored = 0
        local processed = 0
        for object, original in pairs(PerformanceState.RemovedMapParts) do
            processed += 1
            if object and object.Parent and original then
                pcall(function()
                    object.LocalTransparencyModifier = original.LocalTransparencyModifier
                    object.CastShadow = original.CastShadow
                end)
                restored += 1
            end
            if processed % 300 == 0 then task.wait() end
        end
        PerformanceState.RemovedMapParts = {}
        if not quiet then
            toast("Remove Map Props", tostring(restored) .. " map parts restored.")
        end
    end
end

App.RestoreMapProps = function()
    applyRemoveMapProps(false, true)
end

local function titanFolder()
    return workspace:FindFirstChild("Titans")
end

local function isTitanAlive(titan)
    if not titan or not titan:IsA("Model") then
        return false
    end

    local humanoid = titan:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health > 0
end

local function titanNape(titan)
    local nape = titan and titan:FindFirstChild("Nape", true)
    if nape and nape:IsA("BasePart") then
        return nape
    end
    return nil
end

App.RememberNapeVisual = function(nape)
    if not nape or TitanVisualState.OriginalNapeVisuals[nape] ~= nil then
        return
    end
    TitanVisualState.OriginalNapeVisuals[nape] = {
        Transparency = nape.Transparency,
        LocalTransparencyModifier = nape.LocalTransparencyModifier,
        Color = nape.Color,
        Material = nape.Material,
        CastShadow = nape.CastShadow,
    }
end

App.RestoreNapeVisuals = function()
    for nape, original in pairs(TitanVisualState.OriginalNapeVisuals) do
        if nape and nape.Parent and original then
            pcall(function()
                nape.Transparency = original.Transparency
                nape.LocalTransparencyModifier = original.LocalTransparencyModifier
                nape.Color = original.Color
                nape.Material = original.Material
                nape.CastShadow = original.CastShadow
            end)
        end
        TitanVisualState.OriginalNapeVisuals[nape] = nil
    end
end

local function restoreAllNapeSizes()
    for nape, originalSize in pairs(TitanVisualState.OriginalNapeSizes) do
        if nape and nape.Parent then
            pcall(function()
                nape.Size = originalSize
            end)
        end
    end
end

local NAPE_PRESET_SIZES = {
    [2] = Vector3.new(50, 50, 50),
    [3] = Vector3.new(100, 100, 100),
    [4] = Vector3.new(150, 150, 150),
    [5] = Vector3.new(200, 200, 200),
}

local function refreshNapeExtender()
    local folder = titanFolder()

    if not App.Values.NapeExtender then
        restoreAllNapeSizes()
        return
    end

    if not folder then
        return
    end

    local preset = math.clamp(math.floor((tonumber(App.Values.NapeSize) or 1) + 0.5), 1, 5)

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan) then
            local nape = titanNape(titan)

            if nape then
                if TitanVisualState.OriginalNapeSizes[nape] == nil then
                    TitanVisualState.OriginalNapeSizes[nape] = nape.Size
                end

                if preset <= 1 then
                    nape.Size = TitanVisualState.OriginalNapeSizes[nape]
                else

                    nape.Size = NAPE_PRESET_SIZES[preset]
                end
            end
        end
    end
end

local function clearTitanVisuals()
    for titan, highlight in pairs(TitanVisualState.Highlights) do
        if highlight then
            pcall(function() highlight:Destroy() end)
        end
        TitanVisualState.Highlights[titan] = nil
    end

    for titan, box in pairs(TitanVisualState.NapeBoxes) do
        if box then
            pcall(function() box:Destroy() end)
        end
        TitanVisualState.NapeBoxes[titan] = nil
    end
end

local function refreshTitanVisuals()
    local folder = titanFolder()

    if not folder then
        clearTitanVisuals()
        return
    end

    local titanColor = App.Values.TitanESPColor or C.Accent
    local napeColor = App.Values.NapeESPColor or Color3.fromRGB(255, 149, 0)
    local aliveSet = {}

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan) then
            aliveSet[titan] = true

            if App.Values.TitanESP then
                local highlight = TitanVisualState.Highlights[titan]

                if not highlight or not highlight.Parent then
                    highlight = Instance.new("Highlight")
                    highlight.Name = "SliceHubTitanESP"
                    highlight.Adornee = titan
                    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                    highlight.FillTransparency = 0.82
                    highlight.OutlineTransparency = 0
                    highlight.Parent = titan
                    TitanVisualState.Highlights[titan] = highlight
                end

                highlight.FillColor = titanColor
                highlight.OutlineColor = titanColor
            elseif TitanVisualState.Highlights[titan] then
                TitanVisualState.Highlights[titan]:Destroy()
                TitanVisualState.Highlights[titan] = nil
            end

            if App.Values.ShowNapeHitbox then
                local nape = titanNape(titan)
                local box = TitanVisualState.NapeBoxes[titan]

                if nape then
                    App.RememberNapeVisual(nape)
                    if not box or not box.Parent then
                        box = Instance.new("BoxHandleAdornment")
                        box.Name = "SliceHubNapeHitbox"
                        box.AlwaysOnTop = true
                        box.ZIndex = 8
                        box.Transparency = 0.48
                        box.Adornee = nape
                        box.Parent = nape
                        TitanVisualState.NapeBoxes[titan] = box
                    end

                    box.Adornee = nape
                    box.Size = nape.Size + Vector3.new(0.08, 0.08, 0.08)
                    box.Color3 = napeColor
                elseif box then
                    box:Destroy()
                    TitanVisualState.NapeBoxes[titan] = nil
                end
            elseif TitanVisualState.NapeBoxes[titan] then
                TitanVisualState.NapeBoxes[titan]:Destroy()
                TitanVisualState.NapeBoxes[titan] = nil
            end
        end
    end

    for titan, highlight in pairs(TitanVisualState.Highlights) do
        if not aliveSet[titan] or not titan.Parent then
            if highlight then highlight:Destroy() end
            TitanVisualState.Highlights[titan] = nil
        end
    end

    for titan, box in pairs(TitanVisualState.NapeBoxes) do
        if not aliveSet[titan] or not titan.Parent then
            if box then box:Destroy() end
            TitanVisualState.NapeBoxes[titan] = nil
        end
    end
end

local function ensureTitanVisualLoop()
    if TitanVisualState.Running then
        return
    end

    TitanVisualState.Running = true

    task.spawn(function()
        local espWasActive = false
        local extenderWasActive = false

        while gui and gui.Parent do
            local espActive =
                App.Values.TitanESP
                or App.Values.ShowNapeHitbox

            local extenderActive =
                App.Values.NapeExtender == true

            if espActive then
                espWasActive = true
                pcall(refreshTitanVisuals)
            elseif espWasActive then
                clearTitanVisuals()
                App.RestoreNapeVisuals()
                espWasActive = false
            end

            if extenderActive then
                extenderWasActive = true
                pcall(refreshNapeExtender)
            elseif extenderWasActive then
                restoreAllNapeSizes()
                extenderWasActive = false
            end

            if espActive or extenderActive then
                task.wait(App.PerformanceControl.Delay(0.55, 0.85))
            else
                task.wait(App.PerformanceControl.Delay(0.95, 1.60))
            end
        end

        clearTitanVisuals()
        restoreAllNapeSizes()
        App.RestoreNapeVisuals()
        TitanVisualState.Running = false
    end)
end


-- V15.6.28 AOTR COMBAT REGISTER BOUNDARY
-- Fresh function scope keeps spear/blade locals away from the register-heavy UI chunk.
;(function()
local SpearRuntime = {
    Busy = false,
    RefillBusy = false,
    Moving = false,
    MoveTween = nil,
    NextFireAt = 0,
    NextRefillAt = 0,
    LastTarget = nil,
    LastStatus = "Idle",
    LastError = nil,
