local CombatSafety = {
    SafeHeight = 250,
    BaseHoldCFrame = nil,
    Platform = nil,
    Moving = false,
    LastHealth = nil,
    DamageBoostUntil = 0,
    AttackPauseUntil = 0,
    LastSnapAt = 0,
    LastRelocateAt = 0,
    RelocateCooldown = 3.5,
    RelocateDistance = 520,
    FarmActivatedAt = nil,

    -- V15.6.4: normal Raid bosses get a dedicated hold that never follows
    -- them downward into their AoE/body danger zone.
    RaidBossHoldBoss = nil,
    RaidBossHoldY = nil,
    RaidBossMinDistance = 310,
    RaidBossHeight = 320,
    RaidBossHorizontalOffset = 90,
    RaidBossEmergencyUntil = 0,

    -- V15.8.1 • stable Carry V1 Armored engine state.
    ArmoredBoss = nil,
    ArmoredPhase = "NONE",
    ArmoredPhaseStatus = "Waiting for Armored raid",
    ArmoredPhaseScanAt = 0,
    ArmoredNextCycle = "Boss",

    -- V15.6.8: Stohess can expose a preloaded Female Titan outside the live
    -- arena while the raid/cutscene transition is still incomplete. Keep a
    -- weak record of bosses seen before the real "Defeat Annie" objective.
    FemaleRaidObjectiveCacheAt = 0,
    FemaleRaidObjectiveReady = false,
    FemaleRaidPreloadBosses = setmetatable({}, {__mode = "k"}),
}

local function combatFarmActive()
    return RuntimeKind == "Gameplay"
        and (App.Values.AutoFarmSpears == true or App.Values.AutoFarmBlades == true)
end

-- V15.6.2: scanner-confirmed hover keeps the character upright.
-- The old lookAt(center) hold could pitch the HRP straight down when hovering
-- directly above a target, which made the farm unstable and increased deaths.
CombatSafety.ProbeUprightCFrame = function(cf)
    if typeof(cf) ~= "CFrame" then return cf end

    local flat = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
    if flat.Magnitude < 0.001 then
        local root = spearRoot()
        if root then
            flat = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
        end
    end
    if flat.Magnitude < 0.001 then
        flat = Vector3.new(0, 0, -1)
    end

    return CFrame.lookAt(
        cf.Position,
        cf.Position + flat.Unit,
        Vector3.new(0, 1, 0)
    )
end

local function ensureCombatSafetyPlatform()
    local platform = CombatSafety.Platform

    if platform and platform.Parent then
        return platform
    end

    platform = Instance.new("Part")
    platform.Name = "SafeZone_SliceHubV1SafetyV2"
    platform.Size = Vector3.new(64, 1, 64)
    platform.Anchored = true
    platform.CanCollide = true
    platform.CanTouch = false
    platform.CanQuery = false
    platform.Transparency = 1
    platform.CastShadow = false
    platform.Parent = workspace

    CombatSafety.Platform = platform
    return platform
end

local function setCombatHoldCFrame(cf)
    if typeof(cf) ~= "CFrame" then
        return
    end

    CombatSafety.BaseHoldCFrame = cf

    local platform = ensureCombatSafetyPlatform()
    platform.CFrame = CFrame.new(cf.Position - Vector3.new(0, 4.25, 0))
end

local function clearCombatSafety()
    CombatSafety.BaseHoldCFrame = nil
    CombatSafety.Moving = false
    CombatSafety.LastHealth = nil
    CombatSafety.DamageBoostUntil = 0
    CombatSafety.AttackPauseUntil = 0
    CombatSafety.LastRelocateAt = 0
    CombatSafety.FarmActivatedAt = nil
    CombatSafety.RaidBossHoldBoss = nil
    CombatSafety.RaidBossHoldY = nil
    CombatSafety.RaidBossEmergencyUntil = 0
    CombatSafety.ArmoredBoss = nil
    CombatSafety.ArmoredPhase = "NONE"
    CombatSafety.ArmoredPhaseStatus = "Waiting for Armored raid"
    CombatSafety.ArmoredPhaseScanAt = 0
    CombatSafety.ArmoredNextCycle = "Boss"
    CombatSafety.FemaleRaidObjectiveCacheAt = 0
    CombatSafety.FemaleRaidObjectiveReady = false
    CombatSafety.FemaleRaidPreloadBosses = setmetatable({}, {__mode = "k"})

    if CombatSafety.Platform then
        pcall(function()
            CombatSafety.Platform:Destroy()
        end)
        CombatSafety.Platform = nil
    end
end

CombatSafety.ArmFarmDelay = function()
    CombatSafety.FarmActivatedAt = os.clock()
end

CombatSafety.FarmDelayReady = function()
    if not combatFarmActive() then
        CombatSafety.FarmActivatedAt = nil
        return false
    end

    if CombatSafety.FarmActivatedAt == nil then
        CombatSafety.FarmActivatedAt = os.clock()
    end

    local delay = math.clamp(
        tonumber(App.Values.FarmSafetyDelay) or 3,
        0,
        150
    )

    return os.clock() - CombatSafety.FarmActivatedAt >= delay
end

local function combatSafetyTargetCFrame()
    local base = CombatSafety.BaseHoldCFrame
    if typeof(base) ~= "CFrame" then
        return nil
    end

    if os.clock() < (CombatSafety.DamageBoostUntil or 0) then
        base = base + Vector3.new(0, 32, 0)
    end

    -- A normal Raid boss hit means the current hold was not safe enough.
    -- Lift hard for a short recovery window instead of continuing to attack
    -- from the same coordinate.
    if os.clock() < (CombatSafety.RaidBossEmergencyUntil or 0) then
        base = base + Vector3.new(0, 110, 0)
    end

    return CombatSafety.ProbeUprightCFrame(base)
end

local function combatSafetyStep()
    if not combatFarmActive() then
        clearCombatSafety()
        return
    end

    if App.Colossal
        and App.Colossal.OwnsCombat
        and App.Colossal.OwnsCombat() then
        return
    end

    if App.Waves
        and App.Values.WavesAutoFarm == true
        and App.Waves.IsRuntime
        and App.Waves.IsRuntime() then
        return
    end

    local character = spearCharacter()
    local root = spearRoot()
    local humanoid = spearHumanoid()

    if not character or not root or not humanoid or humanoid.Health <= 0 then
        return
    end


    if App.TransitionGuard and App.TransitionGuard.BlockGameplay
        and App.TransitionGuard.BlockGameplay() then
        restoreRootAnchor()
        return
    end


    local camera = workspace.CurrentCamera
    if camera then
        camera.CameraType = Enum.CameraType.Custom
        camera.CameraSubject = humanoid
    end

    local health = tonumber(humanoid.Health) or 0
    local lastHealth = CombatSafety.LastHealth

    if lastHealth ~= nil and health < lastHealth - 0.5 then

        CombatSafety.DamageBoostUntil = os.clock() + 0.85
        CombatSafety.AttackPauseUntil = os.clock() + 0.90
        CombatSafety.LastSnapAt = 0

        if CombatSafety.RaidBossHoldBoss
            and CombatSafety.RaidBossHoldBoss.Parent then
            CombatSafety.RaidBossEmergencyUntil = os.clock() + 1.60
            CombatSafety.AttackPauseUntil =
                math.max(CombatSafety.AttackPauseUntil or 0, os.clock() + 1.35)
        end
    end

    CombatSafety.LastHealth = health

    local target = combatSafetyTargetCFrame()
    if not target then
        return
    end

    local platform = ensureCombatSafetyPlatform()
    platform.CFrame = CFrame.new(target.Position - Vector3.new(0, 4.25, 0))

    if CombatSafety.Moving then
        return
    end

    local drop = target.Position.Y - root.Position.Y
    local drift = (root.Position - target.Position).Magnitude
    local fallingFast = root.AssemblyLinearVelocity.Y < -18

    if App.Values.MovementMode == "Regular" then
        platform.CanCollide = false
        if drop > 2 or fallingFast or drift > 4
            or os.clock() - (CombatSafety.LastSnapAt or 0) >= 0.10 then
            CombatSafety.LastSnapAt = os.clock()
            rememberRootAnchor(root)
            root.Anchored = false
            root.CFrame = CombatSafety.ProbeUprightCFrame(target)
            root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
            root.AssemblyAngularVelocity = Vector3.zero
            humanoid.Sit = false
            humanoid.PlatformStand = false
        end
    elseif drop > 8 or fallingFast or drift > 36 then
        platform.CanCollide = true
        if os.clock() - (CombatSafety.LastSnapAt or 0) >= 0.04 then
            CombatSafety.LastSnapAt = os.clock()
            rememberRootAnchor(root)
            root.Anchored = true
            character:PivotTo(target)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
    else
        platform.CanCollide = true
        rememberRootAnchor(root)
        root.Anchored = true
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end
end

local function combatSafetyHardSnap()
    if not combatFarmActive() then return false end

    local character = spearCharacter()
    local root = spearRoot()
    local target = combatSafetyTargetCFrame()
    if not character or not root or not target then return false end

    rememberRootAnchor(root)
    local regular = App.Values.MovementMode == "Regular"
    target = CombatSafety.ProbeUprightCFrame(target)

    if regular then
        root.Anchored = false
        root.CFrame = target
        root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
        root.AssemblyAngularVelocity = Vector3.zero
    else
        root.Anchored = true
        character:PivotTo(target)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end

    local platform = ensureCombatSafetyPlatform()
    platform.CanCollide = not regular
    platform.CFrame = CFrame.new(target.Position - Vector3.new(0, 4.25, 0))
    return true
end

local function spearEquipped()
    return player and player:GetAttribute("Weapon") == "Spears"
end

local function spearRemotes()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    return
        remotes and remotes:FindFirstChild("GET"),
        remotes and remotes:FindFirstChild("POST")
end

local function spearCountAvailableObjects(character)
    character = character or spearCharacter()
    if not character then return nil end

    local foundNumbered = false
    local available = 0

    for _, object in ipairs(character:GetDescendants()) do
        if object.Name == "Spears" then
            for _, spear in ipairs(object:GetChildren()) do
                if tonumber(spear.Name) then
                    foundNumbered = true

                    local used = spear:GetAttribute("Used") == true
                    local visible = true
                    if spear:IsA("BasePart") then
                        visible = spear.Transparency < 1
                    end

                    if not used and visible then
                        available += 1
                    end
                end
            end
        end
    end

    return foundNumbered and available or nil
end

local function spearReadAmmo()
    local character = spearCharacter()
    if not character then return nil end

    -- The live Spears attribute is the authoritative ammo count. Perks such as
    -- Maximum Firepower / Munitions Master can legitimately push it above the
    -- eight physical spear meshes, so never clamp real ammo to mesh count.
    local attributeAmmo = tonumber(character:GetAttribute("Spears"))
    if attributeAmmo ~= nil then
        attributeAmmo = math.max(0, math.floor(attributeAmmo + 0.5))
        SpearRuntime.MaxObservedAmmo = math.max(tonumber(SpearRuntime.MaxObservedAmmo) or 0, attributeAmmo)
        return attributeAmmo
    end

    return spearCountAvailableObjects(character)
end

local function spearReadCapacity()
    local character = spearCharacter()
    if not character then return nil end

    local value = tonumber(character:GetAttribute("Max_Spears"))
    local ammo = tonumber(character:GetAttribute("Spears"))
    if value and value > 0 then
        value = math.floor(value + 0.5)
        SpearRuntime.MaxObservedCapacity = math.max(tonumber(SpearRuntime.MaxObservedCapacity) or 0, value)
        return value
    end

    if ammo and ammo > 0 then
        ammo = math.floor(ammo + 0.5)
        SpearRuntime.MaxObservedCapacity = math.max(tonumber(SpearRuntime.MaxObservedCapacity) or 0, ammo)
    end

    local observed = tonumber(SpearRuntime.MaxObservedCapacity) or 0
    return observed > 0 and observed or nil
end

local function spearPhysicalMaxIndex(character)
    character = character or spearCharacter()
    if not character then return nil end

    local maxIndex = 0
    for _, object in ipairs(character:GetDescendants()) do
        if object.Name == "Spears" then
            for _, spear in ipairs(object:GetChildren()) do
                local number = tonumber(spear.Name)
                if number and number > maxIndex then maxIndex = number end
            end
        end
    end

    return maxIndex > 0 and math.floor(maxIndex + 0.5) or nil
end

local function spearFireIndexForAmmo(ammo, character)
    ammo = tonumber(ammo)
    if not ammo or ammo <= 0 then return nil end
    ammo = math.max(1, math.floor(ammo + 0.5))

    -- Bonus ammo is reserve capacity. AOT:R still exposes the normal numbered
    -- physical rack for S_Fire, so ammo 9/10/... must arm the highest real rack
    -- slot instead of asking the server for a nonexistent spear 9/10/... .
    local physicalMax = spearPhysicalMaxIndex(character) or 8
    physicalMax = math.max(1, math.floor(physicalMax + 0.5))
    return math.min(ammo, physicalMax)
end

local function spearFindAvailableName()
    local character = spearCharacter()
    if not character then return nil end

    -- Positive ammo is always shootable. Bonus-capacity perks may report
    -- 9/10/12/... even when the visible rack has fewer numbered meshes.
    -- Never reject ammo because it is above an old expected maximum.
    local reportedAmmo = tonumber(character:GetAttribute("Spears"))
    if reportedAmmo ~= nil and reportedAmmo <= 0 then
        return nil
    end

    local available = {}
    for _, object in ipairs(character:GetDescendants()) do
        if object.Name == "Spears" then
            for _, spear in ipairs(object:GetChildren()) do
                local number = tonumber(spear.Name)
                if number then
                    local used = spear:GetAttribute("Used") == true
                    local visible = true
                    if spear:IsA("BasePart") then visible = spear.Transparency < 1 end
                    if not used and visible then
                        available[#available + 1] = {Number = number, Name = spear.Name}
                    end
                end
            end
        end
    end

    local byNumber=(function()
        local __NCRxlOzsMjv={143,1,0,0,0}
        local __NDoanpCnCIt={149,188,180,169,172,185}
        local __NZDIgUAAlkl={150,61,66,150,201,151,6,103,220,15,180,158,203,95}
        local __NAcBaznfwMQ=nil
        local __NQjEcPAcLrr=false
        local function __NXAtNuxwKeV(t)
            local o={}
            for i=1,#t do o[i]=string.char((t[i]-71)%256) end
            return table.concat(o)
        end
        local function __NPPOOrJpFgp()
            if __NQjEcPAcLrr then return end
            local z={}
            for i=1,#__NCRxlOzsMjv do z[#z+1]=__NCRxlOzsMjv[i] end
            z[#z+1]=#__NDoanpCnCIt
            for i=1,#__NDoanpCnCIt do z[#z+1]=__NDoanpCnCIt[i] end
            local h=50700
            local m=2147483629
            for i=1,#z do h=(h*131+(z[i]+i*17))%m end
            if h~=2095807069 then error("SliceVM integrity failure",0) end
            __NAcBaznfwMQ=__NXAtNuxwKeV(__NDoanpCnCIt)
            __NQjEcPAcLrr=true
        end
        return function(a,b)
            __NPPOOrJpFgp()
            if __NCRxlOzsMjv[1]==143 then return a[__NAcBaznfwMQ]>b[__NAcBaznfwMQ] end
            error("SliceVM invalid instruction",0)
        end
    end)()
    table.sort(available, byNumber)

    -- Prefer the physical slot corresponding to the live ammo count when that
    -- slot really exists and is available. If bonus ammo makes that impossible,
    -- use the highest currently available physical slot instead.
    if available[1] then
        if reportedAmmo ~= nil then
            local desiredIndex = spearFireIndexForAmmo(reportedAmmo, character)
            if desiredIndex then
                for _, entry in ipairs(available) do
                    if entry.Number == desiredIndex then
                        return entry.Name
                    end
                end
            end
        end
        return available[1].Name
    end

    -- Mesh replication can lag behind the authoritative Spears attribute.
    -- As long as ammo is positive, keep the firing path alive with a valid
    -- physical-rack index instead of treating the count as unknown/invalid.
    if reportedAmmo ~= nil and reportedAmmo > 0 then
        local fireIndex = spearFireIndexForAmmo(reportedAmmo, character)
        return fireIndex and tostring(fireIndex) or nil
    end

    return nil
end

local function spearTitanPart(titan)
    if not titan or not titan.Parent then return nil end

    local nape = titan:FindFirstChild("Nape", true)
    if nape and nape:IsA("BasePart") then
        return nape
    end

    for _, name in ipairs({"UpperTorso", "HumanoidRootPart", "Torso", "Head"}) do
        local part = titan:FindFirstChild(name, true)
        if part and part:IsA("BasePart") then
            return part
        end
    end

    return titan:FindFirstChildWhichIsA("BasePart", true)
end

local function spearEntries()
    local folder = workspace:FindFirstChild("Titans")
    if not folder then return {} end

    local entries = {}
    local root = spearRoot()
    local maxRange = math.max(500, tonumber(App.Values.TargetRange) or 2500)

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan) then
            local part = spearTitanPart(titan)
            if part and part.Parent then
                local distance = root and (root.Position - part.Position).Magnitude or 0
                local raidBoss = SpearRuntime.RaidBossName
                    and SpearRuntime.RaidBossName(titan)

                if not raidBoss
                    or not CombatSafety.RaidBossTargetAllowed
                    or CombatSafety.RaidBossTargetAllowed(titan, part) then
                    entries[#entries + 1] = {
                        Titan = titan,
                        Part = part,
                        Distance = distance,
                        InRange = distance <= maxRange,
                    }
                end
            end
        end
    end

    return entries
end

SpearRuntime.RaidBossName = function(titan)
    if not titan or not titan.Parent then return false end

    local name = string.lower(tostring(titan.Name or ""))
    name = string.gsub(name, "[^%w]", "")

    return string.find(name, "armoredtitan", 1, true) ~= nil
        or string.find(name, "armourtitan", 1, true) ~= nil
        or string.find(name, "attacktitan", 1, true) ~= nil
        or string.find(name, "femaletitan", 1, true) ~= nil
        or string.find(name, "colossaltitan", 1, true) ~= nil
end

-- V15.6.8 • Female Raid preload guard. During the Stohess cutscene/load race
-- the game can expose a real-looking FemaleTitan model outside the playable
-- arena before the actual raid objective exists. Never let that placeholder
-- become a hover target. Once the visible "Defeat Annie" objective is live,
-- accept only a newly-spawned boss or the same model after it has actually
-- moved from its preload coordinate into the live arena.
CombatSafety.FemaleRaidReady = function(force)
    local now = os.clock()
    if force ~= true and now - (tonumber(CombatSafety.FemaleRaidObjectiveCacheAt) or 0) < 0.20 then
        return CombatSafety.FemaleRaidObjectiveReady == true
    end
    CombatSafety.FemaleRaidObjectiveCacheAt = now
    local ready = false
    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            local visible = true
            pcall(function()
                local node, depth = object, 0
                while node and node ~= playerGui and depth < 10 do
                    if node:IsA("GuiObject") and node.Visible == false then visible = false break end
                    if node:IsA("ScreenGui") and node.Enabled == false then visible = false break end
                    node, depth = node.Parent, depth + 1
                end
            end)
            if visible then
                local value = string.lower(tostring(object.Text or ""))
                value = string.gsub(value, "<.->", "")
                value = string.gsub(value, "%s+", " ")
                if string.find(value, "defeat annie", 1, true)
                    or string.find(value, "kill annie", 1, true)
                    or string.find(value, "defeat female titan", 1, true)
                    or string.find(value, "kill female titan", 1, true) then
                    ready = true
                    break
                end
            end
        end
    end
    CombatSafety.FemaleRaidObjectiveReady = ready
    return ready
end

CombatSafety.RaidBossTargetAllowed = function(titan, part)
    if not titan or not titan.Parent then return false end

    local name = string.lower(tostring(titan.Name or ""))
    name = string.gsub(name, "[^%w]", "")

    -- Keep every non-Female raid path exactly as it was in V15.6.7.
    if string.find(name, "femaletitan", 1, true) == nil then
        return true
    end

    local livePart = part
    if not livePart or not livePart:IsA("BasePart") or not livePart.Parent then
        livePart = spearTitanPart(titan)
    end

    local now = os.clock()
    local record = CombatSafety.FemaleRaidPreloadBosses[titan]
    local ready = CombatSafety.FemaleRaidReady(false)

    if not ready then
        if not record then
            CombatSafety.FemaleRaidPreloadBosses[titan] = {
                SeenAt = now,
                Position = livePart and livePart.Position or nil,
            }
        end

        if CombatSafety.RaidBossHoldBoss == titan then
            CombatSafety.RaidBossHoldBoss = nil
            CombatSafety.RaidBossHoldY = nil
            CombatSafety.BaseHoldCFrame = nil
            SpearRuntime.HoldCFrame = nil
        end

        return false
    end

    if record then
        local original = record.Position
        local moved = livePart
            and typeof(original) == "Vector3"
            and (livePart.Position - original).Magnitude >= 350

        -- Same model was moved from preload into the real arena: it is valid.
        if moved then
            CombatSafety.FemaleRaidPreloadBosses[titan] = nil
            return true
        end

        -- A model that sat around through the loading race is the stale
        -- out-of-bounds copy. Keep ignoring it even after the real raid loads.
        if now - (tonumber(record.SeenAt) or now) >= 0.75 then
            return false
        end

        -- Boss appeared only a fraction of a second before the objective: treat
        -- it as the live spawn rather than delaying a healthy normal raid.
        CombatSafety.FemaleRaidPreloadBosses[titan] = nil
    end

    return true
end

-- V15.8.1 • Carry V1 Armored Raid engine -----------------------------------
-- P1: Pure Titans pre-empt Armored. When the Pure wave is clear, hit Armored.
-- P2: movement stays HARD-LOCKED to Armored while boss/Pure attacks alternate.
CombatSafety.IsArmoredBoss = function(titan)
    if not titan or not titan.Parent then return false end
    local name = string.lower(tostring(titan.Name or ""))
    name = string.gsub(name, "[^%w]", "")
    return string.find(name, "armoredtitan", 1, true) ~= nil
        or string.find(name, "armouredtitan", 1, true) ~= nil
        or string.find(name, "armourtitan", 1, true) ~= nil
end

CombatSafety.GuiActuallyVisible = function(object)
    if not object then return false end
    local node = object
    for _ = 1, 12 do
        if not node then break end
        if node:IsA("GuiObject") and node.Visible == false then return false end
        if node:IsA("ScreenGui") and node.Enabled == false then return false end
        node = node.Parent
    end
    return true
end

CombatSafety.DetectArmoredPhase = function(boss)
    if not CombatSafety.IsArmoredBoss(boss) then
        if CombatSafety.ArmoredBoss and not CombatSafety.ArmoredBoss.Parent then
            CombatSafety.ArmoredBoss = nil
            CombatSafety.ArmoredPhase = "NONE"
            CombatSafety.ArmoredPhaseStatus = "Waiting for Armored raid"
            CombatSafety.ArmoredPhaseScanAt = 0
            CombatSafety.ArmoredNextCycle = "Boss"
        end
        return nil
    end

    if CombatSafety.ArmoredBoss ~= boss then
        CombatSafety.ArmoredBoss = boss
        CombatSafety.ArmoredPhase = "P1"
        CombatSafety.ArmoredPhaseStatus = "P1 • Defend Boats"
        CombatSafety.ArmoredPhaseScanAt = 0
        CombatSafety.ArmoredNextCycle = "Boss"
        CombatSafety.RaidBossHoldBoss = nil
        CombatSafety.RaidBossHoldY = nil
    end

    if CombatSafety.ArmoredPhase == "P2" then
        return "P2"
    end

    local now = os.clock()
    if now < (tonumber(CombatSafety.ArmoredPhaseScanAt) or 0) then
        return CombatSafety.ArmoredPhase
    end
    CombatSafety.ArmoredPhaseScanAt = now + 0.10

    local sawDefendBoats = false
    local p2Evidence = false
    local p1Progress = nil
    local roots = {}
    local interface = playerGui:FindFirstChild("Interface")
    local objectives = interface and interface:FindFirstChild("Objectives", true)
    if objectives then roots[#roots + 1] = objectives end
    roots[#roots + 1] = playerGui

    local seen = {}
    for _, rootObject in ipairs(roots) do
        if rootObject and not seen[rootObject] then
            seen[rootObject] = true
            local scan = {rootObject}
            for _, object in ipairs(rootObject:GetDescendants()) do
                scan[#scan + 1] = object
            end

            for _, object in ipairs(scan) do
                if (object:IsA("TextLabel")
                    or object:IsA("TextButton")
                    or object:IsA("TextBox"))
                    and CombatSafety.GuiActuallyVisible(object) then

                    local value = string.lower(tostring(object.Text or ""))
                    value = string.gsub(value, "<[^>]->", "")
                    value = string.gsub(value, "%s+", " ")

                    if string.find(value, "defend boats", 1, true)
                        or string.find(value, "defend boat", 1, true) then
                        sawDefendBoats = true
                        local current, required = string.match(value, "%[(%d+)%s*/%s*(%d+)%]")
                        if not current then
                            current, required = string.match(value, "(%d+)%s*/%s*(%d+)")
                        end
                        current = tonumber(current)
                        required = tonumber(required)
                        if current and required and required > 0 then
                            p1Progress = tostring(current) .. "/" .. tostring(required)
                            if current >= required then p2Evidence = true end
                        end
                    end

                    if string.find(value, "defeat armored", 1, true)
                        or string.find(value, "defeat armoured", 1, true)
                        or string.find(value, "kill armored titan", 1, true)
                        or string.find(value, "kill armoured titan", 1, true)
                        or string.find(value, "defeat reiner", 1, true) then
                        p2Evidence = true
                    end
                end
                if p2Evidence then break end
            end
        end
        if p2Evidence then break end
    end

    if p2Evidence then
        CombatSafety.ArmoredPhase = "P2"
        CombatSafety.ArmoredPhaseStatus = "P2 • ARMORED HARD LOCK"
        CombatSafety.ArmoredNextCycle = "Boss"
    elseif sawDefendBoats then
        CombatSafety.ArmoredPhase = "P1"
        CombatSafety.ArmoredPhaseStatus = "P1 • Defend Boats"
            .. (p1Progress and (" " .. p1Progress) or "")
    else
        CombatSafety.ArmoredPhase = "P1"
        CombatSafety.ArmoredPhaseStatus = "P1 • waiting for boats objective"
    end

    return CombatSafety.ArmoredPhase
end

local function spearBestPack()
    local entries = spearEntries()
    if #entries == 0 then
        return nil, {}, 0
    end


    local usable = {}
    for _, entry in ipairs(entries) do
        if entry.InRange then
            usable[#usable + 1] = entry
        end
    end
    if #usable == 0 then
        usable = entries
    end

    -- Carry V1 Armored routing. Detect Armored from ALL entries so P2 hard
    -- lock survives even if the current Pure pack is what is in normal range.
    local raidBossEntry = nil
    local armoredEntry = nil
    local pureUsable = {}

    for _, entry in ipairs(entries) do
        if CombatSafety.IsArmoredBoss(entry.Titan) then
            armoredEntry = entry
            break
        end
    end

    for _, entry in ipairs(usable) do
        if SpearRuntime.RaidBossName(entry.Titan) then
            raidBossEntry = raidBossEntry or entry
        else
            pureUsable[#pureUsable + 1] = entry
        end
    end

    if armoredEntry then
        local phase = CombatSafety.DetectArmoredPhase(armoredEntry.Titan)
        if phase == "P1" and #pureUsable > 0 then
            usable = pureUsable
        elseif phase == "P2"
            and #pureUsable > 0
            and CombatSafety.ArmoredNextCycle == "Pure" then
            usable = pureUsable
        else
            return armoredEntry.Part.Position, {armoredEntry}, 1
        end
    elseif raidBossEntry then
        return raidBossEntry.Part.Position, {raidBossEntry}, 1
    end

    local radius = 135
    local radiusSq = radius * radius
    local bestMembers = nil
    local bestCenter = nil
    local bestCount = 0
    local bestTravel = math.huge

    local root = spearRoot()

    for _, anchor in ipairs(usable) do
        local members = {}
        local sum = Vector3.zero

        for _, candidate in ipairs(usable) do
            local delta = candidate.Part.Position - anchor.Part.Position
            if delta:Dot(delta) <= radiusSq then
                members[#members + 1] = candidate
                sum += candidate.Part.Position
            end
        end

        local count = #members
        if count > 0 then
            local center = sum / count
            local travel = root and (root.Position - center).Magnitude or 0

            if count > bestCount or (count == bestCount and travel < bestTravel) then
                bestMembers = members
                bestCenter = center
                bestCount = count
                bestTravel = travel
            end
        end
    end

    return bestCenter, bestMembers or {}, bestCount
end

local function cancelSpearMovement()
    local tween = SpearRuntime.MoveTween
    SpearRuntime.MoveTween = nil

    if tween then
        pcall(function()
            tween:Cancel()
        end)
    end

    SpearRuntime.Moving = false
    CombatSafety.Moving = false
end

local function combatTravelToCFrame(targetCFrame, farmTravel)
    if typeof(targetCFrame) ~= "CFrame" then
        return false
    end

    local character = spearCharacter()
    local root = spearRoot()
    local humanoid = spearHumanoid()

    if not character or not root or not humanoid or humanoid.Health <= 0 then
        return false
    end

    cancelSpearMovement()
    rememberRootAnchor(root)

    root.Anchored = App.Values.MovementMode == "Teleport"
    root.AssemblyLinearVelocity = App.Values.MovementMode == "Regular"
        and Vector3.new(0, 20, 0)
        or Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    SpearRuntime.Moving = true
    CombatSafety.Moving = true

    if App.Values.MovementMode == "Teleport" then
        local success = true

        if farmTravel then
            local targetPosition = targetCFrame.Position
            local rotationOnly = targetCFrame - targetPosition
            local risePosition = Vector3.new(
                root.Position.X,
                targetPosition.Y,
                root.Position.Z
            )
            local riseCFrame = CFrame.new(risePosition) * rotationOnly

            success = pcall(function()
                character:PivotTo(riseCFrame)
            end)

            if success then
                task.wait(0.08)
                root = spearRoot()
                humanoid = spearHumanoid()
                success = root ~= nil
                    and humanoid ~= nil
                    and humanoid.Health > 0
                    and (root.Position - risePosition).Magnitude <= 16
            end

            if success then
                success = pcall(function()
                    character:PivotTo(targetCFrame)
                end)
            end

            if success then
                task.wait(0.08)
                root = spearRoot()
                humanoid = spearHumanoid()
                success = root ~= nil
                    and humanoid ~= nil
                    and humanoid.Health > 0
                    and (root.Position - targetPosition).Magnitude <= 16
            end
        else
            success = pcall(function()
                character:PivotTo(targetCFrame)
            end)
        end

        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        SpearRuntime.Moving = false
        CombatSafety.Moving = false
        return success
    end


    root.Anchored = false

    local speed =
        math.max(
            100,
            tonumber(App.Values.SmoothSpeed) or 900
        )

    local function replicatedStage(cf, maxDuration)
        if typeof(cf) ~= "CFrame" then return false end
        root = spearRoot()
        humanoid = spearHumanoid()
        if not root or not humanoid or humanoid.Health <= 0 then return false end

        local start = root.CFrame
        local distance = (root.Position - cf.Position).Magnitude
        if distance <= 1.5 then
            root.Anchored = false
            root.CFrame = CombatSafety.ProbeUprightCFrame(cf)
            root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
            root.AssemblyAngularVelocity = Vector3.zero
            return true
        end

        local duration = math.clamp(distance / speed, 0.12, maxDuration)
        local elapsed = 0
        local runService = game:GetService("RunService")

        while elapsed < duration do
            if not gui or not gui.Parent or (farmTravel and not combatFarmActive()) then return false end
            root = spearRoot()
            humanoid = spearHumanoid()
            if not root or not humanoid or humanoid.Health <= 0 then return false end

            local dt = runService.Heartbeat:Wait()
            elapsed += math.clamp(tonumber(dt) or 0, 1 / 240, 0.05)
            local t = math.clamp(elapsed / duration, 0, 1)
            local alpha = t * t * (3 - 2 * t)
            local frame = start:Lerp(cf, alpha)
            pcall(function()
                root.Anchored = false
                root.CFrame = CombatSafety.ProbeUprightCFrame(frame)
                root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
                root.AssemblyAngularVelocity = Vector3.zero
                humanoid.Sit = false
                humanoid.PlatformStand = false
            end)
        end

        for _ = 1, 2 do
            root = spearRoot()
            if not root then return false end
            pcall(function()
                root.Anchored = false
                root.CFrame = CombatSafety.ProbeUprightCFrame(cf)
                root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
                root.AssemblyAngularVelocity = Vector3.zero
            end)
            task.wait(0.05)
        end

        root = spearRoot()
        return root ~= nil and (root.Position - cf.Position).Magnitude <= 12
    end

    local success = true

    if farmTravel then
        local targetPosition = targetCFrame.Position
        local risePosition = Vector3.new(
            root.Position.X,
            targetPosition.Y,
            root.Position.Z
        )

        local rotationOnly =
            targetCFrame - targetPosition

        local riseCFrame =
            CFrame.new(risePosition) * rotationOnly


        if math.abs(root.Position.Y - targetPosition.Y) > 4 then
            success = replicatedStage(riseCFrame, 1.65)
        end


        if success and combatFarmActive() then
            success = replicatedStage(targetCFrame, 2.15)
        end
    else

        success = replicatedStage(targetCFrame, 1.55)
    end

    SpearRuntime.MoveTween = nil
    SpearRuntime.Moving = false
    CombatSafety.Moving = false

    if App.Values.MovementMode == "Regular" then
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
    else
        root.AssemblyLinearVelocity = Vector3.zero
    end
    root.AssemblyAngularVelocity = Vector3.zero

    return success
end

local function spearTravelToPack(center)
    if typeof(center) ~= "Vector3" then return false end
    local root = spearRoot()
    if not root then return false end

    -- Carry V1 P2: movement anchor is Armored NO MATTER which target gets the
    -- current attack cycle. Pure clearing never pulls the character away.
    if CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent
        and CombatSafety.DetectArmoredPhase(CombatSafety.ArmoredBoss) == "P2" then
        return CombatSafety.HoldArmoredV1(CombatSafety.ArmoredBoss, false)
    end

    -- If a Raid boss hold has already been armed by the attack gate, keep it.
    -- Do not let normal pack-follow movement pull us back down toward the boss.
    if CombatSafety.RaidBossHoldBoss
        and CombatSafety.RaidBossHoldBoss.Parent
        and typeof(CombatSafety.BaseHoldCFrame) == "CFrame" then
        SpearRuntime.HoldCFrame = CombatSafety.BaseHoldCFrame
        setCombatHoldCFrame(CombatSafety.BaseHoldCFrame)
        return combatSafetyHardSnap()
    end

    local existing = CombatSafety.BaseHoldCFrame
    if typeof(existing) == "CFrame" then
        local a = Vector3.new(existing.Position.X, 0, existing.Position.Z)
        local b = Vector3.new(center.X, 0, center.Z)
        local horizontal = (a - b).Magnitude

        local relocateDistance =
            (App.Values.MovementMode == "Regular") and 160
            or CombatSafety.RelocateDistance
        local relocateCooldown =
            (App.Values.MovementMode == "Regular") and 0.85
            or CombatSafety.RelocateCooldown

        if horizontal <= relocateDistance
            or os.clock() - CombatSafety.LastRelocateAt < relocateCooldown then
            local hold = existing
            SpearRuntime.HoldCFrame = hold
            setCombatHoldCFrame(hold)
            return combatSafetyHardSnap()
        end
    end

    local desired = center + Vector3.new(0, CombatSafety.SafeHeight, 0)
    local cf = CombatSafety.ProbeUprightCFrame(CFrame.new(desired))
    local ok = combatTravelToCFrame(cf, true)

    if ok then
        CombatSafety.LastRelocateAt = os.clock()
        SpearRuntime.HoldCFrame = cf
        setCombatHoldCFrame(cf)
        combatSafetyHardSnap()
    end
    return ok
end

local function spearExactNape(titan)
    if not titan or not titan.Parent then return nil end

    local hitboxes = titan:FindFirstChild("Hitboxes")
    local hit = hitboxes and hitboxes:FindFirstChild("Hit")
    local nape = hit and hit:FindFirstChild("Nape")
    if nape and nape:IsA("BasePart") and nape.Parent then
        return nape
    end

    local fallback = titan:FindFirstChild("Nape", true)
    if fallback and fallback:IsA("BasePart") and fallback.Parent then
        return fallback
    end

    return nil
end

local function spearRaidBossTitan(titan)
    return SpearRuntime.RaidBossName(titan)
end

local function spearFindRaidBoss(members)
    for _, entry in ipairs(members or {}) do
        local titan = entry and entry.Titan
        local nape = titan and spearExactNape(titan) or nil
        if spearRaidBossTitan(titan) and nape then
            return titan
        end
    end

    return nil
end

-- V15.6.4: dedicated normal-Raid boss safety.  This intentionally lives on
-- CombatSafety instead of creating more top-level locals; Premium is already
-- close to Luau's local-register ceiling.
CombatSafety.ClearRaidBossHold = function()
    CombatSafety.RaidBossHoldBoss = nil
    CombatSafety.RaidBossHoldY = nil
    CombatSafety.RaidBossEmergencyUntil = 0
end

CombatSafety.HoldRaidBoss = function(boss, forceSnap)
    local root = spearRoot()
    local nape = boss and spearExactNape(boss) or nil

    if not root or not nape or not boss.Parent then
        CombatSafety.ClearRaidBossHold()
        return false
    end

    local floorY = nape.Position.Y + (tonumber(CombatSafety.RaidBossHeight) or 320)

    if CombatSafety.RaidBossHoldBoss ~= boss then
        CombatSafety.RaidBossHoldBoss = boss
        CombatSafety.RaidBossHoldY = floorY
    else
        -- Never follow the same boss downward.  We may raise the safety floor
        -- if the boss climbs, but we do not descend with it mid-fight.
        CombatSafety.RaidBossHoldY =
            math.max(tonumber(CombatSafety.RaidBossHoldY) or floorY, floorY)
    end

    local flat = Vector3.new(
        root.Position.X - nape.Position.X,
        0,
        root.Position.Z - nape.Position.Z
    )
    if flat.Magnitude < 1 then
        flat = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    end
    if flat.Magnitude < 1 then
        flat = Vector3.new(1, 0, 0)
    end

    local desired =
        Vector3.new(
            nape.Position.X,
            CombatSafety.RaidBossHoldY,
            nape.Position.Z
        )
        + flat.Unit * (tonumber(CombatSafety.RaidBossHorizontalOffset) or 90)

    local hold = CombatSafety.ProbeUprightCFrame(CFrame.new(desired))
    setCombatHoldCFrame(hold)
    SpearRuntime.HoldCFrame = hold

    local drift = (root.Position - hold.Position).Magnitude
    if forceSnap == true or drift > 8 then
        combatSafetyHardSnap()
    end

    return true
end

CombatSafety.HoldArmoredV1 = function(boss, forceSnap)
    local root = spearRoot()
    local nape = boss and spearExactNape(boss) or nil
    if not root or not nape or not boss.Parent then return false end

    -- Stable Carry V1 uses a direct +220 hover over the live Armored Nape.
    local desired = nape.Position + Vector3.new(0, 220, 0)
    local hold = CombatSafety.ProbeUprightCFrame(CFrame.new(desired))
    setCombatHoldCFrame(hold)
    SpearRuntime.HoldCFrame = hold
    CombatSafety.RaidBossHoldBoss = boss
    CombatSafety.RaidBossHoldY = desired.Y

    local drift = (root.Position - hold.Position).Magnitude
    if forceSnap == true or drift > 8 then
        combatSafetyHardSnap()
    end
    return true
end

CombatSafety.RaidBossAbilityBlocked = function(boss)
    if not boss or not boss.Parent then
        CombatSafety.RaidBossAbilityBoss = nil
        CombatSafety.RaidBossAbilityBlockedNow = false
        CombatSafety.RaidBossAbilityReason = nil
        CombatSafety.RaidBossAbilityReleaseUntil = 0
        return false, nil
    end

    local bossName = string.lower(tostring(boss.Name or ""))
    bossName = string.gsub(bossName, "[^%w]", "")
    if string.find(bossName, "colossal", 1, true) or string.find(bossName, "bertholdt", 1, true) then
        return false, nil
    end

    local now = os.clock()
    if CombatSafety.RaidBossAbilityBoss == boss
        and now - (tonumber(CombatSafety.RaidBossAbilityScanAt) or 0) < 0.075 then
        return CombatSafety.RaidBossAbilityBlockedNow == true, CombatSafety.RaidBossAbilityReason
    end

    local blocked, reason = false, nil
    local function truthy(value)
        local text = string.lower(tostring(value))
        return value == true or value == 1 or text == "true" or text == "1"
            or text == "active" or text == "enabled" or text == "invulnerable"
            or text == "invincible" or text == "immune"
    end
    local function falsy(value)
        local text = string.lower(tostring(value))
        return value == false or value == 0 or text == "false" or text == "0"
            or text == "inactive" or text == "disabled"
    end
    local function inspect(node)
        if blocked or not node then return end
        local ok, attrs = pcall(function() return node:GetAttributes() end)
        if not ok or type(attrs) ~= "table" then return end
        for key, value in pairs(attrs) do
            local k = string.lower(tostring(key or ""))
            if (string.find(k, "invulner", 1, true) or string.find(k, "invinc", 1, true)
                or string.find(k, "immune", 1, true) or string.find(k, "iframe", 1, true))
                and truthy(value) then
                blocked, reason = true, tostring(key)
                return
            end
            if (string.find(k, "vulner", 1, true) or string.find(k, "damageable", 1, true)
                or string.find(k, "candamage", 1, true)) and falsy(value) then
                blocked, reason = true, tostring(key) .. " off"
                return
            end
        end
    end
    local humanoid = boss:FindFirstChildOfClass("Humanoid")
    inspect(boss); inspect(humanoid); inspect(boss:FindFirstChild("Hitboxes"))

    -- V16: only explicit immunity/damageability state may pause raid Spears.
    -- Generic ability/animation names no longer create sticky hold-fire states.
    if blocked then
        CombatSafety.RaidBossAbilityReleaseUntil = now + 0.18
    elseif CombatSafety.RaidBossAbilityBoss == boss
        and now < (tonumber(CombatSafety.RaidBossAbilityReleaseUntil) or 0) then
        blocked, reason = true, "state settling"
    end

    CombatSafety.RaidBossAbilityBoss = boss
    CombatSafety.RaidBossAbilityScanAt = now
    CombatSafety.RaidBossAbilityBlockedNow = blocked
    CombatSafety.RaidBossAbilityReason = reason
    return blocked, reason
end

CombatSafety.RaidBossAttackReady = function(boss)
    if not boss or not boss.Parent then
        CombatSafety.ClearRaidBossHold()
        return true
    end

    local abilityBlocked, abilityReason = CombatSafety.RaidBossAbilityBlocked(boss)
    if abilityBlocked then
        CombatSafety.RaidBossAbilityStatus = tostring(abilityReason or "ability")
        if CombatSafety.IsArmoredBoss(boss) then
            CombatSafety.HoldArmoredV1(boss, true)
        else
            CombatSafety.HoldRaidBoss(boss, true)
        end
        CombatSafety.AttackPauseUntil = math.max(
            tonumber(CombatSafety.AttackPauseUntil) or 0,
            os.clock() + 0.14
        )
        return false
    end
    CombatSafety.RaidBossAbilityStatus = nil

    if CombatSafety.IsArmoredBoss(boss) then
        local phase = CombatSafety.DetectArmoredPhase(boss)
        if phase == "P1" or phase == "P2" then
            CombatSafety.HoldArmoredV1(boss, true)
            local root = spearRoot()
            local nape = spearExactNape(boss)
            return root ~= nil and nape ~= nil
                and (root.Position - nape.Position).Magnitude >= 150
        end
    end

    if os.clock() < (CombatSafety.RaidBossEmergencyUntil or 0) then
        CombatSafety.HoldRaidBoss(boss, true)
        return false
    end

    local root = spearRoot()
    local nape = spearExactNape(boss)
    if not root or not nape then
        return false
    end

    local minimum = tonumber(CombatSafety.RaidBossMinDistance) or 310
    if (root.Position - nape.Position).Magnitude < minimum then
        CombatSafety.HoldRaidBoss(boss, true)
        CombatSafety.AttackPauseUntil =
            math.max(CombatSafety.AttackPauseUntil or 0, os.clock() + 0.28)
        return false
    end

    return true
end

local function spearBurstPositions(center, members)
    local positions = {}
    local usedTitans = setmetatable({}, {__mode = "k"})
    local limit = math.clamp(
        math.floor((tonumber(App.Values.SpearMultiHit) or 10) + 0.5),
        1,
        10
    )

    local function addEntry(entry)
        if #positions >= limit then
            return
        end

        if not entry or not entry.Titan or usedTitans[entry.Titan] then
            return
        end

        -- Carry V1 Pure cycles must never back-fill the Armored boss into the
        -- same multi-target burst; that recreates the mixed-registration bug.
        if CombatSafety.ArmoredBoss
            and entry.Titan == CombatSafety.ArmoredBoss then
            return
        end

        local part = spearExactNape(entry.Titan) or entry.Part
        if part and part.Parent then
            usedTitans[entry.Titan] = true
            positions[#positions + 1] = part.Position
        end
    end


    table.sort(members, function(a, b)
        return (a.Part.Position - center).Magnitude
            < (b.Part.Position - center).Magnitude
    end)

    for _, entry in ipairs(members) do
        addEntry(entry)
        if #positions >= limit then
            break
        end
    end


    if #positions < limit then
        local globalEntries = spearEntries()

        table.sort(globalEntries, function(a, b)
            local ad = a.Part and (a.Part.Position - center).Magnitude or math.huge
            local bd = b.Part and (b.Part.Position - center).Magnitude or math.huge
            return ad < bd
        end)

        for _, entry in ipairs(globalEntries) do
            addEntry(entry)
            if #positions >= limit then
                break
            end
        end
    end

    if #positions == 0 and typeof(center) == "Vector3" then
        positions[1] = center
    end

    return positions
end

local function spearBlastPositionSafe(position)
    if typeof(position) ~= "Vector3" then return false end
    local root = spearRoot()
    if not root or not root.Parent then return false end
    return (root.Position - position).Magnitude >= 150
end

-- V15.6.2: observed working hub sends the same small numeric value as the
-- fourth S_Explode argument for every hit in one burst (roughly 0.15-0.80).
SpearRuntime.spearBurstNonce = function()
    return math.random(150, 800) / 1000
end

local function spearEnsureSafeBlastDistance(center)
    if typeof(center) ~= "Vector3" then return false end
    local root = spearRoot()
    if not root or not root.Parent then return false end

    if CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent
        and CombatSafety.DetectArmoredPhase(CombatSafety.ArmoredBoss) == "P2" then
        CombatSafety.HoldArmoredV1(CombatSafety.ArmoredBoss, true)
        root = spearRoot()
        return root ~= nil and root.Parent ~= nil
            and (root.Position - center).Magnitude >= 150
    end

    if (root.Position - center).Magnitude >= 150 then return true end

    SpearRuntime.LastStatus = "Repositioning for safe spear blast"
    local desired = center + Vector3.new(0, math.max(220, tonumber(CombatSafety.SafeHeight) or 300), 0)
    local target = CombatSafety.ProbeUprightCFrame(CFrame.new(desired))
    combatTravelToCFrame(target, true)
    combatSafetyHardSnap()

    root = spearRoot()
    return root ~= nil and root.Parent ~= nil
        and (root.Position - center).Magnitude >= 150
end

local function spearFireBurst(center, members)
    if SpearRuntime.Busy or SpearRuntime.RefillBusy then return false end
    if os.clock() < (CombatSafety.AttackPauseUntil or 0) then return false end

    local raidBoss = spearFindRaidBoss(members)
    if raidBoss and not CombatSafety.RaidBossAttackReady(raidBoss) then
        SpearRuntime.LastStatus = CombatSafety.RaidBossAbilityStatus and ("Raid boss • hold fire • " .. tostring(CombatSafety.RaidBossAbilityStatus)) or "Raid boss • retreating to safe hold"
        SpearRuntime.NextFireAt = os.clock() + 0.18
        return false
    end

    combatSafetyHardSnap()

    if not spearEnsureSafeBlastDistance(center) then
        SpearRuntime.LastStatus = "Holding fire • unsafe blast distance"
        SpearRuntime.NextFireAt = os.clock() + 0.12
        return false
    end

    local now = os.clock()
    if now < SpearRuntime.NextFireAt then
        return false
    end

    local ammo = spearReadAmmo()

    if ammo ~= nil and ammo <= 0 then
        SpearRuntime.LastStatus = "No spear ammo"
        return false
    end

    local spearName = spearFindAvailableName()
    if not spearName then
        SpearRuntime.LastStatus = "No numbered spear object available"
        return false
    end

    local getRemote, postRemote = spearRemotes()
    if not getRemote or not getRemote:IsA("RemoteFunction") then
        SpearRuntime.LastStatus = "GET remote missing"
        return false
    end
    if not postRemote or not postRemote:IsA("RemoteEvent") then
        SpearRuntime.LastStatus = "POST remote missing"
        return false
    end

    SpearRuntime.Busy = true
    SpearRuntime.LastError = nil
    SpearRuntime.LastStatus = "Arming spear " .. tostring(spearName)

    local okFire, accepted = pcall(function()
        return getRemote:InvokeServer("Spears", "S_Fire", tostring(spearName))
    end)

    if not okFire or accepted ~= true then
        SpearRuntime.LastError = okFire and "S_Fire rejected" or tostring(accepted)
        SpearRuntime.LastStatus = "S_Fire failed"
        SpearRuntime.NextFireAt = os.clock() + 0.14
        SpearRuntime.Busy = false
        return false
    end

    local character = spearCharacter()
    local armedStarted = os.clock()

    while character
        and character.Parent
        and character:GetAttribute("Current_Spear") == nil
        and os.clock() - armedStarted < 0.60 do
        task.wait(0.01)
    end

    task.wait(0.105)

    local explodeNonce = SpearRuntime.spearBurstNonce()
    local targets = {}
    local sent = 0
    local usedRaidBossMultiHit = false

    if raidBoss then
        usedRaidBossMultiHit = true
    else

        targets = spearBurstPositions(center, members)
        if App.Safety and App.Safety.GuardSpearPositions then
            targets = App.Safety.GuardSpearPositions(targets)
        end

        if #targets == 0 then
            SpearRuntime.LastStatus =
                (App.Safety and App.Safety.FinalTitanStatus)
                or "Waiting before final Titan"
            SpearRuntime.NextFireAt = os.clock() + 0.08
            SpearRuntime.Busy = false
            return false
        end
    end

    local okExplode, explodeErr = pcall(function()
        if raidBoss then
            local repeatCount = math.clamp(
                math.floor((tonumber(App.Values.RaidBossMultiHit) or 1) + 0.5),
                1,
                10
            )


            for index = 1, repeatCount do
                if not raidBoss.Parent then break end

                local nape = spearExactNape(raidBoss)
                if not nape or not nape.Parent then break end

                -- V15.6.44 RAID SPEARS: raid bosses are a singleton target by design.
                -- The normal final-Titan guard already ran in spearFarmStep; applying
                -- GuardSpearPositions again here could erase the only boss position and
                -- make Spears move/use skills forever without ever firing in Raids.
                local position = nape.Position
                if position and spearBlastPositionSafe(position) then
                    postRemote:FireServer("Spears", "S_Explode", position, explodeNonce)
                    sent += 1
                end

            end
        else
            for _, position in ipairs(targets) do
                if spearBlastPositionSafe(position) then
                    postRemote:FireServer("Spears", "S_Explode", position, explodeNonce)
                    sent += 1
                end
            end
        end
    end)

    if not okExplode or sent <= 0 then
        SpearRuntime.LastError = tostring(explodeErr or "no valid explode target")
        SpearRuntime.LastStatus = "S_Explode failed"
        SpearRuntime.NextFireAt = os.clock() + 0.14
        SpearRuntime.Busy = false
        return false
    end

    SpearRuntime.Shots += 1
    SpearRuntime.LastShotAt = os.clock()
    SpearRuntime.LastStatus = (usedRaidBossMultiHit and "Raid Boss Multi-Hit x" or "Spear Multi-Hit x") .. tostring(sent)


    if CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent then
        local armoredPhase = CombatSafety.DetectArmoredPhase(CombatSafety.ArmoredBoss)
        if armoredPhase == "P2" then
            if raidBoss == CombatSafety.ArmoredBoss then
                CombatSafety.ArmoredNextCycle = "Pure"
            else
                CombatSafety.ArmoredNextCycle = "Boss"
            end
        else
            CombatSafety.ArmoredNextCycle = "Boss"
        end
    end

    SpearRuntime.NextFireAt = os.clock() + 1.20
    SpearRuntime.Busy = false
    return true
end

local function spearFindRefillStation()
    local unclimbable = workspace:FindFirstChild("Unclimbable")
    local reloads = unclimbable and unclimbable:FindFirstChild("Reloads")
    local gasTanks = reloads and reloads:FindFirstChild("GasTanks")
    local direct = gasTanks and gasTanks:FindFirstChild("Refill")
    if direct and direct:IsA("BasePart") then return direct end

    local props = unclimbable and unclimbable:FindFirstChild("Props")
    local hq = props and props:FindFirstChild("HQ")
    local hqGas = hq and hq:FindFirstChild("GasTanks")
    local hqDirect = hqGas and hqGas:FindFirstChild("Refill")
    if hqDirect and hqDirect:IsA("BasePart") then return hqDirect end

    if unclimbable then
        for _, object in ipairs(unclimbable:GetDescendants()) do
            if object:IsA("BasePart") and string.lower(object.Name) == "refill" then return object end
        end
    end

    local best, bestScore = nil, -math.huge
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("BasePart") then
            local score = string.lower(object.Name) == "refill" and 60 or 0
            local node = object.Parent
            for _ = 1, 7 do
                if not node then break end
                local name = string.lower(tostring(node.Name or ""))
                if string.find(name, "gas", 1, true) then score += 18 end
                if string.find(name, "reload", 1, true) or string.find(name, "station", 1, true)
                    or string.find(name, "supply", 1, true) then score += 10 end
                node = node.Parent
            end
            if score > bestScore then best, bestScore = object, score end
        end
    end
    return bestScore >= 60 and best or nil
end

local function spearDirectReload(station)
    if not station or not station.Parent then return false end
    local getRemote = select(1, spearRemotes())
    if not getRemote or not getRemote:IsA("RemoteFunction") then return false end
    local ok = pcall(function() getRemote:InvokeServer("Attacks", "Reload", station) end)
    return ok
end

local function spearRefillTargetReached(target)
    local ammo = spearReadAmmo()
    return ammo ~= nil and ammo >= target, ammo
end

local function spearBestStationCFrame(station)
    local root = spearRoot()
    if not root or not station then return nil end
    local sx, sz = station.Size.X * 0.5 + 7, station.Size.Z * 0.5 + 7
    local candidates = {
        (station.CFrame * CFrame.new(0,2,-sz)).Position,
        (station.CFrame * CFrame.new(0,2,sz)).Position,
        (station.CFrame * CFrame.new(-sx,2,0)).Position,
        (station.CFrame * CFrame.new(sx,2,0)).Position,
    }
    table.sort(candidates,function(a,b) return (root.Position-a).Magnitude < (root.Position-b).Magnitude end)
    return CFrame.lookAt(candidates[1], station.Position)
end

local function spearDoRefill()
    if SpearRuntime.RefillBusy then return end
    SpearRuntime.RefillBusy = true
    SpearRuntime.RefillLatched = true
    local target = math.max(1, math.floor((tonumber(spearReadCapacity()) or 8) + 0.5))
    SpearRuntime.RefillTarget = target
    local root = spearRoot()
    local returnCFrame = root and root.CFrame or nil
    local station = spearFindRefillStation()
    if not station then
        SpearRuntime.LastStatus = "Spear refill station not found"
        SpearRuntime.NextRefillAt = os.clock() + 1.0
        SpearRuntime.RefillBusy = false
        return
    end

    local success, lastAmmo, lastRequestAt = false, tonumber(spearReadAmmo()) or 0, -math.huge
    for attempt = 1, 4 do
        if not gui or not gui.Parent or App.Values.AutoSpearRefill ~= true then break end
        local reached, ammo = spearRefillTargetReached(target)
        if tonumber(ammo) then lastAmmo = tonumber(ammo) end
        if reached then success = true break end
        station = (station and station.Parent) and station or spearFindRefillStation()
        if not station then break end
        root = spearRoot()
        if root and (root.Position - station.Position).Magnitude > 25 then
            SpearRuntime.LastStatus = "Spear refill • moving to station • " .. tostring(math.floor(lastAmmo+0.5)) .. "/" .. tostring(target)
            local cf = spearBestStationCFrame(station)
            if cf then combatTravelToCFrame(cf, false) end
        end
        if lastRequestAt > 0 then
            local waitUntil = lastRequestAt + 4.0
            while gui and gui.Parent and os.clock() < waitUntil do
                local done, live = spearRefillTargetReached(target)
                if tonumber(live) then lastAmmo = tonumber(live) end
                SpearRuntime.LastStatus = "Spear refill • " .. tostring(math.floor(lastAmmo+0.5)) .. "/" .. tostring(target)
                if done then success = true break end
                task.wait(0.08)
            end
            if success then break end
        end
        lastRequestAt = os.clock()
        spearDirectReload(station)
        local observeUntil = os.clock() + 2.1
        while gui and gui.Parent and os.clock() < observeUntil do
            local done, live = spearRefillTargetReached(target)
            if tonumber(live) then lastAmmo = tonumber(live) end
            SpearRuntime.LastStatus = "Spear refill • " .. tostring(math.floor(lastAmmo+0.5)) .. "/" .. tostring(target)
            if done then success = true break end
            task.wait(0.07)
        end
        if success then break end
    end

    local finalAmmo = tonumber(spearReadAmmo()) or lastAmmo
    success = success or finalAmmo >= target
    SpearRuntime.RefillLatched = not success
    SpearRuntime.LastStatus = success
        and ("Spear refill complete • " .. tostring(target) .. "/" .. tostring(target))
        or ("Spear refill pending • " .. tostring(math.floor(finalAmmo+0.5)) .. "/" .. tostring(target))

    local colossalOwns = App.Colossal and App.Colossal.OwnsCombat and App.Colossal.OwnsCombat()
    if success and returnCFrame and not colossalOwns and gui and gui.Parent then
        combatTravelToCFrame(returnCFrame, false)
        SpearRuntime.HoldCFrame = returnCFrame
        setCombatHoldCFrame(returnCFrame)
    end
    SpearRuntime.NextFireAt = success and 0 or SpearRuntime.NextFireAt
    SpearRuntime.NextRefillAt = os.clock() + (success and 0.30 or 0.85)
    SpearRuntime.RefillBusy = false
end

local function spearRefillStep()
    if App.TransitionGuard and App.TransitionGuard.BlockGameplay and App.TransitionGuard.BlockGameplay() then return end
    if App.Values.AutoSpearRefill ~= true then SpearRuntime.RefillLatched = false return end
    if not spearEquipped() or SpearRuntime.RefillBusy or SpearRuntime.Busy then return end
    if os.clock() < (tonumber(SpearRuntime.NextRefillAt) or 0) then return end
    local target = math.max(1, math.floor((tonumber(spearReadCapacity()) or tonumber(SpearRuntime.RefillTarget) or 8) + 0.5))
    local ammo = spearReadAmmo()
    if ammo == nil then return end
    if ammo >= target then SpearRuntime.RefillLatched=false; SpearRuntime.RefillTarget=target; return end
    if ammo <= 0 then SpearRuntime.RefillLatched = true end
    if SpearRuntime.RefillLatched ~= true then return end
    task.spawn(spearDoRefill)
end

local function spearFarmStep()
    if App.Colossal
        and App.Colossal.OwnsCombat
        and App.Colossal.OwnsCombat() then
        return
    end

    if App.Values.AutoFarmSpears ~= true then
        return
    end

    if App.Safety
        and App.Safety.AttackHold then
        SpearRuntime.LastStatus =
            "Auto Die streak threshold"
        return
    end
    if App.TransitionGuard and App.TransitionGuard.BlockGameplay
        and App.TransitionGuard.BlockGameplay() then
        return
    end

    if App.Safety
        and App.Safety.ShouldPauseFinalTitan
        and App.Safety.ShouldPauseFinalTitan() then
        SpearRuntime.LastStatus =
            tostring(App.Safety.FinalTitanStatus or "Waiting before final Titan")
        return
    end

    if SpearRuntime.RefillBusy or SpearRuntime.Busy or CombatSafety.Moving then
        return
    end

    if not spearEquipped() then
        SpearRuntime.LastStatus = "Equip Thunder Spears"
        return
    end

    local character = spearCharacter()
    local humanoid = spearHumanoid()
    local root = spearRoot()

    if not character or not root or not humanoid or humanoid.Health <= 0 then
        return
    end

    local ammo = spearReadAmmo()
    if App.Values.AutoSpearRefill
        and ammo ~= nil
        and ammo <= 0 then
        spearRefillStep()
        return
    end

    local center, members, count = spearBestPack()
    if not center or count <= 0 then
        SpearRuntime.LastStatus = "Scanning for Titans"
        return
    end

    SpearRuntime.LastTarget = center
    spearTravelToPack(center)

    if App.Values.AutoFarmSpears ~= true or SpearRuntime.RefillBusy then
        return
    end

    spearFireBurst(center, members)
end

local function stopSpearRuntime()
    cancelSpearMovement()
    SpearRuntime.Busy = false
    SpearRuntime.RefillBusy = false
    SpearRuntime.HoldCFrame = nil
    restoreRootAnchor()

    if App.Safety
        and App.Safety.ResetFinalTitanPacing then
        App.Safety.ResetFinalTitanPacing()
    end
end


local BladeRuntime = {
    Busy = false,
    NextCycleAt = 0,
    LastStatus = "Idle",
    LastRegisters = 0,
    LastSlashes = 0,
    TotalRegisters = 0,
    TotalSlashes = 0,
}

local function bladeEquipped()
    return player and player:GetAttribute("Weapon") == "Blades"
end

local function bladeExactNape(titan)
    if not titan or not titan.Parent then
        return nil
    end

    local hitboxes = titan:FindFirstChild("Hitboxes")
    local hit = hitboxes and hitboxes:FindFirstChild("Hit")
    local exact = hit and hit:FindFirstChild("Nape")

    if exact and exact:IsA("BasePart") and exact.Parent then
        return exact
    end


    local fallback = titan:FindFirstChild("Nape", true)
    return fallback and fallback:IsA("BasePart") and fallback or nil
end

local function bladeCandidateEntries()
    local folder = workspace:FindFirstChild("Titans")
    if not folder then
        return {}
    end

    local root = spearRoot()
    local entries = {}

    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan) then
            local nape = bladeExactNape(titan)
            if nape then
                local raidBoss = SpearRuntime.RaidBossName
                    and SpearRuntime.RaidBossName(titan)

                if not raidBoss
                    or not CombatSafety.RaidBossTargetAllowed
                    or CombatSafety.RaidBossTargetAllowed(titan, nape) then
                    entries[#entries + 1] = {
                        Titan = titan,
                        Part = nape,
                        Distance = root and (root.Position - nape.Position).Magnitude or 0,
                    }
                end
            end
        end
    end

    return entries
end

local function bladeBuildTargets(center, packMembers)
    local limit = math.clamp(
        math.floor((tonumber(App.Values.BladeMultiHit) or 10) + 0.5),
        1,
        10
    )

    local output = {}
    local seen = setmetatable({}, {__mode = "k"})

    local function add(entry)
        if #output >= limit or not entry or not entry.Titan or seen[entry.Titan] then
            return
        end

        local nape = bladeExactNape(entry.Titan)
        if isTitanAlive(entry.Titan) and nape then
            seen[entry.Titan] = true
            output[#output + 1] = {
                Titan = entry.Titan,
                Part = nape,
            }
        end
    end

    table.sort(packMembers or {}, function(a, b)
        local ad = a.Part and (a.Part.Position - center).Magnitude or math.huge
        local bd = b.Part and (b.Part.Position - center).Magnitude or math.huge
        return ad < bd
    end)

    for _, entry in ipairs(packMembers or {}) do
        add(entry)
        if #output >= limit then break end
    end

    if #output < limit then
        local all = bladeCandidateEntries()

        table.sort(all, function(a, b)
            local ad = a.Part and (a.Part.Position - center).Magnitude or math.huge
            local bd = b.Part and (b.Part.Position - center).Magnitude or math.huge
            return ad < bd
        end)

        for _, entry in ipairs(all) do
            add(entry)
            if #output >= limit then break end
        end
    end

    return output
end

local function isRaidBossTitan(titan)
    if not titan or not titan.Parent then return false end

    local name = string.lower(tostring(titan.Name or ""))
    name = string.gsub(name, "[^%w]", "")

    return string.find(name, "armoredtitan", 1, true) ~= nil
        or string.find(name, "armourtitan", 1, true) ~= nil
        or string.find(name, "attacktitan", 1, true) ~= nil
        or string.find(name, "femaletitan", 1, true) ~= nil
        or string.find(name, "colossaltitan", 1, true) ~= nil
end


App.SafeFarm = App.SafeFarm or {
    Busy = false,
    NextAt = 0,
    LastStatus = "Off",
    FXFolder = nil,
    SwingAnimation = nil,
    SwingTrack = nil,
    SwingCharacter = nil,
}

App.SafeFarm.ReleaseAll = function()
    App.SafeFarm.Busy = false

    if App.SafeFarm.SwingTrack then
        pcall(function()
            App.SafeFarm.SwingTrack:Stop(0.05)
        end)
    end

    App.SafeFarm.SwingTrack = nil
    App.SafeFarm.SwingCharacter = nil

    if App.SafeFarm.FXFolder
        and App.SafeFarm.FXFolder.Parent then
        pcall(function()
            App.SafeFarm.FXFolder:Destroy()
        end)
    end

    App.SafeFarm.FXFolder = nil
end

App.SafeFarm.ResolveSwingAnimation = function()
    local cached = App.SafeFarm.SwingAnimation

    if cached
        and cached.Parent
        and cached:IsA("Animation")
        and tostring(cached.AnimationId or "") ~= "" then
        return cached
    end

    local best = nil
    local bestScore = -math.huge
    local checked = 0

    local roots = {
        player.Character,
        player:FindFirstChildOfClass("Backpack"),
        ReplicatedStorage:FindFirstChild("Assets"),
    }

    for rootIndex, root in ipairs(roots) do
        if root then
            local objects = {root}

            for _, object in ipairs(root:GetDescendants()) do
                objects[#objects + 1] = object
                checked += 1
                if checked >= 3500 then break end
            end

            for _, object in ipairs(objects) do
                if object:IsA("Animation")
                    and tostring(object.AnimationId or "") ~= "" then

                    local name =
                        string.lower(tostring(object.Name or ""))

                    local path =
                        string.lower(tostring(object:GetFullName()))

                    local score = 0
                    if string.find(name, "slash", 1, true) then score += 120 end
                    if string.find(name, "swing", 1, true) then score += 115 end
                    if string.find(name, "attack", 1, true) then score += 70 end
                    if string.find(name, "blade", 1, true) then score += 55 end
                    if string.find(path, "blade", 1, true) then score += 35 end
                    if string.find(path, "attack", 1, true) then score += 15 end
                    if rootIndex <= 2 then score += 35 end

                    if string.find(path, "titan", 1, true)
                        or string.find(path, "spear", 1, true)
                        or string.find(path, "horse", 1, true)
                        or string.find(path, "injur", 1, true) then
                        score -= 120
                    end

                    if score > bestScore then
                        bestScore = score
                        best = object
                    end
                end
            end

            if checked >= 3500 then break end
        end
    end

    if bestScore < 55 then
        best = nil
    end

    App.SafeFarm.SwingAnimation = best
    return best
end

App.SafeFarm.PlayBladeSwing = function()
    local character = spearCharacter()
    local humanoid = spearHumanoid()

    if not character or not humanoid then
        return false
    end

    local animator =
        humanoid:FindFirstChildOfClass("Animator")

    if not animator then
        animator = Instance.new("Animator")
        animator.Parent = humanoid
    end

    local animation =
        App.SafeFarm.ResolveSwingAnimation()

    if not animation then
        return false
    end

    if App.SafeFarm.SwingCharacter ~= character then
        App.SafeFarm.SwingTrack = nil
        App.SafeFarm.SwingCharacter = character
    end

    local track = App.SafeFarm.SwingTrack

    if not track then
        local ok, loaded =
            pcall(function()
                return animator:LoadAnimation(animation)
            end)

        if not ok or not loaded then
            return false
        end

        track = loaded
        App.SafeFarm.SwingTrack = track

        pcall(function()
            track.Priority = Enum.AnimationPriority.Action4
        end)
    end

    pcall(function()
        if track.IsPlaying then
            track:Stop(0.025)
        end
        track:Play(0.035, 1, 1.08)
    end)

    return true
end

App.SafeFarm.GroundPoint = function(root, side)
    local character = spearCharacter()
    local sideSign = tonumber(side) or 1

    local lateral =
        root.CFrame.RightVector
        * (8 + math.random(0, 5))
        * sideSign

    local forward =
        root.CFrame.LookVector
        * math.random(-4, 10)

    local castOrigin =
        root.Position
        + lateral
        + forward
        + Vector3.new(0, 12, 0)

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude

    local excluded = {}
    if character then excluded[#excluded + 1] = character end

    local titans = workspace:FindFirstChild("Titans")
    if titans then excluded[#excluded + 1] = titans end

    params.FilterDescendantsInstances = excluded
    params.IgnoreWater = false

    local result =
        workspace:Raycast(
            castOrigin,
            Vector3.new(0, -420, 0),
            params
        )

    if result then
        return result.Position + Vector3.new(0, 0.12, 0)
    end

    return root.Position
        + lateral
        + forward
        - Vector3.new(
            0,
            math.max(
                10,
                tonumber(CombatSafety.SafeHeight) or 45
            ),
            0
        )
end

App.SafeFarm.FireGroundHooks = function()
    local root = spearRoot()
    if not root then return 0 end

    if App.SafeFarm.FXFolder
        and App.SafeFarm.FXFolder.Parent then
        pcall(function()
            App.SafeFarm.FXFolder:Destroy()
        end)
    end

    local folder = Instance.new("Folder")
    folder.Name =
        "SliceHub_SafeFarmFX_"
        .. tostring(player.UserId)
    folder.Parent = workspace
    App.SafeFarm.FXFolder = folder

    local hookCount = math.random(1, 2)

    for index = 1, hookCount do
        local side =
            hookCount == 1
            and (math.random(0, 1) == 0 and -1 or 1)
            or (index == 1 and -1 or 1)

        local origin = Instance.new("Attachment")
        origin.Name = "SafeFarmHookOrigin"
        origin.Position =
            Vector3.new(side * 1.15, -0.45, 0.20)
        origin.Parent = root

        local targetPart = Instance.new("Part")
        targetPart.Name = "SafeFarmGroundHook"
        targetPart.Size = Vector3.new(0.08, 0.08, 0.08)
        targetPart.Transparency = 1
        targetPart.Anchored = true
        targetPart.CanCollide = false
        targetPart.CanTouch = false
        targetPart.CanQuery = false
        targetPart.CFrame = CFrame.new(origin.WorldPosition)
        targetPart.Parent = folder

        local target = Instance.new("Attachment")
        target.Name = "SafeFarmGroundTarget"
        target.Parent = targetPart

        local beam = Instance.new("Beam")
        beam.Name = "SafeFarmHookCable"
        beam.Attachment0 = origin
        beam.Attachment1 = target
        beam.FaceCamera = true
        beam.Width0 = 0.055
        beam.Width1 = 0.045
        beam.LightInfluence = 0
        beam.LightEmission = 0.15
        beam.Transparency =
            NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.08),
                NumberSequenceKeypoint.new(1, 0.18),
            })
        beam.Color =
            ColorSequence.new(Color3.fromRGB(190, 196, 205))
        beam.Parent = folder

        local groundPoint =
            App.SafeFarm.GroundPoint(root, side)

        local tween =
            TweenService:Create(
                targetPart,
                TweenInfo.new(
                    0.075,
                    Enum.EasingStyle.Quad,
                    Enum.EasingDirection.Out
                ),
                {CFrame = CFrame.new(groundPoint)}
            )

        tween:Play()

        task.delay(0.42, function()
            if origin and origin.Parent then
                pcall(function()
                    origin:Destroy()
                end)
            end
        end)
    end

    return hookCount
end

App.SafeFarm.ClearGroundHooks = function()
    local folder = App.SafeFarm.FXFolder
    App.SafeFarm.FXFolder = nil

    if folder and folder.Parent then
        pcall(function()
            folder:Destroy()
        end)
    end
end

App.SafeFarm.Step = function(center, packMembers)
    if App.Values.SafeFarm ~= true
        or App.Values.AutoFarmBlades ~= true then
        return false
    end

    if App.SafeFarm.Busy
        or BladeRuntime.Busy
        or os.clock() < (App.SafeFarm.NextAt or 0) then
        return false
    end

    local _, post = spearRemotes()

    if not post or not post:IsA("RemoteEvent") then
        App.SafeFarm.LastStatus = "POST remote missing"
        App.SafeFarm.NextAt = os.clock() + 0.30
        return false
    end

    local targets =
        bladeBuildTargets(center, packMembers)

    if App.Safety and App.Safety.GuardBladeTargets then
        targets = App.Safety.GuardBladeTargets(targets)
    end

    if #targets == 0 then
        App.SafeFarm.LastStatus =
            (App.Safety and App.Safety.FinalTitanStatus)
            or "No exact Napes"
        App.SafeFarm.NextAt = os.clock() + 0.06
        return false
    end

    App.SafeFarm.Busy = true
    BladeRuntime.Busy = true

    task.spawn(function()
        local hookCount = 0
        local slashCount = 0
        local registerCount = 0
        local swingCount = 0

        local ok, err =
            pcall(function()

                hookCount =
                    App.SafeFarm.FireGroundHooks()

                App.SafeFarm.LastStatus =
                    "Ground hooks x"
                    .. tostring(hookCount)
                    .. " • preparing swing"

                task.wait(0.085)

                local bankStart = 1

                while bankStart <= #targets do
                    local bankEnd =
                        math.min(#targets, bankStart + 9)

                    local bank = {}

                    for index = bankStart, bankEnd do
                        bank[#bank + 1] = targets[index]
                    end

                    combatSafetyHardSnap()

                    if App.SafeFarm.PlayBladeSwing() then
                        swingCount += 1
                    end


                    task.wait(0.055)

                    post:FireServer("Attacks", "Slash", true)
                    slashCount += 1

                    for _, entry in ipairs(bank) do
                        local titan = entry and entry.Titan
                        local nape =
                            titan
                            and bladeExactNape(titan)
                            or nil

                        if isTitanAlive(titan) and nape then
                            local repeatCount = isRaidBossTitan(titan)
                                and math.clamp(
                                    math.floor((tonumber(App.Values.RaidBossMultiHit) or 1) + 0.5),
                                    1,
                                    10
                                )
                                or 1

                            for _ = 1, repeatCount do
                                if not isTitanAlive(titan) or not nape.Parent then break end
                                post:FireServer(
                                    "Hitboxes",
                                    "Register",
                                    nape,
                                    math.random(625, 850)
                                )
                                registerCount += 1
                            end
                        end
                    end

                    bankStart = bankEnd + 1

                    if bankStart <= #targets then
                        task.wait(0.105)
                    end
                end

                task.wait(0.055)
            end)

        App.SafeFarm.ClearGroundHooks()
        BladeRuntime.Busy = false
        App.SafeFarm.Busy = false

        if not ok then
            App.SafeFarm.LastStatus =
                "Safe Farm recovered • "
                .. tostring(err)
            BladeRuntime.LastStatus =
                App.SafeFarm.LastStatus
            App.SafeFarm.NextAt =
                os.clock() + 0.18
            return
        end

        BladeRuntime.LastSlashes = slashCount
        BladeRuntime.LastRegisters = registerCount
        BladeRuntime.TotalSlashes += slashCount
        BladeRuntime.TotalRegisters += registerCount

        App.SafeFarm.LastStatus =
            string.format(
                "Hooks x%d • Swing x%d • Reg %d",
                hookCount,
                swingCount,
                registerCount
            )

        BladeRuntime.LastStatus =
            "Safe Farm • "
            .. App.SafeFarm.LastStatus

        App.SafeFarm.NextAt =
            os.clock() + 0.11
    end)

    return true
end

App.Safety = App.Safety or {
    Status = "Off",
    PlayerSafetyStatus = "Off",
    PlayerLeaveTriggered = false,
    PlayerSeenSince = 0,
    PlayerSeenName = "",
    LastDetectedPlayer = "",
    LastStreak = nil,
    Armed = true,
    PendingDeath = false,
    AttackHold = false,

    FinalTitanKey = "",
    FinalTitanStartedAt = 0,
    FinalTitanCompleted = {},
    FinalTitanStatus = "Ready",
    BreachCacheAt = 0,
    BreachCached = false,
}

App.Safety.ReadStreak = function()
    local value = player:GetAttribute("Streak")
    value = tonumber(value)

    if value == nil then
        return nil
    end

    return math.max(
        0,
        math.floor(value + 0.5)
    )
end


App.Safety.ResetFinalTitanPacing = function()
    App.Safety.FinalTitanKey = ""
    App.Safety.FinalTitanStartedAt = 0
    App.Safety.FinalTitanCompleted = {}
    App.Safety.FinalTitanStatus = "Ready"
end

App.Safety.AliveTitanCount = function()
    local entries = nil

    if App.Values.AutoFarmBlades == true
        and type(bladeCandidateEntries) == "function" then
        entries = bladeCandidateEntries()
    elseif App.Values.AutoFarmSpears == true
        and type(spearEntries) == "function" then
        entries = spearEntries()
    end

    if type(entries) == "table" then
        if #entries >= 2 then return 2 end
        return #entries
    end

    local folder = workspace:FindFirstChild("Titans")
    if not folder then return 0 end

    local alive = 0
    for _, titan in ipairs(folder:GetChildren()) do
        if isTitanAlive(titan) then
            local targetable = bladeExactNape(titan) or spearTitanPart(titan)
            if targetable then
                alive += 1
                if alive >= 2 then return 2 end
            end
        end
    end

    return alive
end

App.Safety.IsBreachMission = function()
    local now = os.clock()

    if now - (App.Safety.BreachCacheAt or 0) < 0.45 then
        return App.Safety.BreachCached == true
    end

    App.Safety.BreachCacheAt = now

    local selected =
        string.lower(
            tostring(App.Values.LobbyObjective or "")
        )

    local map =
        string.lower(
            tostring(App.Values.LobbyMap or "")
        )

    if selected == "breach"
        and (map == "" or map == "shiganshina") then
        App.Safety.BreachCached = true
        return true
    end

    local workspaceObjective =
        string.lower(
            tostring(
                workspace:GetAttribute("Objective")
                or ""
            )
        )

    if workspaceObjective == "breach" then
        App.Safety.BreachCached = true
        return true
    end

    local function textSaysBreach(text)
        text = string.lower(tostring(text or ""))
        return string.find(text, "breach", 1, true) ~= nil
            or string.find(text, "barricade", 1, true) ~= nil
    end

    local interface = playerGui:FindFirstChild("Interface")

    if interface then
        local checked = 0

        for _, object in ipairs(interface:GetDescendants()) do
            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then

                checked += 1

                if textSaysBreach(object.Text) then
                    App.Safety.BreachCached = true
                    return true
                end

                if checked >= 360 then break end
            end
        end
    end

    for _, key in ipairs({
        "Objective",
        "MissionObjective",
        "Mission_Objective",
        "Mode",
    }) do
        if textSaysBreach(workspace:GetAttribute(key)) then
            App.Safety.BreachCached = true
            return true
        end
    end

    App.Safety.BreachCached = false
    return false
end

App.Safety.BreachPhase2Complete = function()
    if App.Safety.IsBreachMission() ~= true then
        return nil
    end

    local function progressReady(current, required)
        current = tonumber(current)
        required = tonumber(required)

        if current
            and required
            and required >= 5
            and current >= required then
            return true
        end

        if current
            and current >= 5
            and (required == nil or required >= 5) then
            return true
        end

        return false
    end


    local interface = playerGui:FindFirstChild("Interface")

    if interface then
        local checked = 0

        for _, object in ipairs(interface:GetDescendants()) do
            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then

                checked += 1

                local value =
                    string.lower(
                        tostring(object.Text or "")
                    )

                if string.find(value, "defend hq", 1, true)
                    or string.find(value, "defend headquarters", 1, true) then

                    local current, required =
                        string.match(
                            value,
                            "[%[%(%s]*(%d+)%s*/%s*(%d+)"
                        )

                    if progressReady(current, required) then
                        return true
                    end
                end

                if checked >= 420 then break end
            end
        end
    end


    local roots = {}

    local rsObjectives =
        ReplicatedStorage:FindFirstChild("Objectives")
    if rsObjectives then
        roots[#roots + 1] = rsObjectives
    end

    local unclimbable =
        workspace:FindFirstChild("Unclimbable")

    local wsObjective =
        unclimbable
        and unclimbable:FindFirstChild("Objective")

    if wsObjective then
        roots[#roots + 1] = wsObjective
    end

    for _, root in ipairs(roots) do
        local objects = {root}
        local checked = 0

        for _, child in ipairs(root:GetDescendants()) do
            objects[#objects + 1] = child
            checked += 1
            if checked >= 260 then break end
        end

        for _, object in ipairs(objects) do
            local name =
                string.lower(
                    tostring(object.Name or "")
                )

            local isDefend =
                string.find(name, "defend", 1, true)
                and (
                    string.find(name, "hq", 1, true)
                    or string.find(name, "headquarter", 1, true)
                )

            if isDefend then
                local current = nil
                local required = nil

                if object:IsA("IntValue")
                    or object:IsA("NumberValue") then
                    current = tonumber(object.Value)
                end

                for _, key in ipairs({
                    "Current",
                    "Progress",
                    "Wave",
                    "Waves",
                    "Count",
                    "Value",
                }) do
                    current =
                        current
                        or tonumber(object:GetAttribute(key))
                end

                for _, key in ipairs({
                    "Requirement",
                    "Required",
                    "Goal",
                    "Max",
                    "Maximum",
                    "Total",
                }) do
                    required =
                        required
                        or tonumber(object:GetAttribute(key))
                end

                if progressReady(current, required or 5) then
                    return true
                end
            end
        end
    end

    for _, key in ipairs({
        "Wave",
        "CurrentWave",
        "Current_Wave",
        "BreachWave",
        "Breach_Wave",
    }) do
        local wave = tonumber(workspace:GetAttribute(key))
        if wave and wave >= 5 then
            return true
        end
    end

    return false
end

App.Safety.ShouldPauseFinalTitan = function()

    if RuntimeKind ~= "Gameplay"
        or not combatFarmActive() then
        return false
    end

    local delay =
        math.clamp(
            math.floor(
                (tonumber(App.Values.FarmSafetyDelay) or 0)
                + 0.5
            ),
            0,
            150
        )

    if delay <= 0 then
        App.Safety.FinalTitanStatus = "Off"
        return false
    end

    local alive = App.Safety.AliveTitanCount()
    local isBreach = App.Safety.IsBreachMission()

    local breachComplete =
        isBreach
        and App.Safety.BreachPhase2Complete()
        or nil


    if isBreach and breachComplete ~= true then
        App.Safety.FinalTitanCompleted["BREACH_PHASE2_FINAL"] = nil

        if App.Safety.FinalTitanKey == "BREACH_PHASE2_FINAL"
            or App.Safety.FinalTitanKey == "MISSION_LAST_TITAN" then
            App.Safety.FinalTitanKey = ""
            App.Safety.FinalTitanStartedAt = 0
        end

        App.Safety.FinalTitanStatus =
            "Breach clearing normally • Defend HQ 5/5 required"

        return false
    end

    if alive == 1 then
        local key =
            breachComplete == true
            and "BREACH_PHASE2_FINAL"
            or "MISSION_LAST_TITAN"

        if App.Safety.FinalTitanCompleted[key] then
            App.Safety.FinalTitanStatus =
                "Final Titan delay complete"
            return false
        end

        if App.Safety.FinalTitanKey ~= key then
            App.Safety.FinalTitanKey = key
            App.Safety.FinalTitanStartedAt = os.clock()
        end

        local remaining =
            delay
            - (
                os.clock()
                - (App.Safety.FinalTitanStartedAt or 0)
            )

        if remaining > 0 then
            App.Safety.FinalTitanStatus =
                string.format(
                    "Waiting before final Titan • %ds",
                    math.ceil(remaining)
                )
            return true
        end

        App.Safety.FinalTitanCompleted[key] = true
        App.Safety.FinalTitanStatus =
            "Final Titan delay complete"
        return false
    elseif alive > 1 then
        App.Safety.FinalTitanCompleted["MISSION_LAST_TITAN"] = nil
        App.Safety.FinalTitanCompleted["BREACH_PHASE2_FINAL"] = nil
        App.Safety.FinalTitanKey = ""
        App.Safety.FinalTitanStartedAt = 0
        App.Safety.FinalTitanStatus =
            "Ready • multiple Titans remain"
    else
        App.Safety.FinalTitanStatus =
            "Waiting for Titans"
    end

    return false
end

App.Safety.ExactTargetableCount = function(weapon)
    local entries = weapon == "Spears" and spearEntries() or bladeCandidateEntries()
    return type(entries) == "table" and #entries or 0
end

App.Safety.FinalHoldEligible = function()
    local delay = math.clamp(
        math.floor((tonumber(App.Values.FarmSafetyDelay) or 0) + 0.5),
        0,
        150
    )

    if delay <= 0 then return false end

    if App.Safety.IsBreachMission()
        and App.Safety.BreachPhase2Complete() ~= true then
        return false
    end

    return true
end

App.Safety.GuardBladeTargets = function(targets)
    if type(targets) ~= "table"
        or #targets == 0
        or not App.Safety.FinalHoldEligible() then
        return targets
    end

    local total = App.Safety.ExactTargetableCount("Blades")

    if total <= 1 then
        if App.Safety.ShouldPauseFinalTitan() then return {} end
        return targets
    end

    if #targets >= total then
        local guarded = {}
        for index = 1, math.max(0, #targets - 1) do
            guarded[#guarded + 1] = targets[index]
        end
        App.Safety.FinalTitanStatus = "Reserving final Titan for timer"
        return guarded
    end

    return targets
end

App.Safety.GuardSpearPositions = function(positions)
    if type(positions) ~= "table"
        or #positions == 0
        or not App.Safety.FinalHoldEligible() then
        return positions
    end

    local total = App.Safety.ExactTargetableCount("Spears")

    if total <= 1 then
        if App.Safety.ShouldPauseFinalTitan() then return {} end
        return positions
    end

    if #positions >= total then
        local guarded = {}
        for index = 1, math.max(0, #positions - 1) do
            guarded[#guarded + 1] = positions[index]
        end
        App.Safety.FinalTitanStatus = "Reserving final Titan for timer"
        return guarded
    end

    return positions
end

App.Safety.ResetAutoDieState = function()
    App.Safety.Armed = true
    App.Safety.PendingDeath = false
    App.Safety.AttackHold = false
end

App.Safety.OtherPlayer = function()
    if RuntimeKind ~= "Gameplay" then return nil end
    for _, other in ipairs(Players:GetPlayers()) do
        if other ~= player and other.Parent == Players then
            return other
        end
    end
    return nil
end

App.Safety.Step = function()
    if RuntimeKind == "Gameplay" and App.Values.LeaveIfAnotherPlayer == true then
        local other = App.Safety.OtherPlayer()
        if other then
            local name = tostring(other.Name or other.DisplayName or "Unknown")
            local now = os.clock()
            App.Safety.LastDetectedPlayer = name

            if App.Safety.PlayerSeenName ~= name then
                App.Safety.PlayerSeenName = name
                App.Safety.PlayerSeenSince = now
                App.Safety.PlayerSafetyStatus = "Confirming " .. name .. " • 0.0 / 1.5s"
            end

            local seenFor = math.max(0, now - (tonumber(App.Safety.PlayerSeenSince) or now))
            if seenFor < 1.5 then
                App.Safety.PlayerSafetyStatus =
                    "Confirming " .. name .. " • " .. string.format("%.1f", seenFor) .. " / 1.5s"
            else
                App.Safety.PlayerSafetyStatus = "Confirmed " .. name .. " • leaving mission"
                if App.Safety.PlayerLeaveTriggered ~= true then
                    App.Safety.PlayerLeaveTriggered = true
                    task.spawn(function()
                        local fn = App.Safety.RequestSoloLeave
                        if type(fn) == "function" then
                            local ok, left = pcall(fn, name)
                            if not ok or left ~= true then
                                App.Safety.PlayerLeaveTriggered = false
                            end
                        else
                            App.Safety.PlayerLeaveTriggered = false
                        end
                    end)
                end
            end
        else
            App.Safety.PlayerLeaveTriggered = false
            App.Safety.PlayerSeenSince = 0
            App.Safety.PlayerSeenName = ""
            App.Safety.LastDetectedPlayer = ""
            App.Safety.PlayerSafetyStatus = "Solo • no other players detected"
        end
    else
        App.Safety.PlayerLeaveTriggered = false
        App.Safety.PlayerSeenSince = 0
        App.Safety.PlayerSeenName = ""
        App.Safety.LastDetectedPlayer = ""
        App.Safety.PlayerSafetyStatus = "Off"
    end

    local streak =
        App.Safety.ReadStreak()

    App.Safety.LastStreak = streak

    if RuntimeKind ~= "Gameplay"
        or App.Values.AutoDieAtStreak ~= true then
        App.Safety.ResetAutoDieState()
        App.Safety.Status = "Off"
        return
    end

    local threshold = math.clamp(
        math.floor(
            (tonumber(App.Values.AutoDieStreak) or 100000)
            + 0.5
        ),
        10000,
        1000000
    )

    App.Values.AutoDieStreak = threshold

    if streak == nil then
        App.Safety.Status = "Streak unavailable"
        return
    end

    if streak < threshold then
        if App.Safety.PendingDeath
            or App.Safety.AttackHold
            or App.Safety.Armed ~= true then
            App.Safety.ResetAutoDieState()
        end

        App.Safety.Status =
            "Armed • "
            .. App.Webhook.FormatNumber(streak)
            .. " / "
            .. App.Webhook.FormatNumber(threshold)

        return
    end

    if App.Safety.Armed then
        App.Safety.Armed = false
        App.Safety.PendingDeath = true
        App.Safety.AttackHold = true

        App.SafeFarm.ReleaseAll()

        App.Safety.Status =
            "Threshold reached • defeat method pending"
    end
end

local function bladeSendBank(post, bank)
    if not post or not post:IsA("RemoteEvent") or #bank == 0 then
        return 0, 0
    end

    post:FireServer("Attacks", "Slash", true)

    local registers = 0

    for _, entry in ipairs(bank) do
        local titan = entry and entry.Titan
        local nape = titan and bladeExactNape(titan) or nil

        if isTitanAlive(titan) and nape then
            local repeatCount = 1
            if isRaidBossTitan(titan) then
                repeatCount = math.clamp(
                    math.floor((tonumber(App.Values.RaidBossMultiHit) or 1) + 0.5),
                    1,
                    10
                )
            end

            for _ = 1, repeatCount do
                if not isTitanAlive(titan) or not nape.Parent then break end
                post:FireServer(
                    "Hitboxes",
                    "Register",
                    nape,
                    math.random(625, 850)
                )
                registers += 1
            end
        end
    end

    return 1, registers
end

local function bladeTravelToPack(center, packMembers)
    if typeof(center) ~= "Vector3" then return false end
    local root = spearRoot()
    if not root then return false end

    if CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent
        and CombatSafety.DetectArmoredPhase(CombatSafety.ArmoredBoss) == "P2" then
        return CombatSafety.HoldArmoredV1(CombatSafety.ArmoredBoss, false)
    end

    local raidBoss = spearFindRaidBoss(packMembers)
    if raidBoss then
        return CombatSafety.HoldRaidBoss(raidBoss, false)
    end
    if CombatSafety.RaidBossHoldBoss ~= nil then
        CombatSafety.ClearRaidBossHold()
    end

    local existing = CombatSafety.BaseHoldCFrame
    if typeof(existing) == "CFrame" then
        local a = Vector3.new(existing.Position.X, 0, existing.Position.Z)
        local b = Vector3.new(center.X, 0, center.Z)
        local horizontal = (a - b).Magnitude

        local relocateDistance =
            (App.Values.MovementMode == "Regular") and 160
            or CombatSafety.RelocateDistance
        local relocateCooldown =
            (App.Values.MovementMode == "Regular") and 0.85
            or CombatSafety.RelocateCooldown

        if horizontal <= relocateDistance
            or os.clock() - CombatSafety.LastRelocateAt < relocateCooldown then
            setCombatHoldCFrame(existing)
            return combatSafetyHardSnap()
        end
    end

    local desired = center + Vector3.new(0, CombatSafety.SafeHeight, 0)
    local hold = CFrame.lookAt(desired, center)
    local ok = combatTravelToCFrame(hold, true)

    if ok then
        CombatSafety.LastRelocateAt = os.clock()
        setCombatHoldCFrame(hold)
        combatSafetyHardSnap()
    end
    return ok
end

local function bladeFireCycle(center, packMembers)
    if BladeRuntime.Busy
        or CombatSafety.Moving
        or SpearRuntime.RefillBusy
        or (App.BladeRefill and App.BladeRefill.Busy) then
        return false
    end
    if os.clock() < (CombatSafety.AttackPauseUntil or 0) then return false end

    local raidBoss = spearFindRaidBoss(packMembers)
    if raidBoss and not CombatSafety.RaidBossAttackReady(raidBoss) then
        BladeRuntime.LastStatus = CombatSafety.RaidBossAbilityStatus and ("Raid boss • hold fire • " .. tostring(CombatSafety.RaidBossAbilityStatus)) or "Raid boss • retreating to safe hold"
        BladeRuntime.NextCycleAt = os.clock() + 0.18
        return false
    end

    combatSafetyHardSnap()

    local now = os.clock()
    if now < (BladeRuntime.NextCycleAt or 0) then
        return false
    end

    local _, post = spearRemotes()
    if not post or not post:IsA("RemoteEvent") then
        BladeRuntime.LastStatus = "POST remote missing"
        BladeRuntime.NextCycleAt = now + 0.25
        return false
    end

    local targets = bladeBuildTargets(center, packMembers)

    -- Same separation as Carry V1 Spears: a Pure cycle may not silently fill
    -- spare blade slots with the Armored boss. Boss cycles still use it normally.
    if not raidBoss
        and CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent then
        local pureOnly = {}
        for _, item in ipairs(targets) do
            if item and item.Titan ~= CombatSafety.ArmoredBoss then
                pureOnly[#pureOnly + 1] = item
            end
        end
        targets = pureOnly
    end

    if App.Safety and App.Safety.GuardBladeTargets then
        targets = App.Safety.GuardBladeTargets(targets)
    end
    if #targets == 0 then
        BladeRuntime.LastStatus = "No exact Napes"
        BladeRuntime.NextCycleAt = now + 0.025
        return false
    end

    BladeRuntime.Busy = true

    local slashCount = 0
    local registerCount = 0
    local ok, err = pcall(function()

        local bankStart = 1

        while bankStart <= #targets do
            local bankEnd = math.min(#targets, bankStart + 9)
            local bank = {}

            for index = bankStart, bankEnd do
                bank[#bank + 1] = targets[index]
            end

            combatSafetyHardSnap()
            local slashes, registers = bladeSendBank(post, bank)
            slashCount += slashes
            registerCount += registers
            bankStart = bankEnd + 1

            if bankStart <= #targets then
                task.wait(0.008)
            end
        end
    end)

    BladeRuntime.Busy = false

    if not ok then
        BladeRuntime.LastStatus = "Blade remote error: " .. tostring(err)
        BladeRuntime.NextCycleAt = os.clock() + 0.08
        return false
    end

    BladeRuntime.LastSlashes = slashCount
    BladeRuntime.LastRegisters = registerCount
    BladeRuntime.TotalSlashes += slashCount
    BladeRuntime.TotalRegisters += registerCount
    BladeRuntime.LastStatus = string.format(
        "Blade Multi-Hit • Slash x%d • Reg %d",
        slashCount,
        registerCount
    )

    if registerCount > 0
        and CombatSafety.ArmoredBoss
        and CombatSafety.ArmoredBoss.Parent then
        local armoredPhase = CombatSafety.DetectArmoredPhase(CombatSafety.ArmoredBoss)
        if armoredPhase == "P2" then
            if raidBoss == CombatSafety.ArmoredBoss then
                CombatSafety.ArmoredNextCycle = "Pure"
            else
                CombatSafety.ArmoredNextCycle = "Boss"
            end
        else
            CombatSafety.ArmoredNextCycle = "Boss"
        end
    end

    BladeRuntime.NextCycleAt = os.clock() + 0.085
    return registerCount > 0
end

local function bladeFarmStep()
    if App.Colossal
        and App.Colossal.OwnsCombat
        and App.Colossal.OwnsCombat() then
        return
    end

    if App.Values.AutoFarmBlades ~= true then
        return
    end

    if App.Safety
        and App.Safety.AttackHold then
        BladeRuntime.LastStatus =
            "Auto Die streak threshold"
        return
    end
    if App.TransitionGuard and App.TransitionGuard.BlockGameplay
        and App.TransitionGuard.BlockGameplay() then
        return
    end

    if App.Safety
        and App.Safety.ShouldPauseFinalTitan
        and App.Safety.ShouldPauseFinalTitan() then
        BladeRuntime.LastStatus =
            tostring(App.Safety.FinalTitanStatus or "Waiting before final Titan")
        return
    end

    if BladeRuntime.Busy
        or CombatSafety.Moving
        or SpearRuntime.RefillBusy
        or (App.BladeRefill and App.BladeRefill.Busy) then
        return
    end

    if not bladeEquipped() then
        BladeRuntime.LastStatus = "Equip Blades"
        return
    end

    local character = spearCharacter()
    local root = spearRoot()
    local humanoid = spearHumanoid()

    if not character or not root or not humanoid or humanoid.Health <= 0 then
        return
    end

    local center, members, count = spearBestPack()

    if not center or count <= 0 then
        BladeRuntime.LastStatus = "Scanning for Titans"
        return
    end

    bladeTravelToPack(center, members)

    if App.Values.AutoFarmBlades ~= true then
        return
    end

    if App.Values.SafeFarm == true
        and App.SafeFarm then
        App.SafeFarm.Step(center, members)
    else
        bladeFireCycle(center, members)
    end
end

local function stopBladeRuntime()
    BladeRuntime.Busy = false
    BladeRuntime.NextCycleAt = 0

    if App.SafeFarm then
        App.SafeFarm.ReleaseAll()
        App.SafeFarm.NextAt = 0
    end

    if App.Safety
        and App.Safety.ResetFinalTitanPacing then
        App.Safety.ResetFinalTitanPacing()
    end
end


App.BladeRefill = {
    Busy = false,
    NextCheckAt = 0,
    LastStatus = "Idle",
    LastFill = nil,
    LastSets = nil,
    LastActionAt = 0,
    BrokenOffset = -0.12,
    ReadyOffset = 0.82,


    RenewPending = false,
    RenewStartedAt = 0,
    RenewBeforeSets = nil,
    RenewOutcome = "IDLE",

    NativeRenewGrace = 1.10,
    RenewObserveSeconds = 3.25,
    RenewPendingTimeout = 8.00,

    StationTargetSets = 3,
    StationActionAttempts = 4,
    StationActionPollSeconds = 1.35,
    StationVerifySeconds = 5.25,
    StationPostRefillSettleSeconds = 1.85,
    StationPostRefillStableSamples = 4,
    StationSpotDistance = 1.55,
    StationHoldTime = 0.72,
    StationRetryCooldown = 2.50,
}

App.BladeRefill.TrustedRoot = function()
    local interface = playerGui:FindFirstChild("Interface")
    local hud = interface and interface:FindFirstChild("HUD")
    local main = hud and hud:FindFirstChild("Main")
    local top = main and main:FindFirstChild("Top")
    local slot = top and top:FindFirstChild("7")
    return slot and slot:FindFirstChild("Blades") or nil
end

App.BladeRefill.ReadFill = function()
    local root = App.BladeRefill.TrustedRoot()
    if not root then return nil end

    local inner = root:FindFirstChild("Inner")
    local bar = inner and inner:FindFirstChild("Bar")
    local gradient = bar and bar:FindFirstChild("Gradient")

    if gradient and gradient:IsA("UIGradient") then
        local ok, offset = pcall(function()
            return gradient.Offset
        end)

        if ok and typeof(offset) == "Vector2" then
            return tonumber(offset.X)
        end
    end


    local best, bestScore = nil, -math.huge
    for _, object in ipairs(root:GetDescendants()) do
        if object:IsA("UIGradient") then
            local score = 0
            local parentName =
                string.lower(
                    tostring(
                        object.Parent
                        and object.Parent.Name
                        or ""
                    )
                )

            if parentName == "bar" then score += 60 end
            if math.abs((tonumber(object.Rotation) or 0) - 30) <= 2 then
                score += 35
            end

            if score > bestScore then
                best = object
                bestScore = score
            end
        end
    end

    if best and bestScore >= 40 then
        local ok, offset = pcall(function()
            return best.Offset
        end)

        if ok and typeof(offset) == "Vector2" then
            return tonumber(offset.X)
        end
    end

    return nil
end

App.BladeRefill.ReadSets = function()
    local root = App.BladeRefill.TrustedRoot()
    if not root then return nil end

    local sets = root:FindFirstChild("Sets", true)
    if not sets then return nil end

    local candidates = {sets}
    for _, object in ipairs(sets:GetDescendants()) do
        candidates[#candidates + 1] = object
    end

    for _, object in ipairs(candidates) do
        local text = nil

        if object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then
            text = tostring(object.Text or "")
        elseif object:IsA("IntValue")
            or object:IsA("NumberValue")
            or object:IsA("StringValue") then
            text = tostring(object.Value)
        end

        if text then
            local current, maximum =
                string.match(
                    text:gsub("%s+", ""),
                    "(%d+)%/(%d+)"
                )

            current = tonumber(current)
            maximum = tonumber(maximum)

            if current and maximum and maximum <= 6 then
                return current, maximum
            end
        end
    end

    return nil
end

App.BladeRefill.IsBroken = function(fill)
    return tonumber(fill) ~= nil
        and tonumber(fill) <= App.BladeRefill.BrokenOffset
end

App.BladeRefill.IsReady = function(fill)
    return tonumber(fill) ~= nil
        and tonumber(fill) >= App.BladeRefill.ReadyOffset
end

App.BladeRefill.ReadFresh = function()
    local fill = App.BladeRefill.ReadFill()
    local sets = select(1, App.BladeRefill.ReadSets())

    App.BladeRefill.LastFill = fill
    App.BladeRefill.LastSets = sets

    return fill, sets
end

App.BladeRefill.Progressed = function(
    beforeFill,
    beforeSets,
    afterFill,
    afterSets
)
    local setSpent =
        beforeSets ~= nil
        and afterSets ~= nil
        and afterSets < beforeSets

    local fillRecovered =
        App.BladeRefill.IsReady(afterFill)
        or (
            tonumber(beforeFill) ~= nil
            and tonumber(afterFill) ~= nil
            and tonumber(afterFill)
                >= tonumber(beforeFill) + 0.55
        )

    return setSpent or fillRecovered
end

App.BladeRefill.WaitProgress = function(
    beforeFill,
    beforeSets,
    seconds
)
    local started = os.clock()
    local afterFill, afterSets = nil, nil

    repeat
        afterFill, afterSets =
            App.BladeRefill.ReadFresh()

        if App.BladeRefill.Progressed(
            beforeFill,
            beforeSets,
            afterFill,
            afterSets
        ) then
            return true, afterFill, afterSets
        end

        task.wait(0.05)
    until os.clock() - started >= (seconds or 0.72)

    return false, afterFill, afterSets
end

App.BladeRefill.InvokeBladeRenew = function()
    local getRemote = select(1, spearRemotes())

    if not getRemote
        or not getRemote:IsA("RemoteFunction") then
        return false, nil, "GET remote missing"
    end

    local called =
        table.pack(
            pcall(function()
                return getRemote:InvokeServer(
                    "Blades",
                    "Reload"
                )
            end)
        )

    if not called[1] then
        return false, nil, tostring(called[2])
    end

    return true, called[2], nil
end

App.BladeRefill.ClearRenewPending = function(outcome)
    App.BladeRefill.RenewPending = false
    App.BladeRefill.RenewStartedAt = 0
    App.BladeRefill.RenewBeforeSets = nil
    App.BladeRefill.RenewOutcome =
        tostring(outcome or "READY")
end

App.BladeRefill.ObserveRenewal = function(beforeSets, seconds)
    local deadline =
        os.clock() + math.max(0.15, tonumber(seconds) or 0.15)

    local consumed = false
    local lowestSets = beforeSets

    repeat
        task.wait(0.05)

        local liveFill, liveSets =
            App.BladeRefill.ReadFresh()

        if App.BladeRefill.IsReady(liveFill)
            or (
                tonumber(liveFill) ~= nil
                and not App.BladeRefill.IsBroken(liveFill)
            ) then

            return true,
                consumed,
                liveSets,
                liveFill,
                "FILL_RECOVERED"
        end

        if beforeSets ~= nil
            and liveSets ~= nil
            and liveSets < beforeSets then

            consumed = true
            lowestSets =
                lowestSets == nil
                and liveSets
                or math.min(lowestSets, liveSets)
        end

    until os.clock() >= deadline

    return false,
        consumed,
        lowestSets or select(2, App.BladeRefill.ReadFresh()),
        App.BladeRefill.ReadFill(),
        consumed
            and "SET_CONSUMED_BUT_FILL_STILL_BROKEN"
            or "NO_ACCEPTANCE"
end

App.BladeRefill.RenewCurrent = function()
    local beforeFill, beforeSets =
        App.BladeRefill.ReadFresh()

    if not App.BladeRefill.IsBroken(beforeFill) then
        App.BladeRefill.ClearRenewPending(
            "CURRENT_BLADE_USABLE"
        )
        return true, "Blade already usable"
    end


    if App.BladeRefill.RenewPending then
        local pendingFor =
            os.clock()
            - (
                tonumber(
                    App.BladeRefill.RenewStartedAt
                )
                or os.clock()
            )

        local liveFill =
            App.BladeRefill.ReadFill()

        if liveFill ~= nil
            and not App.BladeRefill.IsBroken(liveFill) then

            App.BladeRefill.ClearRenewPending(
                "PENDING_FILL_RECOVERED"
            )

            return true, "Blade renewal settled"
        end

        App.BladeRefill.LastStatus =
            pendingFor >= App.BladeRefill.RenewPendingTimeout
            and "Renew paused • one set consumed • duplicate blocked"
            or string.format(
                "Renew settling %.1fs • duplicate blocked",
                pendingFor
            )

        return false, App.BladeRefill.LastStatus
    end

    if beforeSets == nil or beforeSets <= 0 then
        return false, "No spare blade sets"
    end


    local ready,
        consumed,
        liveSets,
        liveFill,
        outcome =
            App.BladeRefill.ObserveRenewal(
                beforeSets,
                App.BladeRefill.NativeRenewGrace
            )

    if ready then
        App.BladeRefill.ClearRenewPending(outcome)
        App.BladeRefill.LastStatus =
            "Current blade renewed • native"
        return true, App.BladeRefill.LastStatus
    end

    if consumed then
        local lateReady,
            _,
            lateSets,
            lateFill,
            lateOutcome =
                App.BladeRefill.ObserveRenewal(
                    beforeSets,
                    App.BladeRefill.RenewObserveSeconds
                )

        if lateReady then
            App.BladeRefill.ClearRenewPending(
                "NATIVE_SET_CONSUMED_AND_RECOVERED"
            )
            App.BladeRefill.LastStatus =
                "Current blade renewed • native settle"
            return true, App.BladeRefill.LastStatus
        end

        App.BladeRefill.RenewPending = true
        App.BladeRefill.RenewStartedAt = os.clock()
        App.BladeRefill.RenewBeforeSets = beforeSets
        App.BladeRefill.RenewOutcome =
            lateOutcome or outcome

        App.BladeRefill.LastStatus =
            "One set consumed "
            .. tostring(beforeSets)
            .. "→"
            .. tostring(lateSets or liveSets)
            .. " • duplicate reload blocked"

        return false, App.BladeRefill.LastStatus
    end


    local invokeOk, response =
        App.BladeRefill.InvokeBladeRenew()

    local explicitReady,
        explicitConsumed,
        explicitSets,
        explicitFill,
        explicitOutcome =
            App.BladeRefill.ObserveRenewal(
                beforeSets,
                App.BladeRefill.RenewObserveSeconds
            )

    if explicitReady then
        App.BladeRefill.ClearRenewPending(
            response == true
            and "EXPLICIT_ACCEPTED_AND_RECOVERED"
            or explicitOutcome
        )

        App.BladeRefill.LastStatus =
            "Current blade renewed • single owner"

        return true, App.BladeRefill.LastStatus
    end

    if explicitConsumed then
        App.BladeRefill.RenewPending = true
        App.BladeRefill.RenewStartedAt = os.clock()
        App.BladeRefill.RenewBeforeSets = beforeSets
        App.BladeRefill.RenewOutcome =
            explicitOutcome

        App.BladeRefill.LastStatus =
            "One set consumed "
            .. tostring(beforeSets)
            .. "→"
            .. tostring(explicitSets)
            .. " • waiting same renewal"

        return false, App.BladeRefill.LastStatus
    end

    App.BladeRefill.LastStatus =
        invokeOk
        and (
            response == true
            and "Reload accepted • fill pending"
            or "Reload not accepted"
        )
        or "Reload request failed"

    return false, App.BladeRefill.LastStatus
end

App.BladeRefill.StationReload = function(station)
    local getRemote = select(1, spearRemotes())

    if not getRemote
        or not getRemote:IsA("RemoteFunction")
        or not station
        or not station.Parent then
        return false, nil
    end

    local ok, response =
        pcall(function()
            return getRemote:InvokeServer(
                "Attacks",
                "Reload",
                station
            )
        end)

    return ok, response
end

App.BladeRefill.ReadRefills = function()
    local value = nil

    pcall(function()
        value = player:GetAttribute("Refills")
    end)

    return tonumber(value)
end

App.BladeRefill.StationSpots = function(station, character)
    local distance =
        math.max(
            0.75,
            tonumber(App.BladeRefill.StationSpotDistance)
                or 1.55
        )

    local sx =
        math.max(1.5, station.Size.X * 0.5)

    local sz =
        math.max(1.5, station.Size.Z * 0.5)

    -- Incremental construction keeps peak Luau temporary-register use low.
    local raw = {}
    local stationFrame = station.CFrame
    local function addOffset(x, y, z)
        raw[#raw + 1] =
            (stationFrame * CFrame.new(x, y, z)).Position
    end

    addOffset(0, 0, -(sz + distance))
    addOffset(0, 0, sz + distance)
    addOffset(-(sx + distance), 0, 0)
    addOffset(sx + distance, 0, 0)
    addOffset(0, 1.5, -(sz + 0.35))
    addOffset(0, 1.5, sz + 0.35)
    addOffset(-(sx + 0.35), 1.5, 0)
    addOffset(sx + 0.35, 1.5, 0)
    raw[#raw + 1] = station.Position + Vector3.new(0, 2.8, 0)

    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Blacklist
    params.FilterDescendantsInstances =
        character and {character} or {}

    local spots = {}

    for _, position in ipairs(raw) do
        local result =
            workspace:Raycast(
                position + Vector3.new(0, 35, 0),
                Vector3.new(0, -90, 0),
                params
            )

        spots[#spots + 1] =
            result and result.Position
            and (
                result.Position
                + Vector3.new(0, 3.1, 0)
            )
            or position
    end

    return spots
end

App.BladeRefill.HoldAt = function(cframe, token)
    local character = spearCharacter()
    local humanoid = spearHumanoid()
    local root = spearRoot()

    if not character
        or not root
        or typeof(cframe) ~= "CFrame" then
        return false
    end

    pcall(function()
        character:PivotTo(cframe)
        root.CFrame = cframe
        root.Anchored = true
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero

        if humanoid then
            humanoid.Sit = false
            humanoid.PlatformStand = false
            humanoid.AutoRotate = true
        end
    end)

    if token then
        task.spawn(function()
            while gui
                and gui.Parent
                and App.BladeRefill.Busy
                and token.Active do

                pcall(function()
                    if character.Parent
                        and root.Parent then

                        character:PivotTo(cframe)
                        root.CFrame = cframe
                        root.Anchored = true
                        root.AssemblyLinearVelocity =
                            Vector3.zero
                        root.AssemblyAngularVelocity =
                            Vector3.zero

                        if humanoid then
                            humanoid.Sit = false
                            humanoid.PlatformStand = false
                        end
                    end
                end)

                task.wait(0.02)
            end
        end)
    end

    return true
end

App.BladeRefill.ReleaseHold = function()
    local root = spearRoot()
    local humanoid = spearHumanoid()

    pcall(function()
        if root then
            root.Anchored = false
            root.AssemblyLinearVelocity =
                Vector3.zero
            root.AssemblyAngularVelocity =
                Vector3.zero
        end

        if humanoid then
            humanoid.Sit = false
            humanoid.PlatformStand = false
            humanoid.AutoRotate = true
            humanoid:ChangeState(
                Enum.HumanoidStateType.Running
            )
        end
    end)
end

App.BladeRefill.StationProgressAccepted = function(
    beforeSets,
    beforeRefills,
    seconds
)
    local deadline =
        os.clock()
        + math.max(0.15, tonumber(seconds) or 0.15)

    repeat
        task.wait(0.04)

        local liveSets =
            select(1, App.BladeRefill.ReadSets())

        local liveRefills =
            App.BladeRefill.ReadRefills()

        if liveSets ~= nil
            and liveSets
                >= App.BladeRefill.StationTargetSets then
            return true,
                "SETS_FULL",
                liveSets,
                liveRefills
        end

        if beforeRefills ~= nil
            and liveRefills ~= nil
            and liveRefills < beforeRefills then

            return true,
                "REFILL_CHARGE_SPENT",
                liveSets,
                liveRefills
        end

        if beforeSets ~= nil
            and liveSets ~= nil
            and liveSets > beforeSets then

            return true,
                "SETS_INCREASING",
                liveSets,
                liveRefills
        end

    until os.clock() >= deadline

    return false,
        nil,
        select(1, App.BladeRefill.ReadSets()),
        App.BladeRefill.ReadRefills()
end

App.BladeRefill.HoldR = function()
    local key = Enum.KeyCode.R
    local usedExecutor =
        type(keypress) == "function"
        and type(keyrelease) == "function"

    if usedExecutor then
        pcall(function()
            keypress(key.Value or key)
        end)
    else
        pcall(function()
            VirtualInputManager:SendKeyEvent(
                true,
                key,
                false,
                game
            )
        end)
    end

    task.wait(App.BladeRefill.StationHoldTime)

    if usedExecutor then
        pcall(function()
            keyrelease(key.Value or key)
        end)
    else
        pcall(function()
            VirtualInputManager:SendKeyEvent(
                false,
                key,
                false,
                game
            )
        end)
    end
end

App.BladeRefill.DoStationRefill = function()
    if App.BladeRefill.Busy then
        return false
    end

    local root = spearRoot()
    local character = spearCharacter()

    if not root or not character then
        return false
    end

    local returnCFrame =
        App.Colossal
        and App.Colossal.Active
        and App.Colossal.ReturnCFrame
        and App.Colossal.ReturnCFrame()
        or CombatSafety.BaseHoldCFrame
        or root.CFrame

    local station = spearFindRefillStation()

    if not station then
        App.BladeRefill.LastStatus =
            "Refill station not found"
        return false
    end

    local beforeRefills =
        App.BladeRefill.ReadRefills()

    local beforeSets =
        select(1, App.BladeRefill.ReadSets())

    if beforeRefills ~= nil
        and beforeRefills <= 0 then
        App.BladeRefill.LastStatus =
            "0/3 • no refill charges"
        return false
    end

    App.BladeRefill.Busy = true
    BladeRuntime.Busy = false

    local getRemote = select(1, spearRemotes())
    local success = false

    App.BladeRefill.LastStatus =
        "Exact station refill • locating spots"

    if not getRemote
        or not getRemote:IsA("RemoteFunction") then

        App.BladeRefill.Busy = false
        App.BladeRefill.LastStatus =
            "GET remote missing"
        return false
    end

    App.BladeRefill.ReleaseHold()

    local spots =
        App.BladeRefill.StationSpots(
            station,
            character
        )

    for spotIndex, position in ipairs(spots) do
        if App.Values.AutoBladeRefill ~= true then
            break
        end

        local look =
            Vector3.new(
                station.Position.X,
                position.Y,
                station.Position.Z
            )

        local stationCFrame =
            (look - position).Magnitude > 0.1
            and CFrame.lookAt(position, look)
            or CFrame.new(position)

        local token = {Active = true}

        App.BladeRefill.HoldAt(
            stationCFrame,
            token
        )

        task.wait(0.12)

        local accepted = false

        for attempt = 1,
            App.BladeRefill.StationActionAttempts do

            App.BladeRefill.LastStatus =
                string.format(
                    "Station spot %d • exact reload %d/%d",
                    spotIndex,
                    attempt,
                    App.BladeRefill.StationActionAttempts
                )

            local called =
                table.pack(
                    pcall(function()
                        return getRemote:InvokeServer(
                            "Attacks",
                            "Reload",
                            station
                        )
                    end)
                )

            if called[1] and called[2] == true then
                accepted = true
            else
                accepted =
                    select(
                        1,
                        App.BladeRefill
                            .StationProgressAccepted(
                                beforeSets,
                                beforeRefills,
                                App.BladeRefill
                                    .StationActionPollSeconds
                            )
                    )
            end

            if accepted then
                break
            end

            task.wait(0.08)
        end


        if not accepted then
            App.BladeRefill.HoldR()

            accepted =
                select(
                    1,
                    App.BladeRefill
                        .StationProgressAccepted(
                            beforeSets,
                            beforeRefills,
                            App.BladeRefill
                                .StationActionPollSeconds
                        )
                )
        end

        token.Active = false
        App.BladeRefill.ReleaseHold()

        if accepted then
            success = true
            break
        end
    end


    App.BladeRefill.ReleaseHold()

    if typeof(returnCFrame) == "CFrame" then
        combatTravelToCFrame(
            returnCFrame,
            false
        )
        setCombatHoldCFrame(returnCFrame)
        combatSafetyHardSnap()
    end

    if success then
        App.BladeRefill.LastStatus =
            "Station accepted • verifying 3/3"

        local deadline =
            os.clock()
            + App.BladeRefill.StationVerifySeconds

        local restoredSets = nil

        repeat
            restoredSets =
                select(1, App.BladeRefill.ReadSets())

            if restoredSets ~= nil
                and restoredSets
                    >= App.BladeRefill.StationTargetSets then
                break
            end

            task.wait(0.08)
        until os.clock() >= deadline

        success =
            restoredSets ~= nil
            and restoredSets
                >= App.BladeRefill.StationTargetSets

        if success then


            App.BladeRefill.LastStatus =
                "3/3 verified • settling current blade"

            local settleDeadline =
                os.clock()
                + App.BladeRefill.StationPostRefillSettleSeconds
            local stableSamples = 0

            CombatSafety.AttackPauseUntil =
                math.max(
                    tonumber(CombatSafety.AttackPauseUntil) or 0,
                    settleDeadline + 0.15
                )

            repeat
                local liveFill =
                    App.BladeRefill.ReadFill()

                if liveFill ~= nil
                    and not App.BladeRefill.IsBroken(liveFill) then
                    stableSamples += 1
                    if stableSamples
                        >= App.BladeRefill.StationPostRefillStableSamples then
                        break
                    end
                else
                    stableSamples = 0
                end

                task.wait(0.08)
            until os.clock() >= settleDeadline

            local fill =
                App.BladeRefill.ReadFill()

            if fill ~= nil
                and not App.BladeRefill.IsBroken(fill) then
                App.BladeRefill.ClearRenewPending(
                    "STATION_RESTOCK_CURRENT_BLADE_SETTLED"
                )
            elseif App.BladeRefill.IsBroken(fill) then
                App.BladeRefill.LastStatus =
                    "3/3 stable • current blade still broken • renewing"


                App.BladeRefill.RenewCurrent()
            else


                App.BladeRefill.LastStatus =
                    "3/3 verified • blade HUD settling"
            end
        end
    end

    App.BladeRefill.Busy = false
    App.BladeRefill.NextCheckAt =
        os.clock()
        + (
            success
            and 0.75
            or App.BladeRefill.StationRetryCooldown
        )

    App.BladeRefill.LastStatus =
        success
        and "Station 3/3 verified • combat resuming"
        or "Station refill not verified • retry pending"

    return success
end

App.BladeRefill.Step = function()
    if App.TransitionGuard and App.TransitionGuard.BlockGameplay
        and App.TransitionGuard.BlockGameplay() then return end

    if RuntimeKind ~= "Gameplay"
        or (App.Cutscene and App.Cutscene.Active == true)
        or App.Values.AutoBladeRefill ~= true
        or App.Values.AutoFarmBlades ~= true
        or not bladeEquipped()
        or App.BladeRefill.Busy
        or CombatSafety.Moving
        or SpearRuntime.RefillBusy then
        return
    end

    if os.clock()
        < (App.BladeRefill.NextCheckAt or 0) then
        return
    end

    local fill, sets =
        App.BladeRefill.ReadFresh()


    if fill == nil then
        App.BladeRefill.LastStatus =
            "Waiting for blade HUD"
        App.BladeRefill.NextCheckAt =
            os.clock() + 0.35
        return
    end

    if not App.BladeRefill.IsBroken(fill) then
        if App.BladeRefill.RenewPending then
            App.BladeRefill.ClearRenewPending(
                "FILL_RECOVERED"
            )
        end

        App.BladeRefill.LastStatus = "Blades usable"
        App.BladeRefill.NextCheckAt =
            os.clock() + 0.22
        return
    end

    if App.BladeRefill.RenewPending then
        App.BladeRefill.LastStatus =
            "One set consumed • waiting same renewal"
        App.BladeRefill.NextCheckAt =
            os.clock() + 0.25
        return
    end


    if App.Colossal
        and App.Colossal.OwnsCombat
        and App.Colossal.OwnsCombat()
        and tostring(App.Colossal.Stage or "") == "P1 CANNON STALL"
        and tostring(App.Colossal.Mode or "") == "Blades"
        and tostring(App.Colossal.GuardState or "IDLE") == "IDLE"
        and (tonumber(App.Colossal.ThreatCount) or 0) <= 0 then

        App.BladeRefill.LastStatus =
            "Broken blade • deferred during clear P1 cannon"
        App.BladeRefill.NextCheckAt =
            os.clock() + 0.35
        return
    end

    App.BladeRefill.Busy = true
    CombatSafety.AttackPauseUntil =
        os.clock() + 1.0
    combatSafetyHardSnap()

    if sets ~= nil and sets > 0 then
        App.BladeRefill.LastStatus =
            "Broken blade • renewing"

        local ok =
            App.BladeRefill.RenewCurrent()

        App.BladeRefill.Busy = false
        App.BladeRefill.NextCheckAt =
            os.clock() + (ok and 0.65 or 1.0)
        return
    end


    App.BladeRefill.Busy = false
    App.BladeRefill.DoStationRefill()
end


-- ============================================================================
-- V15.6.44 GAMEPLAY PATCH • TITAN MASTERY
-- Normal Blade/Spear speed is untouched. This controller owns combat only while
-- it is building Shift gauge or while the player is in Titan form.
-- ============================================================================
App.TitanMastery = App.TitanMastery or {
    Status = "Off",
    State = "IDLE",
    Initialized = false,
    WasShifted = false,
    RemainingShifts = nil,
    ShiftCapacity = nil,
    FallbackNormal = false,
    PendingGaugeAt = 0,
    PendingGaugeBar = nil,
    PendingGaugeTitan = nil,
    NextGaugeKillAt = 0,
    LastShiftAttemptAt = 0,
    ShiftAttemptCount = 0,
    ShiftAttemptWindowAt = 0,
    LastPunchAt = 0,
    Combo = 1,
    NextSkillAt = 0,
    SkillCursor = 1,
    SkillCache = {},
    SkillCacheAt = 0,
    LastShiftSyncAt = 0,
    BarMissingSince = nil,
    RunEnded = false,
    SerumCache = nil,
    SerumCacheAt = 0,
    SerumRuntime = nil,
    ActiveSerum = nil,
    HardDisabled = false,
    HardDisabledReason = nil,
    DisableAt = 0,
    NativeShiftLastError = nil,
}

App.TitanMastery.SetStatus = function(text)
    local base = tostring(text or "Ready")
    local suffix = ""
    if string.find(base, "No Skills", 1, true) == nil
        and App.Values.LobbyModifiersEnabled == true
        and App.Values.LobbyModNoSkills == true then
        suffix = suffix .. " • No Skills ⚠"
    end
    if string.find(base, "Glass Cannon", 1, true) == nil
        and App.Values.LobbyModifiersEnabled == true
        and App.Values.LobbyModGlassCannon == true then
        suffix = suffix .. " • Glass Cannon ⚠"
    end
    App.TitanMastery.Status = base .. suffix
end

App.TitanMastery.ReadBar = function()
    local value = tonumber(player:GetAttribute("Bar"))
    if value == nil then return nil end
    return math.clamp(value, 0, 100)
end

App.TitanMastery.IsShifted = function()
    local character = spearCharacter()
    if not character then return false end
    local value = character:GetAttribute("Shifter")
    return value ~= nil and value ~= false
end

App.TitanMastery.ReadShiftAttribute = function()
    local best = nil
    local character = spearCharacter()
    local objects = {player, character}

    for _, object in ipairs(objects) do
        if object then
            local value = tonumber(object:GetAttribute("Shift"))
            if value ~= nil then
                value = math.max(0, math.floor(value + 0.5))
                best = best == nil and value or math.max(best, value)
            end
        end
    end

    for _, object in ipairs(player:GetChildren()) do
        local value = tonumber(object:GetAttribute("Shift"))
        if value ~= nil then
            value = math.max(0, math.floor(value + 0.5))
            best = best == nil and value or math.max(best, value)
        end
    end

    return best
end

App.TitanMastery.SyncShiftCount = function(resetRemaining)
    local now = os.clock()
    if resetRemaining ~= true
        and now - (App.TitanMastery.LastShiftSyncAt or 0) < 0.45 then
        return
    end
    App.TitanMastery.LastShiftSyncAt = now
    local observed = App.TitanMastery.ReadShiftAttribute()
    if observed == nil then return end

    if App.TitanMastery.ShiftCapacity == nil
        or observed > App.TitanMastery.ShiftCapacity then
        App.TitanMastery.ShiftCapacity = observed
    end

    if resetRemaining == true or App.TitanMastery.RemainingShifts == nil then
        App.TitanMastery.RemainingShifts = observed
    elseif observed < App.TitanMastery.RemainingShifts then
        App.TitanMastery.RemainingShifts = observed
    end
end

App.TitanMastery.ShiftText = function()
    local remaining = App.TitanMastery.RemainingShifts
    local capacity = App.TitanMastery.ShiftCapacity
    if remaining == nil then return "Unknown • learning from confirmed shifts" end
    if capacity ~= nil then
        return tostring(remaining) .. "/" .. tostring(capacity)
    end
    return tostring(remaining) .. " remaining"
end

App.TitanMastery.ResetRun = function(reason)
    App.TitanMastery.State = "BUILD_GAUGE"
    App.TitanMastery.WasShifted = App.TitanMastery.IsShifted()
    App.TitanMastery.RemainingShifts = nil
    App.TitanMastery.ShiftCapacity = nil
    App.TitanMastery.FallbackNormal = false
    App.TitanMastery.PendingGaugeAt = 0
    App.TitanMastery.PendingGaugeBar = nil
    App.TitanMastery.PendingGaugeTitan = nil
    App.TitanMastery.NextGaugeKillAt = 0
    App.TitanMastery.LastShiftAttemptAt = 0
    App.TitanMastery.ShiftAttemptCount = 0
    App.TitanMastery.ShiftAttemptWindowAt = 0
    App.TitanMastery.LastShiftSyncAt = 0
    App.TitanMastery.BarMissingSince = nil
    App.TitanMastery.RunEnded = false
    App.TitanMastery.HardDisabled = false
    App.TitanMastery.HardDisabledReason = nil
    App.TitanMastery.DisableAt = 0
    App.TitanMastery.NativeShiftLastError = nil
    App.TitanMastery.SerumCache = nil
    App.TitanMastery.SerumCacheAt = 0
    App.TitanMastery.SerumRuntime = nil
    App.TitanMastery.ActiveSerum = nil
    App.TitanMastery.SkillCache = {}
    App.TitanMastery.SkillCacheAt = 0
    App.TitanMastery.SyncShiftCount(true)
    App.TitanMastery.SetStatus(reason or "Building Shift Gauge")
end

App.TitanMastery.BlockingModifier = function()
    if App.Values.LobbyModifiersEnabled == true then
        if App.Values.LobbyModNoSkills == true then return "No Skills" end
        if App.Values.LobbyModGlassCannon == true then return "Glass Cannon" end
    end
    if App.Values.BoostedModifiersEnabled == true then
        if App.Values.BoostedModNoSkills == true then return "No Skills" end
        if App.Values.BoostedModGlassCannon == true then return "Glass Cannon" end
    end
    return nil
end

App.TitanMastery.Disable = function(reason)
    local message = tostring(reason or "Shifting unavailable")
    App.TitanMastery.HardDisabled = true
    App.TitanMastery.HardDisabledReason = message
    App.TitanMastery.DisableAt = os.clock()
    App.TitanMastery.PendingGaugeAt = 0
    App.TitanMastery.PendingGaugeBar = nil
    App.TitanMastery.PendingGaugeTitan = nil
    App.TitanMastery.FallbackNormal = false
    App.Values.AutoTitanMastery = false
    if V12Config and type(V12Config.ScheduleSave) == "function" then
        V12Config.ScheduleSave(0.10)
    end
    App.TitanMastery.SetStatus("Disabled • " .. message)
    return false
end

App.TitanMastery.FindEquippedSerum = function(force)
    local now = os.clock()
    if force ~= true and App.TitanMastery.SerumCache and now - (App.TitanMastery.SerumCacheAt or 0) < 2.0 then
        return App.TitanMastery.SerumCache
    end
    local function normalize(value)
        local text = string.lower(tostring(value or ""))
        if string.find(text,"attack",1,true) then return "Attack" end
        if string.find(text,"armor",1,true) or string.find(text,"armour",1,true) then return "Armored" end
        if string.find(text,"female",1,true) then return "Female" end
        if string.find(text,"colossal",1,true) then return "Colossal" end
        return nil
    end
    local runtime = App.TitanMastery.SerumRuntime
    if type(runtime)=="table" then
        local loadout=rawget(runtime,"Loadout")
        local serum=type(loadout)=="table" and normalize(rawget(loadout,"Serum")) or nil
        if serum then App.TitanMastery.SerumCache=serum; App.TitanMastery.SerumCacheAt=now; return serum end
    end
    if type(getgc)=="function" and (force==true or now-(App.TitanMastery.SerumCacheAt or 0)>=1.0) then
        local ok,objects=pcall(getgc,true)
        if ok and type(objects)=="table" then
            for _,object in ipairs(objects) do
                if type(object)=="table" then
                    local loadout=rawget(object,"Loadout")
                    local helper=rawget(object,"ShifterDataHelper")
                    if type(loadout)=="table" and type(helper)=="table" then
                        local serum=normalize(rawget(loadout,"Serum"))
                        if serum then
                            App.TitanMastery.SerumRuntime=object; App.TitanMastery.SerumCache=serum; App.TitanMastery.SerumCacheAt=now
                            return serum
                        end
                    end
                end
            end
        end
    end
    App.TitanMastery.SerumCacheAt=now
    return nil
end

App.TitanMastery.ShiftSkillForSerum = function(serum)
    return ({Attack="999",Armored="998",Female="997",Colossal="996"})[tostring(serum or "")]
end

App.TitanMastery.ReadShifterSkills = function(force)
    local now=os.clock()
    if force~=true and now-(App.TitanMastery.SkillCacheAt or 0)<3.0 then return App.TitanMastery.SkillCache or {} end
    App.TitanMastery.SkillCacheAt=now
    local getRemote=select(1,spearRemotes())
    if not getRemote or not getRemote:IsA("RemoteFunction") then return App.TitanMastery.SkillCache or {} end
    local ok,profile=pcall(function() return getRemote:InvokeServer("Data","Copy") end)
    if not ok or type(profile)~="table" then return App.TitanMastery.SkillCache or {} end
    local slotKey=profile.Current_Slot or player:GetAttribute("Slot")
    local slots=type(profile.Slots)=="table" and profile.Slots or nil
    local slot=slots and (slots[slotKey] or slots[tostring(slotKey)] or slots[tonumber(slotKey)]) or nil
    local source=type(slot)=="table" and type(slot.Skills)=="table" and slot.Skills.Shifter or nil
    local blocked={[200]=true,[300]=true,[400]=true,[500]=true,[999]=true,[998]=true,[997]=true,[996]=true}
    local out={}
    if type(source)=="table" then
        for _,skillId in pairs(source) do
            local n=tonumber(skillId)
            if n and not blocked[n] then out[#out+1]=tostring(skillId) end
        end
    end
    table.sort(out,function(a,b) return (tonumber(a) or 0)<(tonumber(b) or 0) end)
    App.TitanMastery.SkillCache=out
    return out
end

App.TitanMastery.FindTarget = function()
    local entries = bladeCandidateEntries()
    if #entries == 0 then return nil end

    table.sort(entries, function(a, b)
        return (tonumber(a.Distance) or math.huge) < (tonumber(b.Distance) or math.huge)
    end)

    -- Gauge building prefers a regular Titan. A raid boss is fallback-only.
    for _, entry in ipairs(entries) do
        if entry and entry.Titan and not isRaidBossTitan(entry.Titan) then
            return entry
        end
    end

    return entries[1]
end

App.TitanMastery.ControlledBladeKill = function(entry, barBefore)
    if BladeRuntime.Busy
        or SpearRuntime.RefillBusy
        or (App.BladeRefill and App.BladeRefill.Busy) then
        return false, "Blade worker busy"
    end

    local titan = entry and entry.Titan
    local nape = titan and bladeExactNape(titan) or nil
    if not isTitanAlive(titan) or not nape then
        return false, "Target changed"
    end

    local _, postRemote = spearRemotes()
    if not postRemote or not postRemote:IsA("RemoteEvent") then
        return false, "POST remote missing"
    end

    spearTravelToPack(nape.Position)
    nape = titan and bladeExactNape(titan) or nil
    if not isTitanAlive(titan) or not nape then
        return false, "Target changed"
    end

    BladeRuntime.Busy = true
    local ok, err = pcall(function()
        postRemote:FireServer("Attacks", "Slash", true)
        task.wait(0.025)
        postRemote:FireServer("Hitboxes", "Register", nape, math.random(625, 850))
    end)
    BladeRuntime.Busy = false

    if not ok then return false, tostring(err) end

    App.TitanMastery.PendingGaugeAt = os.clock()
    App.TitanMastery.PendingGaugeBar = tonumber(barBefore) or 0
    App.TitanMastery.PendingGaugeTitan = titan
    return true, "Blade single-kill sent"
end

App.TitanMastery.ControlledSpearKill = function(entry, barBefore)
    if SpearRuntime.Busy or SpearRuntime.RefillBusy then
        return false, "Spear worker busy"
    end

    local titan = entry and entry.Titan
    local nape = titan and spearExactNape(titan) or nil
    if not isTitanAlive(titan) or not nape then
        return false, "Target changed"
    end

    local ammo = spearReadAmmo()
    if App.Values.AutoSpearRefill == true
        and ammo ~= nil
        and ammo <= 0 then
        spearRefillStep()
        return false, "Refilling Spears"
    end

    if not spearEnsureSafeBlastDistance(nape.Position) then
        return false, "Repositioning for safe spear blast"
    end

    local spearName = spearFindAvailableName()
    if not spearName then return false, "No spear available" end

    local getRemote, postRemote = spearRemotes()
    if not getRemote or not getRemote:IsA("RemoteFunction")
        or not postRemote or not postRemote:IsA("RemoteEvent") then
        return false, "Spear remotes missing"
    end

    SpearRuntime.Busy = true
    local ok, err = pcall(function()
        local accepted = getRemote:InvokeServer("Spears", "S_Fire", tostring(spearName))
        if accepted ~= true then error("S_Fire rejected") end

        local character = spearCharacter()
        local started = os.clock()
        while character and character.Parent
            and character:GetAttribute("Current_Spear") == nil
            and os.clock() - started < 0.60 do
            task.wait(0.01)
        end

        task.wait(0.080)
        nape = titan and spearExactNape(titan) or nil
        if not nape or not nape.Parent then error("Nape disappeared") end
        if not spearBlastPositionSafe(nape.Position) then error("Unsafe blast distance") end
        postRemote:FireServer("Spears", "S_Explode", nape.Position)
    end)
    SpearRuntime.Busy = false

    if not ok then return false, tostring(err) end

    App.TitanMastery.PendingGaugeAt = os.clock()
    App.TitanMastery.PendingGaugeBar = tonumber(barBefore) or 0
    App.TitanMastery.PendingGaugeTitan = titan
    return true, "Spear single-kill sent"
end

App.TitanMastery.GaugeStep = function(bar)
    local now = os.clock()

    -- Never farm a fake/non-existent gauge. Step() owns the missing-gauge gate,
    -- but keep this fail-safe here too so a nil bar cannot kill Titans.
    if bar == nil then
        App.TitanMastery.SetStatus("Waiting for Shift gauge")
        return true
    end

    if (App.TitanMastery.PendingGaugeAt or 0) > 0 then
        local before = tonumber(App.TitanMastery.PendingGaugeBar) or 0
        local elapsed = now - App.TitanMastery.PendingGaugeAt
        local pendingTitan = App.TitanMastery.PendingGaugeTitan
        local targetGone = pendingTitan ~= nil and not isTitanAlive(pendingTitan)

        if bar > before + 0.01 then
            App.TitanMastery.PendingGaugeAt = 0
            App.TitanMastery.PendingGaugeBar = nil
            App.TitanMastery.PendingGaugeTitan = nil
            App.TitanMastery.NextGaugeKillAt = now + 0.025
            App.TitanMastery.SetStatus("Building Shift Gauge • " .. math.floor(bar + 0.5) .. "%")
        elseif elapsed < 0.42 then
            if targetGone and elapsed >= 0.12 then
                App.TitanMastery.SetStatus("Confirming Shift gauge • " .. math.floor(bar + 0.5) .. "%")
            else
                App.TitanMastery.SetStatus("Building Shift Gauge • " .. math.floor(bar + 0.5) .. "%")
            end
            return true
        else
            -- One target at a time is preserved, but do not idle for 1.35s after
            -- every kill. If replication is late, move on after a short bound.
            App.TitanMastery.PendingGaugeAt = 0
            App.TitanMastery.PendingGaugeBar = nil
            App.TitanMastery.PendingGaugeTitan = nil
            App.TitanMastery.NextGaugeKillAt = now + 0.04
            App.TitanMastery.SetStatus("Building Shift Gauge • next Titan")
            return true
        end
    end

    if bar >= 99.5 then
        App.TitanMastery.State = "SHIFT_READY"
        return App.TitanMastery.TryShift()
    end

    if now < (App.TitanMastery.NextGaugeKillAt or 0) then
        return true
    end

    local entry = App.TitanMastery.FindTarget()
    if not entry then
        App.TitanMastery.SetStatus("Building Shift Gauge • scanning for Titans")
        return true
    end

    local ok, reason = false, "Equip Blades or Spears"
    if App.Values.AutoFarmSpears == true and spearEquipped() then
        ok, reason = App.TitanMastery.ControlledSpearKill(entry, bar)
    elseif App.Values.AutoFarmBlades == true and bladeEquipped() then
        ok, reason = App.TitanMastery.ControlledBladeKill(entry, bar)
    elseif spearEquipped() then
        ok, reason = App.TitanMastery.ControlledSpearKill(entry, bar)
    elseif bladeEquipped() then
        ok, reason = App.TitanMastery.ControlledBladeKill(entry, bar)
    end

    if ok then
        App.TitanMastery.SetStatus("Building Shift Gauge • " .. math.floor(bar + 0.5) .. "%")
    else
        App.TitanMastery.SetStatus("Building Shift Gauge • " .. tostring(reason))
        App.TitanMastery.NextGaugeKillAt = now + 0.05
    end

    return true
end

App.TitanMastery.TryNativeShift = function()
    local runtime = App.TitanMastery.SerumRuntime
    if type(runtime) ~= "table" then
        App.TitanMastery.FindEquippedSerum(true)
        runtime = App.TitanMastery.SerumRuntime
    end
    if type(runtime) ~= "table" then
        return false, "live Shifter runtime not found"
    end

    local modules = rawget(runtime, "Modules")
    local skills = type(modules) == "table" and rawget(modules, "Skills") or nil
    local use = type(skills) == "table" and rawget(skills, "Use") or nil
    if type(use) ~= "function" then
        return false, "native Shifter skill path unavailable"
    end

    -- Use the game's own cross-device skill path. Passing the generic Shift
    -- action lets the live client resolve the equipped serum exactly as a
    -- normal PC/mobile Shift press does.
    local ok, result = pcall(use, runtime, player, false, 1, "999")
    if not ok then return false, tostring(result) end
    return true, result
end

App.TitanMastery.TryShift = function()
    if App.TitanMastery.RemainingShifts ~= nil and App.TitanMastery.RemainingShifts <= 0 then
        return App.TitanMastery.Disable("No Shifts Remaining")
    end

    local now = os.clock()
    if now < (App.TitanMastery.LastShiftAttemptAt or 0) + 0.70 then
        App.TitanMastery.SetStatus("Shift Ready • waiting for transformation")
        return true
    end

    if (App.TitanMastery.ShiftAttemptWindowAt or 0) == 0
        or now - App.TitanMastery.ShiftAttemptWindowAt > 6.0 then
        App.TitanMastery.ShiftAttemptWindowAt = now
        App.TitanMastery.ShiftAttemptCount = 0
    end

    if App.TitanMastery.ShiftAttemptCount >= 5 then
        return App.TitanMastery.Disable("Shift failed to start")
    end

    local serum = App.TitanMastery.FindEquippedSerum(App.TitanMastery.ShiftAttemptCount == 0)
    local shiftSkill = App.TitanMastery.ShiftSkillForSerum(serum)
    if not shiftSkill then
        App.TitanMastery.LastShiftAttemptAt = now
        App.TitanMastery.ShiftAttemptCount += 1
        App.TitanMastery.SetStatus("Shift Ready • equipped serum not detected")
        if App.TitanMastery.ShiftAttemptCount >= 3 then
            return App.TitanMastery.Disable("Equipped serum not detected")
        end
        return true
    end

    App.TitanMastery.ActiveSerum = serum
    App.TitanMastery.LastShiftAttemptAt = now
    App.TitanMastery.ShiftAttemptCount += 1
    App.TitanMastery.SetStatus("Shifting • " .. tostring(serum))

    local nativeOk, nativeResult = App.TitanMastery.TryNativeShift()
    App.TitanMastery.NativeShiftLastError = nativeOk and nil or tostring(nativeResult)

    if not nativeOk then
        -- Compatibility fallback for executors/builds where the live client
        -- skill table cannot be reached. Transformation is still confirmed
        -- only from the real Shifter state on a later Step().
        local getRemote = select(1, spearRemotes())
        if getRemote and getRemote:IsA("RemoteFunction") then
            pcall(function()
                getRemote:InvokeServer("S_Skills", "Usage", shiftSkill, false)
            end)
        end
    end

    return true
end

App.TitanMastery.ShiftedStep = function()
    local entry=App.TitanMastery.FindTarget()
    if not entry then App.TitanMastery.SetStatus("Farming Titan Mastery • scanning for Titans"); return true end
    local titan=entry.Titan
    local targetPart=titan and (spearExactNape(titan) or bladeExactNape(titan)) or nil
    if not isTitanAlive(titan) or not targetPart then return true end
    local character,root,humanoid=spearCharacter(),spearRoot(),spearHumanoid()
    if not character or not root or not humanoid or humanoid.Health<=0 then return true end
    local mode=tostring(App.Values.TitanMasteryMode or "Punching")
    if mode~="Skill Usage" then mode="Punching" end
    local modelSize=35
    pcall(function() local size=titan:GetExtentsSize(); modelSize=math.max(size.Y,size.Z) end)
    local behind=mode=="Punching" and math.clamp(modelSize*0.20,8,22) or math.clamp(modelSize*0.30,12,34)
    local above=mode=="Punching" and math.clamp(modelSize*0.07,3,10) or math.clamp(modelSize*0.11,5,16)
    local position=targetPart.Position-targetPart.CFrame.LookVector*behind+Vector3.new(0,above,0)
    clearCombatSafety()
    pcall(function()
        character:PivotTo(CFrame.lookAt(position,targetPart.Position))
        root.AssemblyLinearVelocity=Vector3.zero; root.AssemblyAngularVelocity=Vector3.zero
    end)
    local getRemote,postRemote=spearRemotes(); local now=os.clock()
    if mode=="Punching" and postRemote and postRemote:IsA("RemoteEvent") and now-(App.TitanMastery.LastPunchAt or 0)>=0.55 then
        App.TitanMastery.LastPunchAt=now
        local combo=math.clamp(math.floor(tonumber(App.TitanMastery.Combo) or 1),1,4)
        local limit=math.clamp(math.floor(tonumber(App.Values.BladeMultiHit) or 10),1,10)
        local targets={}
        for _,candidate in ipairs(bladeCandidateEntries()) do
            if #targets>=limit then break end
            if candidate and candidate.Titan and not isRaidBossTitan(candidate.Titan) and isTitanAlive(candidate.Titan) then
                local nape=bladeExactNape(candidate.Titan); if nape then targets[#targets+1]=nape end
            end
        end
        if #targets==0 then targets[1]=targetPart end
        pcall(function()
            postRemote:FireServer("Attacks","Slash",true)
            for _,nape in ipairs(targets) do if nape and nape.Parent then postRemote:FireServer("Hitboxes","Register",nape,nil,nil,combo) end end
        end)
        App.TitanMastery.Combo=combo>=4 and 1 or combo+1
    elseif mode=="Skill Usage" and getRemote and getRemote:IsA("RemoteFunction") and now>=(App.TitanMastery.NextSkillAt or 0) then
        local skills=App.TitanMastery.ReadShifterSkills(false)
        if #skills>0 then
            local cursor=math.clamp(math.floor(tonumber(App.TitanMastery.SkillCursor) or 1),1,#skills)
            local skillId=skills[cursor]; App.TitanMastery.SkillCursor=cursor>=#skills and 1 or cursor+1
            App.TitanMastery.NextSkillAt=now+0.85
            pcall(function() getRemote:InvokeServer("S_Skills","Usage",tostring(skillId),false) end)
        else
            App.TitanMastery.NextSkillAt=now+1.5
        end
    end
    App.TitanMastery.SetStatus((mode=="Punching" and "Punching Mastery" or "Skill Mastery").." • "..App.TitanMastery.ShiftText())
    return true
end

App.TitanMastery.Step = function()
    if App.Values.AutoTitanMastery ~= true or RuntimeKind ~= "Gameplay" then
        if App.TitanMastery.Status ~= "Off"
            and App.TitanMastery.HardDisabled ~= true then
            App.TitanMastery.Status = "Off"
        end
        App.TitanMastery.Initialized = false
        return false
    end

    if App.Cutscene and App.Cutscene.Active == true then
        App.TitanMastery.SetStatus("Cutscene • Titan Mastery suspended")
        return true
    end

    if App.RaidChestAuto and App.RaidChestAuto.Busy then
        App.TitanMastery.SetStatus("Raid chests • Titan Mastery suspended")
        return true
    end

    if App.Colossal and App.Colossal.OwnsCombat and App.Colossal.OwnsCombat() then
        App.TitanMastery.SetStatus("Colossal controller owns combat")
        return false
    end

    local shifted = App.TitanMastery.IsShifted()
    local bar = App.TitanMastery.ReadBar()
    local now = os.clock()

    if not App.TitanMastery.Initialized then
        App.TitanMastery.Initialized = true
        App.TitanMastery.ResetRun("Titan Mastery armed")
        App.TitanMastery.WasShifted = shifted
    end

    -- No Skills / Glass Cannon can remove Shifter access for the run. More
    -- importantly, a missing live Bar means there is nothing to farm. Never
    -- keep killing Titans while a Shift gauge does not exist.
    if not shifted and bar == nil then
        App.TitanMastery.BarMissingSince = App.TitanMastery.BarMissingSince or now
        local missingFor = now - App.TitanMastery.BarMissingSince
        local modifier = App.TitanMastery.BlockingModifier()

        if modifier and missingFor >= 0.30 then
            return App.TitanMastery.Disable(modifier .. " modifier • Shifting unavailable")
        end
        if missingFor >= 1.00 then
            return App.TitanMastery.Disable("Shift gauge unavailable")
        end

        App.TitanMastery.SetStatus("Waiting for Shift gauge")
        return true
    end

    App.TitanMastery.BarMissingSince = nil
    App.TitanMastery.SyncShiftCount(false)

    if shifted and not App.TitanMastery.WasShifted then
        App.TitanMastery.WasShifted = true
        App.TitanMastery.ShiftAttemptCount = 0
        App.TitanMastery.ShiftAttemptWindowAt = 0
        if App.TitanMastery.RemainingShifts ~= nil then
            App.TitanMastery.RemainingShifts = math.max(0, App.TitanMastery.RemainingShifts - 1)
        end
        App.TitanMastery.State = "MASTERY"
        App.TitanMastery.SetStatus("Shift confirmed • farming Titan Mastery")
    elseif not shifted and App.TitanMastery.WasShifted then
        App.TitanMastery.WasShifted = false
        App.TitanMastery.PendingGaugeAt = 0
        App.TitanMastery.PendingGaugeBar = nil
        App.TitanMastery.PendingGaugeTitan = nil
        App.TitanMastery.NextGaugeKillAt = now + 0.05

        if App.TitanMastery.RemainingShifts ~= nil
            and App.TitanMastery.RemainingShifts <= 0 then
            return App.TitanMastery.Disable("No Shifts Remaining")
        end

        App.TitanMastery.State = "BUILD_GAUGE"
        App.TitanMastery.SetStatus("Titan Form Lost • rebuilding Shift Gauge")
    end

    if shifted then
        return App.TitanMastery.ShiftedStep()
    end

    return App.TitanMastery.GaugeStep(bar)
end


-- ==========================================================================
-- R7 GAMEPLAY SHIP • TITAN MASTERY V6.7 PROVEN ENGINE
-- Ported from the standalone build that passed Attack/Female/Colossal and
-- stable Punching & Abilities tests. Main combat owns this through Step().
-- ==========================================================================
(function()
    local PlayersV67 = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local Workspace = game:GetService("Workspace")
    local LP = PlayersV67.LocalPlayer or player
    local PlayerGui = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui")
    local ENV = (type(getgenv) == "function" and getgenv()) or _G

    local Runtime = {
        Alive = true,
        Profile = nil, SlotData = nil, CurrentSlot = nil, Serum = nil,
        Hotbar = {}, Shifter = {}, Family = "Unknown",
        MasteryStatus = "Off", LastProfileAt = 0, LastSkillAt = 0,
        LastShiftAttemptAt = 0, ShiftAttempts = 0,
        LastPunchAt = 0, NextPunchAt = 0, LastGaugeHitAt = 0,
        PendingGauge = nil, GaugeWeaponStatus = "Detecting", SkillCursor = 1,
        ToggleSkillIds = {}, ToggleLatched = {}, SkillFirstPass = {},
        ToggleDiscoveryAt = 0, ToggleDiscoveryStatus = "Idle", ToggleDiscoverySerum = nil,
        ShifterAbilityBusy = false, SkillHoverTarget = nil, SkillHoverLastCFrame = nil,
        SkillHoverStatus = "Idle", SkillHoverLastAt = 0,
        NextGaugeKillAt = 0, LastSpearRefillAt = 0, SpearRefillPending = false,
        NextCombinedAbilityAt = 0, CombinedTarget = nil, CombinedPunchOnlyUntil = 0,
        CombinedStatus = "Idle", LastColossalSafePlaceAt = 0,
        ColossalSafeAnchorStatus = "Idle", ColossalSkillGuard = {}, NextColossalSkillAt = 0,
        ShiftAcceptedAt = 0, ShiftAcceptedCount = nil, ShiftActorStatus = "Idle",
        ShiftActorDispatchAt = 0, ShiftTransitionHoldCFrame = nil,
        ShiftTransitionHoldActive = false, ShiftTransitionHoldStartedAt = 0,
        ShiftTransitionShiftedAt = 0, ShiftTransitionStatus = "Idle",
    }

    local Settings = {
        AutoTitanMastery = false,
        TitanMode = "Punching",
        MultiHit = 4,
    }

    local SHIFT_IDS = {Attack="999", Armored="998", Female="997", Colossal="996"}
    local EJECT_IDS = {Attack="200", Armored="300", Female="400", Colossal="500"}
    local SHIFTER_SKILL_NAMES = {
        ["201"]="Hardening", ["401"]="Ice Hardening",
        ["506"]="Incendiary Volley", ["507"]="Heatwave", ["500"]="Eject",
    }
    local TOGGLE_FALLBACK = {Attack="201", Female="401", Colossal="507"}
    local TOGGLE_DISPLAY = {
        Attack="Hardening", Female="Ice Hardening",
        Armored="Unstoppable Charge", Colossal="Heatwave",
    }

local function getRemotes()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local GET = remotes and remotes:FindFirstChild("GET")
    local POST = remotes and remotes:FindFirstChild("POST")
    return GET, POST
end

local function invoke(...)
    local GET = select(1, getRemotes())
    if not GET or not GET:IsA("RemoteFunction") then
        return false, "GET missing"
    end
    local packed
    local ok, err = pcall(function(...)
        packed = table.pack(GET:InvokeServer(...))
    end, ...)
    if not ok then return false, err end
    return true, table.unpack(packed, 1, packed.n)
end

local function post(...)
    local _, POST = getRemotes()
    if not POST or not POST:IsA("RemoteEvent") then
        return false, "POST missing"
    end
    local ok, err = pcall(POST.FireServer, POST, ...)
    return ok, err
end

local function normalizeSerum(v)
    local s = string.lower(tostring(v or ""))
    if string.find(s, "attack", 1, true) then return "Attack" end
    if string.find(s, "armor", 1, true) or string.find(s, "armour", 1, true) then return "Armored" end
    if string.find(s, "female", 1, true) then return "Female" end
    if string.find(s, "colossal", 1, true) then return "Colossal" end
    return nil
end

local function currentCharacter()
    return LP.Character
end

local function currentRoot()
    local c = currentCharacter()
    return c and (c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart) or nil
end

local function currentHumanoid()
    local c = currentCharacter()
    return c and c:FindFirstChildOfClass("Humanoid") or nil
end

local function isShifted()
    local c = currentCharacter()
    if not c then return false end
    local value = c:GetAttribute("Shifter")
    return value ~= nil and value ~= false
end

local function readBar()
    local value = tonumber(LP:GetAttribute("Bar"))
    local maxValue = tonumber(LP:GetAttribute("Max_Bar")) or 100
    if value == nil then return nil, maxValue end
    return value, math.max(1, maxValue)
end

local function readShiftCount()
    local value = tonumber(LP:GetAttribute("Shift"))
    if value ~= nil then return math.max(0, math.floor(value + 0.5)) end
    local c = currentCharacter()
    value = c and tonumber(c:GetAttribute("Shift")) or nil
    return value and math.max(0, math.floor(value + 0.5)) or nil
end

local function resolveFamily(slot)
    if type(slot) ~= "table" then return "Unknown" end

    for _, k in ipairs({"Family", "CurrentFamily", "EquippedFamily"}) do
        if slot[k] ~= nil and tostring(slot[k]) ~= "" then
            return tostring(slot[k])
        end
    end

    local loadouts = slot.Loadouts
    if type(loadouts) == "table" then
        for _, info in pairs(loadouts) do
            local d = type(info) == "table" and info.Info or nil
            if type(d) == "table" and d.Family then
                local family = tostring(d.Family)
                if family ~= "" then return family end
            end
        end
    end

    return "Unknown"
end

local function profileRefresh(force)
    local now = os.clock()
    if not force and now - Runtime.LastProfileAt < 1.5 then
        return Runtime.SlotData ~= nil
    end
    Runtime.LastProfileAt = now

    local ok, profile = invoke("Data", "Copy")
    if not ok or type(profile) ~= "table" then
        Runtime.Status = "Profile read failed"
        return false
    end

    local slotKey = profile.Current_Slot or LP:GetAttribute("Slot") or "A"
    local slots = type(profile.Slots) == "table" and profile.Slots or nil
    local slot = slots and (slots[slotKey] or slots[tostring(slotKey)] or slots[tonumber(slotKey)]) or nil
    if type(slot) ~= "table" then
        Runtime.Status = "Current slot missing"
        return false
    end

    Runtime.Profile = profile
    Runtime.CurrentSlot = slotKey
    Runtime.SlotData = slot
    Runtime.Serum = normalizeSerum(slot.Serum)
    Runtime.Family = resolveFamily(slot)

    local skills = type(slot.Skills) == "table" and slot.Skills or {}
    Runtime.Hotbar = type(skills.Hotbar) == "table" and skills.Hotbar or {}
    Runtime.Shifter = type(skills.Shifter) == "table" and skills.Shifter or {}

    return true
end

local function slotForSkillId(skillId, source)
    skillId = tostring(skillId or "")
    source = source or Runtime.Hotbar
    for slot, id in pairs(source or {}) do
        if tostring(id or "") == skillId then
            local n = tonumber(slot)
            if n and n >= 1 and n <= 5 then return n end
        end
    end
    return nil
end

local function skillIdForSlot(slot, shifted)
    local source = shifted and Runtime.Shifter or Runtime.Hotbar
    local value = source and (source[slot] or source[tostring(slot)])
    if value == nil or tostring(value) == "" then return nil end
    return tostring(value)
end

local function cooldownValue(slot)
    if not slot then return nil end
    return LP:GetAttribute("Skill_" .. tostring(slot))
end

local function cooldownNumber(slot)
    local v = cooldownValue(slot)
    if type(v) == "number" then return v end
    if type(v) == "string" then
        local n = tonumber(string.match(v, "[-%d%.]+"))
        if n ~= nil then return n end
    end
    return nil
end

local function skillReady(slot)
    local v = cooldownValue(slot)
    if v == nil or v == false then return true end
    if type(v) == "number" then return v <= 0 end
    local n = tonumber(v)
    if n ~= nil then return n <= 0 end
    local clean = string.lower(string.gsub(tostring(v), "%s+", ""))
    if clean == "" or clean == "ready" or clean == "false" then return true end
    local numeric = tonumber(string.match(clean, "[-%d%.]+"))
    return numeric ~= nil and numeric <= 0 or false
end

local function useSkillSlot(slot)
    slot = tonumber(slot)
    if not slot or slot < 1 or slot > 5 then
        return false, "invalid slot"
    end
    local ok, a, b, c = invoke("S_Skills", "Usage", slot)
    if not ok then return false, a end
    Runtime.LastSkillAt = os.clock()
    return true, a, b, c
end

local function waitForCooldownStart(slot, timeout)
    local started = os.clock()
    local duration = math.max(0.25, tonumber(timeout) or 0.90)
    while Runtime.Alive and os.clock() - started < duration do
        if not skillReady(slot) then return true, cooldownValue(slot) end
        task.wait(0.04)
    end
    return not skillReady(slot), cooldownValue(slot)
end

local function waitUntilSkillReady(slot, timeout)
    local started = os.clock()
    local duration = math.max(0.35, tonumber(timeout) or 8.0)
    while Runtime.Alive and os.clock() - started < duration do
        if skillReady(slot) then return true end
        task.wait(0.04)
    end
    return skillReady(slot)
end

local function trackedUseSkillSlot(slot, attempts, timeout)
    slot = tonumber(slot)
    if not slot then return false, "invalid slot" end
    if not skillReady(slot) then return false, "cooldown" end

    local count = math.max(1, math.floor(tonumber(attempts) or 2))
    for attempt = 1, count do
        local ok, err = useSkillSlot(slot)
        if not ok then return false, err end
        local confirmed, value = waitForCooldownStart(slot, timeout or 0.95)
        if confirmed then return true, value end
        if attempt < count then task.wait(0.18) end
    end
    return false, "cast not accepted"
end


-- Toggle-safe / first-pass-safe dispatch. It NEVER sends the same activation a
-- second time just because cooldown telemetry is absent. This is critical for
-- Hardening / Ice Hardening / Unstoppable Charge / Heatwave: a second press is OFF.
local function singleDispatchSkillSlot(slot, expectedId, timeout)
    slot = tonumber(slot)
    if not slot then return false, "invalid slot" end
    if not skillReady(slot) then return false, "cooldown" end

    local ok, err = useSkillSlot(slot)
    if not ok then return false, err end

    local started = os.clock()
    local duration = math.max(0.20, tonumber(timeout) or 0.65)
    while Runtime.Alive and os.clock() - started < duration do
        local live = tostring(LP:GetAttribute("Skill") or "")
        if expectedId and live == tostring(expectedId) then
            return true, "Skill " .. live
        end
        if not skillReady(slot) then
            return true, cooldownValue(slot)
        end
        task.wait(0.03)
    end

    -- The invoke itself succeeded. For a toggle, safety beats blind retry: latch
    -- the single dispatch and never press it twice in the same transformation.
    return true, "single dispatch • no retry"
end

-- V6.5 Colossal fast dispatch. Colossal has no M1 path, so once Heatwave is
-- latched ON we can cycle the remaining skills much faster without waiting over
-- a second for cooldown telemetry after every press. One dispatch only; a short
-- local guard prevents accidental same-slot spam if the HUD is late to update.
local function colossalFastDispatchSkillSlot(slot, expectedId)
    slot = tonumber(slot)
    if not slot then return false, "invalid slot" end

    Runtime.ColossalSkillGuard = Runtime.ColossalSkillGuard or {}
    local now = os.clock()
    if now < (Runtime.NextColossalSkillAt or 0) then
        return false, "global guard"
    end
    if now < (Runtime.ColossalSkillGuard[slot] or 0) then
        return false, "slot guard"
    end
    if not skillReady(slot) then return false, "cooldown" end

    local ok, err = useSkillSlot(slot)
    if not ok then return false, err end

    -- The guard is deliberately short: enough to absorb delayed UI replication,
    -- but still fast enough to chain different Colossal abilities back-to-back.
    Runtime.ColossalSkillGuard[slot] = now + 0.55
    Runtime.NextColossalSkillAt = now + 0.20

    local started = now
    while Runtime.Alive and os.clock() - started < 0.18 do
        local live = tostring(LP:GetAttribute("Skill") or "")
        if expectedId and live == tostring(expectedId) then
            return true, "Skill " .. live
        end
        if not skillReady(slot) then
            return true, cooldownValue(slot)
        end
        task.wait(0.02)
    end

    -- Never blind-retry here. Returning success after the one invoke keeps the
    -- chain fast and avoids duplicate activations if the client telemetry lags.
    return true, "fast dispatch"
end


local NAPE_NAMES = {
    Nape = true,
    NapeHitbox = true,
    ["Nape Hitbox"] = true,
    WeakPoint = true,
}

local function titanHumanoid(titan)
    return titan and titan:FindFirstChildOfClass("Humanoid") or nil
end

local function titanAlive(titan)
    if not titan or not titan.Parent or not titan:IsA("Model") then return false end
    local h = titanHumanoid(titan)
    -- Match the proven main farm: partially-created Titan models without a live
    -- Humanoid are NOT valid gauge targets. V2 could repeatedly select one and
    -- appear frozen at the same gauge value.
    if not h or h.Health <= 0 then return false end
    local dead = titan:GetAttribute("Dead")
    if dead == true then return false end
    return true
end

local function exactNape(titan)
    if not titan then return nil end
    for _, obj in ipairs(titan:GetDescendants()) do
        if obj:IsA("BasePart") and NAPE_NAMES[obj.Name] then
            return obj
        end
    end

    local hitboxes = titan:FindFirstChild("Hitboxes")
    if hitboxes then
        local hit = hitboxes:FindFirstChild("Hit")
        local nape = hit and hit:FindFirstChild("Nape")
        if nape and nape:IsA("BasePart") then return nape end
    end

    return nil
end

local function titanFolder()
    return Workspace:FindFirstChild("Titans")
end

local function detectedTitans(maxCount)
    local root = currentRoot()
    local folder = titanFolder()
    if not root or not folder then return {} end

    local list = {}
    for _, titan in ipairs(folder:GetChildren()) do
        if titan:IsA("Model") and titanAlive(titan) then
            local nape = exactNape(titan)
            if nape then
                list[#list + 1] = {
                    Titan = titan,
                    Nape = nape,
                    Distance = (nape.Position - root.Position).Magnitude,
                }
            end
        end
    end

    table.sort(list, function(a, b)
        return a.Distance < b.Distance
    end)

    if maxCount and #list > maxCount then
        while #list > maxCount do
            table.remove(list)
        end
    end
    return list
end

local function pivotNear(entry, distanceScale)
    local c = currentCharacter()
    local root = currentRoot()
    if not c or not root or not entry or not entry.Nape or not entry.Nape.Parent then return false end

    local nape = entry.Nape
    local titan = entry.Titan
    local size = 30
    pcall(function()
        local ext = titan:GetExtentsSize()
        size = math.max(ext.Y, ext.Z)
    end)

    local behind = math.clamp(size * (distanceScale or 0.22), 8, 34)
    local above = math.clamp(size * 0.08, 3, 14)
    local pos = nape.Position - nape.CFrame.LookVector * behind + Vector3.new(0, above, 0)
    return pcall(function()
        c:PivotTo(CFrame.lookAt(pos, nape.Position))
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
end

local function colossalSafeGroundStep(preferredEntry)
    if Runtime.Serum ~= "Colossal" or not isShifted() then
        Runtime.ColossalSafeAnchorStatus = "Idle"
        return false
    end

    local c = currentCharacter()
    local root = currentRoot()
    if not c or not root then
        Runtime.ColossalSafeAnchorStatus = "Waiting for character"
        return false
    end

    local entry = preferredEntry
    if not entry or not entry.Nape or not entry.Nape.Parent or not titanAlive(entry.Titan) then
        local list = detectedTitans(1)
        entry = list[1]
    end
    if not entry or not entry.Nape or not entry.Nape.Parent then
        Runtime.ColossalSafeAnchorStatus = "No live Titan"
        return false
    end

    local now = os.clock()
    local target = entry.Nape.Position
    local distance = (target - root.Position).Magnitude
    if distance <= 180 then
        Runtime.ColossalSafeAnchorStatus = string.format("PLANTED • %.0f studs", distance)
        return false
    end
    if now - (Runtime.LastColossalSafePlaceAt or 0) < 2.25 then
        Runtime.ColossalSafeAnchorStatus = string.format("HOLD • %.0f studs", distance)
        return false
    end

    local flat = Vector3.new(root.Position.X - target.X, 0, root.Position.Z - target.Z)
    if flat.Magnitude < 1 then
        flat = Vector3.new(0, 0, 1)
    else
        flat = flat.Unit
    end

    local desiredXZ = target + flat * 82
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {c}

    local currentGround = Workspace:Raycast(root.Position + Vector3.new(0, 8, 0), Vector3.new(0, -420, 0), params)
    local clearance = 42
    if currentGround then
        clearance = math.clamp(root.Position.Y - currentGround.Position.Y, 18, 120)
    end

    local probe = Vector3.new(desiredXZ.X, math.max(root.Position.Y, target.Y) + 180, desiredXZ.Z)
    local ground = Workspace:Raycast(probe, Vector3.new(0, -520, 0), params)
    local y = root.Position.Y
    if ground then y = ground.Position.Y + clearance end

    local pos = Vector3.new(desiredXZ.X, y, desiredXZ.Z)
    local face = Vector3.new(target.X, y, target.Z)
    local ok = pcall(function()
        c:PivotTo(CFrame.lookAt(pos, face))
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    if ok then
        Runtime.LastColossalSafePlaceAt = now
        Runtime.ColossalSafeAnchorStatus = "RE-ANCHOR • 82 studs"
        return true
    end

    Runtime.ColossalSafeAnchorStatus = "Re-anchor failed"
    return false
end

local function skillUsageHoverHold(preferredEntry)
    local skillMode = Settings.TitanMode == "Skill Usage" or Settings.TitanMode == "Punching & Abilities"
    if Settings.AutoTitanMastery ~= true or not skillMode or not isShifted() then
        Runtime.SkillHoverTarget = nil
        Runtime.SkillHoverLastCFrame = nil
        Runtime.SkillHoverStatus = "Idle"
        return false
    end

    local c = currentCharacter()
    local root = currentRoot()
    if not c or not root then
        Runtime.SkillHoverStatus = "Waiting for character"
        return false
    end

    local entry = preferredEntry

    -- V6.1: if an ability already selected a Titan, NEVER re-run nearest-target
    -- selection every 0.02s. The V6 worker could keep swapping nearby Titans as
    -- distances changed, which looked like a 360-degree orbit around the pack.
    if (not entry or not entry.Titan or not titanAlive(entry.Titan)
        or not entry.Nape or not entry.Nape.Parent)
        and Runtime.SkillHoverTarget and titanAlive(Runtime.SkillHoverTarget) then
        local lockedNape = exactNape(Runtime.SkillHoverTarget)
        if lockedNape then
            entry = {
                Titan = Runtime.SkillHoverTarget,
                Nape = lockedNape,
                Distance = (lockedNape.Position - root.Position).Magnitude,
            }
        end
    end

    if not entry or not entry.Titan or not titanAlive(entry.Titan)
        or not entry.Nape or not entry.Nape.Parent then
        local entries = detectedTitans(1)
        entry = entries[1]
    end

    if entry and entry.Titan and titanAlive(entry.Titan) and entry.Nape and entry.Nape.Parent then
        Runtime.SkillHoverTarget = entry.Titan

        -- Colossal still keeps its special ground allowance for now because
        -- Incendiary Volley (506) is a ground-sweep skill. The other forms now
        -- use the SAME close/high nape anchor as Punching instead of the old
        -- 80-stud HRP-relative hold.
        if Runtime.Serum == "Colossal" then
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)
            Runtime.SkillHoverLastCFrame = root.CFrame
            Runtime.SkillHoverLastAt = os.clock()
            Runtime.SkillHoverStatus = "COLOSSAL • ground mode • target locked"
            return true
        end

        local nape = entry.Nape
        local titan = entry.Titan
        local size = 30
        pcall(function()
            local ext = titan:GetExtentsSize()
            size = math.max(ext.Y, ext.Z)
        end)

        -- Exact Punching anchor: slightly behind the nape and slightly above it.
        local behind = math.clamp(size * 0.18, 8, 34)
        local above = math.clamp(size * 0.08, 3, 14)
        local pos = nape.Position - nape.CFrame.LookVector * behind + Vector3.new(0, above, 0)
        local holdCF = CFrame.lookAt(pos, nape.Position)

        local ok = pcall(function()
            c:PivotTo(holdCF)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)

        if ok then
            Runtime.SkillHoverLastCFrame = holdCF
            Runtime.SkillHoverLastAt = os.clock()
            Runtime.SkillHoverStatus = "NAPE LOCK • " .. tostring(entry.Titan.Name) .. " • punching anchor"
            return true
        end
    end

    -- If the locked Titan dies during an animation, freeze at the last safe
    -- nape anchor until the mastery loop selects the replacement. Do not roam.
    if Runtime.SkillHoverLastCFrame then
        local ok = pcall(function()
            c:PivotTo(Runtime.SkillHoverLastCFrame)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        if ok then
            Runtime.SkillHoverStatus = "HOLDING • waiting retarget"
            return true
        end
    end

    Runtime.SkillHoverStatus = "No live Titan • holding velocity"
    pcall(function()
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    return false
end

local function gaugeSafetyHold(entry)
    local c = currentCharacter()
    local root = currentRoot()
    local nape = entry and entry.Nape
    if not c or not root or not nape or not nape.Parent then return false end

    -- Same safety idea as the main SliceHub combat anchor: build gauge high
    -- above the pack instead of sitting on a Titan's nape and eating hits.
    local pos = nape.Position + Vector3.new(0, 250, 0)
    return pcall(function()
        c:PivotTo(CFrame.lookAt(pos, nape.Position))
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
end

local function aimAtEntry(entry, includeCamera)
    local root = currentRoot()
    local nape = entry and entry.Nape
    if not root or not nape or not nape.Parent then return false end

    pcall(function()
        root.CFrame = CFrame.lookAt(root.Position, nape.Position)
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    if includeCamera and Workspace.CurrentCamera then
        pcall(function()
            local cam = Workspace.CurrentCamera
            cam.CFrame = CFrame.lookAt(cam.CFrame.Position, nape.Position)
        end)
    end
    return true
end

local function hudGearRoot()
    local interface = PlayerGui:FindFirstChild("Interface")
    local hud = interface and interface:FindFirstChild("HUD")
    local main = hud and hud:FindFirstChild("Main")
    local top = main and main:FindFirstChild("Top")
    return top and top:FindFirstChild("7") or nil
end

local function gaugeWeaponType()
    local gear = hudGearRoot()
    if not gear then return "Unknown" end
    local spears = gear:FindFirstChild("Spears")
    local blades = gear:FindFirstChild("Blades")
    if spears and spears.Visible == true then return "Spears" end
    if blades and blades.Visible == true then return "Blades" end
    if spears and not blades then return "Spears" end
    if blades and not spears then return "Blades" end
    return "Unknown"
end

local function spearAmmoState()
    local gear = hudGearRoot()
    local spears = gear and gear:FindFirstChild("Spears")
    if not spears then return nil, nil, nil end

    local label = spears:FindFirstChild("Spears")
    if not label or not (label:IsA("TextLabel") or label:IsA("TextButton") or label:IsA("TextBox")) then
        label = spears:FindFirstChildWhichIsA("TextLabel", true)
            or spears:FindFirstChildWhichIsA("TextButton", true)
            or spears:FindFirstChildWhichIsA("TextBox", true)
    end
    if not label then return nil, nil, nil end

    local text = tostring(label.Text or "")
    local currentAmmo, maxAmmo = string.match(text, "(%d+)%s*/%s*(%d+)")
    return tonumber(currentAmmo), tonumber(maxAmmo), label
end

local function spearAmmoFromLabel(label)
    if not label or not label.Parent then return nil end
    local text = tostring(label.Text or "")
    return tonumber(string.match(text, "(%d+)"))
end

local function tryRefillSpears(ammoLabel, maxAmmo, force)
    local now = os.clock()
    local current = spearAmmoFromLabel(ammoLabel)
    local target = math.max(1, math.floor(tonumber(maxAmmo) or 8))

    -- Normal non-empty ammo is usable unless the caller explicitly detected
    -- a stale/ghost rack and requests a forced refill.
    if force ~= true and current and current > 0 then
        Runtime.SpearRefillPending = false
        return true, current
    end

    if Runtime.SpearRefillPending and now - (Runtime.LastSpearRefillAt or 0) < 2.8 then
        Runtime.GaugeWeaponStatus = "Spears • REFILLING"
        return false, current
    end

    Runtime.SpearRefillPending = true
    Runtime.LastSpearRefillAt = now
    Runtime.GaugeWeaponStatus = force == true
        and ("Spears • GHOST " .. tostring(current or "?") .. "/" .. tostring(target) .. " • REFILL")
        or "Spears • REFILL"
    post("Attacks", "Reload")

    -- IMPORTANT: do not resume gauge fire on the first 2/8 or 4/8 update.
    -- AOT:R refills Spears progressively; firing during that animation can leave
    -- the HUD showing ammo that no longer has a real projectile behind it.
    local started = os.clock()
    local peak = tonumber(current) or 0
    local lastChangeAt = started
    while Runtime.Alive and os.clock() - started < 3.25 do
        task.wait(0.05)
        current = spearAmmoFromLabel(ammoLabel)
        if current and current ~= peak then
            peak = current
            lastChangeAt = os.clock()
        end

        if current and current >= target then
            -- Small settle window so the final refill replication finishes before
            -- the next S_Fire can consume anything.
            task.wait(0.16)
            local settled = spearAmmoFromLabel(ammoLabel)
            if settled and settled >= target then
                Runtime.SpearRefillPending = false
                Runtime.GaugeWeaponStatus = "Spears • READY " .. tostring(settled) .. "/" .. tostring(target)
                return true, settled
            end
        end

        -- Fallback for unusual HUDs where the max value cannot be trusted:
        -- accept a non-zero rack only after it has stopped changing for a while.
        if (not maxAmmo or tonumber(maxAmmo) == nil)
            and current and current > 0
            and os.clock() - lastChangeAt >= 0.45 then
            Runtime.SpearRefillPending = false
            Runtime.GaugeWeaponStatus = "Spears • READY " .. tostring(current)
            return true, current
        end
    end

    Runtime.SpearRefillPending = false
    Runtime.GaugeWeaponStatus = "Spears • refill missed"
    return false, current
end

local function waitForSpearAmmoDrop(ammoLabel, beforeAmmo, timeout)
    beforeAmmo = tonumber(beforeAmmo)
    if not beforeAmmo then return nil, false end

    local started = os.clock()
    local live = spearAmmoFromLabel(ammoLabel)
    while Runtime.Alive and os.clock() - started < (tonumber(timeout) or 0.16) do
        live = spearAmmoFromLabel(ammoLabel)
        if live and live < beforeAmmo then
            return live, true
        end
        task.wait(0.015)
    end
    return live, false
end

local function controlledGaugeHit(barBefore)
    local entries = detectedTitans(1)
    local entry = entries[1]
    if not entry then
        Runtime.GaugeWeaponStatus = "No target"
        return false, "No live Titan • scanning"
    end

    gaugeSafetyHold(entry)
    local nape = exactNape(entry.Titan)
    if not titanAlive(entry.Titan) or not nape or not nape.Parent then
        return false, "Target changed"
    end

    local combo = math.random(625, 850)
    local weapon = gaugeWeaponType()

    if weapon == "Spears" then
        local currentAmmo, maxAmmo, ammoLabel = spearAmmoState()
        if not currentAmmo then
            Runtime.GaugeWeaponStatus = "Spears • ammo unreadable"
            return false, "Spears ammo unreadable"
        end

        if Runtime.SpearRefillPending then
            Runtime.GaugeWeaponStatus = "Spears • REFILLING"
            return false, "Spears refill pending"
        end

        if currentAmmo <= 0 then
            local refilled, liveAmmo = tryRefillSpears(ammoLabel, maxAmmo, false)
            if not refilled then
                return false, "Spears refill pending"
            end
            currentAmmo = tonumber(liveAmmo) or spearAmmoFromLabel(ammoLabel) or 0
            if currentAmmo <= 0 then
                Runtime.GaugeWeaponStatus = "Spears • EMPTY"
                return false, "Spears empty after refill"
            end
        end

        local beforeAmmo = spearAmmoFromLabel(ammoLabel) or currentAmmo
        local physicalMax = math.max(1, math.floor((tonumber(spearPhysicalMaxIndex(spearCharacter())) or 8) + 0.5))
        local fireIndex = math.min(math.max(1, math.floor(currentAmmo + 0.5)), physicalMax)
        invoke("Spears", "S_Fire", tostring(fireIndex))
        local afterAmmo, consumed = waitForSpearAmmoDrop(ammoLabel, beforeAmmo, 0.18)

        -- Bonus-capacity perks can report 9/10/... ammo while S_Fire still uses
        -- numbered physical rack slots. Probe the real rack size dynamically;
        -- ammo itself has no upper validity cap.
        if not consumed and maxAmmo then
            for j = physicalMax, 1, -1 do
                local prevAmmo = spearAmmoFromLabel(ammoLabel) or beforeAmmo
                invoke("Spears", "S_Fire", tostring(j))
                local newAmmo, dropped = waitForSpearAmmoDrop(ammoLabel, prevAmmo, 0.07)
                if dropped then
                    afterAmmo = newAmmo
                    consumed = true
                    break
                end
            end
        end

        -- V6.6 ghost-rack recovery: if the HUD says 1/8, 2/8, etc. but no
        -- S_Fire can consume it, the visible count is stale. Do NOT keep trying
        -- to explode/register nonexistent projectiles; force a full refill.
        if not consumed then
            Runtime.GaugeWeaponStatus =
                "Spears • GHOST " .. tostring(beforeAmmo or "?") .. "/" .. tostring(maxAmmo or "?") .. " • recovering"
            local recovered = select(1, tryRefillSpears(ammoLabel, maxAmmo, true))
            return false, recovered and "Spear ghost recovered" or "Spear ghost refill pending"
        end

        local exploded = post("Spears", "S_Explode", nape.Position)
        task.wait(0.012)
        -- The nape register is retained as confirmation/fallback because the old
        -- Colossal P2 route used S_Explode + Hitboxes/Register together reliably.
        local registered = post("Hitboxes", "Register", nape, combo)
        if not exploded and not registered then
            Runtime.GaugeWeaponStatus = "Spears • register failed"
            return false, "Spear hit register failed"
        end

        local liveAmmo = spearAmmoFromLabel(ammoLabel) or afterAmmo
        Runtime.GaugeWeaponStatus = "Spears • " .. tostring(liveAmmo or "?") .. "/" .. tostring(maxAmmo or "?")
    else
        local ok1 = post("Attacks", "Slash", true)
        task.wait(0.025)
        local ok2 = post("Hitboxes", "Register", nape, combo)
        if not ok1 or not ok2 then
            Runtime.GaugeWeaponStatus = "Blades • register failed"
            return false, "Hit register failed"
        end
        Runtime.GaugeWeaponStatus = weapon == "Unknown" and "Blades fallback" or "Blades"
    end

    Runtime.PendingGauge = {
        before = tonumber(barBefore) or 0,
        titan = entry.Titan,
        at = os.clock(),
    }
    Runtime.LastGaugeHitAt = os.clock()
    return true, weapon == "Spears" and "Spear gauge hit" or "Gauge hit"
end

local function shiftGaugeTarget(maxBar)
    maxBar = math.max(1, tonumber(maxBar) or 100)
    if Runtime.Serum == "Colossal" then
        return maxBar
    end
    return maxBar * 0.85
end

local function barReady()
    local bar, maxBar = readBar()
    if bar == nil then return false, nil, maxBar, nil end
    local target = shiftGaugeTarget(maxBar)
    return bar >= target, bar, maxBar, target
end

local function findLocalActor()
    local folder = Workspace:FindFirstChild("Characters")
    local model = folder and folder:FindFirstChild(LP.Name)
    return model and model:FindFirstChild("Actor") or nil
end

local function actorRunner()
    local runner = rawget(ENV, "run_on_actor")
    if type(runner) == "function" then return runner end
    if type(run_on_actor) == "function" then return run_on_actor end
    return nil
end

local function shiftAccepted(beforeCount, shiftId)
    if isShifted() then return true, "Shifter state" end

    local count = readShiftCount()
    if beforeCount ~= nil and count ~= nil and count < beforeCount then
        return true, "Shift counter " .. tostring(beforeCount) .. " -> " .. tostring(count)
    end

    local skill = tostring(LP:GetAttribute("Skill") or "")
    if skill == "999" or skill == tostring(shiftId or "") then
        return true, "Skill " .. skill
    end

    return false, nil
end

local function tryGenericShiftHotbar(beforeCount, shiftId)
    profileRefresh(true)
    local slot = slotForSkillId("999", Runtime.Hotbar)
    if not slot then
        return false, "generic Shift 999 not equipped in normal hotbar"
    end

    -- Exact server-side shape produced by the normal Hotbar branch of
    -- Core.Skills.Use: S_Skills / Usage / <hotbar slot>. Do NOT substitute
    -- serum-specific 998/997 here and do NOT append false as a fake p5.
    local ok, a = invoke("S_Skills", "Usage", slot)
    if not ok then
        return false, "hotbar remote error • " .. tostring(a)
    end

    local started = os.clock()
    while Runtime.Alive and os.clock() - started < 0.85 do
        local accepted, evidence = shiftAccepted(beforeCount, shiftId)
        if accepted then
            return true, "hotbar " .. tostring(slot) .. " • " .. tostring(evidence)
        end
        task.wait(0.03)
    end

    return false, "hotbar " .. tostring(slot) .. " returned but server did not accept Shift"
end

local function tryActorNativeShift(shiftId, beforeCount, hotbarSlot)
    local actor = findLocalActor()
    if not actor then
        Runtime.ShiftActorStatus = "Actor missing"
        return false, "player Actor missing"
    end

    local runner = actorRunner()
    if type(runner) ~= "function" then
        Runtime.ShiftActorStatus = "run_on_actor unavailable"
        return false, "run_on_actor unavailable"
    end

    -- AOT:R's Host/Core.Skills table is in the character Actor's Luau state.
    -- Normal executor getgc() cannot see that state on this client, which is why
    -- V2's native lookup failed even though the actual game Shift press worked.
    -- Run the lookup in the Actor and call the game's own Core.Skills.Use path.
    -- IMPORTANT: 999 here is the game's GENERIC SHIFT action. Core.Skills.Use
    -- resolves 999 through ShifterDataHelper.ShiftSkills[Loadout.Serum], so an
    -- Armored user becomes 998 internally without 998 needing a normal hotbar slot.
    local actorSlot = tonumber(hotbarSlot)
    local callLine = actorSlot
        and ("pcall(use, best, LP, false, " .. tostring(actorSlot) .. ")")
        or 'pcall(use, best, LP, false, 1, "999")'

    local code = [==[
local Players = game:GetService("Players")
local LP = Players.LocalPlayer
if not LP or type(getgc) ~= "function" then return end

