local function clearShiftTransitionHold(status)
    Runtime.ShiftTransitionHoldActive = false
    Runtime.ShiftTransitionHoldCFrame = nil
    Runtime.ShiftTransitionHoldStartedAt = 0
    Runtime.ShiftTransitionShiftedAt = 0
    Runtime.ShiftTransitionStatus = status or "Idle"
end

local function armShiftTransitionHold(originCF)
    if typeof(originCF) ~= "CFrame" then
        local c = currentCharacter()
        if c then
            pcall(function() originCF = c:GetPivot() end)
        end
    end
    if typeof(originCF) ~= "CFrame" then
        Runtime.ShiftTransitionStatus = "No origin CFrame"
        return false
    end

    Runtime.ShiftTransitionHoldCFrame = originCF
    Runtime.ShiftTransitionHoldActive = true
    Runtime.ShiftTransitionHoldStartedAt = os.clock()
    Runtime.ShiftTransitionShiftedAt = 0
    Runtime.ShiftTransitionStatus = "HOLDING • transformation"
    return true
end

local function shiftTransitionHoldStep()
    if Runtime.ShiftTransitionHoldActive ~= true then return false end

    local holdCF = Runtime.ShiftTransitionHoldCFrame
    if typeof(holdCF) ~= "CFrame" then
        clearShiftTransitionHold("Missing hold CFrame")
        return false
    end

    local now = os.clock()
    if now - (Runtime.ShiftTransitionHoldStartedAt or now) > 17.0 then
        clearShiftTransitionHold("Transition hold timeout")
        return false
    end

    local c = currentCharacter()
    local root = currentRoot()
    if not c or not root then
        Runtime.ShiftTransitionStatus = "HOLDING • character handoff"
        return false
    end

    -- CharacterAdded can happen a fraction before the Shifter attribute appears.
    -- Keep the same world position across BOTH characters, then give the finished
    -- Titan form a short settle window before normal Punching / Ability movement owns it.
    if isShifted() then
        if (Runtime.ShiftTransitionShiftedAt or 0) <= 0 then
            Runtime.ShiftTransitionShiftedAt = now
            Runtime.ShiftTransitionStatus = "HOLDING • Titan settle"
        elseif now - Runtime.ShiftTransitionShiftedAt >= 0.45 then
            clearShiftTransitionHold("Released • mastery owns movement")
            return false
        end
    else
        Runtime.ShiftTransitionStatus = "HOLDING • transformation"
    end

    local ok = pcall(function()
        c:PivotTo(holdCF)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    return ok
end

local function tryShift()
    profileRefresh(true)

    local serum = Runtime.Serum
    local shiftId = SHIFT_IDS[serum]
    if not shiftId then
        Runtime.MasteryStatus = "No supported equipped serum"
        return false
    end

    local count = readShiftCount()
    if count ~= nil and count <= 0 then
        Runtime.MasteryStatus = "No shifts remaining"
        return false
    end

    local now = os.clock()

    -- Once the server has accepted a Shift, DO NOT spam the action while the
    -- transformation animation is still building. The native trace showed the
    -- Shift counter changes immediately while Character/Shifter can arrive ~11s later.
    if (Runtime.ShiftAcceptedAt or 0) > 0 then
        if isShifted() then
            return true
        end

        local elapsed = now - Runtime.ShiftAcceptedAt
        if elapsed < 15.0 then
            Runtime.MasteryStatus =
                "SHIFT " .. tostring(serum)
                .. " • accepted • transforming " .. string.format("%.1fs", elapsed)
            return true
        end

        -- Accepted but never transformed: clear the latch and allow ONE fresh attempt.
        Runtime.ShiftAcceptedAt = 0
        Runtime.ShiftAcceptedCount = nil
        clearShiftTransitionHold("Accepted Shift timed out")
        Runtime.MasteryStatus = "SHIFT " .. tostring(serum) .. " • accepted but transform timed out"
    end

    if now - Runtime.LastShiftAttemptAt < 1.00 then return true end
    if Runtime.ShiftAttempts >= 3 then
        Runtime.MasteryStatus =
            "Shift failed • " .. tostring(Runtime.ShiftActorStatus or "no Actor acceptance")
        return false
    end

    Runtime.LastShiftAttemptAt = now
    Runtime.ShiftAttempts += 1
    local beforeCount = count
    Runtime.MasteryStatus =
        "SHIFT " .. tostring(serum) .. " • Actor native attempt " .. tostring(Runtime.ShiftAttempts)

    local shiftOriginCF = nil
    local shiftOriginCharacter = currentCharacter()
    if shiftOriginCharacter then
        pcall(function() shiftOriginCF = shiftOriginCharacter:GetPivot() end)
    end

    local hotbarSlot = slotForSkillId("999", Runtime.Hotbar)
    local nativeOk, nativeEvidence = tryGenericShiftHotbar(beforeCount, shiftId)

    if not nativeOk then
        Runtime.MasteryStatus =
            "SHIFT " .. tostring(serum) .. " • hotbar path missed • trying Actor native"
        nativeOk, nativeEvidence = tryActorNativeShift(shiftId, beforeCount, hotbarSlot)
    end

    if not nativeOk then
        -- V2's malformed raw fallback is intentionally gone. The exact Core.Skills
        -- contract either uses the generic 999 hotbar slot or executes inside the
        -- Actor runtime. A remote returning without Lua error is NOT success.
        Runtime.MasteryStatus =
            "SHIFT " .. tostring(serum) .. " • native failed • " .. tostring(nativeEvidence)
        return false
    end

    Runtime.ShiftAcceptedAt = os.clock()
    Runtime.ShiftAcceptedCount = readShiftCount()
    armShiftTransitionHold(shiftOriginCF)
    Runtime.ShiftActorStatus = "Accepted • " .. tostring(nativeEvidence)
    Runtime.MasteryStatus =
        "SHIFT " .. tostring(serum) .. " • accepted • " .. tostring(nativeEvidence)
    return true
end

local function titanMasteryGaugeStep()
    if isShifted() then return false end

    local ready, bar, maxBar, targetBar = barReady()
    if bar == nil then
        Runtime.MasteryStatus = "NO SHIFT GAUGE • farm paused"
        Runtime.PendingGauge = nil
        return true
    end

    local now = os.clock()
    if ready then
        Runtime.PendingGauge = nil
        return tryShift()
    end

    if Runtime.PendingGauge then
        local p = Runtime.PendingGauge
        local current = tonumber(LP:GetAttribute("Bar")) or bar
        local elapsed = now - p.at
        local targetGone = p.titan ~= nil and not titanAlive(p.titan)

        if current > p.before + 0.01 then
            Runtime.PendingGauge = nil
            Runtime.NextGaugeKillAt = now + 0.025
            Runtime.MasteryStatus =
                "Gauge " .. math.floor(current + 0.5) .. "/" .. math.floor(maxBar + 0.5)
                .. " • shift@" .. math.floor((targetBar or maxBar) + 0.5)
        elseif elapsed < 0.42 then
            Runtime.MasteryStatus =
                (targetGone and elapsed >= 0.12 and "Gauge confirm " or "Gauge ")
                .. math.floor(bar + 0.5) .. "/" .. math.floor(maxBar + 0.5)
                .. " • shift@" .. math.floor((targetBar or maxBar) + 0.5)
            return true
        else
            Runtime.PendingGauge = nil
            Runtime.NextGaugeKillAt = now + 0.04
            Runtime.MasteryStatus = "Gauge • next Titan"
            return true
        end
    end

    if now < (Runtime.NextGaugeKillAt or 0) then return true end

    local ok, reason = controlledGaugeHit(bar)
    if ok then
        Runtime.MasteryStatus =
            "Gauge " .. math.floor(bar + 0.5) .. "/" .. math.floor(maxBar + 0.5)
            .. " • shift@" .. math.floor((targetBar or maxBar) + 0.5)
    else
        Runtime.MasteryStatus = "Gauge • " .. tostring(reason)
        Runtime.NextGaugeKillAt = now + 0.05
    end
    return true
end

local function equippedShifterId(id)
    id = tostring(id or "")
    return id ~= "" and slotForSkillId(id, Runtime.Shifter) ~= nil
end

local function readResolvedToggleSkill()
    local serum = Runtime.Serum
    if not serum then return nil end

    local cached = Runtime.ToggleSkillIds[serum]
    if cached and equippedShifterId(cached) then
        cached = tostring(cached)
        if Runtime.SkillFirstPass[cached] then Runtime.ToggleLatched[cached] = true end
        return cached
    end

    local raw = tostring(LP:GetAttribute("__SHV6_ToggleSkill") or "")
    local foundSerum, foundId = string.match(raw, "^([^|]+)|([^|]+)")
    if foundSerum == serum and foundId and equippedShifterId(foundId) then
        foundId = tostring(foundId)
        Runtime.ToggleSkillIds[serum] = foundId
        if Runtime.SkillFirstPass[foundId] then Runtime.ToggleLatched[foundId] = true end
        Runtime.ToggleDiscoveryStatus = tostring(TOGGLE_DISPLAY[serum] or "Toggle") .. " • ID " .. foundId .. " • Actor"
        return foundId
    end

    local fallback = TOGGLE_FALLBACK[serum]
    if fallback and equippedShifterId(fallback) then
        fallback = tostring(fallback)
        Runtime.ToggleSkillIds[serum] = fallback
        if Runtime.SkillFirstPass[fallback] then Runtime.ToggleLatched[fallback] = true end
        Runtime.ToggleDiscoveryStatus = tostring(TOGGLE_DISPLAY[serum] or "Toggle") .. " • ID " .. fallback .. " • known"
        return fallback
    end

    return nil
end

