local function collectStrings(value, depth, out, seen)
    if depth > 3 then return end
    local kind = type(value)
    if kind == "string" then
        out[#out + 1] = value
        return
    end
    if kind ~= "table" or seen[value] then return end
    seen[value] = true
    local count = 0
    for k, v in pairs(value) do
        count += 1
        if count > 80 then break end
        if type(k) == "string" then out[#out + 1] = k end
        if type(v) == "string" or type(v) == "table" then
            collectStrings(v, depth + 1, out, seen)
        end
    end
end

local function containsNeedle(value)
    local words = {}
    collectStrings(value, 0, words, {})
    local text = string.lower(table.concat(words, " "))
    for _, needle in ipairs(needles) do
        if string.find(text, needle, 1, true) then return true end
    end
    return false
end

