local function toggleSkillId()
    local id = readResolvedToggleSkill()
    if id then return id end
    requestActorToggleDiscovery()
    return readResolvedToggleSkill()
end

local function resetToggleState(reason)
    Runtime.ToggleLatched = {}
    Runtime.SkillFirstPass = {}
    Runtime.ToggleSkillIds = {}
    Runtime.ToggleDiscoveryAt = 0
    Runtime.ToggleDiscoverySerum = nil
    Runtime.ToggleDiscoveryStatus = reason or "Idle"
end

local function activeShifterSlots()
    profileRefresh(false)

    local blocked = {
        ["200"] = true, ["300"] = true, ["400"] = true, ["500"] = true,
        ["999"] = true, ["998"] = true, ["997"] = true, ["996"] = true,
        ["301"] = true, -- intentionally disabled: target-grab/throw flow is unreliable for automation
    }

    local out = {}
    for slot = 1, 5 do
        local id = skillIdForSlot(slot, true)
        if id and id ~= "" and not blocked[id] then
            out[#out + 1] = {slot = slot, id = id}
        end
    end
    return out
end

local function entryForTitan(titan)
    local root = currentRoot()
    if not root or not titanAlive(titan) then return nil end
    local nape = exactNape(titan)
    if not nape then return nil end
    return {
        Titan = titan,
        Nape = nape,
        Distance = (nape.Position - root.Position).Magnitude,
    }
end

local function shifterTargetPair(preferredPrimary)
    local primary = preferredPrimary
    if primary and (not primary.Titan or not titanAlive(primary.Titan) or not primary.Nape or not primary.Nape.Parent) then
        primary = nil
    end

    local entries = detectedTitans(3)
    if not primary then primary = entries[1] end

    local secondary = nil
    if primary and primary.Titan then
        for _, entry in ipairs(entries) do
            if entry.Titan ~= primary.Titan then
                secondary = entry
                break
            end
        end
    else
        secondary = entries[2]
    end
    return primary, secondary
end

local function combinedTargetEntry()
    local locked = entryForTitan(Runtime.CombinedTarget)
    if locked then
        Runtime.CombinedStatus = "LOCKED • " .. tostring(locked.Titan.Name)
        return locked
    end

    local fresh = detectedTitans(1)[1]
    Runtime.CombinedTarget = fresh and fresh.Titan or nil
    Runtime.CombinedStatus = fresh and ("NEW LOCK • " .. tostring(fresh.Titan.Name)) or "Scanning"
    return fresh
end

local function shifterSkillStep(preferredPrimary)
    if Runtime.ShifterAbilityBusy then
        Runtime.MasteryStatus = "Skill Mastery • ability phase in progress"
        return false
    end

    local primary, secondary = shifterTargetPair(preferredPrimary)
    if not primary then
        Runtime.MasteryStatus = "Skill Mastery • scanning Titans"
        return false
    end

    -- In pure Skill Usage mode keep the V4/V5 hold continuously. In combined
    -- mode do NOT pre-hover while waiting on cooldowns, or it would fight the
    -- close-range punching position every 0.025s. The hold is applied below only
    -- when an ability is actually about to cast.
    if Settings.TitanMode == "Skill Usage" then skillUsageHoverHold(primary) end
    local skills = activeShifterSlots()
    if #skills == 0 then
        Runtime.MasteryStatus = "Skill Mastery • no equipped Shifter skills"
        return false
    end

    local toggleId = toggleSkillId()
    local chosen
    local chosenIsToggle = false

    -- Toggle skill always gets first priority once per transformation. Once its
    -- cast is accepted it is latched and excluded forever until CharacterAdded.
    if toggleId and not Runtime.ToggleLatched[toggleId] then
        for _, item in ipairs(skills) do
            if item.id == toggleId and skillReady(item.slot) then
                chosen = item
                chosenIsToggle = true
                break
            end
        end
    end

    if not chosen and Runtime.Serum == "Colossal" then
        -- Incendiary Volley / ground sweep (506) is one of the strongest pack
        -- clearers. Fire it first whenever it is ready, then round-robin the rest.
        for _, item in ipairs(skills) do
            if item.id == "506"
                and os.clock() >= ((Runtime.ColossalSkillGuard or {})[item.slot] or 0)
                and skillReady(item.slot) then
                chosen = item
                break
            end
        end
    end

    if not chosen then
        local startCursor = Runtime.SkillCursor
        if startCursor < 1 or startCursor > #skills then startCursor = 1 end

        for offset = 0, #skills - 1 do
            local idx = ((startCursor - 1 + offset) % #skills) + 1
            local item = skills[idx]
            local isToggle = toggleId ~= nil and item.id == toggleId
            local safeFirstPassBlocked = Runtime.Serum == "Armored"
                and toggleId == nil
                and Runtime.SkillFirstPass[item.id] == true

            local colossalGuarded = Runtime.Serum == "Colossal"
                and os.clock() < ((Runtime.ColossalSkillGuard or {})[item.slot] or 0)

            if not isToggle and not safeFirstPassBlocked and not colossalGuarded and skillReady(item.slot) then
                chosen = item
                Runtime.SkillCursor = idx % #skills + 1
                break
            end
        end
    end

    if not chosen then
        if Runtime.Serum == "Armored" and toggleId == nil then
            Runtime.MasteryStatus = "Skill Mastery • Armored safe hold • resolving Unstoppable Charge"
        else
            Runtime.MasteryStatus = "Skill Mastery • live cooldowns"
        end
        return false
    end

    -- Armored 301 and all form-specific Eject actions (including Colossal 500)
    -- are intentionally excluded in activeShifterSlots().
    -- V6.1 pins this exact primary for the whole cast so the independent hover
    -- worker cannot jump to a different nearby Titan mid-animation.
    Runtime.SkillHoverTarget = primary.Titan
    if Runtime.Serum == "Colossal" then
        colossalSafeGroundStep(primary)
    end
    skillUsageHoverHold(primary)
    aimAtEntry(primary, true)
    local timeout = Runtime.Serum == "Colossal" and 0.40 or 1.05

    Runtime.ShifterAbilityBusy = true
    local unresolvedArmoredFirstPass = Runtime.Serum == "Armored" and toggleId == nil
    local ok, err
    if Runtime.Serum == "Colossal" and not chosenIsToggle then
        ok, err = colossalFastDispatchSkillSlot(chosen.slot, chosen.id)
    elseif chosenIsToggle or unresolvedArmoredFirstPass then
        ok, err = singleDispatchSkillSlot(chosen.slot, chosen.id, timeout)
    else
        ok, err = trackedUseSkillSlot(chosen.slot, 2, timeout)
    end
    Runtime.ShifterAbilityBusy = false
    if ok then
        Runtime.NextPunchAt = math.max(Runtime.NextPunchAt or 0, os.clock() + 0.18)
        if Settings.TitanMode == "Punching & Abilities" then
            -- V6.7: after a cast, guarantee a short punching window before the
            -- next ability probe. This prevents rapid skill/punch phase thrash.
            Runtime.CombinedPunchOnlyUntil = os.clock() + 0.55
        end
    end
    skillUsageHoverHold(primary)
    if Settings.TitanMode == "Punching & Abilities" then
        Runtime.SkillHoverTarget = nil
    end

    if ok then
        Runtime.SkillFirstPass[chosen.id] = true
        if chosenIsToggle then
            Runtime.ToggleLatched[chosen.id] = true
            Runtime.ToggleDiscoveryStatus = tostring(TOGGLE_DISPLAY[Runtime.Serum] or SHIFTER_SKILL_NAMES[chosen.id] or "Toggle")
                .. " • ON • ID " .. tostring(chosen.id) .. " • locked"
        end
    end

    local skillName = SHIFTER_SKILL_NAMES[tostring(chosen.id)]
    Runtime.MasteryStatus = ok
        and ("Skill Mastery • " .. tostring(Runtime.Serum or "?")
            .. " • slot " .. tostring(chosen.slot) .. " • ID " .. tostring(chosen.id)
            .. (skillName and (" • " .. skillName) or "")
            .. (chosenIsToggle and " • LATCHED ON" or "")
            .. " • CD " .. tostring(cooldownValue(chosen.slot) or "started"))
        or ("Skill call failed • " .. tostring(err))
    return ok
end

local function punchingStep(preferredPrimary)
    if Runtime.ShifterAbilityBusy or os.clock() < (Runtime.NextPunchAt or 0) then
        return false
    end

    local multi = math.clamp(math.floor(tonumber(Settings.MultiHit) or 4), 3, 5)
    Settings.MultiHit = multi
    local entries = detectedTitans(multi + 1)

    -- V6.7 combined mode uses one shared Titan lock for BOTH punching and
    -- abilities. Keep that target first instead of re-sorting after every TP.
    if preferredPrimary and preferredPrimary.Titan and titanAlive(preferredPrimary.Titan)
        and preferredPrimary.Nape and preferredPrimary.Nape.Parent then
        local ordered = {preferredPrimary}
        for _, entry in ipairs(entries) do
            if entry.Titan ~= preferredPrimary.Titan and #ordered < multi then
                ordered[#ordered + 1] = entry
            end
        end
        entries = ordered
    elseif #entries > multi then
        while #entries > multi do table.remove(entries) end
    end

    if #entries == 0 then
        Runtime.MasteryStatus = "Punching Mastery • scanning Titans"
        return false
    end

    -- Only reposition when a punch is actually due. In older combined mode this
    -- PivotTo happened every 0.025s even during the punch cooldown, which made
    -- the skill/punch hand-off visually unstable on dense packs.
    if os.clock() - Runtime.LastPunchAt < 0.48 then return false end
    pivotNear(entries[1], 0.18)
    Runtime.LastPunchAt = os.clock()

    post("Attacks", "Slash", true)
    task.wait(0.02)

    local hits = 0
    for _, entry in ipairs(entries) do
        if entry.Nape and entry.Nape.Parent then
            local ok = post("Hitboxes", "Register", entry.Nape, nil, nil, math.random(1, 4))
            if ok then hits += 1 end
            task.wait(0.01)
        end
    end

    Runtime.MasteryStatus =
        "Punching Mastery • " .. tostring(Runtime.Serum or "?")
        .. " • " .. tostring(hits) .. "/" .. tostring(multi) .. " target(s)"
    return hits > 0
end

local function titanMasteryStep()
    if not Settings.AutoTitanMastery then
        Runtime.MasteryStatus = "Off"
        Runtime.PendingGauge = nil
        Runtime.GaugeWeaponStatus = "Idle"
        Runtime.SpearRefillPending = false
        Runtime.NextCombinedAbilityAt = 0
        Runtime.CombinedTarget = nil
        Runtime.CombinedPunchOnlyUntil = 0
        Runtime.CombinedStatus = "Idle"
        Runtime.ShiftAttempts = 0
        Runtime.ShiftAcceptedAt = 0
        Runtime.ShiftAcceptedCount = nil
        Runtime.ShiftActorStatus = "Idle"
        clearShiftTransitionHold("Idle")
        Runtime.SkillHoverTarget = nil
        Runtime.SkillHoverLastCFrame = nil
        Runtime.SkillHoverStatus = "Idle"
        return
    end

    profileRefresh(false)

    local h = currentHumanoid()
    if not h or h.Health <= 0 then
        Runtime.MasteryStatus = "Waiting for character"
        return
    end

    if not isShifted() then
        Runtime.SkillHoverTarget = nil
        Runtime.SkillHoverLastCFrame = nil
        Runtime.SkillHoverStatus = "Human"
        Runtime.CombinedTarget = nil
        Runtime.CombinedPunchOnlyUntil = 0
        Runtime.CombinedStatus = "Human"
        titanMasteryGaugeStep()
        return
    end

    Runtime.ShiftAttempts = 0
    Runtime.ShiftAcceptedAt = 0
    Runtime.ShiftAcceptedCount = nil

    if Runtime.Serum == "Colossal" then
        colossalSafeGroundStep(nil)
        Runtime.MasteryStatus = "Colossal • SKILLS ONLY • " .. tostring(Runtime.ColossalSafeAnchorStatus or "planted")
        shifterSkillStep()
        return
    end

    if Settings.TitanMode == "Skill Usage" then
        shifterSkillStep()
    elseif Settings.TitanMode == "Punching & Abilities" then
        -- V6.7 stable combined controller: one target owns both phases until it
        -- dies. No nearest-target reshuffle between a punch and an ability.
        local target = combinedTargetEntry()
        if not target then
            Runtime.MasteryStatus = "Combined • scanning Titans"
            return
        end

        local now = os.clock()
        if now >= (Runtime.CombinedPunchOnlyUntil or 0)
            and now >= (Runtime.NextCombinedAbilityAt or 0) then
            Runtime.NextCombinedAbilityAt = now + 0.28
            local casted = shifterSkillStep(target)
            if casted then
                Runtime.NextCombinedAbilityAt = os.clock() + 0.45
                return
            end
        end
        punchingStep(target)
    else
        Runtime.SkillHoverTarget = nil
        Runtime.SkillHoverLastCFrame = nil
        Runtime.SkillHoverStatus = "Punching mode"
        punchingStep()
    end
end


    local function syncSettings()
        Settings.AutoTitanMastery = App.Values.AutoTitanMastery == true
        local mode = tostring(App.Values.TitanMasteryMode or "Punching")
        if mode ~= "Punching" and mode ~= "Skill Usage" and mode ~= "Punching & Abilities" then
            mode = "Punching"
        end
        Settings.TitanMode = mode
        Settings.MultiHit = math.clamp(math.floor(tonumber(App.Values.TitanMasteryMultiHit) or 4), 3, 5)
        App.Values.TitanMasteryMultiHit = Settings.MultiHit
    end

    App.TitanMastery.RuntimeV67 = Runtime
    App.TitanMastery.ReadBar = function()
        local bar = readBar()
        return bar
    end
    App.TitanMastery.IsShifted = isShifted
    App.TitanMastery.ShiftText = function()
        local count = readShiftCount()
        return count ~= nil and tostring(count) or "Unknown"
    end
    App.TitanMastery.GaugeWeaponText = function()
        return tostring(Runtime.GaugeWeaponStatus or "Detecting")
    end
    App.TitanMastery.ColossalAnchorText = function()
        return tostring(Runtime.ColossalSafeAnchorStatus or "Idle")
    end
    App.TitanMastery.ToggleText = function()
        return tostring(Runtime.ToggleDiscoveryStatus or "Idle")
    end

    App.TitanMastery.Step = function()
        syncSettings()

        if Settings.AutoTitanMastery ~= true or RuntimeKind ~= "Gameplay" then
            titanMasteryStep()
            App.TitanMastery.Status = "Off"
            return false
        end

        if App.Cutscene and App.Cutscene.Active == true then
            App.TitanMastery.Status = "Cutscene • Titan Mastery suspended"
            return true
        end
        if App.RaidChestAuto and App.RaidChestAuto.Busy then
            App.TitanMastery.Status = "Raid chests • Titan Mastery suspended"
            return true
        end
        if App.Colossal and App.Colossal.OwnsCombat and App.Colossal.OwnsCombat() then
            App.TitanMastery.Status = "Colossal raid controller owns combat"
            return false
        end

        local ok, err = pcall(titanMasteryStep)
        if not ok then
            Runtime.MasteryStatus = "ERR • " .. tostring(err)
        end
        App.TitanMastery.Status = tostring(Runtime.MasteryStatus or "Ready")
        return true
    end

    -- Ability casts can block Step() while cooldown acceptance is checked. Keep
    -- the V6.7 nape hold independent so normal forms do not drop/360 mid-cast.
    task.spawn(function()
        while Runtime.Alive and gui and gui.Parent do
            syncSettings()
            if Runtime.ShiftTransitionHoldActive == true then
                pcall(shiftTransitionHoldStep)
                task.wait(0.02)
            else
                task.wait(0.08)
            end
        end
        Runtime.Alive = false
    end)

    task.spawn(function()
        while Runtime.Alive and gui and gui.Parent do
            syncSettings()
            local skillMode = Settings.TitanMode == "Skill Usage"
                or (Settings.TitanMode == "Punching & Abilities" and Runtime.ShifterAbilityBusy == true)
            if Settings.AutoTitanMastery == true and skillMode and isShifted() then
                pcall(skillUsageHoverHold)
                task.wait(0.02)
            else
                task.wait(0.08)
            end
        end
    end)

    LP.CharacterAdded:Connect(function()
        local acceptedShiftPending = (Runtime.ShiftAcceptedAt or 0) > 0
        Runtime.PendingGauge = nil
        Runtime.NextGaugeKillAt = 0
        Runtime.SpearRefillPending = false
        Runtime.CombinedTarget = nil
        Runtime.CombinedPunchOnlyUntil = 0
        Runtime.CombinedStatus = "Character reset"
        Runtime.NextCombinedAbilityAt = 0
        Runtime.ColossalSkillGuard = {}
        Runtime.NextColossalSkillAt = 0
        Runtime.ShiftAttempts = acceptedShiftPending and Runtime.ShiftAttempts or 0
        if acceptedShiftPending then
            Runtime.ShiftActorStatus = "Accepted • character transition"
            if Runtime.ShiftTransitionHoldActive == true then
                Runtime.ShiftTransitionStatus = "HOLDING • character handoff"
            end
        else
            Runtime.ShiftAcceptedAt = 0
            Runtime.ShiftAcceptedCount = nil
            Runtime.ShiftActorStatus = "Idle"
            clearShiftTransitionHold("Character transition")
        end
        Runtime.ShiftActorDispatchAt = 0
        Runtime.ShifterAbilityBusy = false
        Runtime.NextPunchAt = 0
        resetToggleState("Character transition")
        Runtime.SkillHoverTarget = nil
        Runtime.SkillHoverLastCFrame = nil
        Runtime.SkillHoverStatus = "Character transition"
        Runtime.SkillCursor = 1
        Runtime.LastProfileAt = 0
        task.delay(1, function()
            if Runtime.Alive then pcall(profileRefresh, true) end
        end)
    end)

    pcall(profileRefresh, true)
end)()


