;(function()
    local C = App.Colossal
    local CFG = C.Config

    local function lower(value)
        return string.lower(tostring(value or ""))
    end

    local function cleanText(value)
        local textValue = lower(value)
        textValue = string.gsub(textValue, "<.->", "")
        textValue = string.gsub(textValue, "[_%-]+", " ")
        textValue = string.gsub(textValue, "%s+", " ")
        return textValue
    end

    local function remotes()
        return spearRemotes()
    end

    local function currentMode()
        if App.Values.AutoFarmBlades == true
            and bladeEquipped() then
            return "Blades"
        end

        if App.Values.AutoFarmSpears == true
            and spearEquipped() then
            return "Spears"
        end

        if App.Values.AutoFarmBlades == true then
            return "Blades"
        end

        if App.Values.AutoFarmSpears == true then
            return "Spears"
        end

        return "None"
    end

    local function canRun()
        return RuntimeKind == "Gameplay"
            and App.FamilySpin
            and App.FamilySpin.IsPremium
            and App.FamilySpin.IsPremium() == true
            and App.Values.ColossalRemastered == true
            and (
                App.Values.AutoFarmBlades == true
                or App.Values.AutoFarmSpears == true
            )
    end

    local function colossalLowPower()
        return App.PerformanceControl
            and App.PerformanceControl.IsLowPower
            and App.PerformanceControl.IsLowPower() == true
    end

    local function directObjectiveState()
        local bestMain = ""
        local bestEren = ""
        local defendObject = nil

        local function considerText(value)
            local textValue = cleanText(value)
            if textValue == "" then return end

            local subject =
                string.find(textValue, "bertholdt", 1, true)
                or string.find(textValue, "bertolt", 1, true)
                or string.find(textValue, "colossal", 1, true)

            local action =
                string.find(textValue, "stall", 1, true)
                or string.find(textValue, "defeat", 1, true)
                or string.find(textValue, "kill", 1, true)
                or string.find(textValue, "slay", 1, true)
                or string.find(textValue, "phase 2", 1, true)
                or string.find(textValue, "p2", 1, true)

            if subject and action and #textValue > #bestMain then
                bestMain = textValue
            end

            if (
                string.find(textValue, "defend eren", 1, true)
                or string.find(textValue, "defend_eren", 1, true)
                or string.find(textValue, "protect eren", 1, true)
                or string.find(textValue, "protect_eren", 1, true)
            ) and #textValue > #bestEren then
                bestEren = textValue
            end
        end

        for _, key in ipairs({
            "Objective",
            "MissionObjective",
            "Mission_Objective",
            "RaidObjective",
        }) do
            considerText(workspace:GetAttribute(key))
        end

        local roots = {}
        local rsObjectives = ReplicatedStorage:FindFirstChild("Objectives")
        if rsObjectives then roots[#roots + 1] = rsObjectives end

        local unclimbable = workspace:FindFirstChild("Unclimbable")
        local wsObjectives = unclimbable and unclimbable:FindFirstChild("Objective")
        if wsObjectives then roots[#roots + 1] = wsObjectives end

        local function considerObject(object)
            if not object then return end
            local name = tostring(object.Name or "")
            considerText(name)

            if object:IsA("StringValue") then
                considerText(object.Value)
            end

            local nameLower = cleanText(name)
            if not defendObject and (
                nameLower == "defend_eren"
                or nameLower == "defend eren"
                or nameLower == "protect_eren"
                or nameLower == "protect eren"
                or (
                    string.find(nameLower, "eren", 1, true)
                    and (
                        string.find(nameLower, "defend", 1, true)
                        or string.find(nameLower, "protect", 1, true)
                    )
                )
            ) then
                defendObject = object
                if bestEren == "" then bestEren = nameLower end
            end
        end

        for _, root in ipairs(roots) do
            considerObject(root)
            local checked = 0
            for _, object in ipairs(root:GetDescendants()) do
                checked += 1
                if checked > 700 then break end
                considerObject(object)
            end
        end

        return bestMain, bestEren, defendObject
    end

    local function refreshObjectiveCache(force)
        local now = os.clock()

        if not force
            and now - (tonumber(C.ObjectiveCacheAt) or 0)
                < CFG.ObjectiveScanInterval then
            return
        end

        C.ObjectiveCacheAt = now

        -- Prefer authoritative replicated/world objective state. GUI text is only
        -- a compatibility fallback for layouts that do not expose objective objects.
        local bestMain, bestEren, defendObject = directObjectiveState()
        C.ErenObjectiveObject = defendObject

        if bestMain == "" or bestEren == "" then
            local interface = playerGui:FindFirstChild("Interface") or playerGui
            local checked = 0

            for _, object in ipairs(interface:GetDescendants()) do
                if object:IsA("TextLabel")
                    or object:IsA("TextButton")
                    or object:IsA("TextBox") then

                    checked += 1
                    if checked > 520 then break end

                    local visible = true
                    pcall(function() visible = object.Visible end)

                    if visible then
                        local textValue = cleanText(object.Text or "")
                        if textValue ~= "" then
                            if bestMain == "" then
                                local subject =
                                    string.find(textValue, "bertholdt", 1, true)
                                    or string.find(textValue, "bertolt", 1, true)
                                    or string.find(textValue, "colossal", 1, true)
                                local action =
                                    string.find(textValue, "stall", 1, true)
                                    or string.find(textValue, "defeat", 1, true)
                                    or string.find(textValue, "kill", 1, true)
                                    or string.find(textValue, "slay", 1, true)
                                    or string.find(textValue, "phase 2", 1, true)
                                    or string.find(textValue, "p2", 1, true)
                                if subject and action then bestMain = textValue end
                            end

                            if bestEren == "" and (
                                string.find(textValue, "defend eren", 1, true)
                                or string.find(textValue, "protect eren", 1, true)
                            ) then
                                bestEren = textValue
                            end
                        end
                    end
                end
            end
        end

        C.ObjectiveCacheText = bestMain
        C.ErenObjectiveCacheText = bestEren
    end

    local function visibleObjectiveText()
        refreshObjectiveCache(false)
        return tostring(C.ObjectiveCacheText or "")
    end

    local function erenObjectiveText()
        refreshObjectiveCache(false)
        return tostring(C.ErenObjectiveCacheText or "")
    end

    local function p2Complete()
        local textValue = visibleObjectiveText()

        return string.match(
            textValue,
            "defeat bertholdt%s*%[1%s*/%s*1%]"
        ) ~= nil
            or string.match(
                textValue,
                "defeat bertolt%s*%[1%s*/%s*1%]"
            ) ~= nil
            or string.match(
                textValue,
                "defeat colossal[^%[]*%[1%s*/%s*1%]"
            ) ~= nil
    end

    local function computeStage()
        local textValue = visibleObjectiveText()

        local explicitP2 =
            string.find(textValue, "defeat bertholdt", 1, true)
            or string.find(textValue, "kill bertholdt", 1, true)
            or string.find(textValue, "slay bertholdt", 1, true)
            or string.find(textValue, "defeat bertolt", 1, true)
            or string.find(textValue, "kill bertolt", 1, true)
            or string.find(textValue, "slay bertolt", 1, true)
            or string.find(textValue, "defeat colossal", 1, true)
            or string.find(textValue, "kill colossal", 1, true)
            or string.find(textValue, "slay colossal", 1, true)
            or string.find(textValue, "phase 2", 1, true)
            or string.find(textValue, "p2", 1, true)

        if explicitP2 then
            C.P2Confirmed = true
        end

        if C.P2Confirmed then
            return "P2 BOSS"
        end


        return "P1 CANNON STALL"
    end

    local function modelAlive(model)
        if not model or not model.Parent then
            return false
        end

        local humanoid =
            model:FindFirstChildOfClass("Humanoid")

        if humanoid then
            return humanoid.Health > 0
        end

        return true
    end

    local function looksColossal(model)
        if not model or not model:IsA("Model") then
            return false
        end

        local name = lower(model.Name)

        return string.find(name, "bertholdt", 1, true) ~= nil
            or string.find(name, "bertolt", 1, true) ~= nil
            or string.find(name, "colossal", 1, true) ~= nil
    end

    local function findBoss(force)
        local now = os.clock()

        if not force
            and C.CachedBoss
            and C.CachedBoss.Parent
            and modelAlive(C.CachedBoss)
            and now - (tonumber(C.LastBossScanAt) or 0)
                < CFG.BossScanInterval then
            C.LastBossSeenAt = now
            return C.CachedBoss
        end

        if not force
            and now - (tonumber(C.LastBossScanAt) or 0)
                < CFG.BossScanInterval then
            return C.CachedBoss
        end

        C.LastBossScanAt = now

        local folder = workspace:FindFirstChild("Titans")
        local best, bestScore = nil, -math.huge

        local function consider(object)
            if not object
                or not object:IsA("Model")
                or not looksColossal(object)
                or not modelAlive(object) then
                return
            end

            local score = 0
            local name = lower(object.Name)

            if string.find(name, "bertholdt", 1, true) then
                score += 5
            end

            if string.find(name, "bertolt", 1, true) then
                score += 5
            end

            if string.find(name, "colossal", 1, true) then
                score += 4
            end

            if object:FindFirstChild("Hitboxes") then
                score += 10
            end

            if score > bestScore then
                best = object
                bestScore = score
            end
        end

        -- Normal AOT:R layout keeps Titans as direct children. Prefer that cheap
        -- scan and only fall back to descendants if the layout changes.
        if folder then
            for _, object in ipairs(folder:GetChildren()) do
                consider(object)
            end

            if not best then
                local checked = 0
                for _, object in ipairs(folder:GetDescendants()) do
                    checked += 1
                    if checked > 2500 then break end
                    if object:IsA("Model") then
                        consider(object)
                    end
                end
            end
        else
            for _, object in ipairs(workspace:GetChildren()) do
                consider(object)
            end
        end

        C.CachedBoss = best
        C.Boss = best
        C.Nape = best and bladeExactNape(best) or nil

        if best then
            C.LastBossSeenAt = now
            C.LastBossMissingAt = 0
        elseif (tonumber(C.LastBossMissingAt) or 0) <= 0 then
            C.LastBossMissingAt = now
        end

        return best
    end

    local function objectPosition(object)
        if not object then return nil end

        if object:IsA("BasePart") then
            return object.Position
        end

        if object:IsA("Attachment") then
            return object.WorldPosition
        end

        if object:IsA("Model") then
            local ok, cf = pcall(function()
                return object:GetPivot()
            end)

            if ok then
                return cf.Position
            end
        end

        local part =
            object:FindFirstChildWhichIsA("BasePart", true)

        return part and part.Position or nil
    end

    local function resolveErenAnchor(force)
        local now = os.clock()

        if not force
            and typeof(C.ErenAnchor) == "Vector3"
            and now - (tonumber(C.ErenAnchorAt) or 0)
                < CFG.ErenAnchorTTL then
            return C.ErenAnchor
        end

        if not force
            and typeof(C.ErenAnchor) ~= "Vector3"
            and now - (tonumber(C.ErenAnchorAt) or 0)
                < CFG.ErenMissRetry then
            return nil
        end

        refreshObjectiveCache(force == true)

        local titans = workspace:FindFirstChild("Titans")
        local bestPosition = nil
        local bestScore = -math.huge

        local function consider(object, baseScore)
            if not object
                or (
                    titans
                    and object:IsDescendantOf(titans)
                ) then
                return
            end

            local position = objectPosition(object)
            if position and baseScore > bestScore then
                bestScore = baseScore
                bestPosition = position
            end
        end

        -- Highest-confidence anchor: the actual live Defend_Eren objective object.
        if C.ErenObjectiveObject and C.ErenObjectiveObject.Parent then
            consider(C.ErenObjectiveObject, 20000)
        end

        local unclimbable = workspace:FindFirstChild("Unclimbable")
        local objectiveRoot = unclimbable and unclimbable:FindFirstChild("Objective")
        if objectiveRoot then
            consider(objectiveRoot:FindFirstChild("Defend_Eren"), 19500)
            consider(objectiveRoot:FindFirstChild("Defend Eren"), 19400)
        end

        -- Compatibility fallbacks for older layouts.
        local exactEren = workspace:FindFirstChild("Eren", true)
        local exactBoulder = workspace:FindFirstChild("Boulder", true)
        consider(exactEren, 10000)
        consider(exactBoulder, 8500)

        if not bestPosition
            and (
                force
                or now - (tonumber(C.ErenFallbackScanAt) or 0)
                    >= CFG.ErenFallbackScanInterval
            ) then

            C.ErenFallbackScanAt = now
            local checked = 0

            for _, object in ipairs(workspace:GetDescendants()) do
                checked += 1
                if checked > CFG.ErenFallbackScanLimit then break end

                if (
                    object:IsA("Model")
                    or object:IsA("BasePart")
                    or object:IsA("Attachment")
                )
                    and not (
                        titans
                        and object:IsDescendantOf(titans)
                    ) then

                    local name = lower(object.Name)
                    local score = 0
                    if name == "defend_eren" or name == "defend eren" then
                        score = 19000
                    elseif name == "eren" then
                        score = 10000
                    elseif string.find(name, "eren", 1, true) then
                        score = 7000
                    elseif name == "boulder" then
                        score = 8500
                    elseif string.find(name, "boulder", 1, true) then
                        score = 5000
                    end

                    if score > 0 then consider(object, score) end
                end
            end
        end

        C.ErenAnchor = bestPosition
        C.ErenAnchorAt = now
        return bestPosition
    end

    local function readErenHealth()
        refreshObjectiveCache(false)

        local percent = nil
        local objective = C.ErenObjectiveObject

        if objective and objective.Parent then
            local humanoid = objective:IsA("Model") and objective:FindFirstChildOfClass("Humanoid")
                or objective:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.MaxHealth > 0 then
                percent = math.clamp((humanoid.Health / humanoid.MaxHealth) * 100, 0, 100)
            end

            if percent == nil then
                local current = nil
                local maximum = nil
                for _, key in ipairs({"Health", "CurrentHealth", "HP", "Current", "Progress"}) do
                    current = current or tonumber(objective:GetAttribute(key))
                end
                for _, key in ipairs({"MaxHealth", "MaximumHealth", "MaxHP", "Required", "Requirement", "Goal", "Max"}) do
                    maximum = maximum or tonumber(objective:GetAttribute(key))
                end
                if current and maximum and maximum > 0 then
                    percent = math.clamp((current / maximum) * 100, 0, 100)
                end
            end
        end

        if percent == nil then
            local textValue = erenObjectiveText()
            percent = tonumber(
                string.match(textValue, "defend eren%s*%[([%d%.]+)%%%]")
                or string.match(textValue, "protect eren%s*%[([%d%.]+)%%%]")
            )
        end

        local previous = tonumber(C.LastErenHealthPercent)
        if percent ~= nil
            and previous ~= nil
            and percent < previous - 0.05 then
            C.ErenDamagedUntil = os.clock() + 8.0
        end

        if percent ~= nil then C.LastErenHealthPercent = percent end
        C.ErenHealthPercent = percent
        return percent
    end

    local function collectThreats(force)
        local now = os.clock()

        if not force
            and now - (tonumber(C.LastThreatScanAt) or 0)
                < CFG.ThreatScanInterval then
            return C.LastThreatEntries or {}
        end

        C.LastThreatScanAt = now
        readErenHealth()

        local anchor = resolveErenAnchor(force == true)
        local folder = workspace:FindFirstChild("Titans")
        local boss = findBoss(false)
        local entries = {}

        local erenHealth = tonumber(C.ErenHealthPercent)
        local erenObjectiveActive = erenObjectiveText() ~= ""
        local erenEmergency = erenObjectiveActive
            and (
                (erenHealth ~= nil and erenHealth <= CFG.ErenEmergencyHealthPercent)
                or os.clock() < (tonumber(C.ErenDamagedUntil) or 0)
            )

        local radius = erenEmergency
            and CFG.ErenEmergencyThreatRadius
            or (C.Stage == "P2 BOSS" and CFG.P2ThreatRadius or CFG.P1ThreatRadius)

        local criticalRadius = erenEmergency
            and CFG.ErenEmergencyCriticalRadius
            or (C.Stage == "P2 BOSS" and CFG.P2CriticalRadius or CFG.P1CriticalRadius)

        if folder and typeof(anchor) == "Vector3" then
            local r2 = radius * radius
            local c2 = criticalRadius * criticalRadius

            for _, titan in ipairs(folder:GetChildren()) do
                if titan ~= boss
                    and modelAlive(titan)
                    and not looksColossal(titan) then

                    local nape = bladeExactNape(titan)

                    if nape then
                        local delta =
                            nape.Position - anchor
                        local d2 = delta:Dot(delta)

                        if d2 <= r2 then
                            entries[#entries + 1] = {
                                Titan = titan,
                                Part = nape,
                                DistanceSquared = d2,
                                Critical = d2 <= c2,
                            }
                        end
                    end
                end
            end
        end

        table.sort(entries, function(a, b)
            if a.Critical ~= b.Critical then
                return a.Critical == true
            end

            return
                (tonumber(a.DistanceSquared) or math.huge)
                < (tonumber(b.DistanceSquared) or math.huge)
        end)

        local critical = 0

        for _, entry in ipairs(entries) do
            if entry.Critical then
                critical += 1
            end
        end

        C.ThreatCount = #entries
        C.CriticalThreatCount = critical
        C.LastThreatEntries = entries
        return entries
    end

    local function cannonPosition(cannon)
        if not cannon then return nil end

        local base = cannon:FindFirstChild("Base", true)

        if base and base:IsA("BasePart") then
            return base.Position
        end

        local ok, cf = pcall(function()
            return cannon:GetPivot()
        end)

        return ok and cf.Position or nil
    end

    local function cannonValid(cannon)
        if not cannon or not cannon.Parent then
            return false
        end

        if not CollectionService:HasTag(cannon, "Cannon") then
            return false
        end

        if cannon:GetAttribute("Setup") ~= true then
            return false
        end

        local owner = cannon:GetAttribute("Player")

        return owner == nil or owner == player.Name
    end

    local function invokeCannon(action, ...)
        local get = select(1, remotes())

        if not get or not get:IsA("RemoteFunction") then
            return false, nil, "GET missing"
        end

        local args = table.pack(...)

        local ok, result = pcall(function()
            return get:InvokeServer(
                "Cannon",
                action,
                table.unpack(args, 1, args.n)
            )
        end)

        return ok,
            ok and result or nil,
            ok and nil or tostring(result)
    end

    local function acquireCannon()
        if cannonValid(C.Cannon) then
            return C.Cannon
        end

        C.Cannon = nil
        C.Entered = false

        local root = spearRoot()
        local origin = root and root.Position or Vector3.zero
        local best, bestDistance = nil, math.huge

        for _, cannon in ipairs(
            CollectionService:GetTagged("Cannon")
        ) do
            if cannonValid(cannon) then
                local position = cannonPosition(cannon)
                local distance =
                    position
                    and (position - origin).Magnitude
                    or math.huge

                if distance < bestDistance then
                    best = cannon
                    bestDistance = distance
                end
            end
        end

        C.Cannon = best
        return best
    end

    local function readAngles(cannon)
        cannon = cannon or C.Cannon

        return {
            Base =
                cannon
                and tonumber(cannon:GetAttribute("Base"))
                or tonumber(C.Angles.Base)
                or CFG.FixedBase,

            BarrelWood =
                cannon
                and tonumber(cannon:GetAttribute("BarrelWood"))
                or tonumber(C.Angles.BarrelWood)
                or CFG.FixedBarrelWood,
        }
    end

    local function enterCannon()
        local cannon = acquireCannon()

        if not cannon then
            C.Status = "P1 • waiting for Setup Cannon"
            return false
        end

        if cannon:GetAttribute("Player") == player.Name then
            C.Entered = true
            C.MountRejects = 0
            C.Angles = readAngles(cannon)
            return true
        end

        local now = os.clock()

        if now - (tonumber(C.LastMountAttemptAt) or 0)
            < CFG.MountRetry then
            return false
        end

        C.LastMountAttemptAt = now

        local ok, result, err =
            invokeCannon("State", cannon, true)

        if ok
            and (
                type(result) == "table"
                or result == true
            ) then

            if type(result) == "table" then
                C.Angles = {
                    Base = tonumber(result.Base) or CFG.FixedBase,
                    BarrelWood =
                        tonumber(result.BarrelWood)
                        or CFG.FixedBarrelWood,
                }
            else
                C.Angles = readAngles(cannon)
            end

            C.Entered = true
            C.MountRejects = 0
            C.LastProgressAt = now
            C.LastProgressReason = "cannon mounted"
            C.Status = "P1 • mounted cannon"
            return true
        end

        C.Entered = false
        C.MountRejects =
            (tonumber(C.MountRejects) or 0)
            + 1

        if C.MountRejects >= CFG.MountRejectReset then
            C.RecoveryCount =
                (tonumber(C.RecoveryCount) or 0)
                + 1
            C.Cannon = nil
            C.LastMountAttemptAt = 0
            C.MountRejects = 0
            C.Status =
                "P1 • mount recovery • reacquiring cannon"
            return false
        end

        C.Status =
            "P1 • cannon mount rejected "
            .. tostring(C.MountRejects)
            .. "/"
            .. tostring(CFG.MountRejectReset)
            .. " • "
            .. tostring(err or result)

        return false
    end

    local function exitCannon(reason)
        local cannon = C.Cannon

        if cannon
            and cannon.Parent
            and cannon:GetAttribute("Player") == player.Name then

            invokeCannon(
                "State",
                cannon,
                false,
                {Angles = C.Angles or readAngles(cannon)}
            )
        end

        C.Entered = false

        if reason then
            C.Status = tostring(reason)
        end
    end

    local function attachmentEvidence(cannon)
        cannon = cannon or C.Cannon

        if not cannon or not cannon.Parent then
            return false, "cannon missing"
        end

        if cannon:GetAttribute("Player") == player.Name then
            return true, "owner attribute"
        end

        local character = spearCharacter()
        local humanoid = spearHumanoid()
        local seatPart = humanoid and humanoid.SeatPart

        if seatPart
            and seatPart:IsDescendantOf(cannon) then
            return true, "humanoid seat"
        end

        local function crossAssemblyJoint(object)
            local ok, part0, part1 = pcall(function()
                return object.Part0, object.Part1
            end)

            if not ok or (not part0 and not part1) then
                return false
            end

            local p0Character =
                part0
                and character
                and part0:IsDescendantOf(character)

            local p1Character =
                part1
                and character
                and part1:IsDescendantOf(character)

            local p0Cannon =
                part0 and part0:IsDescendantOf(cannon)

            local p1Cannon =
                part1 and part1:IsDescendantOf(cannon)

            return
                (p0Character and p1Cannon)
                or (p1Character and p0Cannon)
        end

        if character then
            for _, object in ipairs(character:GetDescendants()) do
                if (
                    object:IsA("Weld")
                    or object:IsA("WeldConstraint")
                    or object:IsA("Motor6D")
                )
                    and crossAssemblyJoint(object) then
                    return true, "character joint"
                end
            end
        end

        for _, object in ipairs(cannon:GetDescendants()) do
            if (
                object:IsA("Weld")
                or object:IsA("WeldConstraint")
                or object:IsA("Motor6D")
            )
                and crossAssemblyJoint(object) then
                return true, "cannon joint"
            end
        end

        return false, "detached"
    end

    local function findRecentProjectile()
        local newest = nil

        for _, object in ipairs(workspace:GetChildren()) do
            if object:IsA("Model")
                and object:GetAttribute("Player") == player.Name
                and object:GetAttribute("Skill") == "Cannon" then
                newest = object
            end
        end

        return newest or workspace:FindFirstChild("Cannon")
    end

    local function fireImpactBurst(projectile, shotId)
        -- V15.6.32: cannon impact belongs to the projectile/shot, not to our
        -- current mount state. P1 may deliberately release the cannon so
        -- Thunder Spears can defend Eren before the projectile impact arrives.
        if not C.Active
            or C.Stage ~= "P1 CANNON STALL" then
            return false
        end

        local age = os.clock() - C.LastShotAt

        if age < 0 or age > CFG.ImpactRecentShotWindow then
            return false
        end

        shotId = tonumber(shotId) or C.Shots

        if shotId > 0
            and C.LastImpactShotId == shotId then
            return false
        end

        projectile = projectile or findRecentProjectile()

        if not projectile or not projectile.Parent then
            return false
        end

        local boss = findBoss(false)
        local nape = boss and bladeExactNape(boss) or nil
        local _, post = remotes()

        if not nape
            or not post
            or not post:IsA("RemoteEvent") then
            return false
        end

        local sent = 0

        for _ = 1, CFG.ImpactRepeats do
            local ok = pcall(function()
                post:FireServer(
                    "S_Skills",
                    "Impact",
                    projectile,
                    nape.Position
                )
            end)

            if ok then sent += 1 end
        end

        if sent > 0 then
            C.LastImpactAt = os.clock()
            C.LastImpactShotId = shotId
            C.Status =
                "P1 • cannon IMPACT x"
                .. tostring(sent)
            return true
        end

        return false
    end

    local function fireCannon()
        local cannon = C.Cannon

        if not cannonValid(cannon) then
            return false
        end

        if cannon:GetAttribute("Firing") == true then
            return false
        end

        local cooldown =
            tonumber(cannon:GetAttribute("Cooldown"))

        if cooldown ~= nil
            and cooldown > CFG.CannonReadyEpsilon then
            return false
        end

        if not findBoss(false) then
            C.Status = "P1 • waiting for Colossal"
            return false
        end

        local angles = {
            Base = CFG.FixedBase,
            BarrelWood = CFG.FixedBarrelWood,
        }

        local ok, result =
            invokeCannon("Shoot", angles)

        if ok and result == true then
            C.Angles = angles
            C.Shots += 1
            C.LastShotAt = os.clock()
            C.LastProgressAt = C.LastShotAt
            C.LastProgressReason =
                "cannon shot " .. tostring(C.Shots)

            if C.GuardRecoveryActive
                and C.Shots
                    > (
                        tonumber(
                            C.GuardRecoveryShotBaseline
                        )
                        or 0
                    ) then
                C.GuardRecoveryActive = false
            end

            C.Status =
                "P1 • cannon shot "
                .. tostring(C.Shots)

            local shotId = C.Shots

            task.delay(
                CFG.ImpactFallbackDelay,
                function()
                    if C.Active
                        and C.Stage == "P1 CANNON STALL"
                        and C.Entered
                        and C.LastImpactShotId ~= shotId then

                        local projectile =
                            findRecentProjectile()

                        if projectile then
                            pcall(
                                fireImpactBurst,
                                projectile,
                                shotId
                            )
                        end
                    end
                end
            )

            return true
        end

        return false
    end

    local function fireSpearTargets(parts, label)
        if C.SpearBusy
            or os.clock() < C.NextSpearAt
            or SpearRuntime.RefillBusy then
            return false
        end

        if not spearEquipped() then
            C.Status =
                tostring(label or "SPEARS")
                .. " • equip Thunder Spears"
            return false
        end

        -- V15.6.32: S_Fire is rejected while the server still owns us as a
        -- cannon user. Release the cannon first and wait for real detach evidence;
        -- the next fast Colossal tick fires Spears once ownership is clear.
        local cannonAttached = C.Entered
            or select(1, attachmentEvidence(C.Cannon))
        if cannonAttached then
            exitCannon(tostring(label or "SPEARS") .. " • releasing cannon")
            C.NextSpearAt = os.clock() + 0.08
            return false
        end

        local ammo = spearReadAmmo()
        if App.Values.AutoSpearRefill == true
            and ammo ~= nil
            and ammo <= 0 then
            C.Status = "Colossal • remote spear refill"
            C.NextSpearAt = os.clock() + 0.18
            if not SpearRuntime.RefillBusy
                and os.clock() >= (tonumber(SpearRuntime.NextRefillAt) or 0) then
                task.spawn(spearDoRefill)
            end
            return false
        end

        local spearName = spearFindAvailableName()

        if not spearName then
            if App.Values.AutoSpearRefill == true
                and not SpearRuntime.RefillBusy
                and os.clock() >= (tonumber(SpearRuntime.NextRefillAt) or 0) then
                C.Status = "Colossal • remote spear refill"
                C.NextSpearAt = os.clock() + 0.18
                task.spawn(spearDoRefill)
            else
                C.Status = "Colossal • no numbered spear object"
            end
            return false
        end

        local get, post = remotes()

        if not get
            or not get:IsA("RemoteFunction")
            or not post
            or not post:IsA("RemoteEvent") then
            C.Status = "Colossal • spear remotes missing"
            return false
        end

        local targets = {}

        for _, part in ipairs(parts or {}) do
            if #targets >= CFG.AttackBankBudget then
                break
            end

            if part
                and part:IsA("BasePart")
                and part.Parent then
                targets[#targets + 1] = part
            end
        end

        if #targets == 0 then
            return false
        end

        -- V15.6 hard self-damage guard. Never arm/detonate a Colossal spear
        -- bank while our character is inside the blast danger radius.
        local liveRoot = spearRoot()
        if C.Stage == "P2 BOSS" and liveRoot then
            for _, targetPart in ipairs(targets) do
                if targetPart
                    and targetPart.Parent
                    and (targetPart.Position - liveRoot.Position).Magnitude
                        < CFG.SpearMinBlastDistance then

                    C.Status =
                        "Colossal • spear blocked • unsafe blast distance"
                    C.NextSpearAt = os.clock() + 0.16
                    return false
                end
            end
        end

        if os.clock() < (tonumber(C.EmergencyUntil) or 0) then
            return false
        end

        C.SpearBusy = true

        task.spawn(function()
            local okFire, accepted = pcall(function()
                return get:InvokeServer(
                    "Spears",
                    "S_Fire",
                    tostring(spearName)
                )
            end)

            if not okFire or accepted ~= true then
                C.Status = "Colossal • S_Fire rejected • detached=" .. tostring(not select(1, attachmentEvidence(C.Cannon)))
                C.NextSpearAt = os.clock() + 0.14
                C.SpearBusy = false
                return
            end

            local character = spearCharacter()
            local armedAt = os.clock()

            while character
                and character.Parent
                and character:GetAttribute("Current_Spear") == nil
                and os.clock() - armedAt < 0.60 do
                task.wait(0.01)
            end

            task.wait(0.105)

            local explodeNonce = SpearRuntime.spearBurstNonce()
            local sent = 0

            for _, targetPart in ipairs(targets) do
                if targetPart and targetPart.Parent then
                    local ok = pcall(function()
                        post:FireServer(
                            "Spears",
                            "S_Explode",
                            targetPart.Position,
                            explodeNonce
                        )
                    end)

                    if ok then sent += 1 end
                end
            end

            C.Status =
                tostring(label or "SPEARS")
                .. " • x"
                .. tostring(sent)

            if sent > 0 then
                C.LastProgressAt = os.clock()
                C.LastProgressReason =
                    tostring(label or "SPEARS")
                    .. " x"
                    .. tostring(sent)
            end

            C.NextSpearAt = os.clock() + 1.20
            if sent > 0 then
                C.DefensePending = false
                C.DefensePendingUntil = os.clock() + 0.20
            end
            C.SpearBusy = false
        end)

        return true
    end

    local function bladeBank(plan, label)
        if os.clock() < (tonumber(C.EmergencyUntil) or 0) then
            return false
        end

        if BladeRuntime.Busy
            or os.clock() < C.BladeNextAt
            or (
                App.BladeRefill
                and App.BladeRefill.Busy
            ) then
            return false
        end

        if not bladeEquipped() then
            C.Status =
                tostring(label or "BLADES")
                .. " • equip Blades"
            return false
        end

        if App.BladeRefill
            and App.BladeRefill.IsBroken
            and App.BladeRefill.IsBroken(
                App.BladeRefill.ReadFill()
            ) then
            C.Status = "Colossal • waiting Blade refill"
            return false
        end

        local _, post = remotes()

        if not post or not post:IsA("RemoteEvent") then
            return false
        end

        local budget = CFG.AttackBankBudget
        local low, high = 625, 850
        local registers = 0

        BladeRuntime.Busy = true

        local ok, err = pcall(function()
            post:FireServer("Attacks", "Slash", true)

            for _, item in ipairs(plan or {}) do
                if registers >= budget then
                    break
                end

                local titan = item and item.Titan
                local repeats =
                    math.max(
                        1,
                        math.floor(
                            tonumber(
                                item
                                and item.Repeats
                                or 1
                            )
                        )
                    )

                for _ = 1, repeats do
                    if registers >= budget then
                        break
                    end

                    local nape =
                        titan
                        and bladeExactNape(titan)
                        or nil

                    if nape
                        and modelAlive(titan) then
                        post:FireServer(
                            "Hitboxes",
                            "Register",
                            nape,
                            math.random(low, high)
                        )
                        registers += 1
                    end
                end
            end
        end)

        BladeRuntime.Busy = false

        if not ok then
            C.Status =
                "Colossal Blade error • "
                .. tostring(err)
            C.BladeNextAt = os.clock() + 0.15
            return false
        end

        BladeRuntime.LastSlashes = 1
        BladeRuntime.LastRegisters = registers
        BladeRuntime.TotalSlashes += 1
        BladeRuntime.TotalRegisters += registers

        C.Status =
            tostring(label or "BLADES")
            .. " • Reg "
            .. tostring(registers)

        if registers > 0 then
            C.LastProgressAt = os.clock()
            C.LastProgressReason =
                tostring(label or "BLADES")
                .. " reg "
                .. tostring(registers)
        end

        C.BladeNextAt = os.clock() + 0.10
        return registers > 0
    end

    local function guardianAnchor()
        local anchor = resolveErenAnchor(false)
        local character = spearCharacter()
        local root = spearRoot()

        if typeof(anchor) ~= "Vector3"
            or not character
            or not root then
            return false
        end

        local desired =
            anchor
            + Vector3.new(
                0,
                CFG.BladeGuardHeight,
                0
            )

        local hold = CFrame.lookAt(desired, anchor)

        character:PivotTo(hold)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero

        setCombatHoldCFrame(hold)
        return true
    end

    local function startGuardianAirborne()
        C.Entered = false
        C.GuardState = "AIRBORNE"
        C.GuardStartedAt = os.clock()
        C.GuardLastThreatAt = os.clock()
        C.GuardEvidence = "detached"
    end

    local function beginGuardianDismount()
        local cannon = C.Cannon
        local attached, evidence =
            attachmentEvidence(cannon)

        if not attached then
            startGuardianAirborne()
            return
        end

        C.GuardState = "DISMOUNT"
        C.GuardRequestedAt = os.clock()
        C.GuardLastRequestAt = os.clock()
        C.GuardEvidence = evidence

        invokeCannon(
            "State",
            cannon,
            false,
            {Angles = C.Angles or readAngles(cannon)}
        )
    end

    local function updateGuardianDismount()
        local attached, evidence =
            attachmentEvidence(C.Cannon)

        C.GuardEvidence = evidence

        if not attached then
            startGuardianAirborne()
            return true
        end

        if os.clock() - C.GuardLastRequestAt
            >= CFG.BladeGuardHandshakeRetry then

            C.GuardLastRequestAt = os.clock()

            if C.Cannon and C.Cannon.Parent then
                invokeCannon(
                    "State",
                    C.Cannon,
                    false,
                    {
                        Angles =
                            C.Angles
                            or readAngles(C.Cannon)
                    }
                )
            end
        end

        return false
    end

    local function beginGuardianRemount()
        local cannon = C.Cannon

        if not cannon or not cannon.Parent then
            C.GuardState = "IDLE"
            C.Cannon = nil
            C.Entered = false
            return
        end

        C.GuardState = "REMOUNT"
        C.GuardRequestedAt = os.clock()
        C.GuardLastRequestAt = os.clock()
        C.Entered = false

        invokeCannon("State", cannon, true)
    end

    local function updateGuardianRemount()
        local cannon = C.Cannon

        if not cannon or not cannon.Parent then
            C.GuardState = "IDLE"
            C.Cannon = nil
            C.Entered = false
            return false
        end

        local attached, evidence =
            attachmentEvidence(cannon)

        C.GuardEvidence = evidence

        if attached then
            C.GuardState = "IDLE"
            C.Entered = true
            C.Angles = readAngles(cannon)
            C.GuardRecoveryActive = true
            C.GuardRecoveryStartedAt = os.clock()
            C.GuardRecoveryShotBaseline = C.Shots
            return true
        end

        if os.clock() - C.GuardLastRequestAt
            >= CFG.BladeGuardHandshakeRetry then

            C.GuardLastRequestAt = os.clock()
            invokeCannon("State", cannon, true)
        end

        return false
    end

    local function updateGuardRecovery()
        if not C.GuardRecoveryActive then
            return false
        end

        if C.Shots
            > (
                tonumber(C.GuardRecoveryShotBaseline)
                or 0
            ) then
            C.GuardRecoveryActive = false
            return false
        end

        if os.clock() - C.GuardRecoveryStartedAt
            >= CFG.BladeGuardRecoveryMaxSeconds then
            C.GuardRecoveryActive = false
            return false
        end

        return true
    end

    local function stepBladeGuardian(threats)
        if App.BladeRefill
            and App.BladeRefill.Busy then
            return true
        end

        local state = C.GuardState

        if state == "IDLE" then
            if #threats <= 0 then
                updateGuardRecovery()
                return false
            end

            local recoveryLocked =
                updateGuardRecovery()

            if recoveryLocked
                and C.CriticalThreatCount <= 0 then
                C.Status =
                    "P1 • cannon recovery before next Eren guard"
                return false
            end

            local attached =
                select(
                    1,
                    attachmentEvidence(C.Cannon)
                )

            if C.Entered or attached then
                beginGuardianDismount()
            else
                startGuardianAirborne()
            end

            return true
        end

        if state == "DISMOUNT" then
            updateGuardianDismount()
            return true
        end

        if state == "AIRBORNE" then
            guardianAnchor()

            local now = os.clock()

            if #threats > 0 then
                C.GuardLastThreatAt = now

                local plan = {}

                for index = 1,
                    math.min(
                        #threats,
                        CFG.P1DefenseMaxTargets
                    ) do

                    plan[#plan + 1] = {
                        Titan = threats[index].Titan,
                        Repeats = 1,
                    }
                end

                bladeBank(plan, "P1 EREN GUARD")
            end

            local clearAge =
                now - C.GuardLastThreatAt
            local guardAge =
                now - C.GuardStartedAt

            if #threats <= 0
                and clearAge >= CFG.BladeGuardClearGrace then
                beginGuardianRemount()
            elseif #threats > 0
                and guardAge >= CFG.BladeGuardMaxSeconds then
                -- R5 COLOSSAL HOTFIX: never abandon live Eren threats just
                -- because the old guard timer expired. Refresh the guard epoch
                -- and stay airborne until the threat scan is actually clear.
                C.GuardStartedAt = now
                C.Status =
                    "P1 EREN GUARD • holding until clear"
            end

            return true
        end

        if state == "REMOUNT" then
            updateGuardianRemount()
            return true
        end

        C.GuardState = "IDLE"
        return false
    end

    local function p2SafeHold(nape, verticalOffset, horizontalOffset, serial)
        local root = spearRoot()
        if not root or not nape then return nil end

        local height = math.max(230, tonumber(verticalOffset) or 250)
        local safe = nape.Position + Vector3.new(0, height, 0)
        local offset = math.max(0, tonumber(horizontalOffset) or 0)

        -- Normally offset is zero: scanner capture showed the stable hub sitting
        -- almost exactly above the active target (~250 studs vertical separation).
        if offset > 0 then
            local flat = Vector3.new(
                root.Position.X - nape.Position.X,
                0,
                root.Position.Z - nape.Position.Z
            )
            if flat.Magnitude < 1 then
                flat = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
            end
            if flat.Magnitude < 1 then flat = Vector3.new(1, 0, 0) end
            safe = safe + flat.Unit * offset
        end

        local minimum = CFG.SpearMinBlastDistance + 10
        if (safe - nape.Position).Magnitude < minimum then
            safe = nape.Position + Vector3.new(0, minimum + 10, 0)
        end

        return CombatSafety.ProbeUprightCFrame(CFrame.new(safe))
    end

    local function moveSpearP2Safety(reason)
        local character = spearCharacter()
        local root = spearRoot()
        local humanoid = spearHumanoid()
        local boss = findBoss(true)
        local nape = boss and bladeExactNape(boss) or nil

        if not character
            or not root
            or not humanoid
            or humanoid.Health <= 0
            or not nape then
            return false
        end

        local serial = C.P2SafetySerial
        local hold = p2SafeHold(
            nape,
            CFG.SpearP2OrbitHeight,
            CFG.SpearP2OrbitRadius,
            serial
        )
        if not hold then return false end

        root.Anchored = false
        root.CFrame = CombatSafety.ProbeUprightCFrame(hold)
        root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
        root.AssemblyAngularVelocity = Vector3.zero


        C.SpearP2HoldCFrame = hold
        C.LastSpearP2HoldAt = os.clock()

        C.P2SafetySerial = serial + 1
        C.LastP2SafetyAt = os.clock()
        C.Status =
            "P2 Spears safety • "
            .. tostring(reason or "handoff")
        return true
    end

    local function holdSpearP2Safety()
        if C.Completed
            or C.Stage ~= "P2 BOSS"
            or C.Mode ~= "Spears"
            or typeof(C.SpearP2HoldCFrame) ~= "CFrame" then
            return false
        end

        local now = os.clock()
        if now - (tonumber(C.LastSpearP2HoldAt) or 0)
            < CFG.SpearP2HoldRefresh then
            return true
        end

        local character = spearCharacter()
        local root = spearRoot()
        local humanoid = spearHumanoid()

        if not character
            or not root
            or not humanoid
            or humanoid.Health <= 0 then
            return false
        end

        root.Anchored = false
        root.CFrame = CombatSafety.ProbeUprightCFrame(C.SpearP2HoldCFrame)
        root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
        root.AssemblyAngularVelocity = Vector3.zero
        humanoid.Sit = false
        humanoid.PlatformStand = false

        C.LastSpearP2HoldAt = now
        return true
    end

    local function trackBladeP2()
        if C.Completed
            or (
                App.BladeRefill
                and App.BladeRefill.Busy
            ) then
            return false
        end

        local now = os.clock()

        if now - C.LastP2TrackAt
            < CFG.BladeP2TrackRefresh then
            return true
        end

        local character = spearCharacter()
        local root = spearRoot()
        local humanoid = spearHumanoid()
        local boss = findBoss(false)
        local nape = boss and bladeExactNape(boss) or nil

        if not character
            or not root
            or not humanoid
            or humanoid.Health <= 0
            or not nape then
            return false
        end

        local hold = p2SafeHold(
            nape,
            CFG.BladeP2TrackHeight,
            CFG.BladeP2OrbitRadius,
            0
        )
        if not hold then return false end

        root.Anchored = false
        root.CFrame = CombatSafety.ProbeUprightCFrame(hold)
        root.AssemblyLinearVelocity = Vector3.new(0, 20, 0)
        root.AssemblyAngularVelocity = Vector3.zero

        humanoid.Sit = false
        humanoid.PlatformStand = false

        C.P2HoldCFrame = hold
        C.LastP2TrackAt = now
        setCombatHoldCFrame(hold)
        return true
    end

    -- Carry V1 scans every live non-boss Pure in P2 and sorts by Eren distance.
    local function carryV1Pures()
        local folder = workspace:FindFirstChild("Titans")
        local boss = findBoss(false)
        local anchor = resolveErenAnchor(false)
        local root = spearRoot()
        local entries = {}
        local nearEren = 0

        if not folder then return entries, nearEren end

        for _, titan in ipairs(folder:GetChildren()) do
            if titan ~= boss
                and modelAlive(titan)
                and not looksColossal(titan) then
                local nape = bladeExactNape(titan)
                if nape then
                    local erenDistance = typeof(anchor) == "Vector3"
                        and (anchor - nape.Position).Magnitude
                        or nil
                    if erenDistance and erenDistance <= 175 then
                        nearEren += 1
                    end
                    entries[#entries + 1] = {
                        Titan = titan,
                        Part = nape,
                        ErenDistance = erenDistance,
                        PlayerDistance = root and (root.Position - nape.Position).Magnitude or 0,
                    }
                end
            end
        end

        table.sort(entries, function(a, b)
            if typeof(anchor) == "Vector3" then
                local ad = tonumber(a.ErenDistance) or math.huge
                local bd = tonumber(b.ErenDistance) or math.huge
                if ad ~= bd then return ad < bd end
            end
            return (tonumber(a.PlayerDistance) or 0) < (tonumber(b.PlayerDistance) or 0)
        end)

        return entries, nearEren
    end

    local function readBossHealthPercent()
        local boss = findBoss(false)
        if not boss then return nil end
        local humanoid = boss:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.MaxHealth > 0 then
            return math.clamp((humanoid.Health / humanoid.MaxHealth) * 100, 0, 100)
        end
        return nil
    end

    local function carryV1DefenseQuota(pures, nearEren)
        readErenHealth()
        local percent = tonumber(C.ErenHealthPercent)
        local totalPure = type(pures) == "table" and #pures or 0
        local nearCount = tonumber(nearEren) or 0

        local earlyThreshold = App.Values.ColossalEarlyDefense == true and 78 or 60
        local active =
            (percent ~= nil and percent <= earlyThreshold)
            or nearCount >= 5
            or totalPure >= 12

        if not active then
            C.CarryV1Status = "Stable • Pure " .. tostring(totalPure)
            C.CarryV1PureStreak = 0
            return false, 1
        end

        local quota = 3
        if percent ~= nil and percent <= 35 then
            quota = 5
        elseif percent ~= nil and percent <= 55 then
            quota = 4
        elseif nearCount >= 10 then
            quota = 4
        end

        C.CarryV1Status =
            "EREN DEFENSE • quota "
            .. tostring(quota)
            .. ":1 • near "
            .. tostring(nearCount)
            .. " • total "
            .. tostring(totalPure)
        return true, quota
    end

    local function stepP2Spears()
        local boss = findBoss(false)
        local nape = boss and bladeExactNape(boss) or nil
        if not nape then return end

        if App.Values.ColossalKillPriority == true then
            local bossHP = readBossHealthPercent()
            if bossHP ~= nil and bossHP <= 5 then
                local repeats = math.clamp(
                    math.floor((tonumber(App.Values.RaidBossMultiHit) or 5) + 0.5),
                    1, CFG.AttackBankBudget
                )
                local parts = {}
                for _ = 1, repeats do parts[#parts + 1] = nape end
                if fireSpearTargets(parts, "KILL SHOT • P2 COLOSSAL") then
                    C.CarryV1PureStreak = 0
                    C.CarryV1NextCycle = "Boss"
                end
                return
            end
        end

        local pures, nearEren = carryV1Pures()
        local emergency, quota = carryV1DefenseQuota(pures, nearEren)
        local pureWanted = #pures > 0 and (
            (emergency and (tonumber(C.CarryV1PureStreak) or 0) < quota)
            or (not emergency and C.CarryV1NextCycle == "Pure")
        )

        if pureWanted then
            local parts = {}
            local leanDefense = App.Values.ColossalLeanDefense == true
            local limit = leanDefense
                and ((tonumber(C.ErenHealthPercent) or 100) <= 35 and 4 or 3)
                or ((tonumber(C.ErenHealthPercent) or 100) <= 35 and 10 or 8)
            for index = 1, math.min(#pures, limit) do
                local part = pures[index] and pures[index].Part
                if part then parts[#parts + 1] = part end
            end
            if #parts > 0 and fireSpearTargets(parts, "CARRY V1 • EREN PURE") then
                C.CarryV1PureStreak = (tonumber(C.CarryV1PureStreak) or 0) + 1
                C.CarryV1NextCycle = "Boss"
            end
            return
        end

        local repeats = math.clamp(
            math.floor((tonumber(App.Values.RaidBossMultiHit) or 5) + 0.5),
            1,
            CFG.AttackBankBudget
        )
        local parts = {}
        for _ = 1, repeats do parts[#parts + 1] = nape end

        if fireSpearTargets(parts, "CARRY V1 • P2 COLOSSAL") then
            C.CarryV1PureStreak = 0
            C.CarryV1NextCycle = #pures > 0 and "Pure" or "Boss"
        end
    end

    local function stepP2Blades()
        local boss = findBoss(false)
        local nape = boss and bladeExactNape(boss) or nil
        if not nape then return end

        if App.Values.ColossalKillPriority == true then
            local bossHP = readBossHealthPercent()
            if bossHP ~= nil and bossHP <= 5 then
                local repeats = math.clamp(
                    math.floor((tonumber(App.Values.RaidBossMultiHit) or 5) + 0.5),
                    1, CFG.AttackBankBudget
                )
                if bladeBank({{Titan=boss, Repeats=repeats}}, "KILL SHOT • P2 COLOSSAL") then
                    C.CarryV1PureStreak = 0
                    C.CarryV1NextCycle = "Boss"
                end
                return
            end
        end

        local pures, nearEren = carryV1Pures()
        local emergency, quota = carryV1DefenseQuota(pures, nearEren)
        local pureWanted = #pures > 0 and (
            (emergency and (tonumber(C.CarryV1PureStreak) or 0) < quota)
            or (not emergency and C.CarryV1NextCycle == "Pure")
        )

        if pureWanted then
            local plan = {}
            local leanDefense = App.Values.ColossalLeanDefense == true
            local limit = leanDefense
                and ((tonumber(C.ErenHealthPercent) or 100) <= 35 and 4 or 3)
                or ((tonumber(C.ErenHealthPercent) or 100) <= 35 and 10 or 8)
            for index = 1, math.min(#pures, limit) do
                local titan = pures[index] and pures[index].Titan
                if titan then plan[#plan + 1] = {Titan=titan, Repeats=1} end
            end
            if #plan > 0 and bladeBank(plan, "CARRY V1 • EREN PURE") then
                C.CarryV1PureStreak = (tonumber(C.CarryV1PureStreak) or 0) + 1
                C.CarryV1NextCycle = "Boss"
            end
            return
        end

        local repeats = math.clamp(
            math.floor((tonumber(App.Values.RaidBossMultiHit) or 5) + 0.5),
            1,
            CFG.AttackBankBudget
        )
        if bladeBank({{Titan=boss, Repeats=repeats}}, "CARRY V1 • P2 COLOSSAL") then
            C.CarryV1PureStreak = 0
            C.CarryV1NextCycle = #pures > 0 and "Pure" or "Boss"
        end
    end

    local function resetRuntime()
        C.Active = false
        C.Completed = false
        C.Stage = "IDLE"
        C.PreviousStage = "IDLE"
        C.P2Confirmed = false
        C.TransitionActive = false
        C.Boss = nil
        C.Nape = nil
        C.CachedBoss = nil
        C.LastBossScanAt = 0
        C.LastBossSeenAt = 0
        C.LastBossMissingAt = 0

        C.ErenAnchor = nil
        C.ErenAnchorAt = 0
        C.ErenObjectiveObject = nil
        C.ErenFallbackScanAt = 0
        C.ErenHealthPercent = nil
        C.LastErenHealthPercent = nil
        C.LastThreatEntries = {}
        C.LastThreatScanAt = 0

        C.ObjectiveCacheAt = 0
        C.ObjectiveCacheText = ""
        C.ErenObjectiveCacheText = ""

        C.ActiveSince = 0
        C.LastProgressAt = 0
        C.LastProgressReason = "idle"
        C.MountRejects = 0
        C.CompletedClearSince = 0

        C.GuardState = "IDLE"
        C.GuardRecoveryActive = false
        C.P2HoldCFrame = nil
        C.SpearP2HoldCFrame = nil
        C.LastSpearP2HoldAt = 0
        C.OpeningSkillUntil = 0
        C.OpeningSkillStarted = false
        C.LastPlayerHealth = nil
        C.EmergencyUntil = 0
        C.LastEmergencyAt = 0
        C.CarryV1NextCycle = "Boss"
        C.CarryV1PureStreak = 0
        C.CarryV1Status = "Waiting"
        C.Status = "Idle"

        local root = spearRoot()

        if root then
            pcall(function()
                root.Anchored = false
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)
        end
    end

    local function updateStage()
        local stage = computeStage()
        local previous = C.Stage

        if stage ~= previous then
            C.PreviousStage = previous
            C.Stage = stage

            if stage == "P2 BOSS"
                and previous ~= "P2 BOSS" then

                C.TransitionActive = true
                C.TransitionStartedAt = os.clock()
                C.P2SafetyUntil =
                    os.clock() + CFG.P2ShieldSeconds

                C.LastProgressAt = os.clock()
                C.LastProgressReason = "P2 transition"
                C.CachedBoss = nil
                C.LastBossScanAt = 0

                C.GuardState = "IDLE"
                C.GuardRecoveryActive = false
                exitCannon(
                    "P1 complete • exiting cannon"
                )

                if C.Mode == "Spears" then
                    task.defer(function()
                        task.wait(0.05)
                        moveSpearP2Safety("phase handoff")
                    end)
                end
            end
        end

        if C.TransitionActive then
            local boss = findBoss(false)
            local camera = workspace.CurrentCamera
            local cameraReady =
                not camera
                or camera.CameraType ~= Enum.CameraType.Scriptable

            local elapsed =
                os.clock() - C.TransitionStartedAt

            if boss
                and modelAlive(boss)
                and cameraReady
                and elapsed >= CFG.P2TransitionMinimum then

                C.TransitionActive = false

                if C.Mode == "Spears" then
                    moveSpearP2Safety("camera released")
                else
                    trackBladeP2()
                end

            elseif boss
                and modelAlive(boss)
                and elapsed >= CFG.P2TransitionWatchdog then

                C.TransitionActive = false
            end
        end

        return C.Stage
    end

    if C.ImpactConnection then
        pcall(function()
            C.ImpactConnection:Disconnect()
        end)
        C.ImpactConnection = nil
    end

    local _, post = remotes()

    if post and post:IsA("RemoteEvent") then
        C.ImpactConnection =
            post.OnClientEvent:Connect(
                function(
                    category,
                    action,
                    projectile,
                    hitbox,
                    power
                )
                    if not C.Active
                        or tostring(category) ~= "Skills"
                        or tostring(action) ~= "Impact"
                        or tonumber(power) ~= 5 then
                        return
                    end

                    if not projectile
                        or not projectile.Parent then
                        return
                    end

                    local now = os.clock()

                    if now - C.LastImpactTriggerAt
                        < CFG.ImpactDedupe then
                        return
                    end

                    C.LastImpactTriggerAt = now

                    task.delay(
                        CFG.ImpactDelay,
                        function()
                            pcall(
                                fireImpactBurst,
                                projectile,
                                C.Shots
                            )
                        end
                    )
                end
            )
    end

    C.OwnsCombat = function()
        return C.Active == true
            and canRun()
    end

    C.ReturnCFrame = function()
        if C.Stage == "P2 BOSS"
            and C.Mode == "Blades"
            and typeof(C.P2HoldCFrame) == "CFrame" then
            return C.P2HoldCFrame
        end

        if C.Stage == "P2 BOSS"
            and C.Mode == "Spears"
            and typeof(C.SpearP2HoldCFrame) == "CFrame" then
            return C.SpearP2HoldCFrame
        end

        local root = spearRoot()
        return root and root.CFrame or nil
    end

    task.spawn(function()
        while gui and gui.Parent do
            local delay = CFG.IdleLoopDelay

            if C.Active then
                delay =
                    colossalLowPower()
                    and CFG.LowPowerLoopDelay
                    or CFG.LoopDelay
            end

            if C.Completed then
                delay = CFG.CompletedLoopDelay
            end

            task.wait(delay)

            if not canRun() then
                if C.Active then
                    exitCannon()
                    resetRuntime()
                end
                continue
            end

            local now = os.clock()
            local objective = visibleObjectiveText()
            local boss = findBoss(false)

            if C.Completed then
                -- Auto Retry can keep the same script alive. Once the completed
                -- objective and old boss disappear for a short grace period,
                -- recycle the controller for the next Colossal run.
                local completionStillVisible =
                    p2Complete()
                    or (
                        objective ~= ""
                        and (
                            string.find(objective, "[1/1]", 1, true)
                            or string.find(objective, "[1 / 1]", 1, true)
                        )
                    )

                local oldBossStillAlive =
                    boss
                    and modelAlive(boss)

                if completionStillVisible
                    or oldBossStillAlive then
                    C.CompletedClearSince = 0
                    continue
                end

                if (tonumber(C.CompletedClearSince) or 0) <= 0 then
                    C.CompletedClearSince = now
                    continue
                end

                if now - C.CompletedClearSince >= 1.5 then
                    resetRuntime()
                end

                continue
            end

            local detected =
                objective ~= ""
                or (
                    boss
                    and looksColossal(boss)
                )

            if not detected and not C.Active then
                continue
            end

            if not detected
                and C.Active
                and C.TransitionActive ~= true
                and now
                    - math.max(
                        tonumber(C.LastProgressAt) or 0,
                        tonumber(C.ActiveSince) or 0
                    )
                    >= 15.0 then

                C.RecoveryCount =
                    (tonumber(C.RecoveryCount) or 0)
                    + 1

                exitCannon(
                    "Colossal state lost • soft reset"
                )
                resetRuntime()
                continue
            end

            if not C.Active then
                C.Active = true
                C.ActiveSince = now
                C.LastProgressAt = now
                C.LastProgressReason = "Colossal detected"
                C.RecoveryCount = 0
                C.OpeningSkillStarted = App.Values.AutoUseSkills == true
                C.OpeningSkillUntil =
                    C.OpeningSkillStarted
                    and (now + CFG.OpeningSkillWindow)
                    or now
                C.LastPlayerHealth = nil
                C.EmergencyUntil = 0
                C.Status = "Colossal detected • initializing"

                -- V14.5 R4: anything hidden by Remove Map Props before Colossal
                -- detection is restored as soon as this raid takes ownership.
                if App.RestoreMapProps then
                    pcall(App.RestoreMapProps)
                end
            end

            C.Mode = currentMode()

            if App.TransitionGuard and App.TransitionGuard.BlockGameplay
                and App.TransitionGuard.BlockGameplay() then
                C.Status = "Transition • Colossal combat suspended"
                continue
            end

            if C.Mode == "None" then
                C.Status =
                    "Colossal detected • enable Blades or Spears farm"
                continue
            end

            local stage = updateStage()

            if C.Mode == "Spears"
                and App.Values.AutoSpearRefill == true
                and not SpearRuntime.RefillBusy
                and os.clock() >= (tonumber(SpearRuntime.NextRefillAt) or 0) then
                local liveAmmo = spearReadAmmo()
                if liveAmmo ~= nil and liveAmmo <= 0 then
                    task.spawn(spearDoRefill)
                end
            end

            if C.TransitionActive then
                continue
            end

            if stage == "P1 CANNON STALL" then
                -- V15.6 opener: give active skills a real window BEFORE the
                -- cannon mount or Eren-defense bank steals character input.
                if C.OpeningSkillStarted
                    and now < (tonumber(C.OpeningSkillUntil) or 0) then

                    local openerErenHealth = tonumber(C.ErenHealthPercent)
                    local openerEmergency = openerErenHealth ~= nil
                        and openerErenHealth <= 45

                    if not openerEmergency then
                        if App.SkillAuto
                            and type(App.SkillAuto.Step) == "function" then
                            pcall(App.SkillAuto.Step)
                        end

                        C.Status =
                            "P1 • opening skills • cannon in "
                            .. string.format(
                                "%.1fs",
                                math.max(
                                    0,
                                    (tonumber(C.OpeningSkillUntil) or now) - now
                                )
                            )
                        continue
                    end
                end

                local threats = collectThreats(false)
                local erenHealth = tonumber(C.ErenHealthPercent)
                local erenEmergency = erenObjectiveText() ~= ""
                    and (
                        (erenHealth ~= nil and erenHealth <= CFG.ErenEmergencyHealthPercent)
                        or now < (tonumber(C.ErenDamagedUntil) or 0)
                    )

                if erenEmergency then
                    threats = collectThreats(true)
                    C.Status = "P1 EREN EMERGENCY • priority defense"
                end

                if C.Mode == "Spears" then
                    local parts = {}

                    for index = 1,
                        math.min(
                            #threats,
                            CFG.P1DefenseMaxTargets
                        ) do

                        local part =
                            threats[index]
                            and threats[index].Part

                        if part then
                            parts[#parts + 1] = part
                        end
                    end

                    if #parts > 0 then
                        C.DefensePending = true
                        C.DefensePendingUntil = math.max(tonumber(C.DefensePendingUntil) or 0, now + 1.35)
                        C.DefenseLastThreatAt = now
                        local defended = fireSpearTargets(parts, "P1 EREN DEFENSE")
                        if defended then
                            C.LastProgressAt = now
                            C.LastProgressReason = "P1 Eren spear defense"
                        end
                        -- While a Pure threat exists, cannon ownership may not steal
                        -- the same tick back from the defense/refill handoff.
                        continue
                    elseif C.DefensePending and now < (tonumber(C.DefensePendingUntil) or 0) then
                        continue
                    else
                        C.DefensePending = false
                    end

                elseif C.Mode == "Blades" then
                    if stepBladeGuardian(threats) then
                        continue
                    end
                end

                if not enterCannon() then
                    continue
                end

                local fired = fireCannon()

                if not fired
                    and C.GuardState == "IDLE" then

                    local progressAt =
                        math.max(
                            tonumber(C.LastShotAt) or 0,
                            tonumber(C.LastProgressAt) or 0,
                            tonumber(C.ActiveSince) or now
                        )

                    if now - progressAt
                        >= CFG.CannonStallSeconds then

                        C.RecoveryCount =
                            (tonumber(C.RecoveryCount) or 0)
                            + 1

                        exitCannon(
                            "P1 watchdog • reacquiring cannon"
                        )

                        C.Cannon = nil
                        C.Entered = false
                        C.LastMountAttemptAt = 0
                        C.LastProgressAt = now
                        C.LastProgressReason =
                            "P1 watchdog recovery"
                    end
                end

                continue
            end

            if stage == "P2 BOSS" then
                if C.Entered then
                    exitCannon("P2 • forced cannon release")
                end

                if p2Complete() then
                    C.Completed = true
                    C.CompletedClearSince = 0
                    C.LastProgressAt = now
                    C.LastProgressReason =
                        "Bertholdt defeated"
                    C.Status =
                        "COMPLETE • Bertholdt defeated"

                    local root = spearRoot()

                    C.P2HoldCFrame = nil
                    C.SpearP2HoldCFrame = nil
                    C.LastThreatEntries = {}

                    if root then
                        pcall(function()
                            root.Anchored = false
                            root.AssemblyLinearVelocity = Vector3.zero
                            root.AssemblyAngularVelocity = Vector3.zero
                        end)
                    end

                    continue
                end

                local p2Boss = findBoss(false)

                if not p2Boss then
                    if (tonumber(C.LastBossMissingAt) or 0) <= 0 then
                        C.LastBossMissingAt = now
                    end

                    if now - C.LastBossMissingAt
                        >= CFG.P2MissingBossRecovery then

                        C.CachedBoss = nil
                        C.LastBossScanAt = 0
                        p2Boss = findBoss(true)

                        if not p2Boss then
                            C.Status =
                                "P2 • boss missing • recovery scan"
                            C.LastBossMissingAt = now
                            C.RecoveryCount =
                                (tonumber(C.RecoveryCount) or 0)
                                + 1
                            continue
                        end
                    else
                        continue
                    end
                end

                C.LastBossMissingAt = 0
                C.LastBossSeenAt = now

                collectThreats(false)

                -- V15.6 survival monitor. A meaningful damage spike or low HP
                -- forces a short attack lock and a fresh safe-orbit snap.
                do
                    local humanoid = spearHumanoid()

                    if humanoid and humanoid.Health > 0 then
                        local health = tonumber(humanoid.Health) or 0
                        local maxHealth =
                            math.max(
                                1,
                                tonumber(humanoid.MaxHealth) or health or 1
                            )
                        local previous = tonumber(C.LastPlayerHealth)
                        local drop =
                            previous
                            and math.max(0, previous - health)
                            or 0
                        local low =
                            (health / maxHealth)
                            <= CFG.EmergencyLowHealthFraction
                        local spike =
                            drop
                            >= maxHealth * CFG.EmergencyDamageFraction

                        C.LastPlayerHealth = health

                        if (spike or low)
                            and now - (tonumber(C.LastEmergencyAt) or 0)
                                >= 0.75 then

                            C.LastEmergencyAt = now
                            C.EmergencyUntil =
                                now + CFG.EmergencyRetreatSeconds

                            if C.Mode == "Spears" then
                                moveSpearP2Safety(
                                    spike and "damage spike" or "low HP"
                                )
                            else
                                trackBladeP2()
                            end

                            C.Status =
                                spike
                                and "P2 • emergency retreat • damage spike"
                                or "P2 • emergency retreat • low HP"
                            continue
                        end
                    end
                end

                if os.clock() < (tonumber(C.EmergencyUntil) or 0) then
                    if C.Mode == "Spears" then
                        holdSpearP2Safety()
                    else
                        trackBladeP2()
                    end
                    continue
                end

                if C.Mode == "Blades" then
                    trackBladeP2()
                    stepP2Blades()

                elseif C.Mode == "Spears" then
                    if typeof(C.SpearP2HoldCFrame) ~= "CFrame" then
                        moveSpearP2Safety("P2 recovery")
                    end

                    holdSpearP2Safety()

                    if os.clock() < C.P2SafetyUntil
                        and os.clock() - C.LastP2SafetyAt
                            >= CFG.P2ShieldRefresh then
                        moveSpearP2Safety(
                            "post-cutscene shield"
                        )
                    end

                    stepP2Spears()
                end
            end
        end
    end)
end)()


App.Waves = App.Waves or {
    Busy = false,
    Status = "Waiting for Waves runtime",
    UpgradeStatus = "Upgrades idle",

    RoundActiveSince = nil,
    LastAliveCount = 0,
    WaveSerial = 0,
    LastCombatProgressAt = os.clock(),

    HoldCFrame = nil,
    LastHoldAt = 0,

    ReadyTarget = nil,
    ReadyLocked = false,
    LastReadyAttempt = 0,

    CurrentCrate = nil,
    LastCrateAttempt = 0,

    OwnsBlades = false,
    PreviousBladeFarm = false,

    UpgradeBusy = false,
    UpgradeTurn = "Gear",
    GearNextAt = 0,
    GearBothIndex = 0,
    GearNoProgress = 0,
    HQNextAt = 0,
    HQIndex = 0,
    HQNoProgress = {},
    HQNextByKey = {},
    Refilling = false,
    FarmCFrame = nil,
    LastBladeReloadAt = 0,
    LastStationAt = 0,
    NextRefillAt = 0,
    LastAttackAt = 0,
    ReadyPhase = nil,
    LastProgressAt = os.clock(),
    LastProgressReason = "Starting",
    LastPhaseSignature = nil,
    TSBuyBusy = false,
    TSBuyDone = false,
    TSBuySpent = false,
    TSBuyNextAt = 0,
    Connections = {},
    AuxPanels = {},
    Running = true,
}

;(function()
    local W = App.Waves

    W.GearKeys = W.GearKeys or {
        Blades = {
            "Crit_Chance",
            "Blade_Durability",
            "ODM_Damage",
            "Crit_Damage",
            "ODM_Speed",
            "ODM_Control",
            "ODM_Range",
            "ODM_Gas",
        },
        Spears = {
            "Crit_Chance",
            "TS_Damage",
            "Crit_Damage",
            "TS_Speed",
            "TS_Control",
            "TS_Range",
            "TS_Gas",
            "Blast_Radius",
        },
    }

    W.HQKeys = W.HQKeys or {
        "Max",
        "Regen",
        "Refills",
        "Replenish",
        "Revive",
    }

    local function premiumAllowed()
        return App.FamilySpin
            and App.FamilySpin.IsPremium
            and App.FamilySpin.IsPremium() == true
    end

    local function liveCharacter()
        local character = player.Character
        local humanoid =
            character
            and character:FindFirstChildOfClass("Humanoid")
        local root =
            character
            and (
                character:FindFirstChild("HumanoidRootPart")
                or character.PrimaryPart
            )

        if not character
            or not humanoid
            or humanoid.Health <= 0
            or not root then
            return nil, nil, nil
        end

        return character, humanoid, root
    end

    local function waitUntil(predicate, timeout, interval)
        local started = os.clock()

        repeat
            local ok, result = pcall(predicate)
            if ok and result then return true end
            task.wait(interval or 0.04)
        until os.clock() - started >= (timeout or 2)

        return false
    end

    local function getObjective()
        local unclimbable =
            workspace:FindFirstChild("Unclimbable")
        local objective =
            unclimbable
            and unclimbable:FindFirstChild("Objective")

        return objective
            and objective:FindFirstChild("Waves")
            or nil
    end

    function W.IsRuntime()
        local waves = workspace:FindFirstChild("Waves")
        return waves ~= nil and getObjective() ~= nil
    end

    function W.GetCratesFolder()
        local waves = workspace:FindFirstChild("Waves")
        return waves and waves:FindFirstChild("Crates") or nil
    end

    function W.GetDropoff()
        local waves = workspace:FindFirstChild("Waves")
        local props = waves and waves:FindFirstChild("Props")
        return props and props:FindFirstChild("Dropoff") or nil
    end

    function W.LiveTitanCount()
        if type(W.Targets) == "function" then return #W.Targets() end
        local titans = workspace:FindFirstChild("Titans")
        if not titans then return 0 end
        local count = 0
        for _, titan in ipairs(titans:GetChildren()) do
            local humanoid = titan:IsA("Model") and titan:FindFirstChildOfClass("Humanoid") or nil
            if humanoid and humanoid.Health > 0 then count += 1 end
        end
        return count
    end

    function W.TitanCenter()
        local folder = titanFolder()
        if not folder then return nil end

        local sum = Vector3.zero
        local count = 0

        for _, titan in ipairs(folder:GetChildren()) do
            if isTitanAlive(titan) then
                local part =
                    titanNape(titan)
                    or titan:FindFirstChild("HumanoidRootPart")
                    or titan.PrimaryPart
                    or titan:FindFirstChildWhichIsA("BasePart", true)

                if part and part.Parent then
                    sum += part.Position
                    count += 1
                end
            end
        end

        return count > 0 and (sum / count) or nil
    end

    function W.CutsceneBusy()
        if W.LiveTitanCount() > 0 then
            return false
        end

        if W.FindReadyGui then
            local target = W.FindReadyGui()
            if target and target.Visible then
                return false
            end
        end

        if App.Cutscene and App.Cutscene.Active == true then
            return true
        end

        local objective = getObjective()

        if objective then
            local countdown =
                tonumber(objective:GetAttribute("Countdown"))
            local show =
                objective:GetAttribute("Show")
            local phase =
                string.lower(
                    tostring(
                        objective:GetAttribute("Phase")
                        or ""
                    )
                )

            if countdown and countdown > 0 then
                return true
            end

            if show == true
                and (
                    phase == "start"
                    or phase == "skip"
                    or phase == "ready"
                ) then
                return true
            end
        end

        return false
    end

    function W.ServerSetupReady()
        local waves = workspace:FindFirstChild("Waves")
        if not waves then
            return false, "Waiting for Workspace.Waves"
        end

        if not getObjective() then
            return false, "Waiting for Waves objective"
        end

        return true, "Waves runtime ready"
    end

    function W.CrateSetupReady()
        local folder = W.GetCratesFolder()
        if not folder or not folder:IsA("Folder") then
            return false, "Waiting for server Waves.Crates"
        end

        if not W.GetDropoff() then
            return false, "Waiting for crate dropoff"
        end

        return true, "Crate system ready"
    end

    function W.IsRoundActive()
        local function resetRound()
            W.RoundActiveSince = nil
            W.RoundLastAlive = nil
            W.RoundLastChangeAt = nil
        end

        if not W.IsRuntime() then
            resetRound()
            return false, "Waiting for Waves runtime"
        end

        local ready, reason = W.ServerSetupReady()
        if not ready then
            resetRound()
            return false, reason
        end

        local alive = W.LiveTitanCount()
        if alive <= 0 then
            resetRound()
            return false, W.CutsceneBusy() and "Wave transition / cutscene" or "Waiting for next wave"
        end

        if W.CutsceneBusy() then
            resetRound()
            return false, "Waiting for cutscene release"
        end

        local now = os.clock()
        if not W.RoundActiveSince then
            W.RoundActiveSince = now
            W.RoundLastChangeAt = now
        elseif W.RoundLastAlive ~= alive then
            W.RoundLastChangeAt = now
        end

        W.RoundLastAlive = alive
        return true, "Wave active • " .. tostring(alive) .. " Titans"
    end

    function W.CaptureHold(force)
        local character, _, root = liveCharacter()

        if not character or not root then
            return nil
        end

        if not force
            and typeof(W.HoldCFrame) == "CFrame" then
            return W.HoldCFrame
        end

        local center = W.TitanCenter()
        local hold = nil

        if center then
            local height = 145
            hold =
                CFrame.lookAt(
                    center + Vector3.new(0, height, 0),
                    center
                )
        else
            local position = root.Position

            if position.Y < 45 then
                position += Vector3.new(0, 125, 0)
            end

            hold =
                CFrame.new(position)
                * (root.CFrame - root.CFrame.Position)
        end

        W.HoldCFrame = hold
        return hold
    end

    function W.HoldCharacter(reason)
        if W.Busy
            or App.Values.WavesAutoFarm ~= true
            or (App.BladeRefill and App.BladeRefill.Busy) then
            return false
        end

        local character, humanoid, root =
            liveCharacter()

        if not character or not root then
            return false
        end

        local hold = W.CaptureHold(false)
        if typeof(hold) ~= "CFrame" then
            return false
        end

        local needsSnap =
            (root.Position - hold.Position).Magnitude > 7
            or root.Position.Y < 30
            or root.AssemblyLinearVelocity.Y < -12

        if needsSnap
            or os.clock() - (W.LastHoldAt or 0) >= 0.14 then

            pcall(function()
                root.Anchored = false
                character:PivotTo(hold)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                humanoid.Sit = false
                humanoid.PlatformStand = false
            end)

            W.LastHoldAt = os.clock()
        end

        if reason then
            W.Status = tostring(reason)
        end

        return true
    end

    local function takeBladeOwnership()
        if not W.OwnsBlades then
            W.PreviousBladeFarm = App.Values.AutoFarmBlades == true
            W.OwnsBlades = true
        end
        App.Values.AutoFarmBlades = false
        stopBladeRuntime()
    end

    function W.ReleaseBladeOwnership()
        if not W.OwnsBlades then
            return
        end

        local restore =
            W.PreviousBladeFarm == true

        W.OwnsBlades = false
        W.PreviousBladeFarm = false
        App.Values.AutoFarmBlades = restore

        if not restore then
            stopBladeRuntime()
        end
    end

    function W.ObserveCombatProgress(alive)
        alive = math.max(0, tonumber(alive) or 0)

        local previous = math.max(0, tonumber(W.LastAliveCount) or 0)
        local now = os.clock()

        if alive > 0 and previous <= 0 then
            W.WaveSerial += 1
            W.HoldCFrame = nil
            W.CaptureHold(true)
            BladeRuntime.NextCycleAt = 0
            CombatSafety.BaseHoldCFrame = nil
            CombatSafety.LastRelocateAt = 0
            W.LastCombatProgressAt = now
            W.MarkProgress("Wave started")
        elseif alive < previous then
            W.LastCombatProgressAt = now
            W.CaptureHold(true)
            W.MarkProgress("Titan defeated")
        elseif alive > 0 and now - (W.LastCombatProgressAt or now) >= 4 then
            BladeRuntime.NextCycleAt = 0
            CombatSafety.BaseHoldCFrame = nil
            W.LastCombatProgressAt = now
            W.Status = "Farming • reacquiring"
        end

        if alive <= 0 and previous > 0 then
            W.CaptureHold(true)
            W.LastCombatProgressAt = now
            W.MarkProgress("Wave cleared")
        end

        W.LastAliveCount = alive
    end


    function W.MarkProgress(reason)
        W.LastProgressAt = os.clock()
        W.LastProgressReason = tostring(reason or "Waves progress")
        if App.Failsafe and App.Values.FailsafeEnabled == true then
            pcall(App.Failsafe.Arm, "Waves progress")
        end
    end

    function W.WavePhase()
        local objective = getObjective()
        if not objective then return nil, nil, nil, nil, nil end
        return objective,
            tostring(objective:GetAttribute("Phase") or ""),
            objective:GetAttribute("Show"),
            tonumber(objective:GetAttribute("Ready")),
            tonumber(objective:GetAttribute("Total"))
    end

    function W.ObservePhaseProgress()
        local objective = getObjective()
        if not objective then return false end

        local parts = {
            tostring(objective:GetAttribute("Phase") or ""),
            tostring(objective:GetAttribute("Show")),
            tostring(objective:GetAttribute("Ready")),
            tostring(objective:GetAttribute("Total")),
            tostring(objective:GetAttribute("Countdown")),
            tostring(objective:GetAttribute("Wave") or objective:GetAttribute("Current") or ""),
            tostring(App.Cutscene and App.Cutscene.Active == true),
        }
        local signature = table.concat(parts, "|")

        if W.LastPhaseSignature ~= signature then
            local previous = W.LastPhaseSignature
            W.LastPhaseSignature = signature
            if previous ~= nil then W.MarkProgress("Waves transition") end
            return true
        end

        return false
    end

    local function exactWavesNape(titan)
        if not titan or not titan:IsA("Model") then return nil end
        local humanoid = titan:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then return nil end
        local hitboxes = titan:FindFirstChild("Hitboxes")
        local hit = hitboxes and hitboxes:FindFirstChild("Hit")
        local nape = hit and hit:FindFirstChild("Nape")
        return nape and nape:IsA("BasePart") and nape.Parent and nape or nil
    end

    local function wavesBossName(value)
        local text = string.lower(tostring(value or ""))
        return string.find(text, "armored", 1, true)
            or string.find(text, "female", 1, true)
            or string.find(text, "colossal", 1, true)
            or string.find(text, "attack", 1, true)
            or string.find(text, "reiner", 1, true)
            or string.find(text, "eren", 1, true)
            or string.find(text, "annie", 1, true)
            or string.find(text, "bertholdt", 1, true)
            or string.find(text, "bertolt", 1, true)
            or string.find(text, "boss", 1, true)
    end

    local function wavesBossTitan(titan)
        if not titan then return false end
        if wavesBossName(titan.Name) then return true end
        local boss, titanType = nil, nil
        pcall(function()
            boss = titan:GetAttribute("Boss")
            titanType = titan:GetAttribute("Type") or titan:GetAttribute("TitanType") or titan:GetAttribute("Variant")
        end)
        return boss == true or wavesBossName(titanType) ~= nil
    end

    function W.Targets()
        local folder = workspace:FindFirstChild("Titans")
        if not folder then return {} end
        local output = {}
        for _, titan in ipairs(folder:GetChildren()) do
            local nape = exactWavesNape(titan)
            if nape then
                output[#output + 1] = {Titan=titan, Nape=nape, Boss=wavesBossTitan(titan)}
            end
        end
        table.sort(output, function(a, b)
            if a.Boss ~= b.Boss then return a.Boss == true end
            return tostring(a.Titan.Name) < tostring(b.Titan.Name)
        end)
        return output
    end

    function W.BladeFill()
        if App.BladeRefill and type(App.BladeRefill.ReadFill) == "function" then
            return App.BladeRefill.ReadFill()
        end
        return nil
    end

    function W.BladeSets()
        if App.BladeRefill and type(App.BladeRefill.ReadSets) == "function" then
            return select(1, App.BladeRefill.ReadSets())
        end
        return nil
    end

    function W.BladeBroken()
        local fill = W.BladeFill()
        return fill ~= nil and fill <= -0.12, fill
    end

    function W.RefillCharges()
        local value = nil
        pcall(function() value = player:GetAttribute("Refills") end)
        return tonumber(value)
    end

    function W.FindRefillStation()
        local direct = workspace:FindFirstChild("Climbable")
        direct = direct and direct:FindFirstChild("_Walls") or nil
        direct = direct and direct:FindFirstChild("Gate") or nil
        direct = direct and direct:FindFirstChild("GasTanks") or nil
        direct = direct and direct:FindFirstChild("Refill") or nil
        if direct and direct:IsA("BasePart") then return direct end
        local best, bestScore = nil, -math.huge
        for _, object in ipairs(workspace:GetDescendants()) do
            if object:IsA("BasePart") then
                local score = string.lower(object.Name) == "refill" and 60 or 0
                local node = object.Parent
                for _ = 1, 8 do
                    if not node then break end
                    local name = string.lower(tostring(node.Name))
                    if string.find(name, "gastank", 1, true) or string.find(name, "gas", 1, true) then score += 18 end
                    if string.find(name, "station", 1, true) or string.find(name, "supply", 1, true) then score += 10 end
                    node = node.Parent
                end
                if score > bestScore then best, bestScore = object, score end
            end
        end
        return best
    end

    function W.ReturnFarm(saved)
        local character, humanoid, root = liveCharacter()
        if not character or not root or typeof(saved) ~= "CFrame" then return false end
        pcall(function()
            character:PivotTo(saved)
            root.Anchored = false
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            humanoid.Sit = false
            humanoid.PlatformStand = false
        end)
        W.HoldCFrame = saved
        CombatSafety.BaseHoldCFrame = saved
        return true
    end

    function W.WaitStationProgress(beforeSets, beforeRefills, seconds)
        local deadline = os.clock() + math.max(0.1, tonumber(seconds) or 0.1)
        local lastSets, lastRefills = W.BladeSets(), W.RefillCharges()
        repeat
            task.wait(0.05)
            lastSets, lastRefills = W.BladeSets(), W.RefillCharges()
            if lastSets ~= nil and lastSets >= 3 then return true, lastSets, lastRefills end
            if beforeSets ~= nil and lastSets ~= nil and lastSets > beforeSets then return true, lastSets, lastRefills end
            if beforeRefills ~= nil and lastRefills ~= nil and lastRefills < beforeRefills then return true, lastSets, lastRefills end
        until os.clock() >= deadline
        return false, lastSets, lastRefills
    end

    function W.InvokeBladeReload()
        local get = select(1, spearRemotes())
        if not get or not get:IsA("RemoteFunction") then return false, nil end
        local ok, response = pcall(function()
            return get:InvokeServer("Blades", "Reload")
        end)
        W.LastBladeReloadAt = os.clock()
        return ok, response
    end

    function W.FinishBladeAfterStation()
        local broken = W.BladeBroken()
        if not broken then return true end
        local sets = W.BladeSets()
        if sets == nil or sets <= 0 then return false end
        W.Status = "Refilling • renewing current blade"
        local beforeSets = sets
        local ok, response = W.InvokeBladeReload()
        local deadline = os.clock() + 2.2
        repeat
            task.wait(0.05)
            if W.BladeBroken() == false then return true end
            local afterSets = W.BladeSets()
            if beforeSets ~= nil and afterSets ~= nil and afterSets < beforeSets and response == true then
                local settle = os.clock() + 1.1
                repeat
                    task.wait(0.05)
                    if W.BladeBroken() == false then return true end
                until os.clock() >= settle
                break
            end
        until os.clock() >= deadline
        return W.BladeBroken() == false
    end

    function W.StationRefill()
        if W.Refilling or App.Values.AutoBladeRefill ~= true then return false end
        local character, humanoid, root = liveCharacter()
        if not character or not root then return false end
        local station = W.FindRefillStation()
        if not station then
            W.Status = "Refilling • station not found"
            W.NextRefillAt = os.clock() + 2.5
            return false
        end
        local charges = W.RefillCharges()
        if charges ~= nil and charges <= 0 then
            W.Status = "Refilling • no charges"
            W.NextRefillAt = os.clock() + 4
            return false
        end
        local get = select(1, spearRemotes())
        if not get or not get:IsA("RemoteFunction") then
            W.Status = "Refilling • waiting"
            W.NextRefillAt = os.clock() + 4
            return false
        end
        W.Refilling = true
        W.Busy = true
        stopBladeRuntime()
        CombatSafety.AttackPauseUntil = os.clock() + 8
        local saved = typeof(W.FarmCFrame) == "CFrame" and W.FarmCFrame or root.CFrame
        local right, forward = station.CFrame.RightVector, station.CFrame.LookVector
        local y = Vector3.new(0, 2.8, 0)
        local spots = {
            station.Position - forward * (station.Size.Z * 0.5 + 1.55) + y,
            station.Position + forward * (station.Size.Z * 0.5 + 1.55) + y,
            station.Position + right * (station.Size.X * 0.5 + 1.55) + y,
            station.Position - right * (station.Size.X * 0.5 + 1.55) + y,
        }
        local success = false
        for index, position in ipairs(spots) do
            if App.Values.WavesAutoFarm ~= true or App.Values.AutoBladeRefill ~= true then break end
            W.Status = "Refilling"
            pcall(function()
                character:PivotTo(CFrame.lookAt(position, station.Position))
                root.Anchored = true
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                humanoid.Sit = false
                humanoid.PlatformStand = false
            end)
            task.wait(0.24)
            local beforeSets, beforeRefills = W.BladeSets(), W.RefillCharges()
            local accepted = false
            for _ = 1, 8 do
                pcall(function() get:InvokeServer("Attacks", "Reload", station) end)
                if select(1, W.WaitStationProgress(beforeSets, beforeRefills, 0.34)) then
                    accepted = true
                    break
                end
                task.wait(0.08)
            end
            if not accepted then
                pcall(function()
                    VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.R, false, game)
                    task.wait(0.35)
                    VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.R, false, game)
                end)
                accepted = select(1, W.WaitStationProgress(beforeSets, beforeRefills, 1.25))
            end
            if accepted then
                local replicated = select(1, W.WaitStationProgress(beforeSets, beforeRefills, 4.5))
                success = replicated or ((W.BladeSets() or 0) > 0)
                break
            end
        end
        pcall(function() if root and root.Parent then root.Anchored = false end end)
        W.ReturnFarm(saved)
        W.LastStationAt = os.clock()
        W.NextRefillAt = os.clock() + (success and 0.8 or 2.5)
        if success then
            local usable = W.FinishBladeAfterStation()
            W.Refilling = false
            W.Busy = false
            if usable then
                local sets = W.BladeSets()
                W.Status = "Refill ready • " .. tostring(sets or "?") .. "/3"
                W.MarkProgress("Waves blade refill")
                return true
            end
            W.Status = "Refill partial • blade renewing"
            return false
        end
        W.Refilling = false
        W.Busy = false
        W.Status = "Refill failed • retrying"
        return false
    end

    function W.RenewBlade()
        if W.Refilling or App.Values.AutoBladeRefill ~= true then return false end
        local broken = W.BladeBroken()
        if not broken then return false end
        local sets = W.BladeSets()
        if sets ~= nil and sets <= 0 then
            if os.clock() >= (W.NextRefillAt or 0) then return W.StationRefill() end
            return false
        end
        if os.clock() - (W.LastBladeReloadAt or 0) < 0.85 then return false end
        W.Status = "Refilling • renewing blade"
        local ok, response = W.InvokeBladeReload()
        if ok then
            local deadline = os.clock() + 1.35
            repeat
                task.wait(0.05)
                if W.BladeBroken() == false then
                    W.Status = "Farming"
                    W.MarkProgress("Waves blade renewal")
                    return true
                end
            until os.clock() >= deadline
        end
        if response == true then W.Status = "Refilling • replication" end
        return false
    end

    function W.HoldAboveTargets(list)
        if W.Refilling or type(list) ~= "table" or #list == 0 then return false end
        local character, humanoid, root = liveCharacter()
        if not character or not root then return false end
        local sum, count, bossCenter = Vector3.zero, 0, nil
        for _, entry in ipairs(list) do
            if entry.Nape and entry.Nape.Parent then
                if entry.Boss then bossCenter = entry.Nape.Position end
                sum += entry.Nape.Position
                count += 1
            end
        end
        if count <= 0 then return false end
        local center = bossCenter or (sum / count)
        local height = bossCenter and 175 or 145
        local hold = CFrame.lookAt(center + Vector3.new(0, height, 0), center)
        W.FarmCFrame = hold
        W.HoldCFrame = hold
        CombatSafety.BaseHoldCFrame = hold
        pcall(function()
            character:PivotTo(hold)
            root.Anchored = false
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            humanoid.Sit = false
            humanoid.PlatformStand = false
        end)
        return true
    end

    function W.AttackTargets(list)
        if W.Refilling or W.Busy or App.Values.WavesAutoFarm ~= true or type(list) ~= "table" or #list == 0 then return 0, 0 end
        local _, post = spearRemotes()
        if not post or not post:IsA("RemoteEvent") then return 0, 0 end
        local total, bossHits, index = 0, 0, 1
        while index <= #list and App.Values.WavesAutoFarm == true and not W.Refilling do
            post:FireServer("Attacks", "Slash", true)
            local last = math.min(#list, index + 9)
            for i = index, last do
                local entry = list[i]
                local repeats = entry.Boss and 5 or 1
                for _ = 1, repeats do
                    local nape = exactWavesNape(entry.Titan)
                    if nape then
                        post:FireServer("Hitboxes", "Register", nape, math.random(625, 850))
                        total += 1
                        if entry.Boss then bossHits += 1 end
                    end
                end
            end
            index = last + 1
            if index <= #list then task.wait(0.015) end
        end
        W.LastAttackAt = os.clock()
        return total, bossHits
    end

    function W.EnsureBladeFarm()
        if not premiumAllowed()
            or App.Values.WavesAutoFarm ~= true
            or not W.IsRuntime()
            or W.Busy
            or W.Refilling
            or os.clock() < (tonumber(W.SuspendFarmUntil) or 0) then
            return false
        end

        takeBladeOwnership()

        if W.CutsceneBusy() then
            W.Status = "Cutscene"
            return false
        end

        if not bladeEquipped() then
            W.Status = "Waiting • equip Blades"
            return false
        end

        if App.Values.AutoBladeRefill == true then
            local broken = W.BladeBroken()
            if broken then
                W.RenewBlade()
                return false
            end
        end

        local roundActive, roundReason = W.IsRoundActive()
        if not roundActive then
            W.Status = tostring(roundReason or "Waiting for wave")
            W.HoldCharacter(W.Status)
            return false
        end

        local list = W.Targets()
        local alive = #list
        W.ObserveCombatProgress(alive)

        if alive <= 0 then
            W.Status = "Waiting"
            W.HoldCharacter("Waiting")
            return false
        end

        W.HoldAboveTargets(list)
        local hits, bossHits = W.AttackTargets(list)
        if hits > 0 then
            W.Status = bossHits > 0 and "Farming • Boss" or "Farming"
        else
            W.Status = "Farming • reacquiring"
        end
        return hits > 0
    end

    local function buttonText(buttonObject)
        local output =
            tostring(buttonObject.Text or "")

        for _, child in ipairs(
            buttonObject:GetDescendants()
        ) do
            if child:IsA("TextLabel")
                or child:IsA("TextButton") then
                output =
                    output
                    .. " "
                    .. tostring(child.Text or "")
            end
        end

        return string.upper(
            string.gsub(output, "%s+", " ")
        )
    end

    function W.FindReadyGui()
        local function eligible(object)
            if not object:IsA("GuiButton")
                or object.Visible ~= true
                or object.AbsoluteSize.X <= 0
                or object.AbsoluteSize.Y <= 0 then
                return false
            end

            local text = buttonText(object)

            return
                string.find(
                    text,
                    "READY",
                    1,
                    true
                ) ~= nil
                or string.find(
                    text,
                    "VOTE SKIP",
                    1,
                    true
                ) ~= nil
                or string.find(
                    text,
                    "SKIP WAVE",
                    1,
                    true
                ) ~= nil
        end

        local interface =
            playerGui:FindFirstChild("Interface")
        local wavesGui =
            interface
            and interface:FindFirstChild("Waves")

        if wavesGui then
            for _, object in ipairs(
                wavesGui:GetDescendants()
            ) do
                if eligible(object) then
                    return object
                end
            end
        end

        for _, object in ipairs(
            playerGui:GetDescendants()
        ) do
            if eligible(object) then
                return object
            end
        end

        return nil
    end

    function W.TryReady()
        if not premiumAllowed()
            or App.Values.WavesAutoSkip ~= true
            or not W.IsRuntime()
            or W.Refilling
            or W.LiveTitanCount() > 0 then
            W.ReadyLocked = false
            W.ReadyPhase = nil
            return false
        end

        local objective, phase, show, ready, total = W.WavePhase()
        if not objective or show ~= true or string.lower(phase) ~= "skip" then
            W.ReadyLocked = false
            W.ReadyPhase = nil
            return false
        end

        local signature = tostring(phase) .. "|" .. tostring(show) .. "|" .. tostring(total)
        if W.ReadyPhase ~= signature then
            W.ReadyPhase = signature
            W.ReadyLocked = false
            W.MarkProgress("Waves READY phase")
        end

        if W.ReadyLocked or os.clock() - (W.LastReadyAttempt or 0) < 0.85 then return false end
        W.LastReadyAttempt = os.clock()
        W.ReadyLocked = true

        local _, post = spearRemotes()
        local sent = false
        if post and post:IsA("RemoteEvent") then
            sent = pcall(function() post:FireServer("Waves", "Update") end)
        end

        if not sent then
            local target = W.FindReadyGui()
            if target then
                local previousSelected = GuiService.SelectedObject
                sent = pcall(function()
                    target.Selectable = true
                    GuiService.SelectedObject = target
                    task.wait()
                    VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
                    task.wait(0.055)
                    VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
                end)
                pcall(function() GuiService.SelectedObject = previousSelected end)
            end
        end

        W.Status = sent and "Waiting • READY sent" or "Waiting • READY retry"
        if not sent then W.ReadyLocked = false return false end

        local beforeReady = ready
        task.spawn(function()
            local deadline = os.clock() + 1.6
            local accepted = false
            repeat
                task.wait(0.05)
                local obj, currentPhase, currentShow, currentReady = W.WavePhase()
                if W.LiveTitanCount() > 0
                    or not obj
                    or currentShow ~= true
                    or string.lower(tostring(currentPhase or "")) ~= "skip"
                    or (beforeReady ~= nil and currentReady ~= nil and currentReady > beforeReady) then
                    accepted = true
                    break
                end
            until os.clock() >= deadline
            if accepted then
                W.Status = "Waiting • READY accepted"
                W.MarkProgress("Waves READY accepted")
            else
                W.ReadyLocked = false
                W.Status = "Waiting • READY retry"
            end
        end)
        return true
    end

    function W.GetPlayerCrate()
        local folder = W.GetCratesFolder()
        if not folder then return nil end

        local exact =
            folder:FindFirstChild(
                "Crate_"
                .. tostring(player.Name)
            )

        return exact
            and exact:IsA("Model")
            and exact
            or nil
    end

    function W.GetCrateHitbox(crate)
        if not crate then return nil end

        local hitbox =
            crate:FindFirstChild("Hitbox")

        if hitbox and hitbox:IsA("BasePart") then
            return hitbox
        end

        return crate:FindFirstChildWhichIsA(
            "BasePart",
            true
        )
    end

    local function moveCharacter(position, look)
        if typeof(position) ~= "Vector3" then
            return false
        end

        local character, humanoid, root =
            liveCharacter()

        if not character then
            return false
        end

        look =
            typeof(look) == "Vector3"
            and look
            or position + Vector3.new(0, 0, -1)

        if (look - position).Magnitude < 0.05 then
            look =
                position + Vector3.new(0, 0, -1)
        end

        pcall(function()
            root.Anchored = false
            character:PivotTo(
                CFrame.lookAt(position, look)
            )
            root.AssemblyLinearVelocity =
                Vector3.zero
            root.AssemblyAngularVelocity =
                Vector3.zero
            humanoid.Sit = false
            humanoid.PlatformStand = false
        end)

        return true
    end

    function W.Pickup(crate)
        if not crate or not crate.Parent then
            return false, "crate missing"
        end

        if crate:GetAttribute("Occupied") == true then
            return true, "already occupied"
        end

        local hitbox = W.GetCrateHitbox(crate)
        if not hitbox then
            return false, "crate hitbox missing"
        end

        for _ = 1, 6 do
            if not crate.Parent then
                return false, "crate removed"
            end

            if crate:GetAttribute("Occupied") == true then
                return true, "picked up"
            end

            local position =
                hitbox.Position
                + Vector3.new(0, 0.45, 0)

            moveCharacter(
                position,
                hitbox.Position
            )

            local _, _, root = liveCharacter()
            local env =
                type(getgenv) == "function"
                and getgenv()
                or _G

            local touch =
                env
                and env.firetouchinterest
                or nil

            if root and type(touch) == "function" then
                pcall(function()
                    touch(root, hitbox, 0)
                    task.wait(0.03)
                    touch(root, hitbox, 1)
                end)
            end

            if waitUntil(
                function()
                    return not crate.Parent
                        or crate:GetAttribute("Occupied") == true
                end,
                0.48,
                0.025
            ) then
                return
                    crate.Parent ~= nil,
                    crate.Parent
                    and "picked up"
                    or "crate removed"
            end
        end

        return
            crate:GetAttribute("Occupied") == true,
            "pickup timeout"
    end

    function W.DropoffTargets(dropoff)
        local output = {}
        local pivot = dropoff:GetPivot()
        local center = pivot.Position

        output[#output + 1] =
            center + Vector3.new(-10, 4, 2)
        output[#output + 1] =
            center + Vector3.new(-14, 4, 0)
        output[#output + 1] =
            center + Vector3.new(-7, 4, 6)
        output[#output + 1] =
            center + Vector3.new(0, 4, 0)
        output[#output + 1] =
            (pivot * CFrame.new(-10, 4, 2)).Position
        output[#output + 1] =
            (pivot * CFrame.new(-14, 4, 0)).Position

        return output, center
    end

    function W.Deliver(crate)
        if not crate or not crate.Parent then
            return true, "already removed"
        end

        if crate:GetAttribute("Occupied") ~= true then
            return false, "crate not occupied"
        end

        local dropoff = W.GetDropoff()
        if not dropoff then
            return false, "dropoff missing"
        end

        local targets, center =
            W.DropoffTargets(dropoff)

        for _, position in ipairs(targets) do
            if not crate.Parent then
                return true, "delivered"
            end

            moveCharacter(position, center)

            if waitUntil(
                function()
                    local folder =
                        W.GetCratesFolder()

                    return not crate.Parent
                        or not crate:IsDescendantOf(workspace)
                        or (
                            folder
                            and not crate:IsDescendantOf(folder)
                        )
                end,
                0.60,
                0.025
            ) then
                return true, "delivered"
            end
        end

        return
            not crate.Parent,
            crate.Parent
            and "dropoff timeout"
            or "delivered"
    end

    function W.ProcessCrate(crate)
        if W.Busy
            or App.Values.WavesAutoCrates ~= true
            or not W.IsRuntime()
            or not crate
            or not crate.Parent then
            return false
        end

        local active, reason =
            W.IsRoundActive()

        if not active then
            W.Status =
                tostring(reason or "Waiting for wave")
                .. " • crates paused"
            return false
        end

        W.Busy = true
        W.CurrentCrate = crate

        local shouldResume =
            W.OwnsBlades
            and App.Values.WavesAutoFarm == true

        App.Values.AutoFarmBlades = false
        stopBladeRuntime()

        task.spawn(function()
            local success = false
            local message = "crate action finished"

            local ok, err = pcall(function()
                if crate:GetAttribute("Occupied") ~= true then
                    W.Status = "Picking up supply crate"
                    local picked, why =
                        W.Pickup(crate)

                    if not picked then
                        message =
                            "Crate pickup failed • "
                            .. tostring(why)
                        return
                    end
                end

                if crate.Parent
                    and crate:GetAttribute("Occupied") == true then

                    W.Status = "Delivering supply crate"
                    success, message =
                        W.Deliver(crate)
                else
                    success = true
                    message = "Crate removed"
                end
            end)

            if not ok then
                message =
                    "Crate error • "
                    .. tostring(err)
            end

            W.Busy = false
            W.CurrentCrate = nil
            W.HoldCFrame = nil

            if shouldResume then
                local roundActive =
                    select(1, W.IsRoundActive())

                App.Values.AutoFarmBlades =
                    roundActive == true
            end

            W.Status = tostring(message)

            if success then
                W.MarkProgress("Supply delivered")
            else
                W.LastCrateAttempt = os.clock() + 0.8
            end
        end)

        return true
    end

    local function upgradeRemote()
        local assets =
            ReplicatedStorage:FindFirstChild("Assets")
        local remotes =
            assets
            and assets:FindFirstChild("Remotes")
        local get =
            remotes
            and remotes:FindFirstChild("GET")

        return get
            and get:IsA("RemoteFunction")
            and get
            or nil
    end

    local function normalizeGearTarget(value)
        value = tostring(value or "Both")

        if value == "Blades"
            or value == "Thunder Spears"
            then
            return value
        end

        return "Both"
    end

    local function gearTargetForPass()
        local selected =
            normalizeGearTarget(
                App.Values.WavesGearTarget
            )

        App.Values.WavesGearTarget = selected

        if selected == "Blades" then
            return "Blades"
        end

        if selected == "Thunder Spears" then
            return "Spears"
        end

        W.GearBothIndex =
            (W.GearBothIndex or 0) + 1

        return
            W.GearBothIndex % 2 == 1
            and "Blades"
            or "Spears"
    end

    function W.RunGearUpgrade()
        local get = upgradeRemote()

        if not get then
            W.GearNextAt = os.clock() + 12
            W.UpgradeStatus =
                "Gear waiting"
            return
        end

        local weapon = gearTargetForPass()
        local keys = W.GearKeys[weapon]

        if type(keys) ~= "table" then
            W.GearNextAt = os.clock() + 12
            return
        end

        W.UpgradeStatus =
            "Upgrading Gear • "
            .. (
                weapon == "Spears"
                and "Thunder Spears"
                or "Blades"
            )

        local ok, profile, detail = pcall(function()
            return get:InvokeServer(
                "Equipment",
                "Upgrade",
                keys
            )
        end)

        if not ok then
            W.GearNoProgress =
                math.min(
                    6,
                    (W.GearNoProgress or 0) + 1
                )

            W.GearNextAt =
                os.clock()
                + math.min(
                    24,
                    4 + W.GearNoProgress * 3
                )

            W.UpgradeStatus =
                "Gear waiting"
            return
        end

        local changed = false

        if type(detail) == "table" then
            for key, value in pairs(detail) do
                if key ~= "Gold"
                    and (
                        tonumber(value) ~= nil
                        or type(value) == "table"
                    ) then
                    changed = true
                    break
                end
            end
        end

        if type(profile) == "table" then
            changed = changed or next(profile) ~= nil
        end

        if changed then
            W.GearNoProgress = 0
            W.GearNextAt = os.clock() + 1.25
            W.UpgradeStatus =
                (
                    weapon == "Spears"
                    and "Thunder Spears"
                    or "Blades"
                )
                .. " upgrade accepted"
        else
            W.GearNoProgress =
                math.min(
                    6,
                    (W.GearNoProgress or 0) + 1
                )

            W.GearNextAt =
                os.clock()
                + math.min(
                    24,
                    4 + W.GearNoProgress * 3
                )

            W.UpgradeStatus =
                "Gear waiting"
        end
    end

    local function hqEnabled(key)
        local map = {
            Max = App.Values.WavesHQMax ~= false,
            Regen = App.Values.WavesHQRegen ~= false,
            Refills = App.Values.WavesHQRefills ~= false,
            Replenish = App.Values.WavesHQReplenish ~= false,
            Revive = App.Values.WavesHQRevive == true,
        }

        return map[key] == true
    end

    function W.ControllerGold(force)
        local get = upgradeRemote()
        local now = os.clock()
        if not force and W.StatsCacheAt and now - W.StatsCacheAt < 0.75 and type(W.StatsCache) == "table" then
            return tonumber(W.StatsCache.Gold), W.StatsCache
        end
        if get then
            local ok, result = pcall(function()
                return get:InvokeServer("Stats", "Get")
            end)
            if ok and type(result) == "table" then
                W.StatsCache = result
                W.StatsCacheAt = now
                return tonumber(result.Gold), result
            end
        end
        return type(W.StatsCache) == "table" and tonumber(W.StatsCache.Gold) or nil, W.StatsCache
    end

    function W.HQUpgradeObject(key)
        local waves = workspace:FindFirstChild("Waves")
        if not waves then return nil end
        local upgrades = waves:FindFirstChild("Upgrades")
        if not upgrades then
            for _, object in ipairs(waves:GetDescendants()) do
                if object.Name == "Upgrades" then upgrades = object break end
            end
        end
        return upgrades and upgrades:FindFirstChild(key) or nil
    end

    function W.HQSnapshot(key)
        local gold = W.ControllerGold(false)
        local data = {Gold=gold, Refills=W.RefillCharges()}
        local objective = getObjective()
        local health = objective and objective:FindFirstChild("Health")
        if health and health:IsA("ValueBase") then
            data.Health = tonumber(health.Value)
            data.MaxHealth = tonumber(health:GetAttribute("Max_Health"))
        end
        local object = W.HQUpgradeObject(key)
        if typeof(object) == "Instance" then
            pcall(function()
                data.Cost = tonumber(object:GetAttribute("Cost"))
                data.Increase = tonumber(object:GetAttribute("Increase"))
                if object:IsA("ValueBase") then data.Value = tonumber(object.Value) end
            end)
        end
        return data
    end

    function W.HQChanged(before, after, key)
        if not before or not after then return false end
        if before.Gold and after.Gold and after.Gold < before.Gold then return true end
        if before.Cost and after.Cost and after.Cost ~= before.Cost then return true end
        if before.Value and after.Value and after.Value ~= before.Value then return true end
        if key == "Replenish" and before.Health and after.Health and after.Health > before.Health then return true end
        if key == "Refills" and before.Refills and after.Refills and after.Refills > before.Refills then return true end
        if before.MaxHealth and after.MaxHealth and after.MaxHealth > before.MaxHealth then return true end
        return false
    end

    function W.RunHQUpgrade()
        local get = upgradeRemote()
        if not get then
            W.HQNextAt = os.clock() + 12
            W.UpgradeStatus = "HQ waiting"
            return
        end

        local count = #W.HQKeys
        local key = nil
        local now = os.clock()

        for _ = 1, count do
            W.HQIndex = ((W.HQIndex or 0) % count) + 1
            local candidate = W.HQKeys[W.HQIndex]
            if hqEnabled(candidate) and now >= (tonumber(W.HQNextByKey[candidate]) or 0) then
                key = candidate
                break
            end
        end

        if not key then
            W.HQNextAt = now + 0.8
            return
        end

        local before = W.HQSnapshot(key)
        if before.Cost and before.Gold and before.Gold < before.Cost then
            W.HQNextByKey[key] = now + 4
            W.HQNextAt = now + 0.8
            W.UpgradeStatus = "HQ waiting"
            return
        end

        W.Status = "Upgrading HQ"
        W.UpgradeStatus = "HQ • " .. tostring(key)
        local ok, response = pcall(function()
            return get:InvokeServer("Waves", "Upgrade", {key})
        end)
        task.wait(0.18)
        W.StatsCacheAt = 0
        local after = W.HQSnapshot(key)
        local changed = W.HQChanged(before, after, key)

        if ok and (changed or response ~= false) then
            W.HQNoProgress[key] = 0
            W.HQNextByKey[key] = os.clock() + 2.2
            W.HQNextAt = os.clock() + 1.1
            W.UpgradeStatus = changed and ("HQ " .. tostring(key) .. " upgraded") or ("HQ " .. tostring(key) .. " accepted")
            if changed then W.MarkProgress("HQ upgraded") end
        else
            local misses = math.min(5, (tonumber(W.HQNoProgress[key]) or 0) + 1)
            W.HQNoProgress[key] = misses
            local delay = math.min(24, 3 + misses * 4)
            W.HQNextByKey[key] = os.clock() + delay
            W.HQNextAt = os.clock() + 1
            W.UpgradeStatus = "HQ waiting"
        end
    end

    function W.TickUpgrades()
        if App.Values.WavesAutoUpgrade ~= true then
            W.UpgradeStatus = "Upgrades idle"
            return false
        end

        local gear =
            App.Values.WavesUpgradeGear == true
        local hq =
            App.Values.WavesUpgradeHQ == true

        if not gear and not hq then
            W.UpgradeStatus =
                "Auto Upgrade armed • choose Gear or HQ"
            return false
        end

        if W.UpgradeBusy or W.Busy then
            return false
        end

        if W.CutsceneBusy() then
            W.UpgradeStatus =
                "Paused during wave transition"
            return false
        end

        local now = os.clock()
        local gearDue =
            gear
            and now >= (W.GearNextAt or 0)
        local hqDue =
            hq
            and now >= (W.HQNextAt or 0)

        if not gearDue and not hqDue then
            return false
        end

        local kind

        if gearDue and hqDue then
            kind =
                W.UpgradeTurn == "Gear"
                and "Gear"
                or "HQ"
        elseif gearDue then
            kind = "Gear"
        else
            kind = "HQ"
        end

        W.UpgradeTurn =
            kind == "Gear"
            and "HQ"
            or "Gear"

        W.UpgradeBusy = true

        task.spawn(function()
            local ok, err = pcall(function()
                if kind == "Gear" then
                    W.RunGearUpgrade()
                else
                    W.RunHQUpgrade()
                end
            end)

            if not ok then
                W.UpgradeStatus =
                    kind
                    .. " error • "
                    .. string.sub(
                        tostring(err),
                        1,
                        90
                    )
            end

            W.UpgradeBusy = false
        end)

        return true
    end

