    local function uiTween(object,duration,properties,style,direction)
        if not object or not object.Parent then return nil end
        local tween=TweenService:Create(object,TweenInfo.new(duration or 0.14,style or Enum.EasingStyle.Quad,direction or Enum.EasingDirection.Out),properties)
        tween:Play()
        return tween
    end

    local function attachMotion(button,baseTransparency,hoverTransparency)
        if not button or not button:IsA("GuiButton") then return end
        button.AutoButtonColor=false
        local scale=button:FindFirstChild("SliceMotionScale")
        if not scale then
            scale=Instance.new("UIScale")
            scale.Name="SliceMotionScale"
            scale.Scale=1
            scale.Parent=button
        end
        local base=tonumber(baseTransparency) or button.BackgroundTransparency
        local hover=tonumber(hoverTransparency) or math.max(0,base-0.08)
        button.MouseEnter:Connect(function() uiTween(button,0.12,{BackgroundTransparency=hover}) uiTween(scale,0.12,{Scale=1.018}) end)
        button.MouseLeave:Connect(function() uiTween(button,0.14,{BackgroundTransparency=base}) uiTween(scale,0.14,{Scale=1}) end)
        button.InputBegan:Connect(function(input)
            if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                uiTween(scale,0.075,{Scale=0.972},Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
            end
        end)
        button.InputEnded:Connect(function(input)
            if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                uiTween(scale,0.12,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            end
        end)
    end

