    end

local function formatNumber(value)
    local n=math.floor((tonumber(value) or 0)+0.5)
    local sign=n<0 and "-" or ""
    local text=tostring(math.abs(n))
    while true do
        local changed
        text,changed=text:gsub("^(%d+)(%d%d%d)", "%1,%2")
        if changed==0 then break end
    end
    return sign..text
end

local statsCache=nil
local statsCacheAt=0

local function fetchStats(force)
    local now=os.clock()
    if not force and type(statsCache)=="table" and now-statsCacheAt<0.75 then
        return statsCache
    end
    if not GET or not GET:IsA("RemoteFunction") then return statsCache end
    local ok,result=pcall(function()
        return GET:InvokeServer("Stats","Get")
    end)
    if ok and type(result)=="table" then
        statsCache=result
        statsCacheAt=now
        return result
    end
    return statsCache
end

local function controllerGold()
    local stats=fetchStats(false)
    if type(stats)=="table" then
        return tonumber(stats.Gold)
    end
    local pg=playerGui
    local interface=pg and pg:FindFirstChild("Interface")
    if interface then
        for _,rootName in ipairs({"Market","Blessing"}) do
            local root=interface:FindFirstChild(rootName)
            if root then
                for _,obj in ipairs(root:GetDescendants()) do
                    if obj:IsA("TextLabel") then
                        local name=string.lower(obj.Name)
                        local path=string.lower(obj:GetFullName())
                        if name=="gold" or path:find(".gold.",1,true) or path:find(".gold",1,true) then
                            local raw=tostring(obj.Text or ""):gsub(",","")
                            local n=tonumber(raw:match("%-?%d+"))
                            if n then return n end
                        end
                    end
                end
            end
        end
    end
    return nil
end

local function wavesDataFolder(name)
    local waves=workspace:FindFirstChild("Waves")
    if not waves then return nil end
    local direct=waves:FindFirstChild(name)
    if direct then return direct end
    for _,obj in ipairs(waves:GetDescendants()) do
        if obj.Name==name then
            if name~="Items" then return obj end
            if obj:FindFirstChild("Perks") or obj:FindFirstChild("Artifacts")
                or obj:FindFirstChild("Memories") or obj:FindFirstChild("Shifting") then
                return obj
            end
        end
    end
    return nil
end

local function hqUpgradeObject(key)
    local upgrades=wavesDataFolder("Upgrades")
    return upgrades and upgrades:FindFirstChild(key) or nil
end

