local function raiseAuxGui(root,baseZ)
    if not root then return end
    baseZ=tonumber(baseZ) or 22
    local function depthFromRoot(obj)
        local depth=0
        local current=obj.Parent
        while current and current~=root do
            depth+=1
            current=current.Parent
        end
        return depth
    end
    for _,obj in ipairs(root:GetDescendants()) do
        if obj:IsA("GuiObject") then
            obj.ZIndex=baseZ+math.min(depthFromRoot(obj),6)
        end
    end
end

local function makeAuxDraggable(frameObject,handle)
    local dragging=false
    local startInput=nil
    local startPosition=nil
    W.Connections[#W.Connections+1]=handle.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            dragging=true
            startInput=input.Position
            startPosition=frameObject.Position
        end
    end)
    W.Connections[#W.Connections+1]=handle.InputEnded:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            dragging=false
        end
    end)
    W.Connections[#W.Connections+1]=UserInputService.InputChanged:Connect(function(input)
        if not dragging or not startInput or not startPosition then return end
        if input.UserInputType~=Enum.UserInputType.MouseMovement and input.UserInputType~=Enum.UserInputType.Touch then return end
        local delta=input.Position-startInput
        frameObject.Position=UDim2.new(
            startPosition.X.Scale,
            startPosition.X.Offset+delta.X,
            startPosition.Y.Scale,
            startPosition.Y.Offset+delta.Y
        )
    end)
end

