local function createAuxPanel(key,titleText,width,height,position)
    local existing=W.AuxPanels[key]
    if existing and existing.Frame and existing.Frame.Parent then
        existing.Frame.Visible=true
        local existingScale=existing.Frame:FindFirstChild("SlicePanelScale")
        if existingScale then
            existingScale.Scale=0.955
            uiTween(existingScale,0.20,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
        end
        return existing
    end
    if not W.Gui or not W.Gui.Parent then return nil end
    local frameObject=Instance.new("Frame")
    frameObject.Name="SliceHub"..key.."Clone"
    frameObject.Size=UDim2.fromOffset(width,height)
    frameObject.Position=position
    frameObject.BackgroundColor3=UITheme.Main
    frameObject.BackgroundTransparency=0.12
    frameObject.BorderSizePixel=0
    frameObject.ZIndex=20
    auxRound(frameObject,11)
    auxStroke(frameObject,0.34)
    addGlassGradient(frameObject)
    frameObject.Parent=W.Gui
    local panelScale=Instance.new("UIScale")
    panelScale.Name="SlicePanelScale"
    panelScale.Scale=0.955
    panelScale.Parent=frameObject

    local header=Instance.new("Frame")
    header.BackgroundColor3=UITheme.Header
    header.BackgroundTransparency=0.16
    header.BorderSizePixel=0
    header.Size=UDim2.new(1,0,0,42)
    header.ZIndex=21
    auxRound(header,11)
    header.Parent=frameObject

    local mask=Instance.new("Frame")
    mask.BackgroundColor3=header.BackgroundColor3
    mask.BackgroundTransparency=header.BackgroundTransparency
    mask.BorderSizePixel=0
    mask.Position=UDim2.new(0,0,1,-11)
    mask.Size=UDim2.new(1,0,0,11)
    mask.ZIndex=21
    mask.Parent=header

    local title=auxLabel(header,titleText,UDim2.fromOffset(13,0),UDim2.new(1,-94,1,0),12,Enum.Font.GothamBold)
    title.ZIndex=22

    local collapse=auxButton(header,"—",UDim2.new(1,-69,0,7),UDim2.fromOffset(27,27))
    collapse.ZIndex=22
    local close=auxButton(header,"X",UDim2.new(1,-36,0,7),UDim2.fromOffset(27,27))
    close.BackgroundColor3=UITheme.Danger
    close.ZIndex=22

    local body=Instance.new("Frame")
    body.BackgroundTransparency=1
    body.Position=UDim2.fromOffset(0,42)
    body.Size=UDim2.new(1,0,1,-42)
    body.ZIndex=21
    body.Parent=frameObject

    local expandedHeight=height
    local collapsed=false
    collapse.Activated:Connect(function()
        collapsed=not collapsed
        collapse.Text=collapsed and "+" or "—"
        if not collapsed then body.Visible=true end
        uiTween(
            frameObject,
            0.18,
            {Size=collapsed and UDim2.fromOffset(width,42) or UDim2.fromOffset(width,expandedHeight)},
            Enum.EasingStyle.Quint,
            collapsed and Enum.EasingDirection.In or Enum.EasingDirection.Out
        )
        if collapsed then
            task.delay(0.18,function()
                if collapsed and body and body.Parent then body.Visible=false end
            end)
        end
    end)
    close.Activated:Connect(function()
        uiTween(panelScale,0.14,{Scale=0.955},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
        task.delay(0.145,function()
            if frameObject and frameObject.Parent then
                frameObject.Visible=false
                panelScale.Scale=1
            end
        end)
    end)
    makeAuxDraggable(frameObject,header)
    uiTween(panelScale,0.22,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)

    local panel={
        Frame=frameObject,
        Header=header,
        Body=body,
        Title=title
    }
    W.AuxPanels[key]=panel
    return panel
end

local function waveToast(titleText,detailText,kind)
    if not W.Gui or not W.Gui.Parent then return end
    local host=W.ToastHost
    if not host or not host.Parent then
        host=Instance.new("Frame")
        host.Name="SliceHubWavesToasts"
        host.BackgroundTransparency=1
        host.AnchorPoint=Vector2.new(0.5,0)
        host.Position=UDim2.new(0.5,0,0,18)
        host.Size=UDim2.fromOffset(350,260)
        host.ZIndex=70
        host.Parent=W.Gui
        local layout=Instance.new("UIListLayout")
        layout.Padding=UDim.new(0,6)
        layout.HorizontalAlignment=Enum.HorizontalAlignment.Center
        layout.VerticalAlignment=Enum.VerticalAlignment.Top
        layout.SortOrder=Enum.SortOrder.LayoutOrder
        layout.Parent=host
        W.ToastHost=host
    end
    local liveToasts={}
    for _,child in ipairs(host:GetChildren()) do
        if child:IsA("Frame") then liveToasts[#liveToasts+1]=child end
    end
    if #liveToasts>=4 then
        liveToasts[1]:Destroy()
    end
    local card=Instance.new("Frame")
    card.Size=UDim2.new(1,0,0,58)
    card.BackgroundColor3=kind=="error"
        and UITheme.Danger
        or kind=="reward"
        and UITheme.Reward
        or UITheme.Surface
    card.BackgroundTransparency=0.12
    card.BorderSizePixel=0
    card.ZIndex=71
    auxRound(card,9)
    auxStroke(card,0.38)
    card.Parent=host
    local toastScale=Instance.new("UIScale")
    toastScale.Scale=0.92
    toastScale.Parent=card
    uiTween(toastScale,0.20,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
    local title=auxLabel(card,string.upper(tostring(titleText or "")),UDim2.fromOffset(11,6),UDim2.new(1,-22,0,20),10,Enum.Font.GothamBold)
    title.ZIndex=72
    local detail=auxLabel(card,tostring(detailText or ""),UDim2.fromOffset(11,27),UDim2.new(1,-22,0,22),9,Enum.Font.Gotham)
    detail.TextColor3=Color3.fromRGB(171,181,199)
    detail.TextTruncate=Enum.TextTruncate.AtEnd
    detail.ZIndex=72
    task.delay(3.15,function()
        if not card or not card.Parent then return end
        uiTween(toastScale,0.18,{Scale=0.94},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
        uiTween(card,0.18,{BackgroundTransparency=1},Enum.EasingStyle.Quad,Enum.EasingDirection.In)
        uiTween(title,0.16,{TextTransparency=1},Enum.EasingStyle.Quad,Enum.EasingDirection.In)
        uiTween(detail,0.16,{TextTransparency=1},Enum.EasingStyle.Quad,Enum.EasingDirection.In)
        task.delay(0.19,function()
            if card and card.Parent then card:Destroy() end
        end)
    end)
end

local function rewardSingular(category)
    local map={
        Perks="PERK",
        Artifacts="ARTIFACT",
        Memories="MEMORY",
        Shifting="ITEM",
        Blessings="BLESSING"
    }
    return map[tostring(category)] or string.upper(tostring(category or "ITEM"))
end

local function rewardDescription(value)
    if type(value)~="table" then return tostring(value or "Unknown") end
    local tag=value.Real_Tag or value.Tag or value.Name or value.Item or value.ID or "Unknown"
    local parts={tostring(tag)}
    if value.Rarity~=nil and tostring(value.Rarity)~="" then
        parts[#parts+1]=tostring(value.Rarity)
    end
    if value.Level~=nil then
        parts[#parts+1]="+"..tostring(value.Level)
    elseif value.Quantity~=nil and tonumber(value.Quantity) and tonumber(value.Quantity)>1 then
        parts[#parts+1]="x"..tostring(value.Quantity)
    end
    return table.concat(parts," • ")
end

local function announceMarketRewards(entry,rewardData,amount)
    local tag=tostring(entry and entry.Tag or "Market Item")
    local crate=string.lower(tag):find("crate",1,true)~=nil
    local rewards={}
    if type(rewardData)=="table" then
        for _,value in pairs(rewardData) do
            if type(value)=="table" then rewards[#rewards+1]=value end
        end
    end
    if crate or #rewards>1 then
        waveToast("CHEST OPENED",tag.." ×"..tostring(amount or 1),"reward")
    else
        waveToast("PURCHASED",tag.." ×"..tostring(amount or 1),"success")
    end
    local prefix=rewardSingular(entry and entry.Category)
    for index,value in ipairs(rewards) do
        task.delay(math.min(0.2*index,0.8),function()
            waveToast(prefix.." DROPPED",rewardDescription(value),"reward")
        end)
    end
end

local function nativeMarketTags()
    local map={}
    local pg=playerGui
    local interface=pg and pg:FindFirstChild("Interface")
    local market=interface and interface:FindFirstChild("Market")
    if not market then return map end
    for _,obj in ipairs(market:GetDescendants()) do
        if obj:IsA("GuiObject") then
            local id=obj:GetAttribute("ID")
            if id~=nil then
                local tag=obj:GetAttribute("Tag")
                if tag~=nil then map[tostring(id)]=tostring(tag) end
                local inner=obj:FindFirstChild("Inner")
                local item=inner and inner:FindFirstChild("Item")
                if item and item:IsA("TextLabel") and tostring(item.Text or "")~="" then
                    map[tostring(id)]=tostring(item.Text)
                end
            end
        end
    end
    return map
end

local function marketItemInfo(category,item,tagMap)
    local id=item:GetAttribute("ID")
    local value=nil
    pcall(function() value=item.Value end)
    local tag=id~=nil and tagMap[tostring(id)] or nil
    if tag==nil or tag=="" then tag=tostring(value or item.Name) end
    local stock=tonumber(item:GetAttribute("Stock")) or 0
    local maxStock=tonumber(item:GetAttribute("Max_Stock")) or stock
    local price=tonumber(item:GetAttribute("Price")) or 0
    local rarity=tostring(item:GetAttribute("Rarity") or "")
    local locked=item:GetAttribute("Locked")
    return {
        Instance=item,
        Category=category,
        ID=id,
        Tag=tag,
        Stock=stock,
        MaxStock=maxStock,
        Price=price,
        Rarity=rarity,
        Locked=locked
    }
end

