local function marketSignatureFor(category)
    local parts={tostring(category),tostring(controllerGold() or "?")}
    local itemsRoot=wavesDataFolder("Items")
    local root=itemsRoot and itemsRoot:FindFirstChild(category)
    if root then
        local entries={}
        for _,item in ipairs(root:GetChildren()) do
            local id=item:GetAttribute("ID")
            if id~=nil then
                entries[#entries+1]=table.concat({
                    tostring(id),
                    tostring(item:GetAttribute("Stock")),
                    tostring(item:GetAttribute("Max_Stock")),
                    tostring(item:GetAttribute("Price")),
                    tostring(item:GetAttribute("Rarity")),
                    tostring(item:GetAttribute("Locked"))
                },"|")
            end
        end
        table.sort(entries)
        for _,value in ipairs(entries) do parts[#parts+1]=value end
    end
    return table.concat(parts,";")
end

