    local refreshButton=auxButton(body,"↻",UDim2.new(1,-45,0,5),UDim2.fromOffset(33,27))
    refreshButton.TextSize=14

    local qtyBox=Instance.new("Frame")
    qtyBox.BackgroundColor3=UITheme.Surface
    qtyBox.BackgroundTransparency=0.20
    qtyBox.BorderSizePixel=0
    qtyBox.Position=UDim2.fromOffset(10,37)
    qtyBox.Size=UDim2.new(1,-20,0,34)
    auxRound(qtyBox,7)
    qtyBox.Parent=body

    local qtyTitle=auxLabel(qtyBox,"BUY QUANTITY",UDim2.fromOffset(10,0),UDim2.new(1,-140,1,0),8,Enum.Font.GothamBold)
    qtyTitle.TextColor3=Color3.fromRGB(146,157,177)
    local qtyMinus=auxButton(qtyBox,"-",UDim2.new(1,-120,0,4),UDim2.fromOffset(28,26))
    local qtyValue=auxLabel(qtyBox,tostring(state.Quantity or 1),UDim2.new(1,-87,0,4),UDim2.fromOffset(40,26),10,Enum.Font.GothamBold)
    qtyValue.TextXAlignment=Enum.TextXAlignment.Center
    local qtyPlus=auxButton(qtyBox,"+",UDim2.new(1,-42,0,4),UDim2.fromOffset(28,26))

    local tabs=Instance.new("Frame")
    tabs.BackgroundTransparency=1
    tabs.Position=UDim2.fromOffset(10,78)
    tabs.Size=UDim2.new(1,-20,0,30)
    tabs.Parent=body

    local categories={"Perks","Artifacts","Memories","Shifting"}
    local tabButtons={}
    for index,category in ipairs(categories) do
