        local b=auxButton(
            tabs,
            string.upper(category),
            UDim2.new((index-1)*width,2,0,0),
            UDim2.new(width,-4,1,0)
        )
        b.TextSize=8
        tabButtons[category]=b
    end

    local status=auxLabel(
        body,
        "",
        UDim2.fromOffset(12,111),
        UDim2.new(1,-24,0,24),
