        Enum.Font.GothamMedium
    )
    status.TextColor3=Color3.fromRGB(151,162,184)

    local scroll=Instance.new("ScrollingFrame")
    scroll.Position=UDim2.fromOffset(10,138)
    scroll.Size=UDim2.new(1,-20,1,-148)
    scroll.BackgroundTransparency=1
    scroll.BorderSizePixel=0
    scroll.ScrollBarThickness=3
    scroll.AutomaticCanvasSize=Enum.AutomaticSize.Y
    scroll.CanvasSize=UDim2.new()
    scroll.Parent=body
    state.ScrollObject=scroll

    local layout=Instance.new("UIListLayout")
    layout.Padding=UDim.new(0,5)
    layout.SortOrder=Enum.SortOrder.LayoutOrder
    layout.Parent=scroll

    scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
        state.ScrollY=scroll.CanvasPosition.Y
    end)

    local function colorTabs()
        for category,b in pairs(tabButtons) do
            b.BackgroundColor3=category==state.Category
                and Color3.fromRGB(51,67,94)
                or Color3.fromRGB(35,39,49)
        end
    end

    local itemsRoot=wavesDataFolder("Items")
    local categoryRoot=itemsRoot and itemsRoot:FindFirstChild(state.Category)
    colorTabs()

    if not categoryRoot then
        status.Text="Waiting for live "..state.Category.." stock..."
    else
        local tags=nativeMarketTags()
        local entries={}
        for _,item in ipairs(categoryRoot:GetChildren()) do
            if item:GetAttribute("ID")~=nil then
                entries[#entries+1]=marketItemInfo(state.Category,item,tags)
            end
        end
        table.sort(entries,function(a,b)
            if (a.Stock>0)~=(b.Stock>0) then return a.Stock>0 end
            if a.Rarity~=b.Rarity then return tostring(a.Rarity)<tostring(b.Rarity) end
            return string.lower(a.Tag)<string.lower(b.Tag)
        end)

        status.Text=tostring(#entries).." live items • updates automatically"

        for _,entry in ipairs(entries) do
            local row=Instance.new("Frame")
            row.Size=UDim2.new(1,-4,0,54)
            row.BackgroundColor3=UITheme.Surface
            row.BackgroundTransparency=0.18
            row.BorderSizePixel=0
            auxRound(row,8)
            row.Parent=scroll

            local title=auxLabel(
                row,
                string.upper(entry.Tag),
                UDim2.fromOffset(10,5),
                UDim2.new(1,-108,0,19),
                9,
                Enum.Font.GothamBold
            )
            title.TextTruncate=Enum.TextTruncate.AtEnd

            local metaParts={}
            if entry.Rarity~="" then metaParts[#metaParts+1]=entry.Rarity end
            metaParts[#metaParts+1]=tostring(entry.Stock).."/"..tostring(entry.MaxStock)
            metaParts[#metaParts+1]=formatNumber(entry.Price).." Gold"
            local meta=auxLabel(
                row,
                table.concat(metaParts,"  •  "),
                UDim2.fromOffset(10,25),
                UDim2.new(1,-108,0,18),
                8,
                Enum.Font.Gotham
            )
            meta.TextColor3=entry.Stock>0
                and Color3.fromRGB(152,163,182)
                or Color3.fromRGB(188,103,112)

            local buy=auxButton(row,"BUY",UDim2.new(1,-94,0,11),UDim2.fromOffset(82,31))
            if entry.Stock<=0 then
                buy.Active=false
                buy.Text="SOLD"
                buy.BackgroundColor3=UITheme.Danger
            end

            buy.Activated:Connect(function()
                if state.Busy or entry.Stock<=0 or entry.ID==nil then return end
                local amount=math.clamp(
                    math.floor(tonumber(state.Quantity) or 1),
                    1,
                    math.max(1,math.floor(entry.Stock))
                )
                state.Busy=true
                W.SuspendFarmUntil=os.clock()+2.5
                buy.Text="..."
                status.Text="Buying "..tostring(amount).." × "..entry.Tag
                task.spawn(function()
                    local beforeStock=tonumber(entry.Instance:GetAttribute("Stock"))
                    local ok,accepted,rewardData=pcall(function()
                        return GET:InvokeServer(
                            "Waves",
                            "Item",
                            "Buy",
                            entry.Category,
                            entry.ID,
                            amount
                        )
                    end)
                    task.wait(0.22)
                    local afterStock=entry.Instance.Parent and tonumber(entry.Instance:GetAttribute("Stock")) or nil
                    local changed=beforeStock~=nil and afterStock~=nil and afterStock<beforeStock
                    if ok and (accepted==true or changed) then
                        status.Text="Purchased "..tostring(amount).." × "..entry.Tag
                        setStatus("MARKET PURCHASE OK",entry.Tag.." × "..tostring(amount))
                        announceMarketRewards(entry,rewardData,amount)
                        W.MarkProgress("Market purchase")
                        statsCacheAt=0
                    elseif not ok then
                        status.Text="Purchase error"
                        setStatus("MARKET PURCHASE FAILED","Direct Waves request errored")
                        waveToast("PURCHASE FAILED",string.sub(tostring(accepted),1,90),"error")
                    else
                        status.Text="Server did not confirm purchase"
                        setStatus("MARKET PURCHASE NOT CONFIRMED",entry.Tag)
                        waveToast("NOT CONFIRMED",entry.Tag,"error")
                    end
                    state.Busy=false
                    state.Signature=nil
                    task.wait(0.12)
                    if panel.Frame.Parent and panel.Frame.Visible then
                        buildMarketRows(panel)
                    end
                end)
            end)
        end
    end

    qtyMinus.Activated:Connect(function()
        state.Quantity=math.max(1,(tonumber(state.Quantity) or 1)-1)
        qtyValue.Text=tostring(state.Quantity)
    end)
    qtyPlus.Activated:Connect(function()
        state.Quantity=math.min(25,(tonumber(state.Quantity) or 1)+1)
        qtyValue.Text=tostring(state.Quantity)
    end)
    refreshButton.Activated:Connect(function()
        statsCacheAt=0
        state.Signature=nil
        buildMarketRows(panel)
    end)
    for category,b in pairs(tabButtons) do
        b.Activated:Connect(function()
            state.Category=category
            state.ScrollY=0
            state.Signature=nil
            buildMarketRows(panel)
        end)
    end

    task.defer(function()
        if scroll and scroll.Parent then
            pcall(function()
                scroll.CanvasPosition=Vector2.new(0,previousScroll)
            end)
        end
    end)

    state.Signature=marketSignatureFor(state.Category)
    raiseAuxGui(body,22)
end

