local blessingsModuleCache=nil

local function blessingsDefinitions()
    if type(blessingsModuleCache)=="table" then return blessingsModuleCache end
    local modules=ReplicatedStorage:FindFirstChild("Modules")
    local storage=modules and modules:FindFirstChild("Storage")
    local scriptObject=storage and storage:FindFirstChild("Blessings")
    if scriptObject and scriptObject:IsA("ModuleScript") then
        local ok,result=pcall(require,scriptObject)
        if ok and type(result)=="table" then
            blessingsModuleCache=result
            return result
        end
    end
    return nil
end

local function blessingDefinition(definitions,category,index)
    local group=type(definitions)=="table" and definitions[category] or nil
    if type(group)~="table" then return nil end
    return group[index] or group[tostring(index)] or group[tonumber(index)]
end

local function blessingCost(rolled)
    return math.ceil(2000*(1.43^(tonumber(rolled) or 0)))
end

local buildBlessingPanel

local function parseNumberText(text)
    local raw=tostring(text or ""):gsub(",","")
    return tonumber(raw:match("%-?%d+"))
end

local function readNativeBlessingState(definitions)
    local output={Options={},Gold=nil,Cost=nil}
    local pg=playerGui
    local interface=pg and pg:FindFirstChild("Interface")
    local blessing=interface and interface:FindFirstChild("Blessing")
    local main=blessing and blessing:FindFirstChild("Main")
    if not main then return output end

    local goldNode=main:FindFirstChild("Gold")
    local goldTitle=goldNode and goldNode:FindFirstChild("Title")
    if goldTitle and goldTitle:IsA("TextLabel") then
        output.Gold=parseNumberText(goldTitle.Text)
    end

    local roll=main:FindFirstChild("Roll")
    local rollTitle=roll and roll:FindFirstChild("Title")
    if rollTitle and rollTitle:IsA("TextLabel") then
        local cleaned=tostring(rollTitle.Text or ""):gsub(",","")
        output.Cost=tonumber(cleaned:match("%((%d+)%)")) or tonumber(cleaned:match("(%d+)"))
    end

    local categories=main:FindFirstChild("Categories")
    for _,category in ipairs({"Body","Offense","Defense","Support"}) do
        local list={}
        local categoryFrame=categories and categories:FindFirstChild(category)
        local inner=categoryFrame and categoryFrame:FindFirstChild("Inner")
        local rewards=inner and inner:FindFirstChild("Rewards")
        if rewards then
            for _,slot in ipairs(rewards:GetChildren()) do
                local tag=slot:GetAttribute("Tag")
                local index=slot:GetAttribute("Index")
                if tag~=nil or index~=nil then
                    local numericIndex=tonumber(index)
                    local definition=numericIndex and blessingDefinition(definitions,category,numericIndex) or nil
                    list[#list+1]={
                        Name=slot.Name,
                        Tag=tostring(tag or (definition and definition.Tag) or index or "Unknown"),
                        Index=numericIndex,
                        Rarity=tostring((definition and definition.Rarity) or "")
                    }
                end
            end
        end
        table.sort(list,function(a,b) return tostring(a.Name)<tostring(b.Name) end)
        output.Options[category]=list
    end

    local populated=0
    for _,category in ipairs({"Body","Offense","Defense","Support"}) do
        populated+=#(output.Options[category] or {})
    end

    if populated==0 and type(W.BlessingClone.LastWheels)=="table" then
        for _,category in ipairs({"Body","Offense","Defense","Support"}) do
            local raw=W.BlessingClone.LastWheels[category]
            local list={}
            if type(raw)=="table" then
                for key,value in pairs(raw) do
                    local index=tonumber(value) or tonumber(key)
                    if type(value)=="table" then
                        index=tonumber(value.Index or value.ID or value.Id or value[1] or key)
                    end
                    if index then
                        local definition=blessingDefinition(definitions,category,index)
                        list[#list+1]={
                            Name=category.."_"..tostring(index),
                            Tag=tostring((definition and definition.Tag) or (type(value)=="table" and (value.Tag or value.Name)) or index),
                            Index=index,
                            Rarity=tostring((definition and definition.Rarity) or (type(value)=="table" and value.Rarity) or "")
                        }
                    end
                end
            end
            table.sort(list,function(a,b) return (tonumber(a.Index) or 0)<(tonumber(b.Index) or 0) end)
            output.Options[category]=list
        end
    end

    return output
end

local function blessingSignatureFor()
    local definitions=blessingsDefinitions()
    local native=readNativeBlessingState(definitions)
    local parts={
        tostring(native.Gold or controllerGold() or "?"),
        tostring(native.Cost or "?"),
        tostring(W.BlessingClone.LastRolled or "?")
    }
    for _,category in ipairs({"Body","Offense","Defense","Support"}) do
        parts[#parts+1]=category
        for _,entry in ipairs(native.Options[category] or {}) do
            parts[#parts+1]=table.concat({
                tostring(entry.Index),
                tostring(entry.Tag),
                tostring(entry.Rarity)
            },"|")
        end
    end
    return table.concat(parts,";")
end

buildBlessingPanel=function(panel)
    local state=W.BlessingClone
    local body=panel.Body
    for _,child in ipairs(body:GetChildren()) do
        child:Destroy()
    end

    local definitions=blessingsDefinitions()
    local native=readNativeBlessingState(definitions)
    local stats=fetchStats(false)
    local capacity=type(stats)=="table" and tonumber(stats.Capacity) or nil
    local gold=native.Gold or controllerGold()
    local nativeCost=tonumber(native.Cost)
    if nativeCost and nativeCost<=0 then nativeCost=nil end
    local cost=nativeCost or blessingCost(state.LastRolled or 0)

    local goldLabel=auxLabel(
        body,
        "Gold  "..(gold and formatNumber(gold) or "?"),
        UDim2.fromOffset(12,6),
        UDim2.new(0.44,-12,0,24),
        10,
        Enum.Font.GothamBold
    )
    goldLabel.TextColor3=Color3.fromRGB(222,186,97)

    local costLabel=auxLabel(
        body,
        "Roll  "..formatNumber(cost),
        UDim2.new(0.44,0,0,6),
        UDim2.new(0.34,0,0,24),
        9,
        Enum.Font.GothamBold
    )
    costLabel.TextXAlignment=Enum.TextXAlignment.Center

    local auto=auxLabel(
        body,
        "AUTO",
        UDim2.new(0.78,0,0,6),
        UDim2.new(0.10,0,0,24),
        8,
        Enum.Font.GothamBold
    )
    auto.TextColor3=Color3.fromRGB(103,195,145)
    auto.TextXAlignment=Enum.TextXAlignment.Center

    local refreshButton=auxButton(body,"↻",UDim2.new(1,-45,0,5),UDim2.fromOffset(33,27))
    refreshButton.TextSize=14

    local resultLabel=auxLabel(
        body,
        state.LastResult or "Ready",
        UDim2.fromOffset(12,35),
        UDim2.new(1,-24,0,30),
        9,
        Enum.Font.GothamMedium
    )
    resultLabel.TextWrapped=true
    resultLabel.TextColor3=Color3.fromRGB(154,166,188)

    local scroll=Instance.new("ScrollingFrame")
    scroll.Position=UDim2.fromOffset(10,70)
    scroll.Size=UDim2.new(1,-20,1,-127)
    scroll.BackgroundTransparency=1
    scroll.BorderSizePixel=0
    scroll.ScrollBarThickness=3
    scroll.AutomaticCanvasSize=Enum.AutomaticSize.Y
    scroll.CanvasSize=UDim2.new()
    scroll.Parent=body

    local layout=Instance.new("UIListLayout")
    layout.Padding=UDim.new(0,6)
    layout.SortOrder=Enum.SortOrder.LayoutOrder
    layout.Parent=scroll

    local populated=0
    for _,category in ipairs({"Body","Offense","Defense","Support"}) do
        local options=native.Options[category] or {}
        populated=populated+#options
        local row=Instance.new("Frame")
        row.Size=UDim2.new(1,-4,0,72)
        row.BackgroundColor3=Color3.fromRGB(27,30,38)
        row.BorderSizePixel=0
        auxRound(row,8)
        row.Parent=scroll

        local title=auxLabel(
            row,
            string.upper(category),
            UDim2.fromOffset(10,4),
            UDim2.new(1,-20,0,18),
            9,
            Enum.Font.GothamBold
        )

        if #options==0 then
            local waitLabel=auxLabel(
                row,
                "Waiting for live selection...",
                UDim2.fromOffset(10,25),
                UDim2.new(1,-20,0,30),
                8,
                Enum.Font.Gotham
            )
            waitLabel.TextColor3=Color3.fromRGB(139,149,168)
        else
            for index,entry in ipairs(options) do
                if index<=3 then
                    local text=tostring(index)..". "..entry.Tag
                    if entry.Rarity~="" then text=text.."  ["..entry.Rarity.."]" end
                    local line=auxLabel(
                        row,
                        text,
                        UDim2.fromOffset(10,20+(index-1)*15),
                        UDim2.new(1,-20,0,15),
                        8,
                        Enum.Font.Gotham
                    )
                    line.TextColor3=Color3.fromRGB(161,171,189)
                    line.TextTruncate=Enum.TextTruncate.AtEnd
                end
            end
        end
    end

    if populated==0 then
        state.LastResult="Waiting for Blessing selection data • auto-refresh is active"
        resultLabel.Text=state.LastResult
    end

    local rollButton=auxButton(
        body,
        "ROLL • "..formatNumber(cost).." GOLD",
        UDim2.new(0,10,1,-48),
        UDim2.new(1,-20,0,38)
    )
    rollButton.BackgroundColor3=UITheme.Reward

    refreshButton.Activated:Connect(function()
        statsCacheAt=0
        state.Signature=nil
        buildBlessingPanel(panel)
    end)

    rollButton.Activated:Connect(function()
        if state.Busy then return end
        local currentGold=readNativeBlessingState(definitions).Gold or controllerGold() or gold
        local currentCost=readNativeBlessingState(definitions).Cost or cost
        if currentGold~=nil and currentGold<currentCost then
            state.LastResult="Not enough Gold • need "..formatNumber(currentCost)
            resultLabel.Text=state.LastResult
            waveToast("NOT ENOUGH GOLD","Need "..formatNumber(currentCost).." Gold","error")
            return
        end
        if capacity~=nil and capacity>=1000 then
            state.LastResult="Inventory is full."
            resultLabel.Text=state.LastResult
            waveToast("INVENTORY FULL","Blessing roll cancelled","error")
            return
        end
        if not GET or not GET:IsA("RemoteFunction") then
            state.LastResult="GET remote is unavailable."
            resultLabel.Text=state.LastResult
            return
        end

        state.Busy=true
        W.SuspendFarmUntil=os.clock()+2.5
        rollButton.Text="ROLLING..."
        resultLabel.Text="Rolling..."
        task.spawn(function()
            local ok,wheels,result,newRolled=pcall(function()
                return GET:InvokeServer("Waves","Blessing","Spin")
            end)
            if not ok then
                state.LastResult="Roll error: "..string.sub(tostring(wheels),1,80)
                setStatus("BLESSING ROLL FAILED","Direct Waves request errored")
                waveToast("BLESSING FAILED",string.sub(tostring(wheels),1,85),"error")
            elseif type(wheels)=="table" and #wheels>0 and tonumber(newRolled)~=nil then
                state.LastWheels=wheels
                state.LastRolled=tonumber(newRolled)
                if type(result)=="table" and result[1]~=nil and result[2]~=nil then
                    local definition=blessingDefinition(definitions,result[1],result[2])
                    local tag=definition and definition.Tag or tostring(result[2])
                    local rarity=definition and definition.Rarity or ""
                    state.LastResult="ROLLED • "..tostring(tag).." • "..tostring(result[1])
                    if rarity~="" then state.LastResult=state.LastResult.." • "..tostring(rarity) end
                    setStatus("BLESSING ROLL OK",tostring(tag).." • "..tostring(result[1]))
                    waveToast("BLESSING ROLLED",tostring(tag)..(rarity~="" and (" • "..rarity) or ""),"reward")
                    W.MarkProgress("Blessing rolled")
                else
                    state.LastResult="ROLLED • Empty"
                    setStatus("BLESSING ROLL OK","Empty result")
                    waveToast("BLESSING ROLLED","No reward","success")
                    W.MarkProgress("Blessing rolled")
                end
            else
                state.LastResult="Server did not confirm the roll."
                setStatus("BLESSING ROLL NOT CONFIRMED","No valid Waves roll result returned")
                waveToast("ROLL NOT CONFIRMED","No valid server result","error")
            end
            state.Busy=false
            state.Signature=nil
            statsCacheAt=0
            task.wait(0.15)
            if panel.Frame.Parent and panel.Frame.Visible then
                buildBlessingPanel(panel)
            end
        end)
    end)

    state.Signature=blessingSignatureFor()
    raiseAuxGui(body,22)
end

local function blessingRefreshClone()
    local panel=createAuxPanel(
        "Blessing",
        "SliceHub • Blessing Machine",
        370,
        500,
        UDim2.new(1,-386,1,-518)
    )
    if not panel then return false end
    statsCacheAt=0
    buildBlessingPanel(panel)
    if not W.BlessingClone.AutoWorker then
        W.BlessingClone.AutoWorker=true
        task.spawn(function()
            while W.Running ~= false and gui and gui.Parent do
                task.wait(1.15)
                local current=W.AuxPanels and W.AuxPanels.Blessing
                if current and current.Frame and current.Frame.Parent and current.Frame.Visible and not W.BlessingClone.Busy then
                    local signature=blessingSignatureFor()
                    if signature~=W.BlessingClone.Signature then
                        buildBlessingPanel(current)
                    end
                end
            end
            W.BlessingClone.AutoWorker=false
        end)
    end
    setStatus("BLESSING CLONE • opened","Live selection + automatic refresh + roll notifications")
    return true
end

        W.OpenMarket=function()
            if not premiumAllowed() or not W.IsRuntime() then return false end
            GET=upgradeRemote() or GET
            if not GET or not GET:IsA("RemoteFunction") then return false end
            W.SuspendFarmUntil=os.clock()+0.8
            return marketRefreshClone()
        end
        W.OpenBlessing=function()
            if not premiumAllowed() or not W.IsRuntime() then return false end
            GET=upgradeRemote() or GET
            if not GET or not GET:IsA("RemoteFunction") then return false end
            W.SuspendFarmUntil=os.clock()+0.8
            return blessingRefreshClone()
        end
        return true
    end

    W.InstallAux()

    function W.NativeButton(button)
        if not button or not button:IsA("GuiButton") or not button.Parent then return false end
        local activated = pcall(function() button:Activate() end)
        if activated then return true end
        local env = (type(getgenv) == "function" and getgenv()) or _G
        local fire = env and env.firesignal or (type(firesignal) == "function" and firesignal or nil)
        if type(fire) == "function" then
            local ok = pcall(function() fire(button.MouseButton1Click) end)
            if ok then return true end
        end
        local previous = GuiService.SelectedObject
        local ok = pcall(function()
            GuiService.SelectedObject = button
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
            task.wait(0.045)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
        end)
        pcall(function() GuiService.SelectedObject = previous end)
        if ok then return true end
        local position = button.AbsolutePosition + button.AbsoluteSize / 2
        local inset = GuiService:GetGuiInset()
        return pcall(function()
            VirtualInputManager:SendMouseButtonEvent(position.X + inset.X, position.Y + inset.Y, 0, true, game, 0)
            task.wait(0.04)
            VirtualInputManager:SendMouseButtonEvent(position.X + inset.X, position.Y + inset.Y, 0, false, game, 0)
        end)
    end

    function W.FindSpearsPurchaseButton()
        local interface = playerGui:FindFirstChild("Interface")
        local equipment = interface and interface:FindFirstChild("Equipment")
        local stat = equipment and equipment:FindFirstChild("Stat")
        local gears = stat and stat:FindFirstChild("Gears")
        local spears = gears and gears:FindFirstChild("Spears")
        local inner = spears and spears:FindFirstChild("Inner")
        local button = inner and inner:FindFirstChild("Interact")
        return button and button:IsA("GuiButton") and button or nil
    end

    function W.FindPurchaseConfirm()
        local interface = playerGui:FindFirstChild("Interface")
        local warning = interface and interface:FindFirstChild("Warning")
        local prompt = warning and warning:FindFirstChild("Prompt")
        local main = prompt and prompt:FindFirstChild("Main")
        local yes = main and main:FindFirstChild("Yes")
        if yes and yes:IsA("GuiButton") and yes.Visible then return yes end
        return nil
    end

    function W.SpearsOwned()
        if player:GetAttribute("Weapon") == "Spears" then return true end
        local character = player.Character
        if character and (character:GetAttribute("Spears") ~= nil or character:GetAttribute("Max_Spears") ~= nil) then
            return true
        end
        local button = W.FindSpearsPurchaseButton()
        if not button then return nil end
        local text = tostring(button.Text or "")
        for _, object in ipairs(button:GetDescendants()) do
            if object:IsA("TextLabel") or object:IsA("TextButton") then text = text .. " " .. tostring(object.Text or "") end
        end
        text = string.upper(text)
        if string.find(text, "OWNED", 1, true) or string.find(text, "EQUIP", 1, true) then return true end
        return false
    end

    function W.TickAutoBuyTS()
        if not premiumAllowed() or App.Values.WavesAutoBuyTS ~= true or W.TSBuyDone or W.TSBuyBusy or not W.IsRuntime() then return false end
        local now = os.clock()
        if now < (W.TSBuyNextAt or 0) or W.Refilling or W.Busy or W.CutsceneBusy() then return false end
        local owned = W.SpearsOwned()
        if owned == true then
            W.TSBuyDone = true
            return true
        end
        if W.TSBuySpent == true then
            W.TSBuyNextAt = now + 8
            return false
        end
        local gold = W.ControllerGold(false)
        if not gold or gold < 250000 then
            W.TSBuyNextAt = now + 8
            return false
        end
        local button = W.FindSpearsPurchaseButton()
        if not button then
            W.TSBuyNextAt = now + 12
            return false
        end

        local beforeGold = gold
        W.TSBuyBusy = true
        W.SuspendFarmUntil = now + 2.5
        W.Status = "Waiting"
        task.spawn(function()
            local ok = W.Running ~= false and gui and gui.Parent and W.NativeButton(button)
            if ok then
                local started = os.clock()
                repeat
                    task.wait(0.08)
                    if W.Running == false or not gui or not gui.Parent then break end
                    local confirm = W.FindPurchaseConfirm()
                    if confirm then
                        W.NativeButton(confirm)
                        break
                    end
                until os.clock() - started >= 1.8
                local verifyStarted = os.clock()
                repeat
                    task.wait(0.18)
                    if W.Running == false or not gui or not gui.Parent then break end
                    if W.SpearsOwned() == true then
                        W.TSBuyDone = true
                        W.MarkProgress("Thunder Spears purchased")
                        break
                    end
                until os.clock() - verifyStarted >= 4.0
                if W.Running ~= false and gui and gui.Parent and W.TSBuyDone ~= true then
                    W.StatsCacheAt = 0
                    local afterGold = W.ControllerGold(true)
                    if beforeGold and afterGold and afterGold <= beforeGold - 200000 then
                        W.TSBuySpent = true
                    end
                end
            end
            W.TSBuyBusy = false
            W.TSBuyNextAt = os.clock() + ((W.TSBuyDone or W.TSBuySpent) and 999999 or 15)
        end)
        return true
    end

    function W.Reset()
        W.Busy = false
        W.RoundActiveSince = nil
        W.LastAliveCount = 0
        W.HoldCFrame = nil
        W.ReadyTarget = nil
        W.ReadyLocked = false
        W.CurrentCrate = nil
        W.Refilling = false
        W.FarmCFrame = nil
        W.ReadyPhase = nil
        W.LastPhaseSignature = nil
        W.SuspendFarmUntil = 0
        W.TSBuyBusy = false
        W.TSBuySpent = false
        W.Status = "Waiting"
        W.ReleaseBladeOwnership()
    end

    task.spawn(function()
        while gui and gui.Parent do
            local wavesEnabled =
                App.Values.WavesAutoFarm == true
                or App.Values.WavesAutoSkip == true
                or App.Values.WavesAutoCrates == true
                or App.Values.WavesAutoUpgrade == true
                or App.Values.WavesAutoBuyTS == true

            task.wait(
                wavesEnabled
                and App.PerformanceControl.Delay(0.10, 0.14)
                or App.PerformanceControl.Delay(0.55, 0.95)
            )

            if RuntimeKind ~= "Gameplay"
                or not premiumAllowed() then
                if W.OwnsBlades then
                    W.ReleaseBladeOwnership()
                end
                continue
            end

            if not wavesEnabled then
                if W.OwnsBlades then
                    W.ReleaseBladeOwnership()
                end
                W.Status = "Waiting"
                continue
            end

            if not W.IsRuntime() then
                if W.OwnsBlades then
                    W.ReleaseBladeOwnership()
                end

                if App.Values.WavesAutoFarm
                    or App.Values.WavesAutoSkip
                    or App.Values.WavesAutoCrates
                    or App.Values.WavesAutoUpgrade
                    or App.Values.WavesAutoBuyTS then
                    W.Status =
                        "Waiting for Waves runtime"
                end

                continue
            end

            local setupReady, setupReason =
                W.ServerSetupReady()

            if not setupReady then
                W.Status =
                    tostring(
                        setupReason
                        or "Waiting for Waves setup"
                    )
                continue
            end

            W.ObservePhaseProgress()

            if App.Failsafe and App.Failsafe.Triggering then
                W.Status = "Recovering"
                continue
            end

            if App.Cutscene and App.Cutscene.Active == true then
                W.Status = "Cutscene"
                W.ObserveCombatProgress(0)
                continue
            end

            W.TickAutoBuyTS()
            W.TickUpgrades()

            local alive = W.LiveTitanCount()

            if App.Values.WavesAutoSkip == true
                and alive <= 0 then
                W.TryReady()
            end

            if App.Values.WavesAutoFarm == true then
                W.EnsureBladeFarm()

                if alive <= 0 then
                    W.HoldCharacter(
                        W.FindReadyGui()
                        and (
                            App.Values.WavesAutoSkip
                            and "READY visible • skip armed"
                            or "READY visible • Auto Wave Skip off"
                        )
                        or (
                            W.CutsceneBusy()
                            and "Holding through transition"
                            or "Holding safely • waiting for next wave"
                        )
                    )
                end

            elseif W.OwnsBlades then
                W.ReleaseBladeOwnership()
            end

            if App.Values.WavesAutoCrates == true
                and not W.Busy
                and os.clock() >= (W.LastCrateAttempt or 0) then

                local active =
                    select(1, W.IsRoundActive())

                if active then
                    local crate =
                        W.GetPlayerCrate()

                    if crate then
                        W.LastCrateAttempt =
                            os.clock() + 0.35

                        W.ProcessCrate(crate)
                    end
                end
            end
        end

        W.Running = false
        W.Reset()
    end)
end)()


App.RaidChestAuto = App.RaidChestAuto or {
    Busy = false,
    Attempted = false,
    ScreenActive = false,
    Status = "Idle",
    LastAttemptAt = 0,
    NextAttemptAt = 0,
    FreeCompleted = false,
    PremiumCompleted = false,
    SawFreeButton = false,
    SawPremiumButton = false,
    Completed = false,
    Failed = false,
    GateExpired = false,
    SessionStartedAt = 0,
    SessionNonce = 0,
    LastClickMethod = "None",
}

App.RaidChestAuto.IsActuallyVisible = function(object)
    if not object or not object:IsA("GuiObject") then
        return false
    end

    if not object.Visible
        or object.AbsoluteSize.X <= 0
        or object.AbsoluteSize.Y <= 0 then
        return false
    end

    local node = object.Parent
    while node and node ~= playerGui do
        if node:IsA("GuiObject") and not node.Visible then
            return false
        end
        if node:IsA("LayerCollector") and not node.Enabled then
            return false
        end
        node = node.Parent
    end

    return true
end

App.RaidChestAuto.Text = function(object)
    if object
        and (
            object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox")
        ) then
        local textValue = tostring(object.Text or "")
        textValue = string.gsub(textValue, "<[^>]->", "")
        textValue = string.gsub(textValue, "%s+", " ")
        textValue = string.gsub(textValue, "^%s+", "")
        textValue = string.gsub(textValue, "%s+$", "")
        return string.lower(textValue)
    end
    return ""
end

App.RaidChestAuto.FindButtonAncestor = function(object)
    local node = object
    for _ = 1, 8 do
        if not node or node == playerGui then break end
        if node:IsA("GuiButton") then return node end
        node = node.Parent
    end
    return nil
end

App.RaidChestAuto.ChestsRoot = function()
    local interface = playerGui:FindFirstChild("Interface")
    return interface and interface:FindFirstChild("Chests") or nil
end

App.RaidChestAuto.ScreenVisible = function()
    local chests = App.RaidChestAuto.ChestsRoot()

    if chests then
        if chests:IsA("GuiObject")
            and App.RaidChestAuto.IsActuallyVisible(chests) then
            return true
        end

        for _, object in ipairs(chests:GetDescendants()) do
            if object:IsA("GuiObject")
                and App.RaidChestAuto.IsActuallyVisible(object) then
                return true
            end
        end
    end

    for _, object in ipairs(playerGui:GetDescendants()) do
        if App.RaidChestAuto.IsActuallyVisible(object) then
            local name = string.lower(tostring(object.Name or ""))
            local textValue = App.RaidChestAuto.Text(object)
            if name == "chests"
                or textValue == "chests"
                or textValue == "raid chests"
                or string.find(textValue, "open (", 1, true) then
                return true
            end
        end
    end

    return false
end

App.RaidChestAuto.FindChestButton = function(kind)
    local wanted = string.lower(tostring(kind or "Free"))
    local wantsFree = wanted == "free"
    local best, bestScore = nil, -math.huge

    local chests = App.RaidChestAuto.ChestsRoot()
    local directName = wantsFree and "Free" or "Premium"
    local direct = chests and chests:FindFirstChild(directName)

    if direct and direct:IsA("GuiObject")
        and App.RaidChestAuto.IsActuallyVisible(direct) then
        if direct:IsA("GuiButton") then return direct end

        for _, descendant in ipairs(direct:GetDescendants()) do
            if descendant:IsA("GuiButton")
                and App.RaidChestAuto.IsActuallyVisible(descendant) then
                return descendant
            end
        end

        local ancestor = App.RaidChestAuto.FindButtonAncestor(direct)
        if ancestor then return ancestor end
    end

    for _, object in ipairs(playerGui:GetDescendants()) do
        if App.RaidChestAuto.IsActuallyVisible(object) then
            local joined =
                App.RaidChestAuto.Text(object)
                .. " "
                .. string.lower(tostring(object.Name or ""))

            local mentionsFree = string.find(joined, "free", 1, true) ~= nil
            local mentionsPremium =
                string.find(joined, "premium", 1, true) ~= nil
                or string.find(joined, "emperor", 1, true) ~= nil

            local wantedMatch =
                (wantsFree and mentionsFree)
                or ((not wantsFree) and mentionsPremium)
            local wrongMatch =
                (wantsFree and mentionsPremium)
                or ((not wantsFree) and mentionsFree)

            if wantedMatch and not wrongMatch then
                local candidate = App.RaidChestAuto.FindButtonAncestor(object)

                if not candidate then
                    local node = object.Parent
                    for _ = 1, 7 do
                        if not node or node == playerGui then break end
                        for _, descendant in ipairs(node:GetDescendants()) do
                            if descendant:IsA("GuiButton")
                                and App.RaidChestAuto.IsActuallyVisible(descendant) then
                                candidate = descendant
                                break
                            end
                        end
                        if candidate then break end
                        node = node.Parent
                    end
                end

                if candidate then
                    local score = 10
                    local candidateText = App.RaidChestAuto.Text(candidate)
                    if string.find(candidateText, "open", 1, true) then score += 12 end
                    if candidate:IsA("GuiButton") then score += 6 end
                    if score > bestScore then
                        bestScore = score
                        best = candidate
                    end
                end
            end
        end
    end

    return best
end

App.RaidChestAuto.FindFinishButton = function()
    local best, bestY = nil, -math.huge
    local chests = App.RaidChestAuto.ChestsRoot()
    local direct = chests and chests:FindFirstChild("Finish")

    if direct and direct:IsA("GuiObject")
        and App.RaidChestAuto.IsActuallyVisible(direct) then
        if direct:IsA("GuiButton") then return direct end

        for _, descendant in ipairs(direct:GetDescendants()) do
            if descendant:IsA("GuiButton")
                and App.RaidChestAuto.IsActuallyVisible(descendant) then
                return descendant
            end
        end

        local ancestor = App.RaidChestAuto.FindButtonAncestor(direct)
        if ancestor then return ancestor end
    end

    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsA("GuiObject")
            and App.RaidChestAuto.IsActuallyVisible(object) then
            local textValue = string.upper(App.RaidChestAuto.Text(object))
            if textValue == "FINISH" then
                local candidate = App.RaidChestAuto.FindButtonAncestor(object) or object
                if candidate:IsA("GuiObject") and candidate.AbsolutePosition.Y > bestY then
                    bestY = candidate.AbsolutePosition.Y
                    best = candidate
                end
            end
        end
    end

    return best
end

-- V15.6.35: resolve the actual OPEN action rather than assuming a chest card
-- itself is the opener. This mirrors Retry-style live UI targeting and supports
-- layouts where selecting Free/Premium and pressing OPEN are separate controls.
App.RaidChestAuto.FindChestActionButton = function(kind)
    local wantsFree = string.lower(tostring(kind or "Free")) == "free"
    local root = App.RaidChestAuto.ChestsRoot() or playerGui
    local best, bestScore = nil, -math.huge

    for _, object in ipairs(root:GetDescendants()) do
        if object:IsA("GuiButton") and App.RaidChestAuto.IsActuallyVisible(object) then
            local pieces = {
                string.lower(tostring(object.Name or "")),
                App.RaidChestAuto.Text(object),
            }
            local node = object.Parent
            for _ = 1, 5 do
                if not node or node == playerGui then break end
                pieces[#pieces + 1] = string.lower(tostring(node.Name or ""))
                pieces[#pieces + 1] = App.RaidChestAuto.Text(node)
                node = node.Parent
            end

            local context = table.concat(pieces, " ")
            local mentionsFree = string.find(context, "free", 1, true) ~= nil
            local mentionsPremium = string.find(context, "premium", 1, true) ~= nil
                or string.find(context, "emperor", 1, true) ~= nil
            local mentionsOpen = string.find(context, "open", 1, true) ~= nil
            local correctKind = wantsFree and mentionsFree
                or ((not wantsFree) and mentionsPremium)
            local wrongKind = wantsFree and mentionsPremium
                or ((not wantsFree) and mentionsFree)

            local score = 0
            if mentionsOpen then score += 90 end
            if correctKind then score += 55 end
            if wrongKind then score -= 100 end
            if root ~= playerGui then score += 20 end
            if string.lower(tostring(object.Name or "")) == "open" then score += 40 end

            if score > bestScore then
                best, bestScore = object, score
            end
        end
    end

    if best and bestScore >= 55 then return best end
    return App.RaidChestAuto.FindChestButton(kind)
end

App.RaidChestAuto.ActivateGui = function(object)
    if not object
        or not object:IsA("GuiObject")
        or not App.RaidChestAuto.IsActuallyVisible(object) then
        return false, "visible UI target missing"
    end

    local button = App.RaidChestAuto.FindButtonAncestor(object) or object
    if not button:IsA("GuiObject") then return false, "button target missing" end

    local position = button.AbsolutePosition
    local size = button.AbsoluteSize
    local x = math.floor(position.X + size.X * 0.5 + 0.5)
    local y = math.floor(position.Y + size.Y * 0.5 + 0.5)
    local inset = Vector2.new(0, 0)
    pcall(function() inset = GuiService:GetGuiInset() end)

    -- Resolution-independent precise click, same principle as hardened Retry.
    local shellWasVisible = nil
    if shell and shell.Parent and shell:IsA("GuiObject") then
        shellWasVisible = shell.Visible
        shell.Visible = false
    end
    local overlay = App.PerformanceControl and App.PerformanceControl.Overlay or nil
    local overlayWasEnabled = nil
    if overlay and overlay.Parent and overlay:IsA("LayerCollector") then
        overlayWasEnabled = overlay.Enabled
        overlay.Enabled = false
    end

    local mouseOk = pcall(function()
        VirtualInputManager:SendMouseMoveEvent(x + inset.X, y + inset.Y, game)
        task.wait(0.04)
        VirtualInputManager:SendMouseButtonEvent(x + inset.X, y + inset.Y, 0, true, game, 0)
        task.wait(0.07)
        VirtualInputManager:SendMouseButtonEvent(x + inset.X, y + inset.Y, 0, false, game, 0)
    end)

    if overlay and overlay.Parent and overlayWasEnabled ~= nil then
        overlay.Enabled = overlayWasEnabled
    end
    if shell and shell.Parent and shellWasVisible ~= nil then
        shell.Visible = shellWasVisible and not App.Hidden
    end

    if mouseOk then
        App.RaidChestAuto.LastClickMethod = "precise mouse"
        return true, "precise mouse"
    end

    -- UI-navigation fallback: select the exact live target and press Return.
    if button:IsA("GuiButton") then
        local previousSelected = nil
        local keyboardOk = pcall(function()
            previousSelected = GuiService.SelectedObject
            button.Selectable = true
            GuiService.SelectedObject = button
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
            task.wait(0.055)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
        end)
        pcall(function() GuiService.SelectedObject = previousSelected end)
        if keyboardOk then
            App.RaidChestAuto.LastClickMethod = "UI navigation"
            return true, "UI navigation"
        end

        local activateOk = pcall(function() button:Activate() end)
        if activateOk then
            App.RaidChestAuto.LastClickMethod = "Activate"
            return true, "Activate"
        end
    end

    return false, "activation failed"
end

App.RaidChestAuto.WaitDelay = function(seconds)
    local started = os.clock()
    local duration = math.max(0, tonumber(seconds) or 0)
    while gui and gui.Parent and os.clock() - started < duration do
        if App.RaidChestAuto.GateExpired then break end
        task.wait(0.10)
    end
end

App.RaidChestAuto.WaitForButton = function(kind, timeout)
    local started = os.clock()
    local duration = math.max(0.25, tonumber(timeout) or 8)
    local premium = string.lower(tostring(kind or "")) ~= "free"

    repeat
        local button = App.RaidChestAuto.FindChestButton(kind)
        if button and App.RaidChestAuto.IsActuallyVisible(button) then
            if premium then App.RaidChestAuto.SawPremiumButton = true
            else App.RaidChestAuto.SawFreeButton = true end
            return button
        end
        if App.RaidChestAuto.GateExpired then return nil end
        task.wait(0.10)
    until not gui or not gui.Parent or os.clock() - started >= duration

    return nil
end

App.RaidChestAuto.OpenVerified = function(kind)
    local lastMethod = "button unavailable"
    local isFree = string.lower(tostring(kind or "")) == "free"

    for attempt = 1, 7 do
        local button = App.RaidChestAuto.FindChestActionButton(kind)
            or App.RaidChestAuto.WaitForButton(kind, attempt == 1 and 2.0 or 0.65)

        if button then
            local beforeButton = button
            local beforeText = App.RaidChestAuto.Text(button)
            local beforePremium = isFree and App.RaidChestAuto.FindChestButton("Premium") or nil
            local beforeFinish = App.RaidChestAuto.FindFinishButton()

            local dispatched, method = App.RaidChestAuto.ActivateGui(button)
            lastMethod = tostring(method or lastMethod)

            if dispatched then
                local verifyStarted = os.clock()
                while gui and gui.Parent and os.clock() - verifyStarted < 1.25 do
                    local current = App.RaidChestAuto.FindChestActionButton(kind)
                    local targetGone = not beforeButton.Parent
                        or not App.RaidChestAuto.IsActuallyVisible(beforeButton)
                    local targetChanged = current ~= nil and current ~= beforeButton
                    local textChanged = beforeButton.Parent
                        and App.RaidChestAuto.Text(beforeButton) ~= beforeText
                    local screenGone = not App.RaidChestAuto.ScreenVisible()
                    local premiumAppeared = isFree
                        and beforePremium == nil
                        and App.RaidChestAuto.FindChestButton("Premium") ~= nil
                    local finishAppeared = (not isFree)
                        and beforeFinish == nil
                        and App.RaidChestAuto.FindFinishButton() ~= nil

                    if targetGone or targetChanged or textChanged or screenGone
                        or premiumAppeared or finishAppeared then
                        return true, lastMethod
                    end
                    task.wait(0.08)
                end
            end
        end

        App.RaidChestAuto.Status = isFree
            and ("Opening free chest • retry " .. tostring(attempt))
            or ("Opening premium chest • retry " .. tostring(attempt))
        task.wait(0.30 + attempt * 0.06)
    end

    return false, lastMethod
end

App.RaidChestAuto.ClickFinishVerified = function()
    local lastMethod = "FINISH not found"

    for attempt = 1, 8 do
        local button = App.RaidChestAuto.FindFinishButton()
        if button then
            local dispatched, method = App.RaidChestAuto.ActivateGui(button)
            lastMethod = tostring(method or lastMethod)
            if dispatched then
                local verifyStarted = os.clock()
                while gui and gui.Parent and os.clock() - verifyStarted < 0.70 do
                    if not App.RaidChestAuto.ScreenVisible()
                        or not button.Parent
                        or not App.RaidChestAuto.IsActuallyVisible(button) then
                        return true, lastMethod
                    end
                    task.wait(0.08)
                end
            end
        end

        task.wait(0.28 + attempt * 0.04)
    end

    return false, lastMethod
end

App.RaidChestAuto.ResetScreen = function()
    App.RaidChestAuto.ScreenActive = false
    App.RaidChestAuto.Attempted = false
    App.RaidChestAuto.Busy = false
    App.RaidChestAuto.NextAttemptAt = 0
    App.RaidChestAuto.ActivationSerial = 0
    App.RaidChestAuto.FreeCompleted = false
    App.RaidChestAuto.PremiumCompleted = false
    App.RaidChestAuto.SawFreeButton = false
    App.RaidChestAuto.SawPremiumButton = false
    App.RaidChestAuto.Completed = false
    App.RaidChestAuto.Failed = false
    App.RaidChestAuto.GateExpired = false
    App.RaidChestAuto.SessionStartedAt = 0
    App.RaidChestAuto.SessionNonce = (tonumber(App.RaidChestAuto.SessionNonce) or 0) + 1
    App.RaidChestAuto.Status = "Idle"
end

App.RaidChestAuto.ObserveButtons = function()
    local free = App.RaidChestAuto.FindChestButton("Free")
    local premium = App.RaidChestAuto.FindChestButton("Premium")
    if free and App.RaidChestAuto.IsActuallyVisible(free) then App.RaidChestAuto.SawFreeButton = true end
    if premium and App.RaidChestAuto.IsActuallyVisible(premium) then App.RaidChestAuto.SawPremiumButton = true end
    return free, premium
end

App.RaidChestAuto.CanFinish = function()
    local freeOk = App.Values.RaidOpenFreeChest ~= true or App.RaidChestAuto.FreeCompleted == true
    local premiumOk = App.Values.RaidOpenPremiumChest ~= true or App.RaidChestAuto.PremiumCompleted == true
    return freeOk and premiumOk
end

App.RaidChestAuto.TryFinishWatchdog = function()
    if App.Values.RaidAutoOpenChests ~= true
        or App.RaidChestAuto.Busy
        or App.RaidChestAuto.GateExpired
        or not App.RaidChestAuto.CanFinish() then
        return false
    end

    local finish = App.RaidChestAuto.FindFinishButton()
    if not finish then return false end

    App.RaidChestAuto.Busy = true
    local ok = App.RaidChestAuto.ClickFinishVerified()
    App.RaidChestAuto.Busy = false
    if ok then
        App.RaidChestAuto.Completed = true
        App.RaidChestAuto.Failed = false
        App.RaidChestAuto.Attempted = true
        App.RaidChestAuto.Status = "Idle"
    else
        App.RaidChestAuto.Failed = true
        App.RaidChestAuto.Attempted = false
        App.RaidChestAuto.Status = "Failed to open"
        App.RaidChestAuto.NextAttemptAt = os.clock() + 0.85
    end
    return ok
end

App.RaidChestAuto.RunSequence = function()
    if App.RaidChestAuto.Busy
        or App.Values.RaidAutoOpenChests ~= true
        or App.RaidChestAuto.GateExpired
        or os.clock() < (tonumber(App.RaidChestAuto.NextAttemptAt) or 0) then
        return false
    end

    local openFree = App.Values.RaidOpenFreeChest == true
    local openPremium = App.Values.RaidOpenPremiumChest == true

    -- V15.6.33: restore the proven Booster Services raid-chest ownership model.
    -- One sequence owns the chest screen from first chest -> reward reveal -> FINISH.
    -- No independent FINISH watchdog is allowed to jump ahead of this sequence.
    if (tonumber(App.RaidChestAuto.SessionStartedAt) or 0) <= 0 then
        App.RaidChestAuto.SessionStartedAt = os.clock()
    end

    App.RaidChestAuto.SessionNonce = (tonumber(App.RaidChestAuto.SessionNonce) or 0) + 1
    local nonce = App.RaidChestAuto.SessionNonce
    App.RaidChestAuto.Attempted = true
    App.RaidChestAuto.Busy = true
    App.RaidChestAuto.Failed = false
    App.RaidChestAuto.Completed = false
    App.RaidChestAuto.FreeCompleted = false
    App.RaidChestAuto.PremiumCompleted = false
    App.RaidChestAuto.LastAttemptAt = os.clock()

    local function alive()
        return gui and gui.Parent
            and not App.RaidChestAuto.GateExpired
            and nonce == App.RaidChestAuto.SessionNonce
    end

    local function waitStage(seconds, labelText)
        local started = os.clock()
        local duration = math.max(0, tonumber(seconds) or 0)
        while alive()
            and App.RaidChestAuto.ScreenVisible()
            and os.clock() - started < duration do
            local remaining = math.max(0, duration - (os.clock() - started))
            App.RaidChestAuto.Status = tostring(labelText)
                .. " • "
                .. string.format("%.1fs", remaining)
            task.wait(0.10)
        end
    end

    local function fail(message)
        if nonce == App.RaidChestAuto.SessionNonce then
            App.RaidChestAuto.Busy = false
            App.RaidChestAuto.Failed = true
            App.RaidChestAuto.Completed = false
            App.RaidChestAuto.Status = tostring(message or "Failed to open")
            -- Booster Services used one clean ownership pass. SliceHub keeps one
            -- bounded retry in case the GUI rendered a fraction late.
            App.RaidChestAuto.Attempted = false
            App.RaidChestAuto.NextAttemptAt = os.clock() + 1.15
        end
        return false
    end

    -- Exact proven settle from Booster Services before touching the first chest.
    task.wait(1.10)
    if not alive() then
        App.RaidChestAuto.Busy = false
        return false
    end

    if not openFree and not openPremium then
        App.RaidChestAuto.Status = "Enabled • no chest type selected"
    end

    if openFree and App.RaidChestAuto.ScreenVisible() then
        App.RaidChestAuto.Status = "Opening Free Chest"
        local free = App.RaidChestAuto.FindChestButton("Free")
            or App.RaidChestAuto.WaitForButton("Free", 5.0)
        if not free then
            return fail("Free chest button not found")
        end

        App.RaidChestAuto.SawFreeButton = true
        local freeOk, freeMethod = App.RaidChestAuto.OpenVerified("Free")
        if not freeOk then
            return fail("Free failed • " .. tostring(freeMethod))
        end

        App.RaidChestAuto.FreeCompleted = true
        waitStage(7.0, "Free opened • waiting")
    end

    if not alive() then
        App.RaidChestAuto.Busy = false
        return false
    end

    if openPremium and App.RaidChestAuto.ScreenVisible() then
        App.RaidChestAuto.Status = "Waiting for Premium Chest"
        local premium = App.RaidChestAuto.FindChestButton("Premium")
            or App.RaidChestAuto.WaitForButton("Premium", 5.0)
        if not premium then
            return fail("Premium Chest never became ready")
        end

        App.RaidChestAuto.SawPremiumButton = true
        App.RaidChestAuto.Status = "Opening Premium Chest"
        local premiumOk, premiumMethod = App.RaidChestAuto.OpenVerified("Premium")
        if not premiumOk then
            return fail("Premium failed • " .. tostring(premiumMethod))
        end

        App.RaidChestAuto.PremiumCompleted = true
        waitStage(7.0, "Premium opened • waiting")
    elseif openFree then
        App.RaidChestAuto.Status = "Free Chest complete"
    end

    if not alive() then
        App.RaidChestAuto.Busy = false
        return false
    end

    -- FINISH belongs to this sequence only, and only after every selected chest.
    if App.RaidChestAuto.ScreenVisible() then
        App.RaidChestAuto.Status = "Waiting for FINISH"
        local finishWaitStarted = os.clock()
        while alive()
            and App.RaidChestAuto.ScreenVisible()
            and os.clock() - finishWaitStarted < 5.0 do
            if App.RaidChestAuto.FindFinishButton() then break end
            task.wait(0.10)
        end

        local finished = false
        local lastMethod = "FINISH not found"
        for _ = 1, 6 do
            local button = App.RaidChestAuto.FindFinishButton()
            if button then
                local ok, method = App.RaidChestAuto.ActivateGui(button)
                lastMethod = tostring(method or lastMethod)
                if ok then
                    local verifyStarted = os.clock()
                    while alive() and os.clock() - verifyStarted < 0.75 do
                        if not App.RaidChestAuto.ScreenVisible()
                            or not button.Parent
                            or not App.RaidChestAuto.IsActuallyVisible(button) then
                            finished = true
                            break
                        end
                        task.wait(0.08)
                    end
                end
            end
            if finished then break end
            task.wait(0.35)
        end

        if not finished then
            return fail("FINISH failed • " .. tostring(lastMethod))
        end
    end

    App.RaidChestAuto.Busy = false
    App.RaidChestAuto.Completed = true
    App.RaidChestAuto.Failed = false
    App.RaidChestAuto.Attempted = true
    App.RaidChestAuto.Status = "Done"
    return true
end

App.RaidChestAuto.WaitBeforeRetry = function(resultKind)
    if App.Values.RaidAutoOpenChests ~= true or tostring(resultKind) ~= "Raid" then
        return true
    end

    local openFree = App.Values.RaidOpenFreeChest == true
    local openPremium = App.Values.RaidOpenPremiumChest == true
    if not openFree and not openPremium then
        return true
    end

    -- V15.6.33: chest ownership gets first priority. Give the raid chest UI enough
    -- time to appear after the ending cutscene before retry/leave logic is released.
    local appeared = false
    local appearStarted = os.clock()
    while gui and gui.Parent and os.clock() - appearStarted < 8.0 do
        App.RaidChestAuto.ObserveButtons()
        if App.RaidChestAuto.ScreenVisible()
            or App.RaidChestAuto.ScreenActive
            or App.RaidChestAuto.Busy
            or App.RaidChestAuto.Attempted then
            appeared = true
            break
        end
        task.wait(0.10)
    end
    if not appeared then return true end

    if (tonumber(App.RaidChestAuto.SessionStartedAt) or 0) <= 0 then
        App.RaidChestAuto.SessionStartedAt = os.clock()
    end

    local deadline = os.clock() + 34.0
    local closedSince = nil
    while gui and gui.Parent and os.clock() < deadline do
        local visible = App.RaidChestAuto.ScreenVisible()
        if App.RaidChestAuto.Completed and not App.RaidChestAuto.Busy and not visible then
            closedSince = closedSince or os.clock()
            if os.clock() - closedSince >= 0.65 then return true end
        else
            closedSince = nil
        end
        task.wait(0.10)
    end

    -- Last-resort fail-open so one broken Roblox result UI cannot permanently lock
    -- an account. Invalidate any chest coroutine before retry is released.
    App.RaidChestAuto.GateExpired = true
    App.RaidChestAuto.Failed = true
    App.RaidChestAuto.Status = "Chest timeout • retry released"
    App.RaidChestAuto.Attempted = true
    App.RaidChestAuto.Busy = false
    App.RaidChestAuto.SessionNonce = (tonumber(App.RaidChestAuto.SessionNonce) or 0) + 1
    return true
end

task.spawn(function()
    while gui and gui.Parent do
        task.wait(App.PerformanceControl.Delay(0.28, 0.45))
        local visible = App.RaidChestAuto.ScreenVisible()
        if not visible then
            if App.RaidChestAuto.ScreenActive and not App.RaidChestAuto.Busy then
                App.RaidChestAuto.ResetScreen()
            end
            continue
        end

        App.RaidChestAuto.ScreenActive = true
        if (tonumber(App.RaidChestAuto.SessionStartedAt) or 0) <= 0 then
            App.RaidChestAuto.SessionStartedAt = os.clock()
        end
        App.RaidChestAuto.ObserveButtons()

        if App.Values.RaidAutoOpenChests ~= true or App.RaidChestAuto.GateExpired then
            continue
        end

        if not App.RaidChestAuto.Busy
            and not App.RaidChestAuto.Attempted
            and os.clock() >= (tonumber(App.RaidChestAuto.NextAttemptAt) or 0) then
            App.RaidChestAuto.RunSequence()
        end
    end
end)

