        ["76"] = {Name="Red Flare", StateKey="SkillRedFlare", Cooldown=30, Icon=15199519457},
        ["93"] = {Name="Order: Advance", StateKey="SkillOrderAdvance", Cooldown=55, Icon=15199519457},
        ["95"] = {Name="Black Flare", StateKey="SkillBlackFlare", Cooldown=35, Icon=15199519457},
        ["97"] = {Name="Order: Rage", StateKey="SkillOrderRage", Cooldown=85, Icon=15199519457},
        ["109"] = {Name="Rage Mode", StateKey="SkillRageMode", Cooldown=25, Icon=98235238958365, Family="Ackerman", Hold=0.10, Attempts=2, ConfirmTimeout=1.10, RetryDelay=0.30},
        ["104"] = {Name="Conquer", StateKey="SkillConquer", Cooldown=73, Icon=15199519457, Family="Reiss", Hold=0.08, Attempts=2, ConfirmTimeout=1.00, RetryDelay=0.25},
        ["103"] = {Name="Order: Command", StateKey="SkillOrderCommand", Cooldown=28, Icon=15199519457, Family="Reiss", Hold=0.075, Attempts=2, ConfirmTimeout=0.95, RetryDelay=0.25},
        ["163"] = {Name="Order: Revolution", StateKey="SkillOrderRevolution", Cooldown=135, Icon=105841954352921, Family="Helos"},
    },
    Passive = {
        ["155"] = {Name="Founder's Vengeance", Icon=15092461853, Family="Fritz"},
    },
    Detected = {},
    LastCast = {},
    LastAttempt = {},
    LastScanAt = 0,
    Busy = false,
    Status = "Off",
}

App.SkillAuto.SlotFromObject = function(object)
    local node = object

    for _ = 1, 7 do
        if not node or node == playerGui then break end

        local lowerName = string.lower(tostring(node.Name or ""))
        local byName = string.match(lowerName, "slot[_%- ]*([1-5])")
            or string.match(lowerName, "^([1-5])$")

        if byName then
            return tonumber(byName)
        end

        if node:IsA("GuiObject") then
            local size = node.AbsoluteSize
            if size.X >= 20 and size.Y >= 20 and size.X <= 220 and size.Y <= 220 then
                for _, child in ipairs(node:GetDescendants()) do
                    if child:IsA("TextLabel")
                        or child:IsA("TextButton")
                        or child:IsA("TextBox") then
                        local clean = string.gsub(tostring(child.Text or ""), "%s+", "")
                        local slot = tonumber(clean)
                        if slot and slot >= 1 and slot <= 5 then
                            return slot
                        end
                    end
                end
            end
        end

        node = node.Parent
    end

    return nil
end

App.SkillAuto.Scan = function(force)
    local now = os.clock()

    if not force
        and now - (tonumber(App.SkillAuto.LastScanAt) or 0) < 0.45 then
        return App.SkillAuto.Detected
    end

    App.SkillAuto.LastScanAt = now
    local detected = {}

    for _, object in ipairs(playerGui:GetDescendants()) do
        local skillId = nil
        pcall(function()
            skillId = object:GetAttribute("Skill")
        end)

        skillId = skillId ~= nil and tostring(skillId) or nil

        if skillId and App.SkillAuto.Skills[skillId] then
            local slot = App.SkillAuto.SlotFromObject(object)
            if slot then
                detected[skillId] = slot
            end
        elseif object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox") then

            local textValue =
                string.lower(
                    string.gsub(
                        tostring(object.Text or ""),
                        "%s+",
                        " "
                    )
                )

            if textValue ~= "" then
                for candidateId, info in pairs(App.SkillAuto.Skills) do
                    if not detected[candidateId]
                        and string.find(
                            textValue,
                            string.lower(tostring(info.Name or "")),
                            1,
                            true
                        ) then

                        local slot =
                            App.SkillAuto.SlotFromObject(object)

                        if slot then
                            detected[candidateId] = slot
                        end
                    end
                end
            end
        end
    end

    App.SkillAuto.Detected = detected

    local names = {}
    for skillId, slot in pairs(detected) do
        local info = App.SkillAuto.Skills[skillId]
        names[#names + 1] = tostring(info.Name) .. " [" .. tostring(slot) .. "]"
    end
    table.sort(names)

    if App.Values.AutoUseSkills ~= true then
        App.SkillAuto.Status = "Off"
    elseif #names > 0 then
        App.SkillAuto.Status = "Detected: " .. table.concat(names, " • ")
    else
        App.SkillAuto.Status = "No supported equipped active skills"
    end

    return detected
end

App.SkillAuto.KeyForSlot = function(slot)
    local map = {
        [1] = Enum.KeyCode.One,
        [2] = Enum.KeyCode.Two,
        [3] = Enum.KeyCode.Three,
        [4] = Enum.KeyCode.Four,
        [5] = Enum.KeyCode.Five,
    }
    return map[tonumber(slot)]
end

App.SkillAuto.CooldownValue = function(slot)
    if not slot then return nil end
    local value = nil
    pcall(function()
        value = player:GetAttribute("Skill_" .. tostring(slot))
    end)
    return value
end

App.SkillAuto.Ready = function(slot)
    local value = App.SkillAuto.CooldownValue(slot)

    if value == nil or value == false then
        return true
    end

    if type(value) == "number" then
        return value <= 0
    end

    if type(value) == "string" then
        local clean = string.lower(string.gsub(value, "%s+", ""))
        if clean == "" or clean == "ready" or clean == "false" then
            return true
        end
        local numeric = tonumber(string.match(clean, "[-%d%.]+"))
        if numeric then
            return numeric <= 0
        end
    end

    return false
end

App.SkillAuto.PressSlot = function(slot, holdSeconds)
    local key = App.SkillAuto.KeyForSlot(slot)
    if not key then return false end

    local hold = math.max(0.045, tonumber(holdSeconds) or 0.065)

    local ok = pcall(function()
        VirtualInputManager:SendKeyEvent(true, key, false, game)
        task.wait(hold)
        VirtualInputManager:SendKeyEvent(false, key, false, game)
    end)

    return ok
end

App.SkillAuto.WaitForCooldownStart = function(slot, timeout)
    local started = os.clock()
    local duration = math.max(0.25, tonumber(timeout) or 0.85)

    while os.clock() - started < duration do
        if not App.SkillAuto.Ready(slot) then
            return true
        end
        task.wait(0.05)
    end

    return not App.SkillAuto.Ready(slot)
end

App.SkillAuto.PausedByRuntime = function()
    if RuntimeKind ~= "Gameplay" then
        return true, "Gameplay only"
    end

    if App.TransitionGuard and App.TransitionGuard.BlockGameplay
        and App.TransitionGuard.BlockGameplay() then
        return true, tostring(App.TransitionGuard.Status or "Paused for transition")
    end

    if App.RaidChestAuto and App.RaidChestAuto.Busy then
        return true, "Paused for raid chests"
    end

    if App.BladeRefill and App.BladeRefill.Busy then
        return true, "Paused for blade refill"
    end

    if SpearRuntime and SpearRuntime.RefillBusy then
        return true, "Paused for spear refill"
    end

    if App.Cutscene and App.Cutscene.Active == true then
        return true, "Paused for cutscene"
    end

    if App.Values.AutoTitanMastery == true
        and App.TitanMastery
        and App.TitanMastery.IsShifted
        and App.TitanMastery.IsShifted() then
        return true, "Titan Mastery owns Shifter skills"
    end

    if App.Colossal and App.Colossal.TransitionActive then
        return true, "Paused for Colossal transition"
    end

    if App.Colossal
        and App.Colossal.Active
        and App.Colossal.Stage == "P1 CANNON STALL"
        and App.Colossal.Entered == true then
        return true, "Cannon mounted • skills wait for dismount"
    end

    return false, nil
end

App.SkillAuto.Step = function()
    if App.Values.AutoUseSkills ~= true then
        App.SkillAuto.Busy = false
        App.SkillAuto.Status = "Off"
        return false
    end

    local paused, reason = App.SkillAuto.PausedByRuntime()
    if paused then
        App.SkillAuto.Status = tostring(reason or "Paused")
        return false
    end

    if App.SkillAuto.Busy then
        return false
    end

    local detected = App.SkillAuto.Scan(false)
    local now = os.clock()


    -- Reiss first: exact priority used by the proven Booster Services build.
    local order = {"104", "103", "97", "93", "109", "163", "95", "76"}

    for _, skillId in ipairs(order) do
        local slot = detected[skillId]
        local info = App.SkillAuto.Skills[skillId]

        if slot and info and App.Values[info.StateKey] ~= false then
            local lastCast = tonumber(App.SkillAuto.LastCast[skillId]) or 0
            local lastAttempt = tonumber(App.SkillAuto.LastAttempt[skillId]) or 0
            local localGap = math.max(2.0, math.min(8.0, (tonumber(info.Cooldown) or 30) * 0.08))

            if (lastCast <= 0 or now - lastCast >= localGap)
                and (lastAttempt <= 0 or now - lastAttempt >= 1.25)
                and App.SkillAuto.Ready(slot) then

                App.SkillAuto.Busy = true
                App.SkillAuto.LastAttempt[skillId] = now
                App.SkillAuto.Status = "Casting " .. tostring(info.Name) .. " [" .. tostring(slot) .. "]"

                task.spawn(function()
                    local confirmed = false


                    local maxAttempts = math.max(1, math.floor(tonumber(info.Attempts) or (skillId == "97" and 3 or 2)))
                    local hold = tonumber(info.Hold) or (skillId == "97" and 0.12 or (skillId == "109" and 0.10 or 0.065))
                    local confirmTimeout = tonumber(info.ConfirmTimeout) or (skillId == "97" and 1.15 or (skillId == "109" and 1.10 or 0.85))
                    local retryDelay = tonumber(info.RetryDelay) or (skillId == "97" and 0.18 or 0.30)

                    for attempt = 1, maxAttempts do
                        if App.Values.AutoUseSkills ~= true then break end

                        App.SkillAuto.PressSlot(slot, hold)
                        confirmed = App.SkillAuto.WaitForCooldownStart(slot, confirmTimeout)

                        if confirmed then break end

                        if attempt < maxAttempts then
                            task.wait(retryDelay)
                            local refreshed = App.SkillAuto.Scan(true)
                            slot = refreshed[skillId] or slot
                        end
                    end

                    if confirmed then
                        App.SkillAuto.LastCast[skillId] = os.clock()
                        App.SkillAuto.Status = "Cast confirmed: " .. tostring(info.Name)
                    else
                        App.SkillAuto.Status = "Cast not accepted: " .. tostring(info.Name)
                    end

                    App.SkillAuto.Busy = false
                end)

                return true
            end
        end
    end

    if next(detected) == nil then
        App.SkillAuto.Status = "No supported equipped active skills"
    end

    return false
end

task.spawn(function()
    while player and player.Parent do
        task.wait(0.35)
        local ok, err = pcall(App.SkillAuto.Step)
        if not ok then
            App.SkillAuto.Busy = false
            App.SkillAuto.Status = "Skill engine error: " .. tostring(err)
        end
    end
end)


local function applyPerformancePreset(name)


    if RuntimeKind == "MainMenu" then
        return
    end

    name = tostring(name or "Balanced")
    App.Values.OptPreset = name

    if name == "Quality" then
        App.Values.SimpleLighting = false
        App.Values.RemoveFog = false
        App.Values.DisableParticlesTrails = false
        App.Values.LowDetailMaterials = false
        App.Values.RemoveMapTextures = false
        App.Values.RemoveMapProps = false
        App.Values.ReduceTitanEffects = false
        App.Values.DisableCameraEffects = false

    elseif name == "Performance" then
        App.Values.SimpleLighting = true
        App.Values.RemoveFog = true
        App.Values.DisableParticlesTrails = true
        App.Values.LowDetailMaterials = true
        App.Values.RemoveMapTextures = true
        App.Values.RemoveMapProps = true
        App.Values.ReduceTitanEffects = true
        App.Values.DisableCameraEffects = true

    else
        App.Values.OptPreset = "Balanced"
        App.Values.SimpleLighting = true
        App.Values.RemoveFog = true
        App.Values.DisableParticlesTrails = true
        App.Values.LowDetailMaterials = false
        App.Values.RemoveMapTextures = false
        App.Values.RemoveMapProps = false
        App.Values.ReduceTitanEffects = true
        App.Values.DisableCameraEffects = true
    end

    applySimpleLighting(App.Values.SimpleLighting)
    applyRemoveFog(App.Values.RemoveFog)
    applyDisableParticlesTrails(App.Values.DisableParticlesTrails)
    applyLowDetailMaterials(App.Values.LowDetailMaterials)
    applyRemoveMapTextures(App.Values.RemoveMapTextures)
    applyRemoveMapProps(App.Values.RemoveMapProps)
    applyReduceTitanEffects(App.Values.ReduceTitanEffects)
    applyDisableCameraEffects(App.Values.DisableCameraEffects)
end

-- V15.6.6: apply saved optimization immediately; do not wait for first farm/camera release.
if RuntimeKind ~= "MainMenu" then
    pcall(applyPerformancePreset, App.Values.OptPreset)
end


local function getV12QueueFunction()
    local env = v12Environment()

    local candidates = {
        env and env.queue_on_teleport,
        env and env.queueonteleport,
        env and env.queue_on_tp,
        type(syn) == "table" and syn.queue_on_teleport or nil,
        type(fluxus) == "table" and fluxus.queue_on_teleport or nil,
        type(_G) == "table" and _G.queue_on_teleport or nil,
        type(_G) == "table" and _G.queueonteleport or nil,
    }

    for _, fn in ipairs(candidates) do
        if type(fn) == "function" then
            return fn
        end
    end

    return nil
end

local function resolveV12Bootstrap()
    local _, _, _, isFile = v12FileFunctions()
    local env = v12Environment()
    local hub = type(env.SliceHub) == "table" and env.SliceHub or nil
    local tier =
        App.FamilySpin.IsPremium()
        and "PREMIUM"
        or "FREE"

    local preferred = tier == "PREMIUM" and "SH/Needed Stuff/runtime/bootstrap_premium.shc" or "SH/Needed Stuff/runtime/bootstrap_free.shc"

    if type(isFile) == "function" then
        local ok, exists = pcall(isFile, preferred)
        if ok and exists then return preferred, tier end
    end

    return preferred, tier
end

local function queueV12AutoExecute(force)
    if V12Config.QueuedForTeleport then
        return true, "Already queued"
    end

    if force ~= true and App.Values.AutoExecuteOnTeleport ~= true then
        return false, "Disabled"
    end

    if os.clock() - (V12Config.LastQueueAt or 0) < 0.75 then
        return true, "Already queued"
    end

    local queueFn = getV12QueueFunction()
    if not queueFn then
        return false, "queue_on_teleport unavailable"
    end

    local bootstrap, tier = resolveV12Bootstrap()
    local kaitunExpression="nil"
    if V12Config.KaitunActive==true and type(V12Config.KaitunCarryCode)=="string" and V12Config.KaitunCarryCode~="" then
        kaitunExpression="{Config="..string.format("%q",V12Config.KaitunCarryCode)..",AutoExecuteOnTeleport=true}"
    end

    local code = string.format([[
repeat task.wait(0.10) until game:IsLoaded()
 local environment = type(getgenv) == "function" and getgenv() or _G
local bootOwner = tostring(game.JobId or "") .. "|" .. %q
if environment.__SliceHubAOTRAutoBootOwner == bootOwner
    and type(environment.__SliceHubActiveShutdown) == "function" then return end
local function runtimeReady()
    return environment.__SliceHubAOTRAutoBootOwner == bootOwner
