    local isFile = (env and env.isfile) or (type(isfile) == "function" and isfile or nil)
    local deleteFile = (env and env.delfile) or (type(delfile) == "function" and delfile or nil)
    local folders = {"autoexec", "autoexecute", "Autoexec", "AutoExecute"}


    if type(deleteFile) == "function" then
        for _, folder in ipairs(folders) do
            local path = folder .. "/SliceHub_AOTR.lua"
            local shouldDelete = true
            if type(isFile) == "function" then
                local okExists, exists = pcall(isFile, path)
                shouldDelete = okExists and exists == true
            end
            if shouldDelete then pcall(deleteFile, path) end
        end
    end

    local installedFolder = nil
    local queueAvailable = type(getV12QueueFunction()) == "function"
    -- V15.6.32: keep a delayed executor autoexec copy even when queue_on_teleport
