    if type(deleteFile) ~= "function" then return false end

    local paths = {
        "SH/SliceHub_AutoExecute.lua",
        "autoexec/SliceHub_AOTR.lua",
        "autoexecute/SliceHub_AOTR.lua",
        "Autoexec/SliceHub_AOTR.lua",
        "AutoExecute/SliceHub_AOTR.lua",
    }
    for _, path in ipairs(paths) do
        local shouldDelete = true
        if type(isFile) == "function" then
            local okExists, exists = pcall(isFile, path)
            shouldDelete = okExists and exists == true
        end
        if shouldDelete then pcall(deleteFile, path) end
    end
    return true
