App.TeleportTrace.Record = function(source, reason)
    App.TeleportTrace.LastSource = tostring(source or "UNKNOWN")
    App.TeleportTrace.LastReason = tostring(reason or "")
    App.TeleportTrace.LastAt = os.time()
    local remaining = math.max(0, math.ceil((tonumber(App.Failsafe and App.Failsafe.Deadline) or 0) - os.clock()))
    local traceText =
        "time=" .. tostring(App.TeleportTrace.LastAt)
        .. "\nsource=" .. App.TeleportTrace.LastSource
        .. "\nreason=" .. App.TeleportTrace.LastReason
        .. "\nfailsafeRemaining=" .. tostring(remaining)
    print(
        "[SliceHub][TELEPORT]",
        "source=" .. App.TeleportTrace.LastSource,
        "reason=" .. App.TeleportTrace.LastReason,
        "failsafeRemaining=" .. tostring(remaining)
    )
    if type(makefolder) == "function" then pcall(makefolder, "SH") end
    if type(writefile) == "function" then
        pcall(writefile, "SH/last_teleport.txt", traceText)
    end
end

App.Failsafe = App.Failsafe or {
    Deadline = 0,
    Triggering = false,
    LastMinutes = nil,
    LastReason = "Idle",
    SmartState = "Idle",
    SmartSince = 0,
    SmartDetail = "Waiting",
    SmartRecoveries = 0,
    LastPublicRecovery = "None",
    LastPublicRecoveryAt = 0,
}

App.Failsafe.Minutes = function()
    App.Values.FailsafeMinutes = math.clamp(
        math.floor((tonumber(App.Values.FailsafeMinutes) or 5) + 0.5),
        1,
        1440
    )
    return App.Values.FailsafeMinutes
end

App.Failsafe.Reset = function(reason)
    App.Failsafe.Deadline = 0
    App.Failsafe.Triggering = false
    App.Failsafe.LastMinutes = nil
    App.Failsafe.LastReason = tostring(reason or "Reset")
    App.Failsafe.SmartState = "Idle"
    App.Failsafe.SmartSince = 0
    App.Failsafe.SmartDetail = "Waiting"
end

App.Failsafe.Arm = function(reason)
    if App.Values.FailsafeEnabled ~= true then
        App.Failsafe.Reset("Disabled")
        return false
    end

    local minutes = App.Failsafe.Minutes()
    App.Failsafe.Deadline = os.clock() + minutes * 60
    App.Failsafe.Triggering = false
    App.Failsafe.LastMinutes = minutes
    App.Failsafe.LastReason = tostring(reason or "Armed")
    return true
end

App.Failsafe.PublicReason = function(reason)
    local text = string.lower(tostring(reason or ""))
    if string.find(text, "result", 1, true) then return "Result stalled" end
    if string.find(text, "loading", 1, true) or string.find(text, "camera", 1, true) then return "Loading stalled" end
    if string.find(text, "respawn", 1, true) or string.find(text, "dead", 1, true) then return "Respawn stalled" end
    if string.find(text, "launch", 1, true) then return "Launch stalled" end
    if string.find(text, "timeout", 1, true) then return "Hard timeout" end
    return "Runtime stalled"
end

App.Failsafe.StatusText = function()
    if App.Values.FailsafeEnabled ~= true then return "Off" end
    if App.Failsafe.Triggering then return "Recovering" end
    if (App.Failsafe.Deadline or 0) <= 0 then return "Arming" end

    local remaining = math.max(0, math.ceil(App.Failsafe.Deadline - os.clock()))
    local hardText = string.format("%dm %02ds", math.floor(remaining / 60), remaining % 60)

    if App.Values.FailsafeSmart == true
        and tostring(App.Failsafe.SmartState or "Idle") ~= "Idle"
        and tostring(App.Failsafe.SmartState or "Idle") ~= "Healthy" then
        local age = math.max(0, math.floor(os.clock() - (tonumber(App.Failsafe.SmartSince) or os.clock())))
        return "Watch " .. tostring(age) .. "s • " .. hardText
    end

    return "Armed • " .. hardText
end

App.Failsafe.StatusKind = function()
    if App.Values.FailsafeEnabled ~= true then return "muted" end
    if App.Failsafe.Triggering then return "warn" end
    if App.Values.FailsafeSmart == true
        and tostring(App.Failsafe.SmartState or "Idle") ~= "Idle"
        and tostring(App.Failsafe.SmartState or "Idle") ~= "Healthy" then return "warn" end
    return "good"
end

App.Failsafe.LastRecoveryText = function()
    if tostring(App.Failsafe.LastPublicRecovery or "None") == "None" then return "None" end
    local stamp = tonumber(App.Failsafe.LastPublicRecoveryAt) or 0
    local suffix = stamp > 0 and (" • " .. os.date("%H:%M", stamp)) or ""
    return tostring(App.Failsafe.LastPublicRecovery) .. suffix
end

App.Failsafe.Trigger = function(reason)
    if App.Failsafe.Triggering then return false, "already triggering" end
    App.Failsafe.Triggering = true
    App.Failsafe.LastReason = tostring(reason or "Failsafe timeout")
    if App.RunState then
        local data = App.RunState.Data or App.RunState.Load()
        if type(data) == "table" then
            data.Recoveries = math.max(0, (tonumber(data.Recoveries) or 0) + 1)
            data.Hourly = type(data.Hourly) == "table" and data.Hourly or {}
            data.Hourly.Failsafes = math.max(0, (tonumber(data.Hourly.Failsafes) or 0) + 1)
            data.Hourly.Reconnects = math.max(0, (tonumber(data.Hourly.Reconnects) or 0) + 1)
            pcall(App.RunState.Save)
        end
    end
    App.Failsafe.LastPublicRecovery = App.Failsafe.PublicReason(App.Failsafe.LastReason)
    App.Failsafe.LastPublicRecoveryAt = os.time()


    pcall(V12Config.SaveMetadataOnly)

    if App.Values.AutoExecuteOnTeleport == true then
        V12Config.QueuedForTeleport = false
        pcall(queueV12AutoExecute, true)
    end

    App.TeleportTrace.Record("FAILSAFE", App.Failsafe.LastReason)
    local ok, err = pcall(function()
        TeleportService:Teleport(13379208636, player)
    end)

    if not ok then
        App.Failsafe.Triggering = false
        App.Failsafe.LastReason = "Teleport failed • " .. tostring(err)
        if App.AFKManager then App.AFKManager.MarkAttention("Recovery could not complete") end
        App.Failsafe.Arm("Retry after teleport failure")
        return false, tostring(err)
    end

    return true, "Returning to Main Menu"
end

