    if App.Failsafe.Triggering then
        App.Failsafe.Triggering = false
        App.Failsafe.LastReason = "TeleportInitFailed • " .. tostring(errorMessage or result)
        if App.Values.FailsafeEnabled == true then
            App.Failsafe.Arm("Retry after TeleportInitFailed")
        end
    end
end))

task.spawn(function()
    task.wait(0.75)
    if App.Values.FailsafeEnabled == true then
        App.Failsafe.Arm("Startup")
    end

    while gui and gui.Parent do
        if App.Values.FailsafeEnabled == true then
            local minutes = App.Failsafe.Minutes()
            if (App.Failsafe.Deadline or 0) <= 0
                or App.Failsafe.LastMinutes ~= minutes then
                App.Failsafe.Arm("Settings changed")
            elseif not App.Failsafe.Triggering
                and os.clock() >= App.Failsafe.Deadline then
                App.Failsafe.Trigger("Failsafe timeout")
            end
        elseif (App.Failsafe.Deadline or 0) > 0
            or App.Failsafe.Triggering then
            App.Failsafe.Reset("Disabled")
        end
        task.wait(0.25)
    end
end)

local returnToLobbyFromMission

local MissionLoop = {
    ActiveResultSerial = 0,
    HandledSerial = 0,
    ResultVisible = false,
    Busy = false,
    Suppressed = false,
    RetryToken = 0,
    LastTransitionMethod = nil,
}

local RESULT_STATES = {
    ["mission completed"] = "Mission Completed",
    ["mission complete"] = "Mission Completed",
    ["mission failed"] = "Mission Failed",
    ["raid completed"] = "Raid Completed",
    ["raid complete"] = "Raid Completed",
    ["raid failed"] = "Raid Failed",
    ["waves completed"] = "Waves Completed",
    ["wave completed"] = "Waves Completed",
    ["waves failed"] = "Waves Failed",
    ["wave failed"] = "Waves Failed",
}

MissionLoop.NormalizeResultState = function(text)
    text = string.lower(tostring(text or ""))
    local exact = RESULT_STATES[text]
    if exact then return exact end

    -- Waves uses "WAVES FINISHED [6]" / similar numbered result labels.
    if string.match(text, "^waves?%s+finished")
        or string.match(text, "^waves?%s+complete") then
        return "Waves Completed"
    end
    if string.match(text, "^waves?%s+failed")
        or string.match(text, "^waves?%s+defeated") then
        return "Waves Failed"
    end
    return nil
end

MissionLoop.ResultKind = function(resultInfo)
    local state = string.lower(tostring(resultInfo and resultInfo.State or ""))
    if string.find(state, "raid", 1, true) then return "Raid" end
    if string.find(state, "wave", 1, true) then return "Waves" end
    return "Mission"
end

MissionLoop.RetryEnabled = function(resultInfo)
    local kind = MissionLoop.ResultKind(resultInfo)
    if kind == "Mission" then return App.Values.MissionAutoRetry == true end
    if kind == "Raid" then return App.Values.RaidRetry == true end
    return false
end


local function missionGuiActuallyVisible(object)
    if not object or not object:IsA("GuiObject") then return false end
    local node = object
    while node and node ~= playerGui do
        if node:IsA("GuiObject") and node.Visible == false then return false end
        if node:IsA("ScreenGui") and node.Enabled == false then return false end
        node = node.Parent
    end
    local size = object.AbsoluteSize
    return size.X > 0 and size.Y > 0
end

local function missionText(object)
    if object and (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
        local text = tostring(object.Text or "")
        text = string.gsub(text, "<[^>]->", "")
        text = string.gsub(text, "^%s+", "")
        text = string.gsub(text, "%s+$", "")
        text = string.gsub(text, "%s+", " ")
        return text
    end
    return nil
end

local ResultPanelScanCache = {
    At = 0,
    Value = nil,
}

local function exactResultPanel()
    local interface = playerGui:FindFirstChild("Interface")
    local rewards = interface and interface:FindFirstChild("Rewards")
    local main = rewards and rewards:FindFirstChild("Main")
    local info = main and main:FindFirstChild("Info")
    local state = info and info:FindFirstChild("State")

    local function corroborates(root, stateObject)
        if not root then return false end

        for _, object in ipairs(root:GetDescendants()) do
            if object ~= stateObject
                and missionGuiActuallyVisible(object) then

                local value =
                    string.lower(
                        tostring(
                            missionText(object)
                            or ""
                        )
                    )

                if value == "stats"
                    or value == "obtained"
                    or string.find(value, "retry", 1, true)
                    or string.find(value, "leave", 1, true)
                    or string.find(value, "time taken", 1, true)
                    or string.find(value, "damage dealt", 1, true)
                    or string.find(value, "titans killed", 1, true) then
                    return true
                end
            end
        end

        return false
    end

    -- Fast path: the normal AOT:R rewards hierarchy is a handful of direct
    -- lookups and remains checked every result-loop tick.
    if state and missionGuiActuallyVisible(state) then
        local lower =
            string.lower(
                tostring(
                    missionText(state)
                    or ""
                )
            )

        local normalized =
            MissionLoop.NormalizeResultState(lower)

        if normalized
            and corroborates(rewards, state) then

            local value = {
                Root = rewards,
                StateObject = state,
                StateLower = lower,
                State = normalized,
            }

            ResultPanelScanCache.Value = value
            ResultPanelScanCache.At = os.clock()
            return value
        end
    end

    -- Slow fallback: the old build walked the entire PlayerGui up to 10 times
    -- per second whenever the direct rewards path was absent.
    local now = os.clock()
    local fallbackDelay =
        App.PerformanceControl
        and App.PerformanceControl.IsLowPower
        and App.PerformanceControl.IsLowPower()
        and 0.75
        or 0.45

    if now - (tonumber(ResultPanelScanCache.At) or 0)
        < fallbackDelay then

        local cached = ResultPanelScanCache.Value
        if cached
            and cached.StateObject
            and cached.StateObject.Parent
            and missionGuiActuallyVisible(
                cached.StateObject
            ) then
            return cached
        end

        return nil
    end

    ResultPanelScanCache.At = now
    ResultPanelScanCache.Value = nil

    for _, object in ipairs(playerGui:GetDescendants()) do
        if (
            object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox")
        )
            and missionGuiActuallyVisible(object) then

            local lower =
                string.lower(
                    tostring(
                        missionText(object)
                        or ""
                    )
                )

            local normalized =
                MissionLoop.NormalizeResultState(lower)

            if normalized then
                local root =
                    object:FindFirstAncestorOfClass(
                        "ScreenGui"
                    )
                    or rewards
                    or playerGui

                if corroborates(root, object) then
                    local value = {
                        Root = root,
                        StateObject = object,
                        StateLower = lower,
                        State = normalized,
                    }

                    ResultPanelScanCache.Value = value
                    return value
                end
            end
        end
    end

    return nil
end


App.TransitionGuard.FindRetryButton = function(root)
    local interface = playerGui:FindFirstChild("Interface")
    local rewards = interface and interface:FindFirstChild("Rewards")
    local main = rewards and rewards:FindFirstChild("Main")
    local info = main and main:FindFirstChild("Info")
    local inner = info and info:FindFirstChild("Main")
    local buttons = inner and inner:FindFirstChild("Buttons")
    local exact = buttons and buttons:FindFirstChild("Retry")

    if exact and exact:IsA("GuiObject") and missionGuiActuallyVisible(exact) then
        return exact
    end

    local best, bestY = nil, -math.huge
    local scanRoot = root or playerGui
    for _, object in ipairs(scanRoot:GetDescendants()) do
        local text = missionText(object)
        local name = string.lower(tostring(object.Name or ""))
        local isRetry = name == "retry"
            or (text and string.find(string.lower(text), "retry", 1, true) ~= nil)
        if isRetry and missionGuiActuallyVisible(object) then
            local node = object
            for _ = 1, 8 do
                if not node or node == playerGui then break end
                if node:IsA("GuiButton") then break end
                node = node.Parent
            end
            local candidate = node and node:IsA("GuiButton") and node or object
            if candidate:IsA("GuiObject") and candidate.AbsolutePosition.Y > bestY then
                best, bestY = candidate, candidate.AbsolutePosition.Y
            end
        end
    end
    if not best and root ~= playerGui then return App.TransitionGuard.FindRetryButton(playerGui) end
    return best
end

App.TransitionGuard.RetryTargetButton = function(object)
    if not object then return nil end
    if object:IsA("GuiButton") then return object end

    for _, child in ipairs(object:GetDescendants()) do
        if child:IsA("GuiButton") and missionGuiActuallyVisible(child) then
            return child
        end
    end

    local node = object
    for _ = 1, 8 do
        if not node or node == playerGui then break end
        if node:IsA("GuiButton") then return node end
        node = node.Parent
    end
    return object:IsA("GuiObject") and object or nil
end

App.TransitionGuard.GameplayReady = function()
    if RuntimeKind ~= "Gameplay" or exactResultPanel() ~= nil then return false end
    if App.Cutscene and App.Cutscene.Active == true then return false end

    local character = player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then return false end

    local camera = workspace.CurrentCamera
    if camera and camera.CameraType == Enum.CameraType.Scriptable then return false end

    local interface = playerGui:FindFirstChild("Interface")
    local hud = interface and interface:FindFirstChild("HUD")
    if not hud then return false end

    if hud:IsA("GuiObject") and missionGuiActuallyVisible(hud) then return true end
    for _, object in ipairs(hud:GetDescendants()) do
        if object:IsA("GuiObject") and missionGuiActuallyVisible(object) then
            return true
        end
    end
    return false
end

App.TransitionGuard.Recover = function(reason)
    if App.TransitionGuard.Recovering == true then return false end
    App.TransitionGuard.Recovering = true
    App.TransitionGuard.Status = tostring(reason or "Retry transition stalled")
    App.Values.MissionLoopStatus = App.TransitionGuard.Status

    if App.RunState then App.RunState.MarkResetAfterLobby() end
    if App.Values.AutoExecuteOnTeleport == true then pcall(queueV12AutoExecute, true) end

    task.spawn(function()
        local ok = false
        if type(returnToLobbyFromMission) == "function" then
            local callOk, result = pcall(returnToLobbyFromMission, App.TransitionGuard.Status, "TRANSITION_GUARD")
            ok = callOk == true and result == true
        end
        if not ok then
            App.TransitionGuard.Recovering = false
            App.TransitionGuard.Status = "Retry recovery not accepted"
        end
    end)
    return true
end

App.TransitionGuard.HasRetryTransitionSignal = function()
    local current = exactResultPanel()
    if not current or not current.Root then return true end

    for _, child in ipairs(current.Root:GetDescendants()) do
        local value = missionText(child)
        if value and missionGuiActuallyVisible(child) then
            local lower = string.lower(value)
            if string.find(lower, "starting", 1, true)
                or string.find(lower, "teleporting", 1, true)
                or string.find(lower, "loading", 1, true)
                or string.find(lower, "joining", 1, true) then
                return true
            end
        end
    end
    return false
end

App.TransitionGuard.Step = function()
    local guard = App.TransitionGuard
    local now = os.clock()

    if guard.ResultActive == true then
        guard.StableSince = 0

        if guard.RetryArmed == true then
            if App.TransitionGuard.HasRetryTransitionSignal() then
                guard.ProgressSince = guard.ProgressSince > 0 and guard.ProgressSince or now
                guard.FailureSince = 0
                guard.InvalidSoloSince = 0
                guard.Status = "Retry transition started • waiting for load"
                App.Values.MissionLoopStatus = guard.Status

                if now - guard.ProgressSince >= 18.0 then
                    App.TransitionGuard.Recover("Retry transition stalled • returning to Town Central")
                end
            else
                guard.ProgressSince = 0
                local retrySince = guard.RetryAcceptedAt > 0 and guard.RetryAcceptedAt or guard.FailureSince
                if retrySince > 0 and now - retrySince >= 10.0 then
                    App.TransitionGuard.Recover("Retry unchanged for 10s • returning to Town Central")
                end
            end
        end
        return
    end

    if guard.RetryArmed ~= true then return end

    if App.TransitionGuard.GameplayReady() then
        guard.StableSince = guard.StableSince > 0 and guard.StableSince or now
        if now - guard.StableSince >= 0.90 then
            guard.RetryArmed = false
            guard.RetryAcceptedAt = 0
            guard.ResultGoneAt = 0
            guard.FailureSince = 0
            guard.InvalidSoloSince = 0
            guard.ProgressSince = 0
            guard.StableSince = 0
            guard.Recovering = false
            guard.Status = "Running • transition verified"
            if App.RunState then App.RunState.BeginRun(true) end
            App.Values.MissionLoopStatus = "Running • waiting for result"
        end
        return
    end

    guard.StableSince = 0
    if guard.RetryAcceptedAt > 0 and now - guard.RetryAcceptedAt >= 18.0 then
        App.TransitionGuard.Recover("Retry transition stalled • returning to Town Central")
    end
end

App.TransitionGuard.ClickRetryVerified = function(resultInfo, token)
    if App.Values.AutoExecuteOnTeleport == true then
        pcall(queueV12AutoExecute, true)
    end

    local target = App.TransitionGuard.RetryTargetButton(
        App.TransitionGuard.FindRetryButton(resultInfo.Root)
    )
    if not target then return false, "Retry button unavailable" end

    local canActivate = false
    local centerX, centerY = nil, nil
    local insetX, insetY = 0, 0
    local wasVisible = false
    local oldMouseIcon = true
    local previousSelected = nil

    pcall(function()
        canActivate = target:IsA("GuiButton")
        local pos = target.AbsolutePosition
        local size = target.AbsoluteSize
        centerX = math.floor(pos.X + size.X * 0.5 + 0.5)
        centerY = math.floor(pos.Y + size.Y * 0.5 + 0.5)
        local inset = GuiService:GetGuiInset()
        insetX, insetY = inset.X, inset.Y
        wasVisible = shell.Visible
        oldMouseIcon = UserInputService.MouseIconEnabled
        previousSelected = GuiService.SelectedObject
    end)

    if not canActivate then return false, "Retry button unavailable" end

    local teleportStarted = {Value = false}
    local teleportConnection = nil
    pcall(function()
        teleportConnection = player.OnTeleport:Connect(function()
            teleportStarted.Value = true
        end)
    end)

    local function cleanup()
        if teleportConnection then
            pcall(function() teleportConnection:Disconnect() end)
        end
        teleportConnection = nil
    end

    local function waitTeleport(timeout)
        local started = os.clock()
        while os.clock() - started < math.max(0.05, tonumber(timeout) or 0.5) do
            if token ~= MissionLoop.RetryToken then return false end
            if teleportStarted.Value == true then return true end
            task.wait(0.06)
        end
        return teleportStarted.Value == true
    end

    -- V15.6.19: restore the pre-V3 Retry dispatcher. Do not special-case 0/1.
    local nativeOk = pcall(function()
        target:Activate()
    end)
    if nativeOk and waitTeleport(0.38) then
        cleanup()
        return true, "native"
    end

    local keyboardOk = pcall(function()
        GuiService.SelectedObject = target
        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
        task.wait(0.055)
        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
    end)
    if keyboardOk and waitTeleport(0.55) then
        pcall(function() GuiService.SelectedObject = previousSelected end)
        cleanup()
        return true, "keyboard"
    end
    pcall(function() GuiService.SelectedObject = previousSelected end)

    local mouseOk = false
    if centerX and centerY then
        pcall(function()
            shell.Visible = false
            UserInputService.MouseIconEnabled = true
        end)
        task.wait(0.035)

        mouseOk = pcall(function()
            VirtualInputManager:SendMouseMoveEvent(centerX + insetX, centerY + insetY, game)
            task.wait(0.035)
            VirtualInputManager:SendMouseButtonEvent(centerX + insetX, centerY + insetY, 0, true, game, 0)
            task.wait(0.065)
            VirtualInputManager:SendMouseButtonEvent(centerX + insetX, centerY + insetY, 0, false, game, 0)
        end)

        if mouseOk and waitTeleport(1.20) then
            pcall(function()
                shell.Visible = wasVisible and not App.Hidden
                if not App.Values.ScriptCursor then UserInputService.MouseIconEnabled = oldMouseIcon end
            end)
            cleanup()
            return true, "mouse"
        end
    end

    pcall(function()
        shell.Visible = wasVisible and not App.Hidden
        if not App.Values.ScriptCursor then UserInputService.MouseIconEnabled = oldMouseIcon end
    end)
    cleanup()

    if nativeOk or keyboardOk or mouseOk then
        return true, "dispatched • 10s watchdog"
    end
    return false, "Retry was not accepted"
end

local function missionLimitValue()
    return math.clamp(math.floor((tonumber(App.Values.MissionLimit) or 0) + 0.5), 0, 250)
end

local function processMissionResult(resultInfo, serial)
    if MissionLoop.Busy or serial <= MissionLoop.HandledSerial then return end
    MissionLoop.HandledSerial = serial
    MissionLoop.Busy = true
    MissionLoop.RetryToken += 1
    local token = MissionLoop.RetryToken
    local resultKind = MissionLoop.ResultKind(resultInfo)

    App.Values.MissionLastResult = resultInfo.State

    local count, completionSeconds, duplicate =
        App.RunState.CountResult(resultInfo.State)

    if App.SliceTrack and type(App.SliceTrack.Trigger) == "function" then
        App.SliceTrack.Trigger(0.65)
    end

    local limit = missionLimitValue()

    local webhookQueued = false
    if App.Webhook
        and App.Values.WebhookEnabled == true then
        local okQueue, queued = pcall(
            App.Webhook.QueueResult,
            resultInfo,
            serial,
            count,
            limit,
            completionSeconds
        )
        webhookQueued = okQueue and queued == true
    end

    if webhookQueued then
        -- Fast retry/teleport can destroy the executor task before the relay
        -- receives the result. Hold the transition for a bounded delivery window.
        App.Values.WebhookStatus = "Sending result • holding transition"
        pcall(App.Webhook.WaitForResultDispatch, 3.5)
    end

    if resultKind == "Mission" and limit > 0 and count >= limit then
        MissionLoop.Suppressed = true
        App.Values.MissionLoopStatus = "Mission limit reached"
        setStatus("Mission limit reached • Run " .. tostring(count) .. " / " .. tostring(limit))
        toast("AFK Manager", "Mission limit reached • " .. tostring(count) .. " / " .. tostring(limit))
        MissionLoop.Busy = false
        if App.AFKManager then
            App.AFKManager.HandleLimit("Mission limit reached")
        else
            App.RunState.MarkResetAfterLobby()
            task.spawn(returnToLobbyFromMission, "Mission limit reached • returning to Town Central", "MISSION_LIMIT")
        end
        return
    end

    if not MissionLoop.RetryEnabled(resultInfo) then
        App.TransitionGuard.RetryArmed = false
        App.TransitionGuard.FailureSince = 0
        App.TransitionGuard.InvalidSoloSince = 0
        App.Values.MissionLoopStatus = resultKind .. " result counted • Auto Retry off"
        MissionLoop.Busy = false
        return
    end

    if resultKind == "Raid" and App.RaidChestAuto and type(App.RaidChestAuto.WaitBeforeRetry) == "function" then
        App.RaidChestAuto.WaitBeforeRetry(resultKind)
    end

    App.Values.MissionLoopStatus = resultKind .. " result confirmed • settling retry UI"
    App.TransitionGuard.RetryArmed = true
    App.TransitionGuard.RetryAcceptedAt = 0
    App.TransitionGuard.FailureSince = 0
    App.TransitionGuard.InvalidSoloSince = 0
    App.TransitionGuard.ProgressSince = 0
    App.TransitionGuard.Status = "Result • automation suspended"
    task.wait(1.05)
    if token ~= MissionLoop.RetryToken or exactResultPanel() == nil then MissionLoop.Busy = false; return end

    App.Values.MissionLoopStatus = resultKind .. " • Retrying…"
    local success, method = App.TransitionGuard.ClickRetryVerified(resultInfo, token)
    if token ~= MissionLoop.RetryToken then MissionLoop.Busy = false; return end

    if success then
        MissionLoop.LastTransitionMethod = method
        App.TransitionGuard.RetryAcceptedAt = os.clock()
        App.TransitionGuard.FailureSince = 0
        App.TransitionGuard.InvalidSoloSince = 0
        App.TransitionGuard.ProgressSince = 0
        App.TransitionGuard.Status = "Retry accepted • waiting for new run"
        App.Values.MissionLoopStatus = resultKind .. " • Retry accepted • waiting for transition"
    else
        local failure = tostring(method or "Retry did not start")
        App.Values.MissionLoopStatus = failure
        App.TransitionGuard.FailureSince = os.clock()
        App.TransitionGuard.Status = failure
        if App.AFKManager and App.Values.FailsafeEnabled ~= true then
            App.AFKManager.MarkAttention("Automation could not continue")
        end
    end
    MissionLoop.Busy = false
end

local function missionLoopStep()
    local resultInfo = exactResultPanel()
    if resultInfo then
        App.TransitionGuard.ResultActive = true
        App.TransitionGuard.Status = App.TransitionGuard.RetryArmed and App.TransitionGuard.Status or "Result • automation suspended"
        if not MissionLoop.ResultVisible then
            MissionLoop.ResultVisible = true
            MissionLoop.ActiveResultSerial += 1

            task.spawn(processMissionResult, resultInfo, MissionLoop.ActiveResultSerial)
        end
    elseif MissionLoop.ResultVisible then
        MissionLoop.RetryToken += 1
        MissionLoop.ResultVisible = false
        MissionLoop.Busy = false
        App.TransitionGuard.ResultActive = false
        if App.TransitionGuard.RetryArmed then
            App.TransitionGuard.ResultGoneAt = os.clock()
            App.TransitionGuard.Status = "Result closed • verifying new run"
            App.Values.MissionLoopStatus = "Retry transition • verifying new run"
        elseif not MissionLoop.Suppressed then
            App.RunState.BeginRun(true)
            App.Values.MissionLoopStatus =
                (App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true)
                and "Running • waiting for result"
                or "Auto Retry off"
        end
    elseif App.TransitionGuard.ResultActive then
        App.TransitionGuard.ResultActive = false
    end

    App.TransitionGuard.Step()

    local count, limit = math.max(0, math.floor(tonumber(App.Values.MissionRunCount) or 0)), missionLimitValue()
    if MissionLoop.Suppressed then
        setStatus("Mission limit reached • " .. tostring(count) .. " / " .. tostring(limit))
    elseif App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true then
        setStatus("Result Loop • " .. tostring(App.Values.MissionLoopStatus))
    end
end



local LobbyRuntime = {
    Busy = false,
    TeleportSeen = false,
    AutoLaunchToken = 0,
    AutoLaunchAttempted = false,
    AutoLaunchPaused = false,
    AutoLaunchFailures = 0,
    AutoLaunchLastAttemptAt = 0,
    CountdownActive = false,
    PartyCleanupStatus = "Ready",
    InternalStatus = "Idle",
    LastInternalError = nil,
}


LobbyRuntime.SetPublicStatus = function(text, kind)
    App.Values.LobbyStatus = tostring(text or "Waiting")
    App.Values.LobbyStatusKind = tostring(kind or "waiting")
end

LobbyRuntime.InternalMapNames = {
    ["Shiganshina"] = "Shiganshina",
    ["Trost"] = "Trost",
    ["Outskirts"] = "Outskirts",
    ["Giant Forest"] = "Forest",
    ["Utgard Castle"] = "Utgard",
    ["Loading Docks"] = "Docks",
    ["Stohess"] = "Stohess",
    ["Chapel"] = "Chapel",
}

local function lobbyGET()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")
    return remote and remote:IsA("RemoteFunction") and remote or nil
end

LobbyRuntime.DisablePartyInvites = function()
    if RuntimeKind ~= "Lobby" then return false end
    local remote = lobbyGET()
    if not remote then return false end

    local ok = pcall(function()
        remote:InvokeServer("Functions", "Settings", "Invites", "Off")
    end)
    return ok == true
end

LobbyRuntime.GuiActuallyVisible = function(object)
    local node = object
    for _ = 1, 12 do
        if not node then break end
        if node:IsA("GuiObject") and node.Visible == false then return false end
        if node:IsA("ScreenGui") and node.Enabled == false then return false end
        node = node.Parent
    end
    return true
end

LobbyRuntime.IsPartyKickButton = function(object)
    if not object or not object:IsA("GuiButton") or not LobbyRuntime.GuiActuallyVisible(object) then
        return false
    end

    local buttonText = string.lower(tostring(object:IsA("TextButton") and object.Text or ""))
    local buttonName = string.lower(tostring(object.Name or ""))
    local intent = buttonText == "kick"
        or buttonText == "remove"
        or string.find(buttonName, "kick", 1, true) ~= nil
        or string.find(buttonName, "remove", 1, true) ~= nil

    if not intent then return false end

    local partyContext = false
    local node = object
    for _ = 1, 9 do
        if not node or node == playerGui then break end
        local name = string.lower(tostring(node.Name or ""))
        if string.find(name, "party", 1, true)
            or string.find(name, "squad", 1, true) then
            partyContext = true
            break
        end
        node = node.Parent
    end

    if not partyContext then return false end

    local row = object.Parent
    if row then
        local ownName = string.lower(tostring(player.Name or ""))
        local ownDisplay = string.lower(tostring(player.DisplayName or ""))
        local checked = 0
        for _, child in ipairs(row:GetDescendants()) do
            if child:IsA("TextLabel") or child:IsA("TextButton") then
                local text = string.lower(tostring(child.Text or ""))
                if (ownName ~= "" and string.find(text, ownName, 1, true))
                    or (ownDisplay ~= "" and string.find(text, ownDisplay, 1, true)) then
                    return false
                end
            end
            checked += 1
            if checked >= 40 then break end
        end
    end

    return true
end

LobbyRuntime.KickExistingPartyMembers = function()
    if RuntimeKind ~= "Lobby" or not playerGui then return 0 end

    local kicked = 0
    local activated = {}

    for _ = 1, 4 do
        local candidate = nil
        for _, object in ipairs(playerGui:GetDescendants()) do
            if not activated[object] and LobbyRuntime.IsPartyKickButton(object) then
                candidate = object
                break
            end
        end

        if not candidate then break end
        activated[candidate] = true

        local ok = pcall(function() candidate:Activate() end)
        if ok then kicked += 1 end
        task.wait(0.18)
    end

    return kicked
end

LobbyRuntime.PrepareSoloLaunch = function()
    App.Values.LobbyKickPartyBeforeLaunch = false
    LobbyRuntime.PartyCleanupStatus = "Removed from Default Launch"
    return true
end


App.LobbyWebhook = App.LobbyWebhook or {
    LastStatus = "Off",
    LastEvent = "None",
    Busy = false,
}

App.LobbyWebhook.Allowed = function(category)
    if RuntimeKind ~= "Lobby" or App.Values.LobbyActivityWebhookEnabled ~= true then
        return false
    end
    if category == "Boosts" then return App.Values.LobbyActivityWebhookBoosts ~= false end
    if category == "Perks" then return App.Values.LobbyActivityWebhookPerks ~= false end
    if category == "Prestige" then return App.Values.LobbyActivityWebhookPrestige ~= false end
    if category == "Gear" then return App.Values.LobbyActivityWebhookGear ~= false end
    return true
end

App.LobbyWebhook.StatusText = function()
    if App.Values.LobbyActivityWebhookEnabled ~= true then return "Off" end
    if not App.Webhook or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        return "Webhook URL required"
    end
    return tostring(App.LobbyWebhook.LastStatus or "Ready")
end

App.LobbyWebhook.StatusKind = function()
    local text = string.lower(App.LobbyWebhook.StatusText())
    if text == "off" then return "muted" end
    if string.find(text, "required", 1, true) or string.find(text, "failed", 1, true) then return "failed" end
    return "good"
end

App.LobbyWebhook.Field = function(name, value, inline)
    if value == nil or tostring(value) == "" then return nil end
    return {name=tostring(name), value=tostring(value), inline=inline == true}
end

App.LobbyWebhook.WalletText = function(before, after, key)
    local b = type(before) == "table" and tonumber(before[key]) or nil
    local a = type(after) == "table" and tonumber(after[key]) or nil
    if b ~= nil and a ~= nil then
        return App.Webhook.FormatNumber(b) .. " → " .. App.Webhook.FormatNumber(a)
    end
    if a ~= nil then return App.Webhook.FormatNumber(a) end
    if b ~= nil then return App.Webhook.FormatNumber(b) end
    return nil
end

App.LobbyWebhook.Send = function(category, title, fields, force)
    if force ~= true and not App.LobbyWebhook.Allowed(category) then return false, "disabled" end
    if not App.Webhook or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        App.LobbyWebhook.LastStatus = "Webhook URL required"
        App.Values.LobbyActivityWebhookStatus = App.LobbyWebhook.LastStatus
        return false, App.LobbyWebhook.LastStatus
    end

    local clean = {}
    for _, field in ipairs(type(fields) == "table" and fields or {}) do
        if type(field) == "table" and field.name ~= nil and field.value ~= nil then
            clean[#clean + 1] = field
        end
    end

    local userId = tostring(App.Values.WebhookPingUserId or ""):gsub("%D", "")
    local suppressPing = (category == "Boosts" and App.Values.WebhookNoPingBoosts == true)
        or (category == "Perks" and App.Values.WebhookNoPingPerks == true)
        or (category == "Prestige" and App.Values.WebhookNoPingPrestige == true)
        or (category == "Gear" and App.Values.WebhookNoPingGear == true)
    if suppressPing then userId = "" end
    local content = userId ~= "" and ("<@" .. userId .. ">") or nil
    local payload = {
        content = content,
        allowed_mentions = userId ~= "" and {users={userId}} or {parse={}},
        embeds = {{
            title = "SLICEHUB — " .. string.upper(tostring(title or "LOBBY ACTIVITY")),
            color = 5818612,
            fields = clean,
            footer = {text = "SliceHub V14.5 • Lobby Automation"},
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }},
    }

    local ok, message = App.Webhook.Post(payload)
    App.LobbyWebhook.LastEvent = tostring(title or category or "Activity")
    App.LobbyWebhook.LastStatus = ok and ("Sent • " .. App.LobbyWebhook.LastEvent) or ("Failed • " .. tostring(message))
    App.Values.LobbyActivityWebhookStatus = App.LobbyWebhook.LastStatus
    return ok, message
end


