App.PerkManager.UUID = function(value)
    value = tostring(value or "")
    return #value >= 32 and #value <= 40
        and string.match(value, "^[0-9a-fA-F]+%-[0-9a-fA-F]+%-[0-9a-fA-F]+%-[0-9a-fA-F]+%-[0-9a-fA-F]+$") ~= nil
end

App.PerkManager.NameFromInfo = function(info)
    if type(info) == "string" and info ~= "" and not App.PerkManager.UUID(info) then return info end
    if type(info) ~= "table" then return "Unknown" end
    for _, key in ipairs({"Name","name","Perk","perk","PerkName","perkName","ItemName","itemName","DisplayName","displayName","Title","title"}) do
        local value = rawget(info, key)
        if type(value) == "string" and value ~= "" and not App.PerkManager.UUID(value) then return value end
    end
    return "Unknown"
end

App.PerkManager.ReadNumber = function(node, keys, depth, seen)
    if type(node) ~= "table" or (tonumber(depth) or 0) > 5 then return nil end
    seen = seen or {}
    if seen[node] then return nil end
    seen[node] = true
    for _, key in ipairs(keys) do
        local value = rawget(node, key)
        if tonumber(value) ~= nil then return tonumber(value) end
    end
    for _, value in pairs(node) do
        if type(value) == "table" then
            local found = App.PerkManager.ReadNumber(value, keys, (tonumber(depth) or 0) + 1, seen)
            if found ~= nil then return found end
        end
    end
    return nil
end

App.PerkManager.ResolvePerks = function(profile)
    if type(profile) ~= "table" then return nil end
    if App.Prestige and type(App.Prestige.ResolveSlot) == "function" then
        local _, slot = App.Prestige.ResolveSlot(profile)
        if type(slot) == "table" and type(slot.Perks) == "table" then return slot.Perks end
    end
    local slots = type(profile.Slots) == "table" and profile.Slots or nil
    if slots then
        local wanted = player:GetAttribute("Slot") or profile.Current_Slot or App.Values.MainSlot or "A"
        for _, key in ipairs({wanted, tostring(wanted), tonumber(wanted), "A", 1, "1"}) do
            if key ~= nil and type(slots[key]) == "table" and type(slots[key].Perks) == "table" then
                return slots[key].Perks
            end
        end
        local only = nil
        for _, slot in pairs(slots) do
            if type(slot) == "table" and type(slot.Perks) == "table" then
                if only ~= nil then only = false break end
                only = slot.Perks
            end
        end
        if type(only) == "table" then return only end
    end
    return type(profile.Perks) == "table" and profile.Perks or nil
end

-- V15.6.11: AOT:R profile layouts have not been stable across every data
-- contract. Do not require literal `Storage` / `Equipped` key names. Identify
-- the perk UUID map and loadout structurally while still staying read-only.
App.PerkManager.FindStorage = function(perks)
    if type(perks) ~= "table" then return nil, nil end
    if type(perks.Storage) == "table" then return perks.Storage, "Storage" end

    local named = {"Inventory","Owned","Stored","PerkStorage","StoragePerks","Items"}
    for _, key in ipairs(named) do
        if type(perks[key]) == "table" then
            local uuidCount, infoCount = 0, 0
            for id, info in pairs(perks[key]) do
                if App.PerkManager.UUID(tostring(id)) then uuidCount += 1 end
                if type(info) == "table" and App.PerkManager.NameFromInfo(info) ~= "Unknown" then infoCount += 1 end
            end
            if uuidCount > 0 or infoCount > 1 then return perks[key], tostring(key) end
        end
    end

    local best, bestKey, bestScore = nil, nil, 0
    for key, candidate in pairs(perks) do
        if type(candidate) == "table" then
            local uuidCount, namedCount, rows = 0, 0, 0
            for id, info in pairs(candidate) do
                rows += 1
                if App.PerkManager.UUID(tostring(id)) then uuidCount += 1 end
                if type(info) == "table" and App.PerkManager.NameFromInfo(info) ~= "Unknown" then namedCount += 1 end
                if rows >= 400 then break end
            end
            local score = uuidCount * 5 + namedCount * 2
            if score > bestScore then best, bestKey, bestScore = candidate, tostring(key), score end
        end
    end
    if bestScore >= 5 then return best, bestKey end
    return nil, nil
end

App.PerkManager.FindEquipped = function(perks)
    if type(perks) ~= "table" then return nil, nil end
    for _, key in ipairs({"Equipped","Loadout","Slots","Equips","EquippedPerks"}) do
        local candidate = perks[key]
        if type(candidate) == "table" then return candidate, tostring(key) end
    end

    local wanted = {Body=true, Offense=true, Defense=true, Support=true}
    for key, candidate in pairs(perks) do
        if type(candidate) == "table" then
            local score = 0
            for slot, value in pairs(candidate) do
                if wanted[tostring(slot)] then score += 3 end
                if type(value) == "string" and App.PerkManager.UUID(value) then score += 1 end
            end
            if score >= 3 then return candidate, tostring(key) end
        end
    end
    return nil, nil
end

App.PerkManager.DescribePerks = function(perks)
    if type(perks) ~= "table" then return "Perks missing" end
    local keys = {}
    for key in pairs(perks) do
        keys[#keys + 1] = tostring(key)
        if #keys >= 8 then break end
    end
    table.sort(keys)
    return #keys > 0 and ("Perks keys: " .. table.concat(keys, ", ")) or "Perks table empty"
end


App.PerkManager.GetTalents = function()
    local remote = lobbyGET()
    if not remote then return nil, "GET RemoteFunction missing" end

    local diagnostics = {}
    local function accept(label, profile)
        if type(profile) ~= "table" then
            diagnostics[#diagnostics + 1] = label .. ": no table"
            return nil
        end
        local perks = App.PerkManager.ResolvePerks(profile)
        local storage, storageKey = App.PerkManager.FindStorage(perks)
        if type(storage) == "table" then
            App.PerkManager.ProfileStatus = label .. " • storage=" .. tostring(storageKey or "detected")
            return profile
        end
        diagnostics[#diagnostics + 1] = label .. ": " .. App.PerkManager.DescribePerks(perks)
        return nil
    end

    -- Keep ordinary/read-only SliceHub data contracts first. We deliberately do
    -- NOT import Tekkit's random Settings mutation trick into production.
    local okCopy, copy = pcall(function()
        return remote:InvokeServer("Data", "Copy")
    end)
    if okCopy then
        local accepted = accept("Data/Copy", copy)
        if accepted then return accepted end
    else
        diagnostics[#diagnostics + 1] = "Data/Copy error"
    end

    local okData, profile = pcall(function()
        return remote:InvokeServer("Functions", "Data")
    end)
    if okData then
        local accepted = accept("Functions/Data", profile)
        if accepted then return accepted end
    else
        diagnostics[#diagnostics + 1] = "Functions/Data error"
    end

    local okSettings, settings = pcall(function()
        return remote:InvokeServer("Functions", "Settings", "Get")
    end)
    if okSettings then
        local accepted = accept("Settings/Get", settings)
        if accepted then return accepted end
    else
        diagnostics[#diagnostics + 1] = "Settings/Get error"
    end

    if type(App.Prestige) == "table" and type(App.Prestige.PendingProfile) == "table" then
        local accepted = accept("Cached profile", App.Prestige.PendingProfile)
        if accepted then return accepted end
    end

    App.PerkManager.ProfileStatus = table.concat(diagnostics, " • ")
    return nil, "Perk storage unavailable • " .. tostring(App.PerkManager.ProfileStatus)
end


App.PerkManager.BuildInventory = function(force)
    if not force and type(App.PerkManager.Cache) == "table" and os.clock() - (tonumber(App.PerkManager.CacheAt) or 0) < 2.0 then
        return App.PerkManager.Cache
    end
    local profile, err = App.PerkManager.GetTalents()
    if not profile then return nil, err end
    local perks = App.PerkManager.ResolvePerks(profile)
    local storage, storageKey = App.PerkManager.FindStorage(perks)
    if type(storage) ~= "table" then return nil, "Perk storage unavailable" end

    local equipped = {}
    local equippedRoot, equippedKey = App.PerkManager.FindEquipped(perks)
    if type(equippedRoot) == "table" then
        local function collect(node, depth)
            if type(node) ~= "table" or depth > 6 then return end
            for key, value in pairs(node) do
                if type(value) == "string" and App.PerkManager.UUID(value) then equipped[value] = tostring(key) end
                if type(value) == "table" then collect(value, depth + 1) end
            end
        end
        collect(equippedRoot, 0)
    end

    local list, byId, byName = {}, {}, {}
    App.PerkManager.LabelToId = {}
    App.PerkManager.IdToLabel = {}
    for id, info in pairs(storage) do
        id = tostring(id)
        if App.PerkManager.UUID(id) then
            local name = App.PerkManager.NameFromInfo(info)
            local rarity = tostring(App.PerkManager.RarityByName[name] or "Unknown")
            local level = App.PerkManager.ReadNumber(info, {"Level","level","LVL","Lvl","lvl","EnhanceLevel","enhanceLevel","Enhancement","enhancement","UpgradeLevel","upgradeLevel"}, 0, {})
            if level ~= nil and (level < 0 or level > 10) then level = nil end
            local invested = App.PerkManager.ReadNumber(info, {"EXP","Exp","exp","XP","Xp","xp","Experience","experience","EnhanceEXP","EnhanceExp","enhanceExp","PerkEXP","PerkExp","perkExp"}, 0, {})
            local item = {Id=id, Name=name, Rarity=rarity, Level=level, InvestedXP=invested, Equipped=equipped[id] ~= nil, EquippedIn=equipped[id], Raw=info}
            list[#list + 1] = item
            byId[id] = item
            byName[name] = byName[name] or {}
            byName[name][#byName[name] + 1] = item
        end
    end
    table.sort(list, function(a,b)
        if a.Name ~= b.Name then return string.lower(a.Name) < string.lower(b.Name) end
        local al, bl = tonumber(a.Level) or -1, tonumber(b.Level) or -1
        if al ~= bl then return al > bl end
        return a.Id < b.Id
    end)
    for _, item in ipairs(list) do
        local label = string.format("%s • %s • +%s • …%s", item.Name, item.Rarity, item.Level ~= nil and tostring(math.floor(item.Level + 0.5)) or "?", string.sub(item.Id, -6))
        App.PerkManager.LabelToId[label] = item.Id
        App.PerkManager.IdToLabel[item.Id] = label
    end
    local inv = {Profile=profile, Perks=perks, Storage=storage, StorageKey=storageKey, EquippedRoot=equippedRoot, EquippedKey=equippedKey, Equipped=equipped, List=list, ById=byId, ByName=byName}
    App.PerkManager.ProfileStatus = tostring(App.PerkManager.ProfileStatus or "Profile") .. " • " .. tostring(#list) .. " perks"
    App.PerkManager.Cache = inv
    App.PerkManager.CacheAt = os.clock()
    return inv
end


App.PerkManager.TargetOptions = function()
    local inv = App.PerkManager.BuildInventory(false)
    local options = {"Select a perk..."}
    if not inv then return options end
    for _, item in ipairs(inv.List) do
        if item.Name ~= "Unknown" and item.Rarity ~= "Unknown" then options[#options + 1] = App.PerkManager.IdToLabel[item.Id] end
    end
    return options
end

App.PerkManager.SelectedTarget = function(inv)
    inv = inv or App.PerkManager.BuildInventory(false)
    if not inv then return nil end
    local label = tostring(App.Values.PerkEnhanceTarget or "")
    local id = App.PerkManager.LabelToId[label]
    return id and inv.ById[id] or nil
end

App.PerkManager.RaritySelectedForSell = function(rarity)
    return App.Values["SellPerk" .. tostring(rarity)] == true
end

App.PerkManager.RaritySelectedForEnhance = function(rarity)
    return App.Values["PerkEnhanceUse" .. tostring(rarity)] == true
end

App.PerkManager.AutoSellOnce = function(manual)
    if RuntimeKind ~= "Lobby" or App.PerkManager.SellBusy then return false, "busy" end
    if not manual and App.Values.AutoSellPerks ~= true then return false, "disabled" end
    local any = false
    for _, rarity in ipairs({"Common","Rare","Epic","Legendary","Mythic"}) do if App.PerkManager.RaritySelectedForSell(rarity) then any = true break end end
    if not any then App.PerkManager.SellStatus = "Choose at least one rarity" return false, App.PerkManager.SellStatus end

    App.PerkManager.SellBusy = true
    local inv, err = App.PerkManager.BuildInventory(true)
    if not inv then App.PerkManager.SellBusy=false; App.PerkManager.SellStatus=tostring(err); return false, err end

    local ids, counts = {}, {Common=0,Rare=0,Epic=0,Legendary=0,Mythic=0}
    for _, item in ipairs(inv.List) do
        if not item.Equipped and item.Rarity ~= "Unknown" and App.PerkManager.RaritySelectedForSell(item.Rarity) then
            ids[#ids + 1] = item.Id
            counts[item.Rarity] = (counts[item.Rarity] or 0) + 1
        end
    end
    if #ids == 0 then App.PerkManager.SellBusy=false; App.PerkManager.SellStatus="No matching sellable perks"; return true, App.PerkManager.SellStatus end

    local remote = lobbyGET()
    if not remote then App.PerkManager.SellBusy=false; App.PerkManager.SellStatus="GET RemoteFunction missing"; return false, App.PerkManager.SellStatus end
    local sold = 0
    for startIndex=1,#ids,40 do
        if not manual and App.Values.AutoSellPerks ~= true then break end
        local batch = {}
        for i=startIndex,math.min(#ids,startIndex+39) do batch[#batch+1]=ids[i] end
        local ok = pcall(function() return remote:InvokeServer("S_Equipment","Delete","Perk",batch) end)
        if not ok then App.PerkManager.SellStatus="Delete invoke failed • stopped" break end
        task.wait(0.35)
        local verify = App.PerkManager.BuildInventory(true)
        if not verify then App.PerkManager.SellStatus="Verification fetch failed • stopped" break end
        local remaining = 0
        for _, id in ipairs(batch) do if verify.ById[id] then remaining += 1 end end
        if remaining > 0 then App.PerkManager.SellStatus="Verification failed • stopped" break end
        sold += #batch
    end

    App.PerkManager.SellBusy=false
    App.PerkManager.LastSellAt=os.clock()
    App.PerkManager.NextSellAt=os.clock()+12
    App.PerkManager.SellStatus="Sold "..tostring(sold).." perk"..(sold==1 and "" or "s")
    if sold > 0 and App.LobbyWebhook then
        local fields={App.LobbyWebhook.Field("Total", tostring(sold), true)}
        for _, rarity in ipairs({"Common","Rare","Epic","Legendary","Mythic"}) do
            if (counts[rarity] or 0)>0 then fields[#fields+1]=App.LobbyWebhook.Field(rarity,tostring(counts[rarity]),true) end
        end
        task.spawn(function() App.LobbyWebhook.Send("Perks","Perks Sold",fields) end)
    end
    return sold > 0, App.PerkManager.SellStatus
end

App.PerkManager.CumulativeXP = function(rarity, level)
    local total = App.PerkManager.TotalXPTo10[rarity]
    if not total then return nil end
    return total * (math.clamp(tonumber(level) or 0,0,10)/10)
end

App.PerkManager.MaterialXP = function(item)
    local base = App.PerkManager.BaseMaterialXP[item.Rarity]
    if not base then return nil end
    local invested = tonumber(item.InvestedXP)
    if invested == nil and item.Level ~= nil then invested = App.PerkManager.CumulativeXP(item.Rarity,item.Level) end
    invested = math.max(0,tonumber(invested) or 0)
    return base + invested * 0.75
end

App.PerkManager.EnhancePlan = function()
    local inv, err = App.PerkManager.BuildInventory(false)
    if not inv then return nil,err end
    local target = App.PerkManager.SelectedTarget(inv)
    if not target then return nil,"Select a target perk" end
    if target.Level == nil then return nil,"Target level unavailable • open Equipment > Perks and refresh" end
    local targetLevel = math.clamp(math.floor((tonumber(App.Values.PerkEnhanceTargetLevel) or 10)+0.5),1,10)
    App.Values.PerkEnhanceTargetLevel = targetLevel
    if targetLevel <= target.Level then return {Target=target,TargetLevel=targetLevel,RequiredXP=0,Gold=0,Materials={},MaterialXP=0,Enough=true} end
    local total = App.PerkManager.TotalXPTo10[target.Rarity]
    if not total then return nil,"Target rarity unavailable" end
    local currentXP = App.PerkManager.CumulativeXP(target.Rarity,target.Level) or 0
    if tonumber(target.InvestedXP) ~= nil and target.InvestedXP >= 0 and target.InvestedXP <= total then currentXP=math.max(currentXP,target.InvestedXP) end
    local needed=math.max(0,(App.PerkManager.CumulativeXP(target.Rarity,targetLevel) or 0)-currentXP)

    local pool={}
    for name,items in pairs(inv.ByName) do
        local eligible={}
        for _,item in ipairs(items) do
            if item.Id~=target.Id and item.Name~=target.Name and not item.Equipped and item.Rarity~="Unknown" and App.PerkManager.RaritySelectedForEnhance(item.Rarity) then
                local xp=App.PerkManager.MaterialXP(item)
                if xp then item._MaterialXP=xp; eligible[#eligible+1]=item end
            end
        end
        table.sort(eligible,function(a,b) return (a._MaterialXP or 0)<(b._MaterialXP or 0) end)

        local maxUse=math.max(0,#items-1)
        for i=1,math.min(#eligible,maxUse) do pool[#pool+1]=eligible[i] end
    end
    table.sort(pool,function(a,b) return (a._MaterialXP or 0)<(b._MaterialXP or 0) end)
    local chosen,gained={},0
    for _,item in ipairs(pool) do
        if gained>=needed then break end
        chosen[#chosen+1]=item; gained += item._MaterialXP or 0
    end
    return {Target=target,TargetLevel=targetLevel,RequiredXP=needed,Gold=math.ceil(needed*20),Materials=chosen,MaterialXP=gained,Enough=gained>=needed}
end

App.PerkManager.EnhanceEstimateText = function()
    local plan,err=App.PerkManager.EnhancePlan()
    if not plan then return tostring(err or "Select a target") end
    if plan.RequiredXP<=0 then return "Already at requested level" end
    return "~"..App.Webhook.FormatNumber(plan.Gold).." Gold • "..App.Webhook.FormatNumber(plan.RequiredXP).." EXP • "..tostring(#plan.Materials).." materials"..(plan.Enough and " • READY" or " • NOT ENOUGH")
end

App.PerkManager.PreviewEnhance = function()
    local plan,err=App.PerkManager.EnhancePlan()
    if not plan then App.PerkManager.EnhanceStatus=tostring(err); return false,err end
    App.PerkManager.EnhanceStatus=("Preview • %s +%s → +%s • %d materials • ~%s Gold"):format(plan.Target.Name,tostring(plan.Target.Level),tostring(plan.TargetLevel),#plan.Materials,App.Webhook.FormatNumber(plan.Gold))
    return plan.Enough,App.PerkManager.EnhanceStatus
end

App.PerkManager.ClearEnhanceTransient = function()
    App.Values.PerkEnhanceTarget=""
    App.Values.PerkEnhanceUseCommon=false
    App.Values.PerkEnhanceUseRare=false
    App.Values.PerkEnhanceUseEpic=false
    App.Values.PerkEnhanceUseLegendary=false
    App.Values.PerkEnhanceUseMythic=false
end

App.PerkManager.RunEnhance = function()
    if RuntimeKind~="Lobby" or App.PerkManager.EnhanceBusy then return false,"busy" end
    local plan,err=App.PerkManager.EnhancePlan()
    if not plan then App.PerkManager.EnhanceStatus=tostring(err); return false,err end
    if plan.RequiredXP<=0 then App.PerkManager.EnhanceStatus="Already at requested level"; return false,App.PerkManager.EnhanceStatus end
    if not plan.Enough or #plan.Materials==0 then App.PerkManager.EnhanceStatus="Not enough selected material EXP"; return false,App.PerkManager.EnhanceStatus end

    App.PerkManager.EnhanceBusy=true
    local beforeWallet=App.Webhook and App.Webhook.ReadAccount and App.Webhook.ReadAccount() or {}
    local targetId=plan.Target.Id
    local oldLevel=plan.Target.Level
    local requested=plan.TargetLevel
    local queue={}
    for _,item in ipairs(plan.Materials) do queue[#queue+1]=item end
    local consumed=0
    local remote=lobbyGET()
    if not remote then App.PerkManager.EnhanceBusy=false; App.PerkManager.EnhanceStatus="GET RemoteFunction missing"; return false,App.PerkManager.EnhanceStatus end

    while #queue>0 do
        local live=App.PerkManager.BuildInventory(true)
        local target=live and live.ById[targetId]
        if not target or target.Level==nil then App.PerkManager.EnhanceStatus="Target verification failed • stopped" break end
        if target.Level>=requested then break end
        local batchMap,batchIds={},{}
        for _=1,math.min(10,#queue) do local material=table.remove(queue,1); batchMap[material.Id]=1; batchIds[#batchIds+1]=material.Id end
        local ok=pcall(function() return remote:InvokeServer("S_Equipment","Enhance",targetId,batchMap) end)
        if not ok then App.PerkManager.EnhanceStatus="Enhance invoke failed • stopped" break end
        task.wait(0.40)
        local verify=App.PerkManager.BuildInventory(true)
        if not verify or not verify.ById[targetId] then App.PerkManager.EnhanceStatus="Post-enhance verification failed • stopped" break end
        local removed=0
        for _,id in ipairs(batchIds) do if not verify.ById[id] then removed+=1 end end
        if removed==0 then App.PerkManager.EnhanceStatus="No materials consumed • stopped" break end
        consumed+=removed
    end

    local final=App.PerkManager.BuildInventory(true)
    local target=final and final.ById[targetId]
    local newLevel=target and tonumber(target.Level) or nil
    local success=newLevel~=nil and newLevel>=requested
    App.PerkManager.EnhanceStatus=success and (("Enhanced %s • +%d → +%d • %d materials"):format(plan.Target.Name,oldLevel,newLevel,consumed)) or tostring(App.PerkManager.EnhanceStatus or "Target level not reached")
    App.PerkManager.EnhanceBusy=false

    if success then
        local afterWallet=App.Webhook and App.Webhook.ReadAccount and App.Webhook.ReadAccount() or {}
        if App.LobbyWebhook then
            local fields={
                App.LobbyWebhook.Field("Perk",plan.Target.Name,false),
                App.LobbyWebhook.Field("Level",("+%d → +%d"):format(oldLevel,newLevel),true),
                App.LobbyWebhook.Field("Materials",tostring(consumed),true),
                App.LobbyWebhook.Field("Estimated Gold",App.Webhook.FormatNumber(plan.Gold),true),
                App.LobbyWebhook.Field("Gold",App.LobbyWebhook.WalletText(beforeWallet,afterWallet,"Gold"),false),
            }
            task.spawn(function() App.LobbyWebhook.Send("Perks","Perk Enhanced",fields) end)
        end
        App.PerkManager.ClearEnhanceTransient()
    end
    return success,App.PerkManager.EnhanceStatus
end


task.spawn(function()
    task.wait(2.0)
    while gui and gui.Parent do
        if RuntimeKind=="Lobby" and App.Values.AutoSellPerks==true and not App.PerkManager.SellBusy and os.clock()>=(tonumber(App.PerkManager.NextSellAt) or 0) and not LobbyRuntime.Busy then
            pcall(App.PerkManager.AutoSellOnce,false)
            App.PerkManager.NextSellAt=os.clock()+12
        end
        task.wait(1.0)
    end
end)

local function lobbyInvokeMission(action, ...)
    local remote = lobbyGET()
    if not remote then return false, nil, "GET RemoteFunction missing" end
    local args = table.pack(...)
    local ok, result = pcall(function()
        return remote:InvokeServer("S_Missions", action, table.unpack(args, 1, args.n))
    end)
    if not ok then return false, nil, tostring(result) end
    return true, result, nil
end

local function lobbyOwnedMission()
    local missions = ReplicatedStorage:FindFirstChild("Missions")
    if not missions then return nil end
    for _, mission in ipairs(missions:GetChildren()) do
        local leader = mission:FindFirstChild("Leader")
        if leader and tostring(leader.Value) == tostring(player.Name) then
            return mission
        end
    end
    return nil
end

local function lobbyWaitOwned(wantOwned, timeout)
    local started = os.clock()
    repeat
        local mission = lobbyOwnedMission()
        if wantOwned and mission then return mission end
        if not wantOwned and not mission then return true end
        task.wait(0.05)
    until os.clock() - started >= timeout
    return wantOwned and lobbyOwnedMission() or (lobbyOwnedMission() == nil)
end

LobbyRuntime.SelectedModifiers = function()
    if App.Values.LobbyModifiersEnabled ~= true
        or tostring(App.Values.LobbyMode) == "Waves" then
        return {}
    end

    local selected = {}
    for key, name in pairs(App.LobbyModifierMap) do
        if App.Values[key] == true then
            selected[#selected + 1] = name
        end
    end
    table.sort(selected)
    return selected
end

LobbyRuntime.BuildDefaultRunConfig = function()
    local mode = tostring(App.Values.LobbyMode or "Mission")

    if mode == "Waves" then
        return {
            CreateMode = "Waves",
            Map = "Trost",
            Objective = "Waves",
            Difficulty = "Easy",
            Modifiers = {},
        }
    end

    if mode == "Raid" then
        local choice = tostring(App.Values.LobbyRaidChoice or "Shiganshina (Arm)")
        local raid = App.LobbyRaidData[choice] or App.LobbyRaidData["Shiganshina (Arm)"]
        return {
            CreateMode = "Raid",
            RaidChoice = choice,
            Map = raid.Map,
            Objective = raid.Objective,
            Minimum = raid.Minimum,
            Difficulty = tostring(App.Values.LobbyDifficulty or "Hard"),
            Modifiers = LobbyRuntime.SelectedModifiers(),
        }
    end

    local map = tostring(App.Values.LobbyMap or "Shiganshina")
    if not App.LobbyMissionData[map] then map = "Shiganshina" end

    local objectives = App.LobbyMissionData[map]
    local objective = tostring(App.Values.LobbyObjective or objectives[1])
    if not table.find(objectives, objective) then
        objective = objectives[1]
        App.Values.LobbyObjective = objective
    end

    return {
        CreateMode = "Mission",
        Map = map,
        Objective = objective,
        Difficulty = tostring(App.Values.LobbyDifficulty or "Easy"),
        Modifiers = LobbyRuntime.SelectedModifiers(),
    }
end

LobbyRuntime.BuildRunConfig = function()
    local defaultConfig = LobbyRuntime.BuildDefaultRunConfig()
    if LobbyRuntime.ForceDefaultLaunch ~= true
        and RuntimeKind == "Lobby"
        and App.BoostedMaps
        and type(App.BoostedMaps.ResolveConfig) == "function" then
        local resolved = select(1, App.BoostedMaps.ResolveConfig(defaultConfig))
        if type(resolved) == "table" then
            return resolved
        end
    end
    return defaultConfig
end

LobbyRuntime.BuildPayload = function(config, difficultyOverride)
    local mode = tostring(config.CreateMode or "Mission")
    local difficulty = tostring(difficultyOverride or config.Difficulty or "Easy")

    if mode == "Waves" then
        return {
            Name = "Trost",
            Difficulty = "Easy",
            Type = "Waves",
            Objective = "Waves",
        }
    end

    if mode == "Raid" then
        return {
            Name = tostring(config.Map or "Shiganshina"),
            Difficulty = difficulty,
            Type = "Raids",
            Objective = tostring(config.Objective or "Armored Titan"),
            Minimum = tonumber(config.Minimum),
        }
    end

    return {
        Name = LobbyRuntime.InternalMapNames[tostring(config.Map or "")]
            or tostring(config.Map or "Shiganshina"),
        Difficulty = difficulty,
        Type = "Missions",
        Objective = tostring(config.Objective or "Skirmish"),
    }
end


LobbyRuntime.HardestOrder = function(config)
    if tostring(config.CreateMode) == "Raid" then
        local raid = App.LobbyRaidData[tostring(config.RaidChoice or "")]
        local allowed = {}
        for _, value in ipairs((raid and raid.Difficulties) or {"Hard", "Severe", "Aberrant"}) do
            allowed[value] = true
        end

        local order = {}
        for _, value in ipairs({"Aberrant", "Severe", "Hard"}) do
            if allowed[value] then order[#order + 1] = value end
        end
        return order
    end

    return {"Aberrant", "Severe", "Hard", "Normal", "Easy"}
end


do
    App.MultiGrind = App.MultiGrind or {
        Version = "V15.6.22-MULTIGRIND-R1",
        Status = "Off",
        Detail = "Enable Multi Grind to coordinate accounts",
        Busy = false,
        InviteLast = {},
        JoinLast = {},
        ReadySince = nil,
        HostSeenSince = nil,
        MissingSince = nil,
        RecoverySent = false,
        EventLast = {},
        PartyPreparedId = nil,
    }
    local MG = App.MultiGrind
    local function trim(v) return tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") end
    local function missionsFolder() return ReplicatedStorage:FindFirstChild("Missions") end
    local function missionLeader(mission)
        local leader = mission and mission:FindFirstChild("Leader")
        return leader and trim(leader.Value) or ""
    end
    local function missionId(mission)
        if not mission then return nil end
        local id = mission:GetAttribute("ID")
        if id ~= nil and tostring(id) ~= "" then return tostring(id) end
        local child = mission:FindFirstChild("ID")
        if child and child:IsA("ValueBase") and tostring(child.Value) ~= "" then return tostring(child.Value) end
        return nil
    end
    local function findPartyByLeader(username)
        local folder = missionsFolder()
        if not folder then return nil end
        local wanted = string.lower(trim(username))
        for _, mission in ipairs(folder:GetChildren()) do
            if string.lower(missionLeader(mission)) == wanted then return mission end
        end
        return nil
    end
    local function partyMembers(mission)
        local result, seen = {}, {}
        if not mission then return result end
        for _, child in ipairs(mission:GetChildren()) do
            if child:IsA("StringValue") and (child.Name == "Leader" or string.find(string.lower(child.Name), "slot", 1, true)) then
                local name = trim(child.Value)
                local low = string.lower(name)
                if name ~= "" and not seen[low] then seen[low]=true; result[#result+1]=name end
            end
        end
        return result
    end
    local function parseNames(raw)
        local out, seen = {}, {}
        for token in string.gmatch(tostring(raw or ""), "[^,%s]+") do
            local name = trim(token)
            local low = string.lower(name)
            if name ~= "" and not seen[low] then seen[low]=true; out[#out+1]=name end
        end
        return out
    end
    local function findPlayer(name)
        local wanted = string.lower(trim(name))
        for _, p in ipairs(Players:GetPlayers()) do if string.lower(p.Name) == wanted then return p end end
        return nil
    end
    local function uniqueOtherLeader()
        local folder = missionsFolder()
        if not folder then return nil end
        local found, lowFound = nil, nil
        for _, mission in ipairs(folder:GetChildren()) do
            local leader = missionLeader(mission)
            local low = string.lower(leader)
            if leader ~= "" and low ~= string.lower(player.Name) then
                if lowFound and lowFound ~= low then return nil end
                found, lowFound = leader, low
            end
        end
        return found
    end
    local function writeRoster(names)
        local env=v12Environment(); local write=env and env.writefile or (type(writefile)=="function" and writefile or nil); local make=env and env.makefolder or (type(makefolder)=="function" and makefolder or nil)
        if type(write)~="function" then return false end
        if type(make)=="function" then pcall(make,"SH"); pcall(make,"SH/multigrind") end
        local ok, encoded=pcall(function() return HttpService:JSONEncode({Names=names,Required=math.clamp(math.floor((tonumber(App.Values.MultiGrindRequiredPlayers) or 2)+0.5),2,8),At=os.time()}) end)
        return ok and pcall(write,"SH/multigrind/roster_"..tostring(player.UserId)..".json",encoded)==true
    end
    local function readRoster()
        local env=v12Environment(); local read=env and env.readfile or (type(readfile)=="function" and readfile or nil); local isf=env and env.isfile or (type(isfile)=="function" and isfile or nil)
        if type(read)~="function" or type(isf)~="function" then return nil end
        local path="SH/multigrind/roster_"..tostring(player.UserId)..".json"
        local okE, exists=pcall(isf,path); if not okE or not exists then return nil end
        local okR, raw=pcall(read,path); if not okR then return nil end
        local okD, data=pcall(function() return HttpService:JSONDecode(raw) end); return okD and type(data)=="table" and data or nil
    end
    local function emit(title, description)
        if App.Values.WebhookEnabled ~= true or not App.Webhook or not App.Webhook.ValidURL(App.Values.WebhookURL) then return end
        local key=tostring(title).."|"..tostring(description); local now=os.clock()
        if now-(tonumber(MG.EventLast[key]) or 0)<10 then return end; MG.EventLast[key]=now
        task.spawn(function() pcall(App.Webhook.Post,{allowed_mentions={parse={}},embeds={{title="SLICEHUB // MULTI GRIND",description="**"..tostring(title).."**\n"..tostring(description),color=10181046,fields={{name="ACCOUNT",value=tostring(player.Name),inline=true},{name="ROLE",value=tostring(App.Values.MultiGrindRole or "Host"),inline=true}},footer={text="SliceHub V15.6.22 • Multi Grind"},timestamp=os.date("!%Y-%m-%dT%H:%M:%SZ")}}}) end)
    end
    local function invite(username)
        local remote=lobbyGET(); if not remote then return false,"GET missing" end
        local ok,result=pcall(function() return remote:InvokeServer("Invites","Invite",username) end)
        if not ok then return false,tostring(result) end
        if result==nil then return false,"Invite returned nil" end
        return true,tostring(result)
    end
    local function inviteCard(host)
        local wanted=string.lower(trim(host))
        for _, item in ipairs(playerGui:GetDescendants()) do
            local tag=item:GetAttribute("Tag"); local id=item:GetAttribute("ID")
            if id~=nil and string.lower(trim(tag))==wanted then return tostring(id) end
        end
        return nil
    end
    local function joinParty(host,id)
        local remote=lobbyGET(); if not remote then return false,"GET missing" end
        pcall(function()
            local assets=ReplicatedStorage:FindFirstChild("Assets")
            local remotes=assets and assets:FindFirstChild("Remotes")
            local post=remotes and remotes:FindFirstChild("POST")
            if post and post:IsA("RemoteEvent") then post:FireServer("Invites","State",host) end
        end)
        local ok,result=pcall(function() return remote:InvokeServer("S_Missions","Join",id) end)
        if not ok then return false,tostring(result) end
        if type(result)=="string" then return false,result end
        local deadline=os.clock()+3
        repeat
            local mission=findPartyByLeader(host)
            if mission then for _,name in ipairs(partyMembers(mission)) do if string.lower(name)==string.lower(player.Name) then writeRoster(partyMembers(mission)); return true,"Joined" end end end
            task.wait(0.10)
        until os.clock()>=deadline
        return false,"Join not confirmed"
    end
    local function createHostParty()
        local existing=lobbyOwnedMission()
        if existing then return existing end
        local config=LobbyRuntime.BuildRunConfig(); local hardest=tostring(config.Difficulty)=="Hardest"; local difficulties=hardest and LobbyRuntime.HardestOrder(config) or {config.Difficulty}
        pcall(function() lobbyInvokeMission("Leave") end); lobbyWaitOwned(false,1.0)
        for _,difficulty in ipairs(difficulties) do
            local ok,result=lobbyInvokeMission("Create",LobbyRuntime.BuildPayload(config,difficulty))
            if ok and type(result)~="string" then
                local mission=lobbyWaitOwned(true,1.75)
                if mission then
                    if MG.PartyPreparedId~=missionId(mission) then
                        for _,modifier in ipairs(config.Modifiers or {}) do lobbyInvokeMission("Modify",modifier); task.wait(0.02) end
                        MG.PartyPreparedId=missionId(mission) or tostring(mission)
                    end
                    return mission
                end
            end
            pcall(function() lobbyInvokeMission("Leave") end); lobbyWaitOwned(false,0.6)
        end
        return nil
    end
    local function hostStep()
        if MG.Busy then return end; MG.Busy=true
        task.spawn(function()
            local mission=createHostParty()
            if not mission then MG.Status="Host • create failed"; MG.Detail="Could not create selected run"; MG.Busy=false; return end
            local members=partyMembers(mission); local joined={}; for _,name in ipairs(members) do joined[string.lower(name)]=true end
            local targets,seen={},{}; local function add(name) name=trim(name); local low=string.lower(name); if name~="" and low~=string.lower(player.Name) and not seen[low] then seen[low]=true; targets[#targets+1]=name end end
            for _,name in ipairs(parseNames(App.Values.MultiGrindExpectedAlts)) do add(name) end
            if App.Values.MultiGrindAutoDetectAlts~=false then for _,p in ipairs(Players:GetPlayers()) do if p~=player then add(p.Name) end end end
            local waiting={}
            for _,name in ipairs(targets) do
                local p=findPlayer(name); local actual=p and p.Name or name; local low=string.lower(actual)
                if not joined[low] then
                    waiting[#waiting+1]=actual
                    if p and os.clock()-(tonumber(MG.InviteLast[low]) or 0)>=8 then
                        MG.InviteLast[low]=os.clock(); local ok,response=invite(actual); MG.Detail=(ok and "Invited " or "Invite failed ")..actual.." • "..tostring(response)
                    end
                end
            end
            local required=math.clamp(math.floor((tonumber(App.Values.MultiGrindRequiredPlayers) or 2)+0.5),2,8)
            local liveConfig=LobbyRuntime.BuildRunConfig()
            if tonumber(liveConfig.Minimum) then required=math.max(required,math.floor(tonumber(liveConfig.Minimum))) end
            MG.Status="Host • Party "..tostring(#members).." / "..tostring(required)
            if #members>=required then
                MG.ReadySince=MG.ReadySince or os.clock(); writeRoster(members)
                if os.clock()-MG.ReadySince>=math.clamp(tonumber(App.Values.MultiGrindReadyDelay) or 2,0,10) then
                    MG.Status="Host • launching"; MG.Detail="Required roster confirmed"
                    if App.Values.AutoExecuteOnTeleport == true then pcall(queueV12AutoExecute, true) end
                    local ok,result,err=lobbyInvokeMission("Start")
                    if ok then emit("Party ready — launching",tostring(#members).."/"..tostring(required).." accounts ready"); MG.Status="Host • launch sent" else MG.Status="Host • launch failed"; MG.Detail=tostring(err or result) end
                end
            else MG.ReadySince=nil; if #waiting>0 then MG.Detail="Waiting: "..table.concat(waiting,", ") end end
            MG.Busy=false
        end)
    end
    local function altStep()
        local host=trim(App.Values.MultiGrindHostUsername)
        if host=="" and App.Values.MultiGrindAutoDetectHost~=false then host=uniqueOtherLeader() or ""; if host~="" then App.Values.MultiGrindHostUsername=host; if V12Config and V12Config.ScheduleSave then V12Config.ScheduleSave(0.15) end end end
        if host=="" then MG.Status="Alt • waiting for Host"; MG.Detail="Waiting for one Host party in this private server"; MG.HostSeenSince=nil; return end
        local mission=findPartyByLeader(host)
        if mission then
            for _,name in ipairs(partyMembers(mission)) do if string.lower(name)==string.lower(player.Name) then MG.Status="Alt • READY"; MG.Detail="Leader: "..host; writeRoster(partyMembers(mission)); MG.HostSeenSince=nil; return end end
            MG.HostSeenSince=MG.HostSeenSince or os.clock()
        else MG.HostSeenSince=nil end
        local id=inviteCard(host)
        if id and os.clock()-(tonumber(MG.JoinLast["gui:"..id]) or 0)>=4 then MG.JoinLast["gui:"..id]=os.clock(); MG.Status="Alt • accepting invite"; local ok,msg=joinParty(host,id); MG.Detail=tostring(msg); return end
        if mission and App.Values.MultiGrindDirectJoin~=false and os.clock()-(MG.HostSeenSince or os.clock())>=2.5 then
            local partyId=missionId(mission)
            if partyId and os.clock()-(tonumber(MG.JoinLast["direct:"..partyId]) or 0)>=8 then MG.JoinLast["direct:"..partyId]=os.clock(); MG.Status="Alt • direct join"; local ok,msg=joinParty(host,partyId); MG.Detail=tostring(msg); return end
        end
        MG.Status="Alt • waiting"; MG.Detail=mission and "Host party visible • waiting for join" or (findPlayer(host) and "Host in server • waiting for party" or "Waiting for Host in private server")
    end
    local function lobbyStep()
        if RuntimeKind~="Lobby" or App.Values.MultiGrindEnabled~=true then return end
        if App.Values.MainAutoJoinPrivateServer~=true or trim(App.Values.MainPrivateServerCode)=="" then MG.Status="Private Server required"; MG.Detail="Enable Auto Join Private Server and save a code"; return end
        if tostring(App.Values.MultiGrindRole)=="Alt" then altStep() else hostStep() end
    end
    local function recoveryStep()
        if RuntimeKind~="Gameplay" or App.Values.MultiGrindEnabled~=true or App.Values.MultiGrindRecovery~=true then MG.MissingSince=nil; return end
        local roster=readRoster(); local missing={}; local required=math.clamp(math.floor((tonumber(App.Values.MultiGrindRequiredPlayers) or 2)+0.5),2,8)
        if type(roster)=="table" and type(roster.Names)=="table" and #roster.Names>0 then
            for _,name in ipairs(roster.Names) do if not findPlayer(name) then missing[#missing+1]=name end end
        elseif #Players:GetPlayers()<required then missing[#missing+1]="required account" end
        if #missing==0 then MG.MissingSince=nil; MG.RecoverySent=false; return end
        MG.MissingSince=MG.MissingSince or os.clock(); MG.Status="Recovery • account missing"; MG.Detail=table.concat(missing,", ")
        if os.clock()-MG.MissingSince<3.5 or MG.RecoverySent then return end
        MG.RecoverySent=true; emit("Account missing — returning Lobby","Missing: "..table.concat(missing,", "))
        task.spawn(function()
            if App.Values.AutoExecuteOnTeleport == true then pcall(queueV12AutoExecute, true) end
            local code=trim(App.Values.MainPrivateServerCode)
            local remote=lobbyGET()
            if remote and code~="" then
                App.TeleportTrace.Record("MULTIGRIND_RECOVERY", "Account missing • returning Lobby")
                pcall(function() remote:InvokeServer("Functions","Teleport","Lobby",code) end)
            elseif App.AFKManager and type(App.AFKManager.ReturnToLobby)=="function" then pcall(App.AFKManager.ReturnToLobby) end
        end)
    end
    if RuntimeKind=="Lobby" then task.spawn(function() task.wait(0.9); while App.RuntimeHealth and App.RuntimeHealth.Alive==true do pcall(lobbyStep); task.wait(0.35) end end) end
    if RuntimeKind=="Gameplay" then task.spawn(function() task.wait(5); while App.RuntimeHealth and App.RuntimeHealth.Alive==true do pcall(recoveryStep); task.wait(0.75) end end) end
end

local function lobbyTeleportStarted()
    if LobbyRuntime.TeleportSeen then return true end
    local value = player:GetAttribute("Teleporting")
    return value ~= nil and value ~= false
end

player.OnTeleport:Connect(function()
    LobbyRuntime.TeleportSeen = true
end)


App.LoadingProtection = App.LoadingProtection or {
    Suspended = false,
    Status = "Idle",
    SuspendedAt = 0,
}

App.LoadingProtection.RestoreVisuals = function()


    pcall(applyRemoveMapProps, false, true)
    pcall(applyRemoveMapTextures, false)
    pcall(applyLowDetailMaterials, false)
    pcall(applyDisableParticlesTrails, false)
    pcall(applyReduceTitanEffects, false)
    pcall(applyDisableCameraEffects, false)
    pcall(applyRemoveFog, false)
    pcall(applySimpleLighting, false)
end

App.LoadingProtection.Suspend = function(reason)
    if App.LoadingProtection.Suspended then
        return
    end

    App.LoadingProtection.Suspended = true
    App.LoadingProtection.SuspendedAt = os.clock()
    App.LoadingProtection.Status =
        tostring(reason or "Protecting AOT:R loading visuals")

    App.LoadingProtection.RestoreVisuals()
    if App.PerformanceControl and type(App.PerformanceControl.Apply3D) == "function" then
        pcall(App.PerformanceControl.Apply3D, false)
    end
end

if RuntimeKind == "Lobby" then
    player.OnTeleport:Connect(function(state)
        local text = tostring(state)

        if string.find(text, "RequestedFromServer", 1, true)
            or string.find(text, "Started", 1, true)
            or string.find(text, "InProgress", 1, true) then

            App.LoadingProtection.Suspend(
                "Teleport detected • restoring AOT:R loading visuals"
            )
        end
    end)

    player:GetAttributeChangedSignal(
        "Teleporting"
    ):Connect(function()
        local value =
            player:GetAttribute(
                "Teleporting"
            )

        if value ~= nil
            and value ~= false then
            App.LoadingProtection.Suspend(
                "Teleport attribute detected • restoring loading visuals"
            )
        end
    end)
end

App.LoadingProtection.Resume = function()
    if not App.LoadingProtection.Suspended then
        return
    end

    App.LoadingProtection.Suspended = false
    App.LoadingProtection.Status = "Optimization resumed"


    pcall(applySimpleLighting, App.Values.SimpleLighting)
    pcall(applyRemoveFog, App.Values.RemoveFog)
    pcall(applyDisableParticlesTrails, App.Values.DisableParticlesTrails)
    pcall(applyLowDetailMaterials, App.Values.LowDetailMaterials)
    pcall(applyRemoveMapTextures, App.Values.RemoveMapTextures)
    pcall(applyRemoveMapProps, App.Values.RemoveMapProps, true)
    pcall(applyReduceTitanEffects, App.Values.ReduceTitanEffects)
    pcall(applyDisableCameraEffects, App.Values.DisableCameraEffects)
    if App.PerformanceControl and type(App.PerformanceControl.Apply3D) == "function" then
        pcall(App.PerformanceControl.Apply3D, App.Values.Disable3DRendering == true)
    end
end

App.LoadingProtection.GameplayReady = function()
    if RuntimeKind ~= "Gameplay" then
        return true
    end

    local character = player.Character
    local humanoid =
        character and character:FindFirstChildOfClass("Humanoid")
    local root =
        character and character:FindFirstChild("HumanoidRootPart")
    local camera = workspace.CurrentCamera

    if not humanoid
        or not root
        or humanoid.Health <= 0
        or not camera then
        return false
    end


    local subjectIsPlayer =
        camera.CameraSubject == humanoid
        or (
            typeof(camera.CameraSubject) == "Instance"
            and camera.CameraSubject:IsDescendantOf(character)
        )

    local cameraReleased =
        camera.CameraType ~= Enum.CameraType.Scriptable

    if subjectIsPlayer and cameraReleased then
        return true
    end

    return false
end

App.LoadingProtection.WaitForGameplayReady = function()
    if RuntimeKind ~= "Gameplay" then
        return true
    end

    App.LoadingProtection.Suspended = false
    App.LoadingProtection.Status = "Optimization active • waiting for gameplay camera"
    local started = os.clock()

    while gui and gui.Parent and os.clock() - started < 8.0 do
        if App.LoadingProtection.GameplayReady() then
            App.LoadingProtection.Status = "Gameplay ready • optimization active"
            return true
        end
        task.wait(0.20)
    end

    App.LoadingProtection.Status = "Optimization active"
    return App.LoadingProtection.GameplayReady()
end

LobbyRuntime.LaunchOnce = function()
    if RuntimeKind ~= "Lobby" then
        LobbyRuntime.LastInternalError = "Town Central required"
        LobbyRuntime.SetPublicStatus("Failed", "failed")
        return false, "Town Central required"
    end

    if LobbyRuntime.Busy then
        LobbyRuntime.SetPublicStatus("Waiting", "waiting")
        return false, "Master launch engine busy"
    end

    LobbyRuntime.Busy = true
    LobbyRuntime.TeleportSeen = false
    LobbyRuntime.InternalStatus = "Starting"
    LobbyRuntime.LastInternalError = nil
    LobbyRuntime.SetPublicStatus("Waiting", "waiting")

    if App.Values.AutoExecuteOnTeleport == true then
        pcall(queueV12AutoExecute, true)
    end

    local config = LobbyRuntime.BuildRunConfig()
    LobbyRuntime.ForceDefaultLaunch = false

    if App.RunState then
        local runData = App.RunState.Data or App.RunState.Load()
        runData.PendingMode = tostring(config.CreateMode or "Mission")
        runData.PendingRaidChoice = tostring(config.RaidChoice or "")
        runData.PendingLaunchUnix = os.time()
        App.RunState.Save()
    end

    local wavesMode = tostring(config.CreateMode or "") == "Waves"
    local hardestRequested =
        tostring(config.Difficulty or "") == "Hardest"
        and not wavesMode

    local createdMission = nil
    local acceptedDifficulty = nil

    local function fail(reason, created)
        if App.LoadingProtection
            and App.LoadingProtection.Suspended then
            App.LoadingProtection.Resume()
        end

        if created then
            pcall(function()
                lobbyInvokeMission("Leave")
            end)
            lobbyWaitOwned(false, 1.0)
        end

        LobbyRuntime.Busy = false
        LobbyRuntime.InternalStatus = "Failed"
        LobbyRuntime.LastInternalError = tostring(reason)
        LobbyRuntime.SetPublicStatus("Failed", "failed")

        return false, tostring(reason)
    end


    LobbyRuntime.InternalStatus =
        "Master • clearing stale mission"

    if not wavesMode then
        pcall(function()
            lobbyInvokeMission("Leave")
        end)

        if not lobbyWaitOwned(
            false,
            hardestRequested and 3.25 or 3.00
        ) then
            return fail(
                hardestRequested
                    and "Could not clear owned mission before Hardest"
                    or "Could not clear existing owned mission",
                false
            )
        end
    end


    if hardestRequested then


        local order =
            LobbyRuntime.HardestOrder(config)

        if #order == 0 then
            return fail(
                "No server-authoritative Hardest order is valid for this run",
                false
            )
        end

        local attemptErrors = {}

        for _, difficulty in ipairs(order) do
            LobbyRuntime.InternalStatus =
                "Hardest probe • "
                .. tostring(difficulty)

            local attemptConfig = {}
            for key, value in pairs(config) do
                if type(value) == "table" then
                    local nested = {}
                    for nestedKey, nestedValue in pairs(value) do
                        nested[nestedKey] = nestedValue
                    end
                    attemptConfig[key] = nested
                else
                    attemptConfig[key] = value
                end
            end

            attemptConfig.Difficulty = difficulty
            attemptConfig.AdaptiveDifficulty = true
            attemptConfig.AdaptiveRequested = "Hardest"
            attemptConfig.AdaptiveSource =
                "server-owned mission confirmation"

            local attemptPayload =
                LobbyRuntime.BuildPayload(
                    attemptConfig
                )

            local invokeDone = false
            local createOk = nil
            local createResponse = nil
            local createErr = nil
            local attemptLive = true

            task.spawn(function()
                local ok, response, err =
                    lobbyInvokeMission(
                        "Create",
                        attemptPayload
                    )

                if attemptLive then
                    createOk = ok
                    createResponse = response
                    createErr = err
                    invokeDone = true
                end
            end)

            local ownedMission = nil


            local deadline =
                os.clock() + 3.75

            repeat
                ownedMission =
                    lobbyOwnedMission()

                if ownedMission then
                    break
                end

                if invokeDone
                    and createOk == false then
                    break
                end

                task.wait(0.05)
            until os.clock() >= deadline

            attemptLive = false

            if ownedMission then
                config = attemptConfig
                createdMission = ownedMission
                acceptedDifficulty = difficulty

                LobbyRuntime.HardestLast = {
                    ok = true,
                    pending = false,
                    mode = tostring(
                        config.CreateMode or "Mission"
                    ),
                    raidChoice = config.RaidChoice,
                    difficulty = difficulty,
                    source =
                        "server-owned mission confirmation",
                    mission =
                        tostring(ownedMission.Name),
                }

                LobbyRuntime.InternalStatus =
                    "Hardest accepted • "
                    .. tostring(difficulty)

                break
            end

            if not invokeDone then
                attemptErrors[#attemptErrors + 1] =
                    tostring(difficulty)
                    .. ": Create timed out"
            elseif createOk == false then
                attemptErrors[#attemptErrors + 1] =
                    tostring(difficulty)
                    .. ": invoke failed: "
                    .. tostring(createErr)
            else
                attemptErrors[#attemptErrors + 1] =
                    tostring(difficulty)
                    .. ": no owned mission appeared; response="
                    .. tostring(createResponse)
            end

            LobbyRuntime.InternalStatus =
                "Hardest rejected • "
                .. tostring(difficulty)


            task.wait(0.12)
        end

        if not createdMission then
            LobbyRuntime.HardestLast = {
                ok = false,
                pending = false,
                mode = tostring(
                    config.CreateMode or "Mission"
                ),
                raidChoice = config.RaidChoice,
                error =
                    "server rejected every difficulty",
                source =
                    "server-owned mission confirmation",
                attempts = attemptErrors,
            }

            return fail(
                "Hardest server probe failed: "
                    .. table.concat(
                        attemptErrors,
                        " | "
                    ),
                false
            )
        end
    else
        local payload =
            LobbyRuntime.BuildPayload(config)

        LobbyRuntime.InternalStatus =
            "Master Create • "
            .. tostring(config.CreateMode)

        local createOk, createResponse, createErr =
            lobbyInvokeMission(
                "Create",
                payload
            )

        if not createOk then
            return fail(
                "Create invoke failed • "
                    .. tostring(createErr),
                false
            )
        end

        createdMission = createResponse


        if not wavesMode then
            -- V15.8.1: Create can return before the replicated owned mission
            -- appears. Wait for the authoritative mission object instead of
            -- killing Auto Launch on a transient nil response.
            local ownedMission = lobbyWaitOwned(true, 1.75)

            if ownedMission then
                createdMission = ownedMission
            elseif createdMission == nil then
                return fail(
                    "Create returned nil and no owned mission appeared",
                    false
                )
            elseif type(createdMission) == "string" then
                return fail(
                    "Create rejected • "
                        .. tostring(createdMission),
                    false
                )
            end
        end
    end

    task.wait(0.045)


    if not wavesMode then
        for _, modifier in ipairs(
            config.Modifiers or {}
        ) do
            LobbyRuntime.InternalStatus =
                "Master Modify • "
                .. tostring(modifier)

            local modifyOk, enabled, modifyErr =
                lobbyInvokeMission(
                    "Modify",
                    tostring(modifier)
                )

            if not modifyOk then
                return fail(
                    "Modify failed • "
                        .. tostring(modifier)
                        .. " • "
                        .. tostring(modifyErr),
                    true
                )
            end

            if enabled == nil then

                task.wait(0.12)
                modifyOk, enabled, modifyErr =
                    lobbyInvokeMission(
                        "Modify",
                        tostring(modifier)
                    )
            end

            if not modifyOk or enabled == nil then
                return fail(
                    not modifyOk
                        and ("Modify failed • " .. tostring(modifier) .. " • " .. tostring(modifyErr))
                        or ("Modify returned nil • " .. tostring(modifier)),
                    true
                )
            end

            task.wait(0.018)
        end
    end


    LobbyRuntime.InternalStatus =
        hardestRequested
        and (
            "Master Start • Hardest = "
            .. tostring(config.Difficulty)
        )
        or (
            "Master Start • "
            .. tostring(config.CreateMode)
        )


    if App.LoadingProtection then
        App.LoadingProtection.Suspend(
            "Protecting AOT:R loading screen"
        )
        task.wait(0.10)
    end

    local startOk, _, startErr =
        lobbyInvokeMission("Start")

    if not startOk then
        -- Transport errors sometimes happen after AOT:R already accepted Start.
        -- Give teleport state a grace window before tearing down that mission.
        local graceStartedAt = os.clock()
        while os.clock() - graceStartedAt < 2.50
            and not lobbyTeleportStarted() do
            task.wait(0.05)
        end

        if not lobbyTeleportStarted() then
            return fail(
                "Start invoke failed • "
                    .. tostring(startErr),
                true
            )
        end
    end


    local startedAt = os.clock()


    while os.clock() - startedAt < 25.00 do
        if lobbyTeleportStarted() then
            LobbyRuntime.Busy = false

            LobbyRuntime.InternalStatus =
                hardestRequested
                    and (
                        "Master launch accepted • "
                        .. tostring(config.Difficulty)
                    )
                    or "Master launch accepted"
            LobbyRuntime.SetPublicStatus("Ready", "ready")

            return true,
                hardestRequested
                    and "server-confirmed Hardest launch"
                    or "exact Master launch"
        end

        task.wait(0.05)
    end

    return fail(
        "Start sent once • transition not detected • no resend",
        true
    )
end

LobbyRuntime.Launch = function()
    App.Values.LobbyKickPartyBeforeLaunch = false

    -- V15.8.1 Auto Launch recovery. We never spam Start on the same owned
    -- mission: LaunchOnce tears down a confirmed failed mission first, then the
    -- next attempt creates a fresh one. This replaces the old one-shot path.
    local maxAttempts = 3
    local lastMessage = "Launch failed"

    for attempt = 1, maxAttempts do
        if lobbyTeleportStarted() then
            LobbyRuntime.Busy = false
            LobbyRuntime.AutoLaunchFailures = 0
            LobbyRuntime.SetPublicStatus("Ready", "ready")
            return true, "teleport already started"
        end

        LobbyRuntime.AutoLaunchLastAttemptAt = os.clock()
        LobbyRuntime.SetPublicStatus(
            attempt > 1
                and ("Launch retry " .. tostring(attempt) .. "/" .. tostring(maxAttempts))
                or "Waiting",
            attempt > 1 and "retry" or "waiting"
        )

        local forceDefault = attempt > 1 and App.Values.AutoJoinBoostedMaps == true
        if forceDefault and App.BoostedMaps then
            App.BoostedMaps.LastAction = "Boosted failed → Default Launch"
        end
        LobbyRuntime.ForceDefaultLaunch = forceDefault
        local ok, message = LobbyRuntime.LaunchOnce()
        if ok then
            LobbyRuntime.AutoLaunchFailures = 0
            LobbyRuntime.SetPublicStatus("Ready", "ready")
            return true, message
        end

        lastMessage = tostring(message or "Launch failed")
        LobbyRuntime.LastInternalError = lastMessage
        LobbyRuntime.AutoLaunchFailures =
            (tonumber(LobbyRuntime.AutoLaunchFailures) or 0) + 1

        if attempt < maxAttempts
            and RuntimeKind == "Lobby"
            and not lobbyTeleportStarted() then
            local backoff = math.min(5, 1 + attempt)
            for remaining = backoff, 1, -1 do
                if lobbyTeleportStarted() then break end
                LobbyRuntime.SetPublicStatus(
                    "Retrying in " .. tostring(remaining) .. "s",
                    "retry"
                )
                task.wait(1)
            end
        end
    end

    LobbyRuntime.SetPublicStatus("Failed", "failed")
    if App.AFKManager and App.Values.FailsafeEnabled ~= true then
        App.AFKManager.MarkAttention("Automation could not continue")
    end
    return false, lastMessage
end


App.Failsafe.AutomationActive = function()
    if RuntimeKind == "MainMenu" then
        return App.Values.MainAutoSelectSlot == true
    end

    if RuntimeKind == "Lobby" then
        return App.Values.LobbyAutoLaunch == true
            or App.Values.AutoTSLaunchNext == true
            or App.Values.AutoUpgradeEnabled == true
            or App.Values.AutoPrestigeEnabled == true
    end

    return App.Values.AutoFarmBlades == true
        or App.Values.AutoFarmSpears == true
        or App.Values.WavesAutoFarm == true
        or App.Values.WavesAutoSkip == true
        or App.Values.WavesAutoCrates == true
        or App.Values.WavesAutoUpgrade == true
        or App.Values.WavesAutoBuyTS == true
        or App.Values.AutoTSDoQuests == true
        or (App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true)
end

App.Failsafe.SetSmartState = function(state, detail)
    state = tostring(state or "Idle")
    if tostring(App.Failsafe.SmartState or "") ~= state then
        App.Failsafe.SmartState = state
        App.Failsafe.SmartSince = os.clock()
    elseif (tonumber(App.Failsafe.SmartSince) or 0) <= 0 then
        App.Failsafe.SmartSince = os.clock()
    end
    App.Failsafe.SmartDetail = tostring(detail or state)
end

App.Failsafe.SmartThreshold = function(state)
    if state == "Launching" then return 45 end
    if state == "LobbyAutoLaunch" then
        return math.max(90, (tonumber(App.Values.LobbyLaunchDelay) or 10) + 45)
    end
    if state == "Loading" then return 120 end
    if state == "Dead" then return 45 end
    if state == "Result" then return 60 end
    return nil
end

App.Failsafe.SmartStep = function()
    if App.Values.FailsafeEnabled ~= true
        or App.Values.FailsafeSmart ~= true
        or App.Failsafe.Triggering then
        App.Failsafe.SetSmartState("Idle", "Waiting")
        return false
    end

    local active = App.Failsafe.AutomationActive()
    local state, detail = "Healthy", "Runtime healthy"

    if RuntimeKind == "Lobby" then
        if LobbyRuntime.Busy == true then
            state, detail = "Launching", "Launch transition"
        elseif active and App.Values.LobbyAutoLaunch == true
            and LobbyRuntime.TeleportSeen ~= true then
            state, detail = "LobbyAutoLaunch", "Waiting for Auto Launch"
        end
    elseif RuntimeKind == "Gameplay" then
        local result = exactResultPanel()
        if result
            and ((App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true)
                or (App.Values.AutoTSDoQuests == true
                    and App.Values.AutoTSReturnLobby == true)) then
            state, detail = "Result", "Result transition stalled"
        else
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and character:FindFirstChild("HumanoidRootPart")

            if active and (not humanoid or not root or humanoid.Health <= 0) then
                state, detail = "Dead", "Waiting for respawn"
            elseif active and App.LoadingProtection
                and type(App.LoadingProtection.GameplayReady) == "function"
                and not App.LoadingProtection.GameplayReady() then
                state, detail = "Loading", "Loading / camera transition"
            end
        end
    end

    App.Failsafe.SetSmartState(state, detail)

    -- V15.6.34: the hard failsafe timer is execution-based.
    -- It is armed once when SliceHub starts and counts down continuously.
    -- Smart Recovery remains an independent early-stall detector and MUST NOT
    -- refresh/push the hard deadline forward while the runtime is healthy.

    local threshold = App.Failsafe.SmartThreshold(state)
    if threshold then
        local age = os.clock() - (tonumber(App.Failsafe.SmartSince) or os.clock())
        if age >= threshold then
            -- Smart Recovery is diagnostic/early-warning only. The configured
            -- hard Failsafe timer is authoritative for lobby/main-menu recovery;
            -- a 10 minute timer must never teleport at 5 minutes because a smart
            -- loading/result heuristic fired early.
            local remaining = math.max(0, (tonumber(App.Failsafe.Deadline) or 0) - os.clock())
            App.Failsafe.LastReason =
                "Smart watch • " .. tostring(detail) .. " • hard timer " .. tostring(math.ceil(remaining)) .. "s"
            return false
        end
    end

    return false
end

