App.AutoUpgrade.DetectWeapon = function(liveOnly)
    local spearScore = 0
    local bladeScore = 0

    local function scoreText(raw, weight)
        local value =
            string.lower(
                tostring(raw or "")
            )

        if value == "" then
            return
        end

        if string.find(value, "thunder spear", 1, true)
            or string.find(value, "thunderspear", 1, true)
            or string.find(value, "spear", 1, true) then
            spearScore += weight
        end

        if string.find(value, "blade", 1, true)
            or string.find(value, "sword", 1, true) then
            bladeScore += weight
        end
    end

    local liveCharacter = player.Character
    local liveBackpack =
        player:FindFirstChildOfClass("Backpack")

    for _, root in ipairs({
        liveCharacter,
        liveBackpack,
    }) do
        if root then
            scoreText(root.Name, 1)

            for _, object in ipairs(root:GetDescendants()) do
                scoreText(
                    object.Name,
                    object:IsA("Tool")
                        and 8
                        or 2
                )

                if object:IsA("StringValue") then
                    scoreText(
                        object.Value,
                        5
                    )
                end
            end
        end
    end

    if liveCharacter then
        if liveCharacter:GetAttribute("Spears") ~= nil then
            spearScore += 12
        end

        if liveCharacter:GetAttribute("Max_Spears") ~= nil then
            spearScore += 12
        end

        if liveCharacter:GetAttribute("BladeDurability") ~= nil then
            bladeScore += 8
        end

        if liveCharacter:GetAttribute("Blades") ~= nil then
            bladeScore += 8
        end
    end

    for key, value in pairs(player:GetAttributes()) do
        scoreText(key, 4)
        scoreText(value, 4)
    end

    for _, object in ipairs(
        App.AutoUpgrade.GameTextObjects()
    ) do
        local value =
            string.lower(
                tostring(object.Text or "")
            )

        if string.find(value, "equipped", 1, true)
            or string.find(value, "loadout", 1, true)
            or string.find(value, "current gear", 1, true) then
            scoreText(value, 10)
        end
    end

    if spearScore >= bladeScore + 3
        and spearScore >= 6 then
        return "Spears"
    end

    if bladeScore >= spearScore + 3
        and bladeScore >= 6 then
        return "Blades"
    end

    if liveOnly == true then
        return "Unknown"
    end

    if App.AutoUpgrade.LastWeapon ~= "Unknown" then
        return App.AutoUpgrade.LastWeapon
    end

    return "Unknown"
end

App.AutoUpgrade.Remote = function()
    return lobbyGET()
end

App.AutoUpgrade.SelectedRemoteKeys = function(weapon)
    local keys = {}

    for _, stat in ipairs(
        App.AutoUpgrade.StatsForWeapon(weapon)
    ) do
        if App.Values[stat.ValueKey] == true
            and stat.RemoteKey then
            keys[#keys + 1] =
                stat.RemoteKey
        end
    end

    return keys
end

App.AutoUpgrade.ResolveSlot = function(profile)
    if type(profile) ~= "table" then return nil,nil end
    if type(profile.Upgrades)=="table" or type(profile.Currency)=="table" or type(profile.Progression)=="table" then return "Active",profile end
    local root=profile
    if type(profile.Data)=="table" then
        root=profile.Data
        if type(root.Upgrades)=="table" or type(root.Currency)=="table" or type(root.Progression)=="table" then return "Active",root end
    end
    local slots=type(root.Slots)=="table" and root.Slots or nil
    if not slots then return nil,nil end
    local candidates,seen={},{}
    local function add(value)
        if value==nil then return end
        local tag=tostring(value); if tag=="" or seen[tag] then return end
        seen[tag]=true; candidates[#candidates+1]=value
    end
    add(player:GetAttribute("Slot")); add(root.Current_Slot); add(profile.Current_Slot); add(App.Values and App.Values.MainSlot)
    local named=tostring(App.Values and App.Values.MainSlot or "")
    add(({A=1,B=2,C=3})[string.upper(named)])
    for _,candidate in ipairs(candidates) do
        for _,key in ipairs({candidate,tostring(candidate),tonumber(candidate)}) do
            if key~=nil and type(slots[key])=="table" then return key,slots[key] end
        end
    end
    local onlyKey,onlySlot,count=nil,nil,0
    local hydratedKey,hydratedSlot,hydratedCount=nil,nil,0
    for key,value in pairs(slots) do
        if type(value)=="table" then
            count+=1; onlyKey,onlySlot=key,value
            if type(value.Upgrades)=="table" or type(value.Currency)=="table" or type(value.Progression)=="table" then hydratedCount+=1; hydratedKey,hydratedSlot=key,value end
        end
    end
    if hydratedCount==1 then return hydratedKey,hydratedSlot end
    if count==1 then return onlyKey,onlySlot end
    return nil,nil
end

App.AutoUpgrade.CoerceNumber = function(value)
    if type(value) == "number" then
        return value
    end

    local text =
        string.lower(
            tostring(value or "")
        )

    text = string.gsub(text, ",", "")
    text = string.gsub(text, "%s+", "")

    local raw, suffix =
        string.match(
            text,
            "^([%+%-]?[%d%.]+)([kmb]?)$"
        )

    local numberValue = tonumber(raw)

    if numberValue == nil then
        return nil
    end

    if suffix == "k" then
        numberValue *= 1000
    elseif suffix == "m" then
        numberValue *= 1000000
    elseif suffix == "b" then
        numberValue *= 1000000000
    end

    return numberValue
end

App.AutoUpgrade.CopyLevels = function(source)
    local output = {}

    if type(source) == "table" then
        for key, value in pairs(source) do
            if type(value) == "number" then
                output[tostring(key)] =
                    value
            end
        end
    end

    return output
end

App.AutoUpgrade.ParseProfile = function(result, weapon)
    if type(result) ~= "table" then
        return nil, nil, nil
    end

    local _, slot =
        App.AutoUpgrade.ResolveSlot(result)

    if type(slot) ~= "table" then
        return nil, nil, nil
    end

    local upgrades =
        type(slot.Upgrades) == "table"
        and slot.Upgrades
        or nil

    local weaponLevels =
        upgrades
        and upgrades[weapon]
        or nil

    local levels =
        App.AutoUpgrade.CopyLevels(
            weaponLevels
        )

    local currency =
        type(slot.Currency) == "table"
        and slot.Currency
        or nil

    local progression =
        type(slot.Progression) == "table"
        and slot.Progression
        or nil

    local gold =
        currency
        and App.AutoUpgrade.CoerceNumber(
            currency.Gold
        )
        or nil

    local prestige =
        progression
        and App.AutoUpgrade.CoerceNumber(
            progression.Prestige
        )
        or nil

    return levels, gold, prestige
end


App.AutoUpgrade.FetchProfile = function(weapon)
    local remote=App.AutoUpgrade.Remote()
    if not remote then return nil,nil,nil,nil end
    local ok,profile=pcall(function() return remote:InvokeServer("Functions","Settings","Get") end)
    if not ok or type(profile)~="table" then return nil,nil,nil,nil end
    local levels,gold,prestige=App.AutoUpgrade.ParseProfile(profile,weapon)
    return levels,gold,prestige,profile
end

App.AutoUpgrade.LevelGain = function(
    beforeLevels,
    afterLevels,
    keys
)
    if type(beforeLevels) ~= "table"
        or type(afterLevels) ~= "table" then
        return nil
    end

    local gain = 0

    for _, key in ipairs(keys or {}) do
        local before =
            tonumber(beforeLevels[key])

        local after =
            tonumber(afterLevels[key])

        if before ~= nil
            and after ~= nil
            and after > before then
            gain += after - before
        end
    end

    return gain
end

App.AutoUpgrade.ReadNativeGold = function()
    local interface =
        playerGui:FindFirstChild("Interface")

    local topbar =
        interface
        and interface:FindFirstChild("Topbar")

    local main =
        topbar
        and topbar:FindFirstChild("Main")

    local currencies =
        main
        and main:FindFirstChild("Currencies")

    local goldRoot =
        currencies
        and currencies:FindFirstChild("Gold")

    if not goldRoot then
        return nil
    end

    for _, name in ipairs({
        "Amount",
        "Value",
        "Text",
        "Count",
    }) do
        local object =
            goldRoot:FindFirstChild(
                name,
                true
            )

        if object
            and (
                object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox")
            ) then
            local value =
                App.AutoUpgrade.CoerceNumber(
                    object.Text
                )

            if value ~= nil then
                return value
            end
        end
    end

    if goldRoot:IsA("TextLabel")
        or goldRoot:IsA("TextButton")
        or goldRoot:IsA("TextBox") then
        return App.AutoUpgrade.CoerceNumber(
            goldRoot.Text
        )
    end

    return nil
end

App.AutoUpgrade.DetectNativeStopReason = function()
    for _, object in ipairs(
        App.AutoUpgrade.GameTextObjects()
    ) do
        local value =
            string.lower(
                tostring(object.Text or "")
            )

        value =
            string.gsub(
                value,
                "<.->",
                ""
            )

        value =
            string.gsub(
                value,
                "%s+",
                " "
            )

        if string.find(value, "not enough gold", 1, true)
            or string.find(value, "insufficient gold", 1, true)
            or string.find(value, "cannot afford", 1, true) then
            return "NO_GOLD",
                "Not enough Gold"
        end

        if string.find(value, "maxed", 1, true)
            or string.find(value, "maximum level", 1, true)
            or string.find(value, "max level", 1, true) then
            return "MAXED",
                "Selected gear stats are maxed"
        end
    end

    return nil, nil
end

App.AutoUpgrade.BeginRun = function()
    App.AutoUpgrade.RunStartWeapon=App.AutoUpgrade.DetectWeapon()
    App.AutoUpgrade.RunStartedAt=os.clock()
    App.AutoUpgrade.RunFinalized=false
    App.AutoUpgrade.CycleComplete=false
    App.AutoUpgrade.Clicks=0
    App.AutoUpgrade.Passes=0
    App.AutoUpgrade.LastLevels={}
    App.AutoUpgrade.RunWebhookSent=false

    local weapon=App.AutoUpgrade.RunStartWeapon
    local levels,gold,prestige=nil,nil,nil
    if weapon~="Unknown" then levels,gold,prestige=App.AutoUpgrade.FetchProfile(weapon) end
    if type(levels)=="table" then App.AutoUpgrade.LastLevels[weapon]=levels end
    App.AutoUpgrade.RunStartGold=gold~=nil and gold or App.AutoUpgrade.ReadNativeGold()
    App.AutoUpgrade.LastGold=gold or App.AutoUpgrade.RunStartGold
    if prestige~=nil then App.AutoUpgrade.LastPrestige=prestige end
end

App.AutoUpgrade.ClassifyResponse = function(result)
    if type(result) == "table" then
        return "SUCCESS"
    end

    if type(result) == "string" then
        local value =
            string.lower(result)

        if string.find(value, "max", 1, true) then
            return "MAXED"
        end

        if string.find(value, "gold", 1, true)
            or string.find(value, "fund", 1, true)
            or string.find(value, "currency", 1, true)
            or string.find(value, "afford", 1, true) then
            return "NO_GOLD"
        end

        return "REJECTED"
    end

    if result == false then
        return "REJECTED"
    end

    return "NO_PROGRESS"
end

App.AutoUpgrade.InvokeBatch = function(keys)
    local remote =
        App.AutoUpgrade.Remote()

    if not remote then
        return false,
            nil,
            "GET RemoteFunction missing"
    end

    local ok, result =
        pcall(function()
            return remote:InvokeServer(
                "S_Equipment",
                "Upgrade",
                keys
            )
        end)

    if not ok then
        return false,
            nil,
            tostring(result)
    end

    return true, result, nil
end

App.AutoUpgrade.TrySingleStatRecovery = function(weapon, keys)
    local total=0
    local latestLevels,latestGold,latestPrestige=App.AutoUpgrade.FetchProfile(weapon)
    for _,key in ipairs(keys or {}) do
        local before=latestLevels
        local ok,result=App.AutoUpgrade.InvokeBatch({key})
        if not ok then continue end
        local kind=App.AutoUpgrade.ClassifyResponse(result)
        if kind=="NO_GOLD" then break end
        task.wait(0.14)
        local after,gold,prestige=App.AutoUpgrade.FetchProfile(weapon)
        local gain=App.AutoUpgrade.LevelGain(before,after,{key})
        if type(gain)=="number" and gain>0 then
            total+=gain; latestLevels=after; latestGold=gold or latestGold; latestPrestige=prestige or latestPrestige
        elseif type(after)=="table" then
            latestLevels=after; latestGold=gold or latestGold; latestPrestige=prestige or latestPrestige
        end
    end
    if type(latestLevels)=="table" then App.AutoUpgrade.LastLevels[weapon]=latestLevels end
    if latestGold~=nil then App.AutoUpgrade.LastGold=latestGold end
    if latestPrestige~=nil then App.AutoUpgrade.LastPrestige=latestPrestige end
    return total
end

App.AutoUpgrade.StopCycle = function(
    resultType,
    reason
)
    if tostring(resultType or "") == "STOPPED" then
        App.Values.AutoUpgradeEnabled =
            false
    end

    App.AutoUpgrade.CycleComplete =
        true

    App.AutoUpgrade.RunFinalized =
        true

    App.AutoUpgrade.LastResultType =
        tostring(
            resultType
            or "STOPPED"
        )

    App.AutoUpgrade.LastAction =
        tostring(
            reason
            or resultType
            or "Stopped"
        )

    if App.AutoUpgrade.RunWebhookSent ~= true
        and (tonumber(App.AutoUpgrade.Clicks) or 0) > 0
        and App.LobbyWebhook then
        App.AutoUpgrade.RunWebhookSent = true
        local _,serverGold = App.AutoUpgrade.FetchProfile(App.AutoUpgrade.LastWeapon or App.AutoUpgrade.Weapon)
        local goldAfter = serverGold ~= nil and serverGold or (App.AutoUpgrade.ReadNativeGold and App.AutoUpgrade.ReadNativeGold() or nil)
        local fields = {
            App.LobbyWebhook.Field("Gear", tostring(App.AutoUpgrade.LastWeapon or App.AutoUpgrade.Weapon or "Unknown"), true),
            App.LobbyWebhook.Field("Confirmed Levels", tostring(App.AutoUpgrade.Clicks or 0), true),
            App.LobbyWebhook.Field("Result", tostring(App.AutoUpgrade.LastAction), false),
            App.LobbyWebhook.Field("Gold", (App.AutoUpgrade.RunStartGold~=nil or goldAfter~=nil) and ((App.AutoUpgrade.RunStartGold~=nil and App.Webhook.FormatNumber(App.AutoUpgrade.RunStartGold) or "?").." → "..(goldAfter~=nil and App.Webhook.FormatNumber(goldAfter) or "?")) or nil, false),
        }
        task.spawn(function() App.LobbyWebhook.Send("Gear","Gear Upgraded",fields) end)
    end
end

App.AutoUpgrade.RunPass = function()
    if RuntimeKind~="Lobby" then return 0,"Town Central required" end
    if App.AutoUpgrade.Busy then return 0,"busy" end
    App.AutoUpgrade.Busy=true
    if App.AutoUpgrade.RunFinalized==true or (tonumber(App.AutoUpgrade.RunStartedAt) or 0)<=0 then App.AutoUpgrade.BeginRun() end

    local weapon=App.AutoUpgrade.DetectWeapon()
    App.AutoUpgrade.Weapon=weapon
    if weapon~="Unknown" then App.AutoUpgrade.LastWeapon=weapon end
    if weapon=="Unknown" then App.AutoUpgrade.LastAction="Waiting for equipped loadout detection"; App.AutoUpgrade.Busy=false; return 0,"unknown loadout" end

    local keys=App.AutoUpgrade.SelectedRemoteKeys(weapon)
    if #keys==0 then App.AutoUpgrade.LastAction="No stats selected"; App.AutoUpgrade.Busy=false; return 0,"no stats selected" end
    App.AutoUpgrade.Passes+=1

    local beforeLevels,beforeGold,beforePrestige=App.AutoUpgrade.FetchProfile(weapon)
    if type(beforeLevels)~="table" then beforeLevels=App.AutoUpgrade.LastLevels[weapon] end
    if beforeGold==nil then beforeGold=App.AutoUpgrade.LastGold or App.AutoUpgrade.ReadNativeGold() end
    if type(beforeLevels)=="table" then App.AutoUpgrade.LastLevels[weapon]=beforeLevels end
    if beforeGold~=nil then App.AutoUpgrade.LastGold=beforeGold end
    if beforePrestige~=nil then App.AutoUpgrade.LastPrestige=beforePrestige end

    App.AutoUpgrade.LastAction="Sending "..tostring(#keys).." selected "..tostring(weapon).." stats"
    local ok,result,remoteError=App.AutoUpgrade.InvokeBatch(keys)
    if not ok then App.AutoUpgrade.StopCycle("ERROR","Remote error • "..tostring(remoteError)); App.AutoUpgrade.Busy=false; return 0,App.AutoUpgrade.LastAction end

    task.wait(0.14)
    local afterLevels,afterGold,afterPrestige=App.AutoUpgrade.FetchProfile(weapon)
    local resultType=App.AutoUpgrade.ClassifyResponse(result)
    local verifiedGain=App.AutoUpgrade.LevelGain(beforeLevels,afterLevels,keys)
    if type(verifiedGain)=="number" and verifiedGain>0 then
        resultType="SUCCESS"
    elseif type(beforeLevels)=="table" and type(afterLevels)=="table" and resultType=="SUCCESS" then

        resultType="NO_PROGRESS"
    end

    if type(afterLevels)=="table" then App.AutoUpgrade.LastLevels[weapon]=afterLevels end
    if afterGold~=nil then App.AutoUpgrade.LastGold=afterGold end
    if afterPrestige~=nil then App.AutoUpgrade.LastPrestige=afterPrestige end

    if resultType=="SUCCESS" then
        local confirmed=(type(verifiedGain)=="number" and verifiedGain>0) and verifiedGain or 1
        App.AutoUpgrade.Clicks+=confirmed
        App.AutoUpgrade.LastAction=string.format("Pass %d • +%d confirmed level%s",App.AutoUpgrade.Passes,confirmed,confirmed==1 and "" or "s")
        App.AutoUpgrade.Busy=false
        return confirmed,App.AutoUpgrade.LastAction
    end


    if (resultType=="NO_PROGRESS" or resultType=="REJECTED") and #keys>1 then
        local recovered=App.AutoUpgrade.TrySingleStatRecovery(weapon,keys)
        if recovered>0 then
            App.AutoUpgrade.Clicks+=recovered
            App.AutoUpgrade.LastAction=string.format("Recovery pass %d • +%d confirmed level%s",App.AutoUpgrade.Passes,recovered,recovered==1 and "" or "s")
            App.AutoUpgrade.Busy=false
            return recovered,App.AutoUpgrade.LastAction
        end
    end

    if resultType=="NO_PROGRESS" then
        local nativeType,nativeReason=App.AutoUpgrade.DetectNativeStopReason()
        if nativeType then resultType=nativeType; App.AutoUpgrade.LastAction=tostring(nativeReason) end
    end
    App.AutoUpgrade.LastResultType=resultType
    if resultType=="MAXED" then App.AutoUpgrade.StopCycle("MAXED","Selected gear stats are maxed")
    elseif resultType=="NO_GOLD" then App.AutoUpgrade.StopCycle("NO_GOLD","Not enough Gold for the next selected upgrade")
    elseif resultType=="REJECTED" then App.AutoUpgrade.StopCycle("REJECTED",tostring(result or "Upgrade request rejected"))
    else App.AutoUpgrade.StopCycle("NO_PROGRESS","No selected stat upgraded; selected stats appear maxed or unaffordable") end
    App.AutoUpgrade.Busy=false
    return 0,App.AutoUpgrade.LastAction
end

App.AutoUpgrade.SelectAll = function(value)
    local weapon =
        App.AutoUpgrade.DetectWeapon()

    if weapon == "Unknown" then
        App.AutoUpgrade.LastAction =
            "Waiting for equipped loadout detection"
        return false
    end

    for _, stat in ipairs(
        App.AutoUpgrade.StatsForWeapon(
            weapon
        )
    ) do
        App.Values[stat.ValueKey] =
            value == true
    end

    App.AutoUpgrade.LastAction =
        (
            value == true
            and "Selected all "
            or "Cleared "
        )
        .. tostring(weapon)
        .. " stats"

    if App.Values.AutoUpgradeEnabled then
        App.AutoUpgrade.BeginRun()
    end

    return true
end


App.AutoUpgrade.Enabled =
    App.Values.AutoUpgradeEnabled == true

if App.AutoUpgrade.Enabled then
    App.AutoUpgrade.BeginRun()
else
    App.AutoUpgrade.CycleComplete = true
    App.AutoUpgrade.RunFinalized = true
end


task.spawn(function()
    while gui and gui.Parent do
        local upgradeActive =
            RuntimeKind == "Lobby"
            and App.Values.AutoUpgradeEnabled == true

        task.wait(
            upgradeActive
            and 0.35
            or App.PerformanceControl.Delay(0.90, 1.40)
        )

        App.AutoUpgrade.Enabled =
            App.Values.AutoUpgradeEnabled == true

        if RuntimeKind == "Lobby"
            and App.AutoUpgrade.Enabled
            and not App.AutoUpgrade.Busy
            and App.AutoUpgrade.CycleComplete ~= true
            and not LobbyRuntime.Busy then

            local clicks =
                App.AutoUpgrade.RunPass()

            if clicks == 0 then
                task.wait(0.9)
            else
                task.wait(
                    math.clamp(
                        tonumber(
                            App.AutoUpgrade.Delay
                        )
                        or 0.55,
                        0.15,
                        2.0
                    )
                )
            end
        end
    end
end)

App.Prestige = {
    Busy = false,
    LastAction = "Waiting for profile",
    LastPrestige = nil,
    LastGold = nil,
    PendingProfile = nil,
    MemoryData = nil,
    LastCheckAt = 0,
    CooldownUntil = 0,
}

App.Prestige.ResolveSlot = function(profile)
    if type(profile) ~= "table" then return nil,nil end


    if type(profile.Progression)=="table" or type(profile.Currency)=="table" or type(profile.Perks)=="table" then
        return "Active",profile
    end

    local root=profile
    if type(profile.Data)=="table" and (type(profile.Data.Slots)=="table" or type(profile.Data.Progression)=="table" or type(profile.Data.Currency)=="table") then
        root=profile.Data
        if type(root.Progression)=="table" or type(root.Currency)=="table" or type(root.Perks)=="table" then return "Active",root end
    end

    local slots=type(root.Slots)=="table" and root.Slots or nil
    if not slots then return nil,nil end
    local candidates,seen={},{}
    local function add(value)
        if value==nil then return end
        local s=tostring(value)
        if s=="" or seen[s] then return end
        seen[s]=true; candidates[#candidates+1]=value
    end
    add(player:GetAttribute("Slot")); add(root.Current_Slot); add(profile.Current_Slot); add(App.Values and App.Values.MainSlot)
    local saved=tostring(App.Values and App.Values.MainSlot or "")
    add(({A=1,B=2,C=3})[string.upper(saved)])

    for _,candidate in ipairs(candidates) do
        local numeric=tonumber(candidate)
        for _,key in ipairs({candidate,tostring(candidate),numeric}) do
            if key~=nil and type(slots[key])=="table" then return key,slots[key] end
        end
    end

    local hydratedKey,hydratedSlot,hydratedCount=nil,nil,0
    local onlyKey,onlySlot,count=nil,nil,0
    for key,value in pairs(slots) do
        if type(value)=="table" then
            count+=1; onlyKey,onlySlot=key,value
            local progression=type(value.Progression)=="table" and value.Progression or {}
            if progression.Prestige~=nil or type(value.Currency)=="table" or type(value.Perks)=="table" then
                hydratedCount+=1; hydratedKey,hydratedSlot=key,value
            end
        end
    end
    if hydratedCount==1 then return hydratedKey,hydratedSlot end
    if count==1 then return onlyKey,onlySlot end
    return nil,nil
end

App.Prestige.ReadLocalNumber = function(kind)
    kind = tostring(kind or "")
    local names = kind == "Prestige"
        and {"Prestige","PrestigeLevel","Prestige_Level"}
        or {"Level","PlayerLevel","Player_Level","CurrentLevel","Current_Level"}

    local function parse(value)
        if tonumber(value) ~= nil then return tonumber(value) end
        local text = tostring(value or ""):gsub(",","")
        local number = string.match(text,"[-+]?%d+%.?%d*")
        return tonumber(number)
    end

    for _, name in ipairs(names) do
        local value = player:GetAttribute(name)
        local parsed = parse(value)
        if parsed ~= nil then return parsed end
        local object = player:FindFirstChild(name,true)
        if object and (object:IsA("IntValue") or object:IsA("NumberValue") or object:IsA("StringValue")) then
            parsed = parse(object.Value)
            if parsed ~= nil then return parsed end
        end
    end

    if kind == "Prestige" and App.AutoUpgrade and tonumber(App.AutoUpgrade.LastPrestige) ~= nil then
        return tonumber(App.AutoUpgrade.LastPrestige)
    end
    return nil
end

App.Prestige.ParseProfile = function(profile)
    local _,slot=App.Prestige.ResolveSlot(profile)
    if type(slot)~="table" then


        local prestige=App.Prestige.ReadLocalNumber("Prestige")
        local gold=App.AutoUpgrade and type(App.AutoUpgrade.ReadNativeGold)=="function" and App.AutoUpgrade.ReadNativeGold() or nil
        local level=App.Prestige.ReadLocalNumber("Level")
        return prestige,gold,nil,level
    end
    local progression=type(slot.Progression)=="table" and slot.Progression or slot
    local currency=type(slot.Currency)=="table" and slot.Currency or {}
    local coerce=App.AutoUpgrade and App.AutoUpgrade.CoerceNumber
    local function num(value) return type(coerce)=="function" and coerce(value) or tonumber(value) end
    local prestige=num(progression.Prestige or slot.Prestige or (type(profile)=="table" and profile.Prestige))
        or App.Prestige.ReadLocalNumber("Prestige")
    local gold=num(currency.Gold or slot.Gold or (type(profile)=="table" and profile.Gold))
    if gold==nil and App.AutoUpgrade and type(App.AutoUpgrade.ReadNativeGold)=="function" then gold=App.AutoUpgrade.ReadNativeGold() end
    local level=num(progression.Level) or num(progression.Current_Level) or num(progression.CurrentLevel)
        or num(progression.Player_Level) or num(progression.PlayerLevel) or num(progression.Lvl)
        or num(slot.Level) or num(slot.Current_Level) or num(slot.CurrentLevel)
        or (type(profile)=="table" and (num(profile.Level) or num(profile.Current_Level) or num(profile.CurrentLevel)) or nil)
        or App.Prestige.ReadLocalNumber("Level")
    return prestige,gold,slot,level
end

App.Prestige.ProfileState = tostring(App.Prestige.ProfileState or "Waiting")
App.Prestige.ProfileReadyAt = tonumber(App.Prestige.ProfileReadyAt) or 0

App.Prestige.ProfileStatusText = function()
    local state = tostring(App.Prestige.ProfileState or "Waiting")
    if state == "Ready" then
        local prestige = tonumber(App.Prestige.LastPrestige)
        return prestige ~= nil and ("Ready • P" .. tostring(math.floor(prestige + 0.5))) or "Ready"
    end
    if state == "Failed" then return "Not ready" end
    return state
end

App.Prestige.ProfileStatusKind = function()
    local state = tostring(App.Prestige.ProfileState or "Waiting")
    if state == "Ready" then return "good" end
    if state == "Failed" then return "failed" end
    return "waiting"
end

App.Prestige.GetProfile = function()
    local lastError="profile unavailable"
    local best=type(App.Prestige.PendingProfile)=="table" and App.Prestige.PendingProfile or nil
    App.Prestige.ProfileState="Loading"
    local premium=BUILD and BUILD.IsPremium==true

    local function accept(profile,source)
        if type(profile)~="table" then return false end
        best=profile; App.Prestige.PendingProfile=profile
        local prestige,gold,_,level=App.Prestige.ParseProfile(profile)
        if prestige~=nil then App.Prestige.LastPrestige=prestige end
        if gold~=nil then App.Prestige.LastGold=gold end
        if level~=nil then App.Prestige.LastLevel=level end
        local ready=prestige~=nil and ((premium and gold~=nil) or (not premium and level~=nil))
        if ready then
            App.Prestige.ProfileState="Ready"; App.Prestige.ProfileReadyAt=os.clock(); App.Prestige.LastProfileSource=tostring(source or "profile")
            return true
        end
        App.Prestige.ProfileState="Waiting"; lastError="profile slot not ready • "..tostring(source or "profile")
        return false
    end


    for attempt=1,4 do
        local remote=lobbyGET()
        if not remote then lastError="GET RemoteFunction missing" break end

        local okData,data=pcall(function() return remote:InvokeServer("Functions","Data") end)
        if okData and accept(data,"Functions/Data") then return data end
        if not okData then lastError=tostring(data or lastError) end

        local okSettings,settings=pcall(function() return remote:InvokeServer("Functions","Settings","Get") end)
        if okSettings and accept(settings,"Functions/Settings/Get") then return settings end
        if not okSettings then lastError=tostring(settings or lastError) end

        -- Memory safety: never probe S_Equipment/Talents as a background read.
        -- If profile state is incomplete, wait for the next normal data refresh.

        if attempt<4 then task.wait(0.12 + attempt*0.05) end
    end
    App.Prestige.ProfileState=type(best)=="table" and "Waiting" or "Failed"
    return best,lastError
end

App.Prestige.Memories = function()
    if App.Prestige.MemoryData ~= nil then
        return App.Prestige.MemoryData
    end

    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local storage = modules and modules:FindFirstChild("Storage")
    local memoryModule = storage and storage:FindFirstChild("Memories")
    if not memoryModule or not memoryModule:IsA("ModuleScript") then
        return nil
    end

    local ok, data = pcall(require, memoryModule)
    if ok and type(data) == "table" then
        App.Prestige.MemoryData = data
        return data
    end
    return nil
end

App.Prestige.FindTalentTagById = function(target)
    local memories = App.Prestige.Memories()
    local talents = memories and memories.Talents
    if type(talents) ~= "table" then return nil end

    local wanted = tostring(target)

    local function search(node, depth)
        if type(node) ~= "table" or depth > 5 then return nil end

        for key, value in pairs(node) do
            if tostring(key) == wanted
                and type(value) == "table"
                and type(value.Tag) == "string"
                and value.Tag ~= "" then
                return value.Tag
            end
        end

        for _, value in pairs(node) do
            if type(value) == "table" then
                local found = search(value, depth + 1)
                if found then return found end
            end
        end
        return nil
    end

    return search(talents, 0)
end

App.Prestige.ResolveTalent = function(offers)
    if type(offers) ~= "table" then return nil end

    local ordered = {}
    for index = 1, #offers do ordered[#ordered + 1] = offers[index] end
    if #ordered == 0 then
        for _, value in pairs(offers) do ordered[#ordered + 1] = value end
    end

    for _, offer in ipairs(ordered) do
        if type(offer) == "string" or type(offer) == "number" then
            local raw = tostring(offer)
            if raw ~= "" then
                local mapped = App.Prestige.FindTalentTagById(offer)
                if mapped then return mapped end
                return raw
            end
        elseif type(offer) == "table" then
            if type(offer.Tag) == "string" and offer.Tag ~= "" then
                return offer.Tag
            end
            local nested = App.Prestige.ResolveTalent(offer)
            if nested then return nested end
        end
    end
    return nil
end

App.Prestige.Threshold = function(prestige)
    local key = "PrestigeP" .. tostring(math.floor(tonumber(prestige) or -1)) .. "M"
    local millions = tonumber(App.Values[key])
    return millions and millions * 1000000 or nil
end

App.Prestige.LevelRequirements = {
    [0] = 100,
    [1] = 125,
    [2] = 150,
    [3] = 175,
    [4] = 200,
}

App.Prestige.RequiredLevel = function(prestige)
    return App.Prestige.LevelRequirements[math.floor(tonumber(prestige) or -1)]
end

App.Prestige.BuffTag = function()
    if App.Values.PrestigeBuff == "EXP" then return "EXP Boost" end
    if App.Values.PrestigeBuff == "Gold" then return "Gold Boost" end
    return "Luck Boost"
end

App.Prestige.FormatGold = function(value)
    value = tonumber(value) or 0
    if value >= 1000000000 then
        local scaled = value / 1000000000
        return (scaled % 1 == 0)
            and string.format("%.0fB", scaled)
            or string.format("%.2fB", scaled)
    end
    if value >= 1000000 then
        local scaled = value / 1000000
        return (scaled % 1 == 0)
            and string.format("%.0fM", scaled)
            or string.format("%.1fM", scaled)
    end
    return tostring(math.floor(value))
end

App.Prestige.StateText = function()
    if App.Prestige.LastPrestige == nil or App.Prestige.LastGold == nil then
        return "Waiting for Prestige / Gold"
    end
    return "P" .. tostring(math.floor(App.Prestige.LastPrestige + 0.5))
        .. " • " .. App.Prestige.FormatGold(App.Prestige.LastGold)
end

App.Prestige.SyncAuthorityState = function(profile)
    local parsedPrestige, parsedGold, slot, level =
        App.Prestige.ParseProfile(profile)

    local livePrestige =
        App.Prestige.ReadLocalNumber("Prestige")

    local prestige =
        tonumber(livePrestige)
        or tonumber(parsedPrestige)

    local gold = tonumber(parsedGold)

    if gold == nil
        and App.AutoUpgrade
        and type(App.AutoUpgrade.ReadNativeGold) == "function" then
        gold = tonumber(App.AutoUpgrade.ReadNativeGold())
    end

    level = tonumber(level)

    if prestige ~= nil then
        prestige = math.floor(prestige + 0.5)
        App.Prestige.LastPrestige = prestige
        if App.AutoUpgrade then
            App.AutoUpgrade.LastPrestige = prestige
        end
    end

    if gold ~= nil then
        App.Prestige.LastGold = gold
        if App.AutoUpgrade then
            App.AutoUpgrade.LastGold = gold
        end
    end

    if level ~= nil then
        App.Prestige.LastLevel = math.floor(level + 0.5)
    end

    return prestige, gold, slot, level
end

App.Prestige.FetchAuthorityState = function(remote)
    remote = remote or lobbyGET()
    if not remote then
        App.Prestige.ProfileState = "Failed"
        return nil, "GET RemoteFunction missing"
    end

    App.Prestige.ProfileState = "Loading"

    local okData, data = pcall(function()
        return remote:InvokeServer("Functions", "Data")
    end)

    if okData and type(data) == "table" then
        App.Prestige.PendingProfile = data
        local prestige, gold, _, level =
            App.Prestige.SyncAuthorityState(data)

        if prestige ~= nil and gold ~= nil then
            App.Prestige.ProfileState = "Ready"
            App.Prestige.ProfileReadyAt = os.clock()
            App.Prestige.LastProfileSource = "Functions/Data"
            return data
        end
    end

    local okSettings, settings = pcall(function()
        return remote:InvokeServer("Functions", "Settings", "Get")
    end)

    if okSettings and type(settings) == "table" then
        if type(data) ~= "table" then
            data = settings
        end

        App.Prestige.PendingProfile = settings
        local prestige, gold =
            App.Prestige.SyncAuthorityState(settings)

        if prestige ~= nil and gold ~= nil then
            App.Prestige.ProfileState = "Ready"
            App.Prestige.ProfileReadyAt = os.clock()
            App.Prestige.LastProfileSource = "Functions/Settings/Get"
            return data
        end
    end

    local prestige = App.Prestige.ReadLocalNumber("Prestige")
    local gold =
        App.AutoUpgrade
        and type(App.AutoUpgrade.ReadNativeGold) == "function"
        and App.AutoUpgrade.ReadNativeGold()
        or nil

    if prestige ~= nil then
        App.Prestige.LastPrestige = math.floor(tonumber(prestige) + 0.5)
        if App.AutoUpgrade then
            App.AutoUpgrade.LastPrestige = App.Prestige.LastPrestige
        end
    end

    if tonumber(gold) ~= nil then
        App.Prestige.LastGold = tonumber(gold)
        if App.AutoUpgrade then
            App.AutoUpgrade.LastGold = App.Prestige.LastGold
        end
    end

    App.Prestige.ProfileState =
        App.Prestige.LastPrestige ~= nil
        and App.Prestige.LastGold ~= nil
        and "Ready"
        or "Waiting"

    if App.Prestige.ProfileState == "Ready" then
        App.Prestige.ProfileReadyAt = os.clock()
        App.Prestige.LastProfileSource = "native"
        return data
    end

    return data,
        tostring(
            (not okData and data)
            or (not okSettings and settings)
            or "Prestige / Gold unavailable"
        )
end

App.Prestige.ResolveAuthorityTalent = function(remote, data)
    local function offersFrom(profile)
        local _, slot = App.Prestige.ResolveSlot(profile)
        if type(slot) ~= "table" then return nil end
        local offers = slot.Next_Talents
        return type(offers) == "table" and offers or nil
    end

    local offers = offersFrom(data)
        or offersFrom(App.Prestige.PendingProfile)

    -- Tekkit confirmed Prestige uses one of the three free offers before the
    -- single Prestige submit. Keep SliceHub's safer read path: refresh normal
    -- profile data only; never call the Memory/Talent reroll or inventory-use
    -- routes just to discover an offer.
    if type(offers) ~= "table" and remote then
        for attempt = 1, 4 do
            task.wait(0.15 + attempt * 0.05)
            local okData, fresh = pcall(function()
                return remote:InvokeServer("Functions", "Data")
            end)
            if okData and type(fresh) == "table" then
                data = fresh
                App.Prestige.PendingProfile = fresh
                App.Prestige.SyncAuthorityState(fresh)
                offers = offersFrom(fresh)
                if type(offers) == "table" then break end
            end
        end
    end

    if type(offers) ~= "table" then
        return nil, "free Memory offers unavailable"
    end

    local ordered = {}
    for _, index in ipairs({1, 2, 3}) do
        local offer = offers[index]
        if offer == nil then offer = offers[tostring(index)] end
        if offer ~= nil then ordered[#ordered + 1] = offer end
    end

    if #ordered == 0 then
        for _, offer in pairs(offers) do
            ordered[#ordered + 1] = offer
            if #ordered >= 3 then break end
        end
    end

    local talent = App.Prestige.ResolveTalent(ordered)
    if not talent then
        return nil, "free Memory offers invalid"
    end

    App.Prestige.LastTalent = tostring(talent)
    return talent, "free Memory pick"
end

App.Prestige.RunCheck = function(manual)
    if RuntimeKind ~= "Lobby" then
        return false, "Town Central required"
    end

    if App.Prestige.Busy then
        return false, "busy"
    end

    if not manual
        and App.Values.AutoPrestigeEnabled ~= true then
        return false, "disabled"
    end

    if not manual
        and os.clock() < (tonumber(App.Prestige.CooldownUntil) or 0) then
        return false, "cooldown"
    end

    App.Prestige.Busy = true
    App.Prestige.LastCheckAt = os.clock()

    local remote = lobbyGET()
    if not remote then
        App.Prestige.LastAction = "GET RemoteFunction missing"
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    local data, stateError =
        App.Prestige.FetchAuthorityState(remote)

    local prestige =
        tonumber(App.Prestige.ReadLocalNumber("Prestige"))
        or tonumber(App.Prestige.LastPrestige)

    local level =
        tonumber(App.Prestige.ReadLocalNumber("Level"))
        or tonumber(App.Prestige.LastLevel)

    local gold = tonumber(App.Prestige.LastGold)

    if prestige == nil or gold == nil or level == nil then
        App.Prestige.LastAction =
            "Waiting for Prestige / Gold / Level • "
            .. tostring(stateError or "profile not ready")
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    prestige = math.floor(prestige + 0.5)
    level = math.floor(level + 0.5)
    App.Prestige.LastPrestige = prestige
    App.Prestige.LastLevel = level
    App.Prestige.LastGold = gold

    if App.AutoUpgrade then
        App.AutoUpgrade.LastPrestige = prestige
        App.AutoUpgrade.LastGold = gold
    end

    local requiredLevel = App.Prestige.RequiredLevel and App.Prestige.RequiredLevel(prestige) or nil
    if requiredLevel == nil then
        App.Prestige.LastAction = "P" .. tostring(prestige) .. " • MAX / unsupported"
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    if level < requiredLevel then
        App.Prestige.LastAction =
            "P" .. tostring(prestige)
            .. " → P" .. tostring(prestige + 1)
            .. " requires Level " .. tostring(requiredLevel)
            .. " • Current " .. tostring(level)
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    local threshold = App.Prestige.Threshold(prestige)

    if threshold == nil then
        App.Prestige.LastAction =
            "P" .. tostring(prestige) .. " • MAX / unsupported"
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    if gold < threshold then
        App.Prestige.LastAction =
            "P" .. tostring(prestige)
            .. " • " .. App.Prestige.FormatGold(gold)
            .. " / " .. App.Prestige.FormatGold(threshold)
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    local talent, talentSource =
        App.Prestige.ResolveAuthorityTalent(remote, data)

    if not talent then
        App.Prestige.LastAction =
            "No valid offered Talent resolved • "
            .. tostring(talentSource or "unavailable")
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    local selection = {
        Boosts = App.Prestige.BuffTag(),
        Talents = talent,
    }

    local oldPrestige = prestige
    local acceptedResult = nil
    local pendingFrom = tonumber(App.Prestige.PendingPrestigeFrom)
    local pendingAt = tonumber(App.Prestige.PendingPrestigeAt) or 0

    if pendingFrom ~= nil and oldPrestige > pendingFrom then
        App.Prestige.PendingPrestigeFrom = nil
        App.Prestige.PendingPrestigeAt = 0
        pendingFrom = nil
        pendingAt = 0
    elseif pendingFrom == oldPrestige
        and pendingAt > 0
        and os.clock() - pendingAt < 45 then
        App.Prestige.LastAction =
            "Prestige request pending • waiting for profile sync"
        App.Prestige.CooldownUntil = pendingAt + 45
        App.Prestige.Busy = false
        return true, App.Prestige.LastAction
    end

    App.Prestige.LastAction =
        "Prestiging P" .. tostring(oldPrestige)
        .. " • " .. tostring(selection.Boosts)
        .. " • Memory " .. tostring(talent)

    App.Prestige.PendingPrestigeFrom = oldPrestige
    App.Prestige.PendingPrestigeAt = os.clock()

    local okPrestige, result = pcall(function()
        return remote:InvokeServer(
            "S_Equipment",
            "Prestige",
            selection
        )
    end)

    if not okPrestige then
        App.Prestige.LastAction =
            "Prestige request failed • safety cooldown"
        App.Prestige.CooldownUntil = os.clock() + 30
        App.Prestige.Busy = false
        return false, App.Prestige.LastAction
    end

    acceptedResult = result

    if type(acceptedResult) == "table" then
        App.Prestige.SyncAuthorityState(acceptedResult)
    end

    local confirmedPrestige =
        tonumber(App.Prestige.ReadLocalNumber("Prestige"))
        or tonumber(App.Prestige.LastPrestige)

    for verify = 1, 16 do
        if confirmedPrestige ~= nil
            and confirmedPrestige > oldPrestige then
            break
        end

        task.wait(0.25)

        local okData, liveData = pcall(function()
            return remote:InvokeServer("Functions", "Data")
        end)

        if okData and type(liveData) == "table" then
            App.Prestige.SyncAuthorityState(liveData)
        end

        confirmedPrestige =
            tonumber(App.Prestige.ReadLocalNumber("Prestige"))
            or tonumber(App.Prestige.LastPrestige)
    end

    App.Prestige.FetchAuthorityState(remote)

    confirmedPrestige =
        tonumber(App.Prestige.ReadLocalNumber("Prestige"))
        or tonumber(App.Prestige.LastPrestige)

    local confirmedGold = tonumber(App.Prestige.LastGold)

    if confirmedPrestige ~= nil
        and confirmedPrestige > oldPrestige then
        confirmedPrestige =
            math.floor(confirmedPrestige + 0.5)

        App.Prestige.LastPrestige = confirmedPrestige
        App.Prestige.PendingPrestigeFrom = nil
        App.Prestige.PendingPrestigeAt = 0
        App.Prestige.LastGold = confirmedGold
        App.Prestige.CooldownUntil = os.clock() + 2.0

        if App.AutoUpgrade then
            App.AutoUpgrade.LastPrestige = confirmedPrestige
            App.AutoUpgrade.LastGold = confirmedGold
        end

        App.Prestige.LastAction =
            "SUCCESS • P" .. tostring(oldPrestige)
            .. " → P" .. tostring(confirmedPrestige)

        if App.LobbyWebhook then
            local fields = {
                App.LobbyWebhook.Field("Prestige", "P"..tostring(oldPrestige).." → P"..tostring(confirmedPrestige), true),
                App.LobbyWebhook.Field("Buff", tostring(App.Values.PrestigeBuff or "Luck"), true),
                App.LobbyWebhook.Field("Memory", tostring(App.Prestige.LastTalent or talent or "Free offer"), true),
                App.LobbyWebhook.Field("Gold After", confirmedGold and App.Webhook.FormatNumber(confirmedGold) or nil, true),
            }
            task.spawn(function()
                App.LobbyWebhook.Send("Prestige", "Prestiged", fields)
            end)
        end

        App.Prestige.Busy = false
        return true, App.Prestige.LastAction
    end

    App.Prestige.LastAction =
        "Prestige submitted once • waiting for live sync"
    App.Prestige.CooldownUntil =
        math.max(
            os.clock() + 15,
            (tonumber(App.Prestige.PendingPrestigeAt) or os.clock()) + 45
        )
    App.Prestige.Busy = false
    return true, App.Prestige.LastAction
end


