}

App.LobbyAutomation.BoostPrices = {
    ["30m"] = 4499,
    ["1h"] = 7999,
    ["2h"] = 13999,
}

App.LobbyAutomation.BoostPurchaseIds = {
    XP = {["30m"] = 1, ["1h"] = 2, ["2h"] = 3},
    Luck = {["30m"] = 4, ["1h"] = 5, ["2h"] = 6},
    Gold = {["30m"] = 7, ["1h"] = 8, ["2h"] = 9},
