App.LobbyAutomation.ReadActive = function(kind)
    local boosts = player:FindFirstChild("Boosts")
    local object = boosts and boosts:FindFirstChild(tostring(kind or "XP"))
    if object
        and (object:IsA("IntValue") or object:IsA("NumberValue")) then
        return math.max(0, tonumber(object.Value) or 0)
    end
    return 0
end

App.LobbyAutomation.ActiveText = function()
    local kind = tostring(App.Values.BoostType or "XP")
    local seconds = App.LobbyAutomation.ReadActive(kind)

    if seconds <= 0 then
        return kind .. " • Inactive"
    end

    local minutes = math.floor(seconds / 60)
    local remain = math.floor(seconds % 60)
    return string.format("%s • %dm %02ds", kind, minutes, remain)
end

App.LobbyAutomation.ActiveAllText = function()
    local parts = {}
    for _, kind in ipairs({"XP", "Gold", "Luck"}) do
        local seconds = App.LobbyAutomation.ReadActive(kind)
        if seconds > 0 then
            local minutes = math.floor(seconds / 60)
            local remain = math.floor(seconds % 60)
            parts[#parts + 1] = string.format("%s %dm %02ds", kind == "XP" and "EXP" or kind, minutes, remain)
        else
            parts[#parts + 1] = (kind == "XP" and "EXP" or kind) .. " inactive"
        end
    end
    return table.concat(parts, " • ")
end

App.LobbyAutomation.PurchaseText = function()
    return tostring(App.LobbyAutomation.PurchasesDone or 0)
        .. " / "
        .. tostring(App.LobbyAutomation.PurchasesTarget or 0)
end

App.LobbyAutomation.Profile = function()
    local remote = lobbyGET()
    if not remote then return nil, nil end

    local okData, profile = pcall(function()
        return remote:InvokeServer("Functions", "Data")
    end)
    if not okData or type(profile) ~= "table" then
        local okSettings, settings = pcall(function()
            return remote:InvokeServer("Functions", "Settings", "Get")
        end)
        if not okSettings or type(settings) ~= "table" then return nil, nil end
        profile = settings
    end

    local _, slot = App.Prestige.ResolveSlot(profile)
    return profile, slot
end

App.LobbyAutomation.InventoryItems = function(slot)
    if type(slot) ~= "table" then return nil end
    local inventory = type(slot.Inventory) == "table" and slot.Inventory or nil
    if inventory and type(inventory.Items) == "table" then return inventory.Items end
    if inventory then
        local score = 0
        for key, value in pairs(inventory) do
            local lower = string.lower(tostring(key))
            if string.find(lower, "boost", 1, true) or string.find(lower, "crate", 1, true) then score += 1 end
            if tonumber(value) ~= nil then score += 0.1 end
            if score >= 1 then return inventory end
        end
    end
    if type(slot.Items) == "table" then return slot.Items end
    return nil
end

App.LobbyAutomation.ItemQuantity = function(items, name)
    if type(items) ~= "table" then return nil end
    local value = items[name]
    if tonumber(value) ~= nil then return tonumber(value) end
    if type(value) == "table" then
        for _, key in ipairs({"Quantity","Amount","Count","Owned","Value"}) do
            if tonumber(value[key]) ~= nil then return tonumber(value[key]) end
        end
    end
    return value ~= nil and 1 or 0
end

App.LobbyAutomation.BoostNames = function(kind, duration)
    kind = tostring(kind or "XP")
    duration = tostring(duration or "30m")
    local names = {"2x " .. kind .. " Boost [" .. duration .. "]"}
    if kind == "XP" then names[#names + 1] = "2x EXP Boost [" .. duration .. "]" end
    return names
end


App.LobbyAutomation.FindOwnedBoost = function(kind, slot)
    local items = App.LobbyAutomation.InventoryItems(slot)
    if type(items) ~= "table" then return nil end

    kind = tostring(kind or "XP")
    for _, duration in ipairs(App.LobbyAutomation.UseDurations) do
        for _, itemName in ipairs(App.LobbyAutomation.BoostNames(kind, duration.Tag)) do
            local quantity = App.LobbyAutomation.ItemQuantity(items, itemName)
            if tonumber(quantity) and quantity > 0 then
                return itemName, quantity, duration.Minutes
            end
        end
    end
    return nil
end


App.LobbyAutomation.RunAchievementSweep = function(force)
    if RuntimeKind ~= "Lobby"
        or App.Values.AutoClaimAchievements ~= true
        or App.LobbyAutomation.AchievementBusy then
        return false
    end

    local now = os.clock()
    if not force
        and now - (App.LobbyAutomation.LastAchievementSweepAt or 0)
            < App.LobbyAutomation.AchievementInterval then
        return false
    end

    local remote = lobbyGET()
    if not remote then
        App.LobbyAutomation.AchievementStatus = "GET remote unavailable"
        return false
    end

    App.LobbyAutomation.AchievementBusy = true
    App.LobbyAutomation.LastAchievementSweepAt = now
    App.LobbyAutomation.AchievementStatus = "Preparing achievement page"

    pcall(function()
        remote:InvokeServer("S_Achievements", "Category", 5)
    end)

    task.wait(0.12)

    local claimed = 0
    local checked = 0

    for id = 1, 71 do
        if App.Values.AutoClaimAchievements ~= true
            or RuntimeKind ~= "Lobby" then
            break
        end

        checked += 1
        App.LobbyAutomation.AchievementStatus =
            "Checking " .. tostring(id) .. " / 71"

        local ok, response = pcall(function()
            return remote:InvokeServer(
                "S_Achievements",
                "Claim",
                id
            )
        end)

        if ok
            and (response == true or type(response) == "table") then
            claimed += 1
        end

        task.wait(0.08)
    end

    App.LobbyAutomation.AchievementBusy = false
    App.LobbyAutomation.AchievementStatus =
        "Done • " .. tostring(checked)
        .. " checked • " .. tostring(claimed)
        .. " claimed"

    return true
end

App.LobbyAutomation.TestBuyOne = function()
    if RuntimeKind ~= "Lobby" then
        App.LobbyAutomation.BoostStatus = "Test purchase is Lobby-only"
        return false, App.LobbyAutomation.BoostStatus
    end
    if App.LobbyAutomation.BuyBusy or App.LobbyAutomation.MarketBusy then
        App.LobbyAutomation.BoostStatus = "Purchase already in progress"
        return false, App.LobbyAutomation.BoostStatus
    end

    local kind = tostring(App.Values.BoostType or "XP")
    local duration = tostring(App.Values.BoostDuration or "30m")
    local idTable = App.LobbyAutomation.BoostPurchaseIds[kind]
    local id = idTable and idTable[duration]
    local price = App.LobbyAutomation.BoostPrices[duration]
    if not id or not price then
        App.LobbyAutomation.BoostStatus = "Test failed • invalid boost selection"
        return false, App.LobbyAutomation.BoostStatus
    end

    local remote = lobbyGET()
    if not remote then
        App.LobbyAutomation.BoostStatus = "Test failed • purchase service unavailable"
        return false, App.LobbyAutomation.BoostStatus
    end

    local function snapshot(profileOverride)
        local profile, slot
        if type(profileOverride) == "table" then
            profile = profileOverride
            _, slot = App.Prestige.ResolveSlot(profile)
        end
        if type(slot) ~= "table" then profile, slot = App.LobbyAutomation.Profile() end
        local currency = type(slot) == "table" and slot.Currency or nil
        local gems = type(currency) == "table" and tonumber(currency.Gems) or nil
        local items = App.LobbyAutomation.InventoryItems(slot)
        local itemName, owned = nil, nil
        for _, candidate in ipairs(App.LobbyAutomation.BoostNames(kind, duration)) do
            local qty = App.LobbyAutomation.ItemQuantity(items, candidate)
            if qty ~= nil then itemName, owned = candidate, qty break end
        end
        itemName = itemName or App.LobbyAutomation.BoostNames(kind, duration)[1]
        return gems, owned, itemName
    end

    local function responseText(value)
        if value == true then return "true" end
        if value == false then return "false" end
        if value == nil then return "nil" end
        if type(value) == "table" then
            local ok, encoded = pcall(function() return game:GetService("HttpService"):JSONEncode(value) end)
            if ok and type(encoded) == "string" then return string.sub(encoded, 1, 120) end
            return "table"
        end
        return string.sub(tostring(value), 1, 120)
    end

    local gemsBefore, ownedBefore, itemName = snapshot()
    App.LobbyAutomation.BuyBusy = true
    App.LobbyAutomation.MarketBusy = true
    App.LobbyAutomation.PurchasesDone = 0
    App.LobbyAutomation.PurchasesTarget = 1
    App.LobbyAutomation.BoostStatus = "TEST • buying 1 × " .. kind .. " " .. duration

    local ok, response = pcall(function()
        return remote:InvokeServer("S_Market", "Buy", "1_Boosts", id, 1)
    end)

    task.wait(0.55)
    -- Many AOT:R mutation calls return the updated profile table. Use that
    -- response directly before asking a second profile contract for verification.
    local gemsAfter, ownedAfter = snapshot(ok and type(response) == "table" and response or nil)
    App.LobbyAutomation.BuyBusy = false
    App.LobbyAutomation.MarketBusy = false

    local gemSpent = gemsBefore ~= nil and gemsAfter ~= nil and gemsAfter < gemsBefore
    local itemGained = ownedBefore ~= nil and ownedAfter ~= nil and ownedAfter > ownedBefore
    local confirmed = gemSpent or itemGained
    if confirmed then App.LobbyAutomation.PurchasesDone = 1 end

    local gemText = (gemsBefore ~= nil and gemsAfter ~= nil) and (tostring(math.floor(gemsBefore)) .. "→" .. tostring(math.floor(gemsAfter))) or "unreadable"
    local itemText = (ownedBefore ~= nil and ownedAfter ~= nil) and (tostring(math.floor(ownedBefore)) .. "→" .. tostring(math.floor(ownedAfter))) or "unreadable"

    if confirmed then
        App.LobbyAutomation.BoostStatus = "TEST OK • Gems " .. gemText .. " • Owned " .. itemText
        return true, App.LobbyAutomation.BoostStatus
    end

    App.LobbyAutomation.BoostStatus = "TEST NO VERIFIED CHANGE • response=" .. (ok and responseText(response) or ("error:" .. responseText(response))) .. " • Gems " .. gemText .. " • " .. itemName .. " " .. itemText
    return false, App.LobbyAutomation.BoostStatus
end


App.LobbyAutomation.StartBuyBatch = function()
    local lobbyWebhookWalletBefore = App.Webhook and App.Webhook.ReadAccount and App.Webhook.ReadAccount() or {}
    if RuntimeKind ~= "Lobby"
        or App.Values.AutoBuyBoosts ~= true
        or App.LobbyAutomation.BuyBusy
        or App.LobbyAutomation.MarketBusy
        or os.clock() < (App.LobbyAutomation.NextBuyAttemptAt or 0) then
        return false
    end

    local kind = tostring(App.Values.BoostType or "XP")
    local duration = tostring(App.Values.BoostDuration or "30m")
    local amount = math.clamp(math.floor((tonumber(App.Values.BoostBuyAmount) or 20) + 0.5), 1, 100)
    local minimum = math.clamp(math.floor((tonumber(App.Values.BoostMinGems) or 0) + 0.5), 0, 1000000000)
    App.Values.BoostBuyAmount, App.Values.BoostMinGems = amount, minimum
    App.LobbyAutomation.NextBuyAttemptAt = os.clock() + 2.0

    local idTable = App.LobbyAutomation.BoostPurchaseIds[kind]
    local id = idTable and idTable[duration]
    local price = App.LobbyAutomation.BoostPrices[duration]
    if not id or not price then App.LobbyAutomation.BoostStatus = "Invalid boost selection" return false end

    local profile, slot = App.LobbyAutomation.Profile()
    local currency = type(slot) == "table" and slot.Currency or nil
    local gems = type(currency) == "table" and tonumber(currency.Gems) or nil
    local totalCost = price * amount
    if gems == nil then App.LobbyAutomation.BoostStatus = "Waiting for Gem balance" return false end

    local required = math.max(minimum, totalCost, tonumber(App.LobbyAutomation.NextBuyGemTarget) or 0)
    if gems < required then
        App.LobbyAutomation.BoostStatus = "Waiting for " .. tostring(math.floor(required)) .. " Gems • " .. tostring(math.floor(gems)) .. " available"
        return false
    end

    local remote = lobbyGET()
    if not remote then App.LobbyAutomation.BoostStatus = "Purchase service unavailable • waiting" return false end

    local function fromProfile(p)
        if type(p) ~= "table" then return nil, nil end
        local _, s = App.Prestige.ResolveSlot(p)
        if type(s) ~= "table" then return nil, nil end
        local c = type(s.Currency) == "table" and s.Currency or nil
        local g = type(c) == "table" and tonumber(c.Gems) or nil
        local items = App.LobbyAutomation.InventoryItems(s)
        local owned = nil
        for _, name in ipairs(App.LobbyAutomation.BoostNames(kind, duration)) do
            local qty = App.LobbyAutomation.ItemQuantity(items, name)
            if qty ~= nil then owned = qty break end
        end
        return g, owned
    end

    App.LobbyAutomation.BuyBusy = true
    App.LobbyAutomation.MarketBusy = true
    App.LobbyAutomation.BuyToken += 1
    local token = App.LobbyAutomation.BuyToken
    App.LobbyAutomation.PurchasesDone = 0
    App.LobbyAutomation.PurchasesTarget = amount
    App.LobbyAutomation.BoostStatus = "Buying " .. tostring(amount) .. " × " .. kind .. " " .. duration

    local gemsBefore, ownedBefore = fromProfile(profile)
    for index = 1, amount do
        if token ~= App.LobbyAutomation.BuyToken or App.Values.AutoBuyBoosts ~= true or RuntimeKind ~= "Lobby" then break end
        App.LobbyAutomation.BoostStatus = "Buying " .. tostring(index) .. " / " .. tostring(amount)

        local ok, response = pcall(function()
            return remote:InvokeServer("S_Market", "Buy", "1_Boosts", id, 1)
        end)
        if not ok then App.LobbyAutomation.BoostStatus = "Purchase call failed • stopped" break end

        task.wait(0.45)
        local gemsAfter, ownedAfter = fromProfile(type(response) == "table" and response or nil)
        if gemsAfter == nil and ownedAfter == nil then
            local fresh, _ = App.LobbyAutomation.Profile()
            gemsAfter, ownedAfter = fromProfile(fresh)
        end
        local confirmed = (gemsBefore ~= nil and gemsAfter ~= nil and gemsAfter < gemsBefore)
            or (ownedBefore ~= nil and ownedAfter ~= nil and ownedAfter > ownedBefore)
        if not confirmed then
            App.LobbyAutomation.BoostStatus = "Purchase not verified • stopped before repeat"
            App.LobbyAutomation.NextBuyAttemptAt = os.clock() + 30
            break
        end

        App.LobbyAutomation.PurchasesDone += 1
        gemsBefore, ownedBefore = gemsAfter, ownedAfter
        task.wait(0.35)
    end

    App.LobbyAutomation.BuyBusy = false
    App.LobbyAutomation.MarketBusy = false
    if App.LobbyAutomation.PurchasesDone >= App.LobbyAutomation.PurchasesTarget then
        App.LobbyAutomation.LastBuyGemSnapshot = gemsBefore and math.floor(gemsBefore) or nil
        App.LobbyAutomation.NextBuyAttemptAt = os.clock() + 3.0
        App.LobbyAutomation.BoostStatus = "Batch verified • waiting for next Gem target"
    elseif (App.LobbyAutomation.NextBuyAttemptAt or 0) < os.clock() + 5 then
        App.LobbyAutomation.NextBuyAttemptAt = os.clock() + 10
    end

    if (tonumber(App.LobbyAutomation.PurchasesDone) or 0) > 0 and App.LobbyWebhook then
        local lobbyWebhookWalletAfter = App.Webhook and App.Webhook.ReadAccount and App.Webhook.ReadAccount() or {}
        local fields = {
            App.LobbyWebhook.Field("Boost", tostring(kind).." "..tostring(duration), true),
            App.LobbyWebhook.Field("Purchased", tostring(App.LobbyAutomation.PurchasesDone), true),
            App.LobbyWebhook.Field("Gems", App.LobbyWebhook.WalletText(lobbyWebhookWalletBefore,lobbyWebhookWalletAfter,"Gems"), false),
        }
        task.spawn(function() App.LobbyWebhook.Send("Boosts","Boost Purchased",fields) end)
    end
    return App.LobbyAutomation.PurchasesDone >= App.LobbyAutomation.PurchasesTarget
end


App.LobbyAutomation.UseOne = function(kind)
    if App.LobbyAutomation.BoostBusy then return false end

    kind = tostring(kind or App.Values.BoostType or "XP")

    if App.LobbyAutomation.ReadActive(kind) > 0 then
        App.LobbyAutomation.BoostStatus =
            kind .. " boost already active"
        return false
    end

    App.LobbyAutomation.BoostBusy = true

    local _, slot = App.LobbyAutomation.Profile()
    local itemName =
        App.LobbyAutomation.FindOwnedBoost(kind, slot)

    if not itemName then
        App.LobbyAutomation.BoostStatus =
            "No owned " .. kind .. " boost"
        App.LobbyAutomation.BoostBusy = false
        App.LobbyAutomation.NextUseAttemptAt =
            os.clock() + 15
        return false
    end

    local remote = lobbyGET()
    if not remote then
        App.LobbyAutomation.BoostStatus =
            "GET remote unavailable"
        App.LobbyAutomation.BoostBusy = false
        return false
    end

    App.LobbyAutomation.BoostStatus =
        "Using " .. itemName

    local ok = pcall(function()
        remote:InvokeServer(
            "S_Inventory",
            "Item",
            itemName
        )
    end)

    if not ok then
        App.LobbyAutomation.BoostStatus =
            "Boost use remote failed"
        App.LobbyAutomation.BoostBusy = false
        App.LobbyAutomation.NextUseAttemptAt =
            os.clock() + 10
        return false
    end

    local deadline = os.clock() + 2.2
    repeat
        task.wait(0.08)
        if App.LobbyAutomation.ReadActive(kind) > 0 then
            App.LobbyAutomation.BoostStatus =
                kind .. " boost activated"
            if App.LobbyWebhook then
                local fields = {App.LobbyWebhook.Field("Boost", tostring(kind), true), App.LobbyWebhook.Field("Item", tostring(itemName), false)}
                task.spawn(function() App.LobbyWebhook.Send("Boosts","Boost Used",fields) end)
            end
            App.LobbyAutomation.BoostBusy = false
            return true
        end
    until os.clock() >= deadline

    App.LobbyAutomation.BoostStatus =
        "Boost use not confirmed"
    App.LobbyAutomation.BoostBusy = false
    App.LobbyAutomation.NextUseAttemptAt =
        os.clock() + 10

    return false
end

App.LobbyAutomation.UseState = {
    XP = {Handled=false, NextAttemptAt=0},
    Gold = {Handled=false, NextAttemptAt=0},
    Luck = {Handled=false, NextAttemptAt=0},
}

App.LobbyAutomation.ResetUseState = function(kind)
    local function resetOne(name)
        App.LobbyAutomation.UseState[name] = App.LobbyAutomation.UseState[name] or {}
        App.LobbyAutomation.UseState[name].Handled = false
        App.LobbyAutomation.UseState[name].NextAttemptAt = 0
    end
    if kind and App.LobbyAutomation.UseState[tostring(kind)] then
        resetOne(tostring(kind))
    else
        resetOne("XP")
        resetOne("Gold")
        resetOne("Luck")
    end
end

App.LobbyAutomation.StepUse = function()
    if RuntimeKind ~= "Lobby"
        or App.Values.AutoUseBoostWhenExpired ~= true
        or App.LobbyAutomation.BoostBusy
        or App.LobbyAutomation.CrateOpenBusy then
        return
    end

    local selected = {
        {Kind="XP", Enabled=App.Values.AutoUseXPBoost == true},
        {Kind="Gold", Enabled=App.Values.AutoUseGoldBoost == true},
        {Kind="Luck", Enabled=App.Values.AutoUseLuckBoost == true},
    }

    local any = false
    for _, entry in ipairs(selected) do
        if entry.Enabled then
            any = true
            local state = App.LobbyAutomation.UseState[entry.Kind]
            local active = App.LobbyAutomation.ReadActive(entry.Kind)
            if active > 0 then
                state.Handled = false
            elseif state.Handled ~= true and os.clock() >= (state.NextAttemptAt or 0) then
                local used = App.LobbyAutomation.UseOne(entry.Kind)
                state.Handled = used == true
                state.NextAttemptAt = os.clock() + (used and 0.75 or 12.0)
                if used then return end
            end
        end
    end

    if not any then
        App.LobbyAutomation.BoostStatus = "Select EXP, Gold, or Luck"
    end
end


