App.LobbyAutomation.ProfileNumbers = function(profile)
    if type(profile) ~= "table" then return nil, nil, nil end
    local _, slot = App.Prestige.ResolveSlot(profile)
    local currency = type(slot) == "table" and slot.Currency or nil
    local gems = type(currency) == "table" and tonumber(currency.Gems) or nil
    local spins = tonumber(profile.Spins)
        or (type(profile.Data) == "table" and tonumber(profile.Data.Spins))
        or (type(slot) == "table" and tonumber(slot.Spins))
    return spins, gems, slot
end

App.LobbyAutomation.RefreshProfile = function()
    local remote = lobbyGET()
    if not remote then return nil, nil, "GET RemoteFunction missing" end

    local function resolve(label, profile)
        if type(profile) ~= "table" then return nil, nil, nil end
        local _, slot = App.Prestige.ResolveSlot(profile)
        if type(slot) == "table" then return profile, slot, label end
        return nil, nil, nil
    end

    local okCopy, copy = pcall(function()
        return remote:InvokeServer("Data", "Copy")
    end)
    if okCopy then
        local profile, slot, label = resolve("Data/Copy", copy)
        if profile then return profile, slot, label end
    end

    local okData, data = pcall(function()
        return remote:InvokeServer("Functions", "Data")
    end)
    if okData then
        local profile, slot, label = resolve("Functions/Data", data)
        if profile then return profile, slot, label end
    end

    local okSettings, settings = pcall(function()
        return remote:InvokeServer("Functions", "Settings", "Get")
    end)
    if okSettings then
        local profile, slot, label = resolve("Functions/Settings/Get", settings)
        if profile then return profile, slot, label end
    end

    return nil, nil, tostring((not okCopy and copy) or (not okData and data) or (not okSettings and settings) or "profile not hydrated")
end


App.LobbyAutomation.Profile = function()
    local profile, slot = App.LobbyAutomation.RefreshProfile()
    return profile, slot
end


-- ==========================================================================
-- R7 GAMEPLAY SHIP • DIRECT TEKKIT LOBBY FLOW
-- Exact working state path from Standalone V4: Functions/Settings Music/Effects
-- -> data.Slots[data.Current_Slot]. No Talents call except actual Prestige.
-- ==========================================================================
App.TekkitLobby = App.TekkitLobby or {
    LastData = nil,
    LastDataAt = 0,
    LastDataSource = "Waiting",
    BusyBoost = false,
}

App.TekkitLobby.GetData = function(force)
    local now = os.clock()
    if force ~= true and type(App.TekkitLobby.LastData) == "table"
        and now - (tonumber(App.TekkitLobby.LastDataAt) or 0) < math.random(1, 3) then
        return App.TekkitLobby.LastData
    end

    local remote = lobbyGET()
    if not remote then
        App.TekkitLobby.LastDataSource = "GET missing"
        return App.TekkitLobby.LastData
    end

    local settingsKey = math.random(1, 2) == 1 and "Music" or "Effects"
    local settingsValue = math.random(0, 20)
    local ok, data = pcall(function()
        return remote:InvokeServer("Functions", "Settings", settingsKey, settingsValue)
    end)

    if ok and type(data) == "table" then
        App.TekkitLobby.LastData = data
        App.TekkitLobby.LastDataAt = now
        App.TekkitLobby.LastDataSource = "Functions/Settings/" .. settingsKey .. "=" .. tostring(settingsValue)
        return data
    end

    App.TekkitLobby.LastDataSource = "FAILED"
    return App.TekkitLobby.LastData
end

App.TekkitLobby.CurrentSlot = function(data)
    if type(data) ~= "table" then return nil, nil end
    local slots = type(data.Slots) == "table" and data.Slots or nil
    local key = data.Current_Slot
    if not slots or key == nil then return nil, nil end
    local slot = slots[key] or slots[tostring(key)] or slots[tonumber(key)]
    if type(slot) ~= "table" then return nil, nil end
    return key, slot
end

