App.LobbyAutomation.ReadActive = function(kind)
    local data = App.TekkitLobby.GetData(false)
    local boosts = type(data) == "table" and data.Boosts or nil
    return math.max(0, tonumber(type(boosts) == "table" and boosts[tostring(kind or "XP")] or nil) or 0)
end

App.LobbyAutomation.FindOwnedBoost = function(kind, slot)
    local items = App.LobbyAutomation.InventoryItems(slot)
    if type(items) ~= "table" then return nil end

    kind = tostring(kind or "XP")
    local preferred = tostring(App.Values.BoostDuration or "30m")
    local order = {preferred, "15m", "30m", "1h", "2h"}
    local seen = {}
    for _, duration in ipairs(order) do
        if not seen[duration] then
            seen[duration] = true
            for _, itemName in ipairs(App.LobbyAutomation.BoostNames(kind, duration)) do
                local quantity = tonumber(App.LobbyAutomation.ItemQuantity(items, itemName)) or 0
                if quantity > 0 then return itemName, quantity end
            end
        end
    end
    return nil
end

App.LobbyAutomation.TestBuyOne = function()
    if RuntimeKind ~= "Lobby" or App.TekkitLobby.BusyBoost then return false, "busy" end
    local kind = tostring(App.Values.BoostType or "XP")
    local duration = tostring(App.Values.BoostDuration or "30m")
    local ids = App.LobbyAutomation.BoostPurchaseIds[kind]
    local id = ids and ids[duration]
    if not id then App.LobbyAutomation.BoostStatus="Invalid boost selection" return false, App.LobbyAutomation.BoostStatus end

    local data, slot = App.LobbyAutomation.Profile()
    local currency = type(slot) == "table" and slot.Currency or nil
    local gems = type(currency) == "table" and tonumber(currency.Gems) or nil
    local itemName = App.LobbyAutomation.BoostNames(kind, duration)[1]
    local items = App.LobbyAutomation.InventoryItems(slot)
    local owned = tonumber(App.LobbyAutomation.ItemQuantity(items, itemName)) or 0
    local remote = lobbyGET()
    if not remote then return false, "GET missing" end

    App.TekkitLobby.BusyBoost = true
    local ok, response = pcall(function()
        return remote:InvokeServer("S_Market", "Buy", "1_Boosts", id, 1)
    end)
    App.TekkitLobby.LastDataAt = 0
    App.TekkitLobby.BusyBoost = false
    App.LobbyAutomation.BoostStatus = ok
        and ("Boost BUY sent • " .. itemName .. " • Gems before=" .. tostring(gems or "?") .. " • owned before=" .. tostring(owned))
        or ("Boost buy failed • " .. tostring(response))
    return ok, response
end

App.LobbyAutomation.StartBuyBatch = function()
    if RuntimeKind ~= "Lobby" or App.Values.AutoBuyBoosts ~= true
        or App.TekkitLobby.BusyBoost or App.LobbyAutomation.BuyBusy
        or os.clock() < (tonumber(App.LobbyAutomation.NextBuyAttemptAt) or 0) then
        return false
    end

    App.LobbyAutomation.NextBuyAttemptAt = os.clock() + 1.25
    local kind = tostring(App.Values.BoostType or "XP")
    local duration = tostring(App.Values.BoostDuration or "30m")
    local data = App.TekkitLobby.GetData(true)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    local boosts = type(data) == "table" and data.Boosts or nil
    local items = type(slot) == "table" and App.LobbyAutomation.InventoryItems(slot) or nil
    local timer = tonumber(type(boosts) == "table" and boosts[kind] or nil)
    if timer == nil or type(items) ~= "table" then
        App.LobbyAutomation.BoostStatus = "Lobby boost state missing"
        return false
    end
    if timer > 300 then
        App.LobbyAutomation.BoostStatus = kind .. " active • " .. tostring(math.floor(timer)) .. "s"
        return false
    end

    local itemName = App.LobbyAutomation.BoostNames(kind, duration)[1]
    local owned = tonumber(App.LobbyAutomation.ItemQuantity(items, itemName)) or 0
    if owned > 0 then
        App.LobbyAutomation.BoostStatus = "Owned • " .. itemName .. " x" .. tostring(owned)
        return true
    end

    local ids = App.LobbyAutomation.BoostPurchaseIds[kind]
    local id = ids and ids[duration]
    local remote = lobbyGET()
    if not id or not remote then
        App.LobbyAutomation.BoostStatus = "Boost purchase route unavailable"
        return false
    end

    App.TekkitLobby.BusyBoost = true
    App.LobbyAutomation.BuyBusy = true
    local ok, response = pcall(function()
        return remote:InvokeServer("S_Market", "Buy", "1_Boosts", id, 1)
    end)
    App.TekkitLobby.LastDataAt = 0
    App.TekkitLobby.BusyBoost = false
    App.LobbyAutomation.BuyBusy = false
    App.LobbyAutomation.PurchasesTarget = 1
    App.LobbyAutomation.PurchasesDone = ok and 1 or 0
    App.LobbyAutomation.BoostStatus = ok
        and ("Boost BUY sent • " .. itemName)
        or ("Boost buy failed • " .. tostring(response))
    return ok
end

App.LobbyAutomation.UseOne = function(kind)
    if RuntimeKind ~= "Lobby" or App.TekkitLobby.BusyBoost then return false end
    kind = tostring(kind or App.Values.BoostType or "XP")

    local data = App.TekkitLobby.GetData(true)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    local itemName, quantity = App.LobbyAutomation.FindOwnedBoost(kind, slot)
    if not itemName then
        App.LobbyAutomation.BoostStatus = "No owned " .. kind .. " boost"
        return false
    end

    local remote = lobbyGET()
    if not remote then return false end
    local boosts = type(data) == "table" and data.Boosts or nil
    local before = tonumber(type(boosts) == "table" and boosts[kind] or nil)

    App.TekkitLobby.BusyBoost = true
    App.LobbyAutomation.BoostBusy = true
    local ok, response = pcall(function()
        return remote:InvokeServer("S_Inventory", "Item", itemName)
    end)
    App.TekkitLobby.LastDataAt = 0
    App.TekkitLobby.BusyBoost = false
    App.LobbyAutomation.BoostBusy = false
    App.LobbyAutomation.BoostStatus = ok
        and ("Boost USE sent • " .. itemName .. " • timer before=" .. tostring(before or "?") .. " • owned=" .. tostring(quantity or "?"))
        or ("Boost use failed • " .. tostring(response))
    return ok
end

App.LobbyAutomation.StepUse = function()
    if RuntimeKind ~= "Lobby" or App.Values.AutoUseBoostWhenExpired ~= true
        or App.TekkitLobby.BusyBoost or App.LobbyAutomation.CrateOpenBusy then
        return false
    end

    for _, entry in ipairs({
        {Kind="XP", Enabled=App.Values.AutoUseXPBoost == true},
        {Kind="Gold", Enabled=App.Values.AutoUseGoldBoost == true},
        {Kind="Luck", Enabled=App.Values.AutoUseLuckBoost == true},
    }) do
        if entry.Enabled then
            local active = App.LobbyAutomation.ReadActive(entry.Kind)
            if active <= 300 then
                local _, slot = App.LobbyAutomation.Profile()
                local itemName = App.LobbyAutomation.FindOwnedBoost(entry.Kind, slot)
                if itemName then return App.LobbyAutomation.UseOne(entry.Kind) end
            end
        end
    end
    return false
end

-- Perks: exact direct Current_Slot storage/equipped path from working V4.
App.PerkManager.GetTalents = function()
    local data = App.TekkitLobby.GetData(true)
    if type(data) == "table" then return data end
    return nil, "Lobby data unavailable"
end

App.PerkManager.ResolvePerks = function(profile)
    local _, slot = App.TekkitLobby.CurrentSlot(profile)
    return type(slot) == "table" and type(slot.Perks) == "table" and slot.Perks or nil
end

App.PerkManager.AutoSellOnce = function(manual)
    if RuntimeKind ~= "Lobby" or App.PerkManager.SellBusy then return false, "busy" end
    if not manual and App.Values.AutoSellPerks ~= true then return false, "disabled" end

    App.PerkManager.SellBusy = true
    local data = App.TekkitLobby.GetData(true)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    local perks = type(slot) == "table" and slot.Perks or nil
    local storage = type(perks) == "table" and perks.Storage or nil
    local equipped = type(perks) == "table" and perks.Equipped or nil
    if type(storage) ~= "table" then
        App.PerkManager.SellBusy = false
        App.PerkManager.SellStatus = "No perk storage • lobby data unavailable"
        return false, App.PerkManager.SellStatus
    end

    local equippedIds = {}
    local function collect(value, depth)
        if depth > 5 then return end
        if type(value) == "string" and value ~= "" then
            equippedIds[value] = true
        elseif type(value) == "table" then
            for _, child in pairs(value) do collect(child, depth + 1) end
        end
    end
    collect(equipped, 0)

    local ids, counts = {}, {Common=0,Rare=0,Epic=0,Legendary=0}
    for id, info in pairs(storage) do
        if #ids >= 50 then break end
        local name = type(info) == "table" and tostring(info.Name or info.Tag or info.Perk or info.PerkName or "") or ""
        local rarity = App.PerkManager.RarityByName[name]
        -- V4/Tekkit test path deliberately leaves Mythics alone.
        if rarity and rarity ~= "Mythic"
            and App.Values["SellPerk" .. tostring(rarity)] == true
            and not equippedIds[tostring(id)] then
            ids[#ids + 1] = id
            counts[rarity] = (counts[rarity] or 0) + 1
        end
    end

    if #ids == 0 then
        App.PerkManager.SellBusy = false
        App.PerkManager.SellStatus = "No selected sellable perks"
        App.PerkManager.NextSellAt = os.clock() + 8
        return true, App.PerkManager.SellStatus
    end

    local remote = lobbyGET()
    local ok, response = pcall(function()
        return remote:InvokeServer("S_Equipment", "Delete", "Perk", ids)
    end)
    App.TekkitLobby.LastDataAt = 0
    App.PerkManager.SellBusy = false
    App.PerkManager.LastSellAt = os.clock()
    App.PerkManager.NextSellAt = os.clock() + 8
    App.PerkManager.Cache = nil
    App.PerkManager.CacheAt = 0
    App.PerkManager.SellStatus = ok
        and ("Delete sent • " .. tostring(#ids) .. " perks")
        or ("Perk delete failed • " .. tostring(response))
    return ok, App.PerkManager.SellStatus
end

-- Prestige: EXACT tested V4/Tekkit sequence. Talents is called exactly once per
-- actual prestige attempt; all three Prestige return values must be non-nil.
App.Prestige.TekkitLatched = false
App.Prestige.TekkitMemoryNames = App.TekkitLobby.MemoryNames

App.Prestige.ProfileStatusText = function()
    local data = App.TekkitLobby.GetData(false)
    local key, slot = App.TekkitLobby.CurrentSlot(data)
    if not slot then return "Lobby state missing" end
    return "Ready • Slot " .. tostring(key) .. " • " .. tostring(App.TekkitLobby.LastDataSource or "getdata")
end

App.Prestige.ProfileStatusKind = function()
    local data = App.TekkitLobby.GetData(false)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    return slot and "good" or "waiting"
end

App.Prestige.StateText = function()
    local p = tonumber(player:GetAttribute("Prestige"))
    local level = tonumber(player:GetAttribute("Level"))
    local data = App.TekkitLobby.GetData(false)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    local gold = type(slot) == "table" and type(slot.Currency) == "table" and tonumber(slot.Currency.Gold) or nil
    if p == nil or level == nil or gold == nil then return "Missing lobby state" end
    p = math.floor(p + 0.5)
    if p >= 5 then return "P5 • MAX" end
    local required = App.Prestige.RequiredLevel(p) or 100
    local threshold = App.Prestige.Threshold(p) or 0
    return "P" .. tostring(p) .. " • Lv " .. tostring(math.floor(level + 0.5)) .. "/" .. tostring(required)
        .. " • Gold " .. App.Prestige.FormatGold(gold) .. "/" .. App.Prestige.FormatGold(threshold)
end

App.Prestige.RunCheck = function(manual)
    if RuntimeKind ~= "Lobby" then return false, "Town Central required" end
    if App.Prestige.Busy or App.Prestige.TekkitLatched then return false, "busy/latched" end
    if not manual and App.Values.AutoPrestigeEnabled ~= true then return false, "disabled" end

    local prestige = tonumber(player:GetAttribute("Prestige"))
    local level = tonumber(player:GetAttribute("Level"))
    local data = App.TekkitLobby.GetData(true)
    local _, slot = App.TekkitLobby.CurrentSlot(data)
    local gold = type(slot) == "table" and type(slot.Currency) == "table" and tonumber(slot.Currency.Gold) or nil

    if prestige == nil then App.Prestige.LastAction="Prestige attribute missing" return false, App.Prestige.LastAction end
    if level == nil then App.Prestige.LastAction="Level attribute missing" return false, App.Prestige.LastAction end
    if gold == nil then App.Prestige.LastAction="Gold missing from lobby data" return false, App.Prestige.LastAction end

    prestige = math.floor(prestige + 0.5)
    level = math.floor(level + 0.5)
    App.Prestige.LastPrestige, App.Prestige.LastLevel, App.Prestige.LastGold = prestige, level, gold
    if prestige >= 5 then App.Prestige.LastAction="P5 • MAX" return false, App.Prestige.LastAction end

    local requiredLevel = App.Prestige.RequiredLevel(prestige) or 100
    if level < requiredLevel then
        App.Prestige.LastAction = "P" .. tostring(prestige) .. " requires Level " .. tostring(requiredLevel)
        return false, App.Prestige.LastAction
    end

    local threshold = App.Prestige.Threshold(prestige) or 0
    if gold < threshold then
        App.Prestige.LastAction = "P" .. tostring(prestige) .. " • " .. App.Prestige.FormatGold(gold)
            .. " / " .. App.Prestige.FormatGold(threshold)
        return false, App.Prestige.LastAction
    end

    local remote = lobbyGET()
    if not remote then return false, "GET missing" end
    App.Prestige.Busy = true
    App.Prestige.LastCheckAt = os.clock()

    local okTalents, profileOrA, offers = pcall(function()
        return remote:InvokeServer("S_Equipment", "Talents")
    end)
    if not okTalents or type(offers) ~= "table" then
        App.Prestige.Busy = false
        App.Prestige.LastAction = "Talents offers missing"
        return false, App.Prestige.LastAction
    end

    task.wait(0.5)
    local highest = 0
    for _, value in ipairs(offers) do
        local number = tonumber(value)
        if number and number >= highest then highest = number end
    end
    if highest == 0 then
        for _, value in pairs(offers) do
            local number = tonumber(value)
            if number and number >= highest then highest = number end
        end
    end

    local memory = App.TekkitLobby.MemoryNames[tostring(highest)]
    if not memory then
        App.Prestige.Busy = false
        App.Prestige.LastAction = "Memory ID unresolved • " .. tostring(highest)
        return false, App.Prestige.LastAction
    end

    local buff = App.Prestige.BuffTag()
    local selection = {Boosts=buff, Talents=memory}
    App.Prestige.LastTalent = memory
    App.Prestige.LastAction = "Prestige • P" .. tostring(prestige) .. " • " .. buff .. " • " .. memory

    local okPrestige, r1, r2, r3 = pcall(function()
        return remote:InvokeServer("S_Equipment", "Prestige", selection)
    end)
    App.TekkitLobby.LastDataAt = 0
    App.Prestige.Busy = false

    if not okPrestige then
        App.Prestige.LastAction = "Prestige call failed • " .. tostring(r1)
        return false, App.Prestige.LastAction
    end

    if r1 ~= nil and r2 ~= nil and r3 ~= nil then
        App.Prestige.TekkitLatched = true
        if type(r1) == "table" then
            App.TekkitLobby.LastData = r1
            App.TekkitLobby.LastDataAt = os.clock()
        end
        App.Prestige.LastAction = "PRESTIGE ACCEPTED • " .. memory .. " • returns="
            .. typeof(r1) .. "," .. typeof(r2) .. "," .. typeof(r3)
        return true, r1
    end

    App.Prestige.LastAction = "Prestige returned partial/nil • "
        .. tostring(r1) .. " / " .. tostring(r2) .. " / " .. tostring(r3)
    return false, App.Prestige.LastAction
end

App.LobbyAutomation.CurrentCrateAllowlist = {
    ["Scout Fashion [2]"] = true,
    ["Anime All-Stars [5]"] = true,
    ["Anime All-Stars [6]"] = true,
    ["Blade Burst [2]"] = true,
}
App.LobbyAutomation.CrateApproval = nil

App.LobbyAutomation.IsOwnedCrateName = function(name)
    local value = string.lower(tostring(name or ""))
    return string.find(value, "crate", 1, true) ~= nil
        or string.find(value, "scout fashion", 1, true) ~= nil
        or string.find(value, "anime all-stars", 1, true) ~= nil
        or string.find(value, "blade burst", 1, true) ~= nil
end

App.LobbyAutomation.OwnedCrates = function(profile)
    profile = type(profile) == "table" and profile or select(1, App.LobbyAutomation.RefreshProfile())
    if type(profile) ~= "table" then return {} end
    local _, slot = App.Prestige.ResolveSlot(profile)
    local items = App.LobbyAutomation.InventoryItems(slot)
    local rows = {}
    if type(items) ~= "table" then return rows end
    for name, quantity in pairs(items) do
        local count = tonumber(quantity) or 0
        if count > 0 and App.LobbyAutomation.IsOwnedCrateName(name) then
            rows[#rows + 1] = {Name=tostring(name), Quantity=math.floor(count + 0.5)}
        end
    end
    table.sort(rows, function(a,b) return a.Name < b.Name end)
    return rows
end

App.LobbyAutomation.OwnedCrateOptions = function()
    local rows = App.LobbyAutomation.OwnedCrates()
    local options = {}
    for _, row in ipairs(rows) do options[#options + 1] = row.Name end
    if #options == 0 then return {"No owned crates"} end
    return options
end

App.LobbyAutomation.IsCurrentMarketCrate = function(name)
    return App.LobbyAutomation.CurrentCrateAllowlist[tostring(name or "")] == true
end

App.LobbyAutomation.CrateAvailabilityText = function()
    local name = tostring(App.Values.CrateOpenTarget or "")
    if name == "" or name == "No owned crates" then return "No owned crate selected" end
    if App.LobbyAutomation.IsCurrentMarketCrate(name) then
        return "AVAILABLE IN SHOP • direct open allowed"
    end
    if App.LobbyAutomation.CrateApproval == name then
        return "NOT AVAILABLE IN SHOP • APPROVED FOR THIS SESSION"
    end
    return "NOT AVAILABLE IN SHOP • approval required before opening"
end

App.LobbyAutomation.ApproveDiscontinuedCrate = function()
    local name = tostring(App.Values.CrateOpenTarget or "")
    if name == "" or name == "No owned crates" then
        App.LobbyAutomation.CrateOpenStatus = "Select an owned crate first"
        return false
    end
    if App.LobbyAutomation.IsCurrentMarketCrate(name) then
        App.LobbyAutomation.CrateApproval = nil
        App.LobbyAutomation.CrateOpenStatus = "Current-shop crate • no approval required"
        return true
    end
    local profile = App.LobbyAutomation.RefreshProfile()
    local quantity = App.LobbyAutomation.InventoryQuantity(profile, name) or 0
    if quantity <= 0 then
        App.LobbyAutomation.CrateOpenStatus = "Selected crate is not owned"
        return false
    end
    App.LobbyAutomation.CrateApproval = name
    App.LobbyAutomation.CrateOpenStatus = "Approved discontinued crate • " .. name
    return true
end

App.LobbyAutomation.RefreshSnapshot = function(force)
    local now = os.clock()
    if force ~= true and now - (App.LobbyAutomation.LastSnapshotAt or 0) < 2.0 then return end
    App.LobbyAutomation.LastSnapshotAt = now
    local profile = App.LobbyAutomation.RefreshProfile()
    if type(profile) == "table" then
        local spins, gems = App.LobbyAutomation.ProfileNumbers(profile)
        if spins ~= nil then App.LobbyAutomation.LastSpins = math.floor(spins + 0.5) end
        if gems ~= nil then App.LobbyAutomation.LastGems = math.floor(gems + 0.5) end
    end
end

App.LobbyAutomation.SpinText = function()
    local spins = tonumber(App.LobbyAutomation.LastSpins)
    local target = math.max(0, math.floor((tonumber(App.Values.SpinTarget) or 0) + 0.5))
    if spins == nil then return "Scanning" end
    return target > 0 and (tostring(spins) .. " / " .. tostring(target)) or tostring(spins)
end

App.LobbyAutomation.SpinPacks = {
    {ID=5, Spins=500, Gems=45000},
    {ID=4, Spins=250, Gems=23000},
    {ID=3, Spins=100, Gems=10000},
    {ID=2, Spins=25, Gems=2500},
    {ID=1, Spins=5, Gems=500},
}

App.LobbyAutomation.ChooseSpinPack = function(needed, gems, reserve)
    needed = math.max(1, math.floor(tonumber(needed) or 1))
    gems = math.max(0, math.floor(tonumber(gems) or 0))
    reserve = math.max(0, math.floor(tonumber(reserve) or 0))
    local usable = math.max(0, gems - reserve)
    for _, pack in ipairs(App.LobbyAutomation.SpinPacks) do
        if pack.Spins <= needed and pack.Gems <= usable then return pack end
    end
    local smallest = App.LobbyAutomation.SpinPacks[#App.LobbyAutomation.SpinPacks]
    if smallest and smallest.Gems <= usable then return smallest end
    return nil
end

App.LobbyAutomation.StepBuySpins = function()
    if RuntimeKind ~= "Lobby" or App.Values.AutoBuySpins ~= true then return false end
    if App.LobbyAutomation.SpinBusy or App.LobbyAutomation.MarketBusy
        or os.clock() < (App.LobbyAutomation.NextSpinAttemptAt or 0) then return false end

    local target = math.clamp(math.floor((tonumber(App.Values.SpinTarget) or 0) + 0.5), 0, 1000000)
    local reserve = math.clamp(math.floor((tonumber(App.Values.SpinMinGems) or 0) + 0.5), 0, 1000000000)
    local limit = math.clamp(math.floor((tonumber(App.Values.SpinPurchaseLimit) or 10) + 0.5), 1, 100)
    App.Values.SpinTarget, App.Values.SpinMinGems, App.Values.SpinPurchaseLimit = target, reserve, limit

    if target <= 0 then
        App.LobbyAutomation.SpinStatus = "Set Target Spins above 0"
        return false
    end
    if App.FamilySpin and App.FamilySpin.Running == true then
        App.LobbyAutomation.SpinStatus = "Waiting for Family Spinner"
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 2.0
        return false
    end
    if (App.LobbyAutomation.SpinPurchases or 0) >= limit then
        App.LobbyAutomation.SpinStatus = "Session purchase limit reached"
        App.Values.AutoBuySpins = false
        return false
    end

    local profile = App.LobbyAutomation.RefreshProfile()
    local spins, gems = App.LobbyAutomation.ProfileNumbers(profile)
    if spins == nil or gems == nil then
        App.LobbyAutomation.SpinStatus = "Waiting for verified Spins / Gems"
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 2.5
        return false
    end
    spins, gems = math.floor(spins + 0.5), math.floor(gems + 0.5)
    App.LobbyAutomation.LastSpins, App.LobbyAutomation.LastGems = spins, gems

    if spins >= target then
        App.LobbyAutomation.SpinStatus = "Target reached • " .. tostring(spins) .. " Spins"
        App.Values.AutoBuySpins = false
        return true
    end

    local pack = App.LobbyAutomation.ChooseSpinPack(target - spins, gems, reserve)
    if not pack then
        App.LobbyAutomation.SpinStatus = "Waiting for Gems above reserve"
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 3.0
        return false
    end

    local get = lobbyGET()
    if not get then
        App.LobbyAutomation.SpinStatus = "Purchase service unavailable"
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 3.0
        return false
    end

    App.LobbyAutomation.SpinBusy = true
    App.LobbyAutomation.MarketBusy = true
    App.LobbyAutomation.SpinStatus = "Buying " .. tostring(pack.Spins) .. " Spins"
    local ok, response = pcall(function()
        return get:InvokeServer("S_Market", "Buy", "Spins", pack.ID, 1)
    end)
    task.wait(0.45)

    local afterProfile = type(response) == "table" and response or nil
    local afterSpins, afterGems = App.LobbyAutomation.ProfileNumbers(afterProfile)
    if afterSpins == nil or afterGems == nil then
        afterProfile = App.LobbyAutomation.RefreshProfile()
        afterSpins, afterGems = App.LobbyAutomation.ProfileNumbers(afterProfile)
    end

    local confirmed = ok and afterSpins ~= nil and afterSpins > spins
    if confirmed then
        App.LobbyAutomation.SpinPurchases += 1
        App.LobbyAutomation.LastSpins = math.floor(afterSpins + 0.5)
        if afterGems ~= nil then App.LobbyAutomation.LastGems = math.floor(afterGems + 0.5) end
        App.LobbyAutomation.SpinStatus = "Verified • " .. tostring(App.LobbyAutomation.LastSpins) .. " Spins"
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 0.75
    else
        App.LobbyAutomation.SpinStatus = "Purchase not verified • stopped"
        App.Values.AutoBuySpins = false
        App.LobbyAutomation.NextSpinAttemptAt = os.clock() + 5.0
    end
    App.LobbyAutomation.MarketBusy = false
    App.LobbyAutomation.SpinBusy = false
    return confirmed
end

App.LobbyAutomation.InventoryQuantity = function(profile, itemName)
    if type(profile) ~= "table" then return nil end
    local _, slot = App.Prestige.ResolveSlot(profile)
    local items = App.LobbyAutomation.InventoryItems(slot)
    return type(items) == "table" and tonumber(items[tostring(itemName)]) or nil
end

App.LobbyAutomation.RefreshSkipRoll = function(force)
    local now = os.clock()
    if force == true or now - (App.LobbyAutomation.CrateSkipCheckedAt or 0) >= 30 then
        App.LobbyAutomation.CrateSkipCheckedAt = now
        if App.FamilySpin and type(App.FamilySpin.DetectSkipRoll) == "function" then
            pcall(App.FamilySpin.DetectSkipRoll)
        end
    end
    return App.FamilySpin and App.FamilySpin.SkipRollOwned == true
end

App.LobbyAutomation.EffectiveCrateOpenDelay = function()
    local configured = math.clamp(tonumber(App.Values.CrateOpenDelay) or 0.20, 0.05, 10.00)
    App.Values.CrateOpenDelay = math.floor(configured * 100 + 0.5) / 100
    local skip = App.LobbyAutomation.RefreshSkipRoll(false)
    return skip and configured or math.max(5.0, configured), skip
end

App.LobbyAutomation.CrateSkipText = function()
    local configured = math.clamp(tonumber(App.Values.CrateOpenDelay) or 0.20, 0.05, 10.00)
    local owned = App.FamilySpin and App.FamilySpin.SkipRollOwned == true
    local effective = owned and configured or math.max(5.0, configured)
    return (owned and "Detected" or "Not detected") .. " • effective " .. string.format("%.2fs", effective)
end

App.LobbyAutomation.StepOpenCrate = function()
    if RuntimeKind ~= "Lobby" or App.Values.AutoOpenCrates ~= true then return false end
    if App.LobbyAutomation.CrateOpenBusy or App.LobbyAutomation.BoostBusy
        or App.LobbyAutomation.MarketBusy
        or os.clock() < (App.LobbyAutomation.NextCrateOpenAt or 0) then return false end

    local selected = tostring(App.Values.CrateOpenTarget or "")
    if selected == "" or selected == "No owned crates" then
        App.LobbyAutomation.CrateOpenStatus = "Select an owned crate"
        App.LobbyAutomation.NextCrateOpenAt = os.clock() + 2.0
        return false
    end

    local profile = App.LobbyAutomation.RefreshProfile()
    if type(profile) ~= "table" then
        App.LobbyAutomation.CrateOpenStatus = "Waiting for inventory profile"
        App.LobbyAutomation.NextCrateOpenAt = os.clock() + 2.5
        return false
    end

    local beforeQty = App.LobbyAutomation.InventoryQuantity(profile, selected) or 0
    if beforeQty <= 0 then
        App.LobbyAutomation.CrateOpenStatus = "Selected crate is no longer owned"
        App.Values.AutoOpenCrates = false
        return false
    end

    local current = App.LobbyAutomation.IsCurrentMarketCrate(selected)
    if not current and App.LobbyAutomation.CrateApproval ~= selected then
        App.LobbyAutomation.CrateOpenStatus = "WARNING • NOT AVAILABLE IN SHOP • approve before opening " .. selected
        App.LobbyAutomation.NextCrateOpenAt = os.clock() + 1.0
        return false
    end

    local get = lobbyGET()
    if not get then
        App.LobbyAutomation.CrateOpenStatus = "GET remote unavailable"
        return false
    end

    local delay, skip = App.LobbyAutomation.EffectiveCrateOpenDelay()
    App.LobbyAutomation.CrateOpenBusy = true
    App.LobbyAutomation.CrateOpenStatus = "Opening " .. selected

    local ok, response = pcall(function()
        return get:InvokeServer("S_Inventory", "Crate", selected)
    end)

    local afterQty = type(response) == "table"
        and App.LobbyAutomation.InventoryQuantity(response, selected)
        or nil
    if afterQty == nil then
        task.wait(0.35)
        local afterProfile = App.LobbyAutomation.RefreshProfile()
        afterQty = App.LobbyAutomation.InventoryQuantity(afterProfile, selected)
    end

    local confirmed = ok and afterQty ~= nil and afterQty < beforeQty
    if confirmed then
        App.LobbyAutomation.CrateOpenStatus = "Verified • " .. selected .. " • " .. (skip and "Skip Roll" or "standard roll")
        App.LobbyAutomation.NextCrateOpenAt = os.clock() + delay
        App.LobbyAutomation.LastSnapshotAt = 0
    else
        App.LobbyAutomation.CrateOpenStatus = "Open not verified • stopped"
        App.Values.AutoOpenCrates = false
        App.LobbyAutomation.NextCrateOpenAt = os.clock() + 5.0
    end
    App.LobbyAutomation.CrateOpenBusy = false
    return confirmed
end

local MissionReturn = {Busy=false, TeleportSeen=false}

player.OnTeleport:Connect(function()
    MissionReturn.TeleportSeen = true
end)

returnToLobbyFromMission = function(reason, source)
    if RuntimeKind ~= "Gameplay" or MissionReturn.Busy then return false end

    MissionReturn.Busy = true
    MissionReturn.TeleportSeen = false

    -- Final bounded flush for mission-limit/AFK/safety returns. No pending
    -- webhook means this returns immediately.
    if App.Webhook and type(App.Webhook.WaitForResultDispatch) == "function" then
        pcall(App.Webhook.WaitForResultDispatch, 4.0)
    end

    if App.Values.AutoExecuteOnTeleport == true then
        pcall(queueV12AutoExecute, true)
    end

    App.Values.AutoFarmBlades = false
    App.Values.AutoFarmSpears = false
    stopBladeRuntime()
    stopSpearRuntime()
    clearCombatSafety()

    local returnReason = tostring(reason or "")
    App.TeleportTrace.Record(source or "MISSION_RETURN", returnReason ~= "" and returnReason or "Returning to Town Central")
    App.Values.MissionLoopStatus = returnReason ~= ""
        and returnReason
        or "Returning to Town Central"
    setStatus(returnReason ~= ""
        and returnReason
        or "Mission limit reached • returning to Town Central")

    local remote = lobbyGET()
    if remote then
        pcall(function()
            remote:InvokeServer("Functions", "Teleport", "Lobby")
        end)
    end

    local started = os.clock()
    while os.clock() - started < 4.0 do
        if MissionReturn.TeleportSeen or not player.Parent then
            return true
        end
        task.wait(0.08)
    end


    MissionReturn.Busy = false
    App.Values.MissionLoopStatus = returnReason ~= ""
        and (returnReason .. " • return not accepted")
        or "Lobby return remote was not accepted"
    setStatus(App.Values.MissionLoopStatus)
    return false
end

App.Safety.RequestSoloLeave = function(name)
    if RuntimeKind ~= "Gameplay" or App.Values.LeaveIfAnotherPlayer ~= true then
        return false
    end

    local detected = tostring(name or App.Safety.LastDetectedPlayer or "another player")
    App.Safety.PlayerSafetyStatus = "Leaving • " .. detected
    return returnToLobbyFromMission(
        "Safety • " .. detected .. " detected • returning to Town Central",
        "PARTY_SAFETY"
    )
end

if App.AFKManager then
    App.AFKManager.ReturnToLobby = function()
        App.AFKManager.StopAutomation()
        if App.RunState then App.RunState.MarkResetAfterLobby() end
        if type(returnToLobbyFromMission) ~= "function" then return false end
        local ok, result = pcall(returnToLobbyFromMission, "AFK Manager • returning to Lobby", "AFK_MANAGER")
        return ok == true and result == true
    end
end

App.Cutscene = {
    State = "IDLE",
    Active = false,
    EvidenceSince = nil,
    InactiveSince = nil,
    Attempts = 0,
    LastAttemptAt = 0,
    LastTarget = nil,
    LastSentAt = 0,
    WavesReadySince = nil,
    Quarantined = false,
    HoverY = nil,
    ReleaseStableSeconds = 0.25,
    Status = "Waiting",
}

-- PC-safe transition quarantine. Every gameplay controller already observes
-- App.Cutscene.Active through TransitionGuard; the only movement retained here
-- is a live hover which follows the server's newest X/Z spawn instead of an old
-- pre-cutscene hold CFrame.
App.Cutscene.EnterQuarantine = function()
    if App.Cutscene.Quarantined then return end
    App.Cutscene.Quarantined = true
    App.Cutscene.HoverY = nil

    cancelSpearMovement()
    CombatSafety.Moving = false
    CombatSafety.BaseHoldCFrame = nil
    SpearRuntime.HoldCFrame = nil
    SpearRuntime.Busy = false
    if App.Waves then App.Waves.HoldCFrame = nil end
    if App.Colossal then
        App.Colossal.P2HoldCFrame = nil
        App.Colossal.SpearP2HoldCFrame = nil
    end

    local root = spearRoot()
    if root then
        App.Cutscene.HoverY = root.Position.Y + 220
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

App.Cutscene.MaintainSafeHover = function()
    if not App.Cutscene.Quarantined then return end
    local root = spearRoot()
    if not root then return end

    local targetY = tonumber(App.Cutscene.HoverY) or (root.Position.Y + 220)
    -- Never reuse the old mission-start X/Z. Follow any server-side Breach
    -- spawn relocation and only preserve a safe vertical hold.
    local safe = CFrame.new(root.Position.X, math.max(root.Position.Y, targetY), root.Position.Z)
    App.Cutscene.HoverY = safe.Position.Y
    pcall(function()
        root.CFrame = safe
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    setCombatHoldCFrame(safe)
    SpearRuntime.HoldCFrame = safe
end

App.Cutscene.ReleaseQuarantine = function()
    local root = spearRoot()
    if root then
        local safe = CombatSafety.ProbeUprightCFrame(root.CFrame)
        setCombatHoldCFrame(safe)
        SpearRuntime.HoldCFrame = safe
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    App.Cutscene.Quarantined = false
    App.Cutscene.HoverY = nil
end

App.Cutscene.IsOwnGuiObject = function(object)
    local node = object
    for _ = 1, 8 do
        if not node then break end
        if string.find(tostring(node.Name), "SliceHubV1NewGen", 1, true) then
            return true
        end
        node = node.Parent
    end
    return false
end

App.Cutscene.GuiVisible = function(object)
    if not object or not object:IsA("GuiObject") then return false end
    local node = object
    while node and node ~= playerGui do
        if node:IsA("GuiObject") and node.Visible == false then return false end
        if node:IsA("ScreenGui") and node.Enabled == false then return false end
        node = node.Parent
    end
    return object.AbsoluteSize.X > 0 and object.AbsoluteSize.Y > 0
end

App.Cutscene.HasNamedAncestor = function(object)
    local node = object
    for _ = 1, 7 do
        if not node or node == playerGui then break end
        local name = string.lower(tostring(node.Name or ""))
        if string.find(name, "cutscene", 1, true)
            or string.find(name, "cinematic", 1, true) then
            return true
        end
        node = node.Parent
    end
    return false
end

App.Cutscene.Detect = function()
    local camera = workspace.CurrentCamera
    local unclimbable = workspace:FindFirstChild("Unclimbable")
    local cutscene = unclimbable and unclimbable:FindFirstChild("Cutscene")
    local exactTarget = cutscene and (cutscene:FindFirstChild("Start") or cutscene:FindFirstChild("Middle"))

    if exactTarget and camera and camera.CameraType == Enum.CameraType.Scriptable then
        return true
    end

    local score = camera and camera.CameraType == Enum.CameraType.Scriptable and 2 or 0

    for _, object in ipairs(playerGui:GetDescendants()) do
        if App.Cutscene.IsOwnGuiObject(object) then
            continue
        end

        if object:IsA("GuiObject") and App.Cutscene.GuiVisible(object) then
            local text = nil
            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then
                text = string.lower(tostring(object.Text or ""))
                text = string.gsub(text, "<[^>]->", "")
                text = string.gsub(text, "%s+", " ")
            end

            local name = string.lower(tostring(object.Name or ""))
            local named = App.Cutscene.HasNamedAncestor(object)

            if (string.find(name, "skip", 1, true)
                or name == "e"
                or name == "ekey")
                and ((camera and camera.CameraType == Enum.CameraType.Scriptable) or named) then
                return true
            end

            if text then
                if string.find(text, "press e", 1, true)
                    or string.find(text, "hold e", 1, true)
                    or (string.find(text, "skip", 1, true)
                        and string.find(text, "e", 1, true)) then
                    return true
                end

                if named then
                    score += 1
                    if string.find(text, "skip", 1, true) then score += 2 end
                end
            elseif named then
                score += 1
            end

            if score >= 3 then return true end
        end
    end

    return score >= 3
end

App.Cutscene.WavesState = function()
    local waves = workspace:FindFirstChild("Waves")
    if not waves then
        App.Cutscene.WavesReadySince = nil
        return false, true
    end

    local unclimbable = workspace:FindFirstChild("Unclimbable")
    local objective = unclimbable and unclimbable:FindFirstChild("Objective")
    local waveObjective = objective and objective:FindFirstChild("Waves")
    if not waveObjective then
        App.Cutscene.WavesReadySince = nil
        return true, false
    end

    local crates = waves:FindFirstChild("Crates")
    if not crates or not crates:IsA("Folder") then
        App.Cutscene.WavesReadySince = nil
        return true, false
    end

    App.Cutscene.WavesReadySince = App.Cutscene.WavesReadySince or os.clock()
    return true, os.clock() - App.Cutscene.WavesReadySince >= 0.75
end

App.Cutscene.KeyPress = function()
    if App.RaidChestAuto
        and App.Values.RaidAutoOpenChests == true
        and (App.RaidChestAuto.Busy
            or App.RaidChestAuto.ScreenActive
            or (type(App.RaidChestAuto.ScreenVisible) == "function"
                and App.RaidChestAuto.ScreenVisible())) then
        App.Cutscene.Status = "Raid chests • skip suspended"
        return false
    end

    local ok = pcall(function()
        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.E, false, game)
        task.wait(0.055)
        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.E, false, game)
    end)
    return ok
end

App.Cutscene.RemoteSkip = function()
    local unclimbable = workspace:FindFirstChild("Unclimbable")
    local cutscene = unclimbable and unclimbable:FindFirstChild("Cutscene")
    local target = cutscene
        and (cutscene:FindFirstChild("Start") or cutscene:FindFirstChild("Middle"))

    if not target then return false end

    local now = os.clock()
    if target == App.Cutscene.LastTarget
        and now - (App.Cutscene.LastSentAt or 0) < 0.35 then
        return false
    end

    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local post = remotes and remotes:FindFirstChild("POST")
    if not post or not post:IsA("RemoteEvent") then return false end

    App.Cutscene.LastTarget = target
    App.Cutscene.LastSentAt = now

    return pcall(function()
        post:FireServer("Functions", "Finished", target)
    end)
end

App.Cutscene.Reset = function()
    App.Cutscene.State = "IDLE"
    App.Cutscene.Active = false
    App.Cutscene.EvidenceSince = nil
    App.Cutscene.InactiveSince = nil
    App.Cutscene.Attempts = 0
    App.Cutscene.LastAttemptAt = 0
    if App.Cutscene.Quarantined then
        App.Cutscene.ReleaseQuarantine()
    end
    App.Cutscene.Status = App.Values.AutoSkipCutscene and "Armed" or "Guard armed"
end

App.Cutscene.Step = function()
    if RuntimeKind ~= "Gameplay" then
        App.Cutscene.Reset()
        return
    end

    local active = false
    pcall(function() active = App.Cutscene.Detect() == true end)
    local now = os.clock()

    if App.Cutscene.State == "IDLE" then
        if active then
            App.Cutscene.Active = true
            App.Cutscene.EnterQuarantine()
            App.Cutscene.EvidenceSince = now
            App.Cutscene.Status = "Verifying cutscene • farm suspended"
            App.Cutscene.State = "DETECTING"
        else
            App.Cutscene.Status = App.Values.AutoSkipCutscene and "Armed" or "Guard armed"
        end
        return
    end

    if App.Cutscene.State == "DETECTING" then
        if not active then
            App.Cutscene.Reset()
        elseif now - (App.Cutscene.EvidenceSince or now) >= 0.30 then
            App.Cutscene.Active = true
            App.Cutscene.Attempts = 0
            App.Cutscene.LastAttemptAt = 0
            App.Cutscene.Status = "Cutscene confirmed • farm suspended"
            App.Cutscene.State = "ACTIVE"
        end
        return
    end

    if App.Cutscene.State == "ACTIVE" then
        App.Cutscene.Active = true
        App.Cutscene.MaintainSafeHover()
        if not active then
            App.Cutscene.InactiveSince = now
            App.Cutscene.Status = "Cutscene released • stabilizing"
            App.Cutscene.State = "VERIFY_RELEASE"
            return
        end

        local canSkip = App.Values.AutoSkipCutscene == true
            and (not App.FamilySpin
                or not App.FamilySpin.IsPremium
                or App.FamilySpin.IsPremium() == true)

        if not canSkip then
            App.Cutscene.Status = "Cutscene confirmed • farm suspended • auto skip OFF"
            return
        end

        local inWaves, wavesReady = App.Cutscene.WavesState()
        local maxAttempts = inWaves and 2 or 4
        local retryGap = inWaves and 0.90 or 0.60

        if inWaves and not wavesReady then
            App.Cutscene.Status = "Waiting for Waves setup • farm suspended"
            return
        end

        if App.Cutscene.Attempts < maxAttempts
            and now - (App.Cutscene.LastAttemptAt or 0) >= retryGap then
            App.Cutscene.Attempts += 1
            App.Cutscene.LastAttemptAt = now
            if not inWaves then App.Cutscene.RemoteSkip() end
            App.Cutscene.KeyPress()
            App.Cutscene.Status = "Skip " .. tostring(App.Cutscene.Attempts)
                .. "/" .. tostring(maxAttempts) .. " • farm suspended"
        end
        return
    end

    if App.Cutscene.State == "VERIFY_RELEASE" then
        App.Cutscene.Active = true
        App.Cutscene.MaintainSafeHover()
        if active then
            App.Cutscene.State = "ACTIVE"
            App.Cutscene.InactiveSince = nil
        elseif now - (App.Cutscene.InactiveSince or now) >= App.Cutscene.ReleaseStableSeconds then
            App.Cutscene.Reset()
        end
    end
end


