local STATE_PATH = "SH/config/auto_ts_quest_" .. tostring(Player.UserId) .. ".json"

local function executorFunction(name)
    local value = Environment[name]
    if type(value) == "function" then
        return value
    end
    local globalValue = _G and _G[name]
    if type(globalValue) == "function" then
        return globalValue
    end
    return nil
end

local ReadFile = executorFunction("readfile")
local WriteFile = executorFunction("writefile")
local IsFile = executorFunction("isfile")
local MakeFolder = executorFunction("makefolder")
local IsFolder = executorFunction("isfolder")

local function ensureStateFolder()
    if type(MakeFolder) ~= "function" then return end
    for _, folder in ipairs({"SH", "SH/config"}) do
        local exists = false
        if type(IsFolder) == "function" then
            local ok, result = pcall(IsFolder, folder)
            exists = ok and result == true
        end
        if not exists then pcall(MakeFolder, folder) end
    end
end

local function readSavedEnabled()
    if type(ReadFile) ~= "function" then
        return Environment.__SliceHubAutoTSEnabled == true
    end
    if type(IsFile) == "function" then
        local ok, exists = pcall(IsFile, STATE_PATH)
        if not ok or exists ~= true then
            return Environment.__SliceHubAutoTSEnabled == true
        end
    end
    local okRead, content = pcall(ReadFile, STATE_PATH)
    if not okRead or type(content) ~= "string" or content == "" then
        return Environment.__SliceHubAutoTSEnabled == true
    end
    local okDecode, decoded = pcall(HttpService.JSONDecode, HttpService, content)
    if okDecode and type(decoded) == "table" then
        return decoded.Enabled == true
    end
    return Environment.__SliceHubAutoTSEnabled == true
end

local function readSavedUtgardRuns()
    if type(ReadFile) ~= "function" then
        return 0
    end
    if type(IsFile) == "function" then
        local ok, exists = pcall(IsFile, STATE_PATH)
        if not ok or exists ~= true then
            return 0
        end
    end
    local okRead, content = pcall(ReadFile, STATE_PATH)
    if not okRead or type(content) ~= "string" or content == "" then
        return 0
    end
    local okDecode, decoded = pcall(HttpService.JSONDecode, HttpService, content)
    if okDecode and type(decoded) == "table"
        and tonumber(decoded.UserId) == tonumber(Player.UserId)
        and ({["10.10"]=true,["10.21"]=true,["11"]=true,["11.1"]=true,["11.2"]=true,["11.3"]=true})[tostring(decoded.Version or "")] then
        return math.clamp(math.floor(tonumber(decoded.UtgardRuns) or 0), 0, 99)
    end
    return 0
end

local function readSavedUtgardVariantKills()
    if type(ReadFile) ~= "function" then
        return math.clamp(math.floor(tonumber(Environment.__SliceHubAutoTSVariantKills) or 0), 0, 3)
    end
    if type(IsFile) == "function" then
        local ok, exists = pcall(IsFile, STATE_PATH)
        if not ok or exists ~= true then
            return 0
        end
    end
    local okRead, content = pcall(ReadFile, STATE_PATH)
    if not okRead or type(content) ~= "string" or content == "" then
        return 0
    end
    local okDecode, decoded = pcall(HttpService.JSONDecode, HttpService, content)
    if okDecode and type(decoded) == "table"
        and tonumber(decoded.UserId) == tonumber(Player.UserId)
        and ({["10.10"]=true,["10.21"]=true,["11"]=true,["11.1"]=true,["11.2"]=true,["11.3"]=true})[tostring(decoded.Version or "")] then
        return math.clamp(math.floor(tonumber(decoded.UtgardVariantKills) or 0), 0, 3)
    end
    return 0
end

local function saveEnabled(value)
    value = value == true
    Environment.__SliceHubAutoTSEnabled = value
    Environment.__SliceHubAutoTSUtgardRuns = math.clamp(
        math.floor(tonumber(Runtime.UtgardRuns) or 0),
        0,
        99
    )
    Environment.__SliceHubAutoTSVariantKills = math.clamp(
        math.floor(tonumber(Runtime.UtgardVariantKills) or 0),
        0,
        3
    )
    if type(WriteFile) ~= "function" then
        return
    end
    ensureStateFolder()
    local okEncode, encoded = pcall(HttpService.JSONEncode, HttpService, {
        Enabled = value,
        UserId = tonumber(Player.UserId),
        UtgardRuns = Environment.__SliceHubAutoTSUtgardRuns,
        UtgardVariantKills = Environment.__SliceHubAutoTSVariantKills,
        SavedAt = os.time(),
        Version = "11.3",
    })
    if okEncode then
        pcall(WriteFile, STATE_PATH, encoded)
    end
end

Runtime.AutoLaunch = readSavedEnabled()
