local DISPLAY_ORDER = {1, 3, 4, 2, 5}
local ROUTE_ORDER = {4, 5, 1, 2, 3}

local function trim(value)
    return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function lower(value)
    return string.lower(trim(value))
end

local function remote()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local getRemote = remotes and remotes:FindFirstChild("GET")

    if getRemote and getRemote:IsA("RemoteFunction") then
        return getRemote
    end

    return nil
end

local function resolveSlot(profile)
    if type(profile) ~= "table" then
        return nil, nil
    end

    local slots = rawget(profile, "Slots")
    if type(slots) ~= "table" then
        return nil, nil
    end

    local slotKey = Player:GetAttribute("Slot")
    if slotKey == nil then
        slotKey = rawget(profile, "Current_Slot")
    end

    if slotKey ~= nil then
        local candidates = {slotKey, tostring(slotKey), tonumber(slotKey)}
        for _, key in ipairs(candidates) do
            if key ~= nil and type(slots[key]) == "table" then
                return key, slots[key]
            end
        end
    end

    local onlyKey = nil
    local onlySlot = nil
    local count = 0

    for key, value in pairs(slots) do
        if type(value) == "table" then
            count = count + 1
            onlyKey = key
            onlySlot = value
            if count > 1 then
                break
            end
        end
    end

    if count == 1 then
        return onlyKey, onlySlot
    end

    return nil, nil
end

local function profileScore(profile)
    local _, slot = resolveSlot(profile)
    if type(slot) ~= "table" then
        return -math.huge, nil
    end

    local score = 10
    local quests = rawget(slot, "Quests")
    local spears = type(quests) == "table" and rawget(quests, "Spears") or nil

    if type(spears) == "table" then
        score = score + 5000
        for index = 1, 5 do
            if type(spears[index]) == "table"
                or type(spears[tostring(index)]) == "table" then
                score = score + 50
            end
        end
    end

    if type(rawget(slot, "Progression")) == "table" then
        score = score + 100
    end

    if type(rawget(slot, "Inventory")) == "table" then
        score = score + 50
    end

    if type(rawget(slot, "Skills")) == "table" then
        score = score + 25
    end

    return score, slot
end

local function getFunctionUpvalues(fn)
    if debug and type(debug.getupvalues) == "function" then
        local ok, values = pcall(debug.getupvalues, fn)
        if ok and type(values) == "table" then
            return values
        end
    end

    if type(getupvalues) == "function" then
        local ok, values = pcall(getupvalues, fn)
        if ok and type(values) == "table" then
            return values
        end
    end

    return nil
end

local function profileFromController(candidate)
    if type(candidate) ~= "table" then
        return nil
    end

    local cache = rawget(candidate, "Cache")
    local modules = rawget(candidate, "Modules")
    if type(cache) ~= "table" or type(modules) ~= "table" then
        return nil
    end

    local cachedPlayer = rawget(cache, "Player")
    if cachedPlayer ~= nil and cachedPlayer ~= Player then
        return nil
    end

    local data = rawget(cache, "Data")
    if profileScore(data) > 0 then
        Runtime.Controller = candidate
        return data
    end

    return nil
end

local function currentControllerProfile()
    local controller = Runtime.Controller
    if type(controller) ~= "table" then
        return nil
    end

    local profile = profileFromController(controller)
    if profile then
        return profile
    end

    Runtime.Controller = nil
    return nil
end

local function scanGetGC()
    if type(getgc) ~= "function" then
        return nil, nil
    end

    local ok, objects = pcall(getgc, true)
    if not ok or type(objects) ~= "table" then
        return nil, nil
    end

    local bestProfile = nil
    local bestScore = -math.huge


    for _, object in ipairs(objects) do
        if type(object) == "table" then
            if type(rawget(object, "Slowed")) == "boolean"
                and rawget(object, "Default") ~= nil
                and rawget(object, "Gear_Shift") ~= nil then
                Runtime.CoreRuntime = object
            end

            local controllerProfile = profileFromController(object)
            if controllerProfile then
                local score = profileScore(controllerProfile)
                if score > bestScore then
                    bestScore = score
                    bestProfile = controllerProfile
                end
            end

            local score = profileScore(object)
            if score > bestScore then
                bestScore = score
                bestProfile = object
            end
        end
    end

    if bestProfile then
        return bestProfile, Runtime.Controller and "Cache.Data" or "raw profile cache"
    end


    for _, object in ipairs(objects) do
        if type(object) == "function" then
            local upvalues = getFunctionUpvalues(object)
            if type(upvalues) == "table" then
                for _, value in pairs(upvalues) do
                    if type(value) == "table"
                        and type(rawget(value, "Slowed")) == "boolean"
                        and rawget(value, "Default") ~= nil
                        and rawget(value, "Gear_Shift") ~= nil then
                        Runtime.CoreRuntime = value
                    end

                    local controllerProfile = profileFromController(value)
                    if controllerProfile then
                        return controllerProfile, "Cache.Data via upvalue"
                    end

                    local score = profileScore(value)
                    if score > bestScore then
                        bestScore = score
                        bestProfile = value
                    end
                end
            end
        end
    end

    if bestProfile then
        return bestProfile, "profile upvalue"
    end

    return nil, nil
end

local function probeProfileRemote()
    local getRemote = remote()
    if not getRemote then
        return nil, "GET RemoteFunction missing"
    end

    local attempts = {
        {"Functions/Data", function() return getRemote:InvokeServer("Functions", "Data") end},
        {"Functions/Settings/Get", function() return getRemote:InvokeServer("Functions", "Settings", "Get") end},
    }

    local lastError = "profile response did not contain the active slot"
    for _, attempt in ipairs(attempts) do
        local ok, result = pcall(attempt[2])
        if ok and profileScore(result) > 0 then
            return result, attempt[1] .. " response"
        end
        if not ok then lastError = tostring(result) end
    end
    return nil, lastError
end

local function findProfile()
    local controllerProfile = currentControllerProfile()
    if controllerProfile then
        return controllerProfile, "Cache.Data"
    end

    if Runtime.Profile and os.clock() - Runtime.LastProfileAt < 2.5 then
        if profileScore(Runtime.Profile) > 0 then
            return Runtime.Profile, Runtime.ProfileSource
        end
    end

    local now = os.clock()
    local remoteInterval = IS_LOBBY and 1.25 or 4.0
    if now - Runtime.LastRemoteProbeAt >= remoteInterval then
        Runtime.LastRemoteProbeAt = now
        local profile, sourceOrError = probeProfileRemote()
        if profile then
            return profile, sourceOrError
        end
        Runtime.LastError = sourceOrError
    end

    local gcInterval = IS_LOBBY and 8.0 or 3.0
    if now - Runtime.LastGetGCScanAt >= gcInterval then
        Runtime.LastGetGCScanAt = now
        local profile, source = scanGetGC()
        if profile then
            return profile, source
        end
    end

    return nil, nil
end

local function recursiveFindStrings(root, wanted)
    local found = {}
    local visited = {}

    local function walk(value, depth)
        if depth > 8 then
            return
        end

        local valueType = type(value)
        if valueType == "string" then
            local text = lower(value)
            if wanted[text] then
                found[text] = true
            end
            return
        end

        if valueType ~= "table" or visited[value] then
            return
        end

        visited[value] = true

        for key, child in pairs(value) do
            if type(key) == "string" then
                local keyText = lower(key)
                if wanted[keyText] then
                    found[keyText] = true
                end
            end
            walk(child, depth + 1)
        end
    end

    walk(root, 0)
    return found
end

local function ownsAllThunderSpearParts(slot)
    if type(slot) ~= "table" then
        return false
    end

    local wanted = {
        ["thunder spear - handle"] = true,
        ["thunder spear - thruster"] = true,
        ["thunder spear - base"] = true,
    }

    local found = recursiveFindStrings(slot, wanted)
    return found["thunder spear - handle"] == true
        and found["thunder spear - thruster"] == true
        and found["thunder spear - base"] == true
end

local function getPrestige(slot)
    if type(slot) ~= "table" then
        return nil
    end

    local progression = rawget(slot, "Progression")
    local value = type(progression) == "table" and rawget(progression, "Prestige") or nil
    value = tonumber(value or rawget(slot, "Prestige"))
    return value
end

local function questEntry(spears, index)
    if type(spears) ~= "table" then
        return nil
    end
    return spears[index] or spears[tostring(index)]
end

local function readQuestState(spears, definition, completedByParts)
    local entry = questEntry(spears, definition.Index)
    local prerequisiteComplete = true

    if definition.Prerequisite then
        local prerequisiteEntry = questEntry(spears, definition.Prerequisite)
        prerequisiteComplete = type(prerequisiteEntry) == "table"
            and (prerequisiteEntry.Rewarded == true
                or prerequisiteEntry.Claimed == true
                or prerequisiteEntry.Completed == true)
    end

    local current = 0
    local rewarded = false

    if type(entry) == "table" then
        current = tonumber(entry.Current or entry.Progress or entry.Amount_Current or 0) or 0
        rewarded = entry.Rewarded == true
            or entry.Claimed == true
            or entry.Completed == true
    end

    if completedByParts then
        rewarded = true
        current = definition.Amount
    end

    local status
    if rewarded then
        status = "complete"
        current = math.max(current, definition.Amount)
    elseif not prerequisiteComplete then
        status = "locked"
    elseif type(entry) ~= "table" then
        status = "missing"
    elseif current >= definition.Amount then
        status = "reward_pending"
    else
        status = "active"
    end

    return {
        Definition = definition,
        Entry = entry,
        Current = math.max(0, math.floor(current + 0.0001)),
        Amount = definition.Amount,
        Rewarded = rewarded,
        PrerequisiteComplete = prerequisiteComplete,
        Status = status,
    }
end

local function scanQuestProfile(profile, source)
    local slotKey, slot = resolveSlot(profile)
    if type(slot) ~= "table" then
        return {
            Ready = false,
            Error = "Active slot was not found in the player profile.",
            Source = source or "unknown",
        }
    end

    local progression = rawget(slot, "Progression")
    local prestige = getPrestige(slot)
    local quests = rawget(slot, "Quests")
    local spears = type(quests) == "table" and rawget(quests, "Spears") or nil
    local completedByParts = ownsAllThunderSpearParts(slot)

    local states = {}
    for index = 1, 5 do
        states[index] = readQuestState(spears, QUESTS[index], completedByParts)
    end

    local allRewarded = true
    for index = 1, 5 do
        if states[index].Status ~= "complete" then
            allRewarded = false
            break
        end
    end

    local completed = completedByParts or allRewarded
    local route = nil
    local pendingReward = nil

    if not completed and prestige and prestige > 0 and type(spears) == "table" then
        for _, index in ipairs(ROUTE_ORDER) do
            local state = states[index]
            if state.Status == "reward_pending" then
                pendingReward = state
                break
            end
            if state.Status == "active" then
                route = state
                break
            end
        end
    end

    return {
        Ready = true,
        Profile = profile,
        Slot = slot,
        SlotKey = slotKey,
        Source = source or "unknown",
        Prestige = prestige,
        Progression = progression,
        Spears = spears,
        States = states,
        CompletedByParts = completedByParts,
        Completed = completed,
        Route = route,
        PendingReward = pendingReward,
    }
end

Runtime.VisibleIceBurstQuestFallback = function()
    local nameObject = nil
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if object:IsA("TextLabel") or object:IsA("TextButton") then
            local textValue = lower(object.Text):gsub("%s+", " ")
            if string.find(textValue, "ice burst stones", 1, true) then
                nameObject = object
                break
            end
        end
    end
    if not nameObject then
        return nil
    end

    local current = nil
    local node = nameObject
    for _ = 1, 6 do
        if not node then break end
        local chunks = {}
        if node:IsA("TextLabel") or node:IsA("TextButton") then
            chunks[#chunks + 1] = tostring(node.Text or "")
        end
        for _, descendant in ipairs(node:GetDescendants()) do
            if descendant:IsA("TextLabel") or descendant:IsA("TextButton") then
                chunks[#chunks + 1] = tostring(descendant.Text or "")
            end
        end
        local combined = table.concat(chunks, " ")
        current = tonumber(string.match(combined, "%[(%d+)%s*/%s*3%]"))
            or tonumber(string.match(combined, "(%d+)%s*/%s*3"))
        if current ~= nil then break end
        node = node.Parent
    end

    current = math.clamp(math.floor(tonumber(current) or 0), 0, 3)
    local states = {}
    for index = 1, 5 do
        local definition = QUESTS[index]
        states[index] = {
            Definition = definition,
            Entry = nil,
            Current = index == 3 and current or 0,
            Amount = definition.Amount,
            Rewarded = false,
            PrerequisiteComplete = true,
            Status = index == 3
                and (current >= 3 and "reward_pending" or "active")
                or "missing",
        }
    end

    return {
        Ready = true,
        Profile = nil,
        Slot = nil,
        SlotKey = nil,
        Source = "visible Thunder Spears quest panel fallback",
        Prestige = nil,
        Progression = nil,
        Spears = {},
        States = states,
        CompletedByParts = false,
        Completed = false,
        Route = current < 3 and states[3] or nil,
        PendingReward = current >= 3 and states[3] or nil,
        VisibleFallback = true,
    }
end


local function guiNodeVisibleForPrime(object)
    if not object then return false end
    local node = object
    while node and node ~= PlayerGui do
        if node:IsA("ScreenGui") and node.Enabled ~= true then return false end
        if node:IsA("GuiObject") and node.Visible ~= true then return false end
        node = node.Parent
    end
    return true
end

local function clickableAncestor(object)
    local node = object
    for _ = 1, 7 do
        if not node then break end
        if node:IsA("TextButton") or node:IsA("ImageButton") then
            return node
        end
        node = node.Parent
    end
    return nil
end

local function findClickableText(exactText)
    exactText = lower(exactText):gsub("%s+", " ")
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if object:IsA("TextLabel") or object:IsA("TextButton") then
            local value = lower(object.Text):gsub("%s+", " ")
            if value == exactText and guiNodeVisibleForPrime(object) then
                return clickableAncestor(object) or (object:IsA("TextButton") and object or nil)
            end
        end
    end
    return nil
end

local function activateNativeGuiButton(button)
    if not button or not button.Parent then return false end
    local accepted = false
    pcall(function()
        button:Activate()
        accepted = true
    end)
    if accepted then return true end

    local fire = Environment.firesignal or firesignal
    if type(fire) == "function" then
        local ok = pcall(function() fire(button.Activated) end)
        if ok then return true end
    end

    if button:IsA("GuiObject") then
        local position = button.AbsolutePosition + button.AbsoluteSize / 2
        return pcall(function()
            VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
            task.wait(0.04)
            VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, false, game, 0)
        end)
    end
    return false
end

Runtime.ClaimVisibleThunderSpearRewards = function()
    local claimed = 0
    for _ = 1, 4 do
        local claim = findClickableText("claim")
        if not claim then break end
        if activateNativeGuiButton(claim) then
            claimed += 1
            task.wait(0.12)
        else
            break
        end
    end
    return claimed
end

Runtime.forceNativePrimeButton = function(button)
    if not button or not button.Parent then return false end
    local attempted = false

    pcall(function()
        button:Activate()
        attempted = true
    end)

    local fire = Environment.firesignal or firesignal
    if type(fire) == "function" then
        pcall(function()
            fire(button.Activated)
            attempted = true
        end)
        pcall(function()
            if button:IsA("TextButton") or button:IsA("ImageButton") then
                fire(button.MouseButton1Click)
                attempted = true
            end
        end)
    end

    if button:IsA("GuiObject")
        and button.AbsoluteSize.X > 0
        and button.AbsoluteSize.Y > 0 then
        local position = button.AbsolutePosition + button.AbsoluteSize / 2
        pcall(function()
            VirtualInputManager:SendMouseButtonEvent(
                position.X, position.Y, 0, true, game, 0
            )
            task.wait(0.04)
            VirtualInputManager:SendMouseButtonEvent(
                position.X, position.Y, 0, false, game, 0
            )
            attempted = true
        end)
    end

    return attempted
end

Runtime.PrimeThunderSpearQuestPanel = function(force)
    if Environment.__SliceHubNewGenTSClaim ~= true then return false end
    if not IS_LOBBY or Runtime.QuestPrimeBusy then return false end

    local now = os.clock()
    if force ~= true and now - (Runtime.LastQuestPrimeAt or 0) < 1.8 then
        return Runtime.VisibleIceBurstQuestFallback() ~= nil
    end

    Runtime.QuestPrimeBusy = true
    Runtime.LastQuestPrimeAt = now
    local opened = false
    local scan = Runtime.VisibleIceBurstQuestFallback()


    for _ = 1, 4 do
        if scan then break end

        local questsButton = findClickableText("quests")
        if questsButton then
            opened = Runtime.forceNativePrimeButton(questsButton) or opened
            task.wait(0.12)
        end

        local thunderButton = findClickableText("thunder spears")
        if thunderButton then
            opened = Runtime.forceNativePrimeButton(thunderButton) or opened
            task.wait(0.18)
        end

        scan = Runtime.VisibleIceBurstQuestFallback()
        if not scan then task.wait(0.12) end
    end

    local deadline = os.clock() + 2.8
    while Runtime.Alive and not scan and os.clock() < deadline do
        task.wait(0.10)
        scan = Runtime.VisibleIceBurstQuestFallback()
    end

    if scan then
        Runtime.ClaimVisibleThunderSpearRewards()
        task.wait(0.18)
        scan = Runtime.VisibleIceBurstQuestFallback() or scan
    end

    Runtime.QuestPrimeBusy = false
    return scan ~= nil or opened
end


local ExactEngine = {
    Busy = false,
    LastStage = "Idle",
    LastError = nil,
}

Player.OnTeleport:Connect(function()
    Runtime.TeleportSeen = true
end)

function ExactEngine.Invoke(action, ...)
    local getRemote = remote()
    if not getRemote then
        return false, nil, "GET RemoteFunction missing"
    end

    local args = table.pack(...)
    local ok, result = pcall(function()
        return getRemote:InvokeServer(
            "S_Missions",
            action,
            table.unpack(args, 1, args.n)
        )
    end)

    if not ok then
        return false, nil, tostring(result)
    end

    return true, result, nil
end

function ExactEngine.FindOwnedMission()
    local missions = ReplicatedStorage:FindFirstChild("Missions")
    if not missions then
        return nil
    end

    for _, mission in ipairs(missions:GetChildren()) do
        local leader = mission:FindFirstChild("Leader")
        if leader and tostring(leader.Value) == tostring(Player.Name) then
            return mission
        end
    end

    return nil
end

function ExactEngine.WaitForOwnedMission(timeout)
    local startedAt = os.clock()
    local duration = math.max(0, tonumber(timeout) or 0)

    repeat
        local mission = ExactEngine.FindOwnedMission()
        if mission then
            return mission
        end
        task.wait(0.05)
    until os.clock() - startedAt >= duration

    return ExactEngine.FindOwnedMission()
end

function ExactEngine.WaitForNoOwnedMission(timeout)
    local startedAt = os.clock()
    local duration = math.max(0, tonumber(timeout) or 0)

    repeat
        if not ExactEngine.FindOwnedMission() then
            return true
        end
        task.wait(0.05)
    until os.clock() - startedAt >= duration

    return ExactEngine.FindOwnedMission() == nil
end

function ExactEngine.TeleportStarted()
    if Runtime.TeleportSeen then
        return true
    end

    local value = Player:GetAttribute("Teleporting")
    return value ~= nil and value ~= false
end

function ExactEngine.Cleanup()
    local invoke = ExactEngine and ExactEngine.Invoke
    if type(invoke) ~= "function" then
        return false
    end
    local ok = pcall(invoke, "Leave")
    return ok == true
end

function ExactEngine.TryLaunch(routeState)
    if ExactEngine.Busy then
        return false, "Exact launcher is busy."
    end

    if type(routeState) ~= "table" or type(routeState.Definition) ~= "table" then
        return false, "No valid Thunder Spear route is selected."
    end

    if LOBBY_PLACE_IDS[tonumber(game.PlaceId) or 0] ~= true then
        return false, "This integrated runtime launches only from the AOT:R lobby."
    end

    ExactEngine.Busy = true
    Runtime.TeleportSeen = false
    ExactEngine.LastStage = "PreLaunchCleanup"
    ExactEngine.LastError = nil

    local function fail(reason, created)
        ExactEngine.LastError = tostring(reason)
        ExactEngine.LastStage = "Failed"
        if created then
            ExactEngine.Cleanup()
        end
        ExactEngine.Busy = false
        return false, tostring(reason)
    end

    ExactEngine.Cleanup()
    if not ExactEngine.WaitForNoOwnedMission(0.70) then
        return fail("Could not clear the existing owned mission before launch.", false)
    end

    local definition = routeState.Definition
    local payload = {
        Name = tostring(definition.InternalMap),
        Difficulty = "Aberrant",
        Type = "Missions",
        Objective = tostring(definition.Objective or "Skirmish"),
    }

    ExactEngine.LastStage = "Create"
    local invoke = ExactEngine and ExactEngine.Invoke
    if type(invoke) ~= "function" then
        return fail("Exact mission invoke route is unavailable.", false)
    end
    local createOk, createResponse, createError = invoke("Create", payload)
    if not createOk then
        return fail("Create failed: " .. tostring(createError), false)
    end

    if type(createResponse) == "string" then
        return fail("Create rejected: " .. tostring(createResponse), false)
    end


    local ownedMission = ExactEngine.WaitForOwnedMission(1.00)
    if not ownedMission and createResponse == nil then
        return fail("Create returned no mission and no owned mission appeared.", false)
    end

    task.wait(0.05)

    ExactEngine.LastStage = "Start"
    local startOk, _, startError = invoke("Start")
    if not startOk then
        return fail("Start failed: " .. tostring(startError), true)
    end

    local startedAt = os.clock()
    while os.clock() - startedAt < 3.0 do
        if ExactEngine.TeleportStarted() then
            ExactEngine.LastStage = "Teleporting"
            ExactEngine.Busy = false
            return true, "Launching " .. definition.Map .. " on Aberrant"
        end
        task.wait(0.04)
    end

    return fail("Start was sent, but teleport was not detected.", true)
end


local function safeParent(gui)
    local parent = nil
    if type(gethui) == "function" then
        pcall(function() parent = gethui() end)
    end
    if not parent then
        parent = CoreGui
    end

    local ok = pcall(function() gui.Parent = parent end)
    if not ok or not gui.Parent then
        gui.Parent = PlayerGui
    end
end

