local function forgetPlatform(platform)
    if not platform then
        return
    end
    for index = #Runtime.SafePlatforms, 1, -1 do
        if Runtime.SafePlatforms[index] == platform then
            table.remove(Runtime.SafePlatforms, index)
        end
    end
end

local function destroyPlatform(platform)
    if not platform then
        return
    end
    forgetPlatform(platform)
    if platform.Parent then
        pcall(function()
            platform:Destroy()
        end)
    end
end

local function destroySafePlatform()
    local seen = {}
    for _, platform in ipairs(Runtime.SafePlatforms) do
        if platform and not seen[platform] then
            seen[platform] = true
            if platform.Parent then
                pcall(function()
                    platform:Destroy()
                end)
            end
        end
    end
    local platform = Runtime.SafePlatform
    if platform and not seen[platform] and platform.Parent then
        pcall(function()
            platform:Destroy()
        end)
    end
    Runtime.SafePlatforms = {}
    Runtime.SafePlatform = nil
    Runtime.SafeCFrame = nil
    Runtime.SafeTarget = nil
    Runtime.Transitioning = false
    Runtime.Touching = false
end

local function characterParts(timeout)
    local deadline = os.clock() + math.max(0, tonumber(timeout) or 0)
    repeat
        local character = Player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
        if character and humanoid and root and humanoid.Health > 0 then
            return character, humanoid, root
        end
        task.wait(0.12)
    until os.clock() >= deadline
    return nil, nil, nil
end

local function supplyNumber(model)
    if not model then
        return nil
    end
    return tonumber(string.match(tostring(model.Name or ""), "^ThunderSpear_Supplies(%d+)$"))
end

local function objectWorldPosition(object)
    if not object then
        return nil
    end
    if object:IsA("BasePart") then
        return object.Position
    end
    if object:IsA("Model") then
        local ok, pivot = pcall(object.GetPivot, object)
        if ok and pivot then
            return pivot.Position
        end
    end
    local part = object:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function supplyVisualEnabled(object)
    if not object then
        return false
    end
    local display = object:FindFirstChild("Display", true)
    if display and (display:IsA("BillboardGui") or display:IsA("SurfaceGui")) and display.Enabled then
        return true
    end
    for _, descendant in ipairs(object:GetDescendants()) do
        if descendant:IsA("Beam") and descendant.Enabled then
            return true
        end
    end
    return false
end

local function objectNearCharacter(object, radius)
    local character = Player.Character
    local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
    if not root then
        return false
    end
    local position = objectWorldPosition(object)
    return position ~= nil and (position - root.Position).Magnitude <= (tonumber(radius) or 18)
end

local function objectLinkedToCharacter(object)
    local character = Player.Character
    if not character or not object then
        return false
    end
    if object:IsDescendantOf(character) then
        return true
    end
    for _, descendant in ipairs(object:GetDescendants()) do
        if descendant:IsA("Weld") or descendant:IsA("WeldConstraint") or descendant:IsA("Motor6D") then
            local part0 = descendant.Part0
            local part1 = descendant.Part1
            if (part0 and part0:IsDescendantOf(character))
                or (part1 and part1:IsDescendantOf(character)) then
                return true
            end
        end
    end
    return false
end

local function likelyCarriedSupplyObject(object)
    if not object or not object.Parent then
        return false
    end


    return objectLinkedToCharacter(object)
        or objectNearCharacter(object, 20)
end

local function listLooseSupplies()
    local crates = {}
    local seen = {}
    local character = Player.Character
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Model")
            and supplyNumber(object)
            and not seen[object]
            and (not character or not object:IsDescendantOf(character))
            and not likelyCarriedSupplyObject(object) then
            seen[object] = true
            crates[#crates + 1] = object
        end
    end
    table.sort(crates, function(a, b)
        return (supplyNumber(a) or 99) < (supplyNumber(b) or 99)
    end)
    return crates
end

local function findDepositZone()
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Model") and object.Name == "Supplies_Circle" then
            return object
        end
    end
    return nil
end

local function hitboxFor(model)
    if not model then
        return nil
    end
    local directHitbox = model:FindFirstChild("Hitbox")
    if directHitbox and directHitbox:IsA("BasePart") then
        return directHitbox
    end
    local hitbox = model:FindFirstChild("Hitbox", true)
    if hitbox and hitbox:IsA("BasePart") then
        return hitbox
    end
    if model.PrimaryPart and model.PrimaryPart:IsA("BasePart") then
        return model.PrimaryPart
    end
    return nil
end

local function visibleDepositCount(zone)
    if not zone then
        return 0
    end
    local count = 0
    for index = 1, 3 do
        local slot = zone:FindFirstChild("CrateBox" .. tostring(index), true)
        if slot and slot:IsA("BasePart") and slot.Transparency < 0.92 then
            count = count + 1
        end
    end
    return count
end

local function discoverCoreRuntime()
    local current = Runtime.CoreRuntime
    if type(current) == "table" and type(rawget(current, "Slowed")) == "boolean" then
        return current
    end
    if type(getgc) ~= "function" or os.clock() - (Runtime.LastCoreRuntimeScanAt or 0) < 0.45 then
        return nil
    end
    Runtime.LastCoreRuntimeScanAt = os.clock()
    local ok, objects = pcall(getgc, true)
    if not ok or type(objects) ~= "table" then
        return nil
    end
    for _, object in ipairs(objects) do
        if type(object) == "table"
            and type(rawget(object, "Slowed")) == "boolean"
            and rawget(object, "Default") ~= nil
            and rawget(object, "Gear_Shift") ~= nil then
            Runtime.CoreRuntime = object
            return object
        end
    end
    return nil
end

local function controllerCarryState()
    local controller = Runtime.Controller
    if type(controller) == "table" then
        local modules = rawget(controller, "Modules")
        local runtimeModule = type(modules) == "table" and rawget(modules, "Runtime") or nil
        if type(runtimeModule) == "table" and type(rawget(runtimeModule, "Slowed")) == "boolean" then
            Runtime.CoreRuntime = runtimeModule
            return runtimeModule.Slowed == true
        end
    end

    local runtimeModule = discoverCoreRuntime()
    if type(runtimeModule) == "table" and type(rawget(runtimeModule, "Slowed")) == "boolean" then
        return runtimeModule.Slowed == true
    end
    return nil
end

local function taggedCarryEvidence()
    local character = Player.Character
    if not character then
        return false
    end


    for _, object in ipairs(CollectionService:GetTagged("Supply")) do
        if object and object.Parent
            and (supplyVisualEnabled(object) or likelyCarriedSupplyObject(object)) then
            return true
        end
    end

    for _, object in ipairs(character:GetDescendants()) do
        local name = lower(object.Name)
        if string.find(name, "supply", 1, true)
            or string.find(name, "crate", 1, true) then
            return true
        end
    end


    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Model") and supplyNumber(object) and likelyCarriedSupplyObject(object) then
            return true
        end
    end
    return false
end

local function carryingEvidence()
    local controllerState = controllerCarryState()
    if controllerState == true then
        return true
    end
    if taggedCarryEvidence() then
        return true
    end
    if controllerState == false then
        return false
    end
    return false
end

local function readLiveSupplyProgress()
    local profile, source = findProfile()
    if profile then
        Runtime.Profile = profile
        Runtime.ProfileSource = source or Runtime.ProfileSource
        Runtime.LastProfileAt = os.clock()
        local scan = scanQuestProfile(profile, Runtime.ProfileSource)
        if scan and scan.Ready and scan.States and scan.States[4] then
            Runtime.CurrentScan = scan
            return tonumber(scan.States[4].Current), scan.States[4].Status
        end
    end
    return nil, nil
end

local function createSafePlatform(targetPart, label)
    local character, humanoid, root = characterParts(8)
    if not character then
        return nil, nil, "Character was not ready."
    end

    local previousPlatform = Runtime.SafePlatform
    local platform = Instance.new("Part")
    platform.Name = "SliceHub_TS_SupplySafeFloor_" .. tostring(label or "Target")
    platform.Anchored = true
    platform.CanCollide = true
    platform.CanTouch = false
    platform.CanQuery = false
    platform.Transparency = 1
    platform.Size = Vector3.new(30, 1, 30)


    local safeHeight = 145
    local standOffset = (tonumber(humanoid.HipHeight) or 2)
        + root.Size.Y / 2
        + platform.Size.Y / 2
    local desiredRootPosition = targetPart.Position + Vector3.new(0, safeHeight, 0)
    platform.CFrame = CFrame.new(desiredRootPosition - Vector3.new(0, standOffset, 0))
    platform.Parent = workspace
    Runtime.SafePlatforms[#Runtime.SafePlatforms + 1] = platform

    Runtime.Transitioning = true
    Runtime.SafePlatform = platform
    Runtime.SafeCFrame = CFrame.new(desiredRootPosition)
    Runtime.SafeTarget = tostring(label or "Target")

    local deadline = os.clock() + 2.0
    local settled = false
    repeat
        if humanoid.Health <= 0 or not character.Parent then
            break
        end
        pcall(function()
            character:PivotTo(Runtime.SafeCFrame)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        humanoid.Sit = false
        humanoid.PlatformStand = false
        pcall(function()
            humanoid:ChangeState(Enum.HumanoidStateType.Running)
        end)
        if (root.Position - Runtime.SafeCFrame.Position).Magnitude <= 4 then
            settled = true
            break
        end
        task.wait(0.08)
    until os.clock() >= deadline
    Runtime.Transitioning = false

    if settled and previousPlatform and previousPlatform ~= platform then
        task.delay(0.35, function()
            if previousPlatform ~= Runtime.SafePlatform then
                destroyPlatform(previousPlatform)
            end
        end)
    end

    if not settled then
        return platform, Runtime.SafeCFrame, "Could not settle on the high safety platform."
    end
    return platform, Runtime.SafeCFrame, nil
end

local function maintainSafePerch()
    if Runtime.Touching or Runtime.Transitioning then
        return true
    end
    local platform = Runtime.SafePlatform
    local desired = Runtime.SafeCFrame
    if not platform or not platform.Parent or not desired then
        return false
    end
    local character, humanoid, root = characterParts(0.2)
    if not character then
        return false
    end
    local distance = (root.Position - desired.Position).Magnitude
    if distance > 4 or root.Position.Y < desired.Position.Y - 2 then
        pcall(function()
            character:PivotTo(desired)
        end)
    end
    pcall(function()
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    humanoid.Sit = false
    humanoid.PlatformStand = false
    if humanoid:GetState() == Enum.HumanoidStateType.Freefall then
        pcall(function()
            humanoid:ChangeState(Enum.HumanoidStateType.Running)
        end)
    end
    return true
end


Runtime.towerNumber = function(model)
    return model and tonumber(string.match(tostring(model.Name or ""), "^WatchTower_(%d+)$")) or nil
end

Runtime.towerBuildCounts = function(model)
    local watchTower = model and model:FindFirstChild("Watch_Tower")
    if not watchTower then return 0, 0 end
    local done, total = 0, 0
    for _, child in ipairs(watchTower:GetChildren()) do
        if child:IsA("BasePart") then
            total += 1
            if child:GetAttribute("Done") == true then done += 1 end
        end
    end
    return done, total
end

Runtime.towerLooksComplete = function(model)
    if not model or not model.Parent then return true end
    local done, total = Runtime.towerBuildCounts(model)
    if total > 0 and done >= total then return true end
    if done > 0 and not CollectionService:HasTag(model, "TS_Towers") then return true end
    return false
end

Runtime.listWorkspaceTowers = function()
    local output, seen = {}, {}
    for _, tagged in ipairs(CollectionService:GetTagged("TS_Towers")) do
        if tagged:IsA("Model") and tagged:IsDescendantOf(workspace) and Runtime.towerNumber(tagged) then
            seen[tagged] = true
            output[#output + 1] = tagged
        end
    end
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Model") and Runtime.towerNumber(object) and not seen[object] then
            seen[object] = true
            output[#output + 1] = object
        end
    end
    table.sort(output, function(a, b)
        return (Runtime.towerNumber(a) or 99) < (Runtime.towerNumber(b) or 99)
    end)
    return output
end

Runtime.updateCompletedTowerEvidence = function()
    for _, tower in ipairs(Runtime.listWorkspaceTowers()) do
        local number = Runtime.towerNumber(tower)
        if number and Runtime.towerLooksComplete(tower) then Runtime.TowerCompleted[number] = true end
    end
end

Runtime.completedTowerCount = function()
    local count = 0
    for number = 1, 3 do
        if Runtime.TowerCompleted[number] == true then count += 1 end
    end
    return count
end

Runtime.findActiveTower = function()
    local fallback
    for _, tower in ipairs(Runtime.listWorkspaceTowers()) do
        local number = Runtime.towerNumber(tower)
        if number and Runtime.TowerCompleted[number] ~= true and not Runtime.towerLooksComplete(tower) then
            if CollectionService:HasTag(tower, "TS_Towers") then return tower end
            fallback = fallback or tower
        end
    end
    return fallback
end

Runtime.towerActivationPart = function(tower)
    local hitbox = tower and tower:FindFirstChild("Hitbox", true)
    if hitbox and hitbox:IsA("BasePart") then return hitbox end
    return tower and tower.PrimaryPart or nil
end

Runtime.towerGrabLinkParts = function(instance)
    if not instance then return nil, nil end
    local part0, part1 = nil, nil
    pcall(function()
        part0 = instance.Part0
        part1 = instance.Part1
    end)
    if part0 or part1 then return part0, part1 end
    pcall(function()
        local attachment0 = instance.Attachment0
        local attachment1 = instance.Attachment1
        part0 = attachment0 and attachment0.Parent or nil
        part1 = attachment1 and attachment1.Parent or nil
    end)
    return part0, part1
end

Runtime.towerBreakGrabJoints = function()
    local character = Player.Character
    local titans = workspace:FindFirstChild("Titans")
    if not character or not titans then return 0 end

    local root = character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
    local seen, broken = {}, 0
    local function isJoint(object)
        return object:IsA("Weld")
            or object:IsA("WeldConstraint")
            or object:IsA("ManualWeld")
            or object:IsA("Motor6D")
            or object:IsA("Constraint")
    end
    local function inspect(container)
        if not container then return end
        for _, object in ipairs(container:GetDescendants()) do
            if not seen[object] and isJoint(object) then
                seen[object] = true
                local part0, part1 = Runtime.towerGrabLinkParts(object)
                local crossLinked = part0 and part1 and (
                    (part0:IsDescendantOf(character) and part1:IsDescendantOf(titans))
                    or (part1:IsDescendantOf(character) and part0:IsDescendantOf(titans))
                )
                if crossLinked and pcall(function() object:Destroy() end) then
                    broken += 1
                end
            end
        end
    end

    inspect(character)
    if root then
        local checked = 0
        for _, titan in ipairs(titans:GetChildren()) do
            if checked >= 16 then break end
            local part = titan:FindFirstChild("HumanoidRootPart")
                or titan:FindFirstChild("Torso")
                or titan.PrimaryPart
                or titan:FindFirstChildWhichIsA("BasePart", true)
            if part and (part.Position - root.Position).Magnitude <= 240 then
                checked += 1
                inspect(titan)
            end
        end
    end
    Runtime.TowerGrabBreaks = (tonumber(Runtime.TowerGrabBreaks) or 0) + broken
    return broken
end

Runtime.towerSafetyPulse = function(desired)
    local character, humanoid, root = characterParts(0.12)
    if not character or typeof(desired) ~= "CFrame" then return false end

    Runtime.towerBreakGrabJoints()
    local state = humanoid:GetState()
    local unsafeState = humanoid.Sit
        or humanoid.PlatformStand
        or state == Enum.HumanoidStateType.Seated
        or state == Enum.HumanoidStateType.PlatformStanding
        or state == Enum.HumanoidStateType.Physics
        or state == Enum.HumanoidStateType.FallingDown
    local displaced = (root.Position - desired.Position).Magnitude > 4.5
        or root.Position.Y < desired.Position.Y - 2

    if unsafeState or displaced then
        pcall(function()
            character:PivotTo(desired)
            root.CFrame = desired
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    else
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    humanoid.Sit = false
    humanoid.PlatformStand = false
    pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
    return true
end

Runtime.towerCreateSafety = function(hitbox, humanoid, root, number)


    local horizontalDiameter = math.max(
        tonumber(hitbox.Size.X) or 0,
        tonumber(hitbox.Size.Z) or 0,
        70
    )
    local activationRadius = math.max(35, horizontalDiameter / 2)
    local maximumInside = math.max(48, activationRadius - 6)
    local safeHeight = math.clamp(
        activationRadius * 0.82,
        48,
        math.min(118, maximumInside)
    )

    local platform = Instance.new("Part")
    platform.Name = "SliceHub_TS_TowerFloor_" .. tostring(number or 0)
    platform.Anchored = true
    platform.CanCollide = true
    platform.CanTouch = false
    platform.CanQuery = false
    platform.Transparency = 1
    platform.Size = Vector3.new(30, 1, 30)

    local standOffset = (tonumber(humanoid.HipHeight) or 2)
        + root.Size.Y / 2 + platform.Size.Y / 2
    local desiredPosition = hitbox.Position + Vector3.new(0, safeHeight, 0)
    platform.CFrame = CFrame.new(desiredPosition - Vector3.new(0, standOffset, 0))
    platform.Parent = workspace
    Runtime.SafePlatforms[#Runtime.SafePlatforms + 1] = platform
    return platform, CFrame.new(desiredPosition), activationRadius, safeHeight
end

Runtime.towerSettle = function(character, humanoid, root, desired, timeout)
    local deadline = os.clock() + math.max(0.6, tonumber(timeout) or 1.5)
    repeat
        if not character.Parent or humanoid.Health <= 0 then return false end
        pcall(function()
            character:PivotTo(desired)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        Runtime.towerBreakGrabJoints()
        humanoid.Sit = false
        humanoid.PlatformStand = false
        pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
        if (root.Position - desired.Position).Magnitude <= 4 then return true end
        task.wait(0.06)
    until os.clock() >= deadline
    return (root.Position - desired.Position).Magnitude <= 5
end

Runtime.towerTransferSafety = function(tower, hitbox, character, humanoid, root)
    local number = Runtime.towerNumber(tower) or 0
    local previous = Runtime.SafePlatform
    local platform, desired, radius, height = Runtime.towerCreateSafety(hitbox, humanoid, root, number)
    Runtime.Transitioning = true
    Runtime.SafePlatform = platform
    Runtime.SafeCFrame = desired
    Runtime.SafeTower = number
    local settled = Runtime.towerSettle(character, humanoid, root, desired, 1.25)
    Runtime.Transitioning = false
    if settled and previous and previous ~= platform then
        task.delay(0.25, function()
            if previous ~= Runtime.SafePlatform then destroyPlatform(previous) end
        end)
    end
    return desired, radius, height, settled
end

Runtime.holdTowerFromSafeAir = function(tower)
    local number = Runtime.towerNumber(tower) or 0
    local hitbox = Runtime.towerActivationPart(tower)
    if not hitbox or not hitbox:IsA("BasePart") then
        return false, "WatchTower_" .. tostring(number) .. " has no activation hitbox"
    end
    local character, humanoid, root = characterParts(8)
    if not character then return false, "character unavailable" end

    local oldAutoRotate = humanoid.AutoRotate
    humanoid.AutoRotate = false
    local desired, radius, height, settled = Runtime.towerTransferSafety(
        tower, hitbox, character, humanoid, root
    )
    if not settled then
        humanoid.AutoRotate = oldAutoRotate
        return false, "could not settle on Tower " .. tostring(number) .. " safety floor"
    end

    local lastDone, lastProgressAt = -1, os.clock()
    local startedAt = os.clock()
    while Runtime.Alive and Runtime.AutoLaunch and IS_OUTSKIRTS do
        if not tower.Parent then
            Runtime.TowerCompleted[number] = true
            humanoid.AutoRotate = oldAutoRotate
            maintainSafePerch()
            return true, "tower left Workspace"
        end
        character, humanoid, root = characterParts(0.5)
        if not character then return false, "character unavailable while building tower" end
        local done, total = Runtime.towerBuildCounts(tower)
        if done ~= lastDone then lastDone, lastProgressAt = done, os.clock() end
        if Runtime.towerLooksComplete(tower) then
            Runtime.TowerCompleted[number] = true
            humanoid.AutoRotate = oldAutoRotate
            maintainSafePerch()
            return true, "native completion verified"
        end

        Runtime.towerSafetyPulse(desired)
        if (root.Position - desired.Position).Magnitude > 5
            or (root.Position - hitbox.Position).Magnitude > radius * 0.94 then
            Runtime.towerSettle(character, humanoid, root, desired, 0.35)
        end


        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        humanoid.Sit = false
        humanoid.PlatformStand = false
        setStatus(
            "BUILDING WATCH TOWER " .. tostring(number),
            string.format(
                "Native progress %d/%d • safe grounded perch %.0f studs high.\nThe previous floor remains until the next floor is secured.",
                done, total, height
            ),
            "info"
        )
        RouteBody.Text = "Outskirts • Skirmish • Aberrant\nTower " .. tostring(number) .. " native activation."
        if os.clock() - lastProgressAt > 24 then
            humanoid.AutoRotate = oldAutoRotate
            return false, "no native tower progress for 24 seconds"
        end
        if os.clock() - startedAt > 110 then
            humanoid.AutoRotate = oldAutoRotate
            return false, "tower build timeout"
        end
        task.wait(0.10)
    end
    humanoid.AutoRotate = oldAutoRotate
    return false, "tower controller disabled"
end

Runtime.runOutskirtsTowerController = function()
    if Runtime.TowerControllerBusy then return end
    Runtime.TowerControllerBusy = true
    Runtime.TowerControllerStarted = true
    Runtime.ObjectiveCombatActive = true
    Runtime.ObjectiveCombatMode = "TOWER_DEFENSE"
    Runtime.ObjectiveCombatPhase = "WATCH TOWER SAFETY"
    Runtime.ObjectiveCombatKills = 0
    Runtime.ObjectiveCombatRegisters = 0
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatBladeReloadRetryAt = 0
    Runtime.ObjectiveCombatLastGrabScanAt = 0
    local guardToken = {Active = true}
    Runtime.TowerGuardToken = guardToken
    task.spawn(function()
        while Runtime.Alive
            and Runtime.AutoLaunch
            and Runtime.TowerControllerBusy
            and guardToken.Active
            and IS_OUTSKIRTS do
            if Runtime.SafeCFrame then
                Runtime.towerSafetyPulse(Runtime.SafeCFrame)
            end
            task.wait(0.02)
        end
    end)
    QuestHeader.Text = "WATCH TOWER MISSION PROGRESS"
    QuestRows[1].Text = ">  Watch Towers  •  NATIVE CONTROLLER ACTIVE"
    QuestRows[1].TextColor3 = Color3.fromRGB(112, 181, 255)
    setLaunchReady(false, "TOWERS ACTIVE")

    while Runtime.Alive and Runtime.AutoLaunch and IS_OUTSKIRTS do
        Runtime.updateCompletedTowerEvidence()
        local completed = Runtime.completedTowerCount()
        if completed >= 3 then
            QuestRows[1].Text = "✓  Watch Towers  •  3/3 BUILT"
            QuestRows[1].TextColor3 = Color3.fromRGB(105, 222, 154)
            setStatus(
                "ALL 3 WATCH TOWERS BUILT",
                "Tower credit is complete. Waiting briefly for the Escort objective to appear in this same Outskirts run.",
                "success"
            )

            local escortDeadline = os.clock() + 12
            local escortFound = false

            repeat
                local unclimbable = workspace:FindFirstChild("Unclimbable")
                local objectiveRoot = unclimbable and unclimbable:FindFirstChild("Objective")
                local escort = objectiveRoot and objectiveRoot:FindFirstChild("Escort")

                if escort and escort:IsA("Model") then
                    escortFound = true
                    break
                end

                if Runtime.SafeCFrame then
                    Runtime.towerSafetyPulse(Runtime.SafeCFrame)
                end

                task.wait(0.20)
            until os.clock() >= escortDeadline
                or not Runtime.Alive
                or not Runtime.AutoLaunch

            Runtime.TowerCleanupHeightUntil = os.clock() + 30
            Runtime.towerBreakGrabJoints()
            guardToken.Active = false
            Runtime.TowerGuardToken = nil
            Runtime.ObjectiveCombatActive = false
            Runtime.TowerControllerBusy = false

            if escortFound and type(Runtime.StartOutskirtsStage) == "function" then
                setStatus(
                    "ESCORT OBJECTIVE ACTIVE",
                    "Same-run Escort detected after Watch Towers. Starting native cart protection.",
                    "success"
                )
                task.spawn(Runtime.StartOutskirtsStage)
                return
            end

            setStatus(
                "ESCORT DID NOT START YET",
                "Same-run Escort was not confirmed after 12 seconds. Falling back to the proven finish + Retry path.",
                "warning"
            )
            if type(Runtime.PrepareTowerCleanupPerch) == "function" then
                Runtime.PrepareTowerCleanupPerch()
            end
            Runtime.RunNormalMissionCleanup(
                "WATCH TOWERS COMPLETE",
                "retry",
                function() return IS_OUTSKIRTS end
            )
            return
        end


        local tower = Runtime.findActiveTower()
        if tower then
            local ok, reason = Runtime.holdTowerFromSafeAir(tower)
            if not ok then
                setStatus("TOWER CONTROLLER WAIT", tostring(reason), "warning")
                maintainSafePerch()
                task.wait(0.35)
            else
                local deadline = os.clock() + 3
                repeat
                    maintainSafePerch()
                    if Runtime.SafeCFrame then Runtime.towerSafetyPulse(Runtime.SafeCFrame) end
                    Runtime.updateCompletedTowerEvidence()
                    if Runtime.findActiveTower() then break end
                    task.wait(0.08)
                until os.clock() >= deadline
            end
        else
            setStatus(
                Runtime.SafePlatform and "SAFE HANDOFF • WAITING FOR NEXT TOWER" or "WAITING FOR WATCH TOWER",
                "Completed evidence " .. tostring(completed) .. "/3. Tower construction has priority; combat stays paused until 3/3.",
                "info"
            )
            maintainSafePerch()
            if Runtime.SafeCFrame then Runtime.towerSafetyPulse(Runtime.SafeCFrame) end
            task.wait(0.08)
        end
    end
    guardToken.Active = false
    Runtime.TowerGuardToken = nil
    Runtime.ObjectiveCombatActive = false
    Runtime.TowerControllerBusy = false
end

local function fireNativeTouch(character, hitbox)
    if type(FireTouchInterest) ~= "function" then
        return false
    end
    local fired = false
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            local okBegin = pcall(FireTouchInterest, part, hitbox, 0)
            local okEnd = pcall(FireTouchInterest, part, hitbox, 1)
            if okBegin or okEnd then
                fired = true
            end
        end
    end
    return fired
end

local function briefNativeTouch(hitbox, verify, label)
    local character, humanoid, root = characterParts(5)
    if not character then
        return false, "Character was not ready for " .. tostring(label) .. "."
    end

    local safeCFrame = Runtime.SafeCFrame
    local oldAutoRotate = humanoid.AutoRotate
    humanoid.AutoRotate = false


    fireNativeTouch(character, hitbox)
    local simulatedDeadline = os.clock() + 0.65
    repeat
        if verify() then
            humanoid.AutoRotate = oldAutoRotate
            return true, "Native touch verified from the safety perch."
        end
        task.wait(0.08)
    until os.clock() >= simulatedDeadline


    local offsets = {0, 1.5, -1.5}
    for _, yOffset in ipairs(offsets) do
        Runtime.Touching = true
        local contactCFrame = CFrame.new(hitbox.Position + Vector3.new(0, yOffset, 0))
        pcall(function()
            character:PivotTo(contactCFrame)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        fireNativeTouch(character, hitbox)
        task.wait(0.22)
        if safeCFrame then
            pcall(function()
                character:PivotTo(safeCFrame)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)
        end
        Runtime.Touching = false

        local verifyDeadline = os.clock() + 1.25
        repeat
            maintainSafePerch()
            if verify() then
                humanoid.AutoRotate = oldAutoRotate
                return true, "Brief physical touch verified."
            end
            task.wait(0.10)
        until os.clock() >= verifyDeadline
    end

    Runtime.Touching = false
    humanoid.AutoRotate = oldAutoRotate
    maintainSafePerch()
    return false, tostring(label) .. " was not verified after safe native-touch attempts."
end

local function cratePickupEvidence(crate, box)
    if not crate or not crate.Parent or not crate:IsDescendantOf(workspace) then
        return true
    end
    if box then
        if not box.Parent or box.Parent ~= crate then
            return true
        end
        if box:IsA("BasePart") and box.Transparency >= 0.95 then
            return true
        end
    end
    return carryingEvidence() == true
end

local function waitForPickup(crate, box, timeout)
    local deadline = os.clock() + math.max(0.2, tonumber(timeout) or 0.2)
    repeat
        if cratePickupEvidence(crate, box) then
            Runtime.Carrying = true
            return true
        end
        task.wait(0.08)
    until os.clock() >= deadline
    return cratePickupEvidence(crate, box)
end

local function waitForDeposit(zone, baselineVisible, baselineProgress, baselineCarry, timeout)
    local deadline = os.clock() + math.max(0.5, tonumber(timeout) or 0.5)
    repeat
        local visible = visibleDepositCount(zone)
        local progress = readLiveSupplyProgress()
        local stillCarrying = carryingEvidence()
        if visible > baselineVisible
            or (progress ~= nil and baselineProgress ~= nil and progress > baselineProgress)
            or (progress ~= nil and progress >= 3)
            or (baselineCarry == true and stillCarrying == false) then
            Runtime.Carrying = false
            return true, visible, progress
        end
        task.wait(0.12)
    until os.clock() >= deadline
    return false, visibleDepositCount(zone), readLiveSupplyProgress()
end


local FOREST_COMBAT = {
    ObjectiveRadius = 300,
    ThreatRadius = 300,
    QuietSeconds = 3.00,
    BatchSize = 6,
    SlashCooldown = 0.080,


    SafeHeight = 340,
    PlatformSize = 38,
    GuardDelay = 0.020,
    GrabJointScanDelay = 0.060,
    SnapDistance = 7,
    SnapBelowTolerance = 3,
    DamageMin = 625,
    DamageMax = 850,
    ReloadRetry = 0.85,
    StationTargetSets = 3,
    StationActionAttempts = 4,
    StationActionPollSeconds = 1.35,
    StationVerifySeconds = 5.25,
    StationSpotDistance = 1.55,
    StationHoldTime = 0.72,
    StationRetryCooldown = 2.50,
    NativeRenewGrace = 1.10,
    BladeRenewObserve = 3.25,
    BladeRenewRetryDelay = 0.90,
    BladeRenewPendingTimeout = 8.00,
    BrokenFillThreshold = -0.12,
}

local function readLiveQuestProgress(index)
    local profile, source = findProfile()
    if not profile then
        return nil, nil
    end
    Runtime.Profile = profile
    Runtime.ProfileSource = source or Runtime.ProfileSource
    Runtime.LastProfileAt = os.clock()
    local scan = scanQuestProfile(profile, Runtime.ProfileSource)
    if scan and scan.Ready and scan.States and scan.States[index] then
        Runtime.CurrentScan = scan
        return tonumber(scan.States[index].Current), scan.States[index].Status
    end
    return nil, nil
end

local function findTitansFolder()
    local direct = workspace:FindFirstChild("Titans")
    if direct then
        return direct
    end
    for _, object in ipairs(workspace:GetChildren()) do
        if object:IsA("Folder") or object:IsA("Model") then
            if lower(object.Name) == "titans" then
                return object
            end
        end
    end
    return nil
end

local function titanAlive(titan)
    if not titan or not titan.Parent or not titan:IsA("Model") then
        return false
    end
    local humanoid = titan:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health > 0
end

local function exactTitanNape(titan)
    if not titan or not titan.Parent then
        return nil
    end
    local hitboxes = titan:FindFirstChild("Hitboxes")
    local hit = hitboxes and hitboxes:FindFirstChild("Hit")
    local nape = hit and hit:FindFirstChild("Nape")
    if nape and nape:IsA("BasePart") and nape.Parent then
        return nape
    end
    return nil
end

local function titanAimPart(titan)
    return exactTitanNape(titan)
        or (titan and titan:FindFirstChild("Nape", true))
        or (titan and titan:FindFirstChild("HumanoidRootPart"))
        or (titan and titan:FindFirstChild("UpperTorso", true))
        or (titan and titan:FindFirstChild("Torso", true))
end

local function titanPosition(titan)
    local part = titanAimPart(titan)
    return part and part:IsA("BasePart") and part.Position or nil
end

local function titanDescriptor(titan)
    if not titan then
        return ""
    end
    local values = {tostring(titan.Name or "")}
    for _, key in ipairs({
        "Type", "TitanType", "Variant", "Class", "Objective",
        "Mission", "Quest", "Target", "SpawnType", "Group", "Wave",
    }) do
        local ok, value = pcall(function()
            return titan:GetAttribute(key)
        end)
        if ok and value ~= nil then
            values[#values + 1] = tostring(value)
        end
    end
    pcall(function()
        for _, tag in ipairs(CollectionService:GetTags(titan)) do
            values[#values + 1] = tostring(tag)
        end
    end)
    return lower(table.concat(values, " "))
end

local function descriptorLooksObjective(titan)
    local text = titanDescriptor(titan)
    for _, token in ipairs({
        "objective", "supply", "supplies", "defend", "missing",
        "quest", "escort", "carriage", "convoy",
    }) do
        if string.find(text, token, 1, true) then
            return true
        end
    end
    return false
end

local function zonePosition(zone)
    local hitbox = hitboxFor(zone)
    if hitbox then
        return hitbox.Position
    end
    return objectWorldPosition(zone)
end

local function distanceFromZone(titan, center)
    local position = titanPosition(titan)
    if not position or typeof(center) ~= "Vector3" then
        return math.huge
    end
    return (position - center).Magnitude
end

local function markObjectiveTitan(titan, center, force)
    if not titan or not titan.Parent then
        return false
    end
    local position = titanPosition(titan)
    if position then
        Runtime.ObjectiveCombatFirstPosition[titan] =
            Runtime.ObjectiveCombatFirstPosition[titan] or position
    end
    local first = Runtime.ObjectiveCombatFirstPosition[titan]
    local closeAtSpawn = typeof(first) == "Vector3"
        and typeof(center) == "Vector3"
        and (first - center).Magnitude <= FOREST_COMBAT.ObjectiveRadius
    local marked = force == true or descriptorLooksObjective(titan) or closeAtSpawn
    if marked then
        local firstMark = Runtime.ObjectiveCombatTagged[titan] ~= true
        Runtime.ObjectiveCombatTagged[titan] = true
        Runtime.ObjectiveCombatLastSpawnAt = os.clock()
        Runtime.ObjectiveCombatWaveSeen = true
        if firstMark then
            Runtime.ObjectiveCombatWaveCount += 1
        end
    end
    return marked
end

local function objectiveThreat(titan, center)
    if Runtime.ObjectiveCombatTagged[titan] == true then
        return true
    end
    if descriptorLooksObjective(titan) then
        Runtime.ObjectiveCombatTagged[titan] = true
        Runtime.ObjectiveCombatWaveSeen = true
        return true
    end


    return false
end

local function collectCombatTargets(center)
    local objectiveTargets = {}
    local normalTargets = {}
    local folder = findTitansFolder()
    if not folder then
        return objectiveTargets, normalTargets, 0
    end

    local total = 0
    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            local nape = exactTitanNape(titan)
            if nape then
                total += 1
                local entry = {
                    Titan = titan,
                    Part = nape,
                    DistanceToObjective = distanceFromZone(titan, center),
                }
                if objectiveThreat(titan, center) then
                    objectiveTargets[#objectiveTargets + 1] = entry
                else
                    normalTargets[#normalTargets + 1] = entry
                end
            end
        end
    end

    table.sort(objectiveTargets, function(a, b)
        return a.DistanceToObjective < b.DistanceToObjective
    end)

    local character = Player.Character
    local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
    local origin = root and root.Position or center or Vector3.zero
    table.sort(normalTargets, function(a, b)
        return (a.Part.Position - origin).Magnitude < (b.Part.Position - origin).Magnitude
    end)

    return objectiveTargets, normalTargets, total
end

local function averageTargetPosition(entries, fallback)
    local sum = Vector3.zero
    local count = 0
    for index = 1, math.min(#entries, FOREST_COMBAT.BatchSize) do
        local part = entries[index] and entries[index].Part
        if part and part.Parent then
            sum += part.Position
            count += 1
        end
    end
    if count > 0 then
        return sum / count
    end
    return fallback
end

local function moveCombatPerch(position, label)
    if typeof(position) ~= "Vector3" then
        return false, "Combat perch position was unavailable."
    end
    local character, humanoid, root = characterParts(5)
    if not character then
        return false, "Character was not ready for combat perch."
    end

    local previousPlatform = Runtime.SafePlatform
    local towerHandoff = previousPlatform
        and previousPlatform.Parent
        and string.find(tostring(previousPlatform.Name), "SliceHub_TS_TowerFloor_", 1, true) ~= nil
    local platform = towerHandoff and nil or previousPlatform
    if not platform or not platform.Parent then
        platform = Instance.new("Part")
        platform.Name = "SliceHub_TS_ObjectiveCombatSafeFloor"
        platform.Anchored = true
        platform.CanCollide = true
        platform.CanTouch = false
        platform.CanQuery = false
        platform.Transparency = 1
        platform.Size = Vector3.new(FOREST_COMBAT.PlatformSize, 1, FOREST_COMBAT.PlatformSize)
        platform.Parent = workspace
        Runtime.SafePlatform = platform
        Runtime.SafePlatforms[#Runtime.SafePlatforms + 1] = platform
    end

    local standOffset = (tonumber(humanoid.HipHeight) or 2)
        + root.Size.Y / 2
        + platform.Size.Y / 2
    local cleanupHeight = os.clock() < (tonumber(Runtime.TowerCleanupHeightUntil) or 0)
        and 420
        or FOREST_COMBAT.SafeHeight
    local desiredRoot = position + Vector3.new(0, cleanupHeight, 0)
    platform.CFrame = CFrame.new(desiredRoot - Vector3.new(0, standOffset, 0))
    Runtime.SafeCFrame = CFrame.lookAt(desiredRoot, position)
    Runtime.SafeTarget = tostring(label or "Combat")
    Runtime.Transitioning = true

    pcall(function()
        character:PivotTo(Runtime.SafeCFrame)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    humanoid.Sit = false
    humanoid.PlatformStand = false
    pcall(function()
        humanoid:ChangeState(Enum.HumanoidStateType.Running)
    end)
    Runtime.Transitioning = false
    if towerHandoff and previousPlatform and previousPlatform ~= platform then
        task.delay(0.45, function()
            if previousPlatform ~= Runtime.SafePlatform then
                destroyPlatform(previousPlatform)
            end
        end)
    end
    if type(Runtime.towerBreakGrabJoints) == "function" then
        Runtime.towerBreakGrabJoints()
    end
    return true
end

Runtime.PrepareTowerCleanupPerch = function()
    local folder = workspace:FindFirstChild("Titans")
    local _, _, root = characterParts(1)
    local fallback = root and root.Position or Vector3.zero
    local sum, count = Vector3.zero, 0
    if folder then
        for _, titan in ipairs(folder:GetChildren()) do
            local humanoid = titan:FindFirstChildOfClass("Humanoid")
            local nape = titan:FindFirstChild("Nape", true)
                or titan:FindFirstChild("HumanoidRootPart")
                or titan.PrimaryPart
            if humanoid and humanoid.Health > 0 and nape and nape:IsA("BasePart") then
                sum += nape.Position
                count += 1
                if count >= 12 then break end
            end
        end
    end
    Runtime.TowerCleanupHeightUntil = os.clock() + 30
    return moveCombatPerch(count > 0 and (sum / count) or fallback, "Tower cleanup handoff")
end

local function bladeToolScore(tool)
    if not tool or not tool:IsA("Tool") then
        return -math.huge
    end
    local name = lower(tool.Name)
    if string.find(name, "ripper", 1, true)
        or string.find(name, "skill", 1, true)
        or string.find(name, "ability", 1, true) then
        return -math.huge
    end
    local score = 0
    if string.find(name, "blade", 1, true) then score += 120 end
    if string.find(name, "sword", 1, true) then score += 100 end
    if string.find(name, "katana", 1, true) then score += 100 end
    if string.find(name, "odm", 1, true) then score += 35 end
    if string.find(name, "gear", 1, true) then score += 12 end
    return score
end

local function prepareBladeTool()
    local character, humanoid = characterParts(1)
    if not character or not humanoid then
        return nil
    end
    local backpack = Player:FindFirstChildOfClass("Backpack")
    local best, bestScore = nil, -math.huge
    local function consider(container)
        if not container then return end
        for _, item in ipairs(container:GetChildren()) do
            local score = bladeToolScore(item)
            if score > bestScore then
                best = item
                bestScore = score
            end
        end
    end
    consider(character)
    consider(backpack)
    if best and bestScore > 0 then
        if best.Parent ~= character then
            pcall(function()
                humanoid:EquipTool(best)
            end)
        end
        pcall(function()
            best:Activate()
        end)
        return best
    end
    return nil
end

local function exactBladePOST()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local post = remotes and remotes:FindFirstChild("POST")
    if post and post:IsA("RemoteEvent") then
        return post
    end
    return nil
end

local function exactBladeGET()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local get = remotes and remotes:FindFirstChild("GET")
    if get and get:IsA("RemoteFunction") then
        return get
    end
    return nil
end

local function trustedBladeRoot()
    local interface = PlayerGui:FindFirstChild("Interface")
    local hud = interface and interface:FindFirstChild("HUD")
    local main = hud and hud:FindFirstChild("Main")
    local top = main and main:FindFirstChild("Top")
    local seven = top and top:FindFirstChild("7")
    return seven and seven:FindFirstChild("Blades") or nil
end

local function readBladeFill()
    local root = trustedBladeRoot()
    if not root then return nil end
    local inner = root:FindFirstChild("Inner")
    local bar = inner and inner:FindFirstChild("Bar")
    local gradient = bar and bar:FindFirstChild("Gradient")
    if gradient and gradient:IsA("UIGradient") then
        local ok, offset = pcall(function() return gradient.Offset end)
        if ok and typeof(offset) == "Vector2" then
            return tonumber(offset.X)
        end
    end
    return nil
end

local function textValue(object)
    if not object then return nil end
    if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
        return tostring(object.Text or "")
    end
    if object:IsA("IntValue") or object:IsA("NumberValue") or object:IsA("StringValue") then
        return tostring(object.Value)
    end
    return nil
end

local function readBladeSetsCompact()
    local root = trustedBladeRoot()
    if not root then return nil end
    local sets = root:FindFirstChild("Sets", true)
    if not sets then return nil end
    local candidates = {sets}
    for _, object in ipairs(sets:GetDescendants()) do
        candidates[#candidates + 1] = object
    end
    for _, object in ipairs(candidates) do
        local text = textValue(object)
        if text then
            local current, maximum = string.match(text:gsub("%s+", ""), "(%d+)%/(%d+)")
            current, maximum = tonumber(current), tonumber(maximum)
            if current and maximum and maximum <= 6 then
                return current, maximum
            end
        end
    end
    return nil
end

local beginBladeStationRefill

local function bladeFillUsable(fill)
    return fill == nil or fill > FOREST_COMBAT.BrokenFillThreshold
end

local function clearBladeRenewPending(outcome)
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatRenewStartedAt = 0
    Runtime.ObjectiveCombatRenewBeforeSets = nil
    Runtime.ObjectiveCombatRenewLastOutcome = tostring(outcome or "READY")
end

local function observeBladeRenewal(beforeSets, seconds)
    local deadline = os.clock() + math.max(0.15, tonumber(seconds) or 0.15)
    local consumed = false
    local lowestSets = beforeSets
    repeat
        task.wait(0.05)
        local liveFill = readBladeFill()
        local liveSets = readBladeSetsCompact()
        if bladeFillUsable(liveFill) then
            return true, consumed, liveSets, liveFill, "FILL_RECOVERED"
        end
        if beforeSets ~= nil and liveSets ~= nil and liveSets < beforeSets then
            consumed = true
            lowestSets = lowestSets == nil and liveSets or math.min(lowestSets, liveSets)
        end
    until os.clock() >= deadline
    return false, consumed, lowestSets or readBladeSetsCompact(), readBladeFill(),
        consumed and "SET_CONSUMED_BUT_FILL_STILL_BROKEN" or "NO_ACCEPTANCE"
end

local function performSingleOwnerBladeRenew(get, beforeSets, allowNativeGrace)
    if not get then
        return false, false, beforeSets, readBladeFill(), "GET_MISSING"
    end


    if allowNativeGrace then
        local ready, consumed, liveSets, liveFill, outcome = observeBladeRenewal(
            beforeSets,
            FOREST_COMBAT.NativeRenewGrace
        )
        if ready or consumed then
            if consumed and not ready then
                local lateReady, _, lateSets, lateFill = observeBladeRenewal(
                    beforeSets,
                    FOREST_COMBAT.BladeRenewObserve
                )
                return lateReady, true, lateSets, lateFill,
                    lateReady and "NATIVE_SET_CONSUMED_AND_RECOVERED" or outcome
            end
            return ready, consumed, liveSets, liveFill,
                ready and "NATIVE_RECOVERED" or outcome
        end
    end


    pcall(function()
        get:InvokeServer("Blades", "Reload")
    end)
    return observeBladeRenewal(beforeSets, FOREST_COMBAT.BladeRenewObserve)
end

local function ensureBladeUsable()
    if Runtime.ObjectiveCombatStationBusy then
        return false
    end

    local sets = readBladeSetsCompact()
    local fill = readBladeFill()

    if bladeFillUsable(fill) then
        if Runtime.ObjectiveCombatRenewPending then
            clearBladeRenewPending("FILL_RECOVERED")
        end


        return true
    end


    if Runtime.ObjectiveCombatRenewPending then
        local pendingFor = os.clock() - (Runtime.ObjectiveCombatRenewStartedAt or os.clock())
        if pendingFor >= FOREST_COMBAT.BladeRenewPendingTimeout then
            setStatus(
                "BLADE RENEWAL PAUSED",
                "One spare set was consumed, but the current blade did not recover. No second reload will be sent automatically.",
                "error"
            )
        end
        return false
    end

    if sets ~= nil and sets <= 0 then
        if os.clock() >= (Runtime.ObjectiveCombatStationRetryAt or 0)
            and type(beginBladeStationRefill) == "function" then
            beginBladeStationRefill("broken blade + 0/3")
        end
        return false
    end

    if Runtime.ObjectiveCombatReloadBusy then
        return false
    end
    if os.clock() < (Runtime.ObjectiveCombatBladeReloadRetryAt or 0) then
        return false
    end

    local get = exactBladeGET()
    if not get then
        setStatus("BLADE RELOAD REMOTE MISSING", "ReplicatedStorage.Assets.Remotes.GET was not found.", "error")
        return false
    end

    Runtime.ObjectiveCombatReloadBusy = true
    task.spawn(function()
        local beforeSets = readBladeSetsCompact()
        local ready, consumed, liveSets, _, outcome = performSingleOwnerBladeRenew(
            get,
            beforeSets,
            true
        )
        if ready then
            Runtime.ObjectiveCombatBladeReloadRetryAt = 0
            clearBladeRenewPending(outcome)
        elseif consumed then
            Runtime.ObjectiveCombatRenewPending = true
            Runtime.ObjectiveCombatRenewStartedAt = os.clock()
            Runtime.ObjectiveCombatRenewBeforeSets = beforeSets
            Runtime.ObjectiveCombatRenewLastOutcome = outcome
            setStatus(
                "BLADE RENEWAL SETTLE",
                string.format(
                    "One set was consumed (%s -> %s). Waiting for the same blade renewal; no duplicate request will be sent.",
                    tostring(beforeSets),
                    tostring(liveSets)
                ),
                "warning"
            )
        else
            Runtime.ObjectiveCombatRenewLastOutcome = outcome
            Runtime.ObjectiveCombatBladeReloadRetryAt =
                os.clock() + FOREST_COMBAT.BladeRenewRetryDelay
        end
        Runtime.ObjectiveCombatReloadBusy = false
    end)
    return false
end

local function fireExactBladeBatch(entries)
    local post = exactBladePOST()
    if not post then
        return false, 0, "ReplicatedStorage.Assets.Remotes.POST missing"
    end
    if not ensureBladeUsable() then
        return false, 0, Runtime.ObjectiveCombatReloadBusy and "Reloading blade" or "Blade unavailable"
    end

    prepareBladeTool()
    local valid = {}
    for index = 1, math.min(#entries, FOREST_COMBAT.BatchSize) do
        local titan = entries[index] and entries[index].Titan
        local nape = titan and exactTitanNape(titan) or nil
        if titanAlive(titan) and nape then
            local variant = entries[index].Variant == true
            if not variant and type(Runtime.IsIceBurstVariant) == "function" then
                variant = select(1, Runtime.IsIceBurstVariant(titan)) == true
            end
            valid[#valid + 1] = {Titan = titan, Part = nape, Variant = variant}
        end
    end
    if #valid == 0 then
        return false, 0, "No exact napes in the selected batch"
    end

    local before = {}
    for _, entry in ipairs(valid) do
        local humanoid = entry.Titan:FindFirstChildOfClass("Humanoid")
        before[entry.Titan] = humanoid and humanoid.Health or nil
    end

    post:FireServer("Attacks", "Slash", true)
    local registers = 0
    for _, entry in ipairs(valid) do
        if entry.Part and entry.Part.Parent then
            post:FireServer(
                "Hitboxes",
                "Register",
                entry.Part,
                math.random(FOREST_COMBAT.DamageMin, FOREST_COMBAT.DamageMax)
            )
            registers += 1
        end
    end
    Runtime.ObjectiveCombatRegisters += registers

    task.wait(0.09)
    local kills = 0
    local damaged = 0
    local variantKills = 0
    for _, entry in ipairs(valid) do
        local titan = entry.Titan
        local humanoid = titan and titan:FindFirstChildOfClass("Humanoid") or nil
        local after = humanoid and humanoid.Health or 0
        local old = before[titan]
        if not titanAlive(titan) then
            kills += 1
            if entry.Variant == true
                and Runtime.ObjectiveCombatMode == "UTGARD"
                and Runtime.UtgardVariantCredited[titan] ~= true then
                Runtime.UtgardVariantCredited[titan] = true
                Runtime.UtgardVariantKills = math.clamp(
                    math.floor(tonumber(Runtime.UtgardVariantKills) or 0) + 1,
                    0,
                    3
                )
                variantKills += 1
                saveEnabled(Runtime.AutoLaunch)
            end
        elseif old ~= nil and after < old - 0.01 then
            damaged += 1
        end
    end
    Runtime.ObjectiveCombatKills += kills
    if kills > 0 or damaged > 0 then
        Runtime.ObjectiveCombatLastProgressAt = os.clock()
    end
    return true, registers, string.format("K%d D%d V%d", kills, damaged, variantKills)
end

Runtime.TowerDefensePulse = function(center, radius)
    if not Runtime.ObjectiveCombatActive
        or Runtime.ObjectiveCombatMode ~= "TOWER_DEFENSE"
        or Runtime.ObjectiveCombatStationBusy
        or typeof(center) ~= "Vector3" then
        return false
    end
    local now = os.clock()
    if now - (tonumber(Runtime.TowerDefenseLastAt) or 0) < 0.16 then
        return false
    end
    Runtime.TowerDefenseLastAt = now

    local folder = findTitansFolder()
    if not folder then return false end
    local targets = {}
    local maxRadius = tonumber(radius) or 185
    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            local nape = exactTitanNape(titan)
            if nape then
                local distance = (nape.Position - center).Magnitude
                if distance <= maxRadius then
                    targets[#targets + 1] = {
                        Titan = titan,
                        Part = nape,
                        DistanceToObjective = distance,
                    }
                end
            end
        end
    end
    table.sort(targets, function(a, b)
        return a.DistanceToObjective < b.DistanceToObjective
    end)
    if #targets == 0 then return false end
    return fireExactBladeBatch(targets)
end

local function guiObjectActuallyVisible(object)
    if not object then
        return false
    end

    local node = object
    while node and node ~= PlayerGui do
        if node:IsA("ScreenGui") and node.Enabled ~= true then
            return false
        end
        if node:IsA("GuiObject") and node.Visible ~= true then
            return false
        end
        node = node.Parent
    end

    if object:IsA("GuiObject") then
        local ok, size = pcall(function()
            return object.AbsoluteSize
        end)
        if ok and size and (size.X <= 0 or size.Y <= 0) then
            return false
        end
    end

    return true
end

local function missionResultVisible()


    local interface = PlayerGui:FindFirstChild("Interface")
    local rewards = interface and interface:FindFirstChild("Rewards")
    local main = rewards and rewards:FindFirstChild("Main")
    local info = main and main:FindFirstChild("Info")
    local state = info and info:FindFirstChild("State")

    if not state or not (state:IsA("TextLabel") or state:IsA("TextButton") or state:IsA("TextBox")) then
        return false, nil
    end
    if not guiObjectActuallyVisible(state) then
        return false, nil
    end

    local text = lower(state.Text)
    local validState = text == "mission completed"
        or text == "mission complete"
        or text == "mission failed"
        or text == "raid completed"
        or text == "raid complete"
        or text == "raid failed"
    if not validState then
        return false, nil
    end


    local corroborated = false
    for _, object in ipairs(rewards:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox"))
            and object ~= state
            and guiObjectActuallyVisible(object) then
            local value = lower(object.Text)
            if value == "stats"
                or value == "obtained"
                or value == "retry"
                or value == "leave"
                or value == "modifiers"
                or string.find(value, "time taken", 1, true)
                or string.find(value, "damage dealt", 1, true) then
                corroborated = true
                break
            end
        end
    end

    return corroborated, corroborated and text or nil
end

local function stopObjectiveCombat(reason)
    Runtime.ObjectiveCombatActive = false
    Runtime.ObjectiveCombatPhase = "STOPPED"
    Runtime.ObjectiveCombatMode = "IDLE"
    Runtime.ObjectiveCombatSafetyToken = nil
    if Runtime.ObjectiveCombatConnection then
        pcall(function()
            Runtime.ObjectiveCombatConnection:Disconnect()
        end)
        Runtime.ObjectiveCombatConnection = nil
    end
    if reason then
        RouteBody.Text = tostring(reason)
    end
end

local function partBelongsToCharacter(part)
    local character = Player.Character
    return character ~= nil and part ~= nil and part:IsDescendantOf(character)
end

local function partBelongsToTitan(part)
    local folder = findTitansFolder()
    return folder ~= nil and part ~= nil and part:IsDescendantOf(folder)
end

local function isGrabJoint(instance)
    return instance
        and (
            instance:IsA("Weld")
            or instance:IsA("WeldConstraint")
            or instance:IsA("ManualWeld")
            or instance:IsA("Motor6D")
            or instance:IsA("Constraint")
        )
end

local function grabLinkParts(instance)
    if not instance then
        return nil, nil
    end
    local part0, part1 = nil, nil
    pcall(function()
        part0 = instance.Part0
        part1 = instance.Part1
    end)
    if part0 or part1 then
        return part0, part1
    end
    pcall(function()
        local attachment0 = instance.Attachment0
        local attachment1 = instance.Attachment1
        part0 = attachment0 and attachment0.Parent or nil
        part1 = attachment1 and attachment1.Parent or nil
    end)
    return part0, part1
end

local function breakCrossLinkedGrabJoints()
    local character = Player.Character
    local folder = findTitansFolder()
    if not character or not folder then
        return 0
    end

    local broken = 0
    local seen = {}
    local function inspect(root)
        if not root then
            return
        end
        for _, object in ipairs(root:GetDescendants()) do
            if not seen[object] and isGrabJoint(object) then
                seen[object] = true
                local part0, part1 = grabLinkParts(object)
                local crossLinked =
                    (partBelongsToCharacter(part0) and partBelongsToTitan(part1))
                    or (partBelongsToCharacter(part1) and partBelongsToTitan(part0))
                if crossLinked then
                    local ok = pcall(function()
                        object:Destroy()
                    end)
                    if ok then
                        broken += 1
                    end
                end
            end
        end
    end

    inspect(character)


    local root = character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
    if root then
        local checked = 0
        for _, titan in ipairs(folder:GetChildren()) do
            if checked >= 12 then
                break
            end
            local position = titanPosition(titan)
            if position and (position - root.Position).Magnitude <= 420 then
                checked += 1
                inspect(titan)
            end
        end
    end

    Runtime.ObjectiveCombatGrabBreaks += broken
    return broken
end

local function grabStateFlagActive(container)
    if not container then
        return false
    end
    local attributes = {}
    pcall(function()
        attributes = container:GetAttributes()
    end)
    for name, value in pairs(attributes) do
        local key = lower(name)
        local relevant = string.find(key, "grab", 1, true)
            or string.find(key, "held", 1, true)
            or string.find(key, "captur", 1, true)
            or string.find(key, "caught", 1, true)
        if relevant then
            if value == true then
                return true
            end
            local valueText = lower(value)
            if valueText == "true"
                or string.find(valueText, "grab", 1, true)
                or string.find(valueText, "held", 1, true)
                or string.find(valueText, "captur", 1, true)
                or string.find(valueText, "caught", 1, true) then
                return true
            end
        end
    end
    for _, object in ipairs(container:GetDescendants()) do
        if object:IsA("BoolValue") and object.Value == true then
            local key = lower(object.Name)
            if string.find(key, "grab", 1, true)
                or string.find(key, "held", 1, true)
                or string.find(key, "captur", 1, true)
                or string.find(key, "caught", 1, true) then
                return true
            end
        end
    end
    return false
end

local function forceCombatSafeSnap(reason)
    local desired = Runtime.SafeCFrame
    local character, humanoid, root = characterParts(0.1)
    if not desired or not character then
        return false
    end
    pcall(function()
        character:PivotTo(desired)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    humanoid.Sit = false
    humanoid.PlatformStand = false
    pcall(function()
        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
    end)
    pcall(function()
        humanoid:ChangeState(Enum.HumanoidStateType.Running)
    end)
    Runtime.ObjectiveCombatEmergencySnaps += 1
    Runtime.SafeTarget = "Anti-grab snap: " .. tostring(reason or "displacement")
    return true
end

local function combatSafetyGuard()
    if Runtime.Touching or Runtime.Transitioning then
        return true
    end
    local desired = Runtime.SafeCFrame
    local platform = Runtime.SafePlatform
    if not desired or not platform or not platform.Parent then
        return false
    end
    local character, humanoid, root = characterParts(0.1)
    if not character then
        return false
    end

    local now = os.clock()
    local broken = 0
    if now - (Runtime.ObjectiveCombatLastGrabScanAt or 0) >= FOREST_COMBAT.GrabJointScanDelay then
        Runtime.ObjectiveCombatLastGrabScanAt = now
        broken = breakCrossLinkedGrabJoints()
    end

    local state = humanoid:GetState()
    local badState = humanoid.Sit == true
        or humanoid.PlatformStand == true
        or state == Enum.HumanoidStateType.PlatformStanding
        or state == Enum.HumanoidStateType.Seated
        or state == Enum.HumanoidStateType.Physics
        or state == Enum.HumanoidStateType.FallingDown
    local flagged = grabStateFlagActive(character)
        or grabStateFlagActive(humanoid)
        or grabStateFlagActive(root)
    local distance = (root.Position - desired.Position).Magnitude
    local displaced = distance > FOREST_COMBAT.SnapDistance
        or root.Position.Y < desired.Position.Y - FOREST_COMBAT.SnapBelowTolerance

    if broken > 0 or badState or flagged or displaced then
        forceCombatSafeSnap(
            broken > 0 and "grab joint"
            or flagged and "grab flag"
            or badState and "humanoid state"
            or "position displacement"
        )
    else
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        humanoid.Sit = false
        humanoid.PlatformStand = false
    end
    return true
end

local function readBladeRefillChargesCompact()
    local value = nil
    pcall(function()
        value = Player:GetAttribute("Refills")
    end)
    return tonumber(value)
end

local function findMissionGasStationPart()
    local climbable = workspace:FindFirstChild("Climbable")
    local walls = climbable and climbable:FindFirstChild("_Walls")
    local gate = walls and walls:FindFirstChild("Gate")
    local gasTanks = gate and gate:FindFirstChild("GasTanks")
    local direct = gasTanks and gasTanks:FindFirstChild("Refill")
    if direct and direct:IsA("BasePart") then
        return direct
    end

    local bestPart, bestScore = nil, -math.huge
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("BasePart") then
            local objectName = lower(object.Name)
            local score = objectName == "refill" and 60 or 0
            local node = object.Parent
            for _ = 1, 8 do
                if not node then
                    break
                end
                local nodeName = lower(node.Name)
                if string.find(nodeName, "gastank", 1, true)
                    or string.find(nodeName, "gas tank", 1, true)
                    or nodeName == "gas" then
                    score += 18
                end
                if string.find(nodeName, "station", 1, true)
                    or string.find(nodeName, "supply", 1, true) then
                    score += 10
                end
                node = node.Parent
            end
            if score > bestScore then
                bestScore = score
                bestPart = object
            end
        end
    end
    return bestScore > 0 and bestPart or nil
end

local function stationGroundAt(position, character)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Blacklist
    params.FilterDescendantsInstances = character and {character} or {}
    local result = workspace:Raycast(
        position + Vector3.new(0, 35, 0),
        Vector3.new(0, -90, 0),
        params
    )
    if result and result.Position then
        return result.Position + Vector3.new(0, 3.1, 0)
    end
    return position
end

local function missionStationSpots(station, character)
    local distance = math.max(0.75, FOREST_COMBAT.StationSpotDistance)
    local sx = math.max(1.5, station.Size.X * 0.5)
    local sz = math.max(1.5, station.Size.Z * 0.5)
    local raw = {
        (station.CFrame * CFrame.new(0, 0, -(sz + distance))).Position,
        (station.CFrame * CFrame.new(0, 0, sz + distance)).Position,
        (station.CFrame * CFrame.new(-(sx + distance), 0, 0)).Position,
        (station.CFrame * CFrame.new(sx + distance, 0, 0)).Position,
        (station.CFrame * CFrame.new(0, 1.5, -(sz + 0.35))).Position,
        (station.CFrame * CFrame.new(0, 1.5, sz + 0.35)).Position,
        (station.CFrame * CFrame.new(-(sx + 0.35), 1.5, 0)).Position,
        (station.CFrame * CFrame.new(sx + 0.35, 1.5, 0)).Position,
        station.Position + Vector3.new(0, 2.8, 0),
    }
    local spots = {}
    for _, position in ipairs(raw) do
        spots[#spots + 1] = stationGroundAt(position, character)
    end
    return spots
end

local function holdRefillKey()
    local key = Enum.KeyCode.R
    local usedExecutor = type(keypress) == "function" and type(keyrelease) == "function"
    if usedExecutor then
        pcall(function()
            keypress(key.Value or key)
        end)
    else
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, key, false, game)
        end)
    end
    task.wait(FOREST_COMBAT.StationHoldTime)
    if usedExecutor then
        pcall(function()
            keyrelease(key.Value or key)
        end)
    else
        pcall(function()
            VirtualInputManager:SendKeyEvent(false, key, false, game)
        end)
    end
end

local function holdCharacterAt(cframe, token)
    local character, humanoid, root = characterParts(0.2)
    if not character or typeof(cframe) ~= "CFrame" then
        return false
    end
    pcall(function()
        character:PivotTo(cframe)
        root.CFrame = cframe
        root.Anchored = true
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        humanoid.Sit = false
        humanoid.PlatformStand = false
        humanoid.AutoRotate = true
    end)
    if token then
        task.spawn(function()
            while Runtime.Alive
                and Runtime.ObjectiveCombatActive
                and Runtime.ObjectiveCombatStationBusy
                and token.Active do
                pcall(function()
                    if character.Parent and root.Parent then
                        character:PivotTo(cframe)
                        root.CFrame = cframe
                        root.Anchored = true
                        root.AssemblyLinearVelocity = Vector3.zero
                        root.AssemblyAngularVelocity = Vector3.zero
                        humanoid.Sit = false
                        humanoid.PlatformStand = false
                    end
                end)
                task.wait(0.02)
            end
        end)
    end
    return true
end

local function stationProgressAccepted(beforeSets, beforeRefills, seconds)
    local deadline = os.clock() + math.max(0.15, tonumber(seconds) or 0.15)
    repeat
        task.wait(0.04)
        local liveSets = readBladeSetsCompact()
        local liveRefills = readBladeRefillChargesCompact()
        if liveSets ~= nil and liveSets >= FOREST_COMBAT.StationTargetSets then
            return true, "SETS_FULL", liveSets, liveRefills
        end
        if beforeRefills ~= nil and liveRefills ~= nil and liveRefills < beforeRefills then
            return true, "REFILL_CHARGE_SPENT", liveSets, liveRefills
        end
        if beforeSets ~= nil and liveSets ~= nil and liveSets > beforeSets then
            return true, "SETS_INCREASING", liveSets, liveRefills
        end
    until os.clock() >= deadline
    return false, nil, readBladeSetsCompact(), readBladeRefillChargesCompact()
end

local function restoreCombatPerch(returnCFrame, message)
    local character, humanoid, root = characterParts(0.5)
    if not character or typeof(returnCFrame) ~= "CFrame" then
        return false
    end
    pcall(function()
        character:PivotTo(returnCFrame)
        root.CFrame = returnCFrame
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        humanoid.Sit = false
        humanoid.PlatformStand = false
        humanoid.AutoRotate = true
        humanoid:ChangeState(Enum.HumanoidStateType.Running)
    end)
    Runtime.SafeCFrame = returnCFrame
    Runtime.SafeTarget = tostring(message or "Blade refill return")
    return true
end

beginBladeStationRefill = function(reason)
    if Runtime.ObjectiveCombatStationBusy
        or not Runtime.ObjectiveCombatActive
        or os.clock() < (Runtime.ObjectiveCombatStationRetryAt or 0) then
        return false
    end

    local returnCFrame = Runtime.SafeCFrame
    if typeof(returnCFrame) ~= "CFrame" then
        setStatus("BLADE REFILL PAUSED", "The combat safety perch was unavailable.", "error")
        Runtime.ObjectiveCombatStationRetryAt = os.clock() + FOREST_COMBAT.StationRetryCooldown
        return false
    end

    Runtime.ObjectiveCombatStationBusy = true
    Runtime.ObjectiveCombatStationStatus = "LOCATING REFILL STATION"
    Runtime.ObjectiveCombatStationReturnCFrame = returnCFrame
    Runtime.Transitioning = true

    task.spawn(function()
        local success = false
        local failureReason = nil
        local station = findMissionGasStationPart()
        local beforeRefills = readBladeRefillChargesCompact()
        local beforeSets = readBladeSetsCompact()

        if beforeRefills ~= nil and beforeRefills <= 0 then
            failureReason = "No station refill charges remain"
        elseif not station then
            failureReason = "Mission gas refill station was not found"
        end

        local character, humanoid, root = characterParts(2)
        if not failureReason and not character then
            failureReason = "Character was unavailable for refill travel"
        end

        if not failureReason then
            setStatus(
                "REFILLING BLADES",
                string.format(
                    "%s • sets %s/3 • refill charges %s\nTeleporting to the exact gas-station interaction spots.",
                    tostring(reason or "0/3 detected"),
                    tostring(beforeSets),
                    tostring(beforeRefills)
                ),
                "warning"
            )
            RouteBody.Text = "Blade combat paused • exact station refill in progress • safe perch will be restored immediately."

            local get = exactBladeGET()
            if not get then
                failureReason = "ReplicatedStorage.Assets.Remotes.GET was not found"
            else
                for spotIndex, position in ipairs(missionStationSpots(station, character)) do
                    if not Runtime.ObjectiveCombatActive or not Runtime.AutoLaunch then
                        failureReason = "Combat controller stopped during refill"
                        break
                    end

                    local look = Vector3.new(station.Position.X, position.Y, station.Position.Z)
                    local stationCFrame = (look - position).Magnitude > 0.1
                        and CFrame.lookAt(position, look)
                        or CFrame.new(position)
                    local token = {Active = true}
                    holdCharacterAt(stationCFrame, token)
                    task.wait(0.12)

                    local accepted = false
                    for attempt = 1, FOREST_COMBAT.StationActionAttempts do
                        Runtime.ObjectiveCombatStationStatus = string.format(
                            "STATION SPOT %d • EXACT RELOAD %d/%d",
                            spotIndex,
                            attempt,
                            FOREST_COMBAT.StationActionAttempts
                        )
                        setStatus(
                            "REFILLING BLADES",
                            Runtime.ObjectiveCombatStationStatus .. "\nHolding the character at the station while the server accepts the restock.",
                            "warning"
                        )

                        local called = table.pack(pcall(function()
                            return get:InvokeServer("Attacks", "Reload", station)
                        end))
                        if called[1] and called[2] == true then
                            accepted = true
                        else
                            accepted = select(1, stationProgressAccepted(
                                beforeSets,
                                beforeRefills,
                                FOREST_COMBAT.StationActionPollSeconds
                            ))
                        end
                        if accepted then
                            break
                        end
                        task.wait(0.08)
                    end

                    if not accepted then
                        holdRefillKey()
                        accepted = select(1, stationProgressAccepted(
                            beforeSets,
                            beforeRefills,
                            FOREST_COMBAT.StationActionPollSeconds
                        ))
                    end

                    token.Active = false
                    if accepted then
                        success = true
                        break
                    end
                end
            end
        end


        restoreCombatPerch(returnCFrame, success and "Station accepted • verifying blades" or "Station attempt ended")
        Runtime.Transitioning = false

        if success then
            Runtime.ObjectiveCombatStationStatus = "VERIFYING 3/3 AT SAFE PERCH"
            local verifyDeadline = os.clock() + FOREST_COMBAT.StationVerifySeconds
            local restoredSets = nil
            repeat
                combatSafetyGuard()
                restoredSets = readBladeSetsCompact()
                if restoredSets ~= nil and restoredSets >= FOREST_COMBAT.StationTargetSets then
                    break
                end
                task.wait(0.08)
            until os.clock() >= verifyDeadline

            if restoredSets == nil or restoredSets < FOREST_COMBAT.StationTargetSets then
                success = false
                failureReason = "Station action was accepted but 3/3 did not replicate"
            else
                local fill = readBladeFill()
                if not bladeFillUsable(fill) then
                    Runtime.ObjectiveCombatStationStatus = "SINGLE-OWNER CURRENT BLADE RENEWAL"
                    local get = exactBladeGET()
                    local ready, consumed, liveSets, _, outcome = performSingleOwnerBladeRenew(
                        get,
                        restoredSets,
                        true
                    )
                    if ready then
                        clearBladeRenewPending(outcome)
                    elseif consumed then
                        Runtime.ObjectiveCombatRenewPending = true
                        Runtime.ObjectiveCombatRenewStartedAt = os.clock()
                        Runtime.ObjectiveCombatRenewBeforeSets = restoredSets
                        Runtime.ObjectiveCombatRenewLastOutcome = outcome
                        success = false
                        failureReason = string.format(
                            "One set was consumed (%s -> %s), but blade recovery did not replicate. Duplicate reload blocked.",
                            tostring(restoredSets),
                            tostring(liveSets)
                        )
                    else
                        success = false
                        failureReason = "3/3 restored, but the single renewal request was not accepted"
                    end
                else
                    clearBladeRenewPending("STATION_RESTOCK_CURRENT_BLADE_ALREADY_USABLE")
                end
            end
        end

        if success then
            Runtime.ObjectiveCombatStationFailures = 0
            Runtime.ObjectiveCombatStationRetryAt = 0
            Runtime.ObjectiveCombatStationStatus = "BLADES READY • COMBAT RESUMING"
            setStatus(
                "BLADES REFILLED",
                string.format(
                    "Station restock verified: %s/3 • current blade usable.\nReturning to %s.",
                    tostring(readBladeSetsCompact()),
                    tostring(Runtime.ObjectiveCombatPhase)
                ),
                "success"
            )
            RouteBody.Text = "Blade refill complete • Defend priority combat resumed from the 340-stud perch."
        else
            Runtime.ObjectiveCombatStationFailures += 1
            Runtime.ObjectiveCombatStationRetryAt = os.clock() + FOREST_COMBAT.StationRetryCooldown
            Runtime.ObjectiveCombatStationStatus = "REFILL FAILED • RETRY COOLDOWN"
            setStatus(
                "BLADE REFILL NOT VERIFIED",
                tostring(failureReason or "Unknown station refill failure")
                    .. string.format("\nRetry %d will be allowed after %.1fs.", Runtime.ObjectiveCombatStationFailures + 1, FOREST_COMBAT.StationRetryCooldown),
                "error"
            )
            RouteBody.Text = "Combat remains paused until the trusted blade HUD confirms usable blades."
        end

        Runtime.ObjectiveCombatStationBusy = false
        Runtime.ObjectiveCombatStationReturnCFrame = nil
    end)

    return true
end

local function mergeCombatTargets(first, second, center)
    local merged = {}
    for _, entry in ipairs(first or {}) do
        merged[#merged + 1] = entry
    end
    for _, entry in ipairs(second or {}) do
        merged[#merged + 1] = entry
    end
    table.sort(merged, function(a, b)
        local ad = tonumber(a.DistanceToObjective)
            or ((a.Part.Position - center).Magnitude)
        local bd = tonumber(b.DistanceToObjective)
            or ((b.Part.Position - center).Magnitude)
        return ad < bd
    end)
    return merged
end

local function visibleDefendObjectiveEvidence()
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton")) and object.Visible then
            local textValue = lower(object.Text)
            local mentionsSupplies = string.find(textValue, "missing supplies", 1, true)
                or string.find(textValue, "defend supplies", 1, true)
            local defendWording = string.find(textValue, "defend", 1, true)
                or string.find(textValue, "protect", 1, true)
                or string.find(textValue, "desperate search", 1, true)
            if mentionsSupplies and defendWording then
                return true, tostring(object.Text or "")
            end
        end
    end
    return false, nil
end

local function visibleDefendObjectiveComplete()
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton")) and object.Visible then
            local value = lower(object.Text):gsub("%s+", " ")
            local isDefendRow = string.find(value, "defend supplies", 1, true)
                or string.find(value, "defend missing supplies", 1, true)
            local completed = string.find(value, "[1/1]", 1, true)
                or string.find(value, "1/1", 1, true)
                or string.find(value, "complete", 1, true)
                or string.find(value, "completed", 1, true)
            if isDefendRow and completed then
                return true, tostring(object.Text or "")
            end
        end
    end
    return false, nil
end

local function runForestObjectiveCombat(zone, requestedMode, resultAction)
    if Runtime.ObjectiveCombatActive then
        return
    end
    local mode = tostring(requestedMode or "DEFEND") == "DEFEND" and "DEFEND" or "CLEANUP"
    Runtime.ObjectiveCombatActive = true
    Runtime.ObjectiveCombatStarted = true
    Runtime.ObjectiveCombatMode = mode
    Runtime.ObjectiveCombatPhase = mode == "DEFEND" and "DEFEND STARTING" or "MISSION CLEANUP STARTING"
    Runtime.ObjectiveCombatLastSpawnAt = os.clock()
    Runtime.ObjectiveCombatLastProgressAt = os.clock()
    Runtime.ObjectiveCombatNoTargetSince = nil
    Runtime.ObjectiveCombatBaseline = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatTagged = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatFirstPosition = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatLastGrabScanAt = 0
    Runtime.ObjectiveCombatWaveSeen = false
    Runtime.ObjectiveCombatWaveCount = 0
    Runtime.ObjectiveCombatWaveClearedAt = nil
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatRenewStartedAt = 0
    Runtime.ObjectiveCombatRenewBeforeSets = nil
    Runtime.ObjectiveCombatRenewLastOutcome = "IDLE"
    Runtime.ObjectiveCombatBladeReloadRetryAt = 0

    local center = zonePosition(zone)
    if typeof(center) ~= "Vector3" then
        setStatus("DEFENSE CENTER MISSING", "Supplies_Circle has no usable world position.", "error")
        stopObjectiveCombat("Fail-closed • defense center missing.")
        return
    end

    local folder = findTitansFolder()
    local folderDeadline = os.clock() + 12
    while Runtime.Alive and Runtime.AutoLaunch and not folder and os.clock() < folderDeadline do
        task.wait(0.20)
        folder = findTitansFolder()
    end
    if not folder then
        setStatus("TITANS FOLDER MISSING", "Workspace.Titans did not appear. Combat was not started.", "error")
        stopObjectiveCombat("Fail-closed • Titans folder missing.")
        return
    end

    local defendUiActive = mode == "DEFEND" and select(1, visibleDefendObjectiveEvidence()) == true
    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            Runtime.ObjectiveCombatBaseline[titan] = true
            Runtime.ObjectiveCombatFirstPosition[titan] = titanPosition(titan)


            if mode == "DEFEND" and (
                descriptorLooksObjective(titan)
                or (defendUiActive and distanceFromZone(titan, center) <= FOREST_COMBAT.ObjectiveRadius)
            ) then
                markObjectiveTitan(titan, center, false)
            end
        end
    end

    if mode == "DEFEND" then
        Runtime.ObjectiveCombatConnection = folder.ChildAdded:Connect(function(titan)
            task.defer(function()
                local deadline = os.clock() + 2.0
                repeat
                    if not Runtime.ObjectiveCombatActive or not titan.Parent then
                        return
                    end
                    if titanAimPart(titan) then
                        break
                    end
                    task.wait(0.05)
                until os.clock() >= deadline
                if titan.Parent then


                    markObjectiveTitan(titan, center, true)
                end
            end)
        end)
    end

    if mode == "DEFEND" then
        QuestRows[4].Text = "✓  Retrieve Missing Supplies  •  COMPLETE"
        QuestRows[4].TextColor3 = Color3.fromRGB(105, 222, 154)
        QuestRows[5].Text = ">  Defend Missing Supplies  •  OBJECTIVE COMBAT ACTIVE"
        QuestRows[5].TextColor3 = Color3.fromRGB(112, 181, 255)
    else
        QuestRows[4].Text = "✓  Retrieve Missing Supplies  •  3/3 DELIVERED"
        QuestRows[4].TextColor3 = Color3.fromRGB(105, 222, 154)
        QuestRows[5].Text = "—  Defend Missing Supplies  •  NEXT FOREST RUN"
        QuestRows[5].TextColor3 = Color3.fromRGB(126, 136, 159)
    end

    setLaunchReady(false, "COMBAT ACTIVE")
    moveCombatPerch(center, mode == "DEFEND" and "Supplies Defense" or "Forest Mission Cleanup")

    local safetyToken = {}
    Runtime.ObjectiveCombatSafetyToken = safetyToken
    task.spawn(function()
        while Runtime.Alive
            and Runtime.AutoLaunch
            and IS_FOREST
            and Runtime.ObjectiveCombatActive
            and Runtime.ObjectiveCombatSafetyToken == safetyToken do
            combatSafetyGuard()
            task.wait(FOREST_COMBAT.GuardDelay)
        end
    end)

    local nextSlashAt = 0
    local nextResultCheckAt = 0
    local nextQuestReadAt = 0
    local defendProgress = nil
    local defendStatus = nil
    local defendComplete = mode ~= "DEFEND"
    local resultDetectorArmed = false
    local resultPanelAbsentSince = nil

    while Runtime.Alive and Runtime.AutoLaunch and IS_FOREST and Runtime.ObjectiveCombatActive do
        local now = os.clock()
        if now >= nextResultCheckAt then
            nextResultCheckAt = now + 0.35
            local resultVisible, resultText = missionResultVisible()


            if not resultDetectorArmed then
                if resultVisible then
                    resultPanelAbsentSince = nil
                else
                    resultPanelAbsentSince = resultPanelAbsentSince or now
                    if now - resultPanelAbsentSince >= 1.50 then
                        resultDetectorArmed = true
                    end
                end
            elseif resultVisible then
                stopObjectiveCombat("Mission result detected • combat stopped.")
                Runtime.HandleStageResult(
                    resultAction or (mode == "DEFEND" and "leave" or "retry"),
                    mode == "DEFEND" and "DEFEND MISSING SUPPLIES COMPLETE"
                        or "RETRIEVE MISSING SUPPLIES COMPLETE"
                )
                break
            end
        end

        local character, humanoid = characterParts(0.2)
        if not character or not humanoid or humanoid.Health <= 0 then
            setStatus("CHARACTER DOWN", "Objective combat stopped because the character is not alive.", "error")
            stopObjectiveCombat("Character unavailable.")
            break
        end

        if Runtime.ObjectiveCombatStationBusy then
            task.wait(0.05)
            continue
        end

        if mode == "DEFEND" and now >= nextQuestReadAt then
            nextQuestReadAt = now + 0.65
            defendProgress, defendStatus = readLiveQuestProgress(5)
            local defendUiComplete = select(1, visibleDefendObjectiveComplete()) == true
            defendComplete = (tonumber(defendProgress) or 0) >= 1
                or defendStatus == "complete"
                or defendStatus == "reward_pending"
                or defendUiComplete
            if defendComplete then
                QuestRows[5].Text = "✓  Defend Missing Supplies  •  OBJECTIVE COMPLETE"
                QuestRows[5].TextColor3 = Color3.fromRGB(105, 222, 154)
            end
        end

        local objectiveTargets, normalTargets, total = collectCombatTargets(center)
        now = os.clock()


        local objectivePhase = mode == "DEFEND" and not defendComplete
        local chosen = objectivePhase
            and objectiveTargets
            or mergeCombatTargets(objectiveTargets, normalTargets, center)

        if #objectiveTargets > 0 and mode == "DEFEND" then
            Runtime.ObjectiveCombatLastSpawnAt = now
            Runtime.ObjectiveCombatWaveSeen = true
            Runtime.ObjectiveCombatWaveClearedAt = nil
        elseif objectivePhase and Runtime.ObjectiveCombatWaveSeen then
            Runtime.ObjectiveCombatWaveClearedAt = Runtime.ObjectiveCombatWaveClearedAt or now
        end

        if objectivePhase then
            if #objectiveTargets > 0 then
                Runtime.ObjectiveCombatPhase = "DEFEND OBJECTIVE WAVE"
            elseif Runtime.ObjectiveCombatWaveSeen then
                Runtime.ObjectiveCombatPhase = "OBJECTIVE WAVE CLEARED • WAITING"
            else
                Runtime.ObjectiveCombatPhase = "WAITING FOR OBJECTIVE TITANS"
            end
        elseif mode == "DEFEND" and defendComplete then
            Runtime.ObjectiveCombatPhase = "DEFEND COMPLETE • NORMAL MISSION CLEANUP"
        else
            Runtime.ObjectiveCombatPhase = "NORMAL MISSION CLEANUP"
        end

        local defendText = mode == "DEFEND" and defendProgress ~= nil
            and (" • Defend " .. tostring(defendProgress) .. "/1 " .. tostring(defendStatus or ""))
            or ""


        moveCombatPerch(center, Runtime.ObjectiveCombatPhase)
        combatSafetyGuard()

        if #chosen == 0 then
            if total <= 0 then
                Runtime.ObjectiveCombatNoTargetSince = Runtime.ObjectiveCombatNoTargetSince or now
            else
                Runtime.ObjectiveCombatNoTargetSince = nil
            end
            setStatus(
                Runtime.ObjectiveCombatPhase,
                string.format(
                    "Objective threats: %d • Normal Titans locked: %d • Total: %d%s\nObjective Titans tagged: %d • anti-grab snaps: %d • grab links cleared: %d",
                    #objectiveTargets,
                    #normalTargets,
                    total,
                    defendText,
                    Runtime.ObjectiveCombatWaveCount,
                    Runtime.ObjectiveCombatEmergencySnaps,
                    Runtime.ObjectiveCombatGrabBreaks
                ),
                objectivePhase and "info" or "success"
            )
            RouteBody.Text = objectivePhase
                and (Runtime.ObjectiveCombatWaveSeen
                    and "Objective wave cleared • ignoring normal map Titans and waiting for the next Defend wave."
                    or "Waiting for Titans spawned by Defend Supplies • normal map Titans are locked out.")
                or "Defend Supplies is confirmed complete • clearing remaining normal Aberrant Titans for rewards."
            task.wait(0.10)
        else
            Runtime.ObjectiveCombatNoTargetSince = nil
            if now >= nextSlashAt then
                local fired, registers, detail = fireExactBladeBatch(chosen)
                nextSlashAt = os.clock() + FOREST_COMBAT.SlashCooldown
                if fired then
                    setStatus(
                        Runtime.ObjectiveCombatPhase,
                        string.format(
                            "Objective threats: %d • Normal Titans: %d • Total: %d%s\nExact Blade batch: %d registers • %s • kills observed: %d • snaps: %d",
                            #objectiveTargets,
                            #normalTargets,
                            total,
                            defendText,
                            registers,
                            tostring(detail),
                            Runtime.ObjectiveCombatKills,
                            Runtime.ObjectiveCombatEmergencySnaps
                        ),
                        objectivePhase and "info" or "success"
                    )
                    RouteBody.Text = objectivePhase
                        and "Strict priority: objective-wave Titans only. Normal map Titans remain untouched."
                        or "Defend completion confirmed: clearing every remaining normal mission Titan."
                else
                    setStatus(
                        Runtime.ObjectiveCombatReloadBusy and "RELOADING BLADES" or "COMBAT WAIT",
                        tostring(detail) .. "\nFixed 340-stud anti-grab perch remains active.",
                        Runtime.ObjectiveCombatReloadBusy and "warning" or "info"
                    )
                end
            end
            task.wait(0.035)
        end
    end

    Runtime.ObjectiveCombatSafetyToken = nil
    if Runtime.ObjectiveCombatConnection then
        pcall(function()
            Runtime.ObjectiveCombatConnection:Disconnect()
        end)
        Runtime.ObjectiveCombatConnection = nil
    end
    Runtime.ObjectiveCombatActive = false
end

local function runForestSupplyController()
    if Runtime.SupplyControllerBusy then
        return
    end
    Runtime.SupplyControllerBusy = true
    Runtime.SupplyControllerStarted = true

    QuestHeader.Text = "SUPPLY CRATE MISSION PROGRESS"
    Launch.Visible = false
    RouteBody.Size = UDim2.new(1, -28, 0, 60)

    for index, row in pairs(QuestRows) do
        if index == 4 then
            row.Text = ">  Retrieve Missing Supplies  •  SUPPLY CONTROLLER ACTIVE"
            row.TextColor3 = Color3.fromRGB(112, 181, 255)
        else
            row.Text = "—  " .. QUESTS[index].Name .. "  •  NOT IN THIS RUN"
            row.TextColor3 = Color3.fromRGB(95, 104, 124)
        end
    end

    local difficulty = tostring(workspace:GetAttribute("Difficulty") or "")
    local objective = tostring(workspace:GetAttribute("Objective") or "")
    if difficulty ~= "" and difficulty ~= "Aberrant" then
        setStatus("WRONG DIFFICULTY", "Forest mission reported " .. difficulty .. ". This route requires Aberrant and will not move the player.", "error")
        RouteBody.Text = "Fail-closed • expected Giant Forest / Skirmish / Aberrant."
        Runtime.SupplyControllerBusy = false
        return
    end
    if objective ~= "" and objective ~= "Skirmish" then
        setStatus("WRONG OBJECTIVE", "Forest mission reported " .. objective .. ". This route requires Skirmish and will not move the player.", "error")
        RouteBody.Text = "Fail-closed • expected Giant Forest / Skirmish / Aberrant."
        Runtime.SupplyControllerBusy = false
        return
    end

    setStatus(
        "WAITING FOR SUPPLY QUEST OBJECTS",
        "Forest was detected. Random ThunderSpear_Supplies models and Supplies_Circle will be discovered automatically.",
        "info"
    )
    RouteBody.Text = "Giant Forest • Skirmish • Aberrant\nWaiting for native supply objects."

    local safetyToken = {}
    Runtime.SafetyToken = safetyToken
    task.spawn(function()
        while Runtime.Alive
            and Runtime.AutoLaunch
            and IS_FOREST
            and Runtime.SafetyToken == safetyToken do
            maintainSafePerch()
            task.wait(0.04)
        end
    end)

    local objectDeadline = os.clock() + 35
    local zone = nil
    local crates = {}
    repeat
        zone = findDepositZone()
        crates = listLooseSupplies()
        local liveProgress = zone and readLiveSupplyProgress() or nil
        local alreadyDelivered = zone and (
            (tonumber(liveProgress) or 0) >= 3
            or visibleDepositCount(zone) >= 3
        )
        if zone and (#crates > 0 or alreadyDelivered) then
            break
        end
        task.wait(0.25)
    until os.clock() >= objectDeadline or not Runtime.Alive or not Runtime.AutoLaunch

    if not zone then
        setStatus("SUPPLIES_CIRCLE NOT FOUND", "The Forest deposit model did not appear. No movement was attempted.", "error")
        RouteBody.Text = "Fail-closed • deposit zone missing."
        Runtime.SupplyControllerBusy = false
        return
    end
    if #crates == 0 then
        local retrieveProgress, retrieveStatus = readLiveQuestProgress(4)
        local defendProgress, defendStatus = readLiveQuestProgress(5)
        local defendUi = visibleDefendObjectiveEvidence()
        local defendActive = not Runtime.RetrieveCompletedThisSession
            and (
                defendStatus == "active"
                or defendStatus == "reward_pending"
                or ((tonumber(defendProgress) or 0) < 1 and defendUi == true)
            )

        if defendActive then
            setStatus(
                "DEFEND MISSING SUPPLIES ACTIVE",
                "This is the later Forest run. Starting objective-wave priority combat from a fixed 340-stud anti-grab perch.",
                "success"
            )
            RouteBody.Text = "Defend Missing Supplies • objective Titans first • normal mission Titans second."
            runForestObjectiveCombat(zone, "DEFEND", "leave")
        elseif (tonumber(retrieveProgress) or 0) >= 3
            or retrieveStatus == "complete"
            or retrieveStatus == "reward_pending"
            or visibleDepositCount(zone) >= 3 then
            setStatus(
                "RETRIEVE OBJECTIVE COMPLETE",
                "All crates are already supplied in this run. Defend begins on the next Forest launch, so SliceHub is finishing normal mission Titans for the gold reward.",
                "success"
            )
            RouteBody.Text = "Retrieve complete • normal mission cleanup • next Forest run starts Defend Supplies."
            runForestObjectiveCombat(zone, "CLEANUP", "retry")
        else
            setStatus("NO ACTIVE FOREST TS OBJECTS", "Supplies_Circle exists, but no loose crates or confirmed Defend state was found.", "warning")
            RouteBody.Text = "Fail-closed • Forest TS stage was not confirmed."
        end
        Runtime.SupplyControllerBusy = false
        return
    end

    local initialVisible = visibleDepositCount(zone)
    Runtime.DeliveredCount = math.max(Runtime.DeliveredCount, initialVisible)

    while Runtime.Alive and Runtime.AutoLaunch and IS_FOREST do
        zone = findDepositZone()
        if not zone then
            setStatus("DEPOSIT ZONE DISAPPEARED", "Supplies_Circle left Workspace. Safety perch is retained and the controller stopped.", "error")
            break
        end

        local liveProgress = readLiveSupplyProgress()
        local visible = visibleDepositCount(zone)
        Runtime.DeliveredCount = math.max(Runtime.DeliveredCount, visible, tonumber(liveProgress) or 0)

        crates = listLooseSupplies()
        if Runtime.DeliveredCount >= 3 or (#crates == 0 and visible >= 3) then
            Runtime.RetrieveCompletedThisSession = true
            setStatus(
                "ALL 3 SUPPLY CRATES DELIVERED",
                "Retrieve Missing Supplies is complete. Waiting briefly for Defend Missing Supplies to activate in this same Forest run.",
                "success"
            )
            RouteBody.Text = "Retrieve complete • waiting for Defend Missing Supplies."
            QuestRows[4].Text = "✓  Retrieve Missing Supplies  •  3/3 DELIVERED"
            QuestRows[4].TextColor3 = Color3.fromRGB(105, 222, 154)
            setLaunchReady(false, "WAITING FOR DEFEND")

            local defendDeadline = os.clock() + 12
            local defendStarted = false

            repeat
                local defendProgress, defendStatus = readLiveQuestProgress(5)
                local defendUi = visibleDefendObjectiveEvidence()
                local defendActive = defendStatus == "active"
                    or defendStatus == "reward_pending"
                    or ((tonumber(defendProgress) or 0) < 1 and defendUi == true)

                if defendActive then
                    defendStarted = true
                    setStatus(
                        "DEFEND MISSING SUPPLIES ACTIVE",
                        "Same-run Defend objective detected. Starting objective-first defense now.",
                        "success"
                    )
                    RouteBody.Text = "Defend Missing Supplies • same Forest run • objective Titans first."
                    runForestObjectiveCombat(zone, "DEFEND", "leave")
                    break
                end

                maintainSafePerch()
                task.wait(0.20)
            until os.clock() >= defendDeadline
                or not Runtime.Alive
                or not Runtime.AutoLaunch

            if defendStarted then
                Runtime.SupplyControllerBusy = false
                return
            end

            setStatus(
                "DEFEND DID NOT START YET",
                "Same-run Defend was not confirmed after 12 seconds. Falling back to the proven finish + Retry path.",
                "warning"
            )
            RouteBody.Text = "Retrieve complete • fallback cleanup • retry Forest for Defend."
            runForestObjectiveCombat(zone, "CLEANUP", "retry")
            break
        end

        local crate = nil
        for _, candidate in ipairs(crates) do
            local number = supplyNumber(candidate)
            if number and Runtime.CompletedCrates[number] ~= true then
                crate = candidate
                break
            end
        end

        if not crate then
            setStatus(
                "WAITING FOR REMAINING SUPPLY CRATE",
                "Delivered evidence: " .. tostring(Runtime.DeliveredCount) .. "/3. No unprocessed loose crate is currently in Workspace.",
                "warning"
            )
            maintainSafePerch()
            task.wait(0.35)
        else
            local number = supplyNumber(crate) or 0
            local crateHitbox = hitboxFor(crate)
            local depositHitbox = hitboxFor(zone)
            if not crateHitbox or not depositHitbox then
                setStatus("SUPPLY HITBOX MISSING", "Crate " .. tostring(number) .. " or Supplies_Circle has no native Hitbox. No blind teleport was attempted.", "error")
                break
            end

            local _, _, travelError = createSafePlatform(crateHitbox, "Crate" .. tostring(number))
            if travelError then
                setStatus("SAFE TRAVEL FAILED", tostring(travelError), "error")
                break
            end

            setStatus(
                "PICKING UP SUPPLY CRATE " .. tostring(number),
                "Random spawn detected at runtime. Testing native touch from a 145-stud safety perch, then a brief physical dip only if needed.",
                "info"
            )
            RouteBody.Text = "Giant Forest • Aberrant\nPickup: ThunderSpear_Supplies" .. tostring(number)
            setLaunchReady(false, "PICKING UP " .. tostring(number))

            local box = crate:FindFirstChild("Box", true)
            local pickupOk, pickupReason = briefNativeTouch(crateHitbox, function()
                return waitForPickup(crate, box, 0.05)
            end, "Supply crate pickup")

            if not pickupOk then
                setStatus("PICKUP NOT VERIFIED", tostring(pickupReason) .. "\nController stopped fail-closed; safety perch retained.", "error")
                RouteBody.Text = "No repeated teleport loop was started."
                break
            end

            Runtime.Carrying = true
            setStatus("CRATE PICKUP VERIFIED", "Native carried-crate state was detected for supply crate " .. tostring(number) .. ". Moving directly above Supplies_Circle.", "success")

            local _, _, depositTravelError = createSafePlatform(depositHitbox, "Deposit")
            if depositTravelError then
                setStatus("DEPOSIT TRAVEL FAILED", tostring(depositTravelError), "error")
                break
            end

            local baselineVisible = visibleDepositCount(zone)
            local baselineProgress = readLiveSupplyProgress()
            local baselineCarry = carryingEvidence()
            setStatus(
                "DELIVERING SUPPLY CRATE " .. tostring(number),
                "Supplies_Circle found. Touching its direct native Hitbox; delivery is verified by carried-state release, a destination slot, or quest progress.",
                "info"
            )
            RouteBody.Text = "Giant Forest • Aberrant\nDeposit: Supplies_Circle"
            setLaunchReady(false, "DELIVERING " .. tostring(number))

            local depositOk, depositReason = briefNativeTouch(depositHitbox, function()
                local ok = waitForDeposit(zone, baselineVisible, baselineProgress, baselineCarry, 0.05)
                return ok == true
            end, "Supply crate deposit")

            if depositOk then
                local verified, newVisible, newProgress = waitForDeposit(zone, baselineVisible, baselineProgress, baselineCarry, 3.0)
                if not verified then
                    depositOk = false
                    depositReason = "The deposit touch fired, but neither destination slots nor quest progress changed."
                else
                    Runtime.CompletedCrates[number] = true
                    Runtime.Carrying = false
                    Runtime.DeliveredCount = math.max(
                        Runtime.DeliveredCount + 1,
                        tonumber(newVisible) or 0,
                        tonumber(newProgress) or 0
                    )
                    QuestRows[4].Text = "✓  Supply Crate " .. tostring(number) .. "  •  DELIVERY VERIFIED (" .. tostring(math.min(3, Runtime.DeliveredCount)) .. "/3)"
                    QuestRows[4].TextColor3 = Color3.fromRGB(105, 222, 154)
                    setStatus(
                        "DELIVERY VERIFIED",
                        "Supply crate " .. tostring(number) .. " was accepted. Rescanning Workspace for the remaining random crate spawns.",
                        "success"
                    )
                    task.wait(0.45)
                end
            end

            if not depositOk then
                setStatus("DEPOSIT NOT VERIFIED", tostring(depositReason) .. "\nController stopped fail-closed; the high safety perch is retained.", "error")
                RouteBody.Text = "No additional crates will be touched while delivery state is uncertain."
                break
            end
        end
    end

    if not Runtime.AutoLaunch or not Runtime.Alive then
        destroySafePlatform()
    else
        maintainSafePerch()
    end
    if Runtime.SafetyToken == safetyToken then
        Runtime.SafetyToken = nil
    end
    Runtime.SupplyControllerBusy = false
end


local ESCORT_COMBAT = {
    ThreatRadius = 170,
    SpawnRadius = 190,
    InitialWaitSeconds = 16,
    MissingFailSeconds = 5,
    LoopDelay = 0.055,
    PerchSnapDistance = 3.5,
}

local function findEscortModel()
    local u = workspace:FindFirstChild("Unclimbable")
    local o = u and u:FindFirstChild("Objective")
    local e = o and o:FindFirstChild("Escort")
    return e and e:IsA("Model") and e or nil
end

local function escortAnchor(escort)
    if not escort then return nil end
    local collider = escort:FindFirstChild("Collider")
    if collider and collider:IsA("BasePart") then return collider end
    local cart = escort:FindFirstChild("Cart")
    local main = cart and cart:FindFirstChild("Main")
    if main and main:IsA("BasePart") then return main end
    if escort.PrimaryPart and escort.PrimaryPart:IsA("BasePart") then
        return escort.PrimaryPart
    end
    return escort:FindFirstChildWhichIsA("BasePart", true)
end

local function escortCenter(escort)
    local part = escortAnchor(escort)
    return part and part.Position or nil
end

local function escortHealth(escort)
    if not escort then return nil end
    local value = escort:FindFirstChild("Health")
    if value and (value:IsA("NumberValue") or value:IsA("IntValue")) then
        return tonumber(value.Value)
    end
    local ok, attribute = pcall(function() return escort:GetAttribute("Health") end)
    return ok and tonumber(attribute) or nil
end

local function visibleEscortProgress()
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton"))
            and guiObjectActuallyVisible(object) then
            local value = lower(object.Text):gsub("%s+", " ")
            if string.find(value, "escort supplies", 1, true)
                or string.find(value, "escort supply", 1, true) then
                local current, required = string.match(value, "%[(%d+)%s*/%s*(%d+)%]")
                if not current then
                    current, required = string.match(value, "(%d+)%s*/%s*(%d+)")
                end
                return tonumber(current), tonumber(required), tostring(object.Text or "")
            end
        end
    end
    return nil, nil, nil
end

local function escortCompleteEvidence()
    local current, required, textValue = visibleEscortProgress()
    if current and required and required > 0 and current >= required then
        return true, "HUD " .. tostring(textValue)
    end
    local liveCurrent, liveStatus = readLiveQuestProgress(2)
    if (tonumber(liveCurrent) or 0) >= 1
        or liveStatus == "complete"
        or liveStatus == "reward_pending" then
        return true, "Quest data " .. tostring(liveCurrent or 1) .. "/1"
    end
    return false, nil
end

local function updateEscortPerch(center)
    if typeof(center) ~= "Vector3" then return false end
    local character, humanoid, root = characterParts(1)
    if not character then return false end

    local platform = Runtime.SafePlatform
    if not platform or not platform.Parent then
        platform = Instance.new("Part")
        platform.Name = "SliceHub_TS_EscortMovingSafeFloor"
        platform.Anchored = true
        platform.CanCollide = true
        platform.CanTouch = false
        platform.CanQuery = false
        platform.Transparency = 1
        platform.Size = Vector3.new(
            FOREST_COMBAT.PlatformSize,
            1,
            FOREST_COMBAT.PlatformSize
        )
        platform.Parent = workspace
        Runtime.SafePlatform = platform
        Runtime.SafePlatforms[#Runtime.SafePlatforms + 1] = platform
    end

    local standOffset = (tonumber(humanoid.HipHeight) or 2)
        + root.Size.Y / 2
        + platform.Size.Y / 2
    local desired = center + Vector3.new(0, FOREST_COMBAT.SafeHeight, 0)
    platform.CFrame = CFrame.new(desired - Vector3.new(0, standOffset, 0))
    Runtime.SafeCFrame = CFrame.lookAt(desired, center)
    Runtime.SafeTarget = "Moving Escort cart"
    Runtime.EscortLastCenter = center

    if not Runtime.ObjectiveCombatStationBusy then
        local displaced = (root.Position - desired).Magnitude
            >= ESCORT_COMBAT.PerchSnapDistance
        if displaced or humanoid.Sit or humanoid.PlatformStand then
            Runtime.Transitioning = true
            pcall(function()
                character:PivotTo(Runtime.SafeCFrame)
                root.CFrame = Runtime.SafeCFrame
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                humanoid.Sit = false
                humanoid.PlatformStand = false
                humanoid:ChangeState(Enum.HumanoidStateType.Running)
            end)
            Runtime.Transitioning = false
        end
    end
    return true
end

local function markEscortThreat(titan, center)
    if not titan or not titan.Parent or typeof(center) ~= "Vector3" then
        return false
    end
    local position = titanPosition(titan)
    if position then
        Runtime.ObjectiveCombatFirstPosition[titan] =
            Runtime.ObjectiveCombatFirstPosition[titan] or position
    end
    local first = Runtime.ObjectiveCombatFirstPosition[titan]
    local closeAtSpawn = typeof(first) == "Vector3"
        and (first - center).Magnitude <= ESCORT_COMBAT.SpawnRadius
    local closeNow = typeof(position) == "Vector3"
        and (position - center).Magnitude <= ESCORT_COMBAT.ThreatRadius
    local marked = descriptorLooksObjective(titan) or closeAtSpawn or closeNow
    if marked then
        if Runtime.ObjectiveCombatTagged[titan] ~= true then
            Runtime.ObjectiveCombatWaveCount += 1
        end
        Runtime.ObjectiveCombatTagged[titan] = true
        Runtime.ObjectiveCombatWaveSeen = true
        Runtime.ObjectiveCombatLastSpawnAt = os.clock()
    end
    return marked
end

local function collectEscortTargets(center, completed)
    local threats, normal = {}, {}
    local total = 0
    local folder = findTitansFolder()
    if not folder then return threats, normal, total end

    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            local nape = exactTitanNape(titan)
            if nape then
                total += 1
                local distance = distanceFromZone(titan, center)
                if not completed then
                    markEscortThreat(titan, center)
                end
                local entry = {
                    Titan = titan,
                    Part = nape,
                    DistanceToObjective = distance,
                }
                if Runtime.ObjectiveCombatTagged[titan] == true
                    or descriptorLooksObjective(titan) then
                    threats[#threats + 1] = entry
                else
                    normal[#normal + 1] = entry
                end
            end
        end
    end

    table.sort(threats, function(a, b)
        return a.DistanceToObjective < b.DistanceToObjective
    end)
    table.sort(normal, function(a, b)
        return a.DistanceToObjective < b.DistanceToObjective
    end)
    return threats, normal, total
end

local function runOutskirtsEscortController()
    if Runtime.EscortControllerBusy or Runtime.ObjectiveCombatActive then return end

    Runtime.EscortControllerBusy = true
    Runtime.EscortControllerStarted = true
    Runtime.ObjectiveCombatActive = true
    Runtime.ObjectiveCombatStarted = true
    Runtime.ObjectiveCombatMode = "ESCORT"
    Runtime.ObjectiveCombatPhase = "WAITING FOR ESCORT CART"
    Runtime.ObjectiveCombatKills = 0
    Runtime.ObjectiveCombatRegisters = 0
    Runtime.ObjectiveCombatBaseline = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatTagged = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatFirstPosition = setmetatable({}, {__mode = "k"})
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatBladeReloadRetryAt = 0
    Runtime.ObjectiveCombatLastGrabScanAt = 0
    Runtime.EscortComplete = false
    Runtime.EscortMissingSince = nil

    QuestHeader.Text = "ESCORT MISSION PROGRESS"
    QuestRows[1].Text = "✓  Watch Towers  •  COMPLETE"
    QuestRows[1].TextColor3 = Color3.fromRGB(105, 222, 154)
    QuestRows[2].Text = ">  Escort  •  MOVING CART CONTROLLER ACTIVE"
    QuestRows[2].TextColor3 = Color3.fromRGB(103, 176, 255)
    QuestRows[3].Text = "—  Ice Burst Stones  •  NOT IN THIS RUN"
    QuestRows[4].Text = "—  Retrieve Missing Supplies  •  NOT IN THIS OUTSKIRTS RUN"
    QuestRows[5].Text = "—  Defend Missing Supplies  •  NOT IN THIS OUTSKIRTS RUN"
    setLaunchReady(false, "ESCORT ACTIVE")

    local escort
    local deadline = os.clock() + ESCORT_COMBAT.InitialWaitSeconds
    repeat
        escort = findEscortModel()
        if escort then break end
        task.wait(0.15)
    until not Runtime.Alive
        or not Runtime.AutoLaunch
        or not IS_OUTSKIRTS
        or os.clock() >= deadline

    if not escort then
        setStatus(
            "ESCORT OBJECTIVE NOT FOUND",
            "Workspace.Unclimbable.Objective.Escort did not appear. Normal map Titans were not attacked.",
            "error"
        )
        RouteBody.Text = "Fail-closed • Escort model missing."
        stopObjectiveCombat("Escort model missing.")
        Runtime.EscortControllerBusy = false
        return
    end

    local folder = findTitansFolder()
    local folderDeadline = os.clock() + 12
    while Runtime.Alive and Runtime.AutoLaunch and not folder
        and os.clock() < folderDeadline do
        task.wait(0.2)
        folder = findTitansFolder()
    end
    if not folder then
        setStatus("TITANS FOLDER MISSING", "Workspace.Titans did not appear.", "error")
        stopObjectiveCombat("Escort Titans folder missing.")
        Runtime.EscortControllerBusy = false
        return
    end

    local center = escortCenter(escort)
    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            Runtime.ObjectiveCombatFirstPosition[titan] = titanPosition(titan)
            if typeof(center) == "Vector3" then markEscortThreat(titan, center) end
        end
    end

    Runtime.ObjectiveCombatConnection = folder.ChildAdded:Connect(function(titan)
        task.defer(function()
            local waitDeadline = os.clock() + 2
            repeat
                if not Runtime.ObjectiveCombatActive or not titan.Parent then return end
                if titanAimPart(titan) then break end
                task.wait(0.05)
            until os.clock() >= waitDeadline
            local liveCenter = escortCenter(findEscortModel()) or Runtime.EscortLastCenter
            if typeof(liveCenter) == "Vector3" then
                markEscortThreat(titan, liveCenter)
            end
        end)
    end)

    setStatus(
        "ESCORT CONTROLLER ACTIVE",
        "Following the native moving cart from 340 studs above. Horse speed and route are unchanged.",
        "info"
    )
    RouteBody.Text =
        "Outskirts • Skirmish • Aberrant\nCart threats first • normal map Titans locked until 1/1."

    local resultArmed = false
    local absentSince

    while Runtime.Alive and Runtime.AutoLaunch and IS_OUTSKIRTS
        and Runtime.ObjectiveCombatActive do

        local now = os.clock()
        local resultVisible, resultText = missionResultVisible()
        if not resultArmed then
            if resultVisible then
                absentSince = nil
            else
                absentSince = absentSince or now
                if now - absentSince >= 1.5 then resultArmed = true end
            end
        elseif resultVisible then
            stopObjectiveCombat("Mission result detected.")
            Runtime.HandleStageResult("leave", "ESCORT COMPLETE")
            break
        end

        local character, humanoid = characterParts(0.1)
        if not character or not humanoid or humanoid.Health <= 0 then
            setStatus("CHARACTER DOWN", "Escort combat stopped.", "error")
            stopObjectiveCombat("Character unavailable.")
            break
        end

        escort = findEscortModel()
        if select(1, escortCompleteEvidence()) then
            Runtime.EscortComplete = true
        end

        if escort then
            Runtime.EscortMissingSince = nil
            center = escortCenter(escort) or Runtime.EscortLastCenter
            Runtime.EscortLastHealth = escortHealth(escort)
                or Runtime.EscortLastHealth
            if Runtime.EscortLastHealth ~= nil
                and Runtime.EscortLastHealth <= 0
                and not Runtime.EscortComplete then
                setStatus("ESCORT FAILED", "The native Escort Health reached 0.", "error")
                stopObjectiveCombat("Escort destroyed.")
                break
            end
        else
            Runtime.EscortMissingSince = Runtime.EscortMissingSince or now
            center = Runtime.EscortLastCenter
            if not Runtime.EscortComplete
                and now - Runtime.EscortMissingSince
                    >= ESCORT_COMBAT.MissingFailSeconds then
                setStatus(
                    "ESCORT MODEL DISAPPEARED",
                    "Escort success was not verified. Normal map Titans remain locked.",
                    "error"
                )
                stopObjectiveCombat("Escort disappeared before completion.")
                break
            end
        end

        if typeof(center) ~= "Vector3" then
            setStatus("ESCORT POSITION MISSING", "Collider/Main position unavailable.", "error")
            stopObjectiveCombat("Escort position missing.")
            break
        end

        if not Runtime.ObjectiveCombatStationBusy then
            updateEscortPerch(center)
            combatSafetyGuard()
        end

        local threats, normal, total =
            collectEscortTargets(center, Runtime.EscortComplete)
        local chosen
        if Runtime.EscortComplete then
            Runtime.ObjectiveCombatPhase =
                "ESCORT COMPLETE • NORMAL MISSION CLEANUP"
            chosen = mergeCombatTargets(threats, normal, center)
            QuestRows[2].Text = "✓  Escort  •  1/1 COMPLETE"
            QuestRows[2].TextColor3 = Color3.fromRGB(105, 222, 154)
        elseif #threats > 0 then
            Runtime.ObjectiveCombatPhase = "ESCORT THREATS"
            chosen = threats
        else
            Runtime.ObjectiveCombatPhase = "WAITING FOR CART ATTACKERS"
            chosen = {}
        end

        local current, required = visibleEscortProgress()
        local healthText = Runtime.EscortLastHealth ~= nil
            and string.format("%.1f", Runtime.EscortLastHealth)
            or "?"

        if #chosen == 0 then
            setStatus(
                Runtime.ObjectiveCombatPhase,
                string.format(
                    "Cart health %s • Escort %s/%s • threats %d • normal locked %d • total %d\nHorse speed untouched • safe snaps %d",
                    healthText,
                    tostring(current or (Runtime.EscortComplete and 1 or 0)),
                    tostring(required or 1),
                    #threats,
                    #normal,
                    total,
                    Runtime.ObjectiveCombatEmergencySnaps
                ),
                Runtime.EscortComplete and "success" or "info"
            )
            RouteBody.Text = Runtime.EscortComplete
                and "Escort 1/1 confirmed • clearing remaining normal Outskirts Titans."
                or "Waiting beside the moving cart • distant normal map Titans untouched."
            task.wait(ESCORT_COMBAT.LoopDelay)
        else
            local fired, registers, detail = fireExactBladeBatch(chosen)
            if fired then
                setStatus(
                    Runtime.ObjectiveCombatPhase,
                    string.format(
                        "Cart health %s • threats %d • normal %d • total %d\nBlade registers %d • %s • kills %d",
                        healthText, #threats, #normal, total,
                        registers, tostring(detail),
                        Runtime.ObjectiveCombatKills
                    ),
                    "success"
                )
                RouteBody.Text = Runtime.EscortComplete
                    and "Escort complete • normal Outskirts cleanup unlocked."
                    or "Strict priority • Titans threatening the cart only."
                task.wait(FOREST_COMBAT.SlashCooldown)
            else
                setStatus(
                    Runtime.ObjectiveCombatStationBusy
                        and "REFILLING BLADES"
                        or "ESCORT COMBAT WAIT",
                    tostring(detail)
                        .. "\nMoving 340-stud anti-grab perch remains active.",
                    Runtime.ObjectiveCombatStationBusy
                        and "warning"
                        or "info"
                )
                task.wait(0.08)
            end
        end
    end

    Runtime.EscortControllerBusy = false
    if not Runtime.AutoLaunch or not Runtime.Alive then
        destroySafePlatform()
    end
end


Runtime.UtgardConfig = {
    InitialWaitSeconds = 10,
    LoopDelay = 0.08,
    ResultActionDelay = 0.18,
    NoTargetResultWait = 1.8,
    RequiredRuns = 3,
    TransitionAttempts = 4,
    TransitionRetryDelay = 0.22,
    TransitionVerifySeconds = 1.45,
    LobbyVerifySeconds = 4.25,
}

Runtime.CollectAllUtgardTargets = function()
    local targets = {}
    local folder = findTitansFolder()
    if not folder then return targets, 0 end

    local character = Player.Character
    local root = character
        and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
    local origin = root and root.Position or Vector3.zero

    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            local nape = exactTitanNape(titan)
            if nape then
                targets[#targets + 1] = {
                    Titan = titan,
                    Part = nape,
                    Variant = false,
                    DistanceToObjective = (nape.Position - origin).Magnitude,
                }
            end
        end
    end

    table.sort(targets, function(a, b)
        return a.DistanceToObjective < b.DistanceToObjective
    end)

    return targets, #targets
end

Runtime.resultTextOf = function(object)
    if object and (object:IsA("TextLabel")
        or object:IsA("TextButton")
        or object:IsA("TextBox")) then
        return tostring(object.Text or "")
    end
    return ""
end

Runtime.resultButtonAncestor = function(object)
    local node = object
    for _ = 1, 8 do
        if not node or node == PlayerGui then break end
        if node:IsA("GuiButton") then return node end
        node = node.Parent
    end
    return nil
end

Runtime.FindMissionResultRoot = function()
    for _, object in ipairs(PlayerGui:GetDescendants()) do
        if Screen and object:IsDescendantOf(Screen) then
            continue
        end
        if (object:IsA("TextLabel") or object:IsA("TextButton"))
            and guiObjectActuallyVisible(object) then
            local value = lower(Runtime.resultTextOf(object))
            if string.find(value, "mission completed", 1, true)
                or string.find(value, "mission failed", 1, true)
                or string.find(value, "mission complete", 1, true) then
                local node = object
                for _ = 1, 10 do
                    if not node or node == PlayerGui then break end
                    if node:IsA("GuiObject") then
                        local hasStats, hasResultAction = false, false
                        for _, child in ipairs(node:GetDescendants()) do
                            if (child:IsA("TextLabel") or child:IsA("TextButton"))
                                and guiObjectActuallyVisible(child) then
                                local childText = lower(Runtime.resultTextOf(child))
                                if string.find(childText, "stats", 1, true) then
                                    hasStats = true
                                end
                                if string.find(childText, "retry", 1, true)
                                    or string.find(childText, "leave", 1, true)
                                    or string.find(childText, "obtained", 1, true) then
                                    hasResultAction = true
                                end
                            end
                        end
                        if hasStats and hasResultAction then return node end
                    end
                    node = node.Parent
                end
                return object.Parent
            end
        end
    end
    return nil
end

Runtime.FindVisibleResultButton = function(needle, resultRoot)
    needle = lower(needle)
    local root = resultRoot or Runtime.FindMissionResultRoot() or PlayerGui
    local best, bestY = nil, -math.huge

    local function scan(scanRoot)
        if not scanRoot then return end
        local objects = {scanRoot}
        for _, object in ipairs(scanRoot:GetDescendants()) do
            objects[#objects + 1] = object
        end

        for _, object in ipairs(objects) do
            if Screen and object:IsDescendantOf(Screen) then
                continue
            end
            if (object:IsA("TextLabel") or object:IsA("TextButton"))
                and guiObjectActuallyVisible(object) then
                local value = lower(Runtime.resultTextOf(object))
                if string.find(value, needle, 1, true) then
                    local candidate = Runtime.resultButtonAncestor(object)
                        or (object:IsA("GuiButton") and object or nil)
                    if candidate and candidate:IsA("GuiObject")
                        and candidate.AbsolutePosition.Y >= bestY then
                        best = candidate
                        bestY = candidate.AbsolutePosition.Y
                        if value == needle then return end
                    end
                end
            end
        end
    end

    scan(root)
    if not best and root ~= PlayerGui then scan(PlayerGui) end
    return best
end

Runtime.closeRobloxMenuForTransition = function()
    local menuOpen = false
    pcall(function() menuOpen = GuiService.MenuIsOpen == true end)
    if not menuOpen then return true end

    pcall(function()
        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Escape, false, game)
        task.wait(0.035)
        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Escape, false, game)
    end)

    local deadline = os.clock() + 0.80
    while os.clock() < deadline do
        local stillOpen = false
        pcall(function() stillOpen = GuiService.MenuIsOpen == true end)
        if not stillOpen then return true end
        task.wait(0.04)
    end
    return false
end

Runtime.WaitForResultTransition = function(initialRoot, initialButton, timeout)
    local initialText = lower(Runtime.resultTextOf(initialButton))
    local deadline = os.clock() + math.max(0.1, tonumber(timeout) or 1.2)

    repeat
        if Runtime.TeleportTransitionStarted or not Player.Parent then
            return true, "teleport"
        end
        if Runtime.TeleportTransitionFailure then
            return false, Runtime.TeleportTransitionFailure
        end

        local currentRoot = Runtime.FindMissionResultRoot()
        if currentRoot == nil or currentRoot ~= initialRoot then
            return true, "result panel changed"
        end
        if initialButton and not initialButton.Parent then
            return true, "button removed"
        end

        if initialButton and initialButton.Parent then
            local currentText = lower(Runtime.resultTextOf(initialButton))
            if currentText ~= "" and currentText ~= initialText then
                if string.find(currentText, "start", 1, true)
                    or string.find(currentText, "load", 1, true)
                    or string.find(currentText, "join", 1, true)
                    or string.find(currentText, "teleport", 1, true)
                    or not string.find(currentText, "retry", 1, true) then
                    return true, "button state changed"
                end
            end
        end

        if currentRoot then
            for _, child in ipairs(currentRoot:GetDescendants()) do
                if (child:IsA("TextLabel") or child:IsA("TextButton"))
                    and guiObjectActuallyVisible(child) then
                    local value = lower(Runtime.resultTextOf(child))
                    if string.find(value, "starting", 1, true)
                        or string.find(value, "loading", 1, true)
                        or string.find(value, "joining", 1, true)
                        or string.find(value, "teleporting", 1, true) then
                        return true, "visible transition state"
                    end
                end
            end
        end
        task.wait(0.055)
    until os.clock() >= deadline

    return false, "transition was not observed"
end

Runtime.connectionCallback = function(signal, activatedSignal, waitTransition)
    local getConnections = Environment.getconnections
    if type(getConnections) ~= "function"
        and type(getconnections) == "function" then
        getConnections = getconnections
    end
    if type(getConnections) ~= "function" then return false end

    local ok, list = pcall(getConnections, signal)
    if not ok or type(list) ~= "table" then return false end

    for _, connection in ipairs(list) do
        local enabled = true
        pcall(function()
            if connection.Enabled == false then enabled = false end
        end)
        if enabled then
            local fired = false
            local okFire, fireMember = pcall(function()
                return connection.Fire
            end)
            if okFire and type(fireMember) == "function" then
                fired = (activatedSignal
                    and pcall(fireMember, connection, nil, 1)
                    or pcall(fireMember, connection)) == true
            end

            if not fired then
                local okFn, callback = pcall(function()
                    return connection.Function
                end)
                if okFn and type(callback) == "function" then
                    fired = (activatedSignal
                        and pcall(callback, nil, 1)
                        or pcall(callback)) == true
                end
            end

            if fired and waitTransition(0.38) then return true end
        end
    end
    return false
end

Runtime.ActivateResultAction = function(actionName)
    pcall(Runtime.QueueMainBuildForTeleport)
    if Runtime.ResultTransitionBusy then
        return false, "another result transition is running"
    end

    Runtime.ResultTransitionBusy = true
    Runtime.ResultTransitionLastError = nil
    Runtime.TeleportTransitionStarted = false
    Runtime.TeleportTransitionFailure = nil

    local action = lower(actionName)
    local attempts = math.max(
        1, tonumber(Runtime.UtgardConfig.TransitionAttempts) or 4
    )

    local function finish(ok, detail)
        Runtime.ResultTransitionBusy = false
        Runtime.ResultTransitionLastMethod = ok
            and tostring(detail or "accepted")
            or "FAILED"
        Runtime.ResultTransitionLastError = ok and nil or tostring(detail)
        return ok, detail
    end

    for attempt = 1, attempts do
        Runtime.ResultTransitionAttempts = attempt
        local resultRoot = Runtime.FindMissionResultRoot()
        local button = Runtime.FindVisibleResultButton(action, resultRoot)
        if not resultRoot or not button then
            task.wait(Runtime.UtgardConfig.TransitionRetryDelay)
            continue
        end

        pcall(function()
            local focused = UserInputService:GetFocusedTextBox()
            if focused then focused:ReleaseFocus(false) end
        end)
        Runtime.closeRobloxMenuForTransition()

        local oldEnabled = Screen and Screen.Enabled
        if Screen then Screen.Enabled = false end
        task.wait(0.035)

        local target = button
        local pos = button.AbsolutePosition
        local size = button.AbsoluteSize
        local x = math.floor(pos.X + size.X / 2 + 0.5)
        local y = math.floor(pos.Y + size.Y / 2 + 0.5)
        pcall(function()
            for _, candidate in ipairs(PlayerGui:GetGuiObjectsAtPosition(x, y)) do
                if not Screen or not candidate:IsDescendantOf(Screen) then
                    local ancestor = Runtime.resultButtonAncestor(candidate)
                    if ancestor then
                        target = ancestor
                        break
                    end
                end
            end
        end)

        local function waitTransition(customTimeout)
            local ok = Runtime.WaitForResultTransition(
                resultRoot,
                target,
                customTimeout or Runtime.UtgardConfig.TransitionVerifySeconds
            )
            return ok == true
        end

        if target:IsA("GuiButton") then
            pcall(function() target:Activate() end)
            local fire = Environment.firesignal or firesignal
            if type(fire) == "function" then
                pcall(function() fire(target.Activated, nil, 1) end)
                pcall(function() fire(target.MouseButton1Click) end)
            end
            if waitTransition(0.30) then
                if Screen then Screen.Enabled = oldEnabled ~= false end
                return finish(true, "Activate/firesignal")
            end

            if Runtime.connectionCallback(target.Activated, true, waitTransition)
                or Runtime.connectionCallback(target.MouseButton1Click, false, waitTransition) then
                if Screen then Screen.Enabled = oldEnabled ~= false end
                return finish(true, "direct callback")
            end
        end

        local oldSelected = nil
        pcall(function()
            oldSelected = GuiService.SelectedObject
            GuiService.SelectedObject = target
        end)
        pcall(function()
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
            task.wait(0.055)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
        end)
        if waitTransition(0.48) then
            if Screen then Screen.Enabled = oldEnabled ~= false end
            return finish(true, "keyboard")
        end
        pcall(function() GuiService.SelectedObject = oldSelected end)

        Runtime.closeRobloxMenuForTransition()
        local inset = Vector2.new(0, 0)
        pcall(function() inset = GuiService:GetGuiInset() end)
        pcall(function()
            VirtualInputManager:SendMouseMoveEvent(x + inset.X, y + inset.Y, game)
            task.wait(0.035)
            VirtualInputManager:SendMouseButtonEvent(
                x + inset.X, y + inset.Y, 0, true, game, 0
            )
            task.wait(0.065)
            VirtualInputManager:SendMouseButtonEvent(
                x + inset.X, y + inset.Y, 0, false, game, 0
            )
        end)

        local transitioned, detail = Runtime.WaitForResultTransition(
            resultRoot,
            target,
            Runtime.UtgardConfig.TransitionVerifySeconds
        )
        if Screen then Screen.Enabled = oldEnabled ~= false end
        if transitioned then
            return finish(true, "protected mouse: " .. tostring(detail))
        end

        task.wait(Runtime.UtgardConfig.TransitionRetryDelay)
    end

    return finish(false, action .. " was not accepted after "
        .. tostring(attempts) .. " verified attempts")
end

Runtime.ReturnToLobbyAfterUtgard = function()
    if Environment.__SliceHubNewGenTSReturnToLobby == false then
        return false, "Auto Return to Lobby is disabled"
    end

    pcall(Runtime.QueueMainBuildForTeleport)
    Runtime.TeleportTransitionStarted = false
    Runtime.TeleportTransitionFailure = nil

    local get = exactBladeGET()
    if get then
        local ok = pcall(function()
            return get:InvokeServer("Functions", "Teleport", "Lobby")
        end)

        if ok then
            local deadline = os.clock()
                + Runtime.UtgardConfig.LobbyVerifySeconds
            repeat
                if Runtime.TeleportTransitionStarted or not Player.Parent then
                    return true, "verified Functions/Teleport/Lobby"
                end
                if Runtime.TeleportTransitionFailure then break end
                task.wait(0.07)
            until os.clock() >= deadline
        end
    end

    return Runtime.ActivateResultAction("leave")
end


Runtime.HandleStageResult = function(action, label)
    action = string.lower(tostring(action or "leave"))
    pcall(Runtime.QueueMainBuildForTeleport)
    setStatus(
        tostring(label or "TS STAGE") .. " • RESULT",
        action == "retry"
            and "Mission rewards verified. Retrying the same Aberrant mission for the linked TS stage."
            or "Mission rewards verified. Returning to lobby to scan and claim the next TS stage.",
        "success"
    )
    task.wait(0.12)
    if action == "retry" then
        local ok, method = Runtime.ActivateResultAction("retry")
        if not ok then
            setStatus("MANUAL RETRY NEEDED", tostring(method), "warning")
        else
            Runtime.RouteText = "Retry accepted via " .. tostring(method)
        end
        return ok, method
    end
    local ok, method = Runtime.ReturnToLobbyAfterUtgard()
    if not ok then
        setStatus("MANUAL LEAVE NEEDED", tostring(method), "warning")
    else
        Runtime.RouteText = "Lobby return accepted via " .. tostring(method)
    end
    return ok, method
end

Runtime.RunNormalMissionCleanup = function(label, resultAction, placeCheck)
    if Runtime.ObjectiveCombatActive then return end
    Runtime.ObjectiveCombatActive = true
    Runtime.ObjectiveCombatMode = "CLEANUP"
    Runtime.ObjectiveCombatPhase = tostring(label or "MISSION CLEANUP")
    Runtime.ObjectiveCombatKills = 0
    Runtime.ObjectiveCombatRegisters = 0
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatBladeReloadRetryAt = 0

    local folder = findTitansFolder()
    local deadline = os.clock() + 10
    while Runtime.Alive and Runtime.AutoLaunch and not folder and os.clock() < deadline do
        task.wait(0.10)
        folder = findTitansFolder()
    end
    if not folder then
        setStatus("TITANS FOLDER MISSING", "Normal mission cleanup could not start.", "error")
        stopObjectiveCombat("Titans folder missing")
        return
    end

    local _, _, root = characterParts(4)
    local center = root and root.Position or Vector3.zero
    local initial = {}
    for _, titan in ipairs(folder:GetChildren()) do
        if titanAlive(titan) then
            local part = exactTitanNape(titan)
            if part then initial[#initial + 1] = {Part = part} end
        end
    end
    center = averageTargetPosition(initial, center)
    moveCombatPerch(center, tostring(label or "Mission Cleanup"))

    local resultArmed, absentSince = false, nil
    while Runtime.Alive and Runtime.AutoLaunch and Runtime.ObjectiveCombatActive
        and (type(placeCheck) ~= "function" or placeCheck()) do
        local now = os.clock()
        local visible, resultText = missionResultVisible()
        if not resultArmed then
            if visible then absentSince = nil
            else
                absentSince = absentSince or now
                if now - absentSince >= 1.0 then resultArmed = true end
            end
        elseif visible then
            stopObjectiveCombat("Mission result detected")
            Runtime.HandleStageResult(resultAction, label)
            return
        end

        if not Runtime.ObjectiveCombatStationBusy then combatSafetyGuard() end
        local targets = {}
        for _, titan in ipairs(folder:GetChildren()) do
            if titanAlive(titan) then
                local part = exactTitanNape(titan)
                if part then
                    targets[#targets + 1] = {
                        Titan = titan,
                        Part = part,
                        DistanceToObjective = (part.Position - center).Magnitude,
                    }
                end
            end
        end
        table.sort(targets, function(a, b)
            return a.DistanceToObjective < b.DistanceToObjective
        end)

        if #targets > 0 then
            local fired, registers, detail = fireExactBladeBatch(targets)
            setStatus(
                tostring(label or "MISSION CLEANUP"),
                string.format(
                    "Alive %d • Blade registers %d • %s • kills %d",
                    #targets, registers, tostring(detail), Runtime.ObjectiveCombatKills
                ),
                fired and "success" or "info"
            )
            task.wait(fired and FOREST_COMBAT.SlashCooldown or 0.06)
        else
            setStatus(
                tostring(label or "MISSION CLEANUP") .. " • WAITING FOR RESULT",
                "No live Titans remain. Waiting for the verified mission result screen.",
                "success"
            )
            task.wait(0.08)
        end
    end
end

Runtime.RunUtgardController = function()
    if Runtime.UtgardControllerBusy or Runtime.ObjectiveCombatActive then return end

    Runtime.UtgardControllerBusy = true
    Runtime.UtgardControllerStarted = true
    Runtime.UtgardResultHandled = false
    Runtime.ObjectiveCombatActive = true
    Runtime.ObjectiveCombatStarted = true
    Runtime.ObjectiveCombatMode = "UTGARD"
    Runtime.ObjectiveCombatPhase = "UTGARD FULL CLEANUP"
    Runtime.ObjectiveCombatKills = 0
    Runtime.ObjectiveCombatRegisters = 0
    Runtime.ObjectiveCombatRenewPending = false
    Runtime.ObjectiveCombatBladeReloadRetryAt = 0
    Runtime.ObjectiveCombatLastGrabScanAt = 0
    Runtime.UtgardNoTargetSince = nil

    QuestHeader.Text = "ICE BURST STONES • THREE-RUN FARM"
    QuestRows[1].Text = "—  Watch Towers  •  NOT IN THIS UTGARD RUN"
    QuestRows[2].Text = "—  Escort  •  NOT IN THIS UTGARD RUN"
    QuestRows[3].Text = string.format(
        ">  Ice Burst Stones  •  UTGARD RUN %d/%d",
        math.min((tonumber(Runtime.UtgardRuns) or 0) + 1,
            Runtime.UtgardConfig.RequiredRuns),
        Runtime.UtgardConfig.RequiredRuns
    )
    QuestRows[3].TextColor3 = Color3.fromRGB(103, 176, 255)
    QuestRows[4].Text = "—  Retrieve Missing Supplies  •  NOT IN THIS UTGARD RUN"
    QuestRows[5].Text = "—  Defend Missing Supplies  •  NOT IN THIS UTGARD RUN"
    setLaunchReady(false, "UTGARD ACTIVE")


    setStatus(
        "UTGARD COMBAT STARTING",
        string.format(
            "Run %d/%d • waiting only for Workspace.Titans, then killing every Titan.",
            math.min((tonumber(Runtime.UtgardRuns) or 0) + 1,
                Runtime.UtgardConfig.RequiredRuns),
            Runtime.UtgardConfig.RequiredRuns
        ),
        "info"
    )
    RouteBody.Text =
        "Utgard Castle • Skirmish • Aberrant\nImmediate combat • no quest/Variant scan • full Titan cleanup."

    local folder = findTitansFolder()
    local deadline = os.clock() + Runtime.UtgardConfig.InitialWaitSeconds
    while Runtime.Alive and Runtime.AutoLaunch and not folder
        and os.clock() < deadline do
        task.wait(0.15)
        folder = findTitansFolder()
    end

    if not folder then
        setStatus(
            "TITANS FOLDER MISSING",
            "Workspace.Titans did not appear in Utgard.",
            "error"
        )
        stopObjectiveCombat("Utgard Titans folder missing.")
        Runtime.UtgardControllerBusy = false
        return
    end

    local character, humanoid, root = characterParts(5)
    if not character or not humanoid or not root then
        setStatus(
            "CHARACTER MISSING",
            "Could not create the Utgard safety perch.",
            "error"
        )
        stopObjectiveCombat("Character unavailable.")
        Runtime.UtgardControllerBusy = false
        return
    end

    local initialTargets = Runtime.CollectAllUtgardTargets()
    local center = averageTargetPosition(
        initialTargets,
        Vector3.new(root.Position.X, root.Position.Y, root.Position.Z)
    )
    moveCombatPerch(center, "Utgard Castle")

    setStatus(
        "UTGARD FULL CLEANUP ACTIVE",
        string.format(
            "Run %d/%d • every live Titan is a valid target immediately.",
            math.min((tonumber(Runtime.UtgardRuns) or 0) + 1,
                Runtime.UtgardConfig.RequiredRuns),
            Runtime.UtgardConfig.RequiredRuns
        ),
        "success"
    )

    local resultArmed = false
    local resultAbsentSince = nil

    while Runtime.Alive and Runtime.AutoLaunch
        and IS_UTGARD and Runtime.ObjectiveCombatActive do

        local now = os.clock()
        local resultVisible, resultText = missionResultVisible()

        if not resultArmed then
            if resultVisible then
                resultAbsentSince = nil
            else
                resultAbsentSince = resultAbsentSince or now
                if now - resultAbsentSince >= 1.25 then
                    resultArmed = true
                end
            end
        elseif resultVisible then
            if not Runtime.UtgardResultHandled then
                Runtime.UtgardResultHandled = true
                Runtime.UtgardRuns = math.clamp(
                    (tonumber(Runtime.UtgardRuns) or 0) + 1,
                    0,
                    Runtime.UtgardConfig.RequiredRuns
                )
                saveEnabled(Runtime.AutoLaunch)

                local completedRuns = Runtime.UtgardRuns
                QuestRows[3].Text = string.format(
                    completedRuns >= Runtime.UtgardConfig.RequiredRuns and
                        "✓  Ice Burst Stones  •  3 UTGARD RUNS COMPLETE" or
                        ">  Ice Burst Stones  •  UTGARD RUNS %d/%d",
                    completedRuns,
                    Runtime.UtgardConfig.RequiredRuns
                )

                if completedRuns >= Runtime.UtgardConfig.RequiredRuns then
                    QuestRows[3].TextColor3 = Color3.fromRGB(105, 222, 154)
                    setStatus(
                        "THREE UTGARD RUNS COMPLETE",
                        tostring(resultText)
                            .. "\nAll three missions were fully cleared for rewards. Returning to the lobby now.",
                        "success"
                    )
                    RouteBody.Text =
                        "Run 3/3 verified • returning to lobby to refresh/claim Ice Burst Stones."
                    stopObjectiveCombat("Three Utgard runs complete.")
                    task.wait(Runtime.UtgardConfig.ResultActionDelay)

                    local returned, method =
                        Runtime.ReturnToLobbyAfterUtgard()
                    if returned then
                        RouteBody.Text =
                            "Lobby return accepted via " .. tostring(method)
                            .. " • waiting for teleport."
                    else
                        setStatus(
                            "MANUAL LEAVE NEEDED",
                            tostring(method)
                                .. "\nVerified lobby transition failed. The saved counter is already 3/3.",
                            "warning"
                        )
                    end
                    break
                end

                setStatus(
                    "UTGARD RUN COMPLETE",
                    string.format(
                        "%s\nRun %d/%d verified. Starting the next full Utgard mission immediately.",
                        tostring(resultText),
                        completedRuns,
                        Runtime.UtgardConfig.RequiredRuns
                    ),
                    "success"
                )
                RouteBody.Text = string.format(
                    "Run %d/%d complete • pressing Retry.",
                    completedRuns,
                    Runtime.UtgardConfig.RequiredRuns
                )
                task.wait(Runtime.UtgardConfig.ResultActionDelay)

                local clicked, method = Runtime.ActivateResultAction("retry")
                if not clicked then
                    setStatus(
                        "MANUAL RETRY NEEDED",
                        tostring(method)
                            .. "\nVerified transition failed. The saved run counter will continue if Retry is pressed manually.",
                        "warning"
                    )
                    stopObjectiveCombat("Retry was not accepted.")
                else
                    RouteBody.Text =
                        "Retry accepted via " .. tostring(method)
                        .. " • waiting for the next Utgard run."
                end
            end

            task.wait(0.15)
        else
            local liveCharacter, liveHumanoid = characterParts(0.1)
            if not liveCharacter
                or not liveHumanoid
                or liveHumanoid.Health <= 0 then
                setStatus(
                    "CHARACTER DOWN",
                    "Utgard farming stopped.",
                    "error"
                )
                stopObjectiveCombat("Character unavailable.")
                break
            end

            if not Runtime.ObjectiveCombatStationBusy then
                combatSafetyGuard()
            end

            local targets, total = Runtime.CollectAllUtgardTargets()
            if total > 0 then
                Runtime.UtgardNoTargetSince = nil

                local fired, registers, detail =
                    fireExactBladeBatch(targets)

                if fired then
                    setStatus(
                        "UTGARD TITAN CLEANUP",
                        string.format(
                            "Run %d/%d • alive %d • Blade registers %d • %s • total kills %d",
                            math.min((tonumber(Runtime.UtgardRuns) or 0) + 1,
                                Runtime.UtgardConfig.RequiredRuns),
                            Runtime.UtgardConfig.RequiredRuns,
                            total,
                            registers,
                            tostring(detail),
                            Runtime.ObjectiveCombatKills
                        ),
                        "success"
                    )
                    RouteBody.Text =
                        "Every Utgard Titan is a valid target • waiting for mission completion afterward."
                    task.wait(FOREST_COMBAT.SlashCooldown)
                else
                    setStatus(
                        Runtime.ObjectiveCombatStationBusy
                            and "REFILLING BLADES"
                            or "UTGARD COMBAT WAIT",
                        tostring(detail)
                            .. "\n340-stud safety perch remains active.",
                        Runtime.ObjectiveCombatStationBusy
                            and "warning"
                            or "info"
                    )
                    task.wait(Runtime.UtgardConfig.LoopDelay)
                end
            else
                Runtime.UtgardNoTargetSince =
                    Runtime.UtgardNoTargetSince or now
                local quiet = now - Runtime.UtgardNoTargetSince

                setStatus(
                    quiet >= Runtime.UtgardConfig.NoTargetResultWait
                        and "UTGARD CLEARED • WAITING FOR RESULT"
                        or "WAITING FOR UTGARD TITANS",
                    string.format(
                        "Run %d/%d • no live Titans • quiet %.1fs",
                        math.min((tonumber(Runtime.UtgardRuns) or 0) + 1,
                            Runtime.UtgardConfig.RequiredRuns),
                        Runtime.UtgardConfig.RequiredRuns,
                        quiet
                    ),
                    quiet >= Runtime.UtgardConfig.NoTargetResultWait
                        and "success"
                        or "info"
                )
                task.wait(Runtime.UtgardConfig.LoopDelay)
            end
        end
    end

    Runtime.UtgardControllerBusy = false
    if not Runtime.AutoLaunch or not Runtime.Alive then
        destroySafePlatform()
    end
end

Runtime.questRowText = function(state)
    local prefix = "?"
    local suffix = "--"
    local color = Color3.fromRGB(126, 136, 159)

    if state.Status == "complete" then
        prefix = "✓"
        suffix = tostring(state.Amount) .. "/" .. tostring(state.Amount) .. "  COMPLETE"
        color = Color3.fromRGB(105, 222, 154)
    elseif state.Status == "active" then
        prefix = ">"
        suffix = tostring(state.Current) .. "/" .. tostring(state.Amount) .. "  ACTIVE"
        color = Color3.fromRGB(112, 181, 255)
    elseif state.Status == "locked" then
        prefix = "LOCK"
        suffix = "PREREQUISITE"
        color = Color3.fromRGB(115, 123, 143)
    elseif state.Status == "reward_pending" then
        prefix = "!"
        suffix = tostring(state.Current) .. "/" .. tostring(state.Amount) .. "  REWARD PENDING"
        color = Color3.fromRGB(255, 195, 102)
    elseif state.Status == "missing" then
        prefix = "?"
        suffix = "DATA MISSING"
        color = Color3.fromRGB(230, 150, 104)
    end

    return prefix .. "  " .. state.Definition.Name .. "  •  " .. suffix, color
end

Runtime.refreshUI = function(scan)
    Runtime.CurrentScan = scan

    if not scan or scan.Ready ~= true then
        local reason = scan and scan.Error or "Waiting for Cache.Data or a profile response."
        setStatus("SCANNING PLAYER QUESTS...", reason, "info")
        RouteBody.Text = "Waiting for quest data..."
        setLaunchReady(false, "WAITING")
        return
    end

    for index = 1, 5 do
        local row = QuestRows[index]
        local state = scan.States[index]
        if row and state then
            local text, color = Runtime.questRowText(state)
            row.Text = text
            row.TextColor3 = color
        end
    end

    local prestigeText = scan.Prestige ~= nil and ("P" .. tostring(scan.Prestige)) or "Prestige unknown"
    local sourceText = tostring(scan.Source or "unknown source")

    if scan.Completed then
        setStatus(
            "THUNDER SPEARS UNLOCKED",
            prestigeText .. " • Completion confirmed by "
                .. (scan.CompletedByParts and "Handle + Thruster + Base ownership" or "all rewarded quest states")
                .. ".\nProfile source: " .. sourceText,
            "success"
        )
        RouteBody.Text = "No mission is required. Auto Launch has been turned off."
        setLaunchReady(false, "COMPLETE")
        Runtime.AutoLaunch = false
        Runtime.LaunchAttempted = false
        Runtime.UtgardRuns = 0
        Runtime.UtgardVariantKills = 0
        saveEnabled(false)
        Runtime.updateOwnershipFlags()
        updateToggleVisual()
        return
    end

    if scan.Prestige ~= nil and scan.Prestige <= 0 then
        setStatus(
            "THUNDER SPEAR QUEST UNAVAILABLE",
            "Prestige 0 detected. Quest-specific towers, supplies, escort, and defense objects will not spawn.\nProfile source: " .. sourceText,
            "warning"
        )
        RouteBody.Text = "Reach Prestige 1 before using Auto TS Quest."
        setLaunchReady(false, "P0 BLOCKED")
        return
    end

    if type(scan.Spears) ~= "table" then
        setStatus(
            "SPEAR QUEST TABLE NOT FOUND",
            prestigeText .. " was detected, but the active slot has no Quests.Spears table yet.\nProfile source: " .. sourceText,
            "warning"
        )
        RouteBody.Text = "Open/initialize the Thunder Spear questline, then leave the scanner running."
        setLaunchReady(false, "NO QUEST DATA")
        return
    end

    if scan.PendingReward then
        local state = scan.PendingReward
        setStatus(
            "QUEST OBJECTIVE COMPLETE - CLAIMING REWARD",
            state.Definition.Name .. " reached " .. tostring(state.Current) .. "/" .. tostring(state.Amount)
                .. ". V10.18 is priming the native Thunder Spears page and pressing its visible CLAIM button.\nProfile source: " .. sourceText,
            "warning"
        )
        RouteBody.Text = "Native Spear reward claim is being attempted automatically."
        setLaunchReady(false, "CLAIMING")
        if IS_LOBBY and not Runtime.QuestPrimeBusy then
            task.spawn(function() Runtime.PrimeThunderSpearQuestPanel(true) end)
        end
        return
    end

    if scan.Route then
        local state = scan.Route
        local definition = state.Definition
        if definition.Index == 3
            and (tonumber(Runtime.UtgardRuns) or 0) >= 3 then
            setStatus(
                "THREE UTGARD RUNS ALREADY COMPLETE",
                "The saved V10.18 series is 3/3. Priming Thunder Spears so the reward/progress can refresh.",
                "success"
            )
            RouteBody.Text =
                "No fourth Utgard mission will launch • refreshing/claiming the quest in lobby."
            setLaunchReady(false, "3 RUNS COMPLETE")
            if IS_LOBBY and not Runtime.QuestPrimeBusy then
                task.spawn(function()
                    Runtime.PrimeThunderSpearQuestPanel(true)
                end)
            end
            return
        end
        setStatus(
            "CURRENT QUEST: " .. string.upper(definition.Name),
            prestigeText .. " • Progress " .. tostring(state.Current) .. "/" .. tostring(state.Amount)
                .. " • Profile source: " .. sourceText,
            "info"
        )
        RouteBody.Text = table.concat({
            definition.Map,
            definition.Objective,
            "Aberrant",
            "\nNext action: launch and complete " .. definition.Name,
        }, "  •  ")
        if SUPPORTED_ROUTE_INDEXES[definition.Index] == true then
            setLaunchReady(not Runtime.LaunchBusy, Runtime.LaunchBusy and "LAUNCHING..." or "LAUNCH MISSION")
        else
            setLaunchReady(false, "STAGE NOT IN V10.18")
        end
        return
    end

    setStatus(
        "QUEST STATE NEEDS REVIEW",
        "The quest table was found, but no safe active route could be selected. No mission will be launched.\nProfile source: " .. sourceText,
        "warning"
    )
    RouteBody.Text = "Fail-closed: no route selected."
    setLaunchReady(false, "NO ROUTE")
end

Runtime.launchCurrentRoute = function(trigger)
    if Runtime.LaunchBusy then
        return
    end

    local scan = Runtime.CurrentScan
    if not scan or not scan.Route then
        setStatus("NO SAFE ROUTE", "The background scanner has not selected an active mission yet.", "warning")
        return
    end

    if SUPPORTED_ROUTE_INDEXES[scan.Route.Definition.Index] ~= true then
        setStatus(
            "QUEST DETECTED - NOT IN V10.18",
            scan.Route.Definition.Name .. " was detected correctly, but this V10.18 test executes Utgard, Escort, and the Forest supply/defense chain.",
            "warning"
        )
        setLaunchReady(false, "STAGE NOT ADDED")
        return
    end

    saveEnabled(true)
    Runtime.updateOwnershipFlags()
    pcall(Runtime.QueueMainBuildForTeleport)
    Runtime.LaunchBusy = true
    Runtime.LaunchAttempted = true
    setLaunchReady(false, "LAUNCHING...")

    local definition = scan.Route.Definition
    setStatus(
        "CREATING " .. string.upper(definition.Map),
        tostring(trigger or "Launch") .. " • " .. definition.Objective .. " • Aberrant\nFast route handoff.",
        "info"
    )

    task.spawn(function()
        local ok, reason = ExactEngine.TryLaunch(scan.Route)
        Runtime.LaunchBusy = false

        if ok then
            setStatus("TELEPORT STARTED", tostring(reason), "success")
            setLaunchReady(false, "TELEPORTING")
        else
            Runtime.AutoLaunch = false
            updateToggleVisual()
            setStatus("LAUNCH FAILED", tostring(reason), "error")
            setLaunchReady(true, "TRY AGAIN")
        end
    end)
end

Runtime.applyEnabledState = function(value)
    Runtime.AutoLaunch = value == true
    Runtime.LaunchAttempted = false
    saveEnabled(Runtime.AutoLaunch)
    Runtime.updateOwnershipFlags()
    updateToggleVisual()

    if Runtime.AutoLaunch then
        if IS_FOREST then
            setStatus(
                "FOREST CONTROLLER ARMED",
                "Supply delivery, Defend waves, Blade refill, and objective-first combat are enabled.",
                "info"
            )
            if not Runtime.SupplyControllerBusy then
                task.spawn(runForestSupplyController)
            end
        elseif IS_OUTSKIRTS then
            setStatus(
                "OUTSKIRTS CONTROLLER ARMED",
                "Native Workspace objects decide Watch Towers or Escort. Horse/cart speed remains unchanged.",
                "info"
            )
            if Runtime.StartOutskirtsStage then Runtime.StartOutskirtsStage() end
        elseif IS_UTGARD then
            setStatus(
                "UTGARD CONTROLLER ARMED",
                "Every Titan is killed immediately. Retry twice, then return to lobby after run 3.",
                "info"
            )
            if not Runtime.UtgardControllerBusy then
                task.spawn(Runtime.RunUtgardController)
            end
        else
            setStatus(
                "AUTO LAUNCH ARMED",
                "The scanner will launch the supported Aberrant quest route.",
                "info"
            )
        end
    else
        stopObjectiveCombat("Auto TS Quest turned off.")
        destroySafePlatform()
        if IS_FOREST then
            setStatus("FOREST CONTROLLER OFF", "Safety platforms removed.", "warning")
        elseif IS_OUTSKIRTS then
            setStatus("ESCORT CONTROLLER OFF", "Moving cart protection stopped.", "warning")
        elseif IS_UTGARD then
            setStatus("UTGARD CONTROLLER OFF", "Utgard farming stopped.", "warning")
        end
    end
end

Runtime.SetEnabled = function(value)
    Runtime.applyEnabledState(value == true)
    return Runtime.AutoLaunch
end

Runtime.RefreshNow = function()
    Runtime.LaunchAttempted = false
    if IS_LOBBY then
        task.spawn(function() Runtime.PrimeThunderSpearQuestPanel(true) end)
    elseif IS_FOREST and Runtime.AutoLaunch and not Runtime.SupplyControllerBusy then
        task.spawn(runForestSupplyController)
    elseif IS_OUTSKIRTS and Runtime.AutoLaunch then
        if Runtime.StartOutskirtsStage then Runtime.StartOutskirtsStage() end
    elseif IS_UTGARD and Runtime.AutoLaunch and not Runtime.UtgardControllerBusy then
        task.spawn(Runtime.RunUtgardController)
    end
end

Toggle.Activated:Connect(function()
    Runtime.SetEnabled(not Runtime.AutoLaunch)
end)

Launch.Activated:Connect(function()
    if Runtime.CurrentScan and Runtime.CurrentScan.Route and not Runtime.LaunchBusy then
        Runtime.launchCurrentRoute("Manual launch")
    end
end)

Close.Activated:Connect(function()
    Runtime.SetEnabled(false)
end)


do
    local dragging = false
    local dragStart = nil
    local startPosition = nil

    Header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPosition = Window.Position
        end
    end)

    Header.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if not dragging then
            return
        end

        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        local delta = input.Position - dragStart
        Window.Position = UDim2.new(
            startPosition.X.Scale,
            startPosition.X.Offset + delta.X,
            startPosition.Y.Scale,
            startPosition.Y.Offset + delta.Y
        )
    end)
end

Runtime.updateOwnershipFlags()
updateToggleVisual()

Runtime.createIntegratedCard = function(parent, layoutOrder, titleText)
    if not parent or parent:FindFirstChild("SliceHubAutoTSQuestCard") then return end
    local card = Instance.new("Frame")
    card.Name = "SliceHubAutoTSQuestCard"
    card.LayoutOrder = layoutOrder or -500
    card.Size = UDim2.new(1, parent:IsA("ScrollingFrame") and -4 or 0, 0, 150)
    card.BackgroundColor3 = Color3.fromRGB(20, 24, 37)
    card.BorderSizePixel = 0
    card.Parent = parent
    local c = Instance.new("UICorner", card); c.CornerRadius = UDim.new(0, 7)
    local s = Instance.new("UIStroke", card); s.Color = Color3.fromRGB(64, 112, 196); s.Transparency = 0.35

    local heading = Instance.new("TextLabel")
    heading.Position = UDim2.fromOffset(14, 10)
    heading.Size = UDim2.new(1, -28, 0, 20)
    heading.BackgroundTransparency = 1
    heading.Font = Enum.Font.GothamBold
    heading.Text = titleText or "AUTO THUNDER SPEAR QUEST"
    heading.TextColor3 = Color3.fromRGB(238, 242, 252)
    heading.TextSize = 12
    heading.TextXAlignment = Enum.TextXAlignment.Left
    heading.Parent = card

    local toggle = Instance.new("TextButton")
    toggle.Position = UDim2.fromOffset(14, 38)
    toggle.Size = UDim2.new(0.58, -20, 0, 34)
    toggle.BorderSizePixel = 0
    toggle.Font = Enum.Font.GothamBold
    toggle.TextSize = 10
    toggle.TextColor3 = Color3.new(1,1,1)
    toggle.Parent = card
    local tc = Instance.new("UICorner", toggle); tc.CornerRadius = UDim.new(0, 6)

    local run = Instance.new("TextButton")
    run.Position = UDim2.new(0.58, 2, 0, 38)
    run.Size = UDim2.new(0.42, -16, 0, 34)
    run.BackgroundColor3 = Color3.fromRGB(42, 48, 68)
    run.BorderSizePixel = 0
    run.Font = Enum.Font.GothamBold
    run.Text = "REFRESH / RUN NOW"
    run.TextColor3 = Color3.fromRGB(222, 228, 243)
    run.TextSize = 9
    run.Parent = card
    local rc = Instance.new("UICorner", run); rc.CornerRadius = UDim.new(0, 6)

    local status = Instance.new("TextLabel")
    status.Position = UDim2.fromOffset(14, 80)
    status.Size = UDim2.new(1, -28, 0, 56)
    status.BackgroundColor3 = Color3.fromRGB(15, 18, 28)
    status.BorderSizePixel = 0
    status.Font = Enum.Font.Gotham
    status.TextColor3 = Color3.fromRGB(169, 179, 202)
    status.TextSize = 9
    status.TextWrapped = true
    status.TextXAlignment = Enum.TextXAlignment.Left
    status.TextYAlignment = Enum.TextYAlignment.Center
    status.Parent = card
    local sc = Instance.new("UICorner", status); sc.CornerRadius = UDim.new(0, 6)
    local pad = Instance.new("UIPadding", status)
    pad.PaddingLeft = UDim.new(0, 10); pad.PaddingRight = UDim.new(0, 10)

    toggle.Activated:Connect(function()
        Runtime.SetEnabled(not Runtime.AutoLaunch)
    end)
    run.Activated:Connect(function() Runtime.RefreshNow() end)

    Runtime.MainCard = card
    Runtime.MainCardToggle = toggle
    Runtime.MainCardRun = run
    Runtime.MainCardStatus = status

    task.spawn(function()
        while Runtime.Alive and card.Parent do
            Runtime.RouteText = tostring(RouteBody.Text or Runtime.RouteText or "")
            toggle.Text = Runtime.AutoLaunch
                and "AUTO GET THUNDER SPEARS: ON"
                or "AUTO GET THUNDER SPEARS: OFF"
            toggle.BackgroundColor3 = Runtime.AutoLaunch
                and Color3.fromRGB(61, 132, 255)
                or Color3.fromRGB(42, 48, 68)
            local prefix = Runtime.StatusKind == "success" and "✓ "
                or Runtime.StatusKind == "error" and "! "
                or Runtime.StatusKind == "warning" and "• "
                or "› "
            status.Text = prefix .. tostring(Runtime.StatusTitle)
                .. "\n" .. string.sub(tostring(Runtime.StatusBody), 1, 220)
            task.wait(0.20)
        end
    end)
end

Runtime.mountIntegratedCard = function()
    return false
end


if IS_FOREST then
    if Runtime.AutoLaunch then
        task.spawn(runForestSupplyController)
    else
        QuestHeader.Text = "FOREST TS MISSION PROGRESS"
        Launch.Visible = false
        RouteBody.Size = UDim2.new(1, -28, 0, 60)
        setStatus(
            "GIANT FOREST DETECTED - CONTROLLER OFF",
            "Turn Auto TS Quest on for supply delivery or strict Defend combat.",
            "warning"
        )
        RouteBody.Text =
            "Giant Forest • Skirmish • expected Aberrant\nWaiting for Auto TS Quest."
    end
elseif IS_OUTSKIRTS then
    local function startOutskirtsStage()
        task.spawn(function()
            local deadline = os.clock() + 9
            repeat
                if findEscortModel() then
                    runOutskirtsEscortController()
                    return
                end
                if Runtime.findActiveTower() or #Runtime.listWorkspaceTowers() > 0 then
                    Runtime.runOutskirtsTowerController()
                    return
                end
                task.wait(0.10)
            until os.clock() >= deadline or not Runtime.AutoLaunch
            setStatus(
                "OUTSKIRTS TS OBJECTIVE NOT FOUND",
                "Neither Escort nor Watch Towers appeared. Normal Titans remain untouched.",
                "error"
            )
        end)
    end
    Runtime.StartOutskirtsStage = startOutskirtsStage
    if Runtime.AutoLaunch then
        startOutskirtsStage()
    else
        QuestHeader.Text = "OUTSKIRTS TS QUEST PROGRESS"
        Launch.Visible = false
        RouteBody.Size = UDim2.new(1, -28, 0, 60)
        setStatus(
            "OUTSKIRTS DETECTED - CONTROLLER OFF",
            "Turn Auto TS Quest on. SliceHub will detect Towers or Escort from native Workspace objects.",
            "warning"
        )
        RouteBody.Text =
            "Outskirts • Skirmish • expected Aberrant\nHorse/cart speed remains unchanged."
    end
elseif IS_UTGARD then


    if Runtime.AutoLaunch then
        task.spawn(Runtime.RunUtgardController)
    else
        QuestHeader.Text = "ICE BURST STONES • THREE-RUN FARM"
        Launch.Visible = false
        RouteBody.Size = UDim2.new(1, -28, 0, 60)
        setStatus(
            "UTGARD DETECTED - CONTROLLER OFF",
            "Turn Auto TS Quest on to kill every Titan immediately.",
            "warning"
        )
        RouteBody.Text =
            "Utgard Castle • Skirmish • expected Aberrant\nThree complete missions, then return to lobby."
    end
else
    if IS_LOBBY then
        task.spawn(function()
            task.wait(0.15)
            Runtime.PrimeThunderSpearQuestPanel(true)
        end)
    end

    task.spawn(function()
        while Runtime.Alive and Screen.Parent do
            local profile, source = findProfile()
            if profile then
                Runtime.Profile = profile
                Runtime.ProfileSource = source or Runtime.ProfileSource
                Runtime.LastProfileAt = os.clock()
                local scan = scanQuestProfile(profile, Runtime.ProfileSource)
                Runtime.refreshUI(scan)

                if Runtime.AutoLaunch
                    and not Runtime.LaunchAttempted
                    and not Runtime.LaunchBusy
                    and scan.Ready
                    and scan.Route
                    and SUPPORTED_ROUTE_INDEXES[
                        scan.Route.Definition.Index
                    ] == true then
                    Runtime.LaunchAttempted = true
                    task.delay(0.20, function()
                        if Runtime.Alive
                            and Runtime.AutoLaunch
                            and not Runtime.LaunchBusy
                            and Runtime.CurrentScan
                            and Runtime.CurrentScan.Route
                            and SUPPORTED_ROUTE_INDEXES[
                                Runtime.CurrentScan.Route.Definition.Index
                            ] == true then
                            Runtime.launchCurrentRoute("Auto launch")
                        end
                    end)
                end
            else
                local fallbackScan = Runtime.VisibleIceBurstQuestFallback()
                if fallbackScan then
                    Runtime.refreshUI(fallbackScan)
                    if fallbackScan.PendingReward and IS_LOBBY and not Runtime.QuestPrimeBusy then
                        task.spawn(function() Runtime.PrimeThunderSpearQuestPanel(true) end)
                    end
                    if Runtime.AutoLaunch
                        and not Runtime.LaunchAttempted
                        and not Runtime.LaunchBusy
                        and fallbackScan.Route
                        and SUPPORTED_ROUTE_INDEXES[
                            fallbackScan.Route.Definition.Index
                        ] == true then
                        Runtime.LaunchAttempted = true
                        task.delay(0.20, function()
                            if Runtime.Alive
                                and Runtime.AutoLaunch
                                and not Runtime.LaunchBusy
                                and Runtime.CurrentScan
                                and Runtime.CurrentScan.Route
                                and Runtime.CurrentScan.Route.Definition.Index == 3 then
                                Runtime.launchCurrentRoute("Visible quest-panel fallback")
                            end
                        end)
                    end
                else
                    if IS_LOBBY and not Runtime.QuestPrimeBusy
                        and os.clock() - (Runtime.LastQuestPrimeAt or 0) >= 2.0 then
                        task.spawn(function() Runtime.PrimeThunderSpearQuestPanel(false) end)
                    end
                    Runtime.refreshUI({
                        Ready = false,
                        Error = Runtime.LastError
                            and ("Player profile not found yet. Last probe: "
                                .. tostring(Runtime.LastError)
                                .. ". V10.18 is priming Quests -> Thunder Spears automatically.")
                            or "Player profile not found yet. V10.18 is priming the native Thunder Spears panel automatically.",
                    })
                end
            end
            task.wait(0.35)
        end
    end)
end




