-- SECURITY-CUTOVER-R3: compile the lazy Auto-TS module once, then destroy its plaintext source.
local __SliceHubAutoTSModuleChunk = nil
do
    local __loader = loadstring or load
    local __source = __SliceHubAutoTSModuleSource
    __SliceHubAutoTSModuleSource = nil
    if type(__loader) == "function" and type(__source) == "string" then
        local __ok, __chunk = pcall(__loader, __source)
        __source = nil
        if __ok and type(__chunk) == "function" then
            __SliceHubAutoTSModuleChunk = __chunk
        end
    end
end

App.AutoTS.LoadModule = function()
    local env = type(getgenv) == "function" and getgenv() or _G
    if type(env) ~= "table" then env = _G end

    env.__SliceHubNewGenTSClaim =
        App.Values.AutoTSClaimCompleted == true

    env.__SliceHubNewGenTSReturnToLobby =
        App.Values.AutoTSReturnLobby ~= false

    env.__SliceHubNewGenTSAllowSavedAuto =
        RuntimeKind == "Lobby"
            and App.Values.AutoTSLaunchNext == true
            or App.Values.AutoTSDoQuests == true

    local chunk = __SliceHubAutoTSModuleChunk
    if type(chunk) ~= "function" then
        App.AutoTS.LastStatus = "TS module unavailable"
        return false
    end

    local okRun, err = pcall(chunk)
    chunk = nil
    App.AutoTSModuleSource = nil
    if type(App.AutoTS) == "table" then
        App.AutoTS.ModuleSource = nil
        App.AutoTS.Source = nil
        App.AutoTS.SourceText = nil
        App.AutoTS.AutoTSModuleSource = nil
    end

    if not okRun then
        App.AutoTS.LastStatus =
            "TS module runtime failed • "
            .. tostring(err)
        return false
    end

    App.AutoTS.Runtime =
        env.__SliceHubAutoTSQuestRuntime

    if not App.AutoTS.Runtime then
        App.AutoTS.LastStatus =
            "TS runtime did not initialize"
        return false
    end

    App.AutoTS.LastStatus = "TS runtime ready"
    return true
end

App.AutoTS.SyncFlags = function()
    local env =
        type(getgenv) == "function"
        and getgenv()
        or _G

    if type(env) == "table" then
        env.__SliceHubNewGenTSClaim =
            App.Values.AutoTSClaimCompleted == true

        env.__SliceHubNewGenTSReturnToLobby =
            App.Values.AutoTSReturnLobby ~= false

        env.__SliceHubNewGenTSAllowSavedAuto =
            RuntimeKind == "Lobby"
                and App.Values.AutoTSLaunchNext == true
                or App.Values.AutoTSDoQuests == true
    end
end

App.AutoTS.RefreshState = function()
    local runtime = App.AutoTS.Runtime
    if not runtime then return end

    local scan = runtime.CurrentScan
    if not scan then return end

    local scanPrestige =
        tonumber(scan.Prestige)

    if scanPrestige ~= nil then
        App.AutoTS.Prestige =
            scanPrestige
    end

    if scan.Completed then
        App.AutoTS.TerminalComplete = true
        App.AutoTS.LastStatus = "Thunder Spears complete"

        App.Values.AutoTSLaunchNext = false
        App.Values.AutoTSDoQuests = false
        App.Values.AutoTSClaimCompleted = false

        local env = v12Environment()
        env.__SliceHubNewGenTSClaim = false
        env.__SliceHubNewGenTSAllowSavedAuto = false
        env.__SliceHubNewGenTSReturnToLobby = false

        if runtime.AutoLaunch == true then
            pcall(runtime.SetEnabled, false)
        end
    elseif scan.PendingReward
        and scan.PendingReward.Definition then
        App.AutoTS.LastStatus =
            "Reward ready • "
            .. tostring(
                scan.PendingReward.Definition.Name
            )
    elseif scan.Route
        and scan.Route.Definition then
        App.AutoTS.LastStatus =
            "Next mission • "
            .. tostring(
                scan.Route.Definition.Map
            )
            .. " • "
            .. tostring(
                scan.Route.Definition.Name
            )
    end
end

App.AutoTS.CheckAberrantEligibility = function()
    return App.AutoTS.RefreshLobbyEligibility(true)
end

App.AutoTS.LoadModule()
App.AutoTS.SyncFlags()

task.spawn(function()
    while gui and gui.Parent do
        App.AutoTS.SyncFlags()

        local runtime =
            App.AutoTS.Runtime

        if runtime then
            App.AutoTS.RefreshState()

            if App.AutoTS.TerminalComplete == true then
                if runtime.AutoLaunch == true then
                    pcall(runtime.SetEnabled, false)
                end
                task.wait(0.45)
                continue
            end

            local currentScan = runtime.CurrentScan
            if currentScan and currentScan.Completed then
                if App.Values.AutoTSLaunchNext
                    or App.Values.AutoTSDoQuests then

                    App.Values.AutoTSLaunchNext = false
                    App.Values.AutoTSDoQuests = false
                    pcall(runtime.SetEnabled, false)

                    if V12Config
                        and V12Config.ScheduleSave then
                        V12Config.ScheduleSave(0.15)
                    end
                end
            end

            if RuntimeKind == "Lobby" then
                local wantsEligibility =
                    App.ActivePage == "Auto Thunder Spears"
                    or App.Values.AutoTSClaimCompleted == true
                    or App.Values.AutoTSLaunchNext == true

                if wantsEligibility
                    and not LobbyRuntime.Busy
                    and not LobbyRuntime.CountdownActive then
                    pcall(
                        App.AutoTS.RefreshLobbyEligibility,
                        false
                    )
                end

                local eligible =
                    App.AutoTS.IsEligible()

                if not eligible then
                    if App.Values.AutoTSLaunchNext then
                        App.Values.AutoTSLaunchNext = false
                        if V12Config and V12Config.ScheduleSave then
                            V12Config.ScheduleSave(0.15)
                        end
                    end

                    if runtime.AutoLaunch == true then
                        pcall(runtime.SetEnabled, false)
                    end

                else
                    if App.Values.AutoTSClaimCompleted == true
                        and os.clock()
                            - (App.AutoTS.LastClaimAt or 0)
                            >= 2.2 then

                        App.AutoTS.LastClaimAt =
                            os.clock()

                        task.spawn(function()
                            pcall(
                                runtime.PrimeThunderSpearQuestPanel,
                                true
                            )
                        end)
                    end

                    if App.Values.AutoTSLaunchNext == true
                        and runtime.AutoLaunch ~= true then

                        App.Values.AutoTSDoQuests = true

                        pcall(
                            runtime.SetEnabled,
                            true
                        )

                        pcall(
                            runtime.RefreshNow
                        )
                    elseif App.Values.AutoTSLaunchNext ~= true
                        and runtime.AutoLaunch == true then

                        pcall(
                            runtime.SetEnabled,
                            false
                        )
                    end
                end

            elseif RuntimeKind == "Gameplay" then
                local shouldRun =
                    App.Values.AutoTSDoQuests == true

                if shouldRun
                    and runtime.AutoLaunch ~= true then

                    pcall(
                        runtime.SetEnabled,
                        true
                    )

                    pcall(
                        runtime.RefreshNow
                    )

                elseif not shouldRun
                    and runtime.AutoLaunch == true then

                    pcall(
                        runtime.SetEnabled,
                        false
                    )
                end
            end
        end

        local tsActive =
            App.Values.AutoTSDoQuests == true
            or App.Values.AutoTSLaunchNext == true
            or App.Values.AutoTSClaimCompleted == true
            or (
                App.AutoTS.Runtime
                and App.AutoTS.Runtime.AutoLaunch == true
            )

        task.wait(
            tsActive
            and App.PerformanceControl.Delay(0.45, 0.60)
            or App.PerformanceControl.Delay(0.95, 1.50)
        )
    end
end)


App.MainMenu.PendingFile =
    "SH/state/newgen_mainmenu_"
    .. tostring(player.UserId)
    .. ".json"

App.MainMenu.AutoStarted = false
App.MainMenu.TeleportSerial = 0
App.MainMenu.Pending = nil

App.MainMenu.NormalizeSlot = function(value)
    value = string.upper(tostring(value or "A"))
    if string.find(value, "C", 1, true) then return "C" end
    if string.find(value, "B", 1, true) then return "B" end
    return "A"
end

App.MainMenu.NormalizeDestination = function(value)
    value = string.lower(tostring(value or "Town"))
    return string.find(value, "trade", 1, true) and "Trade" or "Town"
end

App.MainMenu.Remote = function()
    local assets =
        ReplicatedStorage:FindFirstChild("Assets")
        or ReplicatedStorage:WaitForChild("Assets", 5)

    local remotes =
        assets
        and (
            assets:FindFirstChild("Remotes")
            or assets:WaitForChild("Remotes", 5)
        )

    local remote =
        remotes
        and (
            remotes:FindFirstChild("GET")
            or remotes:WaitForChild("GET", 5)
        )

    return remote
        and remote:IsA("RemoteFunction")
        and remote
        or nil
end

App.MainMenu.CurrentSlot = function()
    local value = player:GetAttribute("Slot")

    if value == nil then
        return nil
    end

    local text = string.upper(tostring(value))

    if text == "1" then return "A" end
    if text == "2" then return "B" end
    if text == "3" then return "C" end

    return string.match(text, "([ABC])$")
        or string.match(text, "^([ABC])$")
end

App.MainMenu.SelectSlot = function(slot)
    slot = App.MainMenu.NormalizeSlot(slot)

    if App.MainMenu.CurrentSlot() == slot then
        App.MainMenu.LastSlot = slot
        return true, "Slot " .. slot .. " already selected"
    end

    local remote = App.MainMenu.Remote()

    if not remote then
        return false, "AOT:R GET remote unavailable"
    end

    local deadline = os.clock() + 12

    repeat
        local ok = pcall(function()
            remote:InvokeServer(
                "Functions",
                "Select",
                slot
            )
        end)

        task.wait(0.30)

        if App.MainMenu.CurrentSlot() == slot then
            App.MainMenu.LastSlot = slot
            return true, "Slot " .. slot .. " selected"
        end

        if not ok then
            task.wait(0.25)
        end
    until os.clock() >= deadline

    return false, "Could not confirm Slot " .. slot
end

App.MainMenu.FileFunctions = function()
    local env = v12Environment()

    return
        env.readfile or (type(readfile) == "function" and readfile or nil),
        env.writefile or (type(writefile) == "function" and writefile or nil),
        env.makefolder or (type(makefolder) == "function" and makefolder or nil)
end

App.MainMenu.SavePending = function(status)
    local _, write, make = App.MainMenu.FileFunctions()

    if type(write) ~= "function" then
        return false
    end

    if type(make) == "function" then
        pcall(make, "SH")
        pcall(make, "SH/state")
    end

    App.MainMenu.Pending = {
        UserId = player.UserId,
        JobId = tostring(game.JobId or ""),
        PlaceId = tonumber(game.PlaceId) or 0,
        Slot = App.MainMenu.NormalizeSlot(App.Values.MainSlot),
        Destination = App.MainMenu.NormalizeDestination(App.Values.MainDestination),
        AutoJoinPrivateServer = App.Values.MainAutoJoinPrivateServer == true,
        PrivateServerCodeSaved = tostring(App.Values.MainPrivateServerCode or "") ~= "",
        Status = tostring(status or "Pending"),
        UpdatedAt = os.time(),
    }

    local okEncode, encoded = pcall(function()
        return HttpService:JSONEncode(App.MainMenu.Pending)
    end)

    return okEncode
        and pcall(
            write,
            App.MainMenu.PendingFile,
            encoded
        ) == true
end

App.MainMenu.LoadPending = function()
    local read = App.MainMenu.FileFunctions()

    if type(read) ~= "function" then
        return nil
    end

    local okRead, raw =
        pcall(read, App.MainMenu.PendingFile)

    if not okRead
        or type(raw) ~= "string"
        or raw == "" then
        return nil
    end

    local okDecode, document = pcall(function()
        return HttpService:JSONDecode(raw)
    end)

    if not okDecode
        or type(document) ~= "table"
        or tonumber(document.UserId) ~= tonumber(player.UserId) then
        return nil
    end

    App.MainMenu.Pending = document

    local pendingStatus = tostring(document.Status or "")


    App.MainMenu.PendingApproval = false
    if pendingStatus == "AwaitingApproval" then
        App.MainMenu.Status = "Saved Auto Slot ready"
        App.MainMenu.Pending.Status = "LegacyApprovalCleared"
    end

    return document
end

App.MainMenu.DestinationPlaceId = function(destination)
    destination = App.MainMenu.NormalizeDestination(destination)

    local places = {
        [4658598196] = {
            Town = 14916516914,
            Trade = 14932214603,
        },
        [5310627045] = {
            Town = 15393230099,
            Trade = 108309021405580,
        },
    }

    local byGame = places[tonumber(game.GameId) or 0]
    return byGame and byGame[destination] or nil
end

App.MainMenu.VisibleNative = function(object)
    if not object
        or not object:IsA("GuiObject")
        or not object.Visible
        or object.AbsoluteSize.X <= 0
        or object.AbsoluteSize.Y <= 0 then
        return false
    end

    if gui and object:IsDescendantOf(gui) then
        return false
    end

    local node = object.Parent

    while node and node ~= playerGui do
        if node:IsA("GuiObject")
            and not node.Visible then
            return false
        end

        if node:IsA("LayerCollector")
            and not node.Enabled then
            return false
        end

        node = node.Parent
    end

    return true
end

App.MainMenu.FindNativeDestinationButton = function(destination)
    destination = App.MainMenu.NormalizeDestination(destination)

    local wanted = destination == "Trade"
        and "trade central"
        or "town central"

    local best = nil
    local bestScore = -math.huge
    local checked = 0

    for _, object in ipairs(playerGui:GetDescendants()) do
        checked += 1
        if checked > 4200 then break end

        if App.MainMenu.VisibleNative(object) then
            local rawText = ""

            if object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox") then
                rawText = tostring(object.Text or "")
            end

            local text = string.lower(rawText)
            local name = string.lower(tostring(object.Name or ""))
            local score = 0

            if string.find(text, wanted, 1, true) then
                score += 100
            end

            if string.find(name, destination == "Trade" and "trade" or "town", 1, true) then
                score += 25
            end

            local candidate = nil

            if object:IsA("GuiButton") then
                candidate = object
                score += 20
            else
                local node = object.Parent
                for _ = 1, 6 do
                    if not node or node == playerGui then break end
                    if node:IsA("GuiButton")
                        and App.MainMenu.VisibleNative(node) then
                        candidate = node
                        score += 40
                        break
                    end
                    node = node.Parent
                end
            end

            if candidate
                and score > bestScore then
                best = candidate
                bestScore = score
            end
        end
    end

    return best, bestScore
end

App.MainMenu.ActivateNativeDestination = function(destination)
    local buttonObject, score =
        App.MainMenu.FindNativeDestinationButton(destination)

    if not buttonObject
        or (tonumber(score) or 0) < 90 then
        return false, "Native destination control not confirmed"
    end

    local ok = pcall(function()
        buttonObject:Activate()
    end)

    if not ok then
        local env = v12Environment()
        local fire = env.firesignal
            or (type(firesignal) == "function" and firesignal or nil)

        if type(fire) == "function" then
            ok = pcall(fire, buttonObject.Activated)
        end
    end

    return ok, ok
        and "Native destination control activated"
        or "Native destination activation failed"
end


App.MainMenu.PrivateServerCode = function()
    return tostring(App.Values.MainPrivateServerCode or "")
        :gsub("^%s+", "")
        :gsub("%s+$", "")
        :sub(1, 160)
end

App.MainMenu.RequestPrivateServer = function()
    local code = App.MainMenu.PrivateServerCode()
    if code == "" then
        return false, "Private Server Code is empty"
    end

    App.MainMenu.PendingApproval = false
    App.MainMenu.SavePending("QueuedPrivateServer")

    if App.Values.AutoExecuteOnTeleport == true then
        local queued, queueMessage = queueV12AutoExecute(true)
        if not queued then
            return false, "Auto Execute queue failed • " .. tostring(queueMessage)
        end
    end

    local remote = App.MainMenu.Remote()
    if not remote then
        return false, "AOT:R GET remote unavailable"
    end

    App.MainMenu.Status = "Joining private server"

    -- One normal game teleport request only. Do not poll or spam this route.
    local ok, result = pcall(function()
        return remote:InvokeServer(
            "Functions",
            "Teleport",
            "Lobby",
            code
        )
    end)

    if not ok or result == false then
        App.MainMenu.SavePending("PrivateServerFailed")
        return false, "Private-server join failed • " .. tostring(result)
    end

    App.MainMenu.SavePending("TeleportingPrivateServer")
    return true,
        "Private-server join requested • Slot "
        .. App.MainMenu.NormalizeSlot(App.Values.MainSlot)
end

App.MainMenu.RequestDestination = function(destination)
    destination = App.MainMenu.NormalizeDestination(destination)

    if App.Values.MainAutoJoinPrivateServer == true then
        return App.MainMenu.RequestPrivateServer()
    end

    App.MainMenu.PendingApproval = false
    App.MainMenu.SavePending("Queued")

    if App.Values.AutoExecuteOnTeleport == true then
        local queued, queueMessage = queueV12AutoExecute(true)
        if not queued then
            return false, "Auto Execute queue failed • " .. tostring(queueMessage)
        end
    end

    local placeId = App.MainMenu.DestinationPlaceId(destination)
    if not placeId then
        return false, "Destination PlaceId unavailable for this AOT:R universe"
    end

    App.MainMenu.Status =
        "Teleporting directly to " .. destination .. " Central"

    local teleportService = game:GetService("TeleportService")
    local ok, err = pcall(function()
        teleportService:TeleportAsync(placeId, {player})
    end)

    if not ok then
        ok, err = pcall(function()
            teleportService:Teleport(placeId, player)
        end)
    end

    if not ok then
        App.MainMenu.SavePending("TeleportFailed")
        return false, "Teleport failed • " .. tostring(err)
    end

    App.MainMenu.SavePending("Teleporting")
    return true,
        "Teleport requested • Slot "
        .. App.MainMenu.NormalizeSlot(App.Values.MainSlot)
        .. " → "
        .. destination
        .. " Central"
end

App.MainMenu.Run = function(force)
    if RuntimeKind ~= "MainMenu" then
        return false, "Main Menu required"
    end

    if App.MainMenu.Busy then
        return false, "Main Menu automation busy"
    end


    App.MainMenu.Busy = true

    local slot =
        App.MainMenu.NormalizeSlot(
            App.Values.MainSlot
        )

    local destination =
        App.MainMenu.NormalizeDestination(
            App.Values.MainDestination
        )

    App.MainMenu.Status =
        "Selecting Slot " .. slot

    local selected, selectMessage =
        App.MainMenu.SelectSlot(slot)

    if not selected then
        App.MainMenu.Status =
            tostring(selectMessage)
        App.MainMenu.Busy = false
        return false, selectMessage
    end

    App.MainMenu.SavePending("SlotSelected")
    App.AutoHideForAutomation("Main Menu Auto Slot")

    App.MainMenu.Status =
        App.Values.MainAutoJoinPrivateServer == true
        and ("Slot " .. slot .. " selected • joining private server")
        or ("Slot " .. slot
            .. " selected • requesting "
            .. destination
            .. " Central")

    local ok, message =
        App.MainMenu.RequestDestination(destination)

    App.MainMenu.Status =
        tostring(message or App.MainMenu.Status)

    App.MainMenu.Busy = false
    return ok, message
end

App.MainMenu.StartAuto = function()
    if RuntimeKind ~= "MainMenu"
        or App.Values.MainAutoSelectSlot ~= true
        or App.MainMenu.AutoStarted then
        return false
    end

    App.MainMenu.AutoStarted = true
    App.MainMenu.CountdownPaused = false
    App.MainMenu.CountdownActive = true
    App.MainMenu.CountdownToken += 1

    local token = App.MainMenu.CountdownToken

    task.spawn(function()
        local seconds = math.clamp(
            math.floor((tonumber(App.Values.MainAutoSlotDelay) or 15) + 0.5),
            0,
            120
        )
        App.MainMenu.CountdownSeconds = seconds

        for remaining = seconds, 1, -1 do
            if token ~= App.MainMenu.CountdownToken
                or App.MainMenu.CountdownPaused
                or App.Values.MainAutoSelectSlot ~= true
                or not gui
                or not gui.Parent then

                App.MainMenu.CountdownActive = false
                App.MainMenu.AutoStarted = false
                return
            end

            App.MainMenu.Status =
                "Auto Slot • "
                .. tostring(remaining)
                .. "s • Slot "
                .. App.MainMenu.NormalizeSlot(App.Values.MainSlot)
                .. " → "
                .. (
                    App.Values.MainAutoJoinPrivateServer == true
                    and "Private Server"
                    or (App.MainMenu.NormalizeDestination(App.Values.MainDestination) .. " Central")
                )

            task.wait(1)
        end

        App.MainMenu.CountdownActive = false

        while gui and gui.Parent
            and App.Values.MainAutoSelectSlot == true
            and App.FamilySpin
            and App.FamilySpin.Running do

            if token ~= App.MainMenu.CountdownToken
                or App.MainMenu.CountdownPaused then
                App.MainMenu.AutoStarted = false
                return
            end

            App.MainMenu.Status =
                "Countdown complete • waiting for Family Spinner"

            task.wait(0.25)
        end

        if token ~= App.MainMenu.CountdownToken
            or App.MainMenu.CountdownPaused then
            App.MainMenu.AutoStarted = false
            return
        end

        if gui and gui.Parent
            and App.Values.MainAutoSelectSlot == true then

            App.MainMenu.Status =
                "Countdown complete • entering"

            App.MainMenu.Run(false)
        end

        App.MainMenu.AutoStarted = false
    end)

    return true
end

App.MainMenu.CancelCountdown = function()
    if RuntimeKind ~= "MainMenu" then
        return false, "Main Menu required"
    end

    if not App.MainMenu.CountdownActive
        and not App.MainMenu.AutoStarted then
        return false, "No Auto Slot countdown is running"
    end

    App.MainMenu.CountdownToken += 1
    App.MainMenu.CountdownActive = false
    App.MainMenu.CountdownPaused = true
    App.MainMenu.AutoStarted = false


    App.MainMenu.Status =
        "Auto Slot countdown cancelled • Auto Select Slot remains ON"

    V12Config.ScheduleSave(0.10)

    return true, "Countdown cancelled • Auto Select Slot remains ON"
end

App.MainMenu.LoadPending()

if RuntimeKind == "MainMenu" then
    player.OnTeleport:Connect(function(state)
        App.MainMenu.TeleportSerial += 1
        App.MainMenu.PendingApproval = false
        App.MainMenu.Status =
            "Teleport accepted • " .. tostring(state)
        App.MainMenu.SavePending("Teleporting")
    end)
end


