}

App.FamilySpin.Normalize = function(value)
    local text = string.lower(tostring(value or ""))
    text = string.gsub(text, "^%s+", "")
    text = string.gsub(text, "%s+$", "")
    return text
end

App.FamilySpin.RarityFor = function(family)
    local wanted = App.FamilySpin.Normalize(family)

    for rarity, families in pairs(App.FamilySpin.Families) do
        for name in pairs(families) do
            if App.FamilySpin.Normalize(name) == wanted then
                return rarity
            end
        end
    end

    return nil
end

App.FamilySpin.IsTerminalMythic = function(family, rarity)
    local normalized =
        App.FamilySpin.Normalize(family)

    return normalized == "fritz"
        or normalized == "helos"
        or tostring(rarity) == "Mythic"
end

App.FamilySpin.HasTargets = function()
    if App.Values.FamilyTargetMode == "Families" then
        for _, name in ipairs({
            "Arlert","Zoe","Tybur","Leonhart","Galliard","Finger","Braun","Ksaver",
            "Ackerman","Yeager","Reiss","Fritz","Helos",
        }) do
            if App.Values["FamilyTarget" .. name] == true then
                return true
            end
        end
        return false
    end

    return App.Values.FamilyTargetEpic == true
        or App.Values.FamilyTargetLegendary == true
        or App.Values.FamilyTargetMythic == true
end

App.FamilySpin.TargetSelected = function(family, rarity)
    if App.Values.FamilyTargetMode == "Families" then
        for _, name in ipairs({
            "Arlert","Zoe","Tybur","Leonhart","Galliard","Finger","Braun","Ksaver",
            "Ackerman","Yeager","Reiss","Fritz","Helos",
        }) do
            if App.FamilySpin.Normalize(name)
                == App.FamilySpin.Normalize(family) then
                return App.Values["FamilyTarget" .. name] == true
            end
        end
        return false
    end

    if rarity == "Epic" then
        return App.Values.FamilyTargetEpic == true
    end
    if rarity == "Legendary" then
        return App.Values.FamilyTargetLegendary == true
    end
    if rarity == "Mythic" then
        return App.Values.FamilyTargetMythic == true
    end

    return false
end

App.FamilySpin.Remote = function()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    local remotes = assets and assets:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("GET")
    return remote and remote:IsA("RemoteFunction") and remote or nil
end

App.FamilySpin.DetectCurrent = function()
    local rawFallback = nil

    for _, object in ipairs({
        player,
        player.Character,
    }) do
        if object then
            for _, key in ipairs({
                "Family",
                "family",
                "CurrentFamily",
                "Current_Family",
            }) do
                local value =
                    object:GetAttribute(key)

                if type(value) == "string"
                    and value ~= "" then

                    rawFallback =
                        rawFallback or value

                    local rarity =
                        App.FamilySpin.RarityFor(value)

                    if rarity then
                        return value, rarity
                    end
                end
            end
        end
    end

    local checked = 0
    local exactCandidate = nil

    for _, object in ipairs(
        playerGui:GetDescendants()
    ) do
        checked += 1

        if checked > 4500 then
            break
        end

        if not object:IsDescendantOf(gui)
            and (
                object:IsA("TextLabel")
                or object:IsA("TextButton")
                or object:IsA("TextBox")
            )
            and object.Visible then

            local normalized =
                App.FamilySpin.Normalize(
                    tostring(object.Text or "")
                )

            for rarity, families in pairs(
                App.FamilySpin.Families
            ) do
                for family in pairs(families) do
                    local wanted =
                        App.FamilySpin.Normalize(family)

                    if string.find(
                        normalized,
                        wanted .. " (",
                        1,
                        true
                    ) then
                        return family, rarity
                    end

                    if normalized == wanted then
                        exactCandidate =
                            exactCandidate
                            or {
                                Family = family,
                                Rarity = rarity,
                            }
                    end
                end
            end
        end
    end

    if exactCandidate then
        return
            exactCandidate.Family,
            exactCandidate.Rarity
    end

    if rawFallback then
        return rawFallback, "Unclassified"
    end

    return nil, nil
end

App.FamilySpin.SkipBooleanEvidence = function(object)
    if not object then
        return nil
    end

    local function truthy(value)
        if type(value) == "boolean" then
            return value
        end

        if type(value) == "number" then
            return value > 0
        end

        if type(value) == "string" then
            local text = string.lower(value)

            if text == "true"
                or text == "owned"
                or text == "purchased"
                or text == "unlocked"
                or text == "enabled"
                or text == "yes" then
                return true
            end

            if text == "false"
                or text == "not owned"
                or text == "locked"
                or text == "disabled"
                or text == "no" then
                return false
            end
        end

        return nil
    end


    for _, key in ipairs({
        "SkipRoll",
        "Skip_Roll",
        "FamilySkipRoll",
        "FastFamilyRoll",
        "SkipFamilyRoll",
    }) do
        local ok, value =
            pcall(function()
                return object:GetAttribute(key)
            end)

        if ok then
            local result = truthy(value)

            if result ~= nil then
                return result,
                    object:GetFullName()
                    .. "."
                    .. key
            end
        end
    end


    local okAttributes, attributes =
        pcall(function()
            return object:GetAttributes()
        end)

    if okAttributes
        and type(attributes) == "table" then

        for key, value in pairs(attributes) do
            local name =
                string.lower(
                    tostring(key)
                )

            if string.find(name, "skip", 1, true)
                and string.find(name, "roll", 1, true) then

                local result = truthy(value)

                if result ~= nil then
                    return result,
                        object:GetFullName()
                        .. "."
                        .. tostring(key)
                end
            end
        end
    end


    local checked = 0

    for _, child in ipairs(object:GetDescendants()) do
        checked += 1

        if checked > 2500 then
            break
        end

        local name =
            string.lower(
                tostring(child.Name or "")
            )

        if string.find(name, "skip", 1, true)
            and string.find(name, "roll", 1, true) then

            if child:IsA("BoolValue") then
                return child.Value == true,
                    child:GetFullName()
            end

            if child:IsA("IntValue")
                or child:IsA("NumberValue") then
                return tonumber(child.Value) ~= nil
                    and tonumber(child.Value) > 0,
                    child:GetFullName()
            end

            if child:IsA("StringValue") then
                local result =
                    truthy(child.Value)

                if result ~= nil then
                    return result,
                        child:GetFullName()
                end
            end

            for _, key in ipairs({
                "Owned",
                "Purchased",
                "Unlocked",
                "Enabled",
                "Active",
            }) do
                local ok, value =
                    pcall(function()
                        return child:GetAttribute(key)
                    end)

                if ok then
                    local result =
                        truthy(value)

                    if result ~= nil then
                        return result,
                            child:GetFullName()
                            .. "."
                            .. key
                    end
                end
            end
        end
    end

    return nil
end

App.FamilySpin.FindSkipPassId = function()
    for _, root in ipairs({
        playerGui,
        ReplicatedStorage,
    }) do
        local checked = 0

        for _, object in ipairs(root:GetDescendants()) do
            checked += 1
            if checked > 4500 then break end

            if not (gui and object:IsDescendantOf(gui)) then
                local name = string.lower(tostring(object.Name or ""))
                local text = ""

                if object:IsA("TextLabel")
                    or object:IsA("TextButton") then
                    text = string.lower(tostring(object.Text or ""))
                end

                if (
                    string.find(name, "skip", 1, true)
                    and string.find(name, "roll", 1, true)
                ) or (
                    string.find(text, "skip", 1, true)
                    and string.find(text, "roll", 1, true)
                ) then
                    local node = object

                    for _ = 1, 6 do
                        if not node then break end

                        for _, key in ipairs({
                            "GamePassId", "GamepassId", "PassId", "AssetId",
                        }) do
                            local id = tonumber(node:GetAttribute(key))
                            if id and id > 0 then
                                return math.floor(id), node:GetFullName()
                            end
                        end

                        node = node.Parent
                    end
                end
            end
        end
    end

    return nil
end

App.FamilySpin.DetectSkipRoll = function()


    local gamepasses =
        player:FindFirstChild("Gamepasses")

    local skipRoll =
        gamepasses
        and gamepasses:FindFirstChild("Skip_Roll")

    if skipRoll
        and skipRoll:IsA("BoolValue") then

        App.FamilySpin.SkipRollOwned =
            skipRoll.Value == true

        App.FamilySpin.SkipRollEvidence =
            skipRoll:GetFullName()
            .. ".Value="
            .. tostring(skipRoll.Value)

        App.FamilySpin.SkipRollStatus =
            App.FamilySpin.SkipRollOwned
            and "Skip Roll detected"
            or "Standard • no Skip Roll"

        if App.FamilySpin.ClampSpinDelay then
            App.FamilySpin.ClampSpinDelay(true)
        end

        return
            App.FamilySpin.SkipRollOwned,
            App.FamilySpin.SkipRollEvidence
    end

    local roots = {
        player,
        player.Character,
    }

    local characters =
        workspace:FindFirstChild("Characters")

    if characters then
        local named =
            characters:FindFirstChild(
                player.Name
            )

        if named then
            roots[#roots + 1] = named
        end

        for _, model in ipairs(
            characters:GetChildren()
        ) do
            if model:IsA("Model")
                and (
                    model:GetAttribute("UserId")
                        == player.UserId
                    or string.find(
                        string.lower(
                            tostring(model.Name)
                        ),
                        string.lower(player.Name),
                        1,
                        true
                    )
                ) then
                roots[#roots + 1] = model
            end
        end
    end

    for _, object in ipairs(roots) do
        local value, evidence =
            App.FamilySpin.SkipBooleanEvidence(
                object
            )

        if value ~= nil then
            App.FamilySpin.SkipRollOwned =
                value == true

            App.FamilySpin.SkipRollEvidence =
                evidence

            App.FamilySpin.SkipRollStatus =
                value
                and "Skip Roll detected"
                or "Standard • no Skip Roll"

            App.FamilySpin.ClampSpinDelay(true)

            return
                App.FamilySpin.SkipRollOwned,
                evidence
        end
    end

    local passId, source =
        App.FamilySpin.FindSkipPassId()

    if passId then
        App.FamilySpin.SkipRollGamePassId =
            passId

        local marketplace =
            game:GetService(
                "MarketplaceService"
            )

        local ok, owned =
            pcall(
                marketplace.UserOwnsGamePassAsync,
                marketplace,
                player.UserId,
                passId
            )

        if ok then
            App.FamilySpin.SkipRollOwned =
                owned == true

            App.FamilySpin.SkipRollEvidence =
                "gamepass "
                .. tostring(passId)
                .. " • "
                .. tostring(source)

            App.FamilySpin.SkipRollStatus =
                owned
                and "Skip Roll detected"
                or "Standard • no Skip Roll"

            App.FamilySpin.ClampSpinDelay(true)

            return
                App.FamilySpin.SkipRollOwned,
                App.FamilySpin.SkipRollEvidence
        end
    end


    for _, object in ipairs(
        playerGui:GetDescendants()
    ) do
        if not object:IsDescendantOf(gui)
            and (
                object:IsA("TextLabel")
                or object:IsA("TextButton")
            )
            and object.Visible then

            local text =
                string.lower(
                    tostring(
                        object.Text or ""
                    )
                )

            if string.find(
                text,
                "skip roll",
                1,
                true
            ) then
                local node = object.Parent

                for _ = 1, 5 do
                    if not node then
                        break
                    end

                    for _, descendant in ipairs(
                        node:GetDescendants()
                    ) do
                        if (
                            descendant:IsA("TextLabel")
                            or descendant:IsA("TextButton")
                        )
                            and descendant.Visible then

                            local state =
                                string.lower(
                                    tostring(
                                        descendant.Text
                                        or ""
                                    )
                                )

                            if string.find(
                                state,
                                "owned",
                                1,
                                true
                            )
                                or string.find(
                                    state,
                                    "purchased",
                                    1,
                                    true
                                ) then

                                App.FamilySpin.SkipRollOwned =
                                    true

                                App.FamilySpin.SkipRollEvidence =
                                    "native Skip Roll UI"

                                App.FamilySpin.SkipRollStatus =
                                    "Skip Roll detected"

                                App.FamilySpin.ClampSpinDelay(true)

                                return true,
                                    App.FamilySpin.SkipRollEvidence
                            end
                        end
                    end

                    node = node.Parent
                end
            end
        end
    end

    App.FamilySpin.SkipRollOwned = false
    App.FamilySpin.SkipRollEvidence =
        "Skip Roll not detected"

    App.FamilySpin.SkipRollStatus =
        "Standard • no Skip Roll"

    App.FamilySpin.ClampSpinDelay(true)

    return false,
        App.FamilySpin.SkipRollEvidence
end

App.FamilySpin.DelayRange = function()
    local premium =
        App.FamilySpin.IsPremium()

    local skip =
        App.FamilySpin.SkipRollOwned == true

    if premium and skip then
        return 0.03, 1.00
    end

    if premium and not skip then
        return 5.00, 10.00
    end

    if not premium and skip then
        return 0.50, 2.00
    end

    return 8.00, 15.00
end

App.FamilySpin.DefaultDelay = function()
    local premium =
        App.FamilySpin.IsPremium()

    local skip =
        App.FamilySpin.SkipRollOwned == true

    if premium and skip then
        return 0.08
    end

    if premium and not skip then
        return 7.00
    end

    if not premium and skip then
        return 0.75
    end

    return 10.00
end

App.FamilySpin.ClampSpinDelay = function(resetIfOutside)
    local minimum, maximum =
        App.FamilySpin.DelayRange()

    local value =
        tonumber(
            App.Values.FamilySpinDelay
        )

    if value == nil
        or value < minimum
        or value > maximum then


        value = minimum
    end

    value =
        math.clamp(
            value,
            minimum,
            maximum
        )

    App.Values.FamilySpinDelay =
        math.floor(value * 100 + 0.5)
        / 100

    return
        App.Values.FamilySpinDelay
end

App.FamilySpin.RandomDelay = function()

    return App.FamilySpin.ClampSpinDelay(false)
end

App.FamilySpin.Roll = function()
    local remote = App.FamilySpin.Remote()

    if not remote then
        return false, "GET remote missing"
    end

    local ok, spins, extra, family, pity, sequence = pcall(function()
        return remote:InvokeServer(
            "Family",
            "Roll"
        )
    end)

    if not ok then
        return false, tostring(spins)
    end

    if family == nil then
        return false, "Roll rejected or no spins left"
    end

    local rarity =
        App.FamilySpin.RarityFor(family)

    if App.FamilySpin.IsTerminalMythic(family, rarity) then
        rarity = "Mythic"
    end

    if rarity == nil
        and type(sequence) == "table" then
        local final = sequence[#sequence]
        if type(final) == "table"
            and App.FamilySpin.Normalize(final.Family)
                == App.FamilySpin.Normalize(family) then
            local candidate = tostring(final.Rarity or "")
            if candidate == "Epic"
                or candidate == "Legendary"
                or candidate == "Mythic" then
                rarity = candidate
            end
        end
    end

    return true, {
        Spins = spins,
        Extra = extra,
        Family = tostring(family),
        Rarity = rarity or "Unknown",
        Pity = pity,
        Sequence = sequence,
    }
end


App.FamilySpin.FindDepositButton = function()
    if RuntimeKind ~= "MainMenu" then return nil, "Main Menu required" end
    local interface = playerGui:FindFirstChild("Interface")
    local customisation = interface and interface:FindFirstChild("Customisation")
    local familyRoot = customisation and customisation:FindFirstChild("Family")
    local buttons = familyRoot and familyRoot:FindFirstChild("Buttons_2")
    local store = buttons and buttons:FindFirstChild("Store")
    if not store then return nil, "DEPOSIT button unavailable" end
    if store:IsA("GuiButton") then
        return store.Visible and store or nil, store.Visible and nil or "DEPOSIT button hidden"
    end
    for _, child in ipairs(store:GetDescendants()) do
        if child:IsA("GuiButton") and child.Visible then return child end
    end
    return nil, "DEPOSIT button unavailable"
end

App.FamilySpin.ReadCurrentPanel = function()
    local interface = playerGui:FindFirstChild("Interface")
    local customisation = interface and interface:FindFirstChild("Customisation")
    local familyRoot = customisation and customisation:FindFirstChild("Family")
    local current = familyRoot and familyRoot:FindFirstChild("Family")
    local title = current and current:FindFirstChild("Title", true)
    if not title or not (title:IsA("TextLabel") or title:IsA("TextButton") or title:IsA("TextBox")) then return nil end
    local raw = tostring(title.Text or "")
    local normalized = App.FamilySpin.Normalize(raw)
    if normalized == "" or normalized == "family" then return nil end
    for rarity, families in pairs(App.FamilySpin.Families) do
        for family in pairs(families) do
            local wanted = App.FamilySpin.Normalize(family)
            if normalized == wanted or string.find(normalized, wanted, 1, true) then
                return family, rarity, raw
            end
        end
    end
    return raw, "Unknown", raw
end

App.FamilySpin.WaitDepositChange = function(expectedFamily, timeout)
    local wanted = App.FamilySpin.Normalize(expectedFamily)
    local deadline = os.clock() + math.max(0.5, tonumber(timeout) or 1.5)
    repeat
        local family, rarity = App.FamilySpin.ReadCurrentPanel()
        if family and App.FamilySpin.Normalize(family) ~= wanted then
            return true, tostring(family), tostring(rarity or App.FamilySpin.RarityFor(family) or "Unknown")
        end
        if not family then
            local fallback, fallbackRarity = App.FamilySpin.DetectCurrent()
            if fallback and App.FamilySpin.Normalize(fallback) ~= wanted then
                return true, tostring(fallback), tostring(fallbackRarity or App.FamilySpin.RarityFor(fallback) or "Unknown")
            end
        end
        task.wait(0.10)
    until os.clock() >= deadline
    return false
end

App.FamilySpin.DepositCurrent = function(expectedFamily)
    if App.FamilySpin.DepositBusy then return false, "Family deposit already running" end
    App.FamilySpin.DepositBusy = true
    local before = tostring(expectedFamily or App.FamilySpin.CurrentFamily or "")
    local button, reason = App.FamilySpin.FindDepositButton()
    if not button then
        App.FamilySpin.DepositBusy = false
        return false, reason or "Family deposit failed, likely storage full."
    end

    App.FamilySpin.Status = "MYTHIC ROLLED • depositing " .. before
    local activated = pcall(function() button:Activate() end)
    if activated then
        local changed, family, rarity = App.FamilySpin.WaitDepositChange(before, 1.50)
        if changed then
            App.FamilySpin.DepositBusy = false
            return true, family, rarity
        end
    end

    local previous = nil
    pcall(function()
        previous = GuiService.SelectedObject
        GuiService.SelectedObject = button
        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
        task.wait(0.05)
        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
    end)
    pcall(function() GuiService.SelectedObject = previous end)
    local changed, family, rarity = App.FamilySpin.WaitDepositChange(before, 1.50)
    App.FamilySpin.DepositBusy = false
    if changed then return true, family, rarity end
    return false, "Family deposit failed, likely storage full."
end

App.FamilySpin.SendDepositWebhook = function(result, success, replacement, detail)
    if App.FamilySpin.IsPremium() ~= true
        or App.Values.FamilyWebhookEnabled ~= true
        or not App.Webhook
        or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        return false, "Premium webhook unavailable"
    end

    local pingContent, allowedMentions = App.FamilySpin.PingPayload()
    local payload = {
        content = pingContent,
        allowed_mentions = allowedMentions,
        embeds = {{
            title = success and "🌟 Mythic Family Deposited" or "⚠️ Family Deposit Failed",
            description = success
                and ("Deposited " .. tostring(result.Family) .. " successfully. Family Spinner is continuing.")
                or "Family deposit failed, likely storage full.",
            fields = {
                {name="Family", value=tostring(result.Family), inline=true},
                {name="Rarity", value=tostring(result.Rarity or "Mythic"), inline=true},
                {name="Replacement", value=success and tostring(replacement or "Detected") or "Mythic protected", inline=true},
                {name="Details", value=tostring(detail or (success and "Verified by current-family change" or "Deposit could not be verified")), inline=false},
                {name="Rolls", value=tostring(App.FamilySpin.Rolls), inline=true},
            },
            footer = {text="SliceHub V1 New Gen • AOT:R Family Deposit"},
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }},
    }
    return App.Webhook.Post(payload)
end

App.FamilySpin.HandleMythic = function(result)
    if App.Values.FamilyAutoDepositMythic ~= true then
        App.FamilySpin.Stop("MYTHIC PROTECTED", result, true)
        return false
    end

    local ok, familyOrReason, rarity = App.FamilySpin.DepositCurrent(result.Family)
    if not ok then
        App.FamilySpin.Running = false
        App.FamilySpin.Serial += 1
        App.Values.FamilySpinEnabled = false
        App.FamilySpin.CurrentFamily = tostring(result.Family)
        App.FamilySpin.CurrentRarity = "Mythic"
        App.FamilySpin.Status = "DEPOSIT FAILED • MYTHIC PROTECTED • " .. tostring(result.Family)
        V12Config.ScheduleSave(0.10)
        if App.FamilySpin.IsPremium() and App.Values.FamilyWebhookEnabled == true then
            task.spawn(App.FamilySpin.SendDepositWebhook, result, false, nil, familyOrReason)
        end
        return false
    end

    App.FamilySpin.CurrentFamily = tostring(familyOrReason or "Unknown")
    App.FamilySpin.CurrentRarity = tostring(rarity or App.FamilySpin.RarityFor(familyOrReason) or "Unknown")
    App.FamilySpin.Status = "MYTHIC DEPOSITED • " .. tostring(result.Family) .. " → " .. App.FamilySpin.CurrentFamily
    V12Config.ScheduleSave(0.10)
    if App.FamilySpin.IsPremium() and App.Values.FamilyWebhookEnabled == true then
        task.spawn(App.FamilySpin.SendDepositWebhook, result, true, App.FamilySpin.CurrentFamily, "Deposit verified")
    end
    return true
end

App.FamilySpin.ValidPingUserId = function(value)
    local text =
        string.gsub(
            tostring(value or ""),
            "%D",
            ""
        )

    return #text >= 15
        and #text <= 22
        and text
        or nil
end

App.FamilySpin.PingPayload = function()
    local userId =
        App.FamilySpin.ValidPingUserId(
            App.Values.FamilyWebhookUserId
        )

    if not userId then
        return nil,
            {parse = {}}
    end

    return "<@" .. userId .. ">",
        {
            parse = {},
            users = {userId},
        }
end

App.FamilySpin.SendWebhook = function(result, terminal)
    if App.FamilySpin.IsPremium() ~= true
        or App.Values.FamilyWebhookEnabled ~= true
        or not App.Webhook
        or not App.Webhook.ValidURL(App.Values.WebhookURL) then
        return false, "Premium webhook unavailable"
    end

    local elapsed =
        math.max(
            0,
            os.clock() - (App.FamilySpin.StartedAt or os.clock())
        )

    local pingContent, allowedMentions =
        App.FamilySpin.PingPayload()

    local payload = {
        content = pingContent,
        allowed_mentions = allowedMentions,
        embeds = {{
            title = terminal
                and "🌟 Mythic Family Rolled"
                or "🎯 Target Family Rolled",
            description = terminal
                and "Mythic protection engaged. SliceHub stopped before another family roll."
                or "Family Spinner reached one of the selected targets.",
            fields = {
                {name="Family", value=tostring(result.Family), inline=true},
                {name="Rarity", value=tostring(result.Rarity), inline=true},
                {name="Targets", value=App.FamilySpin.TargetSummary(), inline=false},
                {name="Rolls", value=tostring(App.FamilySpin.Rolls), inline=true},
                {name="Elapsed", value=string.format("%.1fs", elapsed), inline=true},
                {name="Last Delay", value=App.FamilySpin.LastDelay and string.format("%.2fs", App.FamilySpin.LastDelay) or "—", inline=true},
            },
            footer = {text="SliceHub V1 New Gen • AOT:R Family Spinner"},
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        }},
    }

    return App.Webhook.Post(payload)
end

App.FamilySpin.Stop = function(reason, result, terminal, suppressWebhook)
    App.FamilySpin.Running = false
    App.FamilySpin.Serial += 1
    App.Values.FamilySpinEnabled = false

    if result then
        App.FamilySpin.CurrentFamily = tostring(result.Family)
        App.FamilySpin.CurrentRarity = tostring(result.Rarity)
        App.FamilySpin.Status =
            (terminal and "MYTHIC PROTECTED • " or "TARGET FOUND • ")
            .. tostring(result.Family)

        if App.FamilySpin.IsPremium()
            and App.Values.FamilyWebhookEnabled == true
            and suppressWebhook ~= true then
            task.spawn(
                App.FamilySpin.SendWebhook,
                result,
                terminal == true
            )
        end
    else
        App.FamilySpin.Status = tostring(reason or "Stopped")
    end

    V12Config.ScheduleSave(0.10)
end

App.FamilySpin.Loop = function(serial)
    while App.FamilySpin.Running
        and App.FamilySpin.Serial == serial
        and gui
        and gui.Parent do


        if App.FamilySpin.IsTerminalMythic(
            App.FamilySpin.CurrentFamily,
            App.FamilySpin.CurrentRarity
        ) then
            if not App.FamilySpin.HandleMythic({
                Family = App.FamilySpin.CurrentFamily,
                Rarity = "Mythic",
            }) then return end
        end

        local ok, resultOrError =
            App.FamilySpin.Roll()

        if not ok then
            App.FamilySpin.Stop(
                tostring(resultOrError)
            )
            return
        end

        local result = resultOrError
        App.FamilySpin.Rolls += 1
        App.FamilySpin.CurrentFamily = result.Family
        App.FamilySpin.CurrentRarity = result.Rarity
        App.FamilySpin.Status =
            "Roll "
            .. tostring(App.FamilySpin.Rolls)
            .. " • "
            .. tostring(result.Family)
            .. " ("
            .. tostring(result.Rarity)
            .. ")"

        local depositedMythic = false
        if App.FamilySpin.IsTerminalMythic(
            result.Family,
            result.Rarity
        ) then
            if not App.FamilySpin.HandleMythic(result) then return end
            depositedMythic = true
        end

        if not depositedMythic and App.FamilySpin.TargetSelected(
            result.Family,
            result.Rarity
        ) then
            App.FamilySpin.Stop(
                "Target found",
                result,
                false
            )
            return
        end

        local delay =
            App.FamilySpin.RandomDelay()

        App.FamilySpin.LastDelay = delay

        local deadline = os.clock() + delay
        repeat
            if not App.FamilySpin.Running
                or App.FamilySpin.Serial ~= serial then
                return
            end
            task.wait(
                delay <= 1
                and 0.02
                or 0.10
            )
        until os.clock() >= deadline
    end
end

App.FamilySpin.Start = function()
    if RuntimeKind ~= "MainMenu" then
        App.Values.FamilySpinEnabled = false
        App.FamilySpin.Status = "Main Menu required"
        return false
    end

    if App.FamilySpin.Running then
        return true
    end

    if not App.FamilySpin.HasTargets() then
        App.Values.FamilySpinEnabled = false
        App.FamilySpin.Status = "Select at least one family target"
        return false
    end

    local currentFamily, currentRarity =
        App.FamilySpin.DetectCurrent()

    App.FamilySpin.CurrentFamily = currentFamily or "Unknown"
    App.FamilySpin.CurrentRarity = currentRarity or "Unknown"

    if App.FamilySpin.IsTerminalMythic(
        currentFamily,
        currentRarity
    ) then
        if not App.FamilySpin.HandleMythic({
            Family = currentFamily,
            Rarity = "Mythic",
        }) then return false end
    end

    App.FamilySpin.Running = true
    App.FamilySpin.Serial += 1
    App.FamilySpin.Rolls = 0
    App.FamilySpin.StartedAt = os.clock()
    App.FamilySpin.Status = "Starting"

    App.AutoHideForAutomation("Family Spinner")

    local serial = App.FamilySpin.Serial
    task.spawn(
        App.FamilySpin.Loop,
        serial
    )

    return true
end

App.FamilySpin.RefreshSkipRollAsync = function()
    task.spawn(function()
        App.FamilySpin.SkipRollStatus = "Checking Skip Roll"

        for _ = 1, 10 do
            local owned = App.FamilySpin.DetectSkipRoll()

            if owned then
                return
            end

            task.wait(0.45)
        end

        App.FamilySpin.SkipRollStatus = "Standard • no Skip Roll"
    end)
end

App.FamilySpin.RefreshSkipRollAsync()

task.spawn(function()
    local gamepasses =
        player:WaitForChild(
            "Gamepasses",
            8
        )

    local skipRoll =
        gamepasses
        and gamepasses:WaitForChild(
            "Skip_Roll",
            8
        )

    if skipRoll
        and skipRoll:IsA("BoolValue") then

        skipRoll:GetPropertyChangedSignal(
            "Value"
        ):Connect(function()
            App.FamilySpin.DetectSkipRoll()
            V12Config.ScheduleSave(0.10)
        end)

        App.FamilySpin.DetectSkipRoll()
    end
end)

App.FamilySpin.RefreshCurrentAsync = function()
    task.spawn(function()
        while gui and gui.Parent do
            if RuntimeKind == "MainMenu" then
                local family, rarity =
                    App.FamilySpin.DetectCurrent()

                if family then
                    App.FamilySpin.CurrentFamily =
                        tostring(family)

                    App.FamilySpin.CurrentRarity =
                        tostring(rarity or "Unclassified")
                else
                    App.FamilySpin.CurrentFamily =
                        "Scanning"

                    App.FamilySpin.CurrentRarity =
                        "Scanning"
                end

                task.wait(0.75)
            else
                task.wait(App.PerformanceControl.Delay(1.50, 2.50))
            end
        end
    end)
end

App.FamilySpin.RefreshCurrentAsync()

player.CharacterAdded:Connect(function()
    task.delay(0.65, function()
        if gui and gui.Parent then
            App.FamilySpin.RefreshSkipRollAsync()

            local family, rarity =
                App.FamilySpin.DetectCurrent()

            if family then
                App.FamilySpin.CurrentFamily =
                    tostring(family)

                App.FamilySpin.CurrentRarity =
                    tostring(rarity or "Unclassified")
            end
        end
    end)
end)


task.spawn(function()
    task.wait(1.5)
    while gui and gui.Parent do
        if RuntimeKind == "Gameplay" and App.AFKManager and App.AFKManager.LimitHandled ~= true then
            local hours = math.clamp(math.floor((tonumber(App.Values.AFKTimeLimitHours) or 0) + 0.5), 0, 168)
            if hours > 0 then
                local data = App.AFKManager.Data()
                local started = data and tonumber(data.SessionStartedUnix) or 0
                if started > 0 and os.time() - started >= hours * 3600 then
                    App.AFKManager.HandleLimit("Time limit reached")
                end
            end
        end
        task.wait(1.0)
    end
end)

