    MissionAutoRetry = function()
        MissionLoop.RetryToken += 1
        MissionLoop.Busy = false
        if App.Values.MissionAutoRetry then
            MissionLoop.Suppressed = false
            App.Values.MissionLoopStatus = "Mission Retry armed • waiting for result"
            local live = exactResultPanel()
            if live and MissionLoop.ResultKind(live) == "Mission" and not MissionLoop.ResultVisible then
                MissionLoop.ResultVisible = true
                MissionLoop.ActiveResultSerial += 1
                task.spawn(processMissionResult, live, MissionLoop.ActiveResultSerial)
            end
        else
            App.Values.MissionLoopStatus = "Mission Auto Retry off"
        end
    end,

