        end
        if not ok then toast("Auto Load Config", tostring(message)) end
    end,

    GlobalConfigSync = function()
        if App.Values.GlobalConfigSync == true then
            local ok, message = writeV12Config()
            if not ok then
                App.Values.GlobalConfigSync = false
                V12Config.GlobalEnabled = false
                toast("Config Sync Failed", tostring(message))
                return
            end
            toast(
                "Config Applied To All Instances",
                "Global source • " .. tostring(V12Config.GlobalSourceText())
            )
        else
            local ok, message = V12Config.DisableGlobal()
            if not ok then
                App.Values.GlobalConfigSync = true
                V12Config.GlobalEnabled = true
                toast("Config Sync Failed", tostring(message))
                return
            end
            V12Config.RestorePerAccount()
            toast(
                "Per-Account Config Restored",
                tostring(player.Name) .. " now uses its own active named config."
            )
        end
        if rebuildCurrent then task.delay(0.05, rebuildCurrent) end
    end,

    AutoHideUI = function()
        if App.Values.AutoHideUI == true then
            local active =
                (RuntimeKind == "Lobby" and App.Values.LobbyAutoLaunch == true)
                or (RuntimeKind == "Gameplay" and (
                    (App.Values.MissionAutoRetry == true or App.Values.RaidRetry == true)
                    or App.Values.AutoFarmBlades == true
                    or App.Values.AutoFarmSpears == true
                    or App.Values.AutoTSDoQuests == true
                ))
                or (RuntimeKind == "MainMenu" and App.Values.MainAutoSelectSlot == true)
            if active then App.AutoHideForAutomation("Auto Hide enabled") end
        end
    end,

    AutoExecuteOnTeleport = function()
        local ok, message = V12Config.SaveMetadataOnly()

        if not ok then
            toast("Auto Execute", tostring(message))
            return
        end

        if App.Values.AutoExecuteOnTeleport then
            V12Config.QueuedForTeleport = false
            local installOk, installMessage = installV13PersistentAutoExecute()
            local queueOk, queueMessage = queueV12AutoExecute(false)
            toast(
                queueOk and "Auto Execute Armed" or "Auto Execute Saved",
                queueOk
                    and (installOk and "Teleport loader queued • persistent helper ready." or "Teleport loader queued.")
                    or tostring(queueMessage or installMessage)
            )
        else
            V12Config.QueuedForTeleport = false
            pcall(App.removeV13PersistentAutoExecute)
            toast("Auto Execute", "Disabled for future teleports.")
        end
    end,

