V12Config.OnScopeValuesApplied = function(changed)
    if type(changed) ~= "table" then return end
    for key in pairs(changed) do
        if key ~= "GlobalConfigSync"
            and key ~= "AutoLoadConfig"
            and key ~= "AutoExecuteOnTeleport" then
            local handler = ActionHandlers[key]
            if type(handler) == "function" then
                task.spawn(handler)
            end
        end
    end
    if rebuildCurrent then task.delay(0.05, rebuildCurrent) end
end

task.spawn(function()
    while App.RuntimeHealth and App.RuntimeHealth.Alive == true do
        task.wait(1.0)
        pcall(V12Config.GlobalWatchStep)
    end
end)

local function runActionHandler(key)
    local handler = ActionHandlers[key]
    if handler then task.spawn(handler) end
    if V12Config and type(V12Config.ScheduleSave) == "function" then
        V12Config.ScheduleSave(0.30)
    end
end

