local activeToast

toast = function(titleText, bodyText)
    if activeToast and activeToast.Parent then
        activeToast:Destroy()
    end

    local t = Instance.new("Frame")
    t.AnchorPoint = Vector2.new(1,1)
    t.Position = UDim2.new(1,310,1,-18)
    t.Size = UDim2.fromOffset(280,60)
    t.BackgroundColor3 = C.Surface
    t.BorderSizePixel = 0
    t.ZIndex = 51
    t.Parent = toastLayer
    corner(t,7)
    stroke(t,0.28)

    local bar = Instance.new("Frame")
    bar.Size = UDim2.new(0,3,1,0)
    bar.BackgroundColor3 = C.Accent
    bar.BorderSizePixel = 0
    bar.ZIndex = 52
    bar.Parent = t

    local h = label(t,titleText,UDim2.new(1,-24,0,20),UDim2.fromOffset(14,8),9,C.Text,Enum.Font.GothamBold)
    h.ZIndex = 52
    local d = label(t,bodyText,UDim2.new(1,-24,0,22),UDim2.fromOffset(14,30),8,C.Muted)
    d.TextYAlignment = Enum.TextYAlignment.Top
    d.ZIndex = 52

    activeToast = t
    TweenService:Create(
        t,
        TweenInfo.new(0.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),
        {Position=UDim2.new(1,-18,1,-18)}
    ):Play()

    task.delay(2.1,function()
        if t and t.Parent then
            local tw = TweenService:Create(
                t,
                TweenInfo.new(0.14,Enum.EasingStyle.Quad,Enum.EasingDirection.In),
                {Position=UDim2.new(1,310,1,-18)}
            )
            tw:Play()
            tw.Completed:Wait()
            if t then t:Destroy() end
            if activeToast == t then activeToast = nil end
        end
    end)
end

setStatus = function(text)
    statusText.Text = text
