local function baseRow(parentObject, def)
    local hasDesc = def.Desc ~= nil
    local row = Instance.new("Frame")
    row.Size = UDim2.new(1,0,0,hasDesc and 47 or 38)
    row.BackgroundColor3 = C.Surface2
    row.BackgroundTransparency = 1
    row.BorderSizePixel = 0
    row.Parent = parentObject

    row.MouseEnter:Connect(function()
        TweenService:Create(
            row,
            TweenInfo.new(0.11, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {BackgroundTransparency = 0.93}
        ):Play()
    end)

    row.MouseLeave:Connect(function()
        TweenService:Create(
            row,
            TweenInfo.new(0.11, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {BackgroundTransparency = 1}
        ):Play()
    end)

    local textLeft = def.Icon and 46 or 12

    if def.Icon then
        local icon = Instance.new("ImageLabel")
        icon.Name = "RowIcon"
        icon.BackgroundTransparency = 1
        icon.Position = UDim2.fromOffset(12, hasDesc and 8 or 7)
        icon.Size = UDim2.fromOffset(26, 26)
        icon.ScaleType = Enum.ScaleType.Fit
        icon.Image = type(def.Icon) == "number"
            and ("rbxassetid://" .. tostring(def.Icon))
            or tostring(def.Icon)
        icon.Parent = row
    end

    label(
        row,
        def.Name,
        UDim2.new(1,-250-textLeft+12,0,18),
        UDim2.fromOffset(textLeft,hasDesc and 6 or 10),
        10,
        C.Text,
        Enum.Font.GothamMedium
    )

    if hasDesc then
        local d = label(row,def.Desc,UDim2.new(1,-255-textLeft+12,0,17),UDim2.fromOffset(textLeft,24),8,C.Muted)
        d.TextYAlignment = Enum.TextYAlignment.Top
    end

    local line = Instance.new("Frame")
    line.AnchorPoint = Vector2.new(0,1)
    line.Position = UDim2.new(0,12,1,0)
    line.Size = UDim2.new(1,-24,0,1)
    line.BackgroundColor3 = C.Stroke
    line.BackgroundTransparency = 0.76
    line.BorderSizePixel = 0
    line.Parent = row

    return row
end

local function toggleRow(parentObject, def)
    local row = baseRow(parentObject,def)

    local toggle = Instance.new("TextButton")
    toggle.AutoButtonColor = false
    toggle.Text = ""
    toggle.AnchorPoint = Vector2.new(1,0.5)
    toggle.Position = UDim2.new(1,-13,0.5,0)
    toggle.Size = UDim2.fromOffset(38,20)
    toggle.BackgroundColor3 = C.Surface3
    toggle.BorderSizePixel = 0
    toggle.Parent = row
    corner(toggle,10)

    local knob = Instance.new("Frame")
    knob.AnchorPoint = Vector2.new(0,0.5)
    knob.Size = UDim2.fromOffset(14,14)
    knob.BackgroundColor3 = C.Muted
    knob.BorderSizePixel = 0
    knob.Parent = toggle
    corner(knob,8)

    local knobScale = Instance.new("UIScale")
    knobScale.Scale = 1
    knobScale.Parent = knob

    local function enabledNow()
        if type(def.EnabledFunction) == "function" then
            local ok, value = pcall(def.EnabledFunction)
            return ok and value == true
        end
        return true
    end

    local function refresh(animated)
        local enabled = enabledNow()
        local on = App.Values[def.Key] == true

        if not enabled and on then
            App.Values[def.Key] = false
            on = false
        end

        toggle.Active = enabled
        toggle.BackgroundTransparency = enabled and 0 or 0.48
        knob.BackgroundTransparency = enabled and 0 or 0.35

        local properties = {
            BackgroundColor3 = on and C.AccentSoft or C.Surface3,
        }
        local knobProps = {
            Position = on and UDim2.new(1,-17,0.5,0) or UDim2.new(0,3,0.5,0),
            BackgroundColor3 = on and C.Accent or C.Muted,
        }

        if animated then
            TweenService:Create(toggle,TweenInfo.new(0.12,Enum.EasingStyle.Quad),properties):Play()
            TweenService:Create(knob,TweenInfo.new(0.12,Enum.EasingStyle.Quad),knobProps):Play()
        else
            for k,v in pairs(properties) do toggle[k]=v end
            for k,v in pairs(knobProps) do knob[k]=v end
        end
    end

    toggle.Activated:Connect(function()
        if not enabledNow() then
            refresh(true)
            return
        end

        App.Values[def.Key] = not App.Values[def.Key]
        knobScale.Scale = 0.82
        TweenService:Create(
            knobScale,
            TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            {Scale = 1}
        ):Play()
        refresh(true)
        runActionHandler(def.Key)
        if def.Rebuild and rebuildCurrent then
            task.delay(0.08, rebuildCurrent)
        end
    end)

    refresh(false)

    if type(def.EnabledFunction) == "function" then
        task.spawn(function()
            while row and row.Parent do
                refresh(false)
                task.wait(0.65)
            end
        end)
    end
end

local function statusRow(parentObject,def)
