    local v = label(row,def.Value or "—",UDim2.fromOffset(200,18),UDim2.new(1,-214,0.5,-9),8,C.Muted,Enum.Font.GothamMedium)
    v.TextXAlignment = Enum.TextXAlignment.Right
end


