local function liveRow(parentObject, def)
    local row = baseRow(parentObject, def)
    local valueLabel = label(
        row,
        "—",
        UDim2.fromOffset(250, 18),
        UDim2.new(1, -264, 0.5, -9),
        9,
        C.Muted,
        Enum.Font.GothamMedium
    )
    valueLabel.TextXAlignment = Enum.TextXAlignment.Right
    valueLabel.TextTruncate = Enum.TextTruncate.AtEnd

    local function refresh()
        local ok, value = pcall(function()
            return type(def.ValueFunction) == "function" and def.ValueFunction() or "—"
        end)
        local text = ok and tostring(value or "—") or "—"
        local kind = "muted"
        if type(def.KindFunction) == "function" then
            local okKind, result = pcall(def.KindFunction)
            if okKind then kind = string.lower(tostring(result or "muted")) end
        end

        local color = C.Muted
        if kind == "good" or kind == "ready" or kind == "success" then
            color = C.Good
        elseif kind == "warn" or kind == "waiting" or kind == "retry" then
            color = C.Warn
        elseif kind == "error" or kind == "failed" then
            color = Color3.fromRGB(244, 105, 112)
        end

        valueLabel.Text = type(def.KindFunction) == "function" and ("● " .. text) or text
        valueLabel.TextColor3 = color
    end

    refresh()
    task.spawn(function()
        while row and row.Parent do
            refresh()
            task.wait(0.12)
        end
    end)
end

local function buttonRow(parentObject,def)
