local function segmentRow(parentObject,def)
    local row = baseRow(parentObject,def)
    local options = type(def.OptionsFunction) == "function"
        and def.OptionsFunction()
        or (def.Options or {})
    if #options == 0 then
        options = {"—"}
    end
    local width = math.min(360, 76 * #options)

    local holder = Instance.new("Frame")
    holder.AnchorPoint = Vector2.new(1,0.5)
    holder.Position = UDim2.new(1,-13,0.5,0)
    holder.Size = UDim2.fromOffset(width,28)
    holder.BackgroundColor3 = C.Surface3
    holder.BorderSizePixel = 0
    holder.Parent = row
    corner(holder,6)

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Horizontal
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.VerticalAlignment = Enum.VerticalAlignment.Center
    layout.Padding = UDim.new(0,3)
    layout.Parent = holder

    local buttons = {}

    local function refresh()
        local selected = App.Values[def.Key]
        for option,b in pairs(buttons) do
            b.BackgroundColor3 = option == selected and C.Accent or C.Surface3
            b.TextColor3 = option == selected and C.Text or C.Muted
        end
    end

    for i,option in ipairs(options) do
        local b = button(holder,string.upper(option),UDim2.new(1/#options,-5,0,22),UDim2.new())
        b.LayoutOrder = i
        b.BackgroundColor3 = C.Surface3
        b.TextSize = 7
        buttons[option] = b

        b.Activated:Connect(function()
            App.Values[def.Key] = option
            refresh()
            runActionHandler(def.Key)
            if def.Rebuild and rebuildCurrent then
                task.delay(0.10, rebuildCurrent)
            end
        end)
    end

    refresh()
end

local function colorRow(parentObject, def)
    -- R8 GUI HOTFIX: tolerate stale/legacy saved color payloads instead of
    -- letting one malformed color preference abort the whole page constructor.
    local function normalizeColor(value, fallback)
        if typeof(value) == "Color3" then
            return value
        end

        if type(value) == "table" then
            local r = tonumber(value.R or value.r or value[1])
            local g = tonumber(value.G or value.g or value[2])
            local b = tonumber(value.B or value.b or value[3])
            if r and g and b then
                if math.max(math.abs(r), math.abs(g), math.abs(b)) > 1 then
                    r, g, b = r / 255, g / 255, b / 255
                end
                return Color3.new(
                    math.clamp(r, 0, 1),
                    math.clamp(g, 0, 1),
                    math.clamp(b, 0, 1)
                )
            end
        elseif type(value) == "string" then
            local hex = string.gsub(value, "#", "")
            if #hex == 6 and string.match(hex, "^[%da-fA-F]+$") then
                local r = tonumber(string.sub(hex, 1, 2), 16)
                local g = tonumber(string.sub(hex, 3, 4), 16)
                local b = tonumber(string.sub(hex, 5, 6), 16)
                if r and g and b then
                    return Color3.fromRGB(r, g, b)
                end
            end
        end

        return fallback or C.Accent
    end

    local initialColor = normalizeColor(App.Values[def.Key], C.Accent)
    App.Values[def.Key] = initialColor

    local row = baseRow(parentObject, def)

    local swatch = Instance.new("TextButton")
    swatch.AutoButtonColor = false
    swatch.Text = ""
    swatch.AnchorPoint = Vector2.new(1, 0.5)
    swatch.Position = UDim2.new(1, -13, 0.5, 0)
    swatch.Size = UDim2.fromOffset(62, 26)
    swatch.BackgroundColor3 = initialColor
    swatch.BorderSizePixel = 0
    swatch.Parent = row
    corner(swatch, 6)
    stroke(swatch, 0.35)

    local picker = Instance.new("Frame")
    picker.Name = "ColorPicker"
    picker.AnchorPoint = Vector2.new(1, 0)
    picker.Position = UDim2.new(1, -13, 1, 4)
    picker.Size = UDim2.fromOffset(236, 176)
    picker.BackgroundColor3 = C.Surface2
    picker.BorderSizePixel = 0
    picker.Visible = false
    picker.ZIndex = 40
    picker.Parent = row
    corner(picker, 8)
    stroke(picker, 0.28)

    local hue = Instance.new("TextButton")
    hue.AutoButtonColor = false
    hue.Text = ""
    hue.Position = UDim2.fromOffset(12, 12)
    hue.Size = UDim2.fromOffset(18, 150)
    hue.BackgroundColor3 = Color3.new(1, 1, 1)
    hue.BorderSizePixel = 0
    hue.ZIndex = 41
    hue.Parent = picker
    corner(hue, 5)

    local hueGradient = Instance.new("UIGradient")
    hueGradient.Rotation = 90
    hueGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromHSV(0.00,1,1)),
        ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17,1,1)),
        ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33,1,1)),
        ColorSequenceKeypoint.new(0.50, Color3.fromHSV(0.50,1,1)),
        ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67,1,1)),
        ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83,1,1)),
        ColorSequenceKeypoint.new(1.00, Color3.fromHSV(1.00,1,1)),
    })
    hueGradient.Parent = hue

    local sv = Instance.new("TextButton")
    sv.AutoButtonColor = false
    sv.Text = ""
    sv.Position = UDim2.fromOffset(42, 12)
    sv.Size = UDim2.fromOffset(182, 150)
    sv.BorderSizePixel = 0
    sv.ZIndex = 41
    sv.Parent = picker
    corner(sv, 5)

    local whiteOverlay = Instance.new("Frame")
    whiteOverlay.Size = UDim2.fromScale(1,1)
    whiteOverlay.BackgroundColor3 = Color3.new(1,1,1)
    whiteOverlay.BorderSizePixel = 0
    whiteOverlay.ZIndex = 42
    whiteOverlay.Parent = sv
    corner(whiteOverlay, 5)

    local whiteGradient = Instance.new("UIGradient")
    whiteGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,0),
        NumberSequenceKeypoint.new(1,1),
    })
    whiteGradient.Parent = whiteOverlay

    local blackOverlay = Instance.new("Frame")
    blackOverlay.Size = UDim2.fromScale(1,1)
    blackOverlay.BackgroundColor3 = Color3.new(0,0,0)
    blackOverlay.BorderSizePixel = 0
    blackOverlay.ZIndex = 43
    blackOverlay.Parent = sv
    corner(blackOverlay, 5)

    local blackGradient = Instance.new("UIGradient")
    blackGradient.Rotation = 90
    blackGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,1),
        NumberSequenceKeypoint.new(1,0),
    })
    blackGradient.Parent = blackOverlay

    local h, sat, val = initialColor:ToHSV()
    local draggingHue = false
    local draggingSV = false

    local function apply()
        local color = Color3.fromHSV(h, sat, val)
        App.Values[def.Key] = color
        swatch.BackgroundColor3 = color
        sv.BackgroundColor3 = Color3.fromHSV(h,1,1)
        runActionHandler(def.Key)
    end

    local function updateHue(y)
        h = math.clamp((y - hue.AbsolutePosition.Y) / hue.AbsoluteSize.Y, 0, 1)
        apply()
    end

    local function updateSV(pos)
        sat = math.clamp((pos.X - sv.AbsolutePosition.X) / sv.AbsoluteSize.X, 0, 1)
        val = 1 - math.clamp((pos.Y - sv.AbsolutePosition.Y) / sv.AbsoluteSize.Y, 0, 1)
        apply()
    end

    hue.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingHue = true
            updateHue(input.Position.Y)
        end
    end)

    sv.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingSV = true
            updateSV(input.Position)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if draggingHue and (
            input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            updateHue(input.Position.Y)
        elseif draggingSV and (
            input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            updateSV(input.Position)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingHue = false
            draggingSV = false
        end
    end)

    swatch.Activated:Connect(function()
        picker.Visible = not picker.Visible
        if picker.Visible then
            picker.BackgroundTransparency = 0.25
            local pickerScale = picker:FindFirstChildOfClass("UIScale") or Instance.new("UIScale")
            pickerScale.Parent = picker
            pickerScale.Scale = 0.94
            TweenService:Create(
                pickerScale,
                TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                {Scale = 1}
            ):Play()
            TweenService:Create(
                picker,
                TweenInfo.new(0.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                {BackgroundTransparency = 0.04}
            ):Play()
        end
    end)

    apply()
end

local function sliderRow(parentObject,def)
    local row = baseRow(parentObject,def)

    local holder = Instance.new("Frame")
    holder.AnchorPoint = Vector2.new(1,0.5)
    holder.Position = UDim2.new(1,-13,0.5,0)
    holder.Size = UDim2.fromOffset(220,28)
    holder.BackgroundTransparency = 1
    holder.Parent = row

    local value = label(holder,"",UDim2.fromOffset(48,18),UDim2.fromOffset(0,5),8,C.Text,Enum.Font.GothamMedium)
    value.TextXAlignment = Enum.TextXAlignment.Right

    local bar = Instance.new("Frame")
    bar.Position = UDim2.fromOffset(60,12)
    bar.Size = UDim2.fromOffset(153,4)
    bar.BackgroundColor3 = C.Surface3
    bar.BorderSizePixel = 0
    bar.Parent = holder
    corner(bar,4)

    local fill = Instance.new("Frame")
    fill.BackgroundColor3 = C.Accent
    fill.BorderSizePixel = 0
    fill.Parent = bar
    corner(fill,4)

    local knob = Instance.new("TextButton")
    knob.AutoButtonColor = false
    knob.Text = ""
    knob.AnchorPoint = Vector2.new(0.5,0.5)
    knob.Size = UDim2.fromOffset(12,12)
    knob.BackgroundColor3 = C.Text
    knob.BorderSizePixel = 0
    knob.Parent = bar
    corner(knob,7)

    local dragging = false

    local function rangeValues()
        if def.DynamicFamilyRange == true
            and def.Key == "FamilySpinDelay"
            and App.FamilySpin
            and type(App.FamilySpin.DelayRange) == "function" then

            local minimum, maximum =
                App.FamilySpin.DelayRange()

            minimum =
                tonumber(minimum)
                or 0.50

            maximum =
                tonumber(maximum)
                or minimum

            if maximum < minimum then
                maximum = minimum
            end

            return minimum, maximum
        end

        local minimum =
            type(def.MinFunction) == "function"
            and tonumber(def.MinFunction())
            or tonumber(def.Min)
            or 0

        local maximum =
            type(def.MaxFunction) == "function"
            and tonumber(def.MaxFunction())
            or tonumber(def.Max)
            or (minimum + 1)

        if maximum < minimum then
            maximum = minimum
        end

        return minimum, maximum
    end

    local function toAlpha(v)
        local minimum, maximum = rangeValues()

        if maximum <= minimum then
            return 0
        end

        return ((tonumber(v) or minimum) - minimum)
            / (maximum - minimum)
    end

    local function toValue(alpha)
        local minimum, maximum = rangeValues()
        local raw = minimum + (maximum - minimum) * alpha
        local step = def.Step or 1

        if step <= 0 then
            return raw
        end

        local snapped =
            math.floor(raw / step + 0.5)
            * step

        return math.clamp(
            snapped,
            minimum,
            maximum
        )
    end

    local function refresh()
        local minimum, maximum = rangeValues()

        App.Values[def.Key] =
            math.clamp(
                tonumber(App.Values[def.Key]) or minimum,
                minimum,
                maximum
            )

        local v = App.Values[def.Key]
        local a = math.clamp(toAlpha(v),0,1)
        value.Text = type(def.Format) == "function"
            and tostring(def.Format(v))
            or tostring(v)
        fill.Size = UDim2.fromScale(a,1)
        knob.Position = UDim2.fromScale(a,0.5)
    end

    local function setFromX(x)
        local a = math.clamp((x-bar.AbsolutePosition.X)/bar.AbsoluteSize.X,0,1)
        App.Values[def.Key] = toValue(a)
        refresh()
        runActionHandler(def.Key)
    end

    bar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging=true
            setFromX(input.Position.X)
        end
    end)

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging=true
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if dragging and (
            input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            setFromX(input.Position.X)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if dragging and (
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            dragging=false
        end
    end)

    refresh()

    if def.DynamicFamilyRange == true
        or type(def.MinFunction) == "function"
        or type(def.MaxFunction) == "function" then

        task.spawn(function()
            local lastMinimum = nil
            local lastMaximum = nil
            local lastValue = nil

            while row and row.Parent do
                local minimum, maximum =
                    rangeValues()

                local before =
                    tonumber(App.Values[def.Key])

                refresh()

                local after =
                    tonumber(App.Values[def.Key])

                if minimum ~= lastMinimum
                    or maximum ~= lastMaximum
                    or after ~= lastValue then

                    lastMinimum = minimum
                    lastMaximum = maximum
                    lastValue = after

                    if before ~= after
                        and V12Config
                        and type(V12Config.ScheduleSave) == "function" then
                        V12Config.ScheduleSave(0.10)
                    end
                end

                task.wait(0.25)
            end
        end)
    end
end


local function expandRow(parentObject, def)
    local row = Instance.new("Frame")
    row.Size = UDim2.new(1, 0, 0, 47)
    row.BackgroundTransparency = 1
    row.BorderSizePixel = 0
    row.ClipsDescendants = true
    row.Parent = parentObject

    local head = Instance.new("Frame")
    head.Size = UDim2.new(1, 0, 0, 47)
    head.BackgroundTransparency = 1
    head.Parent = row

    label(head, def.Name, UDim2.new(1, -310, 0, 18), UDim2.fromOffset(12, 6), 10, C.Text, Enum.Font.GothamMedium)
    local desc = label(head, def.Desc or "", UDim2.new(1, -315, 0, 17), UDim2.fromOffset(12, 24), 8, C.Muted)
    desc.TextYAlignment = Enum.TextYAlignment.Top

    local master = Instance.new("TextButton")
    master.AutoButtonColor = false
    master.Text = ""
    master.AnchorPoint = Vector2.new(1, 0.5)
    master.Position = UDim2.new(1, -52, 0.5, 0)
    master.Size = UDim2.fromOffset(38, 20)
    master.BackgroundColor3 = C.Surface3
    master.BorderSizePixel = 0
    master.Parent = head
    corner(master, 10)

    local knob = Instance.new("Frame")
    knob.AnchorPoint = Vector2.new(0, 0.5)
    knob.Size = UDim2.fromOffset(14, 14)
    knob.BackgroundColor3 = C.Muted
    knob.BorderSizePixel = 0
    knob.Parent = master
    corner(knob, 8)

    local arrow = Instance.new("TextButton")
    arrow.AutoButtonColor = false
    arrow.Text = "›"
    arrow.AnchorPoint = Vector2.new(1, 0.5)
    arrow.Position = UDim2.new(1, -12, 0.5, 0)
    arrow.Size = UDim2.fromOffset(28, 28)
    arrow.BackgroundTransparency = 1
    arrow.TextColor3 = C.Muted
    arrow.Font = Enum.Font.GothamBold
    arrow.TextSize = 18
    arrow.Parent = head

    local children = Instance.new("Frame")
    children.Position = UDim2.fromOffset(12, 47)
    children.Size = UDim2.new(1, -24, 0, 0)
    children.BackgroundColor3 = C.Back
    children.BackgroundTransparency = 0.75
    children.BorderSizePixel = 0
    children.ClipsDescendants = true
    children.Parent = row
    corner(children, 6)

    local list = Instance.new("UIListLayout")
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Parent = children

    local function buildChildren()
        for _, child in ipairs(children:GetChildren()) do
            if child ~= list and not child:IsA("UICorner") then
                child:Destroy()
            end
        end

        for _, childDef in ipairs(def.Children or {}) do
            -- R8: one bad nested control must not abort the parent page.
            local ok, err = pcall(function()
                if childDef.Type == "toggle" then
                    toggleRow(children, childDef)
                elseif childDef.Type == "segments" then
                    segmentRow(children, childDef)
                elseif childDef.Type == "slider" then
                    sliderRow(children, childDef)
                elseif childDef.Type == "sliderbox" then
                    App.SliderBoxRow(children, childDef)
                elseif childDef.Type == "numberbox" then
                    App.NumberBoxRow(children, childDef)
                elseif childDef.Type == "color" then
                    colorRow(children, childDef)
                elseif childDef.Type == "live" then
                    liveRow(children, childDef)
                elseif childDef.Type == "status" then
                    statusRow(children, childDef)
                elseif childDef.Type == "button" then
                    buttonRow(children, childDef)
                elseif childDef.Type == "collapse" and App.CollapseRow then
                    App.CollapseRow(children, childDef)
                end
            end)

            if not ok
                and type(Environment) == "table"
                and Environment.SliceHubDebug == true then
                warn(
                    "[SliceHub GUI] Nested control recovered:",
                    tostring(childDef.Name or childDef.Type or "unknown"),
                    tostring(err)
                )
            end
        end
    end

    buildChildren()

    local function refreshMaster(animated)
        local on = App.Values[def.Key] == true
        local holderProps = {BackgroundColor3 = on and C.AccentSoft or C.Surface3}
        local knobProps = {
            Position = on and UDim2.new(1, -17, 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
            BackgroundColor3 = on and C.Accent or C.Muted,
        }

        if animated then
            TweenService:Create(master, TweenInfo.new(0.12, Enum.EasingStyle.Quad), holderProps):Play()
            TweenService:Create(knob, TweenInfo.new(0.12, Enum.EasingStyle.Quad), knobProps):Play()
        else
            for k,v in pairs(holderProps) do master[k]=v end
            for k,v in pairs(knobProps) do knob[k]=v end
        end
    end

    local function setExpanded(expanded, animated)
        App.Values[def.ExpandedKey] = expanded == true

        task.defer(function()
            local contentHeight = list.AbsoluteContentSize.Y
            local targetChildren = expanded and contentHeight or 0
            local targetRow = 47 + targetChildren

            children.Visible = true

            if animated then
                TweenService:Create(
                    children,
                    TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                    {Size = UDim2.new(1, -24, 0, targetChildren), BackgroundTransparency = expanded and 0.82 or 1}
                ):Play()

                TweenService:Create(
                    row,
                    TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                    {Size = UDim2.new(1, 0, 0, targetRow)}
                ):Play()

                TweenService:Create(
                    arrow,
                    TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                    {Rotation = expanded and 90 or 0, TextColor3 = expanded and C.Accent or C.Muted}
                ):Play()
            else
                children.Size = UDim2.new(1, -24, 0, targetChildren)
                row.Size = UDim2.new(1, 0, 0, targetRow)
                arrow.Rotation = expanded and 90 or 0
            end

            if V12Config and type(V12Config.ScheduleSave) == "function" then
                V12Config.ScheduleSave(0.30)
            end
        end)
    end


    list:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        if App.Values[def.ExpandedKey] == true then
            task.defer(function()
                if not row or not row.Parent then return end
                local contentHeight = list.AbsoluteContentSize.Y
                children.Size = UDim2.new(1, -24, 0, contentHeight)
                row.Size = UDim2.new(1, 0, 0, 47 + contentHeight)
            end)
        end
    end)

    master.Activated:Connect(function()
        App.Values[def.Key] = not App.Values[def.Key]
        refreshMaster(true)
        runActionHandler(def.Key)
    end)

    arrow.Activated:Connect(function()
        setExpanded(not App.Values[def.ExpandedKey], true)
    end)

    head.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then

            local mouseX = input.Position.X
            if mouseX < master.AbsolutePosition.X - 8 then
                setExpanded(not App.Values[def.ExpandedKey], true)
            end
        end
    end)

    refreshMaster(false)
    setExpanded(App.Values[def.ExpandedKey], false)
end

App.ChoiceRow = function(parentObject, def)
    local row = baseRow(parentObject, def)
    local options = type(def.OptionsFunction) == "function"
        and def.OptionsFunction()
        or (def.Options or {})
    if #options == 0 then options = {"—"} end

    local holder = Instance.new("Frame")
    holder.AnchorPoint = Vector2.new(1, 0.5)
    holder.Position = UDim2.new(1, -13, 0.5, 0)
    holder.Size = UDim2.fromOffset(300, 28)
    holder.BackgroundColor3 = C.Surface3
    holder.BorderSizePixel = 0
    holder.Parent = row
    corner(holder, 6)

    local left = button(holder, "‹", UDim2.fromOffset(28, 22), UDim2.fromOffset(3, 3))
    left.TextSize = 15

    local current = label(
        holder,
        tostring(App.Values[def.Key] or options[1]),
        UDim2.new(1, -68, 0, 22),
        UDim2.fromOffset(34, 3),
        8,
        C.Text,
        Enum.Font.GothamMedium
    )
    current.TextXAlignment = Enum.TextXAlignment.Center
    current.TextTruncate = Enum.TextTruncate.AtEnd

    local right = button(holder, "›", UDim2.fromOffset(28, 22), UDim2.new(1, -31, 0, 3))
    right.TextSize = 15

    local function refresh()
        local selected = tostring(App.Values[def.Key] or "")
        if not table.find(options, selected) then
            App.Values[def.Key] = options[1]
        end
        current.Text = tostring(App.Values[def.Key] or options[1])
    end

    local function move(delta)
        options = type(def.OptionsFunction) == "function"
            and def.OptionsFunction()
            or (def.Options or {})
        if #options == 0 then return end

        local selected = tostring(App.Values[def.Key] or options[1])
        local index = table.find(options, selected) or 1
        index = ((index - 1 + delta) % #options) + 1
        App.Values[def.Key] = options[index]

        current.TextTransparency = 0.45
        current.Position = UDim2.fromOffset(34 + (delta > 0 and 4 or -4), 3)
        TweenService:Create(
            current,
            TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {TextTransparency = 0, Position = UDim2.fromOffset(34, 3)}
        ):Play()

        runActionHandler(def.Key)
        refresh()

        if def.Rebuild and rebuildCurrent then
            task.delay(0.08, rebuildCurrent)
        end
    end

    left.Activated:Connect(function() move(-1) end)
    right.Activated:Connect(function() move(1) end)
    refresh()
end

App.NumberBoxRow = function(parentObject, def)
    local row = baseRow(parentObject, def)

    local box = Instance.new("TextBox")
    box.AnchorPoint = Vector2.new(1, 0.5)
    box.Position = UDim2.new(1, -13, 0.5, 0)
    box.Size = UDim2.fromOffset(150, 28)
    box.BackgroundColor3 = C.Surface3
    box.BorderSizePixel = 0
    box.ClearTextOnFocus = false
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 10
    box.TextColor3 = C.Text
    box.PlaceholderColor3 = C.Muted
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.Parent = row
    corner(box, 6)

    local stroke = Instance.new("UIStroke")
    stroke.Color = C.Stroke
    stroke.Thickness = 1
    stroke.Transparency = 0.55
    stroke.Parent = box

    local function sanitize()
        local value = tonumber(box.Text)
            or tonumber(App.Values[def.Key])
            or tonumber(def.Min)
            or 0

        value = math.floor(value + 0.5)

        if def.Min ~= nil then
            value = math.max(value, tonumber(def.Min) or value)
        end
        if def.Max ~= nil then
            value = math.min(value, tonumber(def.Max) or value)
        end

        App.Values[def.Key] = value
        box.Text = tostring(value)
        runActionHandler(def.Key)
    end

    box.Text = tostring(App.Values[def.Key] or def.Min or 0)

    box.Focused:Connect(function()
        TweenService:Create(
            stroke,
            TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Color = C.Accent, Transparency = 0.10}
        ):Play()
    end)

    box.FocusLost:Connect(function()
        sanitize()
        TweenService:Create(
            stroke,
            TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Color = C.Stroke, Transparency = 0.55}
        ):Play()
    end)
end


App.SliderBoxRow = function(parentObject, def)
    local row = baseRow(parentObject, def)

    local holder = Instance.new("Frame")
    holder.AnchorPoint = Vector2.new(1, 0.5)
    holder.Position = UDim2.new(1, -13, 0.5, 0)
    holder.Size = UDim2.fromOffset(300, 30)
    holder.BackgroundTransparency = 1
    holder.Parent = row

    local valueLabel = label(
        holder,
        "",
        UDim2.fromOffset(72, 18),
        UDim2.fromOffset(0, 6),
        8,
        C.Text,
        Enum.Font.GothamMedium
    )
    valueLabel.TextXAlignment =
        Enum.TextXAlignment.Right

    local bar = Instance.new("Frame")
    bar.Position = UDim2.fromOffset(84, 13)
    bar.Size = UDim2.fromOffset(126, 4)
    bar.BackgroundColor3 = C.Surface3
    bar.BorderSizePixel = 0
    bar.Parent = holder
    corner(bar, 4)

    local fill = Instance.new("Frame")
    fill.BackgroundColor3 = C.Accent
    fill.BorderSizePixel = 0
    fill.Parent = bar
    corner(fill, 4)

    local knob = Instance.new("TextButton")
    knob.AutoButtonColor = false
    knob.Text = ""
    knob.AnchorPoint = Vector2.new(0.5, 0.5)
    knob.Size = UDim2.fromOffset(12, 12)
    knob.BackgroundColor3 = C.Text
    knob.BorderSizePixel = 0
    knob.Parent = bar
    corner(knob, 7)

    local box = Instance.new("TextBox")
    box.Position = UDim2.fromOffset(220, 1)
    box.Size = UDim2.fromOffset(80, 28)
    box.BackgroundColor3 = C.Surface3
    box.BorderSizePixel = 0
    box.ClearTextOnFocus = false
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 9
    box.TextColor3 = C.Text
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.Parent = holder
    corner(box, 6)

    local boxStroke = Instance.new("UIStroke")
    boxStroke.Color = C.Stroke
    boxStroke.Thickness = 1
    boxStroke.Transparency = 0.55
    boxStroke.Parent = box

    local dragging = false

    local function clampValue(value)
        value = math.floor((tonumber(value) or def.Min or 0) + 0.5)
        value = math.max(tonumber(def.Min) or value, value)
        value = math.min(tonumber(def.Max) or value, value)
        return value
    end

    local function refresh()
        local current =
            clampValue(App.Values[def.Key])

        App.Values[def.Key] = current

        local alpha =
            (current - def.Min)
            / (def.Max - def.Min)

        alpha = math.clamp(alpha, 0, 1)

        valueLabel.Text =
            type(def.Format) == "function"
            and tostring(def.Format(current))
            or tostring(current)

        box.Text = tostring(current)
        fill.Size = UDim2.fromScale(alpha, 1)
        knob.Position = UDim2.fromScale(alpha, 0.5)
    end

    local function setFromX(x)
        local alpha = math.clamp(
            (x - bar.AbsolutePosition.X)
            / bar.AbsoluteSize.X,
            0,
            1
        )

        local raw =
            def.Min
            + (def.Max - def.Min) * alpha

        local step = tonumber(def.Step) or 1
        raw =
            math.floor(raw / step + 0.5)
            * step

        App.Values[def.Key] =
            clampValue(raw)

        refresh()
        runActionHandler(def.Key)
    end

    bar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            setFromX(input.Position.X)
        end
    end)

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if dragging and (
            input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            setFromX(input.Position.X)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if dragging and (
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            dragging = false
        end
    end)

    box.Focused:Connect(function()
        TweenService:Create(
            boxStroke,
            TweenInfo.new(
                0.12,
                Enum.EasingStyle.Quint,
                Enum.EasingDirection.Out
            ),
            {
                Color = C.Accent,
                Transparency = 0.10,
            }
        ):Play()
    end)

    box.FocusLost:Connect(function()
        App.Values[def.Key] =
            clampValue(box.Text)

        refresh()
        runActionHandler(def.Key)

        TweenService:Create(
            boxStroke,
            TweenInfo.new(
                0.14,
                Enum.EasingStyle.Quint,
                Enum.EasingDirection.Out
            ),
            {
                Color = C.Stroke,
                Transparency = 0.55,
            }
        ):Play()
    end)

    refresh()
end

App.CollapseRow = function(parentObject, def)
    local row = Instance.new("Frame")
    row.Size = UDim2.new(1, 0, 0, 47)
    row.BackgroundTransparency = 1
    row.BorderSizePixel = 0
    row.ClipsDescendants = true
    row.Parent = parentObject

    local head = Instance.new("TextButton")
    head.AutoButtonColor = false
    head.Text = ""
    head.Size = UDim2.new(1, 0, 0, 47)
    head.BackgroundColor3 = C.Surface3
    head.BackgroundTransparency = 0.68
    head.BorderSizePixel = 0
    head.Parent = row
    corner(head, 6)

    label(head, def.Name or "Section", UDim2.new(1,-70,0,18), UDim2.fromOffset(12,6), 10, C.Text, Enum.Font.GothamMedium)
    local desc = label(head, def.Desc or "", UDim2.new(1,-76,0,17), UDim2.fromOffset(12,24), 8, C.Muted)
    desc.TextYAlignment = Enum.TextYAlignment.Top

    local arrow = Instance.new("TextLabel")
    arrow.AnchorPoint = Vector2.new(1,0.5)
    arrow.Position = UDim2.new(1,-14,0.5,0)
    arrow.Size = UDim2.fromOffset(24,24)
    arrow.BackgroundTransparency = 1
    arrow.Text = "›"
    arrow.TextColor3 = C.Muted
    arrow.Font = Enum.Font.GothamBold
    arrow.TextSize = 18
    arrow.Parent = head

    local children = Instance.new("Frame")
    children.Position = UDim2.fromOffset(12,47)
    children.Size = UDim2.new(1,-24,0,0)
    children.BackgroundColor3 = C.Back
    children.BackgroundTransparency = 1
    children.BorderSizePixel = 0
    children.ClipsDescendants = true
    children.Visible = false
    children.Parent = row
    corner(children,6)

    local list = Instance.new("UIListLayout")
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Parent = children

    local function childVisible(childDef)
        if type(childDef.OnlyWhen) ~= "table" then return true end
        local condition = childDef.OnlyWhen
        local current = App.Values[condition.Key]
        if type(condition.Values) == "table" then
            return condition.Values[current] == true
        end
        return current == condition.Value
    end

    local function buildChildren()
        for _, child in ipairs(children:GetChildren()) do
            if child ~= list and not child:IsA("UICorner") then
                child:Destroy()
            end
        end

        for _, childDef in ipairs(def.Children or {}) do
            if childVisible(childDef) then
                -- R8: keep collapsed groups usable even if one saved control
                -- contains stale data from an older GUI build.
                local ok, err = pcall(function()
                    if childDef.Type == "toggle" then
                        toggleRow(children, childDef)
                    elseif childDef.Type == "segments" then
                        segmentRow(children, childDef)
                    elseif childDef.Type == "slider" then
                        sliderRow(children, childDef)
                    elseif childDef.Type == "sliderbox" then
                        App.SliderBoxRow(children, childDef)
                    elseif childDef.Type == "numberbox" then
                        App.NumberBoxRow(children, childDef)
                    elseif childDef.Type == "live" then
                        liveRow(children, childDef)
                    elseif childDef.Type == "status" then
                        statusRow(children, childDef)
                    elseif childDef.Type == "button" then
                        buttonRow(children, childDef)
                    elseif childDef.Type == "choice" and App.ChoiceRow then
                        App.ChoiceRow(children, childDef)
                    elseif childDef.Type == "secretbox" and App.SecretBoxRow then
                        App.SecretBoxRow(children, childDef)
                    elseif childDef.Type == "color" then
                        colorRow(children, childDef)
                    end
                end)

                if not ok
                    and type(Environment) == "table"
                    and Environment.SliceHubDebug == true then
                    warn(
                        "[SliceHub GUI] Collapsed control recovered:",
                        tostring(childDef.Name or childDef.Type or "unknown"),
                        tostring(err)
                    )
                end
            end
        end
    end

    local animationToken = 0

    local function setExpanded(expanded, animated)
        expanded = expanded == true
        App.Values[def.ExpandedKey] = expanded
        animationToken += 1
        local token = animationToken

        if expanded then
            buildChildren()
            children.Visible = true
        end

        task.defer(function()
            local contentHeight = expanded and list.AbsoluteContentSize.Y or 0
            local targetRow = 47 + contentHeight

            if animated then
                TweenService:Create(children, TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                    Size = UDim2.new(1,-24,0,contentHeight),
                    BackgroundTransparency = expanded and 0.82 or 1,
                }):Play()
                TweenService:Create(row, TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                    Size = UDim2.new(1,0,0,targetRow),
                }):Play()
                TweenService:Create(arrow, TweenInfo.new(0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Rotation = expanded and 90 or 0,
                    TextColor3 = expanded and C.Accent or C.Muted,
                }):Play()
            else
                children.Size = UDim2.new(1,-24,0,contentHeight)
                row.Size = UDim2.new(1,0,0,targetRow)
                arrow.Rotation = expanded and 90 or 0
                arrow.TextColor3 = expanded and C.Accent or C.Muted
            end

            if not expanded then
                task.delay(animated and 0.21 or 0, function()
                    if token == animationToken and App.Values[def.ExpandedKey] ~= true then
                        children.Visible = false
                    end
                end)
            end

            if V12Config and type(V12Config.ScheduleSave) == "function" then
                V12Config.ScheduleSave(0.30)
            end
        end)
    end

    head.Activated:Connect(function()
        setExpanded(App.Values[def.ExpandedKey] ~= true, true)
    end)

    setExpanded(App.Values[def.ExpandedKey] == true, false)
end

App.SecretBoxRow = function(parentObject, def)
    local row = baseRow(parentObject, def)

    local box = Instance.new("TextBox")
    box.AnchorPoint = Vector2.new(1, 0.5)
    box.Position = UDim2.new(1, -13, 0.5, 0)
    box.Size = UDim2.fromOffset(390, 28)
    box.BackgroundColor3 = C.Surface3
    box.BorderSizePixel = 0
    box.ClearTextOnFocus = false
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 9
    box.TextColor3 = C.Text
    box.PlaceholderColor3 = C.Muted
    box.PlaceholderText = tostring(def.Placeholder or "")
    box.TextXAlignment = Enum.TextXAlignment.Left
    box.Parent = row
    corner(box, 6)

    local padding = Instance.new("UIPadding")
    padding.PaddingLeft = UDim.new(0, 10)
    padding.PaddingRight = UDim.new(0, 10)
    padding.Parent = box

    local line = Instance.new("UIStroke")
    line.Color = C.Stroke
    line.Thickness = 1
    line.Transparency = 0.55
    line.Parent = box

    local function masked()
        local raw = tostring(App.Values[def.Key] or "")

        if def.Mask == false then
            box.Text = raw
        elseif raw == "" then
            box.Text = ""
        elseif App.Webhook
            and App.Webhook.MaskURL then
            box.Text = App.Webhook.MaskURL(raw)
        else
            box.Text = "••••••••••••"
        end
    end

    masked()

    box.Focused:Connect(function()
        box.Text = tostring(App.Values[def.Key] or "")
        box.CursorPosition = #box.Text + 1

        TweenService:Create(
            line,
            TweenInfo.new(
                0.12,
                Enum.EasingStyle.Quint,
                Enum.EasingDirection.Out
            ),
            {
                Color = C.Accent,
                Transparency = 0.10,
            }
        ):Play()
    end)

    box.FocusLost:Connect(function()
        local value = tostring(box.Text or "")

        if App.Webhook
            and App.Webhook.Trim then
            value = App.Webhook.Trim(value)
        end

        App.Values[def.Key] = value
        masked()
        runActionHandler(def.Key)

        TweenService:Create(
            line,
            TweenInfo.new(
                0.14,
                Enum.EasingStyle.Quint,
                Enum.EasingDirection.Out
            ),
            {
                Color = C.Stroke,
                Transparency = 0.55,
            }
        ):Play()
    end)
end

local function section(parentObject,sectionDef)
    local sectionFrame = Instance.new("Frame")
    sectionFrame.Name = "Section"
    sectionFrame.Size = UDim2.new(1,-30,0,56)
    sectionFrame.AutomaticSize = Enum.AutomaticSize.None
    sectionFrame.ClipsDescendants = false
    sectionFrame.BackgroundColor3 = C.Surface
    sectionFrame.BackgroundTransparency = 0.28
    sectionFrame.BorderSizePixel = 0
    sectionFrame.Parent = parentObject
    corner(sectionFrame,7)
    stroke(sectionFrame,0.52)

    label(sectionFrame,sectionDef[1],UDim2.new(1,-24,0,20),UDim2.fromOffset(12,7),9,C.Text,Enum.Font.GothamBold)

    local rule = Instance.new("Frame")
    rule.Position = UDim2.fromOffset(12,31)
    rule.Size = UDim2.new(1,-24,0,1)
    rule.BackgroundColor3 = C.Stroke
    rule.BackgroundTransparency = 0.62
    rule.BorderSizePixel = 0
    rule.Parent = sectionFrame

    local rows = Instance.new("Frame")
    rows.Position = UDim2.fromOffset(0,35)
    rows.Size = UDim2.new(1,0,0,0)
    rows.AutomaticSize = Enum.AutomaticSize.None
    rows.BackgroundTransparency = 1
    rows.Parent = sectionFrame

    local list = Instance.new("UIListLayout")
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Parent = rows

    -- R7 GUI HOTFIX: section sizing is reactive instead of relying on
    -- AutomaticSize or a one-frame snapshot. Safety contains conditional and
    -- live rows that can settle after construction; keeping the section bound
    -- to UIListLayout.AbsoluteContentSize prevents clipped/orphaned pages.
    local function syncSectionHeight()
        if not sectionFrame.Parent or not rows.Parent then return end
        local contentHeight = math.max(0, math.ceil(list.AbsoluteContentSize.Y))
        rows.Size = UDim2.new(1,0,0,contentHeight)
        sectionFrame.Size = UDim2.new(1,-30,0,math.max(56,43 + contentHeight))
    end

    list:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncSectionHeight)

    for _,def in ipairs(sectionDef[2]) do
        local allowed = true
        if def.OnlyWhen then
            if type(def.OnlyWhen.Values) == "table" then
                allowed = def.OnlyWhen.Values[App.Values[def.OnlyWhen.Key]] == true
            else
                allowed = App.Values[def.OnlyWhen.Key] == def.OnlyWhen.Value
            end
        end

        if allowed then
            -- R8 GUI HOTFIX: page construction is fault-isolated per control.
            -- A single stale/bad widget may be skipped, but it can never leave
            -- App.Busy locked and make every other tab stop responding.
            local ok, err = pcall(function()
                if def.Type == "toggle" then
                    toggleRow(rows,def)
                elseif def.Type == "status" then
                    statusRow(rows,def)
                elseif def.Type == "live" then
                    liveRow(rows,def)
                elseif def.Type == "button" then
                    buttonRow(rows,def)
                elseif def.Type == "segments" then
                    segmentRow(rows,def)
                elseif def.Type == "choice" then
                    App.ChoiceRow(rows,def)
                elseif def.Type == "numberbox" then
                    App.NumberBoxRow(rows,def)
                elseif def.Type == "secretbox" then
                    App.SecretBoxRow(rows,def)
                elseif def.Type == "slider" then
                    sliderRow(rows,def)
                elseif def.Type == "sliderbox" then
                    App.SliderBoxRow(rows,def)
                elseif def.Type == "collapse" then
                    App.CollapseRow(rows,def)
                elseif def.Type == "color" then
                    colorRow(rows,def)
                elseif def.Type == "expand" then
                    expandRow(rows,def)
                end
            end)

            if not ok
                and type(Environment) == "table"
                and Environment.SliceHubDebug == true then
                warn(
                    "[SliceHub GUI] Control recovered:",
                    tostring(def.Name or def.Type or "unknown"),
                    tostring(err)
                )
            end
        end
    end

    syncSectionHeight()
    task.defer(syncSectionHeight)

    local sectionScale = Instance.new("UIScale")
    sectionScale.Scale = 0.985
    sectionScale.Parent = sectionFrame

    task.defer(function()
        if sectionFrame and sectionFrame.Parent then
            TweenService:Create(
                sectionScale,
                TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                {Scale = 1}
            ):Play()

            TweenService:Create(
                sectionFrame,
                TweenInfo.new(0.20, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                {BackgroundTransparency = 0.02}
            ):Play()
        end
    end)
end

local function makePage(pageName)
    local info = PageInfo[pageName]
    pageTitle.Text = string.upper(pageName)
    pageSubtitle.Text = ""

    local page = Instance.new("ScrollingFrame")
    page.Name = "SliceHubPage_" .. tostring(pageName):gsub("%s+", "_")
    page.Visible = true
    page.Position = UDim2.new(0,10,0,0)
    page.Size = UDim2.fromScale(1,1)
    page.BackgroundTransparency = 1
    page.BorderSizePixel = 0
    page.ScrollBarThickness = 3
    page.ScrollBarImageColor3 = C.Accent
    page.CanvasSize = UDim2.fromOffset(0,0)
    page.Parent = pageHost

    local list = Instance.new("UIListLayout")
    list.Padding = UDim.new(0,9)
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Parent = page

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0,15)
    pad.PaddingRight = UDim.new(0,15)
    pad.PaddingTop = UDim.new(0,2)
    pad.PaddingBottom = UDim.new(0,15)
    pad.Parent = page

    for _,sectionDef in ipairs(info.Sections) do
        local ok, err = pcall(section, page, sectionDef)
        if not ok
            and type(Environment) == "table"
            and Environment.SliceHubDebug == true then
            warn(
                "[SliceHub GUI] Section recovered:",
                tostring(sectionDef[1] or "unknown"),
                tostring(err)
            )
        end
    end

    list:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        page.CanvasSize = UDim2.fromOffset(0,list.AbsoluteContentSize.Y+20)
    end)

    task.defer(function()
        page.CanvasSize = UDim2.fromOffset(0,list.AbsoluteContentSize.Y+20)
    end)

    return page
end

local function refreshNav()
    local activeButton = nil

    for name, b in pairs(navButtons) do
        local active =
            name == App.ActivePage

        if name == "Farm" then
            active =
                App.ActivePage == "Combat"
                or App.ActivePage == "Safety"
        elseif name == "Launch" then
            active =
                App.ActivePage == "Launch"
                or App.ActivePage == "Multi Grind"
                or App.ActivePage == "Boosted Maps"
        elseif name == "Default" then
            active = App.ActivePage == "Launch"
        end

        if b.Visible then
            b.BackgroundColor3 =
                active
                and C.Surface2
                or C.Side

            b.TextColor3 =
                active
                and C.Text
                or C.Muted
        end

        local marker = b:FindFirstChild("Marker")
        if marker then
            marker.BackgroundTransparency = 1
        end

        if active
            and b.Visible
            and b.AbsoluteSize.Y > 0 then
            activeButton = b
        end
    end

    if RuntimeKind == "Lobby" and App.LaunchNavOpen == true then
        local preferredName =
            App.ActivePage == "Launch" and "Default"
            or App.ActivePage
        local preferred = navButtons[tostring(preferredName or "")]
        if preferred and preferred.Visible and preferred.AbsoluteSize.Y > 0 then
            activeButton = preferred
        end
    end

    if activeButton then
        local y =
            (
                activeButton.AbsolutePosition.Y
                - sidebar.AbsolutePosition.Y
            )
            + 7

        TweenService:Create(
            activeNavMarker,
            TweenInfo.new(
                0.19,
                Enum.EasingStyle.Quint,
                Enum.EasingDirection.Out
            ),
            {
                Position =
                    UDim2.fromOffset(
                        7,
                        y
                    )
            }
        ):Play()
    end
end

;(function()

local function switchPage(name, force)
    if App.Busy and not force then return end
    if not force and App.ActivePage == name then return end

    if RuntimeKind == "Gameplay"
        and name ~= "Combat"
        and name ~= "Safety"
        and App.FarmNavOpen == true
        and type(App.SetFarmNavOpen) == "function" then
        App.SetFarmNavOpen(false, true)
    end

    if RuntimeKind == "Lobby"
        and name ~= "Launch"
        and name ~= "Multi Grind"
        and name ~= "Boosted Maps"
        and App.LaunchNavOpen == true
        and type(App.SetLaunchNavOpen) == "function" then
        App.SetLaunchNavOpen(false, true)
    end

    App.Busy = true
    App.ActivePage = name
    refreshNav()

    -- R5 GUI HOTFIX: page replacement is atomic. Destroy every previous
    -- ScrollingFrame before constructing the next one; never wait on a tween
    -- completion to release navigation ownership. This prevents stale Farm
    -- pages from surviving and prevents App.Busy from trapping all other tabs.
    for _, child in ipairs(pageHost:GetChildren()) do
        if child:IsA("ScrollingFrame") then
            child.Visible = false
            child:Destroy()
        end
    end
    currentPage = nil

    -- R8 GUI HOTFIX: never let a constructor error permanently lock the nav.
    local okPage, nextPageOrError = pcall(makePage, name)
    if not okPage or not nextPageOrError then
        App.Busy = false
        if type(Environment) == "table"
            and Environment.SliceHubDebug == true then
            warn(
                "[SliceHub GUI] Page constructor recovered:",
                tostring(name),
                tostring(nextPageOrError)
            )
        end
        setStatus("GUI recovered • choose another tab")
        return
    end

    local nextPage = nextPageOrError
    nextPage.Position = UDim2.new(0,8,0,0)
    currentPage = nextPage

    -- Construction is complete. Release navigation ownership before any
    -- cosmetic tweens so a later animation/property error cannot poison tabs.
    App.Busy = false

    pageTitle.TextTransparency = 0.35
    pageSubtitle.TextTransparency = 0.45
    pageTitle.Position = UDim2.fromOffset(24,10)
    pageSubtitle.Position = UDim2.fromOffset(24,34)

    TweenService:Create(
        pageTitle,
        TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
        {TextTransparency = 0, Position = UDim2.fromOffset(18,10)}
    ):Play()

    TweenService:Create(
        pageSubtitle,
        TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
        {TextTransparency = 0, Position = UDim2.fromOffset(18,34)}
    ):Play()

    TweenService:Create(
        nextPage,
        TweenInfo.new(0.17,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),
        {Position=UDim2.new(0,0,0,0)}
    ):Play()

    task.delay(0.23, function()
        if currentPage == nextPage
            and nextPage
            and nextPage.Parent then
            applyWindowTransparency()
        end
    end)
    setStatus("Ready • " .. RuntimeKind .. " • Default")
end

App.SwitchPage = switchPage


do
    App.FeatureSearch = App.FeatureSearch or {Index = {}, LastQuery = "", LastResult = ""}
    local aliases = {
        ["private server"] = {"ps","private","server code","vip server"},
        ["auto retry"] = {"retry","rerun","restart mission"},
        ["thunder spear"] = {"ts","spear","spears","thunder"},
        ["auto open chests"] = {"chest","chests","raid chest"},
        ["auto prestige"] = {"prestige","prest"},
        ["webhook"] = {"discord","hook","results webhook"},
        ["multi grind"] = {"multigrind","multi","host","alt","party grind"},
        ["boosted maps"] = {"2x","boost map","boosted","rotation","featured map"},
        ["unload slicehub completely"] = {"unload","kill hub","close hub","shutdown"},
        ["auto launch"] = {"launch","mission launch","raid launch"},
        ["auto select slot"] = {"slot","auto slot"},
        ["family"] = {"spin","family spin","families"},
        ["waves"] = {"wave","wave farm"},
    }

    local function norm(value)
        return string.lower(tostring(value or "")):gsub("[^%w]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local function aliasText(name)
        local lower = norm(name)
        local out = {}
        for key, values in pairs(aliases) do
            if string.find(lower, key, 1, true) or string.find(key, lower, 1, true) then
                for _, value in ipairs(values) do out[#out + 1] = value end
            end
        end
        return table.concat(out, " ")
    end

    local function walk(pageName, sectionName, definitions)
        for _, def in ipairs(definitions or {}) do
            if type(def) == "table" and def.Name then
                local name = tostring(def.Name)
                App.FeatureSearch.Index[#App.FeatureSearch.Index + 1] = {
                    Page = tostring(pageName),
                    Section = tostring(sectionName or ""),
                    Name = name,
                    Haystack = norm(pageName .. " " .. tostring(sectionName or "") .. " " .. name .. " " .. tostring(def.Desc or "") .. " " .. aliasText(name)),
                }
                if type(def.Children) == "table" then walk(pageName, name, def.Children) end
            end
        end
    end

    for pageName, info in pairs(PageInfo) do
        for _, sectionDef in ipairs((type(info) == "table" and info.Sections) or {}) do
            walk(pageName, sectionDef[1], sectionDef[2])
        end
    end

    local box = Instance.new("TextBox")
    box.Name = "FeatureSearch"
    box.PlaceholderText = "Search features  •  Ctrl+K"
    box.Text = ""
    box.ClearTextOnFocus = false
    box.Size = UDim2.fromOffset(220, 28)
    box.Position = UDim2.new(1, -358, 0, 12)
    box.BackgroundColor3 = C.Surface2
    box.BorderSizePixel = 0
    box.TextColor3 = C.Text
    box.PlaceholderColor3 = C.Muted
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 9
    box.TextXAlignment = Enum.TextXAlignment.Left
    box.Parent = header
    corner(box, 6)
    stroke(box, 0.65)
    local padding = Instance.new("UIPadding")
    padding.PaddingLeft = UDim.new(0, 10)
    padding.PaddingRight = UDim.new(0, 10)
    padding.Parent = box

    local results = Instance.new("Frame")
    results.Name = "FeatureSearchResults"
    results.Position = UDim2.new(1, -358, 0, 43)
    results.Size = UDim2.fromOffset(220, 0)
    results.AutomaticSize = Enum.AutomaticSize.Y
    results.BackgroundColor3 = C.Surface
    results.BorderSizePixel = 0
    results.Visible = false
    results.ZIndex = 120
    results.Parent = header
    corner(results, 7)
    stroke(results, 0.35)
    local layout = Instance.new("UIListLayout")
    layout.Padding = UDim.new(0, 2)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = results
    local resultPad = Instance.new("UIPadding")
    resultPad.PaddingTop = UDim.new(0, 5)
    resultPad.PaddingBottom = UDim.new(0, 5)
    resultPad.PaddingLeft = UDim.new(0, 5)
    resultPad.PaddingRight = UDim.new(0, 5)
    resultPad.Parent = results

    local function pulseTarget(target)
        task.delay(0.08, function()
            if not currentPage or not currentPage.Parent then return end
            local wanted = tostring(target.Name)
            for _, object in ipairs(currentPage:GetDescendants()) do
                if object:IsA("TextLabel") and tostring(object.Text) == wanted then
                    local row = object.Parent
                    if row and row:IsA("GuiObject") then
                        local original = row.BackgroundColor3
                        local originalT = row.BackgroundTransparency
                        row.BackgroundColor3 = C.AccentSoft
                        row.BackgroundTransparency = 0.18
                        pcall(function()
                            local scroller = currentPage:FindFirstAncestorWhichIsA("ScrollingFrame") or currentPage
                            if scroller and scroller:IsA("ScrollingFrame") then
                                local y = math.max(0, row.AbsolutePosition.Y - scroller.AbsolutePosition.Y + scroller.CanvasPosition.Y - 80)
                                scroller.CanvasPosition = Vector2.new(scroller.CanvasPosition.X, y)
                            end
                        end)
                        task.delay(1.1, function()
                            if row and row.Parent then
                                TweenService:Create(row, TweenInfo.new(0.22), {BackgroundColor3 = original, BackgroundTransparency = originalT}):Play()
                            end
                        end)
                    end
                    break
                end
            end
        end)
    end

    local function openTarget(target)
        if not target then return end
        App.FeatureSearch.LastResult = target.Page .. " → " .. target.Name
        results.Visible = false
        box.Text = ""
        App.SwitchPage(target.Page, false)
        pulseTarget(target)
    end

    local function score(item, query)
        local name = norm(item.Name)
        local page = norm(item.Page)
        local hay = item.Haystack
        if name == query then return 1000 end
        if string.sub(name, 1, #query) == query then return 800 end
        if string.find(name, query, 1, true) then return 650 end
        if string.find(page, query, 1, true) then return 450 end
        if string.find(hay, query, 1, true) then return 300 end
        local points = 0
        for token in string.gmatch(query, "%S+") do
            if string.find(hay, token, 1, true) then points += 65 else points -= 90 end
        end
        return points
    end

    local function render()
        for _, child in ipairs(results:GetChildren()) do
            if child:IsA("TextButton") then child:Destroy() end
        end
        local query = norm(box.Text)
        App.FeatureSearch.LastQuery = query
        if query == "" then results.Visible = false return end
        local ranked = {}
        for _, item in ipairs(App.FeatureSearch.Index) do
            local points = score(item, query)
            if points > 0 then ranked[#ranked + 1] = {Item=item, Score=points} end
        end
        table.sort(ranked, function(a,b)
            if a.Score == b.Score then return a.Item.Name < b.Item.Name end
            return a.Score > b.Score
        end)
        for index = 1, math.min(6, #ranked) do
            local target = ranked[index].Item
            local b = Instance.new("TextButton")
            b.AutoButtonColor = false
            b.Size = UDim2.new(1, 0, 0, 30)
            b.BackgroundColor3 = C.Surface2
            b.BackgroundTransparency = 0.06
            b.BorderSizePixel = 0
            b.Text = target.Name .. "   ·   " .. target.Page
            b.TextColor3 = C.Text
            b.TextSize = 8
            b.Font = Enum.Font.GothamMedium
            b.TextXAlignment = Enum.TextXAlignment.Left
            b.ZIndex = 121
            b.LayoutOrder = index
            b.Parent = results
            corner(b, 5)
            local p = Instance.new("UIPadding")
            p.PaddingLeft = UDim.new(0, 8)
            p.Parent = b
            b.Activated:Connect(function() openTarget(target) end)
        end
        results.Visible = #ranked > 0
    end

    box:GetPropertyChangedSignal("Text"):Connect(render)
    box.FocusLost:Connect(function(enterPressed)
        if not enterPressed then
            task.delay(0.12, function()
                if not box:IsFocused() then results.Visible = false end
            end)
            return
        end
        local query = norm(App.FeatureSearch.LastQuery)
        local best, bestScore = nil, -math.huge
        for _, item in ipairs(App.FeatureSearch.Index) do
            local points = score(item, query)
            if points > bestScore then best, bestScore = item, points end
        end
        if best and bestScore > 0 then openTarget(best) end
    end)

    App.RuntimeHealth.Track(UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if input.KeyCode == Enum.KeyCode.K and (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) then
            box:CaptureFocus()
        end
    end))
end

rebuildCurrent = function()
    switchPage(App.ActivePage,true)
end

App.RebuildNavigation = function()

    for _, child in ipairs(sidebar:GetChildren()) do
        if child ~= activeNavMarker then
            pcall(function()
                child:Destroy()
            end)
        end
    end
    for key in pairs(navButtons) do
        navButtons[key] = nil
    end

    local items = {}
    App.FarmNavOpen = false
    App.LaunchNavOpen = false

    local function makeButton(parentObject, name, indent)
        local buttonObject = Instance.new("TextButton")

        buttonObject.AutoButtonColor = false
        buttonObject.Text = name
        buttonObject.Size = UDim2.new(1, -14 - indent, 0, 29)
        buttonObject.BackgroundColor3 = C.Side
        buttonObject.BorderSizePixel = 0
        buttonObject.TextColor3 = C.Muted
        buttonObject.TextXAlignment = Enum.TextXAlignment.Left
        buttonObject.Font = Enum.Font.GothamMedium
        buttonObject.TextSize = 9
        buttonObject.Parent = parentObject
        corner(buttonObject, 6)

        local padding = Instance.new("UIPadding")
        padding.PaddingLeft = UDim.new(0, 11 + indent)
        padding.Parent = buttonObject

        local marker = Instance.new("Frame")
        marker.Name = "Marker"
        marker.Position = UDim2.fromOffset(math.max(0, indent - 4), 7)
        marker.Size = UDim2.fromOffset(3, 15)
        marker.BackgroundColor3 = C.Accent
        marker.BackgroundTransparency = 1
        marker.BorderSizePixel = 0
        marker.Parent = buttonObject
        corner(marker, 3)

        local hoverScale = Instance.new("UIScale")
        hoverScale.Scale = 1
        hoverScale.Parent = buttonObject

        buttonObject.MouseEnter:Connect(function()
            TweenService:Create(
                hoverScale,
                TweenInfo.new(0.11, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                {Scale = 1.018}
            ):Play()
        end)

        buttonObject.MouseLeave:Connect(function()
            TweenService:Create(
                hoverScale,
                TweenInfo.new(0.11, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                {Scale = 1}
            ):Play()
        end)

        navButtons[name] = buttonObject
        return buttonObject
    end

    local function addGroup(name)
        local groupLabel = label(
            sidebar,
            name,
            UDim2.new(1, -16, 0, 18),
            UDim2.fromOffset(8, 0),
            8,
            C.Dim,
            Enum.Font.GothamBold
        )

        items[#items + 1] = {
            Kind = "Group",
            Object = groupLabel,
        }
    end

    local farmBranch = nil
    local farmCombat = nil
    local farmSafety = nil

    local launchBranch = nil
    local launchDefault = nil
    local launchMulti = nil
    local launchBoosted = nil

    local function reflow(animated)
        local y = 13
        local duration = animated and 0.18 or 0

        for _, item in ipairs(items) do
            if item.Kind == "Group" then
                item.Object.Visible = true
                local target = UDim2.fromOffset(8, y)
                if animated then
                    TweenService:Create(
                        item.Object,
                        TweenInfo.new(duration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        {Position = target}
                    ):Play()
                else
                    item.Object.Position = target
                end
                y += 22

            elseif item.Kind == "Button" then
                item.Object.Visible = true
                local target = UDim2.fromOffset(7, y)
                if animated then
                    TweenService:Create(
                        item.Object,
                        TweenInfo.new(duration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        {Position = target}
                    ):Play()
                else
                    item.Object.Position = target
                end
                y += 32

            elseif item.Kind == "FarmBranch" then
                item.Object.Position = UDim2.fromOffset(7, y)
                if App.FarmNavOpen then y += 64 end

            elseif item.Kind == "LaunchBranch" then
                item.Object.Position = UDim2.fromOffset(7, y)
                if App.LaunchNavOpen then y += 96 end

            elseif item.Kind == "Gap" then
                y += tonumber(item.Height) or 9
            end
        end

        task.delay(animated and 0.19 or 0, refreshNav)
    end

    local farmBranchToken = 0
    local launchBranchToken = 0

    local function setFarmOpen(open, animated)
        open = open == true
        App.FarmNavOpen = open

        if not farmBranch then
            reflow(animated)
            return
        end

        farmBranchToken += 1
        local token = farmBranchToken

        if open then
            farmBranch.Visible = true
            farmCombat.Visible = true
            farmSafety.Visible = true
        end

        local targetHeight = open and 61 or 0
        local targetTransparency = open and 0 or 1

        if animated then
            TweenService:Create(
                farmBranch,
                TweenInfo.new(
                    0.18,
                    Enum.EasingStyle.Quint,
                    open and Enum.EasingDirection.Out or Enum.EasingDirection.In
                ),
                {Size = UDim2.new(1, -14, 0, targetHeight)}
            ):Play()

            for _, child in ipairs({farmCombat, farmSafety}) do
                TweenService:Create(
                    child,
                    TweenInfo.new(
                        0.15,
                        Enum.EasingStyle.Quad,
                        open and Enum.EasingDirection.Out or Enum.EasingDirection.In
                    ),
                    {
                        BackgroundTransparency = targetTransparency,
                        TextTransparency = targetTransparency,
                    }
                ):Play()
            end
        else
            farmBranch.Size = UDim2.new(1, -14, 0, targetHeight)
            for _, child in ipairs({farmCombat, farmSafety}) do
                child.BackgroundTransparency = targetTransparency
                child.TextTransparency = targetTransparency
            end
        end

        reflow(animated)

        if not open then
            task.delay(animated and 0.19 or 0, function()
                if token == farmBranchToken and App.FarmNavOpen ~= true then
                    farmCombat.Visible = false
                    farmSafety.Visible = false
                    farmBranch.Visible = false
                end
            end)
        end
    end

    local function setLaunchOpen(open, animated)
        open = open == true
        App.LaunchNavOpen = open

        if not launchBranch then
            reflow(animated)
            return
        end

        launchBranchToken += 1
        local token = launchBranchToken

        if open then
            launchBranch.Visible = true
            launchDefault.Visible = true
            launchMulti.Visible = true
            launchBoosted.Visible = true
        end

        local targetHeight = open and 93 or 0
        local targetTransparency = open and 0 or 1

        if animated then
            TweenService:Create(
                launchBranch,
                TweenInfo.new(
                    0.18,
                    Enum.EasingStyle.Quint,
                    open and Enum.EasingDirection.Out or Enum.EasingDirection.In
                ),
                {Size = UDim2.new(1, -14, 0, targetHeight)}
            ):Play()

            for _, child in ipairs({launchDefault, launchMulti, launchBoosted}) do
                TweenService:Create(
                    child,
                    TweenInfo.new(
                        0.15,
                        Enum.EasingStyle.Quad,
                        open and Enum.EasingDirection.Out or Enum.EasingDirection.In
                    ),
                    {
                        BackgroundTransparency = targetTransparency,
                        TextTransparency = targetTransparency,
                    }
                ):Play()
            end
        else
            launchBranch.Size = UDim2.new(1, -14, 0, targetHeight)
            for _, child in ipairs({launchDefault, launchMulti, launchBoosted}) do
                child.BackgroundTransparency = targetTransparency
                child.TextTransparency = targetTransparency
            end
        end

        reflow(animated)

        if not open then
            task.delay(animated and 0.19 or 0, function()
                if token == launchBranchToken and App.LaunchNavOpen ~= true then
                    launchDefault.Visible = false
                    launchMulti.Visible = false
                    launchBoosted.Visible = false
                    launchBranch.Visible = false
                end
            end)
        end
    end

    App.SetFarmNavOpen = setFarmOpen
    App.RefreshFarmNav = reflow
    App.SetLaunchNavOpen = setLaunchOpen
    App.RefreshLaunchNav = reflow

    for _, group in ipairs(NAV) do
        addGroup(group.Group)

        for _, name in ipairs(group.Pages) do
            if RuntimeKind == "Lobby" and name == "Launch" then
                local launch = makeButton(sidebar, "Launch", 0)
                items[#items + 1] = {Kind = "Button", Object = launch}

                launchBranch = Instance.new("Frame")
                launchBranch.Name = "LaunchChildBranch"
                launchBranch.Size = UDim2.new(1, -14, 0, 0)
                launchBranch.BackgroundTransparency = 1
                launchBranch.BorderSizePixel = 0
                launchBranch.ClipsDescendants = true
                launchBranch.Visible = false
                launchBranch.Parent = sidebar
                items[#items + 1] = {Kind = "LaunchBranch", Object = launchBranch}

                launchDefault = makeButton(launchBranch, "Default", 12)
                launchDefault.Position = UDim2.fromOffset(0, 0)
                launchDefault.Size = UDim2.new(1, 0, 0, 29)

                launchMulti = makeButton(launchBranch, "Multi Grind", 12)
                launchMulti.Position = UDim2.fromOffset(0, 32)
                launchMulti.Size = UDim2.new(1, 0, 0, 29)

                launchBoosted = makeButton(launchBranch, "Boosted Maps", 12)
                launchBoosted.Position = UDim2.fromOffset(0, 64)
                launchBoosted.Size = UDim2.new(1, 0, 0, 29)

                for _, child in ipairs({launchDefault, launchMulti, launchBoosted}) do
                    child.Visible = false
                    child.BackgroundTransparency = 1
                    child.TextTransparency = 1
                end

                launch.Activated:Connect(function()
                    setLaunchOpen(true, true)
                    if App.ActivePage ~= "Launch"
                        and App.ActivePage ~= "Multi Grind"
                        and App.ActivePage ~= "Boosted Maps" then
                        switchPage("Launch", false)
                    else
                        refreshNav()
                    end
                end)

                launchDefault.Activated:Connect(function()
                    if App.LaunchNavOpen ~= true then return end
                    switchPage("Launch", false)
                end)

                launchMulti.Activated:Connect(function()
                    if App.LaunchNavOpen ~= true then return end
                    switchPage("Multi Grind", false)
                end)

                launchBoosted.Activated:Connect(function()
                    if App.LaunchNavOpen ~= true then return end
                    switchPage("Boosted Maps", false)
                end)

            elseif RuntimeKind == "Gameplay" and name == "Farm" then
                local farm = makeButton(sidebar, "Farm", 0)
                items[#items + 1] = {Kind = "Button", Object = farm}

                farmBranch = Instance.new("Frame")
                farmBranch.Name = "FarmChildBranch"
                farmBranch.Size = UDim2.new(1, -14, 0, 0)
                farmBranch.BackgroundTransparency = 1
                farmBranch.BorderSizePixel = 0
                farmBranch.ClipsDescendants = true
                farmBranch.Visible = false
                farmBranch.Parent = sidebar
                items[#items + 1] = {Kind = "FarmBranch", Object = farmBranch}

                farmCombat = makeButton(farmBranch, "Combat", 12)
                farmCombat.Position = UDim2.fromOffset(0, 0)
                farmCombat.Size = UDim2.new(1, 0, 0, 29)
                farmCombat.Visible = false
                farmCombat.BackgroundTransparency = 1
                farmCombat.TextTransparency = 1

                farmSafety = makeButton(farmBranch, "Safety", 24)
                farmSafety.Position = UDim2.fromOffset(0, 32)
                farmSafety.Size = UDim2.new(1, 0, 0, 29)
                farmSafety.Visible = false
                farmSafety.BackgroundTransparency = 1
                farmSafety.TextTransparency = 1

                farm.Activated:Connect(function()
                    setFarmOpen(true, true)
                    if App.ActivePage ~= "Combat" then
                        switchPage("Combat", false)
                    else
                        refreshNav()
                    end
                end)

                farmCombat.Activated:Connect(function()
                    if App.FarmNavOpen ~= true then return end
                    switchPage("Combat", false)
                end)

                farmSafety.Activated:Connect(function()
                    if App.FarmNavOpen ~= true then return end
                    switchPage("Safety", false)
                end)

            else
                local navButton = makeButton(sidebar, name, 0)
                items[#items + 1] = {Kind = "Button", Object = navButton}

                navButton.Activated:Connect(function()
                    if RuntimeKind == "Gameplay" and App.FarmNavOpen then
                        setFarmOpen(false, true)
                    end
                    if RuntimeKind == "Lobby" and App.LaunchNavOpen then
                        setLaunchOpen(false, true)
                    end
                    switchPage(name, false)
                end)
            end
        end

        items[#items + 1] = {Kind = "Gap", Height = 9}
    end

    setFarmOpen(false, false)
    setLaunchOpen(false, false)
end

App.RebuildNavigation()
