local originalMouseIconEnabled = UserInputService.MouseIconEnabled
local usingScriptCursor = false

local function restoreMouseCursor()
    if usingScriptCursor then
        UserInputService.MouseIconEnabled = originalMouseIconEnabled
        usingScriptCursor = false
    end
    cursorGui.Visible = false
end

task.spawn(function()
    while gui and gui.Parent do
        -- Do not run a 60 Hz mouse/pulse loop when the custom cursor cannot be seen.
        if App.Values.ScriptCursor ~= true
            or App.Hidden == true
            or shell.Visible ~= true then
            restoreMouseCursor()
            task.wait(App.PerformanceControl.Delay(0.16, 0.32))
            continue
        end

        local mouse = UserInputService:GetMouseLocation()
        local shellPos = shell.AbsolutePosition
        local shellSize = shell.AbsoluteSize

        local inside =
            mouse.X >= shellPos.X
            and mouse.X <= shellPos.X + shellSize.X
            and mouse.Y >= shellPos.Y
            and mouse.Y <= shellPos.Y + shellSize.Y

        if inside then
            if not usingScriptCursor then
                originalMouseIconEnabled = UserInputService.MouseIconEnabled
                UserInputService.MouseIconEnabled = false
                usingScriptCursor = true
            end

            cursorGui.Visible = true
            cursorGui.Position = UDim2.fromOffset(mouse.X, mouse.Y)

            local pulse = 1 + math.sin(os.clock() * 6) * 0.035
            cursorRing.Size = UDim2.fromOffset(12 * pulse, 12 * pulse)
            task.wait(0.016)
        else
            restoreMouseCursor()
            task.wait(0.08)
        end
    end

    restoreMouseCursor()
end)


