do
    local minW, minH = 680, 430
    local gripSize = 20

    local resizing = false
    local resizeCorner = nil
    local startMouse = nil
    local startSize = nil
    local startPos = nil

    local grips = {}

    local function makeGrip(name, anchor, position)
        local g = Instance.new("Frame")
        g.Name = name
        g.AnchorPoint = anchor
        g.Position = position
        g.Size = UDim2.fromOffset(gripSize, gripSize)
        g.BackgroundTransparency = 1
        g.BorderSizePixel = 0
        g.ZIndex = 100
        g.Active = true
        g.Parent = shell
        grips[name] = g
        return g
    end

    makeGrip("NW", Vector2.new(0,0), UDim2.new(0,0,0,0))
    makeGrip("NE", Vector2.new(1,0), UDim2.new(1,0,0,0))
    makeGrip("SW", Vector2.new(0,1), UDim2.new(0,0,1,0))
    makeGrip("SE", Vector2.new(1,1), UDim2.new(1,0,1,0))

    local function viewportLimits()
        local cam = workspace.CurrentCamera
        if not cam then
            return 1600, 1000
        end
        local v = cam.ViewportSize
        return math.max(minW, v.X - 24), math.max(minH, v.Y - 24)
    end

    local function beginResize(cornerName, input)
        if App.Mobile and App.Mobile.Compact then
            return
        end

        resizing = true
        resizeCorner = cornerName
        startMouse = input.Position
        startSize = Vector2.new(shell.Size.X.Offset, shell.Size.Y.Offset)
        startPos = shell.AbsolutePosition
    end

    for cornerName, grip in pairs(grips) do
        grip.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                beginResize(cornerName, input)
            end
        end)
    end

    UserInputService.InputChanged:Connect(function(input)
        if not resizing then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        local uiScale = shell:FindFirstChildOfClass("UIScale")
        local logicalScale = uiScale and math.max(0.01, tonumber(uiScale.Scale) or 1) or 1
        local delta = (input.Position - startMouse) / logicalScale
        local maxW, maxH = viewportLimits()

        local newW = startSize.X
        local newH = startSize.Y
        local left = startPos.X
        local top = startPos.Y

        if resizeCorner == "SE" then
            newW = startSize.X + delta.X
            newH = startSize.Y + delta.Y
        elseif resizeCorner == "SW" then
            newW = startSize.X - delta.X
            newH = startSize.Y + delta.Y
            left = startPos.X + delta.X
        elseif resizeCorner == "NE" then
            newW = startSize.X + delta.X
            newH = startSize.Y - delta.Y
            top = startPos.Y + delta.Y
        elseif resizeCorner == "NW" then
            newW = startSize.X - delta.X
            newH = startSize.Y - delta.Y
            left = startPos.X + delta.X
            top = startPos.Y + delta.Y
        end

        newW = math.clamp(newW, minW, maxW)
        newH = math.clamp(newH, minH, maxH)


        if resizeCorner == "SW" or resizeCorner == "NW" then
            left = startPos.X + (startSize.X - newW)
        end
        if resizeCorner == "NE" or resizeCorner == "NW" then
            top = startPos.Y + (startSize.Y - newH)
        end


        local centerX = left + newW / 2
        local centerY = top + newH / 2

        shell.Size = UDim2.fromOffset(newW, newH)
        shell.Position = UDim2.fromOffset(centerX, centerY)
        V12Config.WindowWidth = math.floor(newW + 0.5)
        V12Config.WindowHeight = math.floor(newH + 0.5)
    end)

    UserInputService.InputEnded:Connect(function(input)
        if resizing and (
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        ) then
            resizing = false
            resizeCorner = nil
            startMouse = nil
            startSize = nil
            startPos = nil
            if V12Config and type(V12Config.ScheduleSave) == "function" then
                V12Config.ScheduleSave(0.15)
            end
        end
    end)
end


do
    local sizeSerial = 0

    shell:GetPropertyChangedSignal(
        "AbsoluteSize"
    ):Connect(function()
        if not shell
            or not shell.Parent
            or (
                MacState
                and MacState.Minimized
            )
            or (
                App.Mobile
                and App.Mobile.Compact
            ) then
            return
        end

        local logicalWidth = tonumber(shell.Size.X.Offset) or 0
        local logicalHeight = tonumber(shell.Size.Y.Offset) or 0

        if logicalWidth < 680
            or logicalHeight < 430 then
            return
        end

        V12Config.WindowWidth =
            math.clamp(
                math.floor(
                    logicalWidth + 0.5
                ),
                680,
                1600
            )

        V12Config.WindowHeight =
            math.clamp(
                math.floor(
                    logicalHeight + 0.5
                ),
                430,
                1000
            )

        sizeSerial += 1
        local serial = sizeSerial

        task.delay(0.45, function()
            if serial ~= sizeSerial then
                return
            end

            if V12Config
                and type(
                    V12Config.ScheduleSave
                ) == "function" then
                V12Config.ScheduleSave(0.05)
            end
        end)
    end)
end


